P.entries["item:nugget-slug"] = {n="Rondelle de métal",s="Les seaux à outils de la Videfange contiennent des Nugget Slugs utilisés par la KapitalRisk dans son équipement lourd.",h="Les seaux à outils de la Videfange contiennent des Nugget Slugs utilisés par la KapitalRisk dans son...",kw={"tarides","rondelle de métal","samophlange","la videfange","seau à outils","kapitalrisk","wenikee boltbucket"},ang={["profession:Engineering"]="Pour un ingénieur, une quincaillerie propriétaire de calibre dix-sept virgule cinq convient mal à un samophlange instable conçu par des gobelins. Attendez-vous à un démontage rapide et explosif."},sec={{t="Fixations industrielles de la Videfange",b="Sur les sites d’extraction de la KapitalRisk, les Nugget Slugs servent à fixer l’équipement lourd. Ils sont conçus pour les assemblages industriels exigeants et calibrés à dix-sept virgule cinq. Le commerce ordinaire leur est peu utile. Pourtant, les bricoleurs en ont besoin pour fabriquer du matériel gobelin sur mesure."},{t="Bricolage avec le samophlange",b="Wenikee Boltbucket a besoin de nombreux Nugget Slugs pour réviser un samophlange instable récupéré dans les Tarides. Des seaux à outils sont éparpillés sur les chantiers de forage de la KapitalRisk, à la Videfange, ce qui rend la récupération lucrative pour les pilleurs.\n\nLes réparations de Wenikee se terminent par une défaillance soudaine. Le samophlange explose pendant qu’elle travaille."}},faq={{q="Qu’est-ce qu’un Rondelle de métal ?",a="Un Rondelle de métal est une fixation métallique de calibre dix-sept virgule cinq utilisée dans les machines lourdes. Ces fixations assemblent des mécanismes complexes comme les foreuses pétrolières et les samophlanges.",al={"que sont les nugget slugs","histoire des nugget slugs","fixation rondelle de métal"}},{q="Où trouve-t-on des Nugget Slugs ?",a="Les Nugget Slugs se trouvent dans des seaux à outils éparpillés dans la Videfange, un camp de forage de la KapitalRisk au nord-est des Tarides.",al={"où trouver des nugget slugs","emplacement des nugget slugs","seaux à outils de la videfange"}},{q="Pourquoi Wenikee Boltbucket en a-t-elle besoin ?",a="Wenikee Boltbucket veut bricoler un samophlange récupéré dans les Tarides et le réparer. Elle n’a plus de fixations de calibre dix-sept virgule cinq. Elle envoie donc des aventuriers en récupérer d’autres dans le camp voisin de la KapitalRisk.",al={"qui a besoin de nugget slugs","pourquoi wenikee veut des nugget slugs","réparation du samophlange"}},{q="Les Nugget Slugs permettent-ils de réparer le samophlange ?",a="Non. Wenikee équipe le samophlange des Nugget Slugs récupérés et commence l’entretien. Puis la machine explose devant elle.",al={"la machine fonctionne-t-elle","explosion du samophlange","résultat des réparations de wenikee"}}},fx={f3aea894={q="D'où viennent les Nugget Slugs et qui les fabrique ?",a="Ces cartouches de calibre dix-sept virgule cinq sont du matériel industriel utilisé par la KapitalRisk à la Videfange. Leurs ouvriers et ingénieurs les stockent dans des seaux à outils disséminés autour de leurs chantiers de forage et d'excavation dans les Tarides orientales.",al={"d'où viennent les nugget slugs","qui fabrique les nugget slugs","origine des nugget slugs"}}},fp="11,185,38.263.0,30.327.1,22.174.0,29.131.0,38.228.0,48.115.1"}
P.entries["item:oathstone-of-ysera-s-dragonflight"] = {n="Oathstone of Ysera's Dragonflight",s="L’Oathstone of Ysera's Dragonflight porte les paroles d’Itharius sur Eranikus. Elle vous appelle à choisir dans le Marais des Chagrins.",h="L’Oathstone of Ysera's Dragonflight porte les paroles d’Itharius sur Eranikus.",kw={"chained essence","vol draconique","eranikus","itharius","oathstone","rédemption","marais des chagrins","ysera"},sec={{t="Une mission confiée",b="Dans le Marais des Chagrins, Itharius vous donne l’Oathstone après vous avoir parlé d’Eranikus. Activez la pierre, et sa voix atteint votre esprit. Il vous demande d’accepter une mission au service de Ysera's Dragonflight."},{t="Le choix",b="La mission d’Itharius vous demande d’aider à racheter l’âme corrompue d’Eranikus. Pour commencer, vous devez abandonner la Chained Essence of Eranikus, qui renferme ce qui reste de la libre volonté d’Eranikus. Itharius qualifie cela de premier de nombreux sacrifices. C’est à vous de choisir d’aider Ysera's Dragonflight."}},faq={{q="À quoi sert l’Oathstone ?",a="Quand vous activez l’Oathstone, Itharius s’adresse à votre esprit et vous demande d’aider Ysera's Dragonflight à racheter Eranikus.",al={"à quoi sert oathstone","but d’oathstone"}},{q="Qui vous donne l’Oathstone ?",a="Itharius vous donne l’Oathstone après vous avoir parlé d’Eranikus dans le Marais des Chagrins.",al={"qui donne oathstone","pierre d’itharius"}},{q="Quel choix la pierre offre-t-elle ?",a="L’Oathstone vous demande de choisir si vous voulez aider Ysera's Dragonflight à racheter Eranikus.",al={"choix d’oathstone","aider ysera ou non"}},{q="À quoi devez-vous renoncer ?",a="Itharius vous demande d’abandonner la Chained Essence of Eranikus, qui enchaîne ce qui reste de la libre volonté d’Eranikus.",al={"quel sacrifice","chained essence"}}},fp="33,128,14.215.0,10.280.1,27.123.1,28.96.0,33.91.1,22.115.1"}
P.entries["item:ogre-s-monocle"] = {n="Monocle d'ogre",s="Dans le sud du Bois de la Pénombre, Zzarc'Vul porte un monocle dont Viktori Prism'Antras a besoin pour son télescope. Sa lentille a la taille et la courbure requises pour focaliser la lumière dans l'instrument d'observation astronomique de Sombre-Comté.",h="Dans le sud du Bois de la Pénombre, Zzarc'Vul porte un monocle dont Viktori Prism'Antras a besoin pour son...",kw={"cog","sombre-comté","look to the stars","monocle d'ogre","télescope","viktori prism'antras","tertre des ogres vul'gol","zzarc'vul"},ang={["faction:Alliance"]="Récupérer la lentille élimine une brute dangereuse des bois du sud et aide les habitants éprouvés de Sombre-Comté à trouver du réconfort dans les étoiles.",["profession:Engineering"]="Le plan de Cog témoigne de l'ambition typique des gnomes : quand les lentilles taillées avec précision manquent sur le terrain, il faut se rabattre sur un énorme monocle."},sec={{t="Une lentille curieuse",b="Zzarc'Vul, un ogre, porte un monocle conçu pour sa stature massive. Lorsque Viktori Prism'Antras, de Sombre-Comté, a commencé à construire un instrument d'observation astronomique d'après les plans de l'ingénieur gnome Cog, les lentilles ordinaires se sont révélées trop petites. Le monocle de Zzarc'Vul est le seul verre poli de la région dont la taille et la courbure permettent de focaliser la lumière dans le télescope achevé."},{t="Le lui prendre à Vul'Gol",b="Au Tertre des ogres Vul'Gol, dans le sud du Bois de la Pénombre, Zzarc'Vul vit parmi ses congénères brutaux. Il semble peu enclin à céder son accessoire distinctif. Vous devez le vaincre sur son propre territoire pour récupérer la lentille, puis la rapporter à Sombre-Comté afin que Viktori puisse tourner son regard vers le ciel nocturne."}},faq={{q="Qui porte le Monocle d'ogre ?",a="Zzarc'Vul, un ogre, porte le monocle au Tertre des ogres Vul'Gol, dans le sud du Bois de la Pénombre.",al={"qui donne le monocle","qui possède le monocle d'ogre","objet zzarc'vul"}},{q="Pourquoi Viktori Prism'Antras a-t-il besoin d'un verre d'ogre ?",a="Viktori Prism'Antras a besoin d'une lentille exceptionnellement grande pour un télescope construit d'après les plans du gnome Cog. Le monocle de Zzarc'Vul est le seul morceau de verre du Bois de la Pénombre qui convienne.",al={"pourquoi avoir besoin du monocle","à quoi sert le monocle","lentille de télescope"}},{q="Comment un ogre a-t-il obtenu un monocle géant ?",a="Le récit n'explique pas comment Zzarc'Vul a obtenu le monocle. Il indique seulement qu'il en possède un assez grand pour le télescope de Viktori.",al={"pourquoi un ogre a-t-il un monocle","histoire des lunettes de lecture d'ogre"}},{q="Où se trouve le Tertre des ogres Vul'Gol ?",a="Le Tertre des ogres Vul'Gol se trouve dans les collines du sud du Bois de la Pénombre, au sud de la route principale entre Sombre-Comté et la frontière occidentale.",al={"où se trouve vul'gol","tertre des ogres bois de la pénombre"}}},fx={["94fbe42d"]={q="Qu'est-ce que le Monocle d'ogre ?",a="Le Monocle d'ogre est une lentille optique surdimensionnée portée en guise d'œilleton par Zzarc'Vul, un ogre éminent résidant au sein du Tertre des ogres Vul'Gol, dans le sud du Bois de la Pénombre. Bien que ce genre d'accessoire optique soit extrêmement rare chez les ogres, son immense lentille en verre le rend particulièrement adapté aux machines optiques lourdes.",al={"qu'est-ce que le monocle d'ogre","objet monocle d'ogre","œilleton d'ogre"}}},fp="14,186,14.351.0,22.286.0,31.87.0,54.175.0,36.131.0,40.127.0"}
P.entries["item:okra"] = {n="Okra mûr",s="À la Ferme des Saldean, Okra mûr aide à nourrir les colons de la Marche de l’Ouest. Cette culture pousse dans les parcelles et épaissit les ragoûts qui les font vivre.",h="À la Ferme des Saldean, Okra mûr aide à nourrir les colons de la Marche de l’Ouest.",kw={"culture","ferme","okra mûr","saldean","salma saldean","légume","le ragoût de la marche de l'ouest"},ang={["faction:Alliance"]="Les nobles de Hurlevent dînent de viandes importées, tandis que les colons de l’Alliance aux frontières cultivent des plantes résistantes comme Okra mûr au milieu des ruines de la Marche de l’Ouest.",["profession:Cooking"]="Un cuisinier itinérant sait qu’un bon ragoût demande plus que de la viande crue. Okra mûr apporte à la maigre récolte sauvage l’amidon et la consistance d’un repas chaud."},sec={{t="Une culture de la Ferme des Saldean",b="La Ferme des Saldean produit encore des légumes, tandis qu’une grande partie de la Marche de l’Ouest reste en friche, menacée par les hors-la-loi défias et les attaques de golems des moissons détraqués. Okra mûr pousse dans les parcelles labourées autour de la ferme et résiste aux conditions difficiles. Il nourrit les colons locaux lorsque le commerce et les ravitaillements de Hurlevent viennent à manquer."},{t="Le ragoût de la marche de l'Ouest",b="Le fameux le ragoût de la marche de l'Ouest de Salma Saldean dépend d’Okra mûr. Elle mêle des gousses tranchées à la viande que les colons peuvent chasser dans les plaines poussiéreuses, notamment de la chair de vautour, des groins de goret sanglant et des yeux de murlocs côtiers. Les gousses se délitent à la chaleur et épaississent le bouillon clair pour en faire un repas nourrissant et reconstituant. Pour les colons qui s’accrochent à leurs fermes, l’Okra mûr frais transforme une maigre collecte en un souper chaud."}},faq={{q="Où pousse Okra mûr dans la Marche de l’Ouest ?",a="Okra mûr pousse dans les parcelles labourées de la Ferme des Saldean, le long de la route centrale de la Marche de l’Ouest. Les plants verts prospèrent dans les sillons près de la ferme de Saldean le fermier.",al={"emplacement d’okra mûr","où trouver okra mûr","où pousse okra mûr"}},{q="À quoi sert Okra mûr ?",a="Salma Saldean récolte Okra mûr à la Ferme des Saldean pour préparer son le ragoût de la marche de l'Ouest emblématique. Son amidon naturel épaissit le bouillon, qui mêle viande de vautour, groins de sanglier et yeux de murlocs pour former un repas consistant.",al={"usages d’okra mûr","à quoi sert okra mûr","pourquoi ai-je besoin d’okra mûr"}},{q="Pourquoi Okra mûr est-il important pour les Saldean ?",a="Le commerce étant perturbé et le royaume apportant peu d’aide, les colons comptent sur ce qu’ils peuvent cultiver et chasser. Okra mûr est l’une des rares cultures encore cultivées à la Ferme des Saldean. Il aide à nourrir la famille et les voyageurs de passage.",al={"okra mûr saldean","importance d’okra mûr"}}},fx={["301f0b5e"]={q="Qu'est-ce que l'Okra mûr ?",a="L'Okra mûr est un légume comestible qui pousse dans les sols labourés de la Marche de l’Ouest. Cultivé dans des fermes telles que celle de Saldean, ses gousses sont suffisamment robustes pour survivre au climat difficile de la région et constituer une culture de base fiable pour les fermiers en difficulté.",al={"qu'est-ce que l'okra mûr","objet okra mûr","plante okra mûr"}},["5bbd3a8c"]={q="D'où vient l'Okra mûr ?",a="L'Okra mûr est cultivé localement dans les fermes de la Marche de l’Ouest, notamment par Salma et Saldean le fermier à la ferme Saldean. Bien qu'une grande partie de la campagne soit tombée en ruine et à l'abandon, des cultures robustes comme l'Okra mûr continuent de pousser dans les champs labourés encore existants.",al={"d'où vient l'okra mûr","qui cultive l'okra mûr","origine de l'okra mûr"}},b45f6830={q="Pourquoi Salma Saldean veut-elle de l'Okra mûr ?",a="Salma Saldean a besoin d'Okra mûr frais, ingrédient essentiel de son célèbre Westfall Stew. Tranché et mijoté avec du gibier sauvage et des viandes locales, ce légume aide à épaissir le bouillon savoureux, offrant un repas riche et copieux pour nourrir les gens des plaines.",al={"pourquoi l'okra mûr est-il recherché","pourquoi salma veut-elle de l'okra mûr","qui veut de l'okra mûr"}}},fp="4,136,26.306.0,13.393.0,33.147.0,22.188.0,38.219.0"}
P.entries["item:or-kalar-s-head"] = {n="Or'Kalar's Head",s="« Or'Kalar's Head » prouve qu’une source dangereuse se cache derrière les attaques de Trépas-d'Orgrim. Korin Fel vous demande de l’apporter à l’avant-poste.",h="« Or'Kalar's Head » prouve qu’une source dangereuse se cache derrière les attaques de Trépas-d'Orgrim.",kw={"hautes-terres arathies","trépas-d'orgrim","korin fel","mug'thol","or'kalar","tête d’or'kalar","stromgarde","la tour d'arathor"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez aider à protéger Trépas-d'Orgrim et le mari de Korin Fel contre l’attaque d’Or'Kalar."},sec={{t="Une menace à Trépas-d'Orgrim",b="Korin Fel vous envoie chercher Or'Kalar près de La Tour d'Arathor. Cet ogre sert Mug'thol à Stromgarde et nourrit une haine féroce envers le mari de Korin, qui l’a vaincu il y a des années. Korin pense qu’Or'Kalar a tendu un piège à son mari. Elle vous demande de le tuer et d’apporter sa tête à Trépas-d'Orgrim."}},faq={{q="Qui est Or'Kalar ?",a="Or'Kalar est un ogre de Stromgarde qui sert Mug'thol et déteste le mari de Korin Fel depuis que celui-ci l’a vaincu il y a des années.",al={"or'kalar","identité d’or'kalar"}},{q="Pourquoi Korin Fel veut-elle la mort d’Or'Kalar ?",a="Korin pense qu’Or'Kalar a tendu un piège à son mari. Elle veut que l’ogre soit tué pour le protéger, ainsi que Trépas-d'Orgrim.",al={"pourquoi tuer or'kalar","requête de korin"}},{q="Où trouver Or'Kalar ?",a="Or'Kalar se trouve près de La Tour d'Arathor, dans les Hautes-terres Arathies.",al={"emplacement d’or'kalar","ogre de la tour"}},{q="Qui reçoit Or'Kalar's Head ?",a="Korin Fel reçoit Or'Kalar's Head à l’avant-poste de Trépas-d'Orgrim.",al={"où apporter la tête","tête de korin fel"}}},fp="15,129,22.293.0,16.112.0,38.111.0,26.62.0,29.61.0"}
P.entries["item:oracle-crystal"] = {n="Cristal d'oracle",s="Le Cristal d'oracle est un objet façonné par les nagas pour leurs oracles, sur la côte de Désolace. Maurin Craquossement en cherche un alors qu'il s'intéresse à un seigneur démon.",h="Le Cristal d'oracle est un objet façonné par les nagas pour leurs oracles, sur la côte de Désolace.",kw={"azrethoc","désolace","maurin craquossement","nagas","oracle","cristal d'oracle","slitherblade"},sec={{t="Artisanat naga",b="Maurin Craquossement veut obtenir un Cristal d'oracle auprès des nagas Slitherblade, sur la côte nord-ouest de Désolace. Les nagas façonnent ces cristaux pour leurs oracles, qui vivent au milieu du vaste récif de corail au large. Maurin tient beaucoup à ce cristal et compte s'en servir dans sa quête du seigneur démon Azrethoc."}},faq={{q="Qu'est-ce qu'un Cristal d'oracle ?",a="Un Cristal d'oracle est un objet façonné par les nagas pour leurs oracles.",al={"cristal d'oracle","qu'est-ce que le cristal","cristal naga"}},{q="Qui veut le Cristal d'oracle ?",a="Maurin Craquossement demande un Cristal d'oracle alors qu'il poursuit le seigneur démon Azrethoc.",al={"qui a besoin du cristal","cristal de maurin","ce que veut craquossement"}},{q="Où trouver un Cristal d'oracle ?",a="Les oracles Slitherblade vivent au large, le long de la côte nord-ouest de Désolace.",al={"où trouver le cristal","emplacement du cristal d'oracle","trouver le cristal naga"}},{q="Qui utilise les Cristaux d'oracle ?",a="Les nagas façonnent des Cristaux d'oracle pour leurs oracles.",al={"qui l'utilise","oracles nagas","utilité du cristal"}}},fp="14,164,10.291.0,26.77.0,29.85.0,35.81.0,25.56.0"}
P.entries["item:ordanus-head"] = {n="Tête d'Ordanus",s="À la Retraite de Raynebois, la Tête d’Ordanus est recherchée comme preuve de la chute du Gardien Ordanus. Braelyn Brasemain, une magicienne elfe de sang, la cherche en Orneval.",h="À la Retraite de Raynebois, la Tête d’Ordanus est recherchée comme preuve de la chute du Gardien Ordanus.",kw={"orneval","braelyn brasemain","cenarius","gardien du bosquet","ordanus","tête d'ordanus","retraite de raynebois","les serres-rocheuses","retraite de sunrock"},ang={["class:Druid"]="Pour un druide, porter la tête tranchée d’un fils aîné de Cenarius rappelle crûment l’animosité tenace que les sorciers arcaniques nourrissent encore envers les protecteurs de la nature.",["faction:Horde"]="Pour un membre de la Horde, abattre Ordanus et remettre sa tête à Braelyn contribue à consolider l’emprise de la Horde sur les frontières disputées des Serres-Rocheuses et d’Orneval. Cela affaiblit les dirigeants locaux des elfes de la nuit."},sec={{t="Une vieille rancune",b="Le Gardien Ordanus était un ancien gardien du bosquet et l’un des fils aînés de Cenarius. Ses druides étouffaient la magie au sommet des Serres-Rocheuses, et Braelyn Brasemain gravit ces hauteurs sur ordre de son maître. Elle comptait mettre fin à leur emprise et se venger d’Ordanus. Avant qu’elle ne puisse frapper, le gardien fut emmené secrètement au cœur d’Orneval.\n\nBraelyn usa de divination arcanique pour scruter la forêt à travers la canopée et découvrit le sanctuaire d’Ordanus dans les branches de la Retraite de Raynebois. Là, elle réclama sa tête tranchée comme preuve que l’arrogance du demi-dieu sauvage avait reçu une réponse."},{t="Le prix de l’arrogance",b="Braelyn Brasemain connaissait Ordanus depuis longtemps et nourrit une vieille rancune contre lui. Elle déteste aussi les druides qui cherchent à étouffer la magie. De son vivant, Ordanus se jugeait supérieur même à l’ancienne noblesse des Bien-nés.\n\nEn prenant sa tête, Braelyn s’attaque à l’héritage de Cenarius. Elle affirme qu’aucun gardien de la nature ne peut endiguer le retour de la puissance magique brute."}},faq={{q="Qui était le Gardien Ordanus ?",a="Le Gardien Ordanus était un ancien gardien du bosquet et l’un des fils aînés de Cenarius. Il y a longtemps, il s’opposa aux pratiquants des arts arcaniques parmi la noblesse des elfes de la nuit et méprisait profondément ceux qui les pratiquaient.",al={"qui est ordanus","histoire d’ordanus","qu’est-ce qu’ordanus"}},{q="Où récupérer cette tête ?",a="La Tête d’Ordanus se récupère sur le Gardien Ordanus, au sommet de la plateforme de bois surélevée de la Retraite de Raynebois, une enclave fortifiée des elfes de la nuit, perchée dans la canopée au centre d’Orneval.",al={"où trouver la tête d’ordanus","emplacement d’ordanus","ordanus à la retraite de raynebois"}},{q="Pourquoi Braelyn Brasemain veut-elle sa tête ?",a="Braelyn Brasemain connaissait Ordanus depuis longtemps et méprisait son arrogance. Il se croyait supérieur même aux Bien-nés. Elle déteste aussi les druides et les fils de Cenarius, qui cherchent à endiguer le flot de magie et ont emmené Ordanus loin du sommet avant qu’elle ne puisse l’atteindre.",al={"pourquoi braelyn veut la tête d’ordanus","rancune de braelyn","pourquoi tuer ordanus"}},{q="Que se passe-t-il après la remise de la tête ?",a="Remettre la Tête d’Ordanus à Braelyn, à la Retraite de Sunrock, acquitte sa dette de sang. Elle récompense le mercenaire avec le puissant présent qu’elle lui avait promis.",al={"remettre la tête d’ordanus","après la mort d’ordanus","récompense de quête de braelyn brasemain"}}},fx={e1459048={q="D'où vient la Tête d'Ordanus ?",a="Ce sinistre trophée a été pris directement au gardien Ordanus, l'un des fils aînés du demi-dieu de la forêt, Cenarius. Bien qu'on l'ait cru en sécurité au sommet du Pic des Serres-Rocheuses, Ordanus a fui vers Orneval et s'est réfugié dans les hauteurs de la Retraite de Raynebois avant d'être traqué.",al={"origine de la tête d'ordanus","d'où vient la tête d'ordanus","à qui appartient la tête d'ordanus"}}},fp="13,146,22.579.0,19.368.1,23.225.0,29.161.0,40.265.0,41.141.1"}
P.entries["item:orendil-s-cure"] = {n="Jouvence d'Orendil",s="Au nord d’Orneval, Orendil Largefeuille prépare un remède pour une enfant malade d’Astranaar. Le rare Cheveu de Bathran redonne espoir à Pelturas Blanchelune pour sa fille Relara.",h="Au nord d’Orneval, Orendil Largefeuille prépare un remède pour une enfant malade d’Astranaar.",kw={"orneval","astranaar","cheveu de bathran","orendil largefeuille","jouvence d'orendil","pelturas blanchelune","relara"},ang={["profession:Herbalism"]="Les plantes indigènes d’Orneval possèdent de grands pouvoirs médicinaux. Le Cheveu de Bathran est l’une de ces herbes ; il ne pousse que dans quelques recoins ombragés de la forêt.",["race:NightElf"]="Pour les Elfes de la nuit d’Astranaar, sauver Relara est urgent pour toute la communauté. Les ermites comme Orendil apportent leur connaissance des bois, tandis que la foi en Elune apporte l’aide divine."},sec={{t="L’espoir d’un père",b="Relara Whitemoon tomba gravement malade alors qu’elle était encore jeune, et les remèdes ordinaires échouèrent à Astranaar. Son père, Pelturas Blanchelune, demanda de l’aide à Orendil Largefeuille, un ermite qui vit dans le nord d’Orneval et maîtrise la médecine naturelle.\n\nOrendil récolta des brassées de Cheveu de Bathran, une plante rare, dans les ruines hantées du Repaire de Bathran, puis prépara une potion pour Relara. À l’arrivée du flacon, Pelturas retrouve espoir. Pourtant, le remède ne fait que ralentir la maladie ; il doit donc chercher les autres remèdes suggérés par Orendil."}},faq={{q="À quoi sert la Jouvence d’Orendil ?",a="La Jouvence d’Orendil est destinée à soulager Relara Whitemoon, une jeune enfant elfe de la nuit à Astranaar. Sa maladie soudaine et grave l’a laissée très affaiblie.",al={"utilité de la jouvence d’orendil","effet du remède","à qui est destiné le remède"}},{q="Qui a préparé le remède ?",a="Orendil Largefeuille a préparé le remède. C’est un herboriste elfe de la nuit qui vit à l’écart dans les forêts du nord d’Orneval, réputé pour sa maîtrise des plantes et des remèdes forestiers.",al={"qui a préparé la jouvence d’orendil","créateur de la jouvence d’orendil"}},{q="Quels ingrédients ont été utilisés ?",a="Le remède contient du Cheveu de Bathran, une plante délicate et rare récoltée parmi les ruines du Repaire de Bathran, dans le nord d’Orneval.",al={"ingrédients du remède","composition de la jouvence d’orendil"}},{q="Cette potion guérit-elle complètement l’enfant ?",a="Non. Pelturas apprend que la Jouvence d’Orendil ne fait que ralentir la maladie dont souffre sa fille. Il cherche donc le remède plus puissant suggéré par Orendil : la Larme d’Elune.",al={"la potion a-t-elle guéri relara","relara est-elle guérie"}}},fx={["8e86537e"]={q="Qu'est-ce que la Jouvence d'Orendil ?",a="La Jouvence d'Orendil est une concoction médicinale préparée par l'herboriste Orendil Largefeuille dans le nord d'Orneval. Conçue comme un traitement spécialisé pour une maladie soudaine et grave, elle représente un effort urgent pour sauver la vie d'une jeune enfant elfe de la nuit souffrant d'une affliction mystérieuse.",al={"histoire de la jouvence d'orendil","qu'est-ce que la jouvence d'orendil","remède d'orendil"}},["6add91d1"]={q="Pourquoi la Jouvence d'Orendil est-elle nécessaire ?",a="À Astranaar, Relara, la jeune fille de Pelturas Blanchelune, est gravement malade. Désespéré de trouver un remède alors que les traitements classiques se sont avérés inefficaces, son père a sollicité l'expertise d'Orendil Largefeuille. L'herboriste a préparé ce mélange spécifique dans l'espoir de stabiliser l'enfant avant que la maladie ne l'emporte.",al={"pourquoi avoir besoin de la jouvence d'orendil","qui a besoin de la jouvence d'orendil","pourquoi livrer la jouvence d'orendil"}}},fp="14,163,15.497.0,32.142.0,21.161.0,38.126.0,43.152.1"}
P.entries["item:orwin-s-shovel"] = {n="Orwin's Shovel",s="Orwin Gizzmick prête sa pelle à Camp Mojache pour chercher du cobalt des Gordunni. Ce minerai bleu luminescent est enfoui à l’avant-poste des Gordunni, où les ogres le gardent de près.",h="Orwin Gizzmick prête sa pelle à Camp Mojache pour chercher du cobalt des Gordunni.",kw={"camp mojache","féralas","cobalt des gordunni","avant-poste des gordunni","orwin gizzmick","orwin's shovel","pelle"},ang={["profession:Mining"]="En tant que mineur, vous connaissez la valeur d’un filon enfoui. Orwin's Shovel vous mène vers le cobalt caché parmi les ogres Gordunni."},sec={{t="L’outil d’un prospecteur",b="Orwin Gizzmick vient tout juste d’arriver en Féralas, et le minerai enfoui par les ogres Gordunni a éveillé son intérêt. Depuis Camp Mojache, il vous envoie vers le nord avec sa pelle pour récolter du cobalt dans leur avant-poste. La lueur bleue indique où creuser. Orwin compte emporter les échantillons et trouver un acheteur."}},faq={{q="À qui appartient Orwin's Shovel ?",a="Orwin Gizzmick vous prête Orwin's Shovel à Camp Mojache pour que vous puissiez creuser à la recherche de cobalt des Gordunni.",al={"pelle d’orwin","pelle orwin","qui a la pelle"}},{q="À quoi sert Orwin's Shovel ?",a="Orwin's Shovel sert à déterrer du cobalt des Gordunni à l’avant-poste des Gordunni en Féralas.",al={"utilité de la pelle","avec quoi creuser","pelle à cobalt"}},{q="Où utiliser Orwin's Shovel ?",a="Vous utilisez Orwin's Shovel à l’avant-poste des Gordunni, au nord de Camp Mojache, où le cobalt est enfoui.",al={"où utiliser la pelle","pelle avant-poste des gordunni","où creuser pour trouver du cobalt"}},{q="Pourquoi Orwin veut-il du cobalt des Gordunni ?",a="Orwin espère trouver quelqu’un qui paiera bien le cobalt pendant qu’il poursuit son voyage.",al={"pourquoi le cobalt","orwin veut du cobalt","acheteur de cobalt"}}},fp="14,175,19.298.0,24.89.0,27.84.0,30.97.0,36.89.0"}
P.entries["item:oslow-s-toolbox"] = {n="Boîte d'outils d'Oslow",s="Au fond du Lac placide, les outils d’Oslow reposent là où les orcs Rochenoire ont coulé le bateau qui les transportait depuis Comté-de-l’Or.",h="Au fond du Lac placide, les outils d’Oslow reposent là où les orcs Rochenoire ont coulé le bateau qui les...",kw={"contremaître oslow","lac placide","comté-du-lac","oslow","les carmines","coffre englouti","the lost tools","boîte à outils"},ang={["faction:Alliance"]="Comté-du-Lac est presque isolé sous le siège des forces Rochenoire. Récupérer les provisions d’Oslow est essentiel pour entretenir les défenses de la ville."},sec={{t="Une traversée fatidique",b="Le Contremaître Oslow a besoin d’outils de construction pour entretenir les défenses et les bâtiments de Comté-du-Lac. Les orcs Rochenoire assiègent Les Carmines, et le pont menant à la ville est détruit. La cargaison venue de Comté-de-l’Or a donc traversé le Lac placide en barque.\n\nLes forces Rochenoire ont frappé l’embarcation avec une catapulte. Le bateau et le lourd coffre d’Oslow ont sombré dans les profondeurs, parmi les murlocs."}},faq={{q="Pourquoi la Boîte d’outils d’Oslow se trouve-t-elle au fond du lac ?",a="Les outils étaient transportés de Comté-de-l’Or à Comté-du-Lac. Le pont étant détruit, ils ont traversé le Lac placide en bateau. Les orcs Rochenoire ont frappé la barque avec une catapulte, envoyant la boîte d’outils au fond du lac.",al={"pourquoi la boîte à outils est dans l’eau","comment oslow a perdu ses outils","histoire de la boîte à outils engloutie"}},{q="À qui appartient cette boîte à outils ?",a="Le Contremaître Oslow possède la boîte à outils et supervise les travaux de construction et de réparation à Comté-du-Lac. Sans matériel adapté, entretenir les fortifications de la ville face aux attaques incessantes est presque impossible.",al={"qui est oslow","propriétaire d’oslow","outils du contremaître oslow"}},{q="Où les outils ont-ils sombré dans le Lac placide ?",a="Les outils reposent dans un coffre englouti, près de l’épave de la barque, dans le Lac placide. Le coffre se trouve parmi des rochers sous-marins, au sud d’un important campement de murlocs sur la rive.",al={"emplacement de la boîte à outils","où se trouve le coffre englouti","où le bateau a sombré"}},{q="Quelles menaces gardent le coffre englouti ?",a="Des murlocs hostiles et des bêtes aquatiques prédatrices infestent les eaux autour de l’épave. De dangereux Lake Threshers rôdent dans les parties les plus profondes du lac.",al={"dangers près de la boîte à outils","ennemis du lac placide","qu’est-ce qui garde les outils d’oslow"}}},fx={["543d5407"]={q="Pourquoi le Contremaître Oslow a-t-il besoin que sa caisse à outils soit récupérée ?",a="Comté-du-Lac est sous un siège intense, laissant la ville isolée et en manque désespéré de fournitures essentielles. En tant que contremaître de la ville, Oslow a besoin de son équipement pour entretenir et réparer les structures et les défenses de Comté-du-Lac. Comme le chariot de livraison venant du Comté-de-l’Or n'a pas pu traverser le pont détruit, la perte des outils de remplacement dans le lac a paralysé les travaux de construction critiques, rendant leur récupération vitale pour la survie de la ville.",al={"pourquoi oslow veut sa caisse à outils","pourquoi oslow a besoin d'outils","pourquoi récupérer la caisse à outils d'oslow"}}},fp="15,106,18.372.0,49.208.0,22.198.0,43.173.0,36.144.0"}
P.entries["item:osric-s-crate"] = {n="Caisse d'Osric",s="À la Colline des Sentinelles, la Caisse d'Osric apporte des armures neuves de Hurlevent à The People's Militia. Les défenseurs affrontent la Confrérie défias et des gnolls maraudeurs sans l'armée de Hurlevent.",h="À la Colline des Sentinelles, la Caisse d'Osric apporte des armures neuves de Hurlevent à The People's...",kw={"dungar longdrink","griffon","osric","caisse d'osric","the people's militia","intendant lewis","colline des sentinelles","marche de l’ouest"},ang={["faction:Alliance"]="Pour l'Alliance, chaque livraison d'armes et d'armures qui atteint la Colline des Sentinelles contribue à empêcher la Confrérie défias de s'emparer des frontières occidentales du royaume."},sec={{t="Ravitaillement du front",b="L'Intendant Lewis reçoit la cargaison et répartit l'équipement de protection entre les combattants volontaires. La Couronne n'apporte aucun soutien officiel à The People's Militia. Ces armures neuves doivent aider les volontaires à tenir leur position."},{t="Réseau de messagers griffons",b="Depuis le perchoir de Dungar Longdrink, dans le Quartier commerçant de Hurlevent, un griffon transporte la caisse jusqu'à Thor, à la Colline des Sentinelles. Le vol évite les routes dangereuses de la Forêt d’Elwynn et la traversée de la Marche de l’Ouest, où des bandits peuvent tendre une embuscade aux voyageurs. En temps de guerre, les griffons aident à ravitailler les garnisons frontalières."}},faq={{q="Que contient la Caisse d'Osric ?",a="La Caisse d'Osric contient des armures de protection fabriquées à Hurlevent. L'Intendant Lewis reçoit la livraison et s'apprête à la répartir entre les combattants qui défendent la Colline des Sentinelles.",al={"contenu de la caisse","contenu de la caisse d'osric","contenu caisse osric"}},{q="Qui est Osric ?",a="Osric est un armurier de Hurlevent qui a préparé la cargaison pour The People's Militia, qui tient la Marche de l’Ouest.",al={"qui est osric","qui a envoyé la caisse d'osric"}},{q="Qui reçoit la caisse ?",a="L'Intendant Lewis reçoit la caisse. Il gère le ravitaillement et l'équipement de The People's Militia à la Colline des Sentinelles, dans la Marche de l’Ouest.",al={"où va la caisse","à qui donner la caisse d'osric","destinataire de la caisse"}},{q="Pourquoi livrer la caisse par griffon ?",a="Les bandits et les hors-la-loi rendent périlleuses les routes de Hurlevent, de la Forêt d’Elwynn et de la Marche de l’Ouest. Un griffon transporte rapidement et en toute sécurité les armures depuis Dungar Longdrink, à Hurlevent, jusqu'à Thor, à la Colline des Sentinelles.",al={"pourquoi transporter la caisse par les airs","pourquoi utiliser des griffons","vol de la caisse d'osric"}}},fx={["34d354cb"]={q="Qu'est-ce que la Caisse d'Osric ?",a="La Caisse d'Osric est une cargaison d'armures expédiée depuis Hurlevent. Elle est destinée aux défenseurs stationnés à la Colline des Sentinelles dans la Marche de l’Ouest, qui manquent désespérément d'équipement tout en résistant contre The Defias Brotherhood.",al={"qu'est-ce que la caisse d'osric","objet caisse d'osric","que contient la caisse d'osric"}},["091b5cbb"]={q="D'où vient la Caisse d'Osric et qui l'a préparée ?",a="La caisse provient de Hurlevent ; elle a été préparée et expédiée par Osric pour ravitailler The People's Militia. Le maître des griffons Dungar Longdrink vous la confie pour que vous la transportiez à dos de griffon à travers le royaume jusqu'à la Marche de l’Ouest.",al={"qui a fabriqué la caisse d'osric","d'où vient la caisse d'osric","origine de la caisse d'osric"}},["11fb3015"]={q="Pourquoi quelqu'un voudrait-il la Caisse d'Osric ?",a="L'Intendant Lewis et The People's Militia de la Colline des Sentinelles ont un besoin urgent de l'armure qu'elle contient. La Marche de l’Ouest ayant été abandonnée par les forces royales et envahie par des hors-la-loi, chaque morceau d'équipement de protection est vital pour maintenir les défenseurs en vie.",al={"pourquoi livrer la caisse d'osric","pourquoi lewis veut-il la caisse d'osric","but de la caisse d'osric"}}},fp="13,181,22.237.0,22.301.0,29.174.0,13.101.0,23.128.0,38.199.0"}
P.entries["item:overdue-package"] = {n="Overdue Package",s="Overdue Package figure parmi les marchandises que Krinkle Goodsteel recherche pour son travail à Gadgetzan. Son registre le mentionne aux côtés de matériaux provenant de plusieurs lieux lointains.",h="Overdue Package figure parmi les marchandises que Krinkle Goodsteel recherche pour son travail à Gadgetzan.",kw={"epave de beezil","caisse endommagée","marécage d’âprefange","gadgetzan","registre de goodsteel","krinkle goodsteel","overdue package"},sec={{t="Parmi les marchandises",b="Krinkle Goodsteel rassemble des marchandises de la Gorge des Vents brûlants et d’ailleurs, à Gadgetzan. Son registre mentionne Overdue Package, ainsi qu’un crystal leg shaft et un balanced flameberge. Le paquet se trouve dans une caisse endommagée, à l’Épave de Beezil, dans le Marécage d’Âprefange."}},faq={{q="Qu’est-ce qu’Overdue Package ?",a="Overdue Package figure parmi les marchandises inscrites dans le registre de Krinkle Goodsteel pour son travail à Gadgetzan.",al={"overdue package","paquet pour krinkle","paquet de goodsteel"}},{q="Où se trouve le paquet ?",a="Overdue Package se trouve dans une caisse endommagée, à l’Épave de Beezil, dans le Marécage d’Âprefange.",al={"où se trouve le paquet","emplacement du paquet","trouver overdue package"}},{q="Qui veut le paquet ?",a="Krinkle Goodsteel, à Gadgetzan, recherche Overdue Package ainsi que les autres marchandises de son registre.",al={"qui le veut","paquet de krinkle","paquet pour qui"}},{q="Pourquoi est-il en retard ?",a="Son nom indique qu’il est en retard, mais aucune raison n’est donnée.",al={"pourquoi en retard","paquet en retard","qu’est-ce qui est en retard"}}},fp="15,166,15.262.0,28.102.0,21.80.0,22.98.0,18.67.0"}
P.entries["item:package-of-empty-ooze-containers"] = {n="Caisse de pots de Limon vides",s="À Forgefer, une caisse de pots de limon vides part pour des prélèvements dangereux à Gangrebois. Laris Bringuefourbi fournit des bocaux capables de contenir du limon corrompu et maudit sans se dissoudre.",h="À Forgefer, une caisse de pots de limon vides part pour des prélèvements dangereux à Gangrebois.",kw={"récipients","maudit","gangrebois","forgefer","bocaux","laris bringuefourbi","limon","caisse","gelée","corrompu"},ang={["faction:Alliance"]="En tant que membre de l'Alliance, récolter ces échantillons vous aide à suivre les recherches inquiétantes de la Société royale des apothicaires des Réprouvés.",["race:Gnome"]="En tant que gnome, les recherches de Laris Bringuefourbi sur le limon lui donnent l'occasion de montrer aux Nains de Forgefer qu'accueillir les gnomes réfugiés en valait la peine."},sec={{t="Équipement de recherche de terrain",b="Laris Bringuefourbi confie une douzaine de bocaux vides aux voyageurs qui partent pour Gangrebois. Six sont destinés au limon maudit et six au limon corrompu. Les spécimens bruts sont caustiques, et ils peuvent ronger les bagages ordinaires. Un verre solide et scellé retient les résidus acides pendant le voyage à travers les continents jusqu'à l'établi de Laris, à Forgefer."},{t="Le mystère du limon",b="L'intérêt de Laris Bringuefourbi pour le limon dépasse la simple lubie d'un excentrique. Il a vu des chercheurs réprouvés de la Société royale des apothicaires récolter ces étranges organismes à travers Azeroth, et se demande ce qu'ils savent. Il soupçonne que les gelées pourraient être des sécrétions primordiales liées à la création du monde. Des agents de terrain rassemblent des preuves dans ses bocaux, qu'il espère voir lui valoir la reconnaissance de la Ligue des explorateurs."}},faq={{q="Que contient la caisse de pots de limon vides ?",a="La caisse contient douze bocaux à spécimens vides : six pour le limon maudit et six pour le limon corrompu.",al={"contenu de la caisse","que contient la caisse","limon dans les bocaux"}},{q="Qui fournit cette caisse ?",a="Laris Bringuefourbi, un érudit et chercheur gnome de Forgefer, fournit la caisse aux aventuriers de l'Alliance.",al={"qui fournit les bocaux","objet de quête de laris bringuefourbi","où trouver la caisse de limon"}},{q="Où ces récipients sont-ils destinés à être utilisés ?",a="Les récipients sont destinés à Gangrebois. Là-bas, les aventuriers vainquent des limons corrompus et maudits, puis prélèvent des résidus sur les créatures vaincues.",al={"où utiliser les bocaux à limon","zone des limons","emplacement des bocaux à limon"}},{q="Pourquoi Laris Bringuefourbi veut-il ces échantillons de limon ?",a="Laris a vu la Société royale des apothicaires des Réprouvés récolter du limon à travers le monde et veut en percer les secrets. Il soupçonne que les gelées pourraient être des sécrétions primordiales liées à la création d'Azeroth, et espère que ces preuves lui vaudront du prestige au sein de la Ligue des explorateurs.",al={"pourquoi récolter du limon","recherches de bringuefourbi","pourquoi laris veut du limon"}}},fx={d8bf9111={q="Qu'est-ce que la Caisse de pots de Limon vides ?",a="Il s'agit d'un kit de terrain assemblé par le chercheur gnome Laris Bringuefourbi à Forgefer. Le colis contient un ensemble de bocaux spécialement préparés, conçus pour recueillir et stocker en toute sécurité des échantillons récoltés sur les limons et vases corrompus trouvés à travers Gangrebois.",al={"qu'est-ce que la caisse de pots de limon vides","paquet de pots de limon","lot de pots de limon vides"}}},fp="32,181,24.324.0,23.402.0,52.91.0,26.110.0,44.137.0,50.260.0"}
P.entries["item:painted-gnoll-armband"] = {n="Brassard peint de gnoll",s="À la Garnison du ruisseau de l'ouest, les brassards peints de gnoll prouvent que des gnolls Riverpaw ont été tués. Leurs meutes pressent la frontière occidentale de la forêt d’Elwynn.",h="À la Garnison du ruisseau de l'ouest, les brassards peints de gnoll prouvent que des gnolls Riverpaw ont été...",kw={"prime","adjoint rainer","forêt d’elwynn","gnolls","brassard peint de gnoll","riverpaw","lac du cairn","garnison du ruisseau de l'ouest"},ang={["faction:Alliance"]="En tant qu’aventurier de l’Alliance, récupérer ces brassards aide la Garnison du ruisseau de l'ouest à défendre la frontière occidentale de Hurlevent, tandis que l’armée permanente de la cité est mobilisée ailleurs."},sec={{t="Trophées des Riverpaw",b="Les guerriers et charognards Riverpaw portent des bandes grossières ornées de motifs tribaux rudimentaires. Ces brassards viennent des gnolls Riverpaw qui rôdent aux frontières sauvages de la forêt d’Elwynn. Les défenseurs de Hurlevent font face à une menace grandissante près du lac du Cairn et dans les bois au sud de la Garnison du ruisseau de l'ouest."},{t="Prime de la Garnison du ruisseau de l'ouest",b="L’armée de Hurlevent est dispersée dans tout le royaume, ce qui laisse la Garnison du ruisseau de l'ouest à court d’hommes pour protéger la frontière occidentale. L’adjoint Rainer offre une prime permanente pour l’élimination des Riverpaw outrunners et des Riverpaw runts. Les brassards peints permettent aux adjoints de comptabiliser les primes et de réduire les meutes près des fermes voisines."}},faq={{q="Pourquoi la Garnison du ruisseau de l'ouest veut-elle ces brassards ?",a="L’adjoint Rainer, à la Garnison du ruisseau de l'ouest, récupère les brassards comme preuve que des gnolls Riverpaw ont été tués. Les troupes de la garnison ne peuvent pas contenir seules les meutes qui avancent. Hurlevent verse donc des primes à ceux qui rapportent ces trophées.",al={"pourquoi ces brassards","qui veut les brassards peints de gnoll","prime de l’adjoint rainer"}},{q="Quels gnolls portent ces brassards peints ?",a="Les gnolls Riverpaw portent ces brassards peints. Les Riverpaw outrunners et les Riverpaw runts infestent les bois au sud de la Garnison du ruisseau de l'ouest et les rives autour du lac du Cairn.",al={"où trouver les brassards","qui donne le brassard peint de gnoll","quels gnolls portent des brassards"}},{q="Pourquoi les gnolls Riverpaw sont-ils dans la forêt d’Elwynn ?",a="Les meutes Riverpaw ont avancé vers l’est le long des frontières de la forêt d’Elwynn et établi des camps près du lac du Cairn et aux abords de la forêt. Les forces militaires du royaume étant réduites, elles chassent, fouillent les environs et menacent les communautés voisines.",al={"pourquoi les gnolls sont-ils ici","invasion des gnolls à elwynn","riverpaw à elwynn"}},{q="Que signifie la peinture sur les brassards ?",a="La peinture marque les trophées pris aux gnolls Riverpaw et aide à prouver leurs éliminations à l’adjoint Rainer. La signification ou le rang associé aux motifs n’est pas précisé.",al={"pourquoi sont-ils peints","motifs des brassards de gnoll"}}},fx={["586b453e"]={q="Qu'est-ce qu'un Brassard peint de gnoll ?",a="Un Brassard peint de gnoll est une parure personnelle rudimentaire portée par les gnolls de la Patte-de-rivière. Fabriqués et peints par la meute, ces brassards marquent leur présence dans les régions frontalières de la Forêt d’Elwynn. Pour l'armée d'Hurlevent, ils servent de preuve physique indéniable qu'un gnoll maraudeur a été tué.",al={"qu'est-ce qu'un brassard peint de gnoll","histoire du brassard peint de gnoll","brassard de gnoll"}}},fp="21,142,22.279.0,29.306.0,48.226.0,41.166.0,41.226.0,54.140.0"}
P.entries["item:panther-cage-key"] = {n="Clé de la cage de la panthère",s="Au Poste de Blanc-relais, Wizlo Braquecoquard garde la Clé de la cage de la panthère. Elle ouvre la cage abandonnée parmi les chariots détruits d’une caravane prise en embuscade dans les Mille pointes.",h="Au Poste de Blanc-relais, Wizlo Braquecoquard garde la Clé de la cage de la panthère.",kw={"centaure","hypercapaciteur bidulotron","clé de la cage de la panthère","mille pointes","poste de blanc-relais","wizlo braquecoquard"},ang={["faction:Horde"]="Aider Wizlo peut rendre les routes autour du Poste de Blanc-relais, dans les Mille pointes, plus sûres après les raids des centaures.",["profession:Engineering"]="La clé ouvre une cage qui renferme le prototype instable d’un bricoleur. Wizlo a laissé son invention délicate dans un endroit dangereux."},sec={{t="Une serrure précaire",b="Wizlo Braquecoquard est un bricoleur gobelin qui a échappé de justesse à une attaque de centaures contre sa caravane, au nord du Poste de Blanc-relais. Les pillards ont fouillé les chariots et la cargaison, mais ont laissé intacte une cage solide. Une panthère rare et féroce attend à l’intérieur. Autour de son cou pend l’invention préférée de Wizlo, un Hypercapaciteur bidulotron. La bête menaçante a tenu les centaures à distance, et seule la clé de Wizlo peut ouvrir la cage et permettre de récupérer l’appareil."}},faq={{q="Qui fournit la Clé de la cage de la panthère ?",a="Wizlo Braquecoquard, un bricoleur gobelin qui se repose au Poste de Blanc-relais, dans le nord-ouest des Mille pointes, fournit la clé.",al={"qui donne la clé de la panthère","où trouver la clé de la cage de la panthère","source de la clé de la cage de la panthère"}},{q="Qu’ouvre la clé ?",a="La clé ouvre une cage de fer parmi les chariots brisés d’une caravane détruite, juste au nord du Poste de Blanc-relais. Une panthère enragée et dangereuse se trouve à l’intérieur.",al={"qu’ouvre la clé de la panthère","emplacement de la cage de la panthère","où se trouve la cage"}},{q="Pourquoi les centaures n’ont-ils pas pillé la cage ?",a="Les centaures ont pillé le reste de la caravane, mais ont laissé la cage intacte. La panthère captive était trop féroce et menaçante pour qu’ils s’en approchent.",al={"pourquoi les centaures ont laissé la panthère","les centaures ont peur de la panthère"}},{q="Que contient la cage, en plus de la bête ?",a="L’Hypercapaciteur bidulotron tant prisé de Wizlo pend au cou de la panthère. Pour le récupérer, quelqu’un doit déverrouiller la cage et affronter le prédateur.",al={"pourquoi ouvrir la cage","ce qui est sur la panthère"}}},fx={b335554a={q="Pourquoi Wizlo Braquecoquard veut-il récupérer la Clé de la cage de la panthère ?",a="Wizlo Braquecoquard vous confie la clé uniquement pour que vous puissiez ouvrir la cage de sa caravane détruite et tuer la féroce panthère qui s'y trouve. La bête porte son précieux Hypercapaciteur bidulotron autour du cou. Il veut que la clé lui soit rendue en même temps que son invention une fois la tâche accomplie, afin de s'assurer que les vestiges de la caravane et ses biens dangereux soient entièrement récupérés.",al={"pourquoi la clé de la cage de la panthère","pourquoi wizlo a-t-il besoin de la clé","pourquoi vouloir la clé de la cage de la panthère"}}},fp="16,160,17.423.0,34.115.0,25.142.0,37.137.0,42.139.0"}
P.entries["item:parker-s-lunch"] = {n="Repas de Parker",s="À Comté-du-Lac, Darcy prépare le Repas de Parker pour la patrouille du Garde Parker. Ce repas révèle les liens et les modestes réconforts entre les défenseurs des Carmines.",h="À Comté-du-Lac, Darcy prépare le Repas de Parker pour la patrouille du Garde Parker.",kw={"a free lunch","darcy","garde parker","comté-du-lac","repas de parker","les carmines"},ang={["faction:Alliance"]="Les renforts de la capitale tardent à arriver. Les habitants et les quelques gardes encore présents s'entraident pour faire tourner Comté-du-Lac.",["profession:Cooking"]="Pour les gardes des confins, un repas chaud préparé à l'avance apporte du réconfort pendant les longues heures passées dans la nature, parmi les bêtes hostiles."},sec={{t="Un repas pour la route",b="Darcy travaille comme serveuse à l'auberge de Comté-du-Lac, où elle prépare un repas pour le Garde Parker. Il patrouille sur la route exposée qui mène au sud, vers le Bois de la Pénombre, tandis que les Carmines subissent les attaques des gnolls et des orcs Rochenoire. La garnison est débordée et privée de l'aide de Hurlevent, si bien que ses gardes montent de longues veilles solitaires. Ce petit geste de Darcy nourrit Parker et marque le début d'une cour timide entre eux."}},faq={{q="Qui a préparé le Repas de Parker ?",a="Darcy, serveuse à l'auberge de Comté-du-Lac, prépare le Repas de Parker pour le Garde Parker pendant sa patrouille. Un voyageur lui apporte le repas.",al={"qui a préparé le repas de parker","qui m'a donné le repas de parker","repas de darcy aux carmines"}},{q="Où trouver le Garde Parker ?",a="Le Garde Parker patrouille sur la route de terre principale, au sud-ouest de Comté-du-Lac, en direction de la frontière du Bois de la Pénombre. Il fait les cent pas en guettant les gnolls errants.",al={"emplacement du garde parker","où est le garde parker","trouver le garde parker"}},{q="Que fait le Garde Parker après avoir reçu son repas ?",a="Parker est touché par l'attention de Darcy et cherche comment lui rendre sa gentillesse. Il s'arrange pour lui faire envoyer des jonquilles fraîches par l'herboriste.",al={"suite du repas de parker","darcy et parker","réaction de parker au repas"}},{q="Pourquoi Darcy ne livre-t-elle pas le repas elle-même ?",a="Les gnolls et les envahisseurs Rochenoire menacent les routes autour de Comté-du-Lac. Darcy est une simple habitante, tandis que Parker a l'entraînement et l'armure nécessaires pour les patrouiller.",al={"pourquoi darcy ne peut pas l'apporter","pourquoi livrer un repas aux carmines"}}},fx={["2351e721"]={q="Qu'est-ce que le Repas de Parker ?",a="Le Repas de Parker est un repas conditionné préparé par Darcy, l'assistante de l'aubergiste à Comté-du-Lac. Elle l'a emballé spécialement pour soutenir le Garde Parker, qui passe de longues heures épuisantes à patrouiller sur les routes dangereuses au sud de la ville, en direction du Bois de la Pénombre.",al={"qu'est-ce que le repas de parker","objet repas de parker"}},b73a829b={q="Pourquoi le Garde Parker a-t-il besoin qu'on lui livre son repas ?",a="Le Garde Parker est stationné loin de la sécurité relative de Comté-du-Lac, montant la garde contre les gnolls itinérants et les orcs du Rochenoire le long de la route frontalière. Incapable d'abandonner son poste pour retourner à l'auberge, il dépend de la gentillesse des citadins comme Darcy — et des voyageurs de passage — pour se nourrir pendant son service.",al={"pourquoi livrer le repas de parker","pourquoi parker veut-il son repas","pourquoi le garde parker a-t-il besoin de son repas"}}},fp="14,154,19.382.0,28.143.0,32.148.0,52.147.1,44.158.0"}
P.entries["item:partially-filled-vessel"] = {n="Récipient à moitié rempli",s="À Aldrassil, Tenaron Poignorage confie aux jeunes initiés elfes de la nuit un Récipient à moitié rempli. Il contient de l’eau bénite du puits de lune de Sombrevallon, à apporter jusqu’à Dolanaar.",h="À Aldrassil, Tenaron Poignorage confie aux jeunes initiés elfes de la nuit un Récipient à moitié rempli.",kw={"aldrassil","corithras ragelune","crown of the earth","dolanaar","puits de lune","récipient à moitié rempli","sombrevallon","tenaron poignorage","récipient"},ang={["class:Druid"]="En tant que druide, vous transportez de l’eau consacrée pour aider le Cercle cénarien à prendre soin de l’Arbre-monde et à surveiller sa santé.",["race:NightElf"]="En tant que jeune Elfe de la nuit, porter ce récipient vous mène du sanctuaire de Sombrevallon aux vastes terres où l’on prend soin de Teldrassil."},sec={{t="Une livraison sacrée",b="Les jeunes initiés kaldorei recueillent l’eau bénite du puits de lune isolé de Sombrevallon. À Aldrassil, Tenaron Poignorage verse un échantillon dans le récipient pour son voyage à travers Teldrassil. Il faut davantage d’eau des puits de lune de l’arbre pour préserver la santé de l’île."},{t="En route pour Dolanaar",b="Portez le récipient vers le sud en franchissant les portes de la vallée, puis suivez les routes pavées vers l’ouest jusqu’à Dolanaar. Le voyage vous conduit au-delà de la pépinière protégée de Sombrevallon, jusque dans les étendues sauvages de Teldrassil. Au puits de lune central de Dolanaar, Corithras Ragelune récupère le récipient et vous indique la suite du rituel."}},faq={{q="Que contient le récipient ?",a="Le druide Tenaron Poignorage verse dans le récipient de l’eau pure du puits de lune sacré de Sombrevallon.",al={"contenu du récipient","quelle eau contient-il"}},{q="Pourquoi n’est-il rempli qu’à moitié ?",a="Le puits de lune de Sombrevallon ne fournit que le premier échantillon. Pour prendre soin de Teldrassil, il faut recueillir l’eau de plusieurs puits de lune avant que le récipient soit plein.",al={"pourquoi à moitié rempli","pourquoi n’est-il pas plein"}},{q="À qui dois-je remettre ce récipient ?",a="Portez le récipient vers le sud, hors de Sombrevallon, puis suivez la route pavée vers l’ouest jusqu’à Dolanaar. Remettez-le à Corithras Ragelune, qui veille sur le puits de lune du village.",al={"à qui remettre le récipient","où l’apporter","remise du récipient"}},{q="Pourquoi transporte-t-on l’eau des puits de lune à travers Teldrassil ?",a="Les druides et les prêtresses surveillent et nourrissent Teldrassil grâce aux eaux de ses puits de lune. Transférer l’eau d’un puits à l’autre aide à maintenir leurs bénédictions sur les branches tourmentées du jeune Arbre-monde.",al={"pourquoi transporter l’eau des puits de lune","but de l’eau","pourquoi déplacer l’eau"}}},fx={["089d2d88"]={q="Pourquoi Corithras Ragelune veut-il le Récipient à moitié rempli ?",a="Corithras Ragelune attend le récipient au puits de lune de Dolanaar pour poursuivre une tâche druidique vitale connue sous le nom de Couronne de la Terre. Recueillir les eaux de Teldrassil est essentiel pour inspecter et entretenir le jeune Arbre-Monde, et Corithras a besoin de l'eau que vous avez apportée d'Aldrassil avant de pouvoir vous guider vers les prochaines étapes du rituel.",al={"pourquoi corithras veut ceci","pourquoi apporter le récipient à dolanaar","pourquoi apporter le récipient à corithras"}},["5f4a3df1"]={q="Qu'est-ce que le Récipient à moitié rempli ?",a="Le Récipient à moitié rempli est un conteneur enchanté utilisé par les druides elfes de la nuit pour recueillir et transporter les eaux sacrées des puits de lune de Teldrassil. Lorsque Tenaron Poignorage vous envoie depuis Sombrevallon, il combine votre fiole d'eau de puits de lune bénie recueillie dans ce récipient afin que le travail sacré puisse se poursuivre à travers les branches de l'Arbre-Monde.",al={"histoire du récipient à moitié rempli","qu'est-ce que ce récipient","qu'est-ce que le récipient à moitié rempli"}},["4f920d4c"]={q="D'où vient le Récipient à moitié rempli et qui l'a fabriqué ?",a="Tenaron Poignorage, l'un des druides anciens stationnés au sommet d'Aldrassil à Sombrevallon, vous fournit ce récipient. Après que vous avez puisé de l'eau au puits de lune de Sombrevallon, Tenaron verse le contenu de votre fiole dans le conteneur pour commencer la collecte, vous confiant la tâche de le transporter plus loin, dans les étendues de Teldrassil.",al={"qui a fabriqué le récipient","d'où vient le récipient","origine du récipient"}}},fp="23,159,17.262.0,18.309.0,26.93.0,32.142.0,29.159.0,52.198.0"}
P.entries["item:paw-of-sin-dall"] = {n="Paw of Sin'Dall",s="Ajeck Rouack vous demande de traquer Sin'Dall, un tigre insaisissable de la Vallée de Strangleronce, et de rapporter une preuve de votre chasse.",h="Ajeck Rouack vous demande de traquer Sin'Dall, un tigre insaisissable de la Vallée de Strangleronce, et de...",kw={"ajeck rouack","expédition de nesingwary","paw of sin'dall","sin'dall","vallée de strangleronce","tigre","maîtrise du tigre"},ang={["class:Hunter"]="En tant que Chasseur, vous devrez relever le défi d'Ajeck Rouack : traquer et tuer Sin'Dall, puis rapporter une preuve de votre chasse."},sec={{t="Paw of Sin'Dall",b="À l’Expédition de Nesingwary, Ajeck Rouack vous lance à la poursuite de Sin’Dall, un tigre insaisissable traqué depuis des semaines. Elle vous demande de revenir avec la patte du tigre comme preuve de la chasse. Rapportez-la, et elle vous saluera comme un véritable maître chasseur de tigres."}},faq={{q="Qui est Sin'Dall ?",a="Sin'Dall est une tigresse insaisissable de la Vallée de Strangleronce, chassée par Ajeck Rouack et les pisteurs de l'Expédition de Nesingwary.",al={"tigre sin'dall","qui est sin'dall"}},{q="Pourquoi Ajeck veut-il la patte de Sin'Dall ?",a="Ajeck Rouack vous demande de rapporter la patte de Sin'Dall pour prouver que vous l'avez traquée et tuée.",al={"preuve par la patte","pourquoi la patte"}},{q="Où dois-je apporter le Paw of Sin'Dall ?",a="Apportez le Paw of Sin'Dall à Ajeck Rouack, à l'Expédition de Nesingwary.",al={"où apporter la patte","patte ajeck rouack"}},{q="Que prouve la patte ?",a="La patte prouve à Ajeck Rouack que vous avez achevé la chasse à Sin'Dall.",al={"signification de la patte","preuve sin'dall"}}},fp="15,114,17.235.0,16.119.0,35.86.1,36.69.0,24.72.1"}
P.entries["item:pendant-of-shadow"] = {n="Pendentif des ombres",s="À la Tour d'Ilgalar, Morganth porte le Pendentif des ombres en quête de La faux d'Élune. Theocritus veut qu'on le rapporte à la Tour d’Azora comme preuve de la mort de Morganth.",h="À la Tour d'Ilgalar, Morganth porte le Pendentif des ombres en quête de La faux d'Élune.",kw={"morganth","pendentif des ombres","les carmines","faux d'élune","theocritus","tour d’azora","tour d'ilgalar"},ang={["class:Mage"]="En tant que mage, récupérer le talisman pour Theocritus montre la responsabilité des mages : arrêter les lanceurs de sorts renégats et imprudents qui menacent le royaume.",["class:Warlock"]="En tant que démoniste, Morganth illustre le péril qu'il y a à attirer l'attention de la Tour d’Azora en poursuivant des artefacts instables et interdits comme La faux d'Élune."},sec={{t="Signe d'un démoniste des ténèbres",b="À la Tour d'Ilgalar, Morganth détient le Pendentif des ombres. Le démoniste renégat cherche à percer les mystères de La faux d'Élune, une ancienne relique à la puissance immense et instable.\n\nTheocritus craint les ravages que Morganth pourrait déchaîner sur Les Carmines et le royaume de Hurlevent. Le mage envoie des aventuriers s'infiltrer dans Ilgalar, mettre fin aux complots de Morganth et prendre le talisman comme preuve de sa mort."}},faq={{q="Où trouver le Pendentif des ombres ?",a="Morganth porte le pendentif au sommet de la Tour d'Ilgalar, dans le nord-est des Carmines.",al={"lieu du pendentif des ombres","où trouver le pendentif des ombres","comment obtenir le pendentif des ombres"}},{q="Qui veut le Pendentif des ombres ?",a="Theocritus veut que le talisman lui soit rapporté à la Tour d’Azora, dans l'est de la Forêt d’Elwynn.",al={"qui récupère le pendentif des ombres","remettre le pendentif des ombres","pendentif de theocritus"}},{q="Pourquoi Theocritus a-t-il besoin de ce pendentif ?",a="Theocritus a besoin du pendentif comme preuve que Morganth a été tué et que la quête dangereuse de La faux d'Élune a pris fin.",al={"pourquoi theocritus le veut","rôle du pendentif des ombres"}},{q="Quelle menace Morganth représentait-il avec le pendentif ?",a="Morganth cherchait La faux d'Élune. Theocritus craignait que le démoniste ne déchaîne une puissance catastrophique sur Les Carmines et le royaume alentour s'il s'emparait de l'artefact.",al={"que faisait morganth","histoire de morganth"}}},fx={d0e37f9a={q="Qu'est-ce que le Pendentif des ombres ?",a="Le Pendentif des ombres est un sombre talisman porté par le démoniste renégat Morganth au sommet de la Tour d'Ilgalar, dans les Carmines. Directement lié aux ambitions sinistres et aux arts obscurs de Morganth, le pendentif sert de preuve de sa défaite pour le magicien Theocritus, qui craint les ravages que Morganth pourrait infliger à Hurlevent s'il n'était pas arrêté.",al={"qu'est-ce que le pendentif des ombres","lore du pendentif des ombres","info sur le pendentif des ombres"}}},fp="17,180,23.403.1,38.99.0,32.92.0,38.121.1,47.171.1"}
P.entries["item:pendant-of-the-sea-lion"] = {n="Pendentif du lion de mer",s="Au Sanctuaire de Remulos, les druides réunissent les deux moitiés du Pendentif du lion de mer. Le talisman achevé prouve qu’un initié est prêt à apprendre Aquatic Form.",h="Au Sanctuaire de Remulos, les druides réunissent les deux moitiés du Pendentif du lion de mer.",kw={"aquatic form","dendrite brasétoile","mathrengyl pasdelours","reflet-de-lune","pendentif du lion de mer","remulos","turak totem-runique"},ang={["class:Druid"]="En tant que druide, assembler le pendentif marque une étape importante de votre entraînement. Il vous permet de respirer sous l’eau et de nager rapidement comme un lion de mer.",["race:Tauren"]="En tant que tauren qui suit la voie du Cercle cénarien, vous honorez vos ancêtres et les enseignements de Reflet-de-Lune en apportant le pendentif à Turak Totem-runique."},sec={{t="Un gage des profondeurs",b="Un druide doit affronter les dangers de l’eau pour obtenir l’aspect aquatique du lion de mer. Le pendentif se compose de deux moitiés. L’une confère l’agilité nécessaire pour échapper aux prédateurs aquatiques, tandis que l’autre donne l’endurance nécessaire pour supporter une immersion prolongée. Les druides réunissent les morceaux au Sanctuaire de Remulos, à Reflet-de-Lune."},{t="Preuve de maîtrise",b="Une fois le pendentif forgé, un initié le présente à un mentor ancien. Turak Totem-runique attend sur les hauteurs de Pitons-du-Tonnerre, tandis que Mathrengyl Pasdelours se trouve à Darnassus. Le talisman prouve que l’initié a accompli les épreuves sous la tutelle de Dendrite Brasétoile. L’ancien peut alors lui enseigner les secrets d’Aquatic Form."}},faq={{q="À quoi sert le Pendentif du lion de mer ?",a="Le pendentif prouve qu’un initié a accompli les épreuves d’agilité et d’endurance aquatiques et qu’il est prêt à apprendre Aquatic Form.",al={"à quoi sert le pendentif du lion de mer","utilité du pendentif du lion de mer","pourquoi obtenir le pendentif du lion de mer"}},{q="Où assemble-t-on le pendentif ?",a="Les druides réunissent les deux moitiés du pendentif au Sanctuaire de Remulos, à Reflet-de-Lune. L’une confère l’agilité et l’autre, l’endurance.",al={"comment fabriquer le pendentif du lion de mer","où réunir les moitiés du pendentif"}},{q="À qui présenter le pendentif à Pitons-du-Tonnerre ?",a="À Pitons-du-Tonnerre, présentez le pendentif achevé à Turak Totem-runique, à la Cime des Anciens.",al={"à qui remettre le pendentif à pitons-du-tonnerre","pendentif de turak totem-runique","remise pour aquatic form côté horde"}},{q="Les Elfes de la nuit peuvent-ils aussi obtenir ce pendentif ?",a="Oui. Les druides elfes de la nuit passent la même épreuve à Reflet-de-Lune, puis apportent le pendentif assemblé à Mathrengyl Pasdelours, à Darnassus.",al={"pendentif du lion de mer côté alliance","pendentif du lion de mer à darnassus"}}},fx={["203d1c94"]={q="Qu'est-ce que le Pendentif du lion de mer ?",a="Le Pendentif du lion de mer est un talisman druidique sacré symbolisant la maîtrise de l'eau. Il incarne l'agilité nécessaire pour échapper aux dangereux prédateurs aquatiques ainsi que l'endurance profonde requise pour rester immergé sans refaire surface. Les druides portent cette relique assemblée comme preuve tangible qu'ils comprennent l'équilibre sauvage de la nature avant d'adopter un aspect aquatique.",al={"qu'est-ce que le pendentif du lion de mer","info sur le pendentif du lion de mer","lore du pendentif du lion de mer"}},ad633d46={q="D'où vient le Pendentif du lion de mer et qui l'a fabriqué ?",a="Le talisman est forgé par les jeunes druides qui passent l'épreuve du lion de mer. Il est créé en récupérant deux pièces distinctes – le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique – dans les lieux d'épreuve et en les assemblant devant le Sanctuaire de Remulos à Reflet-de-Lune, unissant ainsi les aspects en un seul emblème sacré.",al={"qui a fabriqué le pendentif du lion de mer","origine du pendentif du lion de mer","comment est créé le pendentif du lion de mer"}},["384283bf"]={q="Pourquoi vouloir le Pendentif du lion de mer ?",a="Les mentors druidiques exigent de voir le pendentif terminé comme preuve irréfutable de votre formation. Aux Pitons-du-Tonnerre, Turak Totem-runique a besoin du médaillon pour vérifier que vous avez réussi les épreuves de Reflet-de-Lune avant de vous transmettre les secrets de la forme aquatique. Dendrite Brasétoile, à Reflet-de-Lune, examine également la relique assemblée pour confirmer l'achèvement de l'épreuve.",al={"pourquoi vouloir le pendentif du lion de mer","qui veut le pendentif du lion de mer","pourquoi montrer le pendentif du lion de mer"}}},fp="23,154,19.299.0,16.307.0,51.119.0,31.128.0,49.89.0,39.130.0"}
P.entries["item:perenolde-tiara"] = {n="Tiare de Perenolde",s="Dans les Ruines d'Alterac, la Tiare de Perenolde a refait surface. Des artisans nains de Forgefer ont façonné ce bijou serti d'émeraudes, que convoitent des collectionneurs de Hurlevent.",h="Dans les Ruines d'Alterac, la Tiare de Perenolde a refait surface.",kw={"alterac","émeraudes","grel'borg","forgefer","avare","perenolde","remington","bellornière","tiare"},ang={["faction:Alliance"]="En tant que membre de l'Alliance, vous voyez dans la maison Perenolde un rappel amer de sa trahison durant la Deuxième guerre, qui faillit détruire l'Alliance originelle de Lordaeron.",["race:Dwarf"]="En tant que nain, vous pouvez admirer le savoir-faire de Forgefer dans les émeraudes taillées et serties par ses maîtres joailliers pour la noblesse humaine du nord."},sec={{t="Une relique d'un royaume en ruine",b="La famille Perenolde a régné sur Alterac jusqu'à la chute du royaume durant la Deuxième guerre. Parmi ses trésors figurait une délicate tiare, façonnée par des maîtres joailliers de Forgefer et sertie de brillantes émeraudes. Après que la trahison du roi Aiden Perenolde eut précipité Alterac dans la ruine, la tiare disparut dans la dévastation des hauts sommets."},{t="Le butin de l'Avare",b="Grel'borg l'Avare, un ogre-mage, a déterré la tiare en fouillant les ruines d'Alterac à la recherche de richesses abandonnées. La nouvelle de cette relique est parvenue au comte Remington Bellornière, un riche noble de Hurlevent qui collectionne de célèbres reliques pour le musée de sa famille. Le comte cherche maintenant à prendre la tiare à l'ogre."}},faq={{q="Qu'est-ce que la Tiare de Perenolde ?",a="La Tiare de Perenolde est un héritage de la famille royale Perenolde d'Alterac. Des joailliers nains de Forgefer l'ont façonnée et sertie d'émeraudes avant qu'elle ne soit perdue lors de la chute du royaume.",al={"histoire de la tiare de perenolde","qu'est-ce que cette tiare","tiare d'alterac"}},{q="Qui possède la tiare actuellement ?",a="Grel'borg l'Avare, un ogre-mage, a trouvé la tiare parmi les ruines enneigées d'Alterac. Il la garde tout en cherchant d'autres trésors dans le royaume en ruine.",al={"où se trouve la tiare","qui donne la tiare","tiare de grel'borg"}},{q="Pourquoi le comte Remington Bellornière la convoite-t-il ?",a="Le comte Remington Bellornière collectionne des antiquités historiques et prestigieuses pour le musée de sa famille, à Hurlevent. Il veut faire de la tiare le joyau de sa collection, vestige d'un royaume humain déchu.",al={"qui convoite la tiare","pourquoi remington la convoite","motivations de remington bellornière"}},{q="Qui étaient les Perenolde ?",a="Les Perenolde régnaient sur le royaume d'Alterac. Durant la Deuxième guerre, le roi Aiden Perenolde a trahi l'Alliance au profit de la Horde des orcs, et son royaume a sombré dans la ruine.",al={"famille perenolde","maison perenolde","dirigeants d'alterac"}}},fx={da959daa={q="D'où vient la Tiare de Perenolde et qui l'a fabriquée ?",a="La tiare provient du royaume ruiné d'Alterac, au nord, où elle servait de précieux héritage familial à la maison royale de Perenolde. Plutôt que d'être forgée par des artisans humains, on raconte qu'elle a été façonnée par des maîtres joailliers nains de Forgefer, qui ont orné la pièce de magnifiques émeraudes.",al={"qui a fabriqué la tiare de perenolde","origine de la tiare de perenolde","où la tiare a-t-elle été fabriquée"}}},fp="15,167,27.319.0,17.295.0,28.187.0,28.152.0,43.172.0,24.161.0"}
P.entries["item:pestlezugg-s-un-goro-report"] = {n="Pestlezugg's Un'Goro Report",s="Le rapport de Pestlezugg sur Un'Goro transmet ses dernières découvertes de Gadgetzan aux dirigeants de Darnassus ou d'Orgrimmar. Il espère qu'ils prendront la menace des silithides au sérieux et aideront à y faire face.",h="Le rapport de Pestlezugg sur Un'Goro transmet ses dernières découvertes de Gadgetzan aux dirigeants de...",kw={"le calme avant la tempête","darnassus","gadgetzan","gracina spiritmight","orgrimmar","pestlezugg","silithide","rapport sur un'goro","zilzibin drumlore"},ang={["faction:Alliance"]="En tant que voyageur de l'Alliance, vous portez l'avertissement de Pestlezugg à Gracina Spiritmight, à Darnassus, où elle espère que ses dirigeants prendront au sérieux la menace des silithides.",["faction:Horde"]="En tant que voyageur de la Horde, vous apportez l'avertissement de Pestlezugg à Zilzibin Drumlore, à Orgrimmar, dans l'espoir que Thrall apprenne les faits."},sec={{t="Un rapport de Gadgetzan",b="À Gadgetzan, Pestlezugg transmet ses dernières découvertes sur les silithides à quelqu'un qui peut joindre les dirigeants. Le rapport est envoyé à Gracina Spiritmight, au Temple de la Lune, à Darnassus, ou à Zilzibin Drumlore, à Orgrimmar. Pestlezugg estime que le danger est trop grand pour que Gadgetzan y fasse face seule."},{t="Prendre l'avertissement au sérieux",b="Gracina et Zilzibin craignent tous deux que la haine entre l’Alliance et la Horde n’aveugle leurs dirigeants face à la menace des silithides. Gracina affirme que l’Alliance écarte les dangers qui ne viennent pas de la Horde, tandis que les dirigeants de la Horde sont divisés par des conseils contradictoires. Les deux destinataires exhortent à poursuivre les efforts contre les silithides."}},faq={{q="Qui a écrit le rapport ?",a="Pestlezugg, qui travaille à Gadgetzan, a écrit le rapport sur ses dernières découvertes concernant les silithides.",al={"qui est pestlezugg","rapport de pestlezugg","auteur du rapport"}},{q="Que contient le rapport de Pestlezugg ?",a="Le rapport présente les dernières découvertes de Pestlezugg sur la menace des silithides.",al={"que dit le rapport","rapport sur les silithides","contenu du rapport"}},{q="Où le rapport est-il envoyé ?",a="Le rapport est remis à Gracina Spiritmight, au Temple de la Lune, à Darnassus, ou à Zilzibin Drumlore, à Orgrimmar.",al={"où apporter le rapport","destination du rapport","où l'envoyer"}},{q="Pourquoi Pestlezugg l'envoie-t-il ?",a="Pestlezugg estime que Gadgetzan ne peut pas faire face seule à la menace des silithides et espère que les dirigeants agiront à partir de ses découvertes.",al={"pourquoi envoyer le rapport","pourquoi pestlezugg a besoin d'aide","gadgetzan a besoin d'aide"}},{q="Que pense Gracina de l'avertissement ?",a="Gracina affirme que l'Alliance néglige les menaces qui ne viennent pas de la Horde et elle encourage à poursuivre les efforts contre les silithides.",al={"gracina et les silithides","réaction de l'alliance","pourquoi l'alliance ignore la menace"}},{q="Comment la Horde réagit-elle ?",a="Zilzibin affirme que la Horde est distraite par des conseils contradictoires, mais il pense que Thrall pourrait agir si les faits lui parvenaient.",al={"réaction de la horde","thrall et les silithides","rapport de zilzibin"}}},fp="27,174,23.300.0,19.316.1,21.95.0,31.71.0,25.122.0,28.110.0,39.129.0,27.122.0"}
P.entries["item:phial-of-scrying"] = {n="Flasque de divination",s="À Sombrivage, des éclaireurs rejoignent Onu depuis des terres périlleuses. Onu leur remet la Flasque de divination, dont les eaux enchantées forment une bassine pour sonder les bois corrompus.",h="À Sombrivage, des éclaireurs rejoignent Onu depuis des terres périlleuses.",kw={"sombrivage","le glaive du maître","onu","flasque de divination","bassine de divination","marteau du crépuscule"},ang={["class:Druid"]="En tant que druide, vous reconnaissez dans les bassines de divination un mélange d’eau naturelle et de magie de communion. Elles permettent aux gardiens de la forêt d’échanger des murmures à travers les terres corrompues.",["race:NightElf"]="En tant qu’Elfe de la nuit de Sombrivage, vous savez que les eaux de divination aident à surveiller les bois sacrés menacés par des cultes étrangers."},sec={{t="Une lentille sur Sombrivage",b="Au cœur de Sombrivage, les éclaireurs utilisent la Flasque de divination pour sonder les lieux à distance. Ses eaux mystiques forment une bassine temporaire sur le sol. Depuis des endroits périlleux comme le Glaive du Maître, ils peuvent parler à Onu sans retourner à son bosquet."},{t="À la découverte du culte",b="Onu remet la flasque aux éclaireurs pour surveiller les sectateurs du Marteau du crépuscule. Là où un ancien maître déchu gît, empalé par un glaive colossal, un éclaireur ouvre un lien de divination. La vision confirme que de sombres sectateurs se rassemblent autour des dépouilles antiques, à la recherche de parcelles de puissance oubliée qui persistent même dans la mort."}},faq={{q="À quoi sert la Flasque de divination ?",a="Débouchez la Flasque de divination et une bassine magique apparaît sur le sol. Depuis le terrain, vous pouvez l’utiliser pour contacter Onu et lui parler à grande distance.",al={"utiliser la flasque de divination","fonction de la bassine de divination","à quoi sert cette flasque"}},{q="Qui fournit la Flasque de divination ?",a="L’ancien tréant Onu remet la flasque aux éclaireurs de Sombrivage lorsqu’il les envoie reconnaître le Glaive du Maître, au sud.",al={"qui donne la flasque de divination","où trouver la flasque"}},{q="Que se passe-t-il si la flasque est perdue ou épuisée ?",a="Si vous perdez la flasque ou l’utilisez avant d’avoir terminé votre mission, Onu peut vous en donner une autre pendant qu’il médite à Sombrivage.",al={"flasque de divination perdue","obtenir une autre flasque","remplacer la flasque"}},{q="Pourquoi Onu sonde-t-il le Glaive du Maître ?",a="Onu sait qu’un ancien seigneur est tombé au Glaive du Maître et vous demande d’y chercher des sectateurs du Marteau du crépuscule. Leur but se précise au fil de l’enquête.",al={"pourquoi sonder le glaive du maître","mission d’onu au glaive"}}},fx={["92e56a99"]={q="Qu'est-ce que la Flasque de divination ?",a="La Flasque de divination est un récipient enchanté contenant des eaux mystiques fournies par l'Ancien du savoir, Onu. Lorsqu'elle est versée sur le terrain, elle crée temporairement un bol de divination qui sert de conduit magique, vous permettant d'établir un lien spirituel direct avec l'Ancien sur de vastes distances.",al={"qu'est-ce que la flasque de divination","lore de la flasque de divination","explication de la flasque de divination"}},["16c85a4e"]={q="Pourquoi Onu veut-il que vous utilisiez la Flasque de divination ?",a="Onu vous demande de fouiller le Glaive du Maître à la recherche des membres du culte du Marteau du crépuscule. La flasque vous permet de créer un bol de divination et de parler avec lui après avoir fouillé le site, sans avoir à retourner d'abord dans son bosquet.",al={"pourquoi utiliser la flasque de divination","pourquoi onu veut-il la flasque","pourquoi avoir besoin de la flasque de divination"}}},fp="16,173,23.242.0,19.313.1,34.155.0,34.122.0,47.120.0,44.171.0"}
P.entries["item:piece-of-krom-zar-s-banner"] = {n="Morceau de la bannière de Krom'zar",s="Dans le bunker de Regthar Seuil-de-mort, à l’ouest de La Croisée, une bannière déchirée marque l’échec de l’assaut. Le seigneur de guerre Krom'zar menait la force de représailles des Kolkar vers l’est, depuis Désolace.",h="Dans le bunker de Regthar Seuil-de-mort, à l’ouest de La Croisée, une bannière déchirée marque l’échec de...",kw={"bannière","centaure","contre-attaque","la croisée","seuil-de-mort","kolkar","krom'zar","regthar"},ang={["faction:Horde"]="Vaincre Krom'zar et prendre sa bannière met un terme à une offensive majeure des centaures. Les routes du nord entre Durotar, Mulgore et La Croisée sont sûres.",["race:Tauren"]="En tant que tauren, vous savez que l’agressivité des centaures trouble depuis longtemps les tribus nomades. L’avant-garde de Krom'zar est détruite, et les pistes vers Mulgore sont plus sûres."},sec={{t="Trophée de l’incursion des centaures",b="Le seigneur de guerre Krom'zar a mené sa bande de guerre vers l’est depuis Désolace pour riposter. Les chefs kolkar des Tarides étaient tombés, et les centaures furieux ont attaqué les bunkers défensifs à l’ouest de La Croisée. Un morceau découpé dans l’étendard de Krom'zar, tombé au combat, prouve à Regthar Seuil-de-mort que l’assaut a été écrasé et que les routes commerciales du sud ont été préservées pour la Horde."}},faq={{q="À quoi sert ce morceau de bannière ?",a="Apportez l’étoffe déchirée à Regthar Seuil-de-mort, dans son bunker à l’ouest de La Croisée. Elle prouve que le seigneur de guerre Krom'zar a été tué et que sa force de pillards a été mise en déroute, mettant fin à la défense des Tarides du nord.",al={"utilité de la bannière","pourquoi garder la bannière","que faire du morceau de bannière"}},{q="Qui était le seigneur de guerre Krom'zar ?",a="Krom'zar était un commandant kolkar de Désolace. Après la mort des chefs kolkar locaux, il a mené une contre-attaque directe contre les avant-postes de la Horde.",al={"qui est kromzar","histoire de krom'zar","seigneur de guerre krom'zar"}},{q="Pourquoi les Kolkar ont-ils attaqué le bunker ?",a="Après la chute de Barak, Verog, Hezrul et des autres chefs locaux, les centaures furieux ont rassemblé des renforts venus de Désolace. Ils cherchaient à se venger de la présence de la Horde à l’ouest de La Croisée.",al={"pourquoi riposter","pourquoi l’invasion des kolkar","raison de la contre-attaque dans les tarides"}},{q="Thrall entendra-t-il parler de cette victoire ?",a="Oui. Regthar Seuil-de-mort promet d’envoyer directement un message au chef de guerre Thrall, à Orgrimmar. Il fera l’éloge des défenseurs qui ont repoussé l’invasion.",al={"récompense de thrall","thrall est-il au courant"}}},fx={["92115071"]={q="Qu'est-ce que le Morceau de la bannière de Krom'zar ?",a="Il s'agit d'un lambeau récupéré de l'étendard de combat du seigneur de guerre Krom'zar, commandant de l'armée de centaures Kolkar assoiffés de vengeance qui a marché de Désolace vers les Tarides. Pour les forces de la Horde défendant les bunkers ouest, il sert de preuve physique indéniable que le seigneur de guerre est tombé au combat et que son invasion a été brisée.",al={"qu'est-ce que le morceau de la bannière de krom'zar","morceau de la bannière de krom'zar","qu'est-ce que le fragment de bannière"}},caa193f6={q="D'où vient le Morceau de la bannière de Krom'zar ?",a="La bannière a été transportée dans les Tarides par le seigneur de guerre Krom'zar et sa horde Kolkar, venus tout droit de leur patrie de Désolace pour se venger de la Horde. Lorsque Krom'zar se rend sur le terrain devant les bunkers ouest et tombe au combat, sa bannière reste sur le champ de bataille, où ce morceau peut être arraché.",al={"d'où vient la bannière de krom'zar","qui a fabriqué la bannière de krom'zar","origine de la bannière de krom'zar"}},["7a980ed6"]={q="Pourquoi Regthar Deathgate veut-il un Morceau de la bannière de Krom'zar ?",a="Regthar Deathgate a besoin d'une preuve concrète que l'armée d'invasion Kolkar a été décisivement écrasée. Présenter cette bannière déchirée confirme que le seigneur de guerre Krom'zar a été tué devant les bunkers de la Horde, permettant à Regthar de déclarer officiellement la fin de l'invasion et d'envoyer un rapport sur votre bravoure directement au chef de guerre Thrall.",al={"pourquoi regthar veut-il la bannière","pourquoi apporter la bannière de krom'zar à regthar","pourquoi la bannière de krom'zar est-elle nécessaire"}}},fp="26,163,31.357.0,35.193.0,25.140.0,37.197.0,33.139.0"}
P.entries["item:plainstrider-beak"] = {n="Bec de trotteur des plaines",s="Dans les Tarides, les chasseurs apportent des becs de trotteur des plaines à La Croisée pour prouver que les oiseaux menaçants ont été éliminés.",h="Dans les Tarides, les chasseurs apportent des becs de trotteur des plaines à La Croisée pour prouver que les...",kw={"tarides","la croisée","bec de trotteur des plaines","plainstrider menace","sergra darkthorn","grand trotteur des plaines"},ang={["class:Hunter"]="En tant que chasseur, vous traquez les trotteurs des plaines dans les vastes plaines de Kalimdor et ramassez leurs becs, apprenant à assurer vos prises.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à protéger les routes commerciales et de ravitaillement qui approvisionnent l'avant-poste en éliminant les troupeaux nuisibles à l'est de La Croisée."},sec={{t="À la mesure de la chasse",b="Les trotteurs des plaines fourragent près de La Croisée et menacent ses provisions. Des trotteurs des plaines supérieurs, fuyants et acariâtres parcourent la savane alentour. Sergra Sombreronce demande aux chasseurs qui arrivent de rapporter leurs becs, preuve que les troupeaux ont été éloignés des voies de ravitaillement et des entrepôts."}},faq={{q="Pourquoi Sergra Sombreronce veut-elle des becs de trotteur des plaines ?",a="Sergra Sombreronce demande aux chasseurs d'éliminer les trotteurs des plaines, car ces oiseaux s'en prennent aux provisions autour de La Croisée. Leurs becs montrent que la menace pesant sur les réserves locales a diminué.",al={"pourquoi ramasser des becs","quête de bec de trotteur des plaines de sergra","pourquoi des becs"}},{q="Quelles créatures donnent ces becs ?",a="Les chasseurs prélèvent les becs sur les trotteurs des plaines supérieurs, fuyants et acariâtres qui parcourent la savane des Tarides.",al={"quelles créatures donnent des becs de trotteur des plaines","sources de becs de trotteur des plaines","où trouver des becs"}},{q="Pourquoi tous les trotteurs des plaines ne donnent-ils pas un bec quand ils sont tués ?",a="Dans la lutte, les trotteurs des plaines rapides et agités peuvent laisser un bec fendu, brisé ou impropre à servir de trophée intact. Les chasseurs ne ramassent que les becs intacts.",al={"pourquoi le taux d'obtention est faible","bec de trotteur des plaines n'obtenant pas"}}},fx={["7e2762f5"]={q="Qu'est-ce qu'un Bec de trotteur des plaines ?",a="Un Bec de trotteur des plaines est le bec tranché prélevé sur les oiseaux coureurs qui parcourent la savane des Tarides. Durs et pointus, ces becs sont collectés par les chasseurs comme preuve tangible que les oiseaux nuisibles menaçant les provisions locales ont été abattus.",al={"objet bec de trotteur des plaines","qu'est-ce qu'un bec de trotteur des plaines","becs de trotteur des plaines"}},["6978f6b2"]={q="D'où vient un Bec de trotteur des plaines ?",a="Ces becs proviennent directement des diverses espèces de trotteurs des plaines – tels que les trotteurs des plaines supérieurs, agiles ou hargneux – originaires des Tarides. Ils sont récoltés par les chasseurs à travers les plaines arides en tant que trophées et preuve d'une élimination réussie.",al={"où obtenir un bec de trotteur des plaines","qui lâche le bec de trotteur des plaines","source du bec de trotteur des plaines"}}},fp="17,120,21.282.0,50.177.0,34.101.0,54.148.0"}
P.entries["item:plainstrider-feather"] = {n="Plume de trotteur des plaines",s="Sur la Mesa de Nuage rouge, les jeunes chasseurs ramassent les Plumes de trotteur des plaines des oiseaux qui parcourent les plaines de Mulgore. Le Camp Narache confectionne des vêtements et des parures tribales avec ces plumes, en hommage aux créatures qui subviennent aux besoins du village.",h="Sur la Mesa de Nuage rouge, les jeunes chasseurs ramassent les Plumes de trotteur des plaines des oiseaux qui...",kw={"camp narache","plume","grull vent-du-faucon","mulgore","trotteur des plaines","mesa de nuage rouge","the hunt begins"},ang={["class:Hunter"]="En tant que chasseur, traquer les trotteurs des plaines rapides à travers la Mesa de Nuage rouge met votre patience et votre sens du pistage à l’épreuve, et vous apprend à respecter votre proie.",["race:Tauren"]="En tant que jeune tauren, ramasser les plumes d’un trotteur des plaines vous apprend à respecter les créatures de la Mère-Terre et à utiliser chaque partie de votre prise pour vous nourrir et vous vêtir."},sec={{t="La première offrande d’un chasseur",b="Sur la Mesa de Nuage rouge, les jeunes taurens apprennent à pister et à chasser pour répondre aux besoins de leur tribu. Les trotteurs des plaines parcourent le plateau herbeux et fournissent nourriture et plumes utiles. Le Camp Narache confectionne des vêtements et de l’équipement avec leur plumage.\n\nLes jeunes chasseurs apportent des plumes et de la viande fraîche à Grull Vent-du-faucon pour ravitailler le camp. Cette offrande constitue leur première épreuve. Le Chef Vent-du-faucon les reconnaît et les accueille à Pitons-du-Tonnerre."}},faq={{q="À quoi servent les Plumes de trotteur des plaines ?",a="Le Camp Narache confectionne des vêtements et des objets cérémoniels avec les Plumes de trotteur des plaines. Grull Vent-du-faucon les récupère auprès des jeunes chasseurs pour renouveler les réserves de la tribu.",al={"utilité des plumes","usage des plumes de trotteur des plaines","pourquoi ramasser des plumes"}},{q="Qui ramasse les Plumes de trotteur des plaines sur la Mesa de Nuage rouge ?",a="À la demande de Grull Vent-du-faucon, les jeunes chasseurs ramassent des Plumes de trotteur des plaines sur la Mesa de Nuage rouge. Il renouvelle les réserves du Camp Narache et met leur discipline à l’épreuve en leur faisant subvenir aux besoins de la tribu.",al={"qui veut des plumes","qui a besoin de plumes","plumes grull vent-du-faucon"}},{q="Où trouve-t-on des trotteurs des plaines ?",a="Les trotteurs des plaines parcourent les prairies dégagées de la Mesa de Nuage rouge et les plaines vallonnées de Mulgore.",al={"où trouver des trotteurs des plaines","lieu où trouver les trotteurs des plaines","récolte de plumes"}},{q="Pourquoi Grull Vent-du-faucon exige-t-il ces plumes pour les rites tribaux ?",a="Dans la culture taurenne, la chasse assure la survie et procure du plaisir. Apporter de la viande et du plumage au Chef Vent-du-faucon montre qu’un jeune chasseur peut faire vivre la tribu avant de partir pour Pitons-du-Tonnerre.",al={"histoire de the hunt begins","épreuve de chasse taurenne","pourquoi chasser les trotteurs des plaines"}}},fx={f2ff74a3={q="Qu'est-ce qu'une Plume de trotteur des plaines ?",a="Une Plume de trotteur des plaines est un plumage recueilli sur les grands oiseaux incapables de voler qui errent dans les prairies de Mulgore. Les taurens de la Mesa de Nuage rouge utilisent chaque récolte de la terre avec un profond respect, et ces plumes robustes et colorées servent de matériaux pratiques pour confectionner des vêtements de tous les jours ainsi que des ornements traditionnels.",al={"qu'est-ce qu'une plume de trotteur des plaines","info sur la plume de trotteur des plaines","plumes de trotteur des plaines"}},["8bb68bd8"]={q="D'où viennent les Plumes de trotteur des plaines ?",a="Ces plumes proviennent naturellement du plumage récolté directement sur les trotteurs des plaines sauvages errant sur la Mesa de Nuage rouge et dans les plaines plus vastes de Mulgore. Elles ne sont pas façonnées par des mains mortelles, mais récoltées par les chasseurs après une chasse réussie dans la prairie ouverte.",al={"source de la plume de trotteur des plaines","où obtenir des plumes de trotteur des plaines","qui a fabriqué la plume de trotteur des plaines"}}},fp="20,225,25.400.0,40.153.0,52.186.0,33.85.0,64.179.0"}
P.entries["item:plainstrider-kidney"] = {n="Rognon de trotteur des plaines",s="Dans les Tarides, les chasseurs récoltent des rognons de trotteur des plaines pour les traditions brassicoles insolites de Kalimdor. La plupart des voyageurs trouvent cet organe peu ragoûtant, mais il est indispensable à une bière exotique.",h="Dans les Tarides, les chasseurs récoltent des rognons de trotteur des plaines pour les traditions brassicoles...",kw={"brasseur drohn","chen stormstout","trotteur des plaines","rognon de trotteur des plaines","cabestan","stormstout","les tarides"},ang={["class:Hunter"]="En tant que chasseur, vous devez dépouiller soigneusement les trotteurs des plaines dans la savane afin de préserver leurs organes internes pour les vendre aux brasseurs de Cabestan.",["profession:Cooking"]="En tant que cuisinier, vous pourriez rechigner à faire fermenter des rognons d'oiseau pour obtenir des spiritueux raffinés. Dans les étendues sauvages de Kalimdor, survivre signifie souvent utiliser chaque partie de sa prise."},sec={{t="Un ingrédient de brassage peu orthodoxe",b="De grands trotteurs des plaines incapables de voler parcourent les Tarides. Les chasseurs utilisent leurs plumes et leur viande pour fabriquer des outils et de simples rations. À Cabestan, le Brasseur Drohn recherche leurs rognons dans un tout autre but : il affirme qu'ils sont nécessaires pour recréer la bière légendaire et puissante de Chen Stormstout.\n\nDrohn affirme que les rognons donnent à la bière un piquant unique. Cette recette appartient à une lignée de brasseurs peu conventionnels, transmise au fil des ans."}},faq={{q="À quoi sert un rognon de trotteur des plaines ?",a="Le Brasseur Drohn, à Cabestan, a besoin de rognons de trotteur des plaines pour recréer une bière légendaire de Stormstout. Il affirme que son mentor a appris la recette de Chen Stormstout, le brasseur pandaren itinérant.",al={"utilité du rognon de trotteur des plaines","pourquoi ai-je besoin de rognons de trotteur des plaines","fonction du rognon de trotteur des plaines"}},{q="Pourquoi brasser une bière avec des organes d'animaux ?",a="Les bières insolites de Kalimdor utilisent souvent des morceaux d'animaux locaux robustes pour leur donner des saveurs puissantes et un piquant particulier. Le Brasseur Drohn affirme que préparer des recettes sauvages et puissantes lui rappelle des créations peu orthodoxes comme le trogg brew.",al={"rognon dans la bière","pourquoi mettre un rognon dans la bière stormstout","parties animales dans l'alcool"}},{q="Quelles créatures fournissent ces rognons ?",a="Les trotteurs des plaines véloces, hargneux et puissants qui parcourent les Tarides fournissent ces rognons.",al={"où trouver des rognons de trotteur des plaines","qui fournit le rognon de trotteur des plaines","source du rognon de trotteur des plaines"}},{q="Quels autres ingrédients faut-il avec les rognons ?",a="Le Brasseur Drohn demande cinq rognons de trotteur des plaines, cinq défenses de lion des savanes et une Corne de lézard-tonnerre pour sa préparation.",al={"autres ingrédients de brassage","de quoi drohn a-t-il besoin d'autre","ingrédients de stormstout"}}},fx={d14d143c={q="Qu'est-ce qu'un Rognon de trotteur des plaines ?",a="Il s'agit d'un organe interne récolté sur les grands trotteurs des plaines incapables de voler qui parcourent les savanes des Tarides. Bien que la plupart des chasseurs jettent ces entrailles ou les laissent aux charognards, certains brasseurs excentriques les prisent comme des ajouts puissants et peu conventionnels aux spiritueux exotiques.",al={"qu'est-ce qu'un rognon de trotteur des plaines","info sur le rognon de trotteur des plaines","parlez-moi du rognon de trotteur des plaines"}},["4fd58422"]={q="D'où vient un Rognon de trotteur des plaines ?",a="Ces organes sont prélevés directement sur les trotteurs des plaines sauvages originaires des Tarides, y compris les variétés supérieures, hargneuses et agiles. Ce sont des parties naturelles de l'anatomie des oiseaux plutôt que des produits manufacturés, bien qu'en obtenir un nécessite de traquer les bêtes aviaires rapides et agressives à travers les plaines.",al={"source du rognon de trotteur des plaines","où obtenir un rognon de trotteur des plaines","origine du rognon de trotteur des plaines"}},["53f4067b"]={q="Pourquoi le Brasseur Drohn veut-il des Rognons de trotteur des plaines ?",a="Le Brasseur Drohn, à Cabestan, cherche ces rognons pour recréer la légendaire et puissante bière du même nom de Chen Brasse-orage. Chen a transmis cette recette non conventionnelle au mentor de Drohn, et Drohn a besoin des rognons, ainsi que de défenses de lion et d'une Corne de lézard-tonnerre, pour préparer la bière avec sa fougue caractéristique.",al={"pourquoi les rognons de trotteur des plaines sont-ils nécessaires","qui veut des rognons de trotteur des plaines","but des rognons de trotteur des plaines pour drohn"}}},fp="19,181,32.415.0,39.198.0,46.215.0,36.86.0,56.126.0"}
P.entries["item:plainstrider-meat"] = {n="Viande de trotteur des plaines",s="Sur la Mesa de Nuage rouge, les jeunes taurens rassemblent de la viande de trotteur des plaines pour nourrir le Camp Narache. Chasser ces oiseaux pour leur viande et leurs plumes met à l’épreuve leur habileté et leur autonomie.",h="Sur la Mesa de Nuage rouge, les jeunes taurens rassemblent de la viande de trotteur des plaines pour nourrir...",kw={"camp narache","chef vent-du-faucon","grull vent-du-faucon","mulgore","trotteur des plaines","viande de trotteur des plaines","mesa de nuage rouge","the hunt begins"},ang={["class:Hunter"]="En tant que chasseur, vous pouvez mettre à l’épreuve votre sens du pistage et votre adresse au tir contre les trotteurs des plaines rapides qui parcourent les vastes plaines de Mulgore.",["race:Tauren"]="En tant que jeune Tauren sur la Mesa de Nuage rouge, chasser les trotteurs des plaines est une première étape pour gagner le respect du Chef Vent-du-faucon et le droit d’entrer dans les Pitons-du-Tonnerre."},sec={{t="Des vivres pour la mesa",b="Le Camp Narache, sur la Mesa de Nuage rouge, dépend du gibier des prairies alentour. Quand les réserves s’amenuisent, la viande de trotteur des plaines aide à nourrir le village. Les oiseaux fournissent aussi des plumes pour les vêtements et les parures cérémonielles. Les Taurens dépendent de la terre et prennent ce dont ils ont besoin tout en respectant la nature."},{t="L’épreuve du jeune chasseur",b="Grull Vent-du-faucon envoie de jeunes chasseurs traquer les trotteurs des plaines rapides à travers la Mesa de Nuage rouge. Ils récoltent viande et plumes pour prouver leur habileté à pister et leur autonomie. Ils se présentent ensuite devant le père de Grull, le Chef Vent-du-faucon."}},faq={{q="À quoi sert la Viande de trotteur des plaines ?",a="De jeunes chasseurs récoltent de la Viande de trotteur des plaines sur la Mesa de Nuage rouge pour réapprovisionner les réserves de nourriture du Camp Narache pour Grull Vent-du-faucon.",al={"pourquoi la viande de trotteur des plaines","quête de viande de trotteur des plaines","que faire de la viande de trotteur des plaines"}},{q="Qui demande cette viande ?",a="Grull Vent-du-faucon demande aux jeunes chasseurs de chasser les trotteurs des plaines et de réapprovisionner les réserves de nourriture de la tribu, tout en prouvant leur valeur comme pourvoyeurs.",al={"qui veut de la viande de trotteur des plaines","viande pour grull vent-du-faucon"}},{q="Où trouver de la Viande de trotteur des plaines ?",a="Les trotteurs des plaines parcourent les prairies de Mulgore, notamment la Mesa de Nuage rouge, où les chasseurs récoltent leur viande.",al={"où trouver de la viande de trotteur des plaines","emplacements des trotteurs des plaines","farmer de la viande de trotteur des plaines"}},{q="Pourquoi la chasse aux trotteurs des plaines est-elle importante pour les Taurens ?",a="Les Taurens chassent les trotteurs des plaines pour se nourrir et comme discipline spirituelle. Rapporter du gibier au camp témoigne du respect pour la Terre-Mère, de l’autonomie et de la capacité à subvenir aux besoins de la tribu.",al={"culture de la chasse chez les taurens","pourquoi chasser les trotteurs des plaines"}}},fx={f1043112={q="Pourquoi la Viande de trotteur des plaines est-elle recherchée au Camp Narache ?",a="Les stocks de nourriture du Camp Narache sont au plus bas, et la tribu compte sur une chasse efficace pour reconstituer ses provisions. Grull Vent-du-faucon demande aux jeunes chasseurs de collecter de la Viande de trotteur des plaines pour nourrir le village et prouver leur habileté au Chef Vent-du-faucon.",al={"pourquoi besoin viande trotteur","but viande trotteur des plaines","pourquoi collecter viande trotteur"}},f404715e={q="Qu'est-ce que la Viande de trotteur des plaines ?",a="La Viande de trotteur des plaines est du gibier frais récolté sur les oiseaux incapables de voler qui errent dans les plaines de Mulgore. Pour les taurens de la Mesa de Nuage rouge, c'est une nourriture de base vitale, rassemblée lors de chasses traditionnelles qui soutiennent la colonie et honorent le lien entre le chasseur et sa proie.",al={"info sur la viande de trotteur des plaines","qu'est-ce que la viande de trotteur des plaines","lore de la viande de trotteur des plaines"}},["00c8b7f8"]={q="D'où vient la Viande de trotteur des plaines ?",a="La Viande de trotteur des plaines provient des trotteurs des plaines sauvages originaires de Mulgore. Les jeunes chasseurs la récoltent directement sur les bêtes errant sur la Mesa de Nuage rouge lors de leurs premiers rites de chasse pour la tribu.",al={"d'où vient la viande de trotteur des plaines","origine de la viande de trotteur des plaines","comment obtenir de la viande de trotteur des plaines"}}},fp="17,165,23.293.0,22.221.0,35.116.0,23.135.0,37.99.0,64.176.0"}
P.entries["item:plainstrider-scale"] = {n="Ecaille de trotteur des plaines",s="À Mulgore, Maur Mande-pluie a besoin d’une Ecaille de trotteur des plaines pour préparer un remède au village de Sabot-de-Sang. Cette écaille robuste aide à combattre une infection qui se propage.",h="À Mulgore, Maur Mande-pluie a besoin d’une Ecaille de trotteur des plaines pour préparer un remède au village...",kw={"sabot-de-sang","maur mande-pluie","mazzranache","mulgore","trotteur des plaines","remède","écaille","grand trotteur"},ang={["race:Tauren"]="En tant que Tauren, vous apprenez à recueillir des remèdes dans la nature et à utiliser la faune des plaines pour faire vivre votre tribu."},sec={{t="Un ingrédient rare",b="Les trotteurs des plaines parcourent Mulgore, leurs pattes puissantes couvertes d’écailles robustes. Elles les protègent, mais seules certaines sont assez fermes pour être broyées et servir dans des remèdes populaires."},{t="Un remède contre une morsure venimeuse",b="Maur Mande-pluie, au village de Sabot-de-Sang, a été mordu à l’épaule par Mazzranache, un trotteur légendaire aux yeux rouges démoniaques et à la morsure venimeuse. La blessure l’a plongé dans le délire et la fièvre. Pour purifier l’infection qui se propage avant qu’elle ne lui soit fatale, il lui faut une Ecaille de trotteur des plaines, un cœur de loup, un fémur de puma et un gésier de rapace."}},faq={{q="À quoi sert l’Ecaille de trotteur des plaines ?",a="Maur Mande-pluie, au village de Sabot-de-Sang, a besoin d’une Ecaille de trotteur des plaines pour préparer un remède. Il la combine avec des morceaux d’autres prédateurs de Mulgore afin de soigner la blessure infectée que Mazzranache lui a infligée avec sa morsure venimeuse.",al={"utilité de l’écaille de trotteur des plaines","usage de l’écaille de trotteur des plaines","besoin d’une écaille de trotteur des plaines"}},{q="Où trouver une Ecaille de trotteur des plaines ?",a="Vous trouverez des écailles de trotteur des plaines sur les trotteurs sauvages qui parcourent les prairies dégagées de Mulgore.",al={"où trouver une écaille de trotteur des plaines","comment obtenir une écaille de trotteur des plaines","emplacement de l’écaille de trotteur des plaines"}},{q="Pourquoi Maur Mande-pluie est-il infecté ?",a="Mazzranache, un grand trotteur aux yeux cramoisis et à la morsure venimeuse, a mordu Maur Mande-pluie à l’épaule. La blessure lui a donné une fièvre qui s’aggrave et l’a plongé dans le délire.",al={"comment maur est-il tombé malade","pourquoi maur est-il malade","morsure de mazzranache"}},{q="De quels autres ingrédients Maur a-t-il besoin pour son remède ?",a="Pour son remède, Maur a besoin d’une Ecaille de trotteur des plaines, d’un Cœur de loup des prairies, d’un Fémur de puma des basses plaines et d’un Gésier de Rapace.",al={"ingrédients de maur mande-pluie","remède contre mazzranache","objets de quête de mazzranache"}}},fx={["95a4c3dd"]={q="Qu'est-ce qu'une Ecaille de trotteur des plaines ?",a="Il s'agit d'une écaille robuste et spécialisée prélevée sur les trotteurs qui parcourent les prairies balayées par les vents de Mulgore. Bien que les oiseaux et les trotteurs soient connus principalement pour leur plumage et leur bec acéré, leurs pattes rugueuses sont recouvertes d'écailles dures et épaisses, capables de résister à la rudesse des plaines. Les chamans et les herboristes apprécient ces écailles rares et denses pour leurs propriétés protectrices lors de la préparation de onguents et de remèdes spécialisés.",al={"qu'est-ce qu'une ecaille de trotteur","ecaille de trotteur des plaines","ecailles de trotteur des plaines"}},d7ded3c8={q="D'où vient l'Ecaille de trotteur des plaines ?",a="C'est une partie animale naturelle prélevée directement sur les trotteurs sauvages qui errent dans Mulgore. Personne ne la fabrique ; les chasseurs la récoltent sur les pattes des trotteurs tombés dans les plaines, ne gardant que les écailles les plus solides pour des préparations médicinales.",al={"source ecaille de trotteur","d'où vient l'ecaille de trotteur","qui a fabriqué l'ecaille de trotteur"}}},fp="18,142,17.156.0,28.325.1,40.203.0,39.85.0,32.167.0,53.115.0"}
P.entries["item:plainstrider-talon"] = {n="Serre de trotteur des plaines",s="Dans tout Mulgore, les chamans taurens récoltent des Serres de trotteur des plaines pour purifier leurs totems. Ces griffes acérées proviennent de grands trotteurs des plaines incapables de voler, natifs de la région, et aident à purifier l’eau corrompue.",h="Dans tout Mulgore, les chamans taurens récoltent des Serres de trotteur des plaines pour purifier leurs...",kw={"sabot-de-sang","totem purificateur","mulgore","mull corne-tonnerre","trotteur des plaines","serre de trotteur des plaines","poison water","puits sabot-d’hiver"},ang={["class:Shaman"]="En tant que chaman, vous pouvez voir comment les rituels taurens utilisent des parties physiques des bêtes, comme leurs serres, pour fabriquer des totems purificateurs et puiser dans les esprits natifs de la terre.",["race:Tauren"]="En tant que tauren, vous honorez la faune de Mulgore par la chasse. Chaque bête abattue contribue à soigner la Terre-Mère lorsque les gobelins l’exploitent."},sec={{t="Liens des plaines",b="De grands trotteurs des plaines incapables de voler parcourent les vastes prairies de Mulgore. Leurs pattes puissantes et leurs griffes acérées les aident à fouiller la terre dure et à se défendre contre les prédateurs. Pour les Taurens de Sabot-de-Sang, chaque partie d’une bête chassée revêt une signification spirituelle.\n\nQuand des entreprises gobelines souillèrent des sources sacrées comme le Puits Sabot-d’Hiver, le chaman Mull Corne-tonnerre chercha des serres de trotteur des plaines et des pattes de loup des prairies. Dans l’artisanat rituel tauren, les parties de prédateurs et d’animaux qui fourragent sur ces terres canalisent l’essence spirituelle du lieu dans des totems capables de purger les poisons contre nature."}},faq={{q="Quelles créatures donnent une Serre de trotteur des plaines ?",a="Les trotteurs des plaines adultes, les trotteurs des plaines anciens et le célèbre trotteur Mazzranache donnent des Serres de trotteur des plaines dans les prairies de Mulgore.",al={"qui donne une serre de trotteur des plaines","où trouver des serres de trotteur des plaines","source des serres de trotteur des plaines"}},{q="À quoi servent les Serres de trotteur des plaines ?",a="Mull Corne-tonnerre, à Sabot-de-Sang, a besoin de serres de trotteur des plaines et de pattes de loup des prairies pour fabriquer un totem purificateur. Il s’en sert pour purifier le Puits Sabot-d’Hiver corrompu.",al={"utilité des serres de trotteur des plaines","pourquoi ai-je besoin de serres","quête des serres de trotteur des plaines"}},{q="Pourquoi Mull Corne-tonnerre a-t-il besoin de parties d’animaux pour purifier l’eau ?",a="Le chamanisme tauren repose sur l’harmonie avec les esprits naturels de Mulgore. Lier la faune locale à un totem rituel invoque la puissance brute de la terre pour combattre les polluants contre nature introduits par les gobelins de KapitalRisk.",al={"pourquoi des pattes et des griffes d’animaux","serres pour rituel de purification chamanique"}},{q="Qui a empoisonné les puits de Mulgore ?",a="Des agents de KapitalRisk opérant à Mulgore, ainsi que leurs complices, ont souillé les puits sacrés des tribus. Leurs actes bouleversent l’environnement local et menacent les tribus taurens.",al={"qui a souillé les puits","qui a empoisonné l’eau de mulgore","responsable de l’eau empoisonnée"}}},fx={fdecb439={q="Qu'est-ce qu'une Serre de trotteur des plaines ?",a="Une Serre de trotteur des plaines est une griffe acérée prélevée sur les grands trotteurs incapables de voler qui parcourent Mulgore. Bien qu'utilisées naturellement par ces oiseaux rapides pour la défense et la recherche de nourriture dans les plaines, les serres portent également une connexion innée avec le monde naturel. Pour les Taurens, ces matériaux représentent la force de la terre et peuvent être canalisés par le biais de rituels chamaniques.",al={"qu'est-ce qu'une serre de trotteur","lore serres de trotteur","griffes de trotteur"}},["07c33870"]={q="D'où viennent les Serres de trotteur des plaines ?",a="Ces serres sont prélevées sur les trotteurs adultes qui parcourent les plaines ouvertes de Mulgore, au sud-ouest du village de Sabot-de-Sang. Les chasseurs les récoltent sur des trotteurs adultes ou âgés, ou même sur des bêtes rares comme Mazzranache, comme des offrandes de la générosité de la terre.",al={"source serre de trotteur","où trouver serres de trotteur","origine serre de trotteur"}},["826885d3"]={q="Pourquoi Mull Corne-tonnerre veut-il des Serres de trotteur des plaines ?",a="Mull Corne-tonnerre, au village de Sabot-de-Sang, a besoin de ces serres pour fabriquer un totem de purification pour le Puits Sabot-d'Hiver. Les gobelins et leurs laquais de KapitalRisk ont souillé l'eau sacrée, et Mull doit faire appel à l'essence primale des bêtes natives de Mulgore pour contrer le poison et restaurer la pureté du puits.",al={"pourquoi mull veut des serres","pourquoi besoin serre de trotteur","but serre de trotteur"}}},fp="18,188,19.568.0,41.136.0,38.171.0,63.212.0,40.189.0"}
P.entries["item:podrig-s-order"] = {n="Ordre de Podrig",s="En Forêt des Pins-Argentés, l’Ordre de Podrig demande des armes à Fossoyeuse pour équiper le Sépulcre.",h="En Forêt des Pins-Argentés, l’Ordre de Podrig demande des armes à Fossoyeuse pour équiper le Sépulcre.",kw={"gordon wendham","hadrec","karos razok","podrig","ordre de podrig","le sépulcre","forêt des pins-argentés"},ang={["profession:Blacksmithing"]="En tant que forgeron, vous savez que les armes forgées sont vitales sur les lignes de front. Les combats épuisent sans cesse les réserves d’une garnison.",["race:Undead"]="En tant que mort-vivant, vous pouvez voir comment Fossoyeuse ravitaille les avant-postes comme le Sépulcre. Ainsi, les soldats de la Dame noire restent armés contre le Fléau."},sec={{t="Armer le Sépulcre",b="Le Garde noir Podrig jugea les réserves du Sépulcre globalement suffisantes après l’inventaire ordonné par l’exécuteur Hadrec. Pourtant, les armes de remplacement venaient cruellement à manquer. Sa dépêche énumère les lames et les armes nécessaires aux gardes noirs qui tiennent l’avant-poste dans la Forêt des Pins-Argentés. Le Fléau, les bêtes sauvages et d’autres dangers menacent la frontière."},{t="Dépêche par maître des chauves-souris",b="L’ordre est adressé à Gordon Wendham, marchand d’armes dans le Quartier des Marchands de Fossoyeuse. Les cryptes humides de la Forêt des Pins-Argentés rendent la forge difficile. Des courriers transportent le document jusqu’au maître des chauves-souris Karos Razok, afin que les trajets aériens réprouvés accélèrent l’acheminement depuis la capitale."}},faq={{q="Que contient l’Ordre de Podrig ?",a="L’Ordre de Podrig énumère les armes de remplacement destinées aux gardes noirs du Sépulcre. Leurs armes ont été perdues ou brisées sur le terrain.",al={"contenu de l’ordre","contenu de l’ordre de podrig","détails de l’ordre de podrig"}},{q="Qui a écrit l’Ordre de Podrig ?",a="Le Garde noir Podrig a rédigé l’ordre sur instruction de l’exécuteur Hadrec. Il l’a fait après l’inventaire de l’armurerie du Sépulcre.",al={"qui l’a écrit","auteur de l’ordre de podrig"}},{q="Qui reçoit l’ordre ?",a="L’ordre est destiné à Gordon Wendham, marchand d’armes dans le Quartier des Marchands de Fossoyeuse.",al={"qui reçoit l’ordre","où va l’ordre de podrig","destinataire de l’ordre de podrig"}},{q="Pourquoi le Sépulcre a-t-il besoin de nouvelles armes ?",a="Les escarmouches contre le Fléau et d’autres forces hostiles en Forêt des Pins-Argentés laissent souvent l’équipement des gardes noirs brisé ou perdu. Ils ont besoin d’armes de remplacement.",al={"pourquoi faut-il des armes","pénurie d’armes au sépulcre"}}},fx={["92a3bbc0"]={q="Qu'est-ce que l'Ordre de Podrig ?",a="L'Ordre de Podrig est un document de réquisition officiel des Réprouvés, rédigé afin d'obtenir de l'armement frais pour l'avant-poste du Sépulcre. Rédigé par Podrig pour le compte de l'exécuteur Hadrec, le parchemin liste les armes de remplacement nécessaires aux Gardes de la mort de la garnison pour survivre à leurs affrontements continus contre le Fléau et d'autres terreurs rôdant dans la forêt des Pins-Argentés.",al={"qu'est-ce que l'ordre de podrig","objet ordre de podrig","réquisition de podrig"}},["6fc9fe58"]={q="Pourquoi Gordon Wendham a-t-il besoin de l'Ordre de Podrig ?",a="En tant que marchand d'armes du quartier des Marchands à Fossoyeuse, Gordon Wendham a besoin de cette réquisition formelle pour vérifier et satisfaire la demande de ravitaillement de la garnison. Sans ce manifeste vérifié, le Sépulcre ne peut recevoir la cargaison d'armes et d'équipement nécessaire pour réapprovisionner ses Gardes de la mort en première ligne.",al={"pourquoi gordon wendham veut l'ordre","pourquoi apporter l'ordre de podrig à fossoyeuse","pourquoi l'ordre de podrig est nécessaire"}}},fp="14,82,20.335.0,24.268.0,34.124.0,25.121.0,23.96.0,40.152.0"}
P.entries["item:pork-belly-pie"] = {n="Tourte de panse de porc",s="Dans la Forêt d’Elwynn, Billy Maclure attend une tourte de la ferme des Champierreux avant de parler d’un collier disparu. Tante Bernice la prépare malgré la longue querelle entre leurs familles.",h="Dans la Forêt d’Elwynn, Billy Maclure attend une tourte de la ferme des Champierreux avant de parler d’un...",kw={"tante bernice champierreux","back to billy","billy maclure","forêt d’elwynn","maclure","tourte de panse de porc","champierreux"},ang={["faction:Alliance"]="Pour les voyageurs de l’Alliance venus aider dans les campagnes d’Elwynn, livrer des tourtes révèle les querelles profondes qui déchirent les terres agricoles de Hurlevent.",["profession:Cooking"]="La tourte maison de tante Bernice fait encore son effet malgré la querelle entre les familles, mais sa recette reste secrète."},sec={{t="Un pot-de-vin entre fermes rivales",b="Les familles Champierreux et Maclure se disputent les terres et l’honneur depuis des années. Le jeune Billy Maclure a un faible pour la tourte de panse de porc de tante Bernice. Quand un précieux collier de la famille Champierreux disparaît, Billy refuse de révéler ce qu’il sait avant qu’un aventurier lui apporte une part encore chaude. Bernice la prépare à contrecœur, en souhaitant que le garçon avide s’étouffe avec."}},faq={{q="À quoi sert la Tourte de panse de porc ?",a="Tante Bernice Champierreux prépare la tourte pour faire parler le jeune Billy Maclure. Il sait quelque chose sur le collier disparu de la famille Champierreux, mais refuse de parler avant d’avoir goûté à sa cuisine.",al={"utilité de la tourte","pourquoi la tourte de panse de porc","que faire de la tourte"}},{q="Qui prépare la Tourte de panse de porc ?",a="Tante Bernice Champierreux prépare la tourte à la ferme des Champierreux. Elle en veut à Billy Maclure et à sa famille, mais la prépare pour aider à retrouver le collier perdu de sa famille.",al={"qui a préparé la tourte","cuisinière de la tourte","tourte de tante bernice champierreux"}},{q="Pourquoi Billy Maclure veut-il de la nourriture d’une famille rivale ?",a="Billy Maclure veut goûter à la cuisine de tante Bernice malgré la querelle entre les Champierreux et les Maclure. Il préfère la tourte de panse de porc à sa rancune familiale.",al={"pourquoi billy veut une tourte","pourquoi maclure veut de la nourriture des champierreux"}},{q="Les joueurs peuvent-ils manger la Tourte de panse de porc ?",a="Non. La tourte est destinée à Billy Maclure et ne peut pas être mangée pour restaurer la santé ou le mana.",al={"peut-on la manger","la tourte de panse de porc se mange-t-elle"}}},fx={["6505ed9f"]={q="Qu'est-ce que la Tourte de panse de porc ?",a="Il s'agit d'une tourte à la viande salée préparée avec de la panse de porc, réputée pour être délicieuse malgré la querelle amère entre les deux familles de fermiers du sud de la Forêt d’Elwynn. Fraîchement préparée dans la cuisine des Champierreux, elle sert de pot-de-vin appétissant pour obtenir des informations de la part du jeune Maclure, Billy, qui prétend que sa mémoire ne fonctionne que lorsqu'il a l'estomac plein.",al={"qu'est-ce que la tourte de panse de porc","lore tourte de panse de porc","à propos de la tourte de panse de porc"}}},fp="14,167,29.366.0,36.188.0,29.161.0,53.181.0,35.85.0"}
P.entries["item:powdered-azurite"] = {n="Azurite en poudre",s="Dans les Contreforts de Hautebrande, les ouvriers broient la pierre bleue de la Mine de Veine-Azur pour en faire de l’Azurite en poudre. Thun'grim Firegaze en a besoin pour forger une armure brutale aux guerriers montants de la Horde.",h="Dans les Contreforts de Hautebrande, les ouvriers broient la pierre bleue de la Mine de Veine-Azur pour en...",kw={"mine de veine-azur","azurite","brutal armor","hautebrande","azurite en poudre","réactif","thun'grim firegaze"},ang={["class:Warrior"]="En tant que guerrier, vous mettez votre endurance à l’épreuve à l’étranger tout en récoltant de l’Azurite en poudre pour Thun'grim Firegaze. Il a besoin de ce réactif pour forger votre armure à la force sauvage.",["faction:Horde"]="En tant que membre de la Horde, vous devez vous enfoncer au cœur des Royaumes de l'est et prendre aux mains de l’Alliance la poussière raffinée des Contreforts de Hautebrande."},sec={{t="Un composé minéral rare",b="Des ouvriers humains extraient la pierre bleue des filons minéraux sous les Contreforts de Hautebrande. Ils la broient et la conditionnent pour le commerce et la métallurgie. Un forgeron expérimenté mélange la poussière à des métaux denses, ce qui rend l’armure plus durable et résistante."},{t="Forger une Brutal Armor",b="Les forgerons de la Horde prisent l’Azurite en poudre pour sa résistance en métallurgie, bien que le minerai provienne de tunnels tenus par les humains, de l’autre côté de la Grande mer. Thun'grim Firegaze est un armurier orc vieillissant des Tarides. Il en demande de petites quantités avec du fer raffiné et des réactifs ardents. Mélangée à la fonte, la poudre l’aide à marteler les lourdes plaques de sa Brutal Armor."}},faq={{q="À quoi sert l’Azurite en poudre ?",a="Thun'grim Firegaze mélange l’Azurite en poudre à des lingots de fer et à des réactifs volatils pour forger des pièces de Brutal Armor destinées aux champions de la Horde.",al={"utilisation de l’azurite en poudre","qu’est-ce que l’azurite en poudre"}},{q="Où trouver de l’Azurite en poudre ?",a="Les mineurs humains récoltent l’Azurite en poudre dans la Mine de Veine-Azur, sur la côte sud des Contreforts de Hautebrande, dans les Royaumes de l'est.",al={"où trouver de l’azurite en poudre","emplacement de l’azurite en poudre","qui laisse tomber de l’azurite en poudre"}},{q="Pourquoi un armurier des Tarides a-t-il besoin de réactifs de Hautebrande ?",a="Thun'grim Firegaze recherche des matériaux de qualité pour fabriquer une armure digne de guerriers légendaires. Le fer est facile à trouver, mais le minerai de Veine-Azur trempe le métal. Il envoie donc ses champions le chercher de l’autre côté de la mer.",al={"pourquoi hautebrande","source minérale de thun'grim"}}},fx={["139f7c50"]={q="Qu'est-ce que l'Azurite en poudre ?",a="L'Azurite en poudre est un réactif minéral bleu broyé, extrait de veines profondes dans les Contreforts de Hautebrande. Révéré par les maîtres armuriers pour ses propriétés métallurgiques uniques, la fine poudre peut être alliée ou trempée dans des métaux de base lors de la forge. Elle est particulièrement appréciée par l'armurier de la Horde Thun'grim Firegaze, qui l'utilise avec des réactifs exotiques pour fabriquer des armures de mailles lourdes et résistantes, dignes de guerriers renommés.",al={"qu'est-ce que l'azurite en poudre","lore azurite en poudre","objet azurite en poudre"}},["720f3d61"]={q="D'où vient l'Azurite en poudre, et qui l'a minée ?",a="La substance est extraite de la Mine d'Azurelode, située le long des collines méridionales des Contreforts de Hautebrande. Les mineurs Humains travaillant dans les puits souterrains d'Azurelode déterrent le minerai d'azurite brut et le broient en une poudre raffinée. Comme la mine reste sous le contrôle ferme des travailleurs humains de Hautebrande, l'obtention de la poudre nécessite de la prendre directement aux mineurs travaillant sous terre.",al={"où trouver azurite en poudre","qui mine l'azurite en poudre","source azurite en poudre"}}},fp="16,168,23.218.0,20.366.0,34.133.0,36.128.0,67.193.0"}
P.entries["item:powers-of-the-void"] = {n="Puissance du Vide",s="À Comté-du-Nord, un tome dérobé attire l’attention de Drusilla La Salle. Un novice a pris Puissance du Vide dans une aile gardée de la bibliothèque de l’Abbaye de Comté-du-Nord, alors qu’il partait rejoindre la Confrérie défias. Drusilla cherche le livre pour ses propres recherches sur la magie noire.",h="À Comté-du-Nord, un tome dérobé attire l’attention de Drusilla La Salle.",kw={"confrérie défias","drusilla la salle","diablotin","khadgar","abbaye de comté-du-nord","puissance du vide","livres dérobés","the stolen tome","démoniste"},ang={["class:Warlock"]="En tant que démoniste, récupérer le tome dérobé permet de vérifier si vous avez la volonté nécessaire pour mériter qu’on vous apprenne à invoquer un diablotin.",["race:Human"]="En tant qu’humain, vous pouvez constater que l’Ordre sacré de Comté-du-Nord conserve des archives magiques dangereuses aux côtés de textes ecclésiastiques, à l’abri des regards des novices."},sec={{t="Un texte interdit de Comté-du-Nord",b="Puissance du Vide était conservé derrière des rayonnages gardés dans la bibliothèque de l’Abbaye de Comté-du-Nord. Les archives de l’abbaye renferment des textes sacrés et des registres ecclésiastiques, ainsi que des ouvrages savants sur les énergies de l’ombre et du Néant. On pense que l’archimage Khadgar a rédigé le tome. Son sujet était dangereux ; les autorités de l’abbaye le gardaient donc sous surveillance, à l’abri des visiteurs de passage. Cela empêchait Drusilla La Salle, mentor des démonistes de Comté-du-Nord, de le consulter sans éveiller les soupçons du clergé."},{t="Vol des défias et récupération",b="Un novice de Comté-du-Nord a emporté le tome lorsqu’il a renié ses vœux pour rejoindre la Confrérie défias. En fuyant dans les vignobles voisins, il a pris plusieurs volumes précieux de l’abbaye. Drusilla envoie de prometteurs initiés démonistes au camp de bandits défias pour récupérer le livre dans leurs tentes. Elle convoite son savoir obscur pour ses propres recherches. Cette épreuve permet de vérifier si un initié a le cran nécessaire pour asservir des démons d’outre-monde."}},faq={{q="Qu’est-ce que Puissance du Vide ?",a="Puissance du Vide est un rare ouvrage occulte sur les énergies de l’ombre et du Néant, que l’on pense rédigé par l’archimage Khadgar. Avant son vol, le tome était conservé dans une aile gardée de la bibliothèque de l’Abbaye de Comté-du-Nord.",al={"qu’est-ce que puissance du vide","livre puissance du vide","qu’est-ce que le tome dérobé"}},{q="Pourquoi le livre était-il enfermé dans l’Abbaye de Comté-du-Nord ?",a="L’Abbaye de Comté-du-Nord conserve des archives historiques, dont des textes dangereux sur la magie illicite. Les ouvrages sur les énergies du Vide et la démonologie sont enfermés afin que les novices et les praticiens égarés ne puissent en faire mauvais usage.",al={"pourquoi était-il dans l’abbaye","pourquoi les prêtres l’avaient-ils","aile de la bibliothèque de comté-du-nord"}},{q="Comment la Confrérie défias a-t-elle obtenu le livre ?",a="Un novice de l’Abbaye de Comté-du-Nord a fait défection au profit de la Confrérie défias et a emporté plusieurs volumes précieux de la bibliothèque interdite. Il les a cachés dans le camp de bandits des vignobles de Comté-du-Nord.",al={"qui a volé le livre","livres volés par les défias","comment les défias l’ont-ils obtenu"}},{q="Pourquoi Drusilla La Salle veut-elle Puissance du Vide ?",a="Drusilla La Salle veut le savoir du tome pour ses propres pratiques occultes. En tant que mentor des démonistes de Comté-du-Nord, elle ne pouvait pas entrer dans la bibliothèque gardée de l’abbaye sans éveiller les soupçons.",al={"pourquoi drusilla le veut-elle","qui veut le livre","drusilla la salle tome dérobé"}},{q="Que prouve la récupération du tome à Drusilla ?",a="La récupération du tome permet de vérifier si un initié a le cran nécessaire pour asservir des démons. Drusilla lui fait passer cette épreuve avant de lui apprendre à invoquer son premier diablotin.",al={"pourquoi les démonistes ont-ils besoin du livre","épreuve d’invocation d’un diablotin","récompense du tome dérobé"}}},fx={["082e56cb"]={q="Qui a écrit Puissance du Vide ?",a="Le traité arcanique aurait été rédigé par l'archimage légendaire Khadgar, qui a étudié de nombreux aspects profonds et périlleux de la magie avant de s'aventurer au-delà de La Porte des ténèbres. Ses connaissances interdites sur le vide profond ont été jugées beaucoup trop dangereuses pour une lecture occasionnelle, incitant les prêtres et les érudits de l'Abbaye de Comté-du-Nord à le sceller dans une aile protégée de leur bibliothèque jusqu'à ce qu'un novice perfide ne le vole.",al={"auteur puissance du vide","qui a fait puissance du vide","créateur puissance du vide"}}},fp="18,251,28.476.0,25.427.0,27.217.0,47.198.0,44.183.0,51.175.0,48.147.0"}
P.entries["item:prairie-alpha-tooth"] = {n="Dent d'Alpha des prairies",s="Près des Pitons-du-Tonnerre, des alphas loups des prairies parcourent les plaines de Mulgore. Mull Corne-tonnerre a besoin de leurs dents pour purifier le puits Wildmane.",h="Près des Pitons-du-Tonnerre, des alphas loups des prairies parcourent les plaines de Mulgore.",kw={"sabot-de-sang","mulgore","mull corne-tonnerre","dent d'alpha des prairies","alpha loup des prairies","puits d'eau","wildmane totem"},ang={["class:Shaman"]="En tant que chaman, vous apaisez les esprits des puits en rétablissant l'équilibre de la terre. Offrir les crocs d'un prédateur au sommet de la chaîne alimentaire ancre cette harmonie naturelle.",["race:Tauren"]="En tant que Tauren, prendre le croc d'un alpha des prairies honore votre devoir sacré de chasseur. Récoltez ce qui est nécessaire avec respect, puis rendez cette essence primordiale à la terre empoisonnée pour la guérir."},sec={{t="Une offrande purificatrice",b="Les puits de Mulgore font vivre les Tauren, et des rites de respect et de sacrifice préservent leur pureté. Mull Corne-tonnerre, du village de Sabot-de-Sang, a besoin des dents des alphas loups des prairies qui rôdent sous les Pitons-du-Tonnerre pour purifier le puits Wildmane. Ces redoutables chefs de meute incarnent la force de la nature sauvage. Leurs dents rendent hommage à l’équilibre entre le chasseur, sa proie et les esprits de la terre."}},faq={{q="À quoi sert une Dent d'Alpha des prairies ?",a="Mull Corne-tonnerre utilise huit dents d'alpha des prairies lors d'un rituel pour purifier le puits Wildmane. C'est le dernier puits contaminé près du village de Sabot-de-Sang.",al={"utilité d'une dent d'alpha","utilité des dents de loup à mulgore","objet wildmane totem"}},{q="Où rôdent les alphas loups des prairies ?",a="Les alphas loups des prairies parcourent les plaines herbeuses de Mulgore, surtout dans les régions centrale et nord, près des falaises au pied des Pitons-du-Tonnerre.",al={"où rôdent les alphas loups des prairies","emplacements des loups alpha","lieux où trouver les alphas loups des prairies"}},{q="Pourquoi un rituel de purification de l'eau nécessite-t-il des dents de loup ?",a="Les rites des Tauren honorent l'équilibre de la nature. La purification requiert des parties sacrées des redoutables bêtes indigènes de Mulgore, symboles du sacrifice et de la vitalité de sa faune.",al={"pourquoi des dents de loup pour l'eau","lore du rituel des dents de mull corne-tonnerre"}}},fx={f1f3b80c={q="Qu'est-ce qu'une Dent d'Alpha des prairies ?",a="Une Dent d'Alpha des prairies est une dent prélevée sur un alpha de loup des prairies, l'un des chefs de meute les plus féroces rôdant dans les plaines de Mulgore. Chez les Taurens, ces crocs représentent la force et l'esprit des superprédateurs de la terre, portant un poids spirituel lorsqu'ils sont offerts lors d'un rituel.",al={"dent d'alpha des prairies","qu'est-ce qu'une dent d'alpha des prairies","dent alpha loup des prairies"}},["0674aadd"]={q="D'où vient une Dent d'Alpha des prairies ?",a="Ces dents sont récoltées sur les loups des prairies alpha qui errent dans les prairies de Mulgore, en particulier près de la base des Pitons-du-Tonnerre au nord. Étant des crocs naturels de prédateurs vivants, ils sont pris directement sur les bêtes pendant la chasse plutôt que fabriqués par des mains mortelles.",al={"d'où viennent les dents d'alpha des prairies","origine dent d'alpha des prairies","qui donne dent d'alpha des prairies"}}},fp="19,134,20.357.0,39.147.0,34.146.0,53.169.0"}
P.entries["item:prairie-wolf-heart"] = {n="Cœur de loup des prairies",s="Maur Mande-pluie, à Sabot-de-Sang, a besoin d’un Cœur de loup des prairies pour soigner une morsure venimeuse.",h="Maur Mande-pluie, à Sabot-de-Sang, a besoin d’un Cœur de loup des prairies pour soigner une morsure venimeuse.",kw={"sabot-de-sang","maur mande-pluie","mazzranache","mulgore","rôdeur des prairies","cœur de loup des prairies","cœur de loup"},ang={["class:Hunter"]="En tant que chasseur, vous apprenez à suivre les meutes qui chassent dans les plaines de Mulgore et à comprendre les bêtes qui y vivent.",["race:Tauren"]="En tant que tauren, vous savez que les parties d’animaux peuvent servir à préparer des remèdes pratiques pour survivre dans les étendues sauvages de Mulgore."},sec={{t="Un remède contre une morsure venimeuse",b="Maur Mande-pluie vit à Sabot-de-Sang, où le venin de Mazzranache, le légendaire trotteur des plaines, lui a donné de la fièvre. La morsure menace de répandre le poison dans tout son corps. Maur cherche un cœur de loup des prairies, un os de cougar et un gésier d’oiseau pour préparer un remède traditionnel des plaines. Il espère enrayer l’infection avant que le délire ne lui soit fatal."}},faq={{q="À quoi sert un Cœur de loup des prairies ?",a="Maur Mande-pluie, à Sabot-de-Sang, a besoin d’un Cœur de loup des prairies pour préparer un remède populaire. Il le mélange à d’autres parties d’animaux pour soigner la morsure venimeuse que lui a infligée Mazzranache.",al={"utilité du cœur de loup","pourquoi obtenir un cœur de loup","utilité du cœur de loup des prairies"}},{q="Où trouver un Cœur de loup des prairies ?",a="Les loups des prairies, les alphas des prairies et les rôdeurs des prairies chassent dans les plaines de Mulgore. Le cœur se trouve dans leur dépouille.",al={"emplacement du cœur de loup","qui donne le cœur de loup","où trouver le cœur de loup des prairies"}},{q="Pourquoi Maur Mande-pluie a-t-il besoin d’organes d’animaux pour soigner sa blessure ?",a="La morsure infectée de Mazzranache provoque fièvre et délire. Maur compte sur les remèdes des plaines taurens, préparés avec un cœur de loup, un fémur de cougar, une Écaille de trotteur des plaines et un Gésier de Rapace, pour purifier l’infection avant qu’elle ne lui soit fatale.",al={"pourquoi utiliser un cœur de loup en médecine","remède de maur"}},{q="N’importe quel cœur de loup peut-il servir au remède ?",a="Maur demande un cœur de loup. Celui dont il a besoin pour son remède provient d’un loup des prairies, d’un alpha des prairies ou d’un rôdeur des prairies des plaines de Mulgore.",al={"n’importe quel cœur de loup","quels loups le donnent"}}},fx={ee1c9772={q="Qu'est-ce qu'un Cœur de loup des prairies ?",a="Un Cœur de loup des prairies est l'organe récolté des loups prédateurs qui rôdent dans les plaines vallonnées de Mulgore. Bien qu'il n'ait que peu de valeur commerciale, la vitalité du cœur d'une bête sauvage en fait un ingrédient prisé dans la médecine traditionnelle Tauren. Il sert de l'un des nombreux réactifs puissants nécessaires pour brasser des remèdes capables de purger les poisons naturels virulents et les infections profondes.",al={"qu'est-ce qu'un coeur de loup des prairies","cœur de loup des prairies","à propos du coeur de loup des prairies"}},["1392571f"]={q="D'où vient un Cœur de loup des prairies ?",a="Le cœur est prélevé directement sur les loups des prairies, les alphas de loup des prairies et les traqueurs des prairies sauvages natifs des plateaux herbeux de Mulgore. C'est un organe biologique naturel récolté sur un prédateur tué plutôt qu'un objet fabriqué par des mains mortelles.",al={"d'où vient le coeur de loup des prairies","origine coeur de loup des prairies","qui a fabriqué le coeur de loup des prairies"}}},fp="18,89,28.330.0,38.170.0,43.121.0,63.220.0,42.143.0"}
P.entries["item:prairie-wolf-paw"] = {n="Patte de loup des prairies",s="Dans tout Mulgore, les loups des prairies chassent dans les plaines, et leurs pattes sont récoltées pour les rites chamaniques. Au village de Sabot-de-Sang, Mull Corne-tonnerre les associe à des serres de trotteur des prairies pour créer un totem de purification.",h="Dans tout Mulgore, les loups des prairies chassent dans les plaines, et leurs pattes sont récoltées pour les...",kw={"sabot-de-sang","mulgore","mull corne-tonnerre","serre de trotteur des plaines","poison water","loup des prairies","patte de loup des prairies","puits sabot-d’hiver"},ang={["class:Shaman"]="En tant que chaman, vous utilisez des totems de purification fabriqués à partir de parties d’animaux locaux pour puiser dans l’essence vivante de la terre et purger la corruption contre nature.",["race:Tauren"]="En tant que tauren, vous récoltez des pattes de loup pour prendre soin de la terre. Ses bêtes indigènes contribuent à purifier les puits ancestraux souillés par la cupidité des gobelins."},sec={{t="Composants naturels des plaines",b="Les loups des prairies chassent en meute dans les herbes de Mulgore, aux côtés des traqueurs des prairies et de leurs alphas de meute. Ils menacent les jeunes chasseurs et le bétail local. Pour les chamans taurens, ces pattes sont plus que des trophées : elles portent la vitalité naturelle de la terre et contribuent à l’équilibre spirituel des plaines."},{t="Purifier les puits",b="Quand des entreprises gobelines ont souillé les réserves d’eau sacrées de Mulgore, le chaman Mull Corne-tonnerre a eu besoin de l’aide de la terre pour lutter contre la pollution. Associées à des serres de trotteur des prairies, les pattes de loup apportent une résonance spirituelle aux totems de purification. Une fois le totem créé, la purification du Puits Sabot-d’Hiver peut commencer."}},faq={{q="Quelles créatures donnent une Patte de loup des prairies ?",a="Les loups des prairies, les traqueurs des prairies et les alphas des loups des prairies chassent dans les plaines de Mulgore, principalement au sud-ouest du village de Sabot-de-Sang, et fournissent des pattes de loup des prairies.",al={"qui donne une patte de loup des prairies","où trouver des pattes de loup des prairies","source des pattes de loup des prairies"}},{q="Qui veut des Pattes de loup des prairies ?",a="Mull Corne-tonnerre, un chaman tauren du village de Sabot-de-Sang, veut ces pattes pour aider à créer un totem de purification destiné aux puits contaminés.",al={"qui veut des pattes de loup des prairies","pattes de loup de mull corne-tonnerre","rendre les pattes de loup des prairies"}},{q="Pourquoi faut-il des pattes de loup pour purifier l’eau ?",a="Les chamans taurens font appel à la vitalité naturelle de la terre contre la corruption. Associées à des serres d’oiseau, les pattes de loup lient l’esprit vivant de Mulgore à un totem élémentaire capable de purger les poisons gobelins.",al={"pourquoi des pattes de loup","histoire des pattes de loup des prairies","pourquoi mull veut des pattes"}},{q="Quel puits ces pattes aident-elles à purifier ?",a="Ces pattes aident à créer un totem de purification pour le Puits Sabot-d’Hiver, empoisonné par des intrus gobelins et leurs agents.",al={"quel puits","purification du puits sabot-d’hiver"}}},fx={["94c15e4c"]={q="Qu'est-ce qu'une Patte de loup des prairies ?",a="Une Patte de loup des prairies est un composant rituel naturel récolté sur les canidés sauvages parcourant les plaines de Mulgore. Plutôt que de servir de simples trophées, ces pattes portent l'essence vivante de la terre, ce qui les rend précieuses pour les chamans Taurens qui fabriquent des totems pour guérir et préserver la terre.",al={"patte de loup des prairies","que sont les pattes de loup des prairies","patte de loup mulgore"}},["7a637be5"]={q="D'où viennent les Pattes de loup des prairies ?",a="Ces pattes sont récoltées directement sur les loups des prairies, les traqueurs des prairies et les alphas de loup natifs des plateaux herbeux de Mulgore. Ce sont des parties naturelles de la nature sauvage, prises par les chasseurs pour offrir la force de la terre en période de besoin spirituel.",al={"d'où viennent les pattes de loup des prairies","source patte de loup des prairies","qui donne pattes de loup"}}},fp="16,198,30.301.0,19.306.0,39.155.0,28.130.0,42.193.0,44.116.0"}
P.entries["item:prayer-to-elune"] = {n="Prayer to Elune",s="La Prayer to Elune est gravée sur une tablette d’or et se trouve parmi les affaires du Marteau du Crépuscule. Zamael Lunthistle demande qu’on la porte à Astarii Starseeker, au Temple de la Lune.",h="La Prayer to Elune est gravée sur une tablette d’or et se trouve parmi les affaires du Marteau du Crépuscule.",kw={"astarii starseeker","darnassus","elune","tablette dorée","prayer to elune","gorge des vents brûlants","temple de la lune","marteau du crépuscule"},ang={["race:NightElf"]="En tant qu’Elfe de la nuit, vous connaissez Elune comme la déesse de votre peuple ; cette tablette porte une prière destinée à lui parvenir."},sec={{t="Une tablette dorée",b="Parmi les affaires du Marteau du Crépuscule, dans la Gorge des Vents brûlants, se trouve une tablette d’or portant une prière à Elune. C’est la prière de Zamael Lunthistle, qui demande qu’on la porte à Astarii Starseeker, au Temple de la Lune de Darnassus, afin qu’elle soit entendue."}},faq={{q="Qu’est-ce que la Prayer to Elune ?",a="La Prayer to Elune est une prière gravée sur une tablette dorée.",al={"tablette de prière","prière à elune","quelle prière"}},{q="Où se trouve la prière ?",a="La tablette dorée se trouve parmi les affaires du Twilight’s Hammer, dans la Gorge des Vents brûlants.",al={"où est la tablette","trouver la prière","lieu de la prière"}},{q="Qui veut la tablette ?",a="Zamael Lunthistle souhaite que sa prière soit retrouvée et portée à Astarii Starseeker, au Temple de la Lune de Darnassus.",al={"qui la veut","prière d’astarii","à qui l’apporter"}},{q="Pourquoi Astarii la veut-elle ?",a="Cette prière est celle de Zamael. Il dit que sa foi s’est ravivée et que sa prière doit être entendue, même s’il ne s’attend à aucune absolution. Astarii vous remercie d’avoir rendu une âme égarée à Elune.",al={"pourquoi la tablette","pourquoi prier elune","à quoi sert-elle"}}},fp="15,192,15.263.0,28.60.0,20.83.0,21.116.0,25.178.0"}
P.entries["item:pridewing-venom-sac"] = {n="Glande à venin d'Aile-fière",s="Près du Lac Mirkfallon, le venin des Ailes-fières inquiète les Elfes de la nuit d’Astranaar. Selon des rapports, des agents de la Horde en récoltent pour mener des attaques secrètes, et les Sentinelles cherchent à les priver de ce poison.",h="Près du Lac Mirkfallon, le venin des Ailes-fières inquiète les Elfes de la nuit d’Astranaar.",kw={"astranaar","lac mirkfallon","aile-fière","shindrell prestefeu","les serres-rocheuses","glande à venin","wyverne"},ang={["faction:Alliance"]="Priver les agents de la Horde du venin des Ailes-fières aide à protéger les patrouilles des frontières contre les assassins invisibles le long des frontières disputées des Serres-Rocheuses et d’Orneval.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous pouvez regretter qu’il faille chasser d’innocentes bêtes sauvages. Pourtant, protéger les vies des elfes des lames empoisonnées passe avant tout."},sec={{t="Une menace dans les escarpements",b="Les Ailes-fières chassent dans les escarpements au sud d’Orneval, surtout près du Lac Mirkfallon. Originaires des Serres-Rocheuses, ces prédateurs volants s’aventurent jusqu’ici, et leur venin se trouve dans des glandes à l’intérieur de leur corps. Selon des rapports de Theramore, des assassins de la Horde utilisent ce poison pour enduire leurs lames et frapper en secret les villages des Elfes de la nuit. Les Sentinelles d’Astranaar envoient donc des éclaireurs chasser les wyvernes et récolter leurs glandes avant que les agents de la Horde ne puissent s’en emparer."}},faq={{q="Quelles créatures donnent une Glande à venin d'Aile-fière ?",a="Les jeunes Ailes-fières, les chasseurs du ciel, les patriarches et les consorts près du Lac Mirkfallon donnent des glandes à venin.",al={"où trouver une glande à venin d'aile-fière","qui donne une glande à venin d'aile-fière","sources de venin d'aile-fière"}},{q="Pourquoi Astranaar veut-elle des Glandes à venin d'Aile-fière ?",a="Shindrell Prestefeu a reçu des rapports selon lesquels des agents de la Horde enduisent leurs armes de venin d’Aile-fière pour lancer des attaques silencieuses contre l’Alliance. Prendre ou détruire les glandes peut empêcher ces assauts.",al={"pourquoi récolter des glandes à venin","venin de shindrell prestefeu"}},{q="Qui accepte ces glandes à venin en Orneval ?",a="À Astranaar, la ville des Elfes de la nuit en Orneval, Shindrell Prestefeu recueille les glandes à venin pour protéger son peuple des attaques secrètes.",al={"qui récupère le venin d'aile-fière","où rendre la quête des ailes-fières"}},{q="Les Ailes-fières sont-elles naturellement alliées à la Horde ?",a="Non. Les Ailes-fières près du Lac Mirkfallon sont des bêtes sauvages, pas des alliées volontaires de la Horde. Des agents orcs exploitent leur venin pour faire la guerre.",al={"les ailes-fières sont-elles de la horde","les ailes-fières travaillent-elles pour les orcs"}}},fx={e2bba8d5={q="Qu'est-ce qu'une Glande à venin d'Aile-fière ?",a="Une Glande à venin d'Aile-fière est un organe récolté sur les wyvernes aile-fière nichant dans Les Serres-Rocheuses. Elle contient les toxines naturelles puissantes que ces prédateurs ailés produisent pour soumettre leurs proies. Dans le fragile face-à-face entre les elfes de la nuit et la Horde, un tel venin est devenu une arme prisée pour les attaques secrètes, incitant les défenseurs d'Astranaar à prendre des mesures.",al={"qu'est-ce qu'une glande à venin d'aile-fière","objet glande à venin d'aile-fière","que sont les glandes à venin d'aile-fière"}},["816b56c2"]={q="D'où vient une Glande à venin d'Aile-fière ?",a="Ces glandes sont récoltées directement sur les corps des Aile-fière, de féroces wyvernes sauvages qui se perchent près du Lac Mirkfallon dans Les Serres-Rocheuses. Comme ce sont des organes corporels naturels produits par les bêtes elles-mêmes plutôt que des produits manufacturés, les obtenir nécessite de chasser les wyvernes à travers les escarpements et de sécuriser le venin avant que les agents de la Horde ne puissent le récolter.",al={"source glande à venin d'aile-fière","d'où viennent les glandes à venin d'aile-fière","qui donne glande à venin d'aile-fière"}}},fp="19,193,21.446.0,43.97.0,45.181.0,42.133.0,51.133.0"}
P.entries["item:prismatic-punch-card"] = {n="Carte perforée prismatique",s="À Gnomeregan, la Carte perforée prismatique possède le niveau d’habilitation le plus élevé. Les réfugiés gnomes de Forgefer recherchent les archives auxquelles elle donne accès.",h="À Gnomeregan, la Carte perforée prismatique possède le niveau d’habilitation le plus élevé.",kw={"castpipe","data rescue","engineering labs","gnomeregan","matricielle de cartes perforées","carte perforée prismatique"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous pouvez voir dans la programmation séquentielle des cartes perforées et le réseau automatisé de terminaux des exemples du haut niveau des machines informatiques fabriquées par les bricoleurs de Gnomeregan.",["race:Gnome"]="En tant que gnome, vous pouvez voir dans le système de sécurité de la Matricielle de cartes perforées l’ingéniosité et la bureaucratie gnomes toujours à l’œuvre après la chute de votre foyer."},sec={{t="Une question de sécurité",b="Quand les gnomes ont fui Gnomeregan, les troggs et les radiations toxiques les ont chassés de la ville. D’immenses réserves de recherches et d’archives civiques sont restées dans ses profondeurs. Les gnomes protégeaient les systèmes de haut niveau par plusieurs paliers d’habilitation. Pour atteindre la Matricielle de cartes perforées 3005-D dans les Engineering Labs inférieurs, une carte doit passer par une série de terminaux.\n\nLa carte est d’abord blanche, puis passe au jaune, au bleu et au rouge. Au terminal final, elle est poinçonnée en version prismatique. Son niveau d’habilitation encodé est indiqué comme étant en attente de l’invention d’un tout nouveau chiffre."},{t="La transmission vitale",b="Le Maître mécanicien Castpipe envoie des aventuriers depuis les enclaves de réfugiés de Forgefer dans les couloirs contaminés de Gnomeregan pour récupérer des données qu’il dit vitales et indispensables à la vie. Le message binaire de la Carte perforée prismatique révèle le contenu de la transmission : on informe Castpipe que son linge est prêt à être récupéré."}},faq={{q="Comment créer une Carte perforée prismatique ?",a="Insérez une Carte perforée rouge dans la Matricielle de cartes perforées 3005-D, dans les Engineering Labs inférieurs de Gnomeregan. Commencez par améliorer une Carte perforée blanche, dans l’ordre, avec les terminaux des modèles A, B et C répartis dans le complexe.",al={"obtenir la carte perforée prismatique","créer une carte perforée prismatique","ordre d’amélioration des cartes perforées"}},{q="Quelles données sont stockées sur la Carte perforée prismatique ?",a="La carte indique que son niveau de sécurité attend l’invention d’un nouveau chiffre, puis contient une longue suite de code binaire. Le Maître mécanicien Castpipe affirme que ces données sont vitales.",al={"que dit la carte","traduction du code binaire de la carte perforée","carte perforée décodée"}},{q="Qui veut la Carte perforée prismatique ?",a="Le Maître mécanicien Castpipe, un ingénieur gnome exilé à Forgefer, demande la carte dans le cadre de Data Rescue. Il affirme qu’elle contient des informations urgentes et inestimables, abandonnées lors de l’évacuation de Gnomeregan par les gnomes.",al={"qui rend la carte perforée prismatique","quête de castpipe","qui a besoin de la carte"}},{q="Où se trouvent les terminaux de la Matricielle de cartes perforées ?",a="Les terminaux sont répartis dans Gnomeregan selon les paliers d’habilitation. Le terminal 3005-A se trouve près du Train Depot et de l’entrée du Workshop Entrance, à proximité de la surface. Le modèle B est dans le dortoir, au-delà de la Clean Zone ; le modèle C se trouve plus profondément dans le complexe et le modèle D dans les Engineering Labs inférieurs.",al={"emplacement des terminaux","où sont les matricielles de cartes perforées","où poinçonner les cartes"}}},fx={f4168582={q="Qu'est-ce qu'une Carte perforée prismatique ?",a="Une Carte perforée prismatique est une carte de données à très haut niveau d'habilitation générée par les systèmes informatiques de Gnomeregan. Sa classification de sécurité automatisée est censée être si élevée que les mathématiques gnomiques n'ont pas encore inventé un nombre suffisant pour la décrire. En réalité, elle contient du texte binaire encodé produit par les terminaux des profondeurs de la ville, fonctionnant comme le summum du protocole d'extraction de données à plusieurs niveaux des gnomes.",al={"qu'est-ce qu'une carte perforée prismatique","lore carte perforée prismatique","carte prismatique gnomeregan"}},["7551673e"]={q="D'où vient la Carte perforée prismatique, et qui l'a fabriquée ?",a="La carte est produite au plus profond de la ville déchue de Gnomeregan par le Matrix Punchograph 3005-D, un terminal automatisé de haute sécurité situé au niveau inférieur des Engineering Labs. Elle n'est pas fabriquée à la main par une personne, mais encodée par le réseau mécanisé des gnomes lorsqu'un utilisateur insère une Carte perforée rouge correctement améliorée dans l'appareil.",al={"origine carte perforée prismatique","qui a fabriqué la carte perforée prismatique","où obtenir la carte perforée prismatique"}}},fp="20,134,20.538.0,22.316.1,41.204.0,48.169.1,35.200.0,51.268.0"}
P.entries["item:pristine-crawler-leg"] = {n="Pristine Crawler Leg",s="Les pattes de clampant intactes proviennent des crabes épineux des rochers qui vivent autour de l’île de Theramore. Morgan Stern en a besoin pour présenter un nouveau plat qu’il met au point.",h="Les pattes de clampant intactes proviennent des crabes épineux des rochers qui vivent autour de l’île de...",kw={"cuisine","patte de clampant","marécage d’âprefange","morgan stern","patte de clampant intacte","pattes de clampant intactes","spiny rock crab","theramore"},ang={["profession:Cooking"]="En tant que cuisinier, vous comprenez pourquoi Morgan tient autant à la carapace qu’à la chair : les deux font partie du plat qu’il met au point."},sec={{t="Une requête de chef",b="Morgan Stern met au point un plat sur l’île de Theramore, et les pattes de clampant intactes en sont l’un des ingrédients. Il veut des carapaces sans éraflures, car leur état compte pour la présentation du plat. Les Spiny Rock Crabs rôdent dans les eaux à l’est de l’île, où vous trouverez les pattes dont il a besoin."}},faq={{q="À quoi servent les pattes de clampant intactes ?",a="Morgan Stern a besoin de pattes de clampant intactes comme ingrédient pour une nouvelle recette qu’il met au point à Theramore.",al={"utilité des pattes de clampant","pourquoi des pattes intactes","ce dont morgan a besoin"}},{q="Où trouver des pattes de clampant intactes ?",a="Les Spiny Rock Crabs qui vivent dans les eaux à l’est de l’île de Theramore ont des pattes de clampant intactes.",al={"emplacement des pattes de clampant","où trouver des pattes de crabe","spiny rock crabs"}},{q="Pourquoi les pattes doivent-elles être intactes ?",a="Morgan veut des carapaces sans éraflures, car elles sont essentielles à la présentation du plat.",al={"pourquoi des carapaces sans éraflures","pattes de crabe parfaites","patte de clampant intacte"}},{q="Qui veut les pattes de clampant ?",a="Morgan Stern, un cuisinier de Theramore, veut ces pattes pour ses recherches sur une recette.",al={"pattes pour morgan stern","qui a besoin de pattes de crabe","cuisinier à theramore"}}},fp="20,156,18.288.0,35.106.0,39.84.0,36.80.0,27.74.0"}
P.entries["item:pristine-spider-silk"] = {n="Soie d'araignée en parfait état",s="Au Bois de la Pénombre, des araignées venimeuses fournissent le fil raffiné dont les mages de Hurlevent ont besoin pour tisser des robes résistantes aux enchantements.",h="Au Bois de la Pénombre, des araignées venimeuses fournissent le fil raffiné dont les mages de Hurlevent ont...",kw={"petit veuve noire","recluse charognarde","bois de la pénombre","robe de mage","soie d'araignée en parfait état","sanctuaire du sorcier","wynne larson"},ang={["class:Mage"]="En tant que mage de Hurlevent, vous êtes envoyé au Bois de la Pénombre pour récolter ce fil raffiné et gagner une robe à la mesure de votre talent grandissant pour les arcanes.",["profession:Tailoring"]="En tant que tailleur, vous travaillez avec un fil délicat et résistant, récolté sur des araignées mortelles. C’est un textile naturel de qualité pour les robes magiques."},sec={{t="Tisser l’arcane",b="Les mages de Hurlevent ont besoin d’une soie assez solide pour résister aux enchantements et à l’usure d’un adepte. Les tailleurs utilisent de la soie d’araignée ordinaire, mais les fils des recluses charognardes et des petits veuves noires du Bois de la Pénombre sont plus résistants. Les mages du Sanctuaire du sorcier envoient les adeptes prometteurs dans ces bois pour en récolter. Le maître tailleur Wynne Larson tisse ensuite la soie pour en faire une robe destinée à un adepte."}},faq={{q="D’où vient la Soie d’araignée en parfait état ?",a="La Soie d’araignée en parfait état provient des recluses charognardes et des petits veuves noires du Bois de la Pénombre.",al={"où trouver la soie d’araignée en parfait état","qui donne la soie d’araignée en parfait état","emplacement de la soie d’araignée en parfait état"}},{q="Qui confectionne des vêtements avec cette soie ?",a="Wynne Larson, une couturière du Quartier des Mages de Hurlevent, tisse la soie récoltée pour en faire une robe destinée au Sanctuaire du sorcier.",al={"qui utilise la soie d’araignée en parfait état","qui transforme la soie en robes","robe de wynne larson"}},{q="Pourquoi les mages ont-ils besoin de cette soie particulière ?",a="Les mages ont besoin d’une soie assez résistante pour qu’une robe d’adepte supporte les enchantements et l’usure. La soie des araignées du Bois de la Pénombre possède la résistance et la qualité requises.",al={"pourquoi une soie parfaite","utilisation de la soie d’araignée magique"}}},fx={dfaa8e27={q="Qu'est-ce que la Soie d'araignée en parfait état ?",a="La Soie d'araignée en parfait état est une toile immaculée, d'une finesse exceptionnelle, tissée par les arachnides qui hantent le Bois de la Pénombre. Contrairement aux toiles communes et en lambeaux que l'on trouve accrochées aux arbres dans toute la forêt sombre, seuls les brins les plus purs et intacts sont qualifiés de parfaits. Les tailleurs et les mages l'apprécient grandement pour sa qualité et sa texture supérieures, l'utilisant comme tissu de base essentiel pour confectionner des vêtements distingués adaptés aux mages en apprentissage.",al={"soie d'araignée en parfait état","qu'est-ce que la soie en parfait état","objet soie en parfait état"}}},fp="20,108,18.366.0,42.88.0,35.120.0,44.157.0"}
P.entries["item:pristine-tigress-fang"] = {n="Pristine Tigress Fang",s="Un Pristine Tigress Fang est un spécimen que le Prophète Mok'thardin recherche au Campement Grom'gol. Son état est important pour ses enchantements destinés à la Horde.",h="Un Pristine Tigress Fang est un spécimen que le Prophète Mok'thardin recherche au Campement Grom'gol.",kw={"enchantement","croc","grom'gol","ruines de mizjah","mok'thardin","pristine tigress fang","vallée de strangleronce","tigresse"},ang={["faction:Horde"]="Mok'thardin recherche le croc et les griffes de Shadowmaw pour canaliser la magie de la jungle au profit de la Horde."},sec={{t="Un spécimen de choix",b="De l’autre côté de la rivière, au sud-est des Ruines de Mizjah, les Stranglethorn Tigresses rôdent dans la jungle. Le Prophète Mok'thardin demande un croc en parfait état, ainsi que des griffes de Shadowmaw Panther. Il affirme que ses rituels ont déjà porté leurs fruits et compte canaliser la magie de la jungle pour la Horde."}},faq={{q="Qui veut le Pristine Tigress Fang ?",a="Le Prophète Mok'thardin, au Campement Grom'gol, veut un Pristine Tigress Fang pour ses enchantements.",al={"qui veut le croc","croc mok'thardin","pour qui le croc"}},{q="Pourquoi le croc doit-il être en parfait état ?",a="Mok'thardin affirme que seul un croc en parfait état convient à ses travaux sur la magie de la jungle.",al={"pourquoi en parfait état","croc parfait","état du croc"}},{q="Où trouver un Pristine Tigress Fang ?",a="Les Stranglethorn Tigresses de la Vallée de Strangleronce portent des Pristine Tigress Fangs. Mok'thardin désigne la jungle au sud-est des Ruines de Mizjah, de l’autre côté de la rivière.",al={"où trouver le croc","emplacement du croc de tigresse","croc de tigresse"}},{q="De quoi Mok'thardin a-t-il besoin d’autre ?",a="Mok'thardin demande aussi huit Shadowmaw Claws, en plus du Pristine Tigress Fang.",al={"de quoi a-t-il besoin d’autre","aussi des griffes","besoins de mok'thardin"}},{q="Que cherche à faire Mok'thardin ?",a="Mok'thardin cherche à canaliser la puissance de la magie de la jungle pour la Horde grâce à de puissants enchantements.",al={"magie de mok'thardin","enchantement de la jungle","pourquoi le veut-il"}}},fp="21,144,15.292.0,36.94.0,38.96.0,41.153.0,32.84.0,33.105.0"}
P.entries["item:prowler-claws"] = {n="Griffe de rôdeur",s="Dans les Tarides, les Griffes de rôdeur sont rapportées à Sergra Darkthorn, à La Croisée. Elles prouvent qu’un chasseur peut traquer et vaincre les rôdeurs qui rôdent dans les plaines.",h="Dans les Tarides, les Griffes de rôdeur sont rapportées à Sergra Darkthorn, à La Croisée.",kw={"les tarides","la croisée","griffe de rôdeur","les rôdeurs des tarides","rôdeur des savanes","sergra darkthorn"},ang={["class:Hunter"]="En tant que chasseur, traquer les rôdeurs des savanes et prendre leurs griffes met à l’épreuve votre aptitude à la furtivité, au pistage et à la maîtrise des bêtes au corps à corps.",["faction:Horde"]="En tant que membre de la Horde, contribuer à réduire le nombre de rôdeurs autour de La Croisée protège les messagers, les caravanes et les colons qui empruntent les routes centrales de Kalimdor."},sec={{t="Trophées du traqueur",b="Les rôdeurs des savanes se tapissent dans les hautes herbes des Tarides, prêts à frapper avec patience et ruse. Contrairement aux trotteurs des plaines et aux zhévras qui paissent, ces grands félins tendent des embuscades aux créatures qui pénètrent sur leur territoire de chasse. S’emparer de leurs griffes recourbées suppose d’affronter des prédateurs qui comptent sur la furtivité et défendent leur territoire. Pour les guerriers et les éclaireurs de la Horde, cette chasse met à l’épreuve leur capacité à traquer un prédateur sur son propre terrain et à faire de lui une proie."},{t="Une preuve pour la chasseresse",b="Sergra Darkthorn, la chasseresse de La Croisée, demande aux novices de lui rapporter des Griffes de rôdeur avant de les soumettre à de plus grandes épreuves. Ces griffes prouvent qu’un chasseur sait suivre des traces dans les herbes de la savane et résister à l’attaque d’un prédateur. Ceux qui reviennent avec elles ont montré qu’ils savent rester vigilants parmi les dangereuses bêtes des plaines."}},faq={{q="Où trouver des Griffes de rôdeur ?",a="Les rôdeurs des savanes parcourent les prairies centrales des Tarides, surtout les plaines au sud-ouest de La Croisée. Prenez leurs griffes et rapportez-les.",al={"emplacement des griffes de rôdeur","comment obtenir des griffes de rôdeur","où trouver des griffes de rôdeur"}},{q="Qui veut ces griffes et pourquoi ?",a="Sergra Darkthorn, une chasseresse expérimentée de La Croisée, veut sept Griffes de rôdeur. Les lui rapporter met à l’épreuve votre capacité à traquer et combattre de dangereux prédateurs.",al={"qui a besoin de griffes de rôdeur","rapporter les griffes de rôdeur","quête des griffes de sergra"}},{q="Pourquoi la chasse aux rôdeurs des savanes est-elle si importante ?",a="Les rôdeurs des savanes sont des carnivores furtifs qui traquent les voyageurs et leurs proies depuis les hautes broussailles. Les chasser met à l’épreuve votre capacité à éviter une embuscade et à vaincre une bête rusée et meurtrière.",al={"pourquoi chasser les rôdeurs","rôdeurs dangereux"}}},fx={["551eb0e2"]={q="Que sont les Griffes de rôdeur ?",a="Les Griffes de rôdeur sont les serres tranchantes comme des rasoirs prélevées sur les pattes des rôdeurs de savane, ces félins prédateurs mortels qui rôdent dans les hautes herbes des Tarides. Pour les chasseurs de La Croisée, récupérer ces trophées prouve que vous êtes capable de traquer et de vaincre une bête rusée et létale sans devenir vous-même une proie.",al={"que sont les griffes de rôdeur","objet griffes de rôdeur","au sujet des griffes de rôdeur"}},c8bad4fe={q="D'où viennent les Griffes de rôdeur ?",a="Ces griffes proviennent directement des rôdeurs de savane qui errent dans les plaines des Tarides, en particulier dans les prairies situées au sud-ouest de La Croisée. Ce sont des trophées naturels récoltés sur les cadavres des grands félins par des chasseurs assez qualifiés pour les abattre.",al={"d'où viennent les griffes de rôdeur","source des griffes de rôdeur","comment obtenir des griffes de rôdeur"}}},fp="13,154,23.425.0,22.323.0,29.143.0,30.170.0,56.179.0"}
P.entries["item:pulsing-blue-shard"] = {n="Pulsing Blue Shard",s="Les Pulsing Blue Shards sont des cristaux rares prélevés sur des Ironjaw Basilisks dans la Vallée de Strangleronce. Kin'weelay a besoin de leur magie pour contrôler la Vue de l'esprit.",h="Les Pulsing Blue Shards sont des cristaux rares prélevés sur des Ironjaw Basilisks dans la Vallée de...",kw={"éclats bleus","mine aux cristaux","ironjaw basilisk","kin'weelay","vue de l'esprit","pulsing blue shard","vallée de strangleronce","yenniku"},sec={{t="Un cristal chantant",b="Kin'weelay, un troll du Campement Grom'gol, vous demande de lui rapporter des Pulsing Blue Shards prélevés sur des Ironjaw Basilisks dans la Mine aux cristaux. Il a besoin de leur magie pour la Vue de l'esprit, un joyau réputé pour sa grande puissance."}},faq={{q="Que sont les Pulsing Blue Shards ?",a="Les Pulsing Blue Shards sont des cristaux rares prélevés sur des Ironjaw Basilisks dans la Vallée de Strangleronce. Leur magie peut aider Kin'weelay à contrôler la Vue de l'esprit.",al={"éclat bleu","cristal pulsant"}},{q="Qui a besoin des cristaux ?",a="Kin'weelay, au Campement Grom'gol, a besoin de Pulsing Blue Shards pour ses travaux sur la Vue de l'esprit.",al={"qui veut des éclats bleus","éclats de kin'weelay"}},{q="D'où viennent les cristaux ?",a="Les Ironjaw Basilisks de la Mine aux cristaux fournissent des Pulsing Blue Shards.",al={"où trouver des éclats","éclats de la mine aux cristaux"}},{q="Qu'est-ce que la Vue de l'esprit ?",a="La Vue de l'esprit est un joyau caché dans les profondeurs de la Vallée de Strangleronce, réputé pour sa grande puissance. Kin'weelay pense que les cristaux peuvent l'aider à soumettre sa magie à sa volonté.",al={"vue de l'esprit","cristaux chantants"}},{q="Pourquoi Kin'weelay les veut-il ?",a="Kin'weelay a besoin de la magie des cristaux pour contrôler la Vue de l'esprit, qu'il espère utiliser pour ramener Yenniku des ténèbres.",al={"pourquoi les éclats","à quoi servent les éclats"}}},fp="18,145,17.203.0,29.145.0,21.92.0,30.64.0,23.158.0,30.124.1"}
P.entries["item:pupellyverbos-port"] = {n="Porto Pupellyverbos",s="Une caisse de Porto Pupellyverbos est passée par-dessus bord près des Hinterlands pendant une tempête. Whiskey Slim, à Baie-du-Butin, a besoin de récupérer les bouteilles avant que le capitaine découvre leur disparition.",h="Une caisse de Porto Pupellyverbos est passée par-dessus bord près des Hinterlands pendant une tempête.",kw={"baie-du-butin","hinterlands","grog perdu","falaises du surplomb","corsaire","porto pupellyverbos","tempête","whiskey slim"},sec={{t="Perdu en mer",b="Au large des falaises du Surplomb, une tempête s’abattit sur le navire de Whiskey Slim. Le capitaine avait pris la caisse de Porto Pupellyverbos à un corsaire qui faisait route vers Hurlevent, et Whiskey Slim l’ouvrit pour se donner du courage tandis que les vagues enflaient. Une énorme vague emporta les bouteilles par-dessus bord. À présent, le grog est éparpillé le long du rivage, et Whiskey Slim redoute la colère du capitaine."}},faq={{q="Qu'est-ce que le Porto Pupellyverbos ?",a="Le Porto Pupellyverbos est le grog du capitaine, une caisse dont son équipage s’est emparé auprès d’un corsaire qui faisait route vers Hurlevent.",al={"pupellyverbos","de quel porto s'agit-il","alcool pupellyverbos"}},{q="Comment les bouteilles ont-elles été perdues ?",a="Une tempête près des falaises du Surplomb a fait déferler une immense vague sur le navire, qui a emporté les bouteilles en mer.",al={"où sont passées les bouteilles","comment le porto a-t-il été perdu","qu'est-il arrivé au grog"}},{q="Qui cherche le porto ?",a="Whiskey Slim, à Baie-du-Butin, veut récupérer les bouteilles perdues avant que le capitaine découvre leur disparition.",al={"qui veut l'alcool","bouteilles de whiskey slim","grog de slim"}},{q="D'où venait la caisse ?",a="L'équipage du capitaine s'est emparé de la caisse d'un corsaire qui se dirigeait vers Hurlevent.",al={"qui avait la caisse","origine du porto","alcool du corsaire"}}},fp="18,177,11.337.0,27.109.0,29.100.0,28.101.0,30.86.0"}
P.entries["item:pure-hearts"] = {n="Coeurs purs",s="À Fossoyeuse, les Coeurs purs attirent une succube depuis le Twisting Nether. Carendin Halgar fournit ces composants rituels aux démonistes réprouvés, qui les utilisent pour invoquer le démon et tenter de le vaincre et de le lier.",h="À Fossoyeuse, les Coeurs purs attirent une succube depuis le Twisting Nether.",kw={"carendin halgar","quartier de la magie","coeurs purs","succube","invocation","the binding","fossoyeuse"},ang={["class:Warlock"]="Pour un démoniste, utiliser les Coeurs purs marque un tournant dans la démonologie. Cela prouve votre force mentale face aux séductions du Twisting Nether.",["race:Undead"]="En tant que Mort-vivant, vous utilisez des coeurs immaculés pour manipuler les appétits démoniaques. Cette sorcellerie froide et pragmatique est caractéristique des Réprouvés."},sec={{t="Leurre pour le Néant",b="Carendin Halgar fournit des Coeurs purs aux démonistes qui invoquent une succube dans le Quartier de la Magie de Fossoyeuse. Ils déposent les essences spirituelles immaculées sur le cercle d'invocation. Les coeurs attirent le démon à travers le Twisting Nether jusque dans le royaume des mortels.\n\nDès qu'elle apparaît, le démoniste doit résister à ses charmes mentaux envoûtants et l'abattre. Vaincre la succube prouve sa domination mystique et la renvoie dans le Twisting Nether. Carendin apprend ensuite au démoniste le sort qui lui permet de l'invoquer à volonté."}},faq={{q="À quoi servent les Coeurs purs ?",a="Les Coeurs purs attirent une succube à travers le Twisting Nether et la font venir dans le royaume des mortels. Dans le Quartier de la Magie de Fossoyeuse, un démoniste peut l'affronter et la lier sur le cercle d'invocation.",al={"utilisation des coeurs purs","pourquoi les coeurs purs","à quoi servent les coeurs purs"}},{q="Qui fournit les Coeurs purs ?",a="Carendin Halgar, un maître démoniste réprouvé de Fossoyeuse, donne des Coeurs purs aux démonistes qui se préparent à invoquer une succube.",al={"qui donne les coeurs purs","donneur de quête des coeurs purs"}},{q="Pourquoi une succube réagit-elle aux Coeurs purs ?",a="Les succubes se nourrissent de corruption et de séduction. L'éclat des coeurs immaculés les attire à travers le Twisting Nether jusqu'au cercle d'invocation d'un démoniste.",al={"pourquoi la succube veut les coeurs purs","histoire des coeurs purs"}},{q="Peut-on garder les Coeurs purs après le rituel ?",a="Non. Une fois la succube invoquée et maîtrisée, les restes des Coeurs purs retournent à Carendin Halgar, preuve que l'épreuve de liaison est achevée.",al={"garder les coeurs purs","que deviennent les coeurs purs"}}},fx={["105bfa16"]={q="Que sont les Coeurs purs ?",a="Les Coeurs purs sont des composants rituels puissants utilisés par les démonistes Réprouvés à Fossoyeuse. Lorsqu'ils sont lancés sur un cercle d'invocation, leur essence pure agit comme un appât à travers le Néant distordu, ouvrant une faille spécifiquement conçue pour attirer et invoquer une succube dangereuse en votre présence.",al={"que sont les coeurs purs","objet coeurs purs","démoniste coeurs purs"}},["3abadf0f"]={q="Pourquoi quelqu'un voudrait-il les Coeurs purs ?",a="Un apprenti démoniste a besoin des Coeurs purs pour accomplir le dangereux rituel de lien d'une succube. Sans offrir un tel appât pur pour combler le vide, vous ne pouvez pas attirer le démon dans le royaume mortel pour la soumettre et maîtriser l'art de l'invoquer sous vos ordres.",al={"pourquoi vouloir des coeurs purs","but des coeurs purs","pourquoi les coeurs purs sont recherchés"}}},fp="11,206,19.499.0,34.183.0,29.123.0,43.149.0,52.151.0"}
P.entries["item:purified-kor-gem"] = {n="Gemme de Kor purifiée",s="À la forge de Jordan Morpuits, près de Forgefer, une Gemme de Kor purifiée est nécessaire pour façonner une arme de la Lumière. D’abord, la magie elfique doit purifier la pierre corrompue.",h="À la forge de Jordan Morpuits, près de Forgefer, une Gemme de Kor purifiée est nécessaire pour façonner une...",kw={"auberdine","profondeurs de brassenoire","gemme de kor corrompue","dun morogh","jordan morpuits","gemme de kor purifiée","épreuve de la droiture","thundris windweaver"},ang={["class:Paladin"]="En tant que paladin, vous prouvez votre dévotion en obtenant cette gemme et en la purifiant. Puis vous la transportez de Kalimdor à Dun Morogh, où elle contribue à forger une arme de la Lumière.",["faction:Alliance"]="En tant que membre de l’Alliance, vous comptez sur la sagesse des Elfes de la nuit à Auberdine pour aider un forgeron humain sur les pentes de Dun Morogh."},sec={{t="De la corruption à la consécration",b="Les nagas détiennent la Gemme de Kor corrompue dans les Profondeurs de Brassenoire, sous la côte d’Orneval. Un paladin la porte à Thundris Tissevent, un Elfe de la nuit à Auberdine. Là, Thundris fait appel aux arts des arcanes et de la nature pour la purger de ses souillures aquatique et ténébreuse. La pierre ressort purifiée, prête à canaliser la puissance sacrée."},{t="Le chef-d’œuvre du forgeron",b="Jordan Morpuits, un fabricant d’armes humain près de Forgefer, a besoin de la gemme pour une arme de maître. Il a depuis longtemps conçu les plans d’une arme digne de la Main d’argent, mais il lui manquait les matériaux rares nécessaires à sa forge. La Gemme de Kor purifiée, le Bois de chêne de blanchepierre et un minerai rare donnent à l’arme son cœur spirituel, afin qu’elle canalise le courroux vertueux d’un paladin."}},faq={{q="À quoi sert la Gemme de Kor purifiée ?",a="La gemme est destinée à Jordan Morpuits, le forgeron près de Forgefer, à Dun Morogh. Il s’en sert pour forger une arme consacrée pour un paladin qui accomplit ses épreuves.",al={"utilité de la gemme de kor purifiée","pourquoi ai-je besoin de la gemme de kor","à quoi sert la gemme de kor"}},{q="D’où vient la gemme ?",a="Les nagas détiennent la pierre corrompue dans les Profondeurs de Brassenoire, sous la côte d’Orneval.",al={"origine de la gemme de kor","où obtenir la gemme de kor","qui donne la gemme de kor"}},{q="Qui purifie la gemme ?",a="Thundris Tissevent, un Elfe de la nuit à Auberdine, purifie la Gemme de Kor corrompue et lui rend son état purifié.",al={"comment purifier la gemme de kor","qui purifie la gemme de kor","thundris tissevent et la gemme de kor"}},{q="Tout aventurier peut-il utiliser la Gemme de Kor purifiée ?",a="Les paladins qui accomplissent l’Épreuve de la droiture recherchent la gemme. Jordan Morpuits forge des armes pour les guerriers sacrés qui lui apportent le cristal purifié et d’autres matériaux rares.",al={"la gemme de kor est-elle réservée aux paladins","tout le monde peut-il utiliser la gemme de kor purifiée"}}},fx={a30b14db={q="Qu'est-ce qu'une Gemme de Kor purifiée ?",a="La Gemme de Kor purifiée est un composant minéral rare et sanctifié, nettoyé de toute corruption immonde. Récupérée à l'origine en tant que pierre corrompue détenue par les naga dans les Profondeurs de Brassenoire, elle a été soigneusement purifiée de son influence obscure par Thundris Windweaver à Auberdine afin que ses propriétés latentes puissent être utilisées en toute sécurité pour des travaux sacrés.",al={"qu'est-ce qu'une gemme de kor purifiée","signification gemme de kor purifiée","informations gemme de kor purifiée"}}},fp="16,161,27.299.0,23.338.0,38.161.0,29.83.0,21.114.0,52.161.0"}
P.entries["item:putrid-claw"] = {n="Griffe putride",s="Près de Brill, les primes pour les Griffes putrides aident à contenir le Fléau. Des morts-vivants décérébrés rôdent dans les bois à l'ouest de la ville, surtout près du vieux pont, et le Nécrogarde Dillinger récupère leurs griffes comme preuve.",h="Près de Brill, les primes pour les Griffes putrides aident à contenir le Fléau.",kw={"a putrid task","brill","nécrogarde dillinger","griffe putride","cadavre ravagé","mort décomposé","fléau","clairières de tirisfal"},ang={["race:Undead"]="En quittant Le Glas comme nouvelle recrue réprouvée, vous découvrez que la liberté implique de vous défendre contre les carcasses décérébrées auxquelles vous ressembliez autrefois."},sec={{t="Trophée des décérébrés",b="Le Fléau décérébré continue de pénétrer dans les Clairières de Tirisfal. Des morts décomposés et des cadavres ravagés errent aux frontières orientales, se regroupant le long des routes et près du vieux pont à l'ouest de Brill. Les gardes noirs offrent des primes pour ces horreurs afin de protéger les voyageurs et les lignes de ravitaillement de la garnison. Une griffe putride tranchée prouve qu'un cadavre traînant de plus a été éliminé pour de bon."}},faq={{q="À quoi servent les griffes putrides ?",a="Le Nécrogarde Dillinger, à Brill, récupère les griffes putrides en échange de primes. Elles prouvent que les recrues réprouvées locales réduisent les rangs du Fléau qui rôde dans les Clairières de Tirisfal.",al={"utilisation des griffes putrides","pourquoi récupérer les griffes putrides","qui veut des griffes putrides"}},{q="D'où viennent les griffes putrides ?",a="Les griffes putrides proviennent des morts décomposés et des cadavres ravagés qui rôdent dans les bois hantés à l'ouest de Brill, surtout près du vieux pont sur la rivière.",al={"où trouver des griffes putrides","butin de griffe putride","butin de mort décomposé"}},{q="Pourquoi le Fléau se trouve-t-il dans les Clairières de Tirisfal ?",a="Après la dévastation de Lordaeron, des vestiges du Fléau décérébré du roi-liche continuent de pénétrer à l'ouest, dans les Clairières de Tirisfal. Ils menacent les routes et les villages si personne ne les élimine.",al={"pourquoi des zombies près de brill","fléau dans les clairières de tirisfal"}},{q="Pourquoi les Réprouvés ne laissent-ils pas simplement les morts-vivants décérébrés errer ?",a="La reine Sylvanas et les Réprouvés se sont libérés de l'emprise du roi-liche et ont retrouvé leur volonté. Le Fléau décérébré obéit à de sombres instincts ou aux ordres persistants du roi-liche, attaquant à vue tous les vivants et les morts-vivants libres.",al={"réprouvés contre zombies décérébrés","pourquoi tuer d'autres morts-vivants"}}},fx={["37750c4d"]={q="Qu'est-ce qu'une Griffe putride ?",a="Une Griffe putride est la main coupée et en décomposition d'un zombie sans esprit appartenant au Fléau. Ces appendices en putréfaction sont prélevés sur les cadavres ambulants qui hantent les Clairières de Tirisfal comme preuve de leur destruction.",al={"qu'est-ce qu'une griffe putride","informations griffes putrides","histoire griffe putride"}}},fp="11,191,22.354.0,31.155.0,32.140.0,38.170.0,59.205.0"}
P.entries["item:pyrewood-shackle"] = {n="Chaîne de Bois-du-Bûcher",s="À Bois-du-Bûcher, des entraves enchantées lient les habitants à l’étrange magie de l’archimage Arugal. La nuit venue, un sombre destin les attend.",h="À Bois-du-Bûcher, des entraves enchantées lient les habitants à l’étrange magie de l’archimage Arugal.",kw={"arugal","tisselaube","rage-sauvage","bois-du-bûcher","le sépulcre","entrave","forêt des pins-argentés","worgen"},ang={["class:Mage"]="En tant que mage, vous pouvez reconnaître la magie de transmutation inconsidérée et les sortilèges contraignants tissés dans de l’acier ordinaire.",["race:Undead"]="En tant que Réprouvés, vous savez que la sorcellerie débridée d’Arugal menace vos frontières. Recueillir ces entraves enchantées est essentiel pour neutraliser l’influence du Donjon d’Ombrecroc."},sec={{t="La magie contraignante d’Arugal",b="Le jour, les habitants de Bois-du-Bûcher vivent sous forme humaine, puis deviennent au coucher du soleil de féroces worgens Rage-sauvage. L’archimage Arugal les a liés par des entraves enchantées lors de ses expériences de sorcellerie worgen. Au Sépulcre, Dalar Tisselaube, chercheur des arcanes chez les Réprouvés, étudie ces entraves. Il en recueille l’énergie persistante pour découvrir l’effet des enchantements, comprendre la magie d’Arugal et desserrer l’emprise du fou archimage sur la région."}},faq={{q="À quoi servent les entraves de Bois-du-Bûcher ?",a="Au Sépulcre, Dalar Tisselaube étudie les enchantements des entraves. Il espère démêler les sorts de l’archimage Arugal et démanteler son influence dans la Forêt des Pins-Argentés.",al={"utilité des entraves de bois-du-bûcher","pourquoi recueillir les entraves","entraves de dalar tisselaube"}},{q="Qui porte ces entraves ?",a="Les habitants maudits de Bois-du-Bûcher, dans le sud de la Forêt des Pins-Argentés, portent ces entraves. Ils les portent sous forme humaine le jour et sous forme de worgens Rage-sauvage la nuit.",al={"qui abandonne les entraves de bois-du-bûcher","source des entraves","où trouver les entraves de bois-du-bûcher"}},{q="Pourquoi les villageois se transforment-ils la nuit ?",a="Les expériences inconsidérées et les enchantements de l’archimage Arugal ont fait que les habitants de Bois-du-Bûcher se transforment la nuit. Les entraves renferment un enchantement qui leur donne l’apparence d’humains ordinaires à la lumière du jour, tandis que l’obscurité révèle leur forme féroce de worgen.",al={"pourquoi bois-du-bûcher se transforme en worgen","malédiction de bois-du-bûcher","secret des loups-garous de bois-du-bûcher"}},{q="Qui est Dalar Tisselaube ?",a="Dalar Tisselaube est un mage réprouvé au Sépulcre, dans la Forêt des Pins-Argentés. Il étudie les anomalies arcaniques laissées par l’archimage Arugal et cherche à briser les malédictions de l’archimage.",al={"dalar tisselaube","qui est dalar"}}},fx={b92f5faa={q="Qu'est-ce qu'une Chaîne de Bois-du-Bûcher ?",a="Une Chaîne de Bois-du-Bûcher est une entrave enchantée liée aux malheureux habitants de Bois-du-Bûcher, dans le sud de la Forêt des Pins-Argentés. Imprégnées de l'étrange sorcellerie imprudente de l'Archimage Arugal, ces chaînes jouent un rôle direct dans la soumission des citadins à sa volonté et dans le masquage de la sombre malédiction qui les afflige.",al={"chaîne de bois-du-bûcher","que sont les chaînes de bois-du-bûcher","chaînes de bois-du-bûcher"}},f6bcbb50={q="D'où vient une Chaîne de Bois-du-Bûcher et qui l'a fabriquée ?",a="Ces chaînes enchantées ont été forgées et placées sur les villageois par l'Archimage Arugal, le mage renégat de Dalaran qui a élu domicile au Donjon d'Ombrecroc. Arugal a jeté ces chaînes sur les paysans de Bois-du-Bûcher dans le cadre de ses enchantements corrompus, les gardant sous sa coupe tout en dissimulant leur transformation lupine sous une illusion de vie humaine ordinaire durant la journée.",al={"qui a fabriqué les chaînes de bois-du-bûcher","origine chaîne de bois-du-bûcher","d'où viennent les chaînes"}},["98d012f7"]={q="Pourquoi quelqu'un voudrait-il des Chaînes de Bois-du-Bûcher ?",a="Dalar Tisselaube, un mage Réprouvé ambitieux menant des recherches au Sépulcre, recherche ces chaînes enchantées pour étudier la magie d'Arugal. En puisant dans leur énergie résiduelle, Dalar espère percer le mystère de l'enchantement bizarre qui fait apparaître les villageois comme humains le jour et se transformer en worgens Moonrage affamés après le crépuscule, cherchant ultimement à démanteler les sorts d'Arugal.",al={"pourquoi collecter des chaînes de bois-du-bûcher","qui a besoin de chaînes de bois-du-bûcher","but de la chaîne de bois-du-bûcher"}}},fp="16,141,22.410.1,36.176.0,27.155.1,40.234.1,24.167.0"}
P.entries["item:quinn-s-potion"] = {n="Potion de Quinn",s="Au Sépulcre, l’Apothicaire Renferrel prépare la Potion de Quinn pour un éclaireur blessé. Quinn Yorick en a besoin après une patrouille désastreuse dans la Forêt des Pins-Argentés.",h="Au Sépulcre, l’Apothicaire Renferrel prépare la Potion de Quinn pour un éclaireur blessé.",kw={"apothicaire renferrel","deathstalker","le lopin d'ivar","quinn yorick","potion de quinn","le sépulcre","forêt des pins-argentés"},ang={["race:Undead"]="En tant que Réprouvé, vous savez que la Société royale des apothicaires consacre rarement des efforts aux simples remèdes de terrain, sauf s’ils aident à préserver les éclaireurs qui gardent les frontières de la Forêt des Pins-Argentés."},sec={{t="Le remède de Renferrel",b="L’Apothicaire Renferrel prépare un remède pour le Deathstalker Quinn Yorick. La Société royale des apothicaires a appris au Sépulcre que Quinn avait été grièvement blessé près du lopin d’Ivar et ne pouvait plus bouger. Renferrel a préparé cette potion pour l’aider à se rétablir.\n\nLes blessures mineures sur le terrain détournent rarement Renferrel de ses recherches plus sinistres pour dame Sylvanas. Il a tout de même fourni le remède afin que Quinn reprenne assez de forces pour voyager."}},faq={{q="À quoi sert la Potion de Quinn ?",a="La Potion de Quinn aide le Deathstalker Quinn Yorick à se remettre de ses blessures dans le nord de la Forêt des Pins-Argentés. Elle lui rend assez de forces pour qu’il puisse voyager à nouveau.",al={"utilité de la potion de quinn","effet de la potion de quinn","pourquoi préparer la potion de quinn"}},{q="Qui a préparé cette potion ?",a="L’Apothicaire Renferrel, alchimiste de la Société royale des apothicaires affecté aux cryptes du Sépulcre, a préparé cette potion.",al={"qui a préparé la potion de quinn","qui l’a préparée","potion de renferrel"}},{q="Où faut-il livrer la potion ?",a="Portez la potion au nord du Sépulcre, à Quinn Yorick, qui se réfugie près de la ferme appelée le lopin d’Ivar.",al={"où apporter la potion","emplacement de quinn","où trouver quinn yorick"}},{q="Pourquoi Quinn Yorick avait-il besoin d’une potion ?",a="Quinn patrouillait dans le nord de la Forêt des Pins-Argentés avec une patrouille de Deathstalkers. Au lopin d’Ivar, le goule Ivar the Foul a attaqué les éclaireurs, laissant Quinn grièvement blessé et immobilisé.",al={"pourquoi quinn est blessé","que s’est-il passé pour quinn yorick","quinn blessé"}}},fx={["52098f03"]={q="Qu'est-ce que la Potion de Quinn ?",a="Il s'agit d'une décoction réparatrice préparée par l'Apothicaire Renferrel au Sépulcre. Formulée spécifiquement pour aider le scout blessé Quinn Yorick, le breuvage lui donne la force dont il a besoin pour se remettre de ses blessures et retrouver assez de mobilité pour voyager.",al={"potion de quinn","qu'est-ce que cette potion","qu'est-ce que le breuvage de quinn"}}},fp="14,154,16.415.0,32.156.0,23.123.0,43.109.0,41.169.0"}
P.entries["item:rackmore-s-golden-key"] = {n="Rackmore's Golden Key",s="Sur l’Ile de Ranazjar, la clé d’or de Rackmore ouvre le coffre où un marin a caché son trésor. Les nagas Slitherblade gardent la clé parmi les vestiges épars de son voyage.",h="Sur l’Ile de Ranazjar, la clé d’or de Rackmore ouvre le coffre où un marin a caché son trésor.",kw={"désolace","clé d’or","rackmore","clé d’or de rackmore","ile de ranazjar","nagas slitherblade","trésor"},sec={{t="La cache d’un marin",b="Le journal de Rackmore raconte que son navire faisait route vers le Bastion de Pennelune lorsque des créatures marines l’attaquèrent. Pour leur soustraire son trésor, il cacha un coffre sur l’Ile de Ranazjar. Il faut deux clés pour l’ouvrir, une en argent et une en or. Les nagas Slitherblade détiennent la clé d’or, tandis qu’il faut aussi trouver la clé d’argent de Rackmore."}},faq={{q="Qu’ouvre la clé d’or de Rackmore ?",a="La clé d’or de Rackmore ouvre le coffre caché sur l’Ile de Ranazjar, avec la clé d’argent de Rackmore.",al={"clé d’or","clé de rackmore","à quoi sert la clé d’or"}},{q="Où se trouve le coffre au trésor de Rackmore ?",a="Rackmore a caché son coffre sur l’Ile de Ranazjar après l’attaque de son navire par des créatures marines.",al={"emplacement du coffre de rackmore","où se trouve le coffre","trésor de ranazjar"}},{q="Qui détient la clé d’or ?",a="Les nagas Slitherblade de Désolace détiennent la clé d’or de Rackmore.",al={"qui détient la clé de rackmore","clé des nagas","clé des slitherblade"}},{q="Pourquoi Rackmore a-t-il caché son trésor ?",a="Rackmore a caché le coffre pour soustraire son trésor aux créatures marines qui avaient attaqué son navire.",al={"pourquoi cacher le coffre","histoire du trésor de rackmore","pourquoi le trésor est-il caché"}}},fp="21,173,18.317.0,39.103.0,37.84.0,23.63.0,35.96.0"}
P.entries["item:rackmore-s-silver-key"] = {n="Rackmore's Silver Key",s="Rackmore’s Silver Key a été perdue parmi les makruras de Désolace. Ceux qui cherchent le trésor caché de Rackmore la convoitent.",h="Rackmore’s Silver Key a été perdue parmi les makruras de Désolace.",kw={"désolace","drysnap crawler","drysnap pincer","clé en or","rackmore","rackmore’s chest","rackmore’s silver key","ile de ranazjar","clé d’argent"},sec={{t="La clé perdue",b="Le journal de Rackmore raconte que son navire faisait route vers le Bastion de Pennelune quand des créatures marines l’attaquèrent. Pour protéger son trésor des ennemis, il cacha le coffre sur l’Ile de Ranazjar. La clé d’argent fut perdue, et le coffre reste verrouillé jusqu’à ce qu’on la retrouve avec son équivalent en or."}},faq={{q="Que permet d’ouvrir Rackmore’s Silver Key ?",a="Rackmore’s Silver Key est l’une des deux clés nécessaires pour ouvrir Rackmore’s Chest sur l’Ile de Ranazjar. L’autre est la clé en or.",al={"utilité de la clé d’argent","ce que la clé ouvre","clé de rackmore"}},{q="Où trouver Rackmore’s Silver Key ?",a="Les Drysnap Pincers et les Drysnap Crawlers de Désolace portent Rackmore’s Silver Key.",al={"emplacement de la clé d’argent","où trouver la clé","trouver rackmore’s silver key"}},{q="Qui était Rackmore ?",a="Rackmore était le propriétaire d’un coffre au trésor caché sur l’Ile de Ranazjar après l’attaque de son navire.",al={"histoire de rackmore","qui est rackmore","rackmore"}},{q="Pourquoi le trésor de Rackmore est-il caché ?",a="Rackmore a caché son coffre sur l’Ile de Ranazjar pour empêcher que son trésor ne tombe entre les mains des créatures qui avaient attaqué son navire.",al={"pourquoi le coffre est caché","pourquoi le trésor de rackmore","trésor caché"}},{q="Qu’est-il arrivé au navire de Rackmore ?",a="Le journal de Rackmore raconte que des créatures marines attaquèrent son navire alors qu’il faisait route vers le Bastion de Pennelune.",al={"navire attaqué","navire de rackmore","qu’est-il arrivé au navire"}}},fp="21,126,12.282.0,39.123.0,41.79.0,17.95.0,36.129.0,35.108.0"}
P.entries["item:rage-scar-yeti-hide"] = {n="Rage Scar Yeti Hide",s="La peau de yéti Rage Scar Yeti Hide provient des yétis du Repaire des Griffes féroces, au nord de Féralas. Pratt McGrubben et Jangdor Swiftstrider recherchent ces peaux pour leur travail du cuir.",h="La peau de yéti Rage Scar Yeti Hide provient des yétis du Repaire des Griffes féroces, au nord de Féralas.",kw={"féralas","jangdor swiftstrider","cuir","pratt mcgrubben","repaire des griffes féroces","rage scar yeti hide","rage scar yetis","peau de yéti"},sec={{t="Une meilleure peau",b="Au nord de Féralas, les peaux des yétis du Repaire des Griffes féroces sont très prisées des travailleurs du cuir. Pratt McGrubben, au Bastion de Pennelune, et Jangdor Swiftstrider, au Camp Mojache, en recherchent chacun dix pour leur travail. Ils espèrent qu’une fois traitées, ces peaux se révéleront aussi résistantes que le thorium."}},faq={{q="D’où viennent les peaux de yéti Rage Scar Yeti Hide ?",a="Les peaux de yéti Rage Scar Yeti Hide proviennent des yétis du Repaire des Griffes féroces, au nord de Féralas.",al={"où trouver une peau de yéti","origine de rage scar yeti hide"}},{q="Qui veut ces peaux ?",a="Pratt McGrubben, au Bastion de Pennelune, et Jangdor Swiftstrider, au Camp Mojache, recherchent tous deux des peaux de yéti Rage Scar Yeti Hide.",al={"qui veut ces peaux","pour qui sont les peaux"}},{q="Pourquoi ces peaux ont-elles de la valeur ?",a="Une fois traitée, la peau pourrait se révéler exceptionnellement résistante, ce qui la rend prometteuse pour le travail du cuir.",al={"pourquoi vouloir des peaux de yéti","qualité de la peau"}},{q="Combien de peaux faut-il ?",a="Pratt McGrubben et Jangdor Swiftstrider demandent chacun dix peaux de yéti Rage Scar Yeti Hide.",al={"combien","dix peaux"}}},fp="19,164,13.267.0,40.80.0,22.114.0,27.93.0,26.79.0"}
P.entries["item:ran-bloodtooth-s-skull"] = {n="Crâne de Ran Dent-rouge",s="En Orneval, le Crâne de Ran Dent-rouge parvient aux elfes de la nuit d’Astranaar, preuve qu’une terrible menace a été vaincue.",h="En Orneval, le Crâne de Ran Dent-rouge parvient aux elfes de la nuit d’Astranaar, preuve qu’une terrible...",kw={"orneval","astranaar","crâne de bloodtooth","bloodtooth","furbolg","raene mène-loup","purification de raene","ran bloodtooth"},ang={["faction:Alliance"]="Rapporter ce sinistre trophée témoigne de la valeur des champions de l’Alliance qui défendent les fragiles frontières d’Orneval aux côtés des Sentinelles.",["race:NightElf"]="Pour les elfes de la nuit, ce crâne marque une victoire solennelle et honore la tâche inachevée de Teronis. Il rappelle aussi combien la corruption démoniaque a ravagé leurs anciens alliés furbolgs."},sec={{t="Un trophée pour la défense d’Orneval",b="La souillure démoniaque et la corruption de la nature sauvage ont plongé les furbolgs d’Orneval dans une folie meurtrière. Ran Bloodtooth menait l’une des tribus les plus féroces. Son crâne prouve aux Sentinelles elfes de la nuit qu’il est tombé et que son emprise sur les furbolgs des environs est brisée. Astranaar connaît un peu de répit."},{t="Honorer les défunts",b="À Astranaar, la sentinelle Raene Mène-loup reçoit le Crâne de Ran Dent-rouge. Il marque la fin d’une enquête commencée par l’éclaireur défunt Teronis. À côté du crâne repose Dartol's Rod, reconstitué après le départ de Teronis pour le retrouver. Ensemble, le crâne et le bâton honorent ceux qui ont combattu pour préserver la forêt sacrée."}},faq={{q="Qui était Ran Bloodtooth ?",a="Ran Bloodtooth dirigeait une tribu de furbolgs corrompus en Orneval. Les Sentinelles elfes de la nuit le comptaient parmi les menaces les plus féroces de la région.",al={"qui est ran bloodtooth","histoire de ran bloodtooth","qui était bloodtooth"}},{q="Pourquoi les Sentinelles veulent-elles son crâne ?",a="À Astranaar, Raene Mène-loup reçoit le Crâne de Ran Dent-rouge, preuve qu’il est tombé. Il repose à côté de Dartol's Rod en mémoire de ceux qui ont péri en défendant Orneval.",al={"pourquoi ai-je besoin du crâne","crâne de raene mène-loup","à quoi sert le crâne"}},{q="Qui était Teronis ?",a="Teronis était un ami de longue date de Raene Mène-loup et un allié des Sentinelles en Orneval. Il cherchait une gemme pour un bâton créé par le magicien défunt Dartol, dans l’espoir de ralentir les attaques des furbolgs. Des murlocs l’ont tué au lac Falathim. Raene Mène-loup et des aventuriers de passage ont alors repris sa tâche.",al={"histoire de teronis","qui est teronis","teronis astranaar"}}},fx={["4d0a3ce4"]={q="Qu'est-ce que le Crâne de Ran Dent-rouge ?",a="Il s'agit du crâne coupé de Ran Dent-rouge, l'une des menaces furbolg corrompues les plus féroces et les plus dangereuses rôdant à Orneval. Pris comme preuve de sa défaite, il marque la fin de la terreur qu'il faisait régner contre les Sentinelles et la forêt.",al={"crâne de ran dent-rouge","qu'est-ce que le crâne de ran","tête de ran dent-rouge"}},f5c7858d={q="D'où vient le Crâne de Ran Dent-rouge ?",a="Le crâne est récupéré directement sur Ran Dent-rouge après l'avoir tué à Orneval. Ce n'est pas un artefact forgé ou fabriqué par des mains mortelles, mais plutôt le sombre trophée récolté sur le chef lui-même.",al={"d'où vient le crâne de ran","qui a fabriqué le crâne de ran dent-rouge","source du crâne de ran dent-rouge"}}},fp="22,115,31.284.0,19.305.1,23.136.0,36.164.0,16.287.0"}
P.entries["item:ransom-letter"] = {n="Ransom Letter",s="La Lettre de rançon est une menace des voleurs qui détiennent le livre de Narain à Tanaris. Ses mots découpés et collés réclament de l'argent et un rendez-vous en tête à tête.",h="La Lettre de rançon est une menace des voleurs qui détiennent le livre de Narain à Tanaris.",kw={"gnome","narain","psychique","rançon","lettre de rançon","demande de rançon","livre volé","tanaris"},ang={["race:Gnome"]="En tant que gnome, vous reconnaîtrez peut-être la fierté que Narain tire de ses dons psychiques. Le livre volé et la menace de rançon le mettent en fureur."},sec={{t="Une menace découpée",b="La disparition du livre de Narain entraîne une demande de rançon à Tanaris. Les mots de la lettre sont découpés dans différentes polices et collés sur du parchemin. Elle promet que le livre sera rendu si les exigences sont satisfaites, puis détaille les instructions sur trois pages. Le message s'achève sur un ordre sans détour : apportez l'argent et venez seul."},{t="La colère de Narain",b="Quand Narain lit la lettre de rançon, son visage devient rouge vif. Le gnome jure d'apprendre aux ravisseurs ce que signifie s'en prendre à un télépathe. Son livre volé est devenu une source de colère autant qu'une affaire d'argent."}},faq={{q="Qui a écrit la lettre de rançon ?",a="La lettre ne nomme pas son auteur. Elle dit que les ravisseurs détiennent le livre de Narain et réclame de l'argent en échange.",al={"auteur de la lettre","qui l'a envoyée","auteur de la demande de rançon"}},{q="À qui appartenait le livre volé ?",a="Le livre appartient à Narain, un gnome de Tanaris.",al={"à qui appartient le livre","livre de narain","livre volé"}},{q="Que réclame la lettre ?",a="Les ravisseurs réclament de l'argent et ordonnent au destinataire de venir seul.",al={"que veulent-ils","demande de rançon","apporter l'argent"}},{q="Pourquoi la lettre est-elle composée de mots découpés ?",a="Son texte est composé de mots de différentes polices collés sur du parchemin. La lettre n'explique pas ce choix.",al={"lettre de rançon avec différentes polices","lettre découpée et collée","lettre étrange"}},{q="Comment Narain réagit-il ?",a="Le visage de Narain devient rouge vif et il jure de donner une leçon aux ravisseurs.",al={"narain en colère","réaction du gnome","que dit narain"}}},fp="13,141,16.325.0,16.207.1,28.116.0,22.47.0,28.66.0,42.107.0,22.79.1"}
P.entries["item:raptor-head"] = {n="Tête de raptor",s="À La Croisée, les Têtes de raptor répondent à la prime de Gazrog. La paie des gardes a disparu d’une tour de guet, et un raptor sauvage a été pris dans le vol.",h="À La Croisée, les Têtes de raptor répondent à la prime de Gazrog.",kw={"tarides","la croisée","gazrog","tête de raptor","raptor thieves","argent volé","sunscale"},ang={["class:Hunter"]="Traquer les Sunscale raptors dans les broussailles arides des Tarides met vos talents à l’épreuve face aux chasseurs en meute les plus agressifs et rusés de la savane.",["faction:Horde"]="La Croisée est au cœur des déplacements de la Horde dans le centre de Kalimdor. Éliminer les prédateurs voleurs aide à protéger les provisions et la paie de la garnison."},sec={{t="Prime de La Croisée",b="Un coffre contenant la paie des gardes a été volé dans la tour de guet de La Croisée, privant ses défenseurs de leur argent. À leur grande incrédulité, ils ont surpris un raptor sauvage en plein vol. Gazrog offre désormais une prime pour les reptiles rusés qui rôdent dans les Tarides. Rapportez leurs têtes tranchées à l’avant-poste, et ces prédateurs pourront être éliminés avant qu’ils ne dérobent d’autres provisions de la Horde."}},faq={{q="Pourquoi Gazrog veut-il des têtes de raptor ?",a="Un coffre contenant l’argent destiné aux gardes de La Croisée a été volé dans leur tour. À la stupeur générale, un raptor a été pris en flagrant délit. Gazrog veut que ces bêtes soient traquées dans les Tarides afin qu’elles ne puissent plus piller le campement.",al={"pourquoi ramasser des têtes de raptor","gazrog et les raptors","prime pour les têtes de raptor"}},{q="Pourquoi des raptors sauvages voleraient-ils de l’argent ?",a="Gazrog admet qu’il ignore pourquoi des bêtes sauvages voudraient des pièces de métal. Les raptors de Kalimdor sont réputés pour leur intelligence inquiétante. Ce vol a humilié les gardes de La Croisée, qui réclament vengeance.",al={"pourquoi les raptors veulent de l’argent","raptors qui volent des pièces","mystère des raptors voleurs"}},{q="Quels raptors donnent ces têtes ?",a="Les têtes proviennent des Sunscale raptors qui parcourent le centre et le sud des Tarides, notamment les Sunscale Lashtails, les Screechers et les Scytheclaws. Des bêtes redoutées comme Ishamuhale et Takk the Leaper en donnent aussi.",al={"où trouver des têtes de raptor","quels raptors donnent des têtes","raptors des tarides"}},{q="Que se passe-t-il après avoir rapporté les têtes ?",a="Après que Gazrog a reçu douze têtes et que la menace des raptors a diminué, il faut retrouver la destination de l’expédition d’argent volée.",al={"que faire après les raptors voleurs","après avoir ramassé des têtes de raptor"}}},fx={f6102aac={q="Qu'est-ce qu'une Tête de raptor ?",a="Une Tête de raptor est le trophée et la preuve de prime prélevés sur les raptors qui errent dans les Tarides, y compris les meutes locales Sunscale et les bêtes notoires comme Ishamuhale ou Takk le Sauteur. Les autorités de La Croisée exigent ces jetons macabres comme preuve vérifiable que les prédateurs rusés qui troublent leurs lignes de ravitaillement et leurs gardes ont été abattus.",al={"qu'est-ce qu'une tête de raptor","objet tête de raptor","que sont les têtes de raptor"}},["377da5ba"]={q="D'où vient une Tête de raptor ?",a="Ces têtes proviennent directement des raptors prédateurs qui traquent les savanes et les crêtes des Tarides. Les Sunscale Lashtails, Screechers, Scytheclaws, ainsi que des chasseurs notables à travers les plaines, les fournissent une fois abattus. En tant que restes biologiques récoltés sur le terrain, elles ne sont fabriquées par personne, mais plutôt revendiquées comme trophées d'une chasse réussie.",al={"d'où viennent les têtes de raptor","origine tête de raptor","qui a fabriqué la tête de raptor"}}},fp="11,150,24.355.0,34.228.0,36.207.0,32.207.0,40.139.0"}
P.entries["item:rare-earth"] = {n="Terre rare",s="À Dolanaar, la Terre rare attend un voyageur en route vers le camp de Denalan, près du lac Al'Ameth. Cette terre vient de Darnassus pour ses expériences botaniques sur Teldrassil.",h="À Dolanaar, la Terre rare attend un voyageur en route vers le camp de Denalan, près du lac Al'Ameth.",kw={"darnassus","denalan","dolanaar","herboristerie","lac al'ameth","terre rare","syral feuillelame"},ang={["profession:Herbalism"]="En tant qu'herboriste, vous pouvez vous tourner vers Syral Feuillelame et Denalan, qui étudient comment une terre particulière modifie la croissance et les propriétés des jeunes pousses de Teldrassil.",["race:NightElf"]="En tant qu'elfe de la nuit qui veille sur le jeune Arbre-Monde, vous pouvez voir comment les expériences menées au lac Al'Ameth révèlent les façons dont la vie s'adapte aux ramures sauvages de Teldrassil."},sec={{t="Terre de Darnassus",b="La Terre rare est arrivée en retard à Dolanaar, en provenance de Darnassus. Denalan, un botaniste excentrique installé sur la rive est du lac Al'Ameth, l'a demandée pour étudier les plantes du jeune écosystème de Teldrassil. L'herboriste Syral Feuillelame confie maintenant la terre aux voyageurs qui se dirigent vers le sud. Elle espère qu'elle parviendra à Denalan avant que ses propriétés ne s'estompent."}},faq={{q="À quoi sert la Terre rare ?",a="Au lac Al'Ameth, Denalan utilise la Terre rare dans ses expériences botaniques. Il cultive les plantes indigènes de Teldrassil avec des composés minéraux et des terres enrichies de Darnassus.",al={"utilité de la terre rare","que fait denalan avec la terre rare","but de la terre rare"}},{q="Qui envoie la Terre rare à Denalan ?",a="L'herboriste Syral Feuillelame détient le paquet à Dolanaar. Il est arrivé en retard de Darnassus, et elle demande aux voyageurs qui se dirigent vers le sud, en direction du lac Al'Ameth, de le porter à Denalan.",al={"qui donne la terre rare","où trouver la terre rare","paquet de syral feuillelame"}},{q="Pourquoi Denalan s'inquiétait-il de la livraison ?",a="L'envoi a pris du retard en chemin vers Dolanaar, laissant Denalan attendre près du lac. À son arrivée, il craint que la terre ait perdu la fraîcheur nécessaire à ses expériences.",al={"la terre rare est-elle abîmée","terre fraîche pour denalan","pourquoi la terre est-elle en retard"}}},fx={e720b4cb={q="Qu'est-ce que la Terre rare ?",a="La Terre rare est une cargaison de sol fertile, spécialement sélectionnée et expédiée depuis Darnassus. Elle est soigneusement préparée et conditionnée pour des recherches agricoles et botaniques sensibles, conservant des nutriments spécialisés qui nécessitent une livraison fraîche pour maintenir son efficacité pour des expériences de culture délicates.",al={"qu'est-ce que la terre rare","objet terre rare","histoire terre rare"}},["5312d2a9"]={q="Pourquoi Denalan veut-il la Terre rare ?",a="Denalan est un chercheur herboriste stationné sur les rives orientales du lac Al'Ameth, étudiant et expérimentant la flore locale de Teldrassil. Il compte sur ce sol rare et riche en nutriments provenant de Darnassus pour nourrir ses plantations délicates et faire progresser ses travaux botaniques sur l'île.",al={"pourquoi denalan veut-il de la terre rare","pourquoi vouloir de la terre rare","pourquoi la terre rare est-elle nécessaire"}}},fp="10,160,17.313.0,28.170.0,36.170.0,43.172.0"}
P.entries["item:raschal-s-report"] = {n="Raschal's Report",s="Raschal's Report signale une infestation de silithides dans le sud-est de Féralas. Shandris Pennelune envoie une copie à Gracina Spiritmight, au Temple de la Lune.",h="Raschal's Report signale une infestation de silithides dans le sud-est de Féralas.",kw={"darnassus","féralas","gracina spiritmight","raschal","rapport de raschal","shandris pennelune","silithides","sud-est de féralas","temple de la lune"},ang={["class:Priest"]="En tant que prêtre, vous portez le rapport à Gracina Spiritmight, une prêtresse dont les connaissances sur ces créatures pourraient aider les défenseurs de Féralas.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous apportez le rapport de Shandris Pennelune à Gracina Spiritmight, au Temple de la Lune, où elle reconnaît la menace que les silithides font peser sur Féralas."},sec={{t="Une copie pour Darnassus",b="Au Bastion de Pennelune, Shandris Pennelune vous confie une copie du rapport de Raschal's Report sur les silithides du sud-est de Féralas. Le rapport principal est transmis à Darnassus. Cette copie est destinée à Gracina Spiritmight, prêtresse du Temple de la Lune, qui connaît bien ces créatures."},{t="Le conseil du Temple",b="Gracina Spiritmight vous reçoit au Temple de la Lune, où elle reconnaît le danger décrit dans Raschal's Report. Elle identifie les insectes comme des silithides et avertit qu'ils dévoreront rapidement Féralas. À ses yeux, ils sont les instruments d'une grande menace pour la Horde comme pour l'Alliance, et elle prie pour avoir la volonté de les vaincre."}},faq={{q="Que contient Raschal's Report ?",a="Raschal's Report décrit l'infestation de silithides dans le sud-est de Féralas.",al={"rapport de raschal","contenu du rapport"}},{q="À qui est destiné Raschal's Report ?",a="Une copie de Raschal's Report est destinée à Gracina Spiritmight, prêtresse du Temple de la Lune à Darnassus.",al={"destinataire du rapport","rapport pour gracina"}},{q="Qui vous demande de porter le rapport ?",a="Shandris Pennelune vous confie une copie de Raschal's Report destinée à Gracina Spiritmight.",al={"qui m'a envoyé","rapport de shandris"}},{q="Quels insectes sont mentionnés dans le rapport ?",a="Gracina identifie les insectes décrits dans Raschal's Report comme des silithides.",al={"insectes de féralas","que sont les silithides"}},{q="Pourquoi Gracina a-t-elle besoin du rapport ?",a="Gracina connaît bien les créatures comme les silithides, et Shandris pense que recevoir le rapport leur sera utile à tous.",al={"pourquoi le porter à gracina","rapport pour le temple"}}},fp="16,164,20.288.0,20.329.0,25.76.0,28.112.0,33.90.0,35.73.0,33.125.0"}
P.entries["item:rattlecage-skull"] = {n="Crâne de Cliquethorax",s="Au Glas, de jeunes démonistes réprouvés récoltent des crânes de morts-vivants décérébrés. Venya Marthand leur impose cette épreuve avant de leur enseigner les arts sombres de l'invocation.",h="Au Glas, de jeunes démonistes réprouvés récoltent des crânes de morts-vivants décérébrés.",kw={"le glas","invocation de diablotin","piercing the veil","rattlecage skeleton","crâne de cliquethorax","clairières de tirisfal","venya marthand"},ang={["class:Warlock"]="En tant que démoniste réprouvé, rassembler ces crânes est votre premier pas sur la voie de la discipline. Vous prouvez ainsi que votre volonté est assez froide pour asservir votre premier démon.",["race:Undead"]="En tant que mort-vivant, détruire des squelettes inférieurs dénués de raison reflète la croyance des Réprouvés dans la domination par la seule volonté. Les morts-vivants doués de libre arbitre se distinguent des serviteurs décérébrés."},sec={{t="L'épreuve du néophyte",b="Au Glas, Venya Marthand guide les Réprouvés récemment relevés qui sont doués pour la magie noire. Elle les envoie soumettre des Rattlecage Skeletons près de la forge en ruine et en rapporter les crânes. L'épreuve vérifie qu'un jeune démoniste peut soumettre à sa volonté des créatures venues d'au-delà de ce monde. Elle les prépare à percer le néant et à asservir leur premier serviteur démoniaque."}},faq={{q="À quoi servent les crânes de Cliquethorax ?",a="Au Glas, Venya Marthand demande aux démonistes réprouvés de lui rapporter trois crânes de Cliquethorax. Ils prouvent ainsi leur concentration et leur détermination avant qu'elle leur apprenne à invoquer et à asservir un diablotin.",al={"que sont les crânes de cliquethorax","utilité des crânes de cliquethorax","qui veut les crânes de cliquethorax"}},{q="D'où viennent les crânes de Cliquethorax ?",a="Les crânes de Cliquethorax proviennent de Rattlecage Skeletons décérébrés qui errent sur les routes envahies par la végétation et dans les ruines près de la forge abandonnée du Glas.",al={"où trouver les crânes de cliquethorax","qui donne les crânes de cliquethorax","emplacement des crânes de cliquethorax"}},{q="Pourquoi Venya Marthand exige-t-elle des crânes de squelettes pour l'épreuve des démonistes ?",a="Venya Marthand croit que le pouvoir échappe aux ignorants et que la maîtrise consiste à soumettre les forces extérieures à sa volonté. Tuer des squelettes décérébrés et s'emparer de leurs têtes montre qu'un apprenti peut commander aux énergies chaotiques sans se laisser consumer par elles.",al={"pourquoi des crânes pour les démonistes","épreuve de venya marthand"}},{q="Quel savoir obtient-on après avoir rassemblé ces crânes ?",a="Une fois les crânes remis, Venya Marthand enseigne le rituel secret qui permet d'invoquer et d'asservir un diablotin. Les jeunes démonistes obtiennent ainsi leur premier véritable serviteur démoniaque.",al={"que rapporte la quête des crânes de cliquethorax","récompense de piercing the veil"}}},fx={["9627b388"]={q="Qu'est-ce qu'un Crâne de Cliquethorax ?",a="Un Crâne de Cliquethorax est la tête coupée d'un squelette Cliquethorax, l'un des morts-vivants sans esprit errant sur les terres dévastées près de la forge abandonnée du Glas. Pour les apprentis démonistes Réprouvés, ces sombres trophées servent de preuve de détermination et de concentration magique élémentaire, montrant qu'un initié peut affronter et vaincre les morts-vivants.",al={"qu'est-ce qu'un crâne de cliquethorax","histoire crâne de cliquethorax"}}},fp="16,155,17.352.0,36.172.0,37.145.0,68.239.0,55.160.0"}
P.entries["item:raven-claw-talisman"] = {n="Talisman de la griffe du corbeau",s="Dans le Refuge des saisons de Ban'ethil, le Talisman de la griffe du corbeau repose parmi des reliques destinées à éveiller des druides endormis. Il fait partie des quatre Relics of Wakening, qui guident les druides de la Serre pour les ramener sains et saufs du Rêve d'émeraude.",h="Dans le Refuge des saisons de Ban'ethil, le Talisman de la griffe du corbeau repose parmi des reliques...",kw={"athridas mantelours","ban'ethil","refuge des saisons","dolanaar","druides de la serre","talisman de la griffe du corbeau","relics of wakening","teldrassil"},ang={["class:Druid"]="En tant que druide, vous savez comment le Talisman de la griffe du corbeau reflète l'usage de foyers rituels par les druides de la Serre pour protéger un esprit errant dans le Rêve d'émeraude.",["race:NightElf"]="En tant qu'elfe de la nuit, vous protégez une tradition ancestrale et vos proches endormis en récupérant cette relique des mains des furbolgs Gnarlpine."},sec={{t="Une clé de l'éveil",b="Le Talisman de la griffe du corbeau repose dans un coffre, au cœur du Refuge des saisons de Ban'ethil. C'est là que les druides de la Serre de Teldrassil sont entrés dans un profond sommeil méditatif. Sans le foyer cérémoniel approprié, un druide coupé du monde éveillé risque de rester prisonnier du Rêve d'émeraude. Athridas Mantelours, à Dolanaar, a besoin de ce talisman et de trois autres reliques pour ramener les dormeurs sains et saufs : la Plume noire, le Saphir des cieux et la Rune de nidification."},{t="La menace dans le Refuge",b="Des furbolgs Gnarlpine corrompus ont envahi le Refuge des saisons de Ban'ethil. Les coffres sacrés et les druides endormis sont désormais en péril. Leur profanation a isolé le sanctuaire de toute aide extérieure, et les reliques risquent d'être perdues ou détruites. Athridas Mantelours appelle les défenseurs de Teldrassil à braver les couloirs de terre sinueux de l'antre et à mettre le Talisman de la griffe du corbeau en sécurité avant que les druides déplacés ne soient perdus à jamais dans le Rêve."}},faq={{q="À quoi sert le Talisman de la griffe du corbeau ?",a="Le Talisman de la griffe du corbeau est l'une des quatre reliques sacrées des Relics of Wakening. Ces reliques sont nécessaires pour tirer les druides de la Serre de leur profonde hibernation dans le Rêve d'émeraude.",al={"utilité du talisman de la griffe du corbeau","fonction du talisman de la griffe du corbeau","pourquoi avoir besoin du talisman de la griffe du corbeau"}},{q="Où trouve-t-on le Talisman de la griffe du corbeau ?",a="Le Talisman de la griffe du corbeau repose dans le Coffre de la griffe du corbeau, au fond des tunnels de terre du Refuge des saisons de Ban'ethil. Le refuge se trouve à l'ouest de Dolanaar, sur Teldrassil.",al={"emplacement du talisman de la griffe du corbeau","emplacement du coffre de la griffe du corbeau","où trouver le talisman de la griffe du corbeau"}},{q="Qui a besoin du Talisman de la griffe du corbeau ?",a="Athridas Mantelours, un druide elfe de la nuit de Dolanaar, a besoin du talisman. Il s'en servira pour préparer les rites d'éveil de ses proches déplacés.",al={"qui veut le talisman de la griffe du corbeau","qui prend le talisman de la griffe du corbeau","à qui remettre cet objet"}},{q="Pourquoi les druides ne peuvent-ils pas se réveiller sans lui ?",a="L'hibernation druidique est une transe délicate dans le Rêve d'émeraude. Sans les Relics of Wakening pour ancrer le rituel, l'esprit d'un dormeur risque de s'y perdre indéfiniment.",al={"pourquoi les druides ont besoin de reliques pour se réveiller","pourquoi les relics of wakening","les druides peuvent-ils se réveiller sans reliques"}}},fx={["33636b37"]={q="Qu'est-ce que le Talisman de la griffe du corbeau ?",a="Le Talisman de la griffe du corbeau est l'une des quatre Reliques de l'Éveil sacrées gardées par les Druides de la Griffe. Entreposé dans un coffre dédié à l'intérieur du Refuge des saisons de Ban'ethil, il est un composant essentiel du rituel délicat nécessaire pour rappeler en toute sécurité les druides endormis de leur hibernation dans le Rêve d'émeraude.",al={"qu'est-ce que le talisman de la griffe du corbeau","informations talisman de la griffe du corbeau","relique talisman de la griffe du corbeau"}}},fp="19,210,18.440.0,28.413.0,41.164.0,39.153.0,34.139.0,40.175.0"}
P.entries["item:razorflank-s-medallion"] = {n="Médaillon de Trancheflanc",s="Au cœur du Kraal de Tranchebauge, Charlga Trancheflanc porte le médaillon qui marque son règne. Son retour prouve aux sentinelles elfes de la nuit qu’elle est tombée.",h="Au cœur du Kraal de Tranchebauge, Charlga Trancheflanc porte le médaillon qui marque son règne.",kw={"agamaggan","charlga trancheflanc","falfindel gardevoie","lonebrow","kraal de tranchebauge","médaillon de trancheflanc","thalanaar"},ang={["faction:Alliance"]="En tant qu’aventurier de l’Alliance, récupérer le médaillon venge Heralath, l’éclaireur tombé, et Lonebrow, l’explorateur nain. Cela sécurise la route frontalière de Thalanaar vers Féralas.",["race:NightElf"]="En tant qu’Elfe de la nuit, tuer Charlga et revendiquer son médaillon permet à votre peuple d’étudier en toute sécurité les lieux de repos sacrés corrompus d’Agamaggan."},sec={{t="La chute de la mégère",b="Charlga Trancheflanc dirige les quilboars de Tranchebauge et porte le médaillon. À Thalanaar, Falfindel Gardevoie apprend la mort d’explorateurs, dont Heralath et le nain Lonebrow. Il envoie des aventuriers de l’Alliance affronter la dirigeante des quilboars.\n\nLe médaillon confirme aux sentinelles elfes de la nuit qui gardent les frontières de Féralas que Charlga est morte. Les forces rassemblées dans le Kraal ont perdu leur dirigeante."}},faq={{q="Qui porte le Médaillon de Trancheflanc ?",a="Charlga Trancheflanc porte le médaillon au cœur du Kraal de Tranchebauge. Elle y dirige les quilboars.",al={"qui donne le médaillon de trancheflanc","source du médaillon de trancheflanc","médaillon de charlga"}},{q="Qui souhaite qu’on lui rapporte ce médaillon ?",a="Falfindel Gardevoie, à Thalanaar, demande le médaillon. Il veut la preuve que Charlga a été tuée.",al={"qui veut le médaillon de trancheflanc","rapporter le médaillon de trancheflanc","médaillon de falfindel"}},{q="Pourquoi Falfindel a-t-il besoin d’une preuve de la mort de Charlga ?",a="Charlga a rassemblé une force hostile de quilboars dans le Kraal de Tranchebauge, menaçant les régions alentour. Heralath et Lonebrow comptaient parmi les éclaireurs tués. Le médaillon assure aux elfes de la nuit que la menace immédiate est écartée, afin qu’ils puissent poursuivre leurs recherches.",al={"pourquoi tuer charlga","but du médaillon","pourquoi avoir besoin du médaillon"}}},fx={b119a669={q="Qu'est-ce que le Médaillon de Trancheflanc ?",a="Le Médaillon de Trancheflanc est un jeton personnel porté par Charlga Trancheflanc, la vieille femme et chef des marcassins vivant au plus profond du Kraal de Tranchebauge. Plus qu'une simple ornementation, il sert de symbole indubitable de son autorité sur les tribus grouillantes du Kraal, ce qui en fait le trophée définitif de sa chute.",al={"qu'est-ce que le médaillon de trancheflanc","histoire médaillon de trancheflanc","médaillon de charlga trancheflanc"}}},fp="22,157,25.393.0,35.98.0,41.100.0,49.269.0"}
P.entries["item:reagent-pouch-shaman"] = {n="Bourse de réactifs",s="À Durotar, les sectateurs de la Lame ardente transportent les réactifs nécessaires au premier sapta de feu d’un chaman. Telf Joolam les mélange au goudron de feu des quilboars Razormane pour préparer une potion qui permet à un jeune chaman de voir le royaume du feu.",h="À Durotar, les sectateurs de la Lame ardente transportent les réactifs nécessaires au premier sapta de feu...",kw={"lame ardente","call of fire","durotar","caverne des terrevent","sapta de feu","totem de feu","bourse de réactifs","telf joolam"},ang={["class:Shaman"]="Pour un chaman, récupérer la bourse est une étape initiatique vers l’obtention du Totem de feu. Cela lui apprend que les forces élémentaires corrompues peuvent être réappropriées au service de l’équilibre.",["class:Warlock"]="En tant que démoniste, vous reconnaissez dans ces bourses des fournitures de sorcellerie destinées aux sectateurs gangrenés. Leurs éléments rituels sont conçus pour la pyromancie démoniaque, et non pour communier avec la nature."},sec={{t="Composants de la flamme",b="Les sectateurs de la Lame ardente transportent les réactifs nécessaires au premier sapta de feu d’un jeune chaman. L’ermite Telf Joolam mélange les poudres et les huiles de leurs bourses au goudron de feu des quilboars Razormane. Ces ingrédients réunis donnent une potion qui permet de voir le royaume du feu et d’accorder le chaman aux esprits de la flamme."},{t="Sources corrompues, vision pure",b="Les sectateurs de la Lame ardente mettent la flamme au service de la destruction et de la sorcellerie gangrenée. Pourtant, les éléments contenus dans leurs bourses restent liés à la chaleur et à la combustion. Les chamans enseignent que les forces élémentaires sont en tension : le feu crée autant qu’il détruit. Un chaman peut se servir des outils des sectateurs pour éveiller une véritable communion avec les esprits."}},faq={{q="À quoi sert la bourse de réactifs ?",a="Telf Joolam utilise les réactifs et le goudron de feu des quilboars Razormane pour préparer un sapta de feu. En le buvant, un chaman obtient une vision qui lui permet de chercher les esprits élémentaires et de revendiquer le Totem de feu.",al={"utilisation de la bourse de réactifs","à quoi sert la bourse de réactifs","quête de chaman de la bourse de réactifs"}},{q="Où trouver une bourse de réactifs ?",a="Vous pouvez récupérer une bourse sur les sectateurs de la Lame ardente dans la Caverne des Terrevent, au milieu des hauteurs rocheuses au nord-est de Tranchecolline, à Durotar.",al={"butin de la bourse de réactifs","où trouver la bourse de réactifs","emplacement de la bourse de la lame ardente"}},{q="Pourquoi un chaman a-t-il besoin de réactifs de démoniste ?",a="Les sectateurs de la Lame ardente remplissent leurs bourses d’ingrédients liés à la magie du feu. Leurs rituels de flamme font de ces réactifs des catalyseurs utiles pour préparer un sapta de feu.",al={"pourquoi des objets de démoniste","pourquoi les réactifs de la lame ardente","chaman et objets gangrenés"}}},fx={ad39cae0={q="Qu'est-ce que la Bourse de réactifs ?",a="Il s'agit d'une petite sacoche portée par les membres de la Lame ardente, remplie d'herbes rituelles, de cendres et de catalyseurs occultes qu'ils utilisent pour alimenter leurs sombres sortilèges. Bien qu'elle soit destinée à la magie noire, la concentration intense de composants ignés fait de cette bourse un puissant ensemble de matériaux élémentaires bruts.",al={"qu'est-ce que la bourse de réactifs","lore de la bourse de réactifs","bourse de réactifs lame ardente"}},["2a611680"]={q="D'où provient la Bourse de réactifs ?",a="Ces bourses sont assemblées et portées par les cultistes de la Lame ardente qui se cachent dans les grottes de Durotar et des Tarides. Ces démonistes rassemblent et stockent les composants spécifiques nécessaires à leurs rites destructeurs, les gardant à portée de main lorsqu'ils lancent des sorts de feu et de Shadow Magic.",al={"origine de la bourse de réactifs","qui a fabriqué la bourse de réactifs","d'où vient la bourse de réactifs"}}},fp="13,209,23.316.0,28.307.0,35.189.0,32.126.0,40.160.0"}
P.entries["item:reconstructed-tome"] = {n="Tome recomposé",s="Entre les mains des démonistes, le Tome recomposé rassemble les enseignements épars de la cabale. Ses pages renferment des rites pour invoquer et lier un chasseur corrompu du Néant distordu.",h="Entre les mains des démonistes, le Tome recomposé rassemble les enseignements épars de la cabale.",kw={"liaison","dragonmaw","chasseur corrompu","cabestan","tome recomposé","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="En tant que démoniste, reconstituer le Tome recomposé vous ouvre l’accès à des rites sombres permettant de dominer un chasseur corrompu. Sa faim de magie peut être retournée contre les lanceurs de sorts ennemis."},sec={{t="Un grimoire réassemblé",b="Les démonistes de l’Alliance et de la Horde recherchent les feuillets déchirés du Tome of the Cabal. Une fois le grimoire reconstitué, ils consultent des érudits occultes. Ces derniers espèrent découvrir ses rares enseignements avant de rendre le livre achevé."},{t="La clé du chasseur corrompu",b="Strahad Farsan reçoit le tome restauré et des bâtonnets de canalisation pris à des lanceurs de sorts Dragonmaw. C’est un maître invocateur près du port de Cabestan, dans les Tarides. Les rituels du tome fournissent à ses acolytes les paroles nécessaires pour invoquer un chasseur corrompu vorace, le vaincre et le lier à la volonté d’un démoniste."}},faq={{q="À quoi sert le Tome recomposé ?",a="Le Tome recomposé renferme les enseignements de la cabale et les rites pour invoquer et lier un chasseur corrompu. Un démoniste l’apporte avec des bâtonnets de canalisation à Strahad Farsan, à Cabestan, pour le rituel.",al={"utilité du tome recomposé","pourquoi avoir besoin du tome recomposé","usage du tome recomposé"}},{q="Qui est Strahad Farsan ?",a="Strahad Farsan est un expert en invocation qui réside au-dessus du port de Cabestan, dans les Tarides. Il supervise les épreuves des démonistes qui cherchent à asservir des démons plus dangereux.",al={"qui est strahad","rôle de strahad farsan"}},{q="Pourquoi les érudits qui étudient le livre veulent-ils en avoir une copie ?",a="Les érudits qui aident à déchiffrer les pages déchirées trouvent les textes occultes de la cabale rares et fascinants. Les chercheurs nains et réprouvés convoitent ce savoir démoniaque, qui dépasse leurs lectures habituelles.",al={"qui l’a traduit","érudits et tome recomposé"}},{q="De quoi d’autre faut-il disposer pour le rituel, en plus du tome ?",a="Strahad a besoin de trois bâtonnets de canalisation pour aider ses acolytes à maintenir le rituel d’invocation. Des lanceurs de sorts Dragonmaw détiennent ces bâtonnets dans les Paluns.",al={"autres objets nécessaires","objets à joindre au tome recomposé"}}},fx={d276d405={q="D'où vient le Tome recomposé, et qui l'a créé ?",a="Ce livre est la version restaurée de l'ancien Tome of the Cabal. Des érudits démonistes en réassemblent les chapitres déchirés et la reliure usée après que des aventuriers en ont récupéré les composants éparpillés dans des lieux dangereux à travers les continents.",al={"origine du tome recomposé","qui a créé le tome recomposé","d'où vient le tome recomposé"}},["04500ccd"]={q="Pourquoi le Tome recomposé est-il recherché ?",a="Les démonistes et les érudits des arts sombres recherchent ce tome pour les puissants secrets interdits consignés dans ses pages retrouvées. Strahad Farsan a besoin de ses rites spécifiques pour guider un aspirant démoniste dans l'invocation et l'asservissement d'un redoutable marcheur du Vide, tandis que les érudits locaux en désirent un exemplaire simplement pour ses connaissances magiques rares et fascinantes.",al={"pourquoi vouloir le tome recomposé","pourquoi strahad veut le tome recomposé","but du tome recomposé"}},a9385a16={q="Qu'est-ce que le Tome recomposé ?",a="Le Tome recomposé est la version assemblée du Tome of the Cabal, un grimoire interdit contenant des rituels démoniaques ésotériques. Après que ses pages éparpillées et ses matériaux de reliure ont été rassemblés à travers le monde, des érudits reconstituent minutieusement le texte fragmenté afin que ses connaissances obscures puissent être déchiffrées et mises à profit.",al={"qu'est-ce que le tome recomposé","histoire tome recomposé","livre tome of the cabal"}}},fp="18,172,22.250.0,20.291.1,40.182.0,22.160.0,51.199.0,54.146.0"}
P.entries["item:recruitment-letter"] = {n="Lettre de recrutement",s="À Durotar, Pisteur Takrin envoie les aventuriers prometteurs vers l’ouest, pour servir dans Les Tarides. Sa lettre dirige les volontaires aptes au combat vers l’avant-poste frontalier de Kargal Balafre-glorieuse.",h="À Durotar, Pisteur Takrin envoie les aventuriers prometteurs vers l’ouest, pour servir dans Les Tarides.",kw={"tarides","conscript of the horde","la croisée","kargal balafre-glorieuse","tranchecolline","lettre de recrutement","pisteur takrin"},ang={["faction:Horde"]="En tant que membre de la Horde, porter cette lettre marque votre passage de la défense locale à Durotar au service militaire actif sur la frontière de Kalimdor.",["race:Orc"]="Pour un jeune orc, présenter une lettre de service signée à un vétéran comme Kargal Balafre-glorieuse est une première étape pour gagner l’honneur au sein de la nouvelle Horde du chef de guerre Thrall."},sec={{t="S’engager pour la frontière",b="Autour de Tranchecolline, Pisteur Takrin observe les jeunes guerriers et éclaireurs faire leurs preuves. Il choisit ceux qui sont assez forts pour servir sur la ligne de front et leur remet une lettre pour les Tarides. Les recrues franchissent le pont sur le fleuve Furie-du-Sud, quittent la terre rouge et abritée de Durotar et rejoignent la garde de la Horde contre les hurans, les centaures et les éclaireurs de l’Alliance."},{t="Se présenter à Balafre-glorieuse",b="Juste de l’autre côté du fleuve, Kargal Balafre-glorieuse accueille les recrues à l’avant-poste. Ce vétéran grisonnant gère le poste et évalue chaque conscrit avant de valider son enrôlement. Ceux qu’il approuve sont bientôt envoyés plus à l’ouest, vers La Croisée, où les avant-postes frontaliers manquent d’effectifs."}},faq={{q="Qui a écrit cette lettre de recrutement ?",a="Pisteur Takrin distribue la lettre. Cet éclaireur orc est posté le long de la route qui part de Tranchecolline et surveille les recrues capables qui se dirigent vers l’ouest.",al={"qui remet la lettre de recrutement","qui l’a écrite","lettre de pisteur takrin"}},{q="Où faut-il apporter cette lettre ?",a="Apportez la lettre à Kargal Balafre-glorieuse, au poste de guet orc juste de l’autre côté du pont sur le fleuve Furie-du-Sud, à la frontière entre Durotar et Les Tarides.",al={"où apporter la lettre de recrutement","remettre la lettre de recrutement","à qui la donner"}},{q="Que se passe-t-il une fois la lettre signée ?",a="Kargal signe le document pour officialiser votre enrôlement, puis vous envoie plus loin dans les plaines pour prendre votre service à La Croisée, où les renforts sont attendus de toute urgence.",al={"que se passe-t-il après la signature de kargal","quête suivante après la lettre de recrutement"}},{q="Pourquoi la Horde enrôle-t-elle des aventuriers dans Les Tarides ?",a="La Horde enrôle des aventuriers, car Les Tarides est un territoire vaste et dangereux qui relie d’importants lieux de peuplement de la Horde. Les clans centaures, les hurans agressifs des Crins-de-Sang et les opérations de l’Alliance entretiennent une menace constante ; les commandants de première ligne ont donc besoin de toutes les recrues disponibles.",al={"pourquoi recrutent-ils","pourquoi l’enrôlement dans les tarides"}}},fx={e6a35429={q="Qu'est-ce que la Lettre de recrutement ?",a="La Lettre de recrutement est un document de conscription officiel délivré à des aventuriers compétents en Durotar. Le Pisteur Takrin la remet à ceux qui semblent assez robustes pour aider la Horde à étendre sa présence sur la frontière hostile des Tarides, en les recommandant aux commandants des avant-postes militaires.",al={"qu'est-ce que la lettre de recrutement","but de la lettre de recrutement","qu'est-ce que cette lettre"}},["6a5949ec"]={q="Pourquoi Kargal Balafre-glorieuse veut-il la Lettre de recrutement ?",a="Kargal Balafre-glorieuse commande l'avant-poste frontalier qui protège le pont menant aux Tarides et a désespérément besoin de recrues compétentes pour renforcer la frontière. La lettre signée prouve que vous avez été approuvé par le Pisteur Takrin et que vous êtes prêt à être affecté là où la Horde a le plus besoin de vous.",al={"pourquoi kargal veut la lettre","pourquoi remettre la lettre de recrutement","lettre de recrutement remise"}}},fp="18,168,27.348.0,23.286.0,34.141.0,34.139.0,39.174.0,57.263.0"}
P.entries["item:red-burlap-bandana"] = {n="Masque rouge",s="Près des vignobles de l’abbaye, dans la Vallée de Comté-du-Nord, l’Adjoint Willem récupère les bandanas rouges des voleurs défias tués. Cette étoffe distingue les bandits de grand chemin et les coupe-bourses de bas rang de la Confrérie des voleurs.",h="Près des vignobles de l’abbaye, dans la Vallée de Comté-du-Nord, l’Adjoint Willem récupère les bandanas...",kw={"bandana","brotherhood of thieves","défias","masque","comté-du-nord","masque rouge","willem"},ang={["class:Rogue"]="En tant que voyou en devenir, vous pouvez apprendre des maladroits monte-en-l’air de Comté-du-Nord à quelle vitesse des hors-la-loi indisciplinés deviennent des cibles faciles pour les forces de l’ordre locales.",["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez voir les bandanas rouges atteindre le seuil de l’Abbaye de Comté-du-Nord, signe que Hurlevent perd le contrôle des frontières rurales du royaume."},sec={{t="Une marque de la Confrérie",b="À Comté-du-Nord, les jeunes recrues et les voyous ordinaires de la Confrérie défias portent des masques rouges en toile de jute. Cette étoffe grossière et bon marché dissimule leur visage et marque leur allégeance à la rébellion grandissante. Ils portent ces foulards dans les vergers de l’est, où les gardes locaux reconnaissent l’étoffe rouge comme preuve que des voleurs ont été tués dans les environs."}},faq={{q="Pourquoi l’Adjoint Willem veut-il ces bandanas ?",a="L’Adjoint Willem récupère les bandanas pour prouver qu’un aventurier a tué des voyous défias près de l’Abbaye de Comté-du-Nord. Les voleurs portent ouvertement l’étoffe rouge, confirmant que la prime a été réclamée.",al={"pourquoi récupérer les bandanas","bandanas de willem","remettre à la confrérie des voleurs"}},{q="Qui porte les bandanas rouges en toile de jute ?",a="Les monte-en-l’air et les voyous de la Confrérie défias portent des bandanas rouges en toile de jute. Cette étoffe grossière dissimule leur visage et marque leur loyauté envers les hors-la-loi.",al={"qui porte un bandana rouge","histoire des masques défias","qui laisse tomber les bandanas rouges"}},{q="Pourquoi les voleurs défias opèrent-ils à Comté-du-Nord ?",a="Des éclaireurs et des brigands défias campent de l’autre côté du ruisseau, à l’est de l’Abbaye de Comté-du-Nord, pour récupérer et voler des provisions. La garnison de l’abbaye est débordée, laissant les vergers voisins à la merci des bandits de grand chemin.",al={"pourquoi les défias sont à comté-du-nord","voleurs près de l’abbaye"}},{q="Qu’est-ce qui rend les bandanas rouges ?",a="Une teinture écarlate donne leur couleur rouge aux bandanas en toile de jute bon marché. Cette teinte est la bannière et l’uniforme de la Confrérie défias, aidant ses membres à se reconnaître sur le terrain.",al={"pourquoi les masques défias sont rouges","signification de l’étoffe rouge"}}},fx={c4ebebb0={q="Qu'est-ce qu'un Masque rouge ?",a="Un Masque rouge est le masque en tissu caractéristique porté par les membres de The Defias Brotherhood. Fabriqué à bas prix à partir de toile de jute grossière et teint en rouge, il dissimule le visage de celui qui le porte et marque son appartenance à la guilde hors-la-loi. Au Comté-du-Nord, il sert de preuve directe de la présence et de l'activité d'un voyou à l'est de la rivière.",al={"identité du masque rouge","que sont les masques rouges","lore du bandana defias"}}},fp="18,180,25.319.0,43.189.0,34.148.0,47.188.0,28.172.0"}
P.entries["item:red-leather-bandana"] = {n="Masque en cuir rouge",s="Dans la Marche de l’Ouest, le Masque en cuir rouge distingue ceux qui défient la couronne de Hurlevent. La Confrérie défias le porte pour se couvrir le visage et afficher sa cause.",h="Dans la Marche de l’Ouest, le Masque en cuir rouge distingue ceux qui défient la couronne de Hurlevent.",kw={"confrérie","défias","galiaan","masque","masque en cuir rouge","colline des sentinelles","marche de l’ouest"},ang={["class:Rogue"]="En tant que voleur, vous connaissez ce masque cramoisi, signe du banditisme clandestin dans les terres humaines. Les voleurs organisés avec une précision militaire le portent.",["faction:Alliance"]="Pour l’Alliance, chaque bandana rouge pris à un hors-la-loi tombé au combat signifie un brigand de moins pour menacer les fermiers affamés et la milice débordée de la Marche de l’Ouest."},sec={{t="Marque de la Confrérie",b="Dans les champs et les fermes abandonnées de la Marche de l’Ouest, coupe-jarrets, pillards et ouvriers rebelles portent des bandanas cramoisis pour se cacher le visage. À la Colline des Sentinelles, The People's Militia voit en chacun d’eux la preuve de leur fidélité à la confrérie rebelle d’Edwin VanCleef. L’Eclaireur Galiaan récupère les bandanas auprès des voyageurs pour suivre les déplacements de la Confrérie et la diminution de ses effectifs dans la région."}},faq={{q="Pourquoi les défias portent-ils des bandanas en cuir rouge ?",a="Les défias portent des bandanas rouges pour se cacher le visage lorsqu’ils pillent les fermes et les routes. Ils affichent aussi leur allégeance au soulèvement d’Edwin VanCleef contre Hurlevent.",al={"masque défias","pourquoi un bandana rouge","signification du bandana défias"}},{q="Qui veut que ces bandanas soient récupérés dans la Marche de l’Ouest ?",a="L’Eclaireur Galiaan, de The People's Militia à la Colline des Sentinelles, demande aux voyageurs de récupérer les bandanas. Il suit les déplacements de la bande et confirme grâce à eux la mort des bandits errants.",al={"qui récupère les bandanas rouges","quête de bandana de galiaan","remettre le bandana à la colline des sentinelles"}},{q="Où trouve-t-on ces bandanas ?",a="Les défias rebelles, les coupe-jarrets et les contrebandiers portent ces bandanas dans leurs camps, les champs et les mines de la Marche de l’Ouest.",al={"butin bandana rouge","ferme aux bandanas rouges","qui lâche le masque en cuir rouge"}}},fp="19,153,23.372.1,44.153.1,47.179.0,31.112.0"}
P.entries["item:red-linen-bandana"] = {n="Masque rouge en lin",s="Dans la Forêt d’Elwynn, le masque rouge en lin distingue la Confrérie défias et cache le visage de ses membres. Sara Timberlain, au Camp de bûcherons du Val d'est, veut cette étoffe pour confectionner des vêtements et des bandages.",h="Dans la Forêt d’Elwynn, le masque rouge en lin distingue la Confrérie défias et cache le visage de ses...",kw={"masque défias","val d'est","forêt d’elwynn","lin","masque rouge en lin","sara timberlain"},ang={["class:Rogue"]="En tant que Voleur, vous connaissez l’étoffe cramoisie nouée sur le bas du visage. Elle distingue les brigands de grand chemin et les coupe-bourses dans les bois autour de la capitale.",["profession:Tailoring"]="Dans les campagnes d’Elwynn, les tisserands peuvent transformer le lin des masques de bandits en vêtements de travail."},sec={{t="Marque des Défias",b="Dans la Vallée de Comté-du-Nord, les novices et les simples brutes portent des masques en toile de jute grossière. Le lin cramoisi marque l’allégeance des membres à part entière à la confrérie de voleurs d’Edwin VanCleef. Il signale aussi leur rébellion contre la couronne de Hurlevent."},{t="Une étoffe réutilisée",b="Sara Timberlain demande aux voyageurs de récupérer des masques dans les campements de hors-la-loi. Ces masques sont associés aux bandits, mais leur lin est de bonne qualité. Une fois lavée et reprise à l’aiguille, l’étoffe peut servir à confectionner des vêtements solides et des bandages pour les travailleurs de la forêt."}},faq={{q="Pourquoi les Défias portent-ils des masques rouges en lin ?",a="Les membres de la Confrérie défias portent des masques rouges en lin pour cacher leur visage. L’étoffe marque aussi leur allégeance à la confrérie d’Edwin VanCleef et leur défi envers Hurlevent.",al={"signification du masque défias","pourquoi des masques rouges","masque rouge défias"}},{q="En quoi diffèrent-ils des masques portés au Comté-du-Nord ?",a="Les brutes de la Vallée de Comté-du-Nord portent des masques en toile de jute grossière. Les membres confirmés de la Confrérie défias, dans toute la Forêt d’Elwynn, portent du lin rouge plus fin.",al={"toile de jute ou lin","masques du comté-du-nord","masque en toile de jute"}},{q="Qui veut récupérer ces masques ?",a="Sara Timberlain, au Camp de bûcherons du Val d'est, veut récupérer les masques. Elle les lave et les défait pour tisser des vêtements pratiques.",al={"qui récupère les masques rouges en lin","masque sara timberlain","rendre la quête du masque"}},{q="Quels ennemis portent des masques rouges en lin ?",a="Les membres de la Confrérie défias portent des masques rouges en lin dans toute la Forêt d’Elwynn. On compte parmi eux les Defias Bandits, Ambushers, Rogue Wizards, dockworkers et des meneurs comme Morgan le collecteur.",al={"qui laisse tomber le masque rouge en lin","où trouver des masques","butin des défias"}}},fp="17,190,18.223.0,16.251.0,42.165.0,54.122.0,36.127.0,39.178.0"}
P.entries["item:red-wool-bandana"] = {n="Foulard en laine rouge",s="Dans Stormwind Stockade, des morceaux de foulard en laine rouge signalent la Confrérie défias. Les prisonniers arrachent de la laine à leurs couvertures et portent l’étoffe rouge comme emblème de défi.",h="Dans Stormwind Stockade, des morceaux de foulard en laine rouge signalent la Confrérie défias.",kw={"défias","mac raskol","nikova raskol","foulard en laine rouge","hurlevent","the color of blood","la prison"},ang={["faction:Alliance"]="Pour les défenseurs de l’Alliance, récupérer ces foulards rend une sombre justice au jeune Mac Raskol et frappe les émeutiers qui occupent la prison de la ville.",["profession:Tailoring"]="Ces foulards grossiers montrent comment, en captivité, des mains désespérées peuvent défaire des couvertures de laine rêche et réutiliser leurs fibres."},sec={{t="Cousus en signe de défi",b="Dans Stormwind Stockade, les détenus de la Confrérie défias préservent leur identité. En secret, ils arrachent des morceaux aux couvertures de laine de la prison et les cousent en foulards rouges. Les gardes considèrent ces foulards comme de la contrebande, et leur découverte peut déclencher des mutineries meurtrières. Chaque foulard proclame que la Confrérie et sa rébellion perdurent, même dans les fers."},{t="La vengeance d’une grand-mère",b="Les foulards en laine rouge sont liés à la mort de Mac Raskol, un gardien de prison de quatorze ans. Il a surpris des détenus en train de déchiqueter des couvertures pour en faire des foulards et a tenté de les discipliner. Des bagnards défias l’ont poignardé dans le dos. Sa grand-mère éplorée, Nikova, cherche maintenant des aventuriers pour entrer dans le donjon en pleine émeute, abattre les émeutiers et rapporter une étoffe cramoisie en preuve de vengeance."}},faq={{q="Où les prisonniers trouvent-ils ces foulards dans la Prison ?",a="Les détenus défias arrachent les foulards à leurs couvertures de laine fournies par la prison. Désarmés et incarcérés, ils transforment leur maigre literie en signes de défi qu’ils portent dans leurs cellules.",al={"origine des foulards","origine des foulards de la prison","fabrication des foulards rouges"}},{q="Qui demande de récupérer ces foulards ?",a="Nikova Raskol, une grand-mère éplorée de Hurlevent, demande aux aventuriers de récupérer les foulards. Son petit-fils Mac, âgé de quatorze ans, gardait la Prison, et les prisonniers l’ont assassiné après qu’il les a surpris en train de fabriquer ces foulards.",al={"qui a besoin de foulards en laine rouge","donneur de quête couleur du sang","nikova raskol foulard"}},{q="Pourquoi les prisonniers tiennent-ils tant à porter des foulards rouges ?",a="La Confrérie défias porte des masques et des foulards rouges comme couleurs et uniforme de gang. Derrière les barreaux, ces morceaux aident les détenus à préserver leur rang, leur moral et leur unité.",al={"pourquoi des foulards rouges","symbole rouge des défias","signification du foulard rouge"}},{q="Quels détenus en portent ?",a="Presque tous les membres défias en pleine émeute dans la Prison en portent un, notamment les Captifs défias, les Détenus défias, les Prisonniers défias, les Insurgés défias et les Bagnards défias.",al={"qui donne le foulard en laine rouge","butin de foulard dans la prison"}}},fx={["7f0c1a2a"]={q="Qu'est-ce qu'un Foulard en laine rouge ?",a="Un Foulard en laine rouge est une écharpe cramoisie improvisée, confectionnée par les membres emprisonnés de The Defias Brotherhood à l'intérieur de la Stormwind Stockade. En déchiquetant et en teignant les couvertures en laine fournies par la prison, les détenus fabriquent ces symboles en tissu pour afficher ouvertement leur allégeance à la Confrérie et maintenir leur identité de gang même derrière les barreaux.",al={"qu'est-ce qu'un foulard en laine rouge","objet foulard en laine rouge","foulard rouge des geôles"}}},fp="16,166,20.335.0,25.366.0,54.181.0,35.218.0,60.156.0,25.134.0"}
P.entries["item:remaining-drops-of-purest-water"] = {n="Restes d'eau pure",s="À travers Kalimdor et Lordaeron, les Restes d'eau pure attendent un périlleux voyage. Brine a recueilli cette eau pour préparer une potion destinée à aider les chamans.",h="À travers Kalimdor et Lordaeron, les Restes d'eau pure attendent un périlleux voyage.",kw={"brasero d'everfount","brine","call of water","manifestation corrompue","eau la plus pure","forêt des pins-argentés","totem d'eau"},ang={["class:Shaman"]="En tant que chaman, vous portez les gouttes des Tarides arides jusqu'à la côte souillée de la Forêt des Pins-Argentés, dans le cadre de vos épreuves pour maîtriser l'eau. Ce pèlerinage est indispensable pour obtenir votre Totem d'eau.",["faction:Horde"]="En tant que membre de la Horde, vous quittez les territoires de la Horde en Kalimdor pour rejoindre les possessions précaires des Réprouvés dans la Forêt des Pins-Argentés. Sur cette longue distance, le pèlerinage apporte une restauration spirituelle face à la souillure du Fléau."},sec={{t="Un remède aux eaux souillées",b="Dans les Tarides, Brine prépare une potion avec de l'eau recueillie à travers Kalimdor et Lordaeron. Une partie donne aux chamans une vision des éléments lointains. Les gouttes restantes ont une tâche plus difficile.\n\nLes chamans les portent jusqu'à la côte de la Forêt des Pins-Argentés, près du Sépulcre, où se trouve le Brasero d'Everfount. Là, ils brûlent les gouttes avec les brassards d'un élémentaire déchu et corrompu. L'eau pure dissipe la corruption de la peste des morts-vivants et appelle un esprit de l'eau intact avec lequel les chamans peuvent communier. Leur communion avec l'élément s'achève ainsi."}},faq={{q="À quoi servent ces gouttes ?",a="Sur la côte de la Forêt des Pins-Argentés, les gouttes sont brûlées sur le Brasero d'Everfount avec les brassards d'une manifestation aquatique corrompue. Le rite purifie le sanctuaire élémentaire souillé et invoque un esprit de l'eau intact.",al={"utilité des restes de gouttes","but des gouttes restantes","utiliser l'eau la plus pure"}},{q="D'où vient ce liquide ?",a="Brine, une chamane orque qui vit sur une colline dans le sud des Tarides, a préparé la potion. Elle la prépare pendant les épreuves spirituelles des aspirants chamans, et ces gouttes en sont le reste.",al={"qui a préparé l'eau pure","origine des gouttes","gouttes d'eau de brine"}},{q="Pourquoi accomplir le rituel jusque dans la Forêt des Pins-Argentés ?",a="Un sanctuaire aquatique sur la côte de la Forêt des Pins-Argentés, à l'ouest du Sépulcre, a été corrompu par la peste des morts-vivants. Ses esprits élémentaires sont devenus hostiles et déformés. Purifier le bassin met à l'épreuve la dévotion et la maîtrise d'un chaman sur de grandes distances.",al={"pourquoi la forêt des pins-argentés","pourquoi voyager jusqu'à la forêt des pins-argentés","sanctuaire aquatique des pins-argentés"}},{q="Que se passe-t-il quand elles touchent le brasero ?",a="Versées dans les flammes du brasero avec les brassards corrompus, les gouttes crépitent dans le feu. L'incantation dissipe les derniers vestiges de la peste et invoque une manifestation aquatique pure.",al={"rituel du brasero","que se passe-t-il sur le brasero","rituel du brasero d'everfount"}}},fx={db79eea5={q="Qu'est-ce que les Restes d'eau pure ?",a="Cette petite fiole contient les derniers vestiges de la potion purifiante concoctée par l'ermite Brine dans le sud des Tarides. Infusé avec de l'eau collectée dans les Tarides, au Moulin-de-Tarren et en Orneval, ce liquide puissant possède d'immenses propriétés purificatrices. Bien qu'il n'en reste que quelques gouttes, sa pureté concentrée suffit à dissiper la corruption persistante lorsqu'elle est offerte lors de rites élémentaires.",al={"qu'est-ce que les restes d'eau pure","que sont les gouttes d'eau pure","lore des gouttes d'eau pure"}},["55d7092f"]={q="Pourquoi Islen Oeil-des-rivières veut-elle que vous utilisiez les Restes d'eau pure ?",a="Islen Oeil-des-rivières a besoin que vous versiez ces gouttes sur le Brasier de source éternelle dans la Forêt des Pins-Argentés. Un sanctuaire aquatique sacré y a succombé à la peste des morts-vivants, rendant les esprits locaux sourds à la communion chamanique. En offrant ces quelques gouttes restantes accompagnées des brassards d'une manifestation corrompue vaincue, le brasier peut déclencher un rituel purificateur assez puissant pour invoquer un esprit de l'eau pure.",al={"pourquoi utiliser les gouttes d'eau pure","pourquoi les restes d'eau pure sont-ils nécessaires","pourquoi avez-vous besoin des gouttes d'eau pure"}}},fp="31,152,27.549.0,30.221.0,31.181.0,61.235.0,41.179.0"}
P.entries["item:remedy-of-arugal"] = {n="Remède d'Arugal",s="Dans la Forêt des Pins-Argentés, Dalar Tisselaube cherche le sort d'Arugal pour comprendre le fonctionnement de sa magie worgen.",h="Dans la Forêt des Pins-Argentés, Dalar Tisselaube cherche le sort d'Arugal pour comprendre le fonctionnement...",kw={"arugal","arugal's folly","dalar tisselaube","grimoires poussiéreux","moonrage","remède d'arugal","le sépulcre","forêt des pins-argentés"},ang={["class:Mage"]="En tant que mage réprouvé, vous partagez peut-être le mépris de Dalar Tisselaube pour les expériences maladroites et inconsidérées d'Arugal, tout en percevant le danger d'une magie d'invocation incontrôlée.",["race:Undead"]="En tant que Réprouvé, vous contribuez à récupérer ce sort, première étape essentielle pour repousser les worgens sauvages qui menacent les frontières de la Forêt des Pins-Argentés."},sec={{t="Les restes d'un mage",b="Avant de s'emparer du Donjon d'Ombrecroc, l'archimage Arugal trouva refuge dans une ferme de blé abandonnée, au nord du pont sur la rivière, dans la Forêt des Pins-Argentés. Parmi les outils agricoles et les planchers pourrissants, il laissa des grimoires où étaient consignés ses arts étranges. Un parchemin, le Remède d'Arugal, décrit ses premières méthodes et formules magiques, issues de ses expériences sur les transmutations qui frappèrent la population locale."},{t="L'examen des Réprouvés",b="Au Sépulcre, Dalar Tisselaube est un lanceur de sorts réprouvé qui n'accorde guère d'importance au prestige d'Arugal. Il juge l'intellect d'Arugal fragile et superficiel. Pourtant, Tisselaube doit comprendre le fonctionnement de la malédiction des worgens. Récupérer le Remède apporte aux agents réprouvés le savoir arcanique qu'il recherche pour contrer la menace grandissante d'Arugal et assurer la sécurité de la Forêt des Pins-Argentés pour Dame Sylvanas."}},faq={{q="Qu'est-ce que le Remède d'Arugal ?",a="Le Remède d'Arugal consigne les méthodes arcaniques qu'Arugal employa lors de ses premières expériences sur la magie worgen dans la Forêt des Pins-Argentés.",al={"qu'est-ce que le remède d'arugal","objet remède d'arugal","sort remède"}},{q="Où le Remède a-t-il été abandonné ?",a="Arugal laissa le Remède dans des grimoires poussiéreux, à l'étage d'une ferme de blé abandonnée au nord du pont sur la rivière, dans la Forêt des Pins-Argentés.",al={"où trouver le remède d'arugal","emplacement du remède d'arugal","grimoire de la ferme"}},{q="Pourquoi Dalar Tisselaube veut-il ce sort ?",a="Dalar Tisselaube veut étudier la magie d'Arugal afin que les Réprouvés puissent trouver comment la contrer et assurer la sécurité de la Forêt des Pins-Argentés.",al={"pourquoi dalar veut le remède","remède de dalar tisselaube"}},{q="Qui garde les grimoires de la ferme ?",a="Les serviteurs lupins d'Arugal infestent la ferme. Quand quelqu'un dérange les grimoires poussiéreux du deuxième étage, un Moonrage Darkrunner bondit pour défendre les biens de son maître.",al={"qu'est-ce qui attaque à la ferme","embuscade dans le grimoire"}}},fx={["157696b2"]={q="D'où vient le Remède d'Arugal, et qui l'a créé ?",a="Le Remède d'Arugal est une incantation rédigée par l'archimage Arugal lui-même durant ses premiers jours dans la Forêt des Pins-Argentés. Après que ses plans ont commencé à se concrétiser, il a résidé brièvement dans une ferme céréalière au nord du pont principal, laissant derrière lui des grimoires poussiéreux contenant ses recherches.",al={"qui a créé le remède d'arugal","origine du remède d'arugal","d'où vient le remède d'arugal"}}},fp="16,96,18.379.0,17.375.0,29.124.0,33.136.0,42.113.0,38.171.0"}
P.entries["item:rendered-spores"] = {n="Spores fondues",s="Dans Les Tarides, les Spores fondues sont acheminées en urgence vers Pitons-du-Tonnerre avant que leur émulsion ne se dégrade. Apothecary Zamah doit la stabiliser sous la ville.",h="Dans Les Tarides, les Spores fondues sont acheminées en urgence vers Pitons-du-Tonnerre avant que leur...",kw={"apothicaire helbrim","apothecary zamah","tarides","la croisée","émulsion","les bassins de la vision","spores fondues","pitons-du-tonnerre"},ang={["race:Tauren"]="En tant que tauren, vous voyez des apothicaires réprouvés expérimenter sur l’étrange flore des Tarides, dans les sacrés Bassins de la Vision. Leur travail témoigne de l’alliance précaire et pragmatique forgée à Pitons-du-Tonnerre.",["race:Undead"]="En tant que mort-vivant, vous appartenez à un peuple dont la Société royale des apothicaires recherche des composés biologiques partout en Kalimdor pour aider les Réprouvés. Des coursiers rapides relient les chercheurs de terrain comme Helbrim aux spécialistes comme Zamah."},sec={{t="Un mélange volatil",b="Près des oasis humides des Tarides, l’Apothicaire Helbrim recueille des spores fongiques et les transforme en émulsion chimique active. Le mélange est instable. Au bout de quarante-cinq minutes, il se dégrade et ne peut plus être étudié."},{t="Livraison aux Bassins de la Vision",b="Dans son avant-poste isolé, l’Apothicaire Helbrim ne peut pas achever le raffinage de l’émulsion. Elle doit parvenir à sa collègue réprouvée, Apothecary Zamah, sous la Cime des Esprits à Pitons-du-Tonnerre. Aux Bassins de la Vision, Zamah dispose de l’équipement et des réactifs nécessaires pour refermer et finir de traiter les spores pour la Société royale des apothicaires."}},faq={{q="À quoi servent les Spores fondues ?",a="L’Apothicaire Helbrim transforme des matières fongiques en émulsion que la Société royale des apothicaires pourra étudier. À Pitons-du-Tonnerre, Apothecary Zamah s’en sert pour poursuivre ses recherches sur les étranges excroissances qui se répandent dans Les Tarides.",al={"utilité des spores fondues","que fait zamah avec les spores","pourquoi les spores fondues"}},{q="Pourquoi l’émulsion a-t-elle une durée limitée ?",a="L’émulsion préparée par l’Apothicaire Helbrim est volatile et commence à se dégrader dès qu’elle est mélangée. Elle ne reste active que quarante-cinq minutes : elle doit donc traverser les plaines jusqu’à Pitons-du-Tonnerre avant de devenir inerte.",al={"pourquoi les spores fondues sont limitées dans le temps","pourquoi les spores se périment","durée des spores fondues"}},{q="Qui a créé ces spores ?",a="À La Croisée, dans Les Tarides, l’Apothicaire Helbrim transforme en composé liquide instable les spores fongiques brutes recueillies près des oasis.",al={"qui a créé les spores fondues","qui transforme les spores","spores d’helbrim"}},{q="Où faut-il apporter le mélange ?",a="Le mélange doit parvenir à Apothecary Zamah, aux Bassins de la Vision sous la Cime des Esprits, à Pitons-du-Tonnerre, la capitale des taurens.",al={"où apporter les spores fondues","emplacement de zamah","emplacement des bassins de la vision"}}},fx={["7897c588"]={q="Qu'est-ce que les Spores fondues ?",a="Les Spores fondues sont un extrait transformé d'étranges excroissances fongiques récoltées dans les Tarides. L'Apothicaire Helbrim a fait bouillir et fondre les spores brutes pour obtenir une émulsion liquide volatile et instable, préparant soigneusement le mélange pour une étude alchimique approfondie par la Société royale des apothicaires.",al={"qu'est-ce que les spores fondues","infos sur les spores fondues","que sont les spores fondues"}}},fp="15,153,18.219.0,31.310.0,34.217.0,40.211.0,25.134.0,34.120.0"}
P.entries["item:renferrel-s-findings"] = {n="Les découvertes de Renferrel",s="Dans la Forêt des Pins-Argentés, les découvertes de Renferrel acheminent ses recherches vers Moulin-de-Tarren. L’Apothicaire Renferrel a réuni ses notes au Sépulcre pour l’Apothicaire Lydon, qui aide à préparer la nouvelle peste des Réprouvés.",h="Dans la Forêt des Pins-Argentés, les découvertes de Renferrel acheminent ses recherches vers Moulin-de-Tarren.",kw={"découvertes","lydon","nouvelle peste","renferrel","société royale des apothicaires","le sépulcre","moulin-de-tarren"},ang={["faction:Horde"]="En tant que membre de la Horde, vous savez que les coursiers qui transportent les documents de Renferrel relient des avant-postes comme le Sépulcre et Moulin-de-Tarren, renforçant la présence de la Horde dans tout Lordaeron.",["race:Undead"]="En tant que mort-vivant, vous savez que ces documents servent l’ambition de Sylvanas Coursevent : perfectionner une nouvelle peste contre le Fléau et les ennemis vivants qui empiètent sur les terres des Réprouvés."},sec={{t="Une peste en préparation",b="Au Sépulcre, l’Apothicaire Renferrel consigne ses travaux sur la nouvelle peste. La Société royale des apothicaires répond directement à Dame Sylvanas Coursevent, la Dame noire. Les chercheurs dispersés dans tout Lordaeron doivent unir leurs efforts pour trouver une percée. Renferrel envoie donc ses découvertes au sud, à Moulin-de-Tarren, où ses confrères apothicaires pourront s’appuyer sur ses résultats."},{t="En route pour Moulin-de-Tarren",b="Les documents de Renferrel relient la Forêt des Pins-Argentés aux Contreforts de Hautebrande et aux travaux alchimiques des Réprouvés. L’Apothicaire Lydon attend les notes à Moulin-de-Tarren, où il pourra les comparer à ses propres recherches contre les vivants et le Fléau. Les routes de Hautebrande sont disputées, aussi la Société compte-t-elle sur des coursiers fiables. Sans eux, ses recherches dispersées ne tarderaient pas à piétiner."}},faq={{q="Que contiennent les découvertes de Renferrel ?",a="Les découvertes de Renferrel contiennent les dernières recherches de l’Apothicaire Renferrel et des données expérimentales recueillies dans la Forêt des Pins-Argentés. Ces notes portent sur les travaux des Réprouvés pour préparer une nouvelle peste.",al={"contenu des découvertes","recherches de renferrel","contenu des notes"}},{q="À qui ces recherches doivent-elles parvenir ?",a="Les documents doivent parvenir à l’Apothicaire Lydon. Il mène des recherches sur la peste à Moulin-de-Tarren, une colonie réprouvée des Contreforts de Hautebrande.",al={"destinataire des découvertes de renferrel","destination des découvertes","destinataire de la livraison"}},{q="Pourquoi les apothicaires échangent-ils leurs notes ?",a="Dame Sylvanas Coursevent a ordonné à la Société royale des apothicaires de créer une nouvelle peste. Les apothicaires pensent que comparer leurs résultats leur permettra de trouver une percée bien plus rapidement qu’en travaillant seuls.",al={"raison de partager les découvertes","raison de les envoyer à lydon","communication entre apothicaires"}},{q="Où l’Apothicaire Renferrel mène-t-il ses expériences ?",a="L’Apothicaire Renferrel mène ses expériences au Sépulcre, le principal avant-poste réprouvé au cœur de la Forêt des Pins-Argentés.",al={"emplacement de renferrel","lieu où se trouve l’apothicaire renferrel","auteur des découvertes de renferrel"}}},fx={f680c460={q="Que sont Les découvertes de Renferrel ?",a="Les découvertes de Renferrel sont une collection de notes alchimiques et de documents de recherche compilés par l'Apothicaire Renferrel. Ils détaillent ses expériences en cours menées pour le compte de la Société royale des apothicaires, destinées à être partagées directement avec ses collègues à travers Lordaeron.",al={"qu'est-ce que les découvertes de renferrel","objet découvertes de renferrel","que sont ces découvertes"}},bf8d559a={q="D'où viennent Les découvertes de Renferrel, et qui les a créées ?",a="Ces documents ont été rédigés par l'Apothicaire Renferrel, un chercheur ambitieux stationné au Sépulcre dans la Forêt des Pins-Argentés. Travaillant assidûment sous le mandat des Réprouvés, il a rédigé ces notes pour consigner ses progrès et ses percées dans la préparation de mixtures expérimentales.",al={"qui a écrit les découvertes de renferrel","d'où viennent les découvertes de renferrel","créateur des découvertes de renferrel"}},["21b2c0f4"]={q="Pourquoi quelqu'un voudrait-il Les découvertes de Renferrel ?",a="La Société royale des apothicaires subit une pression immense de la part de Dame Sylvanas Coursevent pour concocter un A New Plague. Croyant qu'une collaboration accélérera leur sombre travail, Renferrel a envoyé ses recherches à l'Apothicaire Lydon au Moulin-de-Tarren, qui est impatient d'étudier les méthodes de son collègue et de les intégrer à ses propres efforts.",al={"pourquoi livrer les découvertes de renferrel","qui veut les découvertes de renferrel","pourquoi lydon veut les découvertes de renferrel"}}},fp="20,209,23.354.0,14.377.0,36.173.0,41.139.0,39.189.0,56.127.0"}
P.entries["item:report-on-the-defias-brotherhood"] = {n="Rapport sur les Défias",s="Au Donjon de Hurlevent, les conclusions sur la Confrérie défias parviennent à la cour royale. L’architecte de la ville, Baros Alexston, confie le rapport à l’aventurier qui a découvert le complot.",h="Au Donjon de Hurlevent, les conclusions sur la Confrérie défias parviennent à la cour royale.",kw={"audience avec le roi","baros alexston","défias","rapport","donjon de hurlevent","vancleef","marche de l’ouest"},ang={["faction:Alliance"]="En portant le rapport devant la cour royale, vous achevez un long combat pour sécuriser la Marche de l’Ouest et avertir les dirigeants de Hurlevent de l’insurrection à leurs frontières.",["race:Human"]="En tant qu’humain du royaume, vous portez un rapport sur le conflit toujours irrésolu entre la noblesse de Hurlevent et les maçons qui ont rebâti la ville."},sec={{t="Un message pour le trône",b="Après une longue enquête sur les troubles en Marche de l’Ouest et dans les terres voisines, l’architecte de la ville, Baros Alexston, a préparé un rapport pour les dirigeants de Hurlevent. Il l’a confié à l’aventurier qui a déjoué le complot.\n\nLe rapport est porté au Donjon de Hurlevent pour une audience privée. Les conclusions portent sur les manigances des conspirateurs et le danger qu’elles représentent pour le royaume."},{t="Accueil au Donjon",b="Le roi Varian Wrynn est en voyage diplomatique lorsque le messager arrive dans la salle du trône. Les conseillers royaux et la régence qui gouverne au nom du jeune roi Anduin reçoivent le rapport à sa place. Ils félicitent le messager d’avoir mis fin aux projets de VanCleef.\n\nDame Katrana Prestor figure parmi les dignitaires présents lorsque les avertissements parviennent à la régence."}},faq={{q="Qu’est-ce que le Rapport sur les Défias ?",a="Ce rapport est un dossier officiel rédigé par Baros Alexston. Il rassemble des renseignements sur Edwin VanCleef, son armée souterraine et le vaste complot défias contre Hurlevent.",al={"quel est ce rapport","objet rapport défias","rapport de baros alexston"}},{q="Qui a rédigé ce rapport ?",a="Baros Alexston, architecte de la ville de Hurlevent, a préparé le rapport. Il a autrefois travaillé aux côtés des maçons, avant qu’ils ne fassent sécession pour former la Confrérie défias.",al={"qui a rédigé le rapport défias","auteur du rapport"}},{q="Pourquoi est-ce que je porte ce rapport au Donjon de Hurlevent ?",a="Baros Alexston estime que l’aventurier qui a découvert le complot mérite de présenter les conclusions au trône. Il espère que vous serez reconnu par la royauté pour avoir protégé le royaume.",al={"pourquoi porter ce rapport","audience royale remise du rapport"}},{q="Le roi Varian lira-t-il le rapport ?",a="Non. Le roi Varian Wrynn est en voyage diplomatique lorsque vous arrivez au Donjon de Hurlevent. Sa cour et la régence reçoivent le rapport à sa place.",al={"le roi lit-il le rapport","audience avec varian wrynn"}}},fp="32,178,25.367.0,21.337.1,45.170.1,22.160.1,43.182.0,33.138.0"}
P.entries["item:resonite-crystal"] = {n="Cristal de résonite",s="Dans la Caverne des Eboulis, les kobolds creusent frénétiquement à la recherche de cristaux de résonite. Leurs travaux inquiètent Mor'rogal, à la Retraite de Roche-Soleil.",h="Dans la Caverne des Eboulis, les kobolds creusent frénétiquement à la recherche de cristaux de résonite.",kw={"ravin des éboulis","cristal","terrestres","kobold","mor'rogal","résonite","les serres-rocheuses","titans"},ang={["class:Shaman"]="En tant que chaman, vous pouvez sentir la résonance inquiétante des cristaux de résonite. C'est une magie primordiale de la terre, latente, laissée par les créations des Titans enfouies sous les montagnes.",["profession:Mining"]="En tant que mineur, vous trouvez la résonite en concentrations intenses, dans des filons très différents des filons ordinaires de cuivre ou d'étain. Pour l'atteindre, il faut dépasser les kobolds agressifs et s'enfoncer dans les couches souterraines les plus profondes."},sec={{t="Résonance ancienne",b="Au fond du Ravin des Éboulis, les kobolds creusent frénétiquement à la recherche de cristaux de résonite. Leur soudaine obsession alarme les chamans de la Retraite de Roche-Soleil. Mor'rogal examine les pierres et perçoit un faible bourdonnement magique. Il reconnaît des traces de magie des Terrestres. Ces signes indiquent une strate ancienne façonnée par les Titans."},{t="Au cœur de la terre",b="Les mineurs kobolds ont creusé assez profondément pour déranger les anciens Terrestres. Les Titans ont façonné les Terrestres pour tailler et modeler les fondations du monde. Leur magie imprègne encore la roche environnante. Des agents de la Horde rassemblent des cristaux de résonite pour découvrir ce qui pousse les kobolds à agir et retourner le pouvoir de la pierre enchantée contre ce qui sommeille en contrebas."}},faq={{q="Où trouve-t-on des cristaux de résonite ?",a="Les cristaux de résonite se trouvent dans la Caverne des Eboulis, au fond du Ravin des Éboulis, dans le sud-est des Serres-Rocheuses.",al={"emplacement de la résonite","où trouver de la résonite","farm de cristaux de résonite"}},{q="Pourquoi les kobolds extraient-ils des cristaux de résonite ?",a="Les kobolds extraient frénétiquement ces cristaux rares, mais Mor'rogal en ignore la raison. Il demande des échantillons et une exploration des profondeurs de la caverne pour découvrir ce qu'ils font.",al={"pourquoi les kobolds minent","complot des kobolds et des cristaux","kobolds du ravin des éboulis"}},{q="Quel pouvoir renferme un cristal de résonite ?",a="Mor'rogal soupçonne que les cristaux sont liés à quelque chose d'inquiétant sous les montagnes. Il reconnaît leur nature magique après avoir reçu des échantillons et des nouvelles de la caverne.",al={"magie des cristaux de résonite","qu'est-ce que la résonite","la résonite est-elle magique"}},{q="Qui étudie ces cristaux ?",a="Mor'rogal, un Tauren de la Retraite de Roche-Soleil, dans les Serres-Rocheuses, étudie les cristaux. Il cherche à comprendre la soudaine recrudescence de l'activité des kobolds et à trouver un moyen de contrer le mal découvert.",al={"qui veut de la résonite","cristaux de mor'rogal","résonite de la retraite de roche-soleil"}},{q="Que sont les Terrestres mentionnés en lien avec le cristal ?",a="Les Titans ont créé les Terrestres pour façonner la terre. Mor'rogal enquête sur un lien possible entre eux et la résonite.",al={"que sont les terrestres","lien entre les terrestres et les titans"}}},fx={c14b6c8c={q="Qu'est-ce que le Cristal de résonite ?",a="La résonite est un cristal minéral rare trouvé dans la Caverne des Eboulis dans Les Serres-Rocheuses. L'exploitation minière effrénée des kobolds a alarmé Mor'rogal, qui demande des échantillons et des nouvelles de la grotte pour enquêter.",al={"qu'est-ce que la résonite","lore du cristal de résonite","minerai de résonite"}},af246400={q="Pourquoi quelqu'un voudrait-il le Cristal de résonite ?",a="Mor'rogal souhaite obtenir des échantillons de minerai pour comprendre l'extraction effrénée des kobolds et découvrir ce qui se cache sous le Ravin des Éboulis. Il demande à un aventurier d'explorer la grotte et de rassembler les cristaux.",al={"pourquoi récolter des cristaux de résonite","qui veut le cristal de résonite","but du cristal de résonite"}}},fp="16,131,17.290.1,17.334.1,34.123.0,45.172.0,44.170.0,31.194.0,60.129.0"}
P.entries["item:restabilization-cog"] = {n="Rouage de rééquilibrage",s="Aux portes de Gnomeregan, les gnomes lépreux portent encore des rouages de rééquilibrage. À Kharanos, les bricoleurs ont besoin de rouages intacts pour une machine conçue pour inverser la mutation lépreuse.",h="Aux portes de Gnomeregan, les gnomes lépreux portent encore des rouages de rééquilibrage.",kw={"dun morogh","gibblewilt","gnomeregan","kharanos","gnome lépreux","operation recombobulation","esbrouf fulgurouage","rouage de rééquilibrage"},ang={["profession:Engineering"]="En tant qu'ingénieur, vous pouvez comprendre comment les rouages de rééquilibrage s'intègrent aux machines gnomes comme le Recombobulateur.",["race:Gnome"]="Gnome exilé dans Dun Morogh, vous récupérez des mécanismes sur vos proches corrompus dans l'espoir de trouver un remède pour les gnomes tombés de Gnomeregan."},sec={{t="Composants pour un remède",b="Les radiations ont inondé Gnomeregan lors d'une tentative ratée d'anéantir les troggs envahisseurs. D'innombrables gnomes sont tombés malades et sont devenus hostiles, puis ont fui leur foyer en exil. Même dans leur folie, ils portent des mécanismes gnomes complexes.\n\nOzzie Virevolt et Esbrouf Fulgurouage pensent que cette terrible transformation peut être annulée. Leur prototype de Dispositif de recombobulation a besoin de pièces récupérées sur les affligés aux portes de Gnomeregan. Des rouages de rééquilibrage intacts équilibreront ses systèmes de combustion internes."}},faq={{q="À quoi sert un rouage de rééquilibrage ?",a="À Kharanos, le bricoleur Esbrouf Fulgurouage a besoin de rouages de rééquilibrage pour le Recombobulateur. Avec les Gyromechanic Gears, ils constituent une partie de la machine expérimentale conçue pour soigner les gnomes lépreux irradiés.",al={"utilité du rouage","à quoi sert le rouage de rééquilibrage","pourquoi récupérer les rouages"}},{q="Où peut-on trouver ces rouages ?",a="Les gnomes lépreux et le dérangé Gibblewilt portent ces rouages. Ils rôdent autour des portes extérieures et dans les tranchées, à l'extérieur de Gnomeregan, dans l'ouest de Dun Morogh.",al={"emplacement du rouage de rééquilibrage","qui donne les rouages","où récupérer les rouages"}},{q="Le Recombobulateur peut-il vraiment soigner les gnomes lépreux ?",a="Esbrouf Fulgurouage et Ozzie Virevolt pensent qu'un mécanisme calibré peut inverser la mutation. Le Recombobulateur n'a pas encore été testé pour savoir s'il peut restaurer l'esprit et le corps des gnomes lépreux, et la recherche d'un remède se poursuit.",al={"le recombobulateur fonctionne-t-il","existe-t-il un remède pour les gnomes lépreux"}}},fx={["8ac7e8f1"]={q="Qu'est-ce qu'un Rouage de rééquilibrage ?",a="Un Rouage de rééquilibrage est un composant mécanique de précision récupéré sur les machines en ruine et les gnomes lépreux irradiés qui errent à l'extérieur de la cité en ruine de Gnomeregan. Conçus pour maintenir l'équilibre structurel et rotationnel des dispositifs gnomiques complexes, ces rouages sont prisés par les bricoleurs à la recherche de pièces robustes et pré-usinées pour stabiliser des inventions capricieuses comme le Recombobulateur d'Ozzie Virevolt.",al={"qu'est-ce qu'un rouage de rééquilibrage","lore du rouage de rééquilibrage","à propos du rouage de rééquilibrage"}},ceb0040c={q="D'où viennent les Rouages de rééquilibrage ?",a="Ces rouages proviennent des vastes complexes mécaniques de Gnomeregan. Lorsque la ville a été évacuée suite au désastreux rejet de radiations, d'innombrables dispositifs automatisés ainsi que les survivants tragiques ayant succombé à la folie de la lèpre ont emporté ces composants standardisés jusque sur la neige à l'extérieur des portes.",al={"qui a créé le rouage de rééquilibrage","origine du rouage de rééquilibrage","d'où vient le rouage de rééquilibrage"}}},fp="19,156,21.476.0,39.203.0,30.142.0,54.220.0"}
P.entries["item:rin-ji-s-secret-quest-item"] = {n="Rin'ji's Secret",s="Dans les Hinterlands, une tablette couverte de signes trolls Witherbark pourrait receler quelque chose de précieux. On demande à Oran Snakewrithe, dans le Quartier de la Magie de Fossoyeuse, de la déchiffrer.",h="Dans les Hinterlands, une tablette couverte de signes trolls Witherbark pourrait receler quelque chose de...",kw={"hinterlands","quartier de la magie","oran snakewrithe","rin'ji","secret","tablette","troll","fossoyeuse","witherbark"},ang={["race:Troll"]="La tablette porte des signes Witherbark. Son mystère concerne donc l'histoire et les traditions d'une tribu troll."},sec={{t="Marques trolls",b="Rin'ji's Secret est une tablette découverte au milieu des troubles des Hinterlands. Sa surface porte les signes des trolls Witherbark, dont le sens reste inconnu. Oran Snakewrithe, spécialiste des trolls Witherbark à Fossoyeuse, pourrait savoir la lire."}},faq={{q="Qu'est-ce que Rin'ji's Secret ?",a="Rin'ji's Secret est une tablette couverte de signes trolls Witherbark. Son sens reste un mystère.",al={"secret de rinji","tablette de rin'ji","qu'est-ce que la tablette"}},{q="Qui peut lire la tablette ?",a="Oran Snakewrithe, spécialiste des trolls Witherbark dans le Quartier de la Magie de Fossoyeuse, pourrait déchiffrer la tablette.",al={"qui la déchiffre","tablette d'oran","érudit du quartier de la magie"}},{q="D'où vient la tablette ?",a="La tablette est liée aux épreuves de Rin'ji dans les Hinterlands.",al={"lieu de découverte","tablette des hinterlands","lieu où se trouve rinji"}},{q="Rin'ji's Secret a-t-elle de la valeur ?",a="La tablette pourrait avoir de la valeur, mais celle-ci reste incertaine tant que ses signes n'ont pas été compris.",al={"valeur de la tablette","tablette précieuse","valeur de rinji's secret"}}},fp="15,166,14.245.0,24.91.0,24.114.0,25.59.0,28.89.0"}
P.entries["item:ring-of-zoram"] = {n="Anneau de Zoram",s="À Zoram, l’anneau des dirigeants de la cité a refait surface après des millénaires sous la mer. Les nagas le détiennent, et Talen cherche la clé d’une statuette antique.",h="À Zoram, l’anneau des dirigeants de la cité a refait surface après des millénaires sous la mer.",kw={"statuette antique","orneval","lady vespia","anneau de zoram","ruuzel","talen","la grève de zoram"},ang={["faction:Alliance"]="Reprendre l’anneau aux nagas aide l’érudit elfe de la nuit Talen à faire revivre l’histoire kaldorei le long des frontières contestées d’Orneval.",["race:NightElf"]="L’anneau est un vestige d’avant la Grande Fracture, datant d’une époque où l’arrogance des arcanes et les mers montantes n’avaient pas encore déchiré l’empire kaldorei."},sec={{t="L’anneau de la cité engloutie",b="Avant l’effondrement du Puits d’éternité, Zoram était un joyau de l’empire des Elfes de la nuit, sur la côte occidentale de Kalimdor. Ses dirigeants portaient l’Anneau de Zoram, dont la face interne porte un étrange code en langue des Elfes de la nuit. La Grande Fracture a brisé le continent il y a dix mille ans. L’anneau a sombré avec la cité sous les flots et repose aujourd’hui sous les eaux de la grève de Zoram."},{t="Les nagas s’en emparent",b="Pendant des millénaires, les sédiments et les ruines ont caché l’anneau. Puis les nagas ont commencé à fouiller la côte d’Orneval, et Ruuzel, leur chef sur un îlot au large de la partie nord de la grève, l’a découvert parmi les débris engloutis. L’érudit elfe de la nuit Talen le recherche pour bien plus que son ancienneté. L’anneau est la seule clé permettant d’ouvrir les reliques récupérées dans les profondeurs, dont des statuettes antiques scellées au fond de la mer."}},faq={{q="À quoi sert l’Anneau de Zoram ?",a="Avant que la Grande Fracture n’engloutisse Zoram, ses dirigeants portaient l’anneau, qui servait aussi de clé à une ancienne serrure. Talen le cherche aujourd’hui pour ouvrir une statuette verrouillée, récupérée dans les ruines submergées.",al={"utilité de l’anneau de zoram","que fait l’anneau","histoire de l’anneau de zoram"}},{q="Qui détient l’Anneau de Zoram ?",a="Les nagas qui envahissent la grève de Zoram ont remonté l’anneau des ruines. Leur chef Ruuzel le détient sur une île au large de la côte nord, mais la célèbre naga Lady Vespia a également été vue en sa possession.",al={"qui détient l’anneau","butin de l’anneau de zoram","où trouver l’anneau de zoram"}},{q="Pourquoi Talen veut-il l’anneau ?",a="Talen veut percer les secrets d’une statuette antique récupérée dans la grève de Zoram. Sans l’Anneau de Zoram, qui lui sert de clé, le mécanisme de la statuette ne peut être ouvert.",al={"pourquoi talen veut l’anneau","quête de talen et de l’anneau"}},{q="Qu’est devenue la cité de Zoram ?",a="Avant la Grande Fracture, Zoram était une cité des Elfes de la nuit située à l’ouest de Kalimdor. Lorsque le Puits d’éternité a implosé il y a dix mille ans, la cité a été détruite et engloutie par les flots. Seule la grève de Zoram a subsisté.",al={"qu’est-il arrivé à zoram","histoire de la cité de zoram"}}},fx={["7e40c0d5"]={q="Qu'est-ce que l'Anneau de Zoram ?",a="L'Anneau de Zoram est une relique ancienne autrefois portée par les souverains de la cité engloutie de Zoram, avant que les vagues du Grand Cataclysme ne l'immergent. Un code étrange est inscrit à l'intérieur de l'anneau dans la langue des elfes de la nuit, et il est la clé de l'antique serrure d'une statuette récupérée dans les ruines.",al={"qu'est-ce que l'anneau de zoram","lore de l'anneau de zoram","objet anneau de zoram"}},["770adfa7"]={q="D'où vient l'Anneau de Zoram, et qui l'a fabriqué ?",a="L'anneau provient de la cité elfe de la nuit de Zoram, située sur la côte de l'ancien Kalimdor avant le Cataclysme. Il appartenait aux souverains de la cité avant que des raz-de-marée cataclysmiques n'engloutissent Zoram il y a dix mille ans, laissant la relique perdue en mer jusqu'à ce que les nagas ne la draguent récemment des ruines.",al={"origine de l'anneau de zoram","qui a créé l'anneau de zoram","d'où vient l'anneau de zoram"}}},fp="13,163,23.386.0,23.375.0,35.192.0,32.200.0,29.173.0,31.228.0"}
P.entries["item:robo-mechanical-guts"] = {n="Entrailles mécaniques de robot",s="À Hurlevent, Shoni récupère des pièces sur les machines errantes de Gnomeregan. Elles lui serviront à réparer les véhicules de forage conçus pour reconquérir la cité de Dun Morogh.",h="À Hurlevent, Shoni récupère des pièces sur les machines errantes de Gnomeregan.",kw={"mécanismes d’horlogerie","dun morogh","gnomeregan","gyrodrillmatic excavationators","entrailles mécaniques de robot","shoni","hurlevent"},ang={["profession:Engineering"]="Chaque enchevêtrement de câbles et chaque engrenage gyroscopique proviennent de mécanismes automatisés gnomes. Les radiations et l’isolement ont transformé les machines, qui errent désormais sans but.",["race:Gnome"]="En tant que gnome, récupérer les pièces des sentinelles d’horlogerie rebelles de votre foyer perdu peut avoir un goût doux-amer. Leurs mécanismes fournissent des pièces qui aideront à reconquérir Gnomeregan."},sec={{t="Récupération pour la flotte",b="Après la fuite du Grand Bricoleur Gelbin Mekkanivelle et des gnomes survivants de Gnomeregan, des milliers de machines sont restées sur place. Des mécanismes automatisés, des sentinelles d’horlogerie et des robots industriels errent encore dans les couloirs de la ville radioactive.\n\nÀ Hurlevent, la bricoleuse Shoni assemble des Gyrodrillmatic Excavationators pour percer les défenses de Gnomeregan et reconquérir la cité perdue. Elle envoie des aventuriers dans les salles contaminées récupérer des pièces encore utilisables sur les robots, notamment des ressorts, des câbles et des composants gyroscopiques."}},faq={{q="À quoi servent les entrailles mécaniques de robot ?",a="À Hurlevent, Shoni récupère des Entrailles mécaniques de robot pour réparer des Gyrodrillmatic Excavationators. Ces véhicules de forage doivent aider à reconquérir Gnomeregan, à Dun Morogh.",al={"utilité des entrailles mécaniques de robot","utilisation des entrailles mécaniques de robot","pourquoi récupérer des entrailles mécaniques"}},{q="Où trouver ces composants ?",a="Vous pouvez récupérer ces composants sur les automates d’horlogerie hostiles, les méchas et les créatures contaminées qui errent dans les abords et les profondeurs de Gnomeregan.",al={"où trouver des entrailles mécaniques de robot","lieu d’obtention des entrailles de robot","pièces de robot de gnomeregan"}},{q="Qui est Shoni, et pourquoi a-t-elle besoin d’autant de pièces ?",a="Shoni est une ingénieure gnome postée dans le Quartier des Nains de Hurlevent. Elle a besoin de pièces pour préparer près de quatre cents machines d’excavation souterraines destinées à percer les ruines occupées de Gnomeregan.",al={"qui est shoni","shoni à hurlevent","flotte de gyrodrillmatic excavationators"}}},fx={b1d0efc3={q="Qu'est-ce que les Robo-Mechanical Guts ?",a="Il s'agit des mécanismes internes emmêlés, des engrenages, du câblage et des composants mécaniques récupérables arrachés aux automates à rouages qui errent dans Gnomeregan. Bien qu'ils ne soient que de la ferraille pour un œil non averti, ces entrailles fonctionnelles fournissent des mécanismes bruts cruciaux que des ingénieurs gnomes ingénieux peuvent réutiliser pour des projets de véhicules complexes.",al={"que sont les robo-mechanical guts","objet robo-mechanical guts","que sont les boyaux mécaniques"}},cf2ae288={q="D’où proviennent les Robo-Mechanical Guts et qui les a fabriqués ?",a="Ces assemblages ont été créés dans les ateliers de Gnomeregan par des inventeurs gnomes afin d’alimenter leur main-d’œuvre automatisée et les défenses de la ville. Lorsque le désastre radioactif a frappé et que le grand bricoleur Mekkatorque a ordonné l’évacuation, d’innombrables constructions mécaniques ont été abandonnées sur place, où elles continuent d’errer dans les passages en ruines avec leurs mécanismes internes toujours intacts.",al={"qui a fabriqué les robo-mechanical guts","d’où viennent les robo-mechanical guts","origine des robo-mechanical guts"}},f52d09f9={q="Pourquoi quelqu’un voudrait-il des Robo-Mechanical Guts ?",a="Shoni la Shilencieuse, à Hurlevent, en a désespérément besoin comme pièces de rechange pour réparer toute une flotte de gyrodrillmatic excavationators. Avec des réserves limitées dans la capitale humaine, elle se tourne vers les mécas renégats de Gnomeregan, considérés comme une immense casse, pour maintenir sa flotte d’ingénierie opérationnelle.",al={"pourquoi collecter des robo-mechanical guts","qui veut des robo-mechanical guts","pourquoi shoni veut-elle des robo-mechanical guts"}}},fp="20,161,21.513.0,39.171.0,35.145.0,49.191.0"}
P.entries["item:roc-gizzard"] = {n="Roc Gizzard",s="Les Roc Gizzards proviennent des rocs de Tanaris. Dans les Hinterlands, Rhapsody Shindigger en veut trois pour préparer une boisson corsée.",h="Les Roc Gizzards proviennent des rocs de Tanaris.",kw={"fire roc","kalimdor kocktail","rhapsody shindigger","roc","roc gizzard","searing roc","tanaris"},sec={{t="Une boisson plus corsée",b="Dans les Hinterlands, Rhapsody Shindigger vous demande de lui apporter trois Roc Gizzards de Tanaris. Il en a besoin pour préparer un Kalimdor Kocktail, avec des foies de Féralas. Rhapsody dit que cette boisson l’aidera à raconter un vol terrifiant au-dessus d’un marais."}},faq={{q="D’où viennent les Roc Gizzards ?",a="Les Rocs, Fire Rocs et Searing Rocs de Tanaris donnent des Roc Gizzards.",al={"emplacement du roc gizzard","où trouver des gésiers","parties de roc à tanaris"}},{q="Qui a besoin de Roc Gizzards ?",a="Rhapsody Shindigger, dans les Hinterlands, a besoin de trois Roc Gizzards pour son Kalimdor Kocktail.",al={"qui veut des roc gizzards","rhapsody et les gésiers","gésiers pour qui"}},{q="Qu’est-ce qu’un Kalimdor Kocktail ?",a="C’est une boisson corsée que Rhapsody Shindigger compte préparer avec des Roc Gizzards et des foies de Féralas.",al={"boisson de rhapsody","quelle boisson demande des gésiers","cocktail de kalimdor"}},{q="Pourquoi Rhapsody veut-il cette boisson ?",a="Rhapsody dit qu’il lui faut quelque chose de fort avant de pouvoir parler d’un vol terrifiant au-dessus d’un marais.",al={"pourquoi rhapsody a besoin d’une boisson","qu’est-ce qui le fait parler","récit du marais de rhapsody"}}},fp="11,115,16.246.0,32.64.0,23.90.0,28.97.0,33.97.0"}
P.entries["item:rock-elemental-shard"] = {n="Rock Elemental Shard",s="Les Rock Elemental Shards sont des fragments récupérés sur des élémentaires de roche dans les Terres Ingrates. Jarkal Mossmeld en a besoin parmi plusieurs composants pour réapprovisionner ses stocks d’alchimie.",h="Les Rock Elemental Shards sont des fragments récupérés sur des élémentaires de roche dans les Terres Ingrates.",kw={"composants d’alchimie","terres ingrates","jarkal mossmeld","kargath","rock elemental shard","élémentaires de roche"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez apporter à Jarkal Mossmeld, à Kargath, les composants des Terres Ingrates. Il vous offrira des pièces en échange."},sec={{t="Composants de pierre",b="À Kargath, Jarkal Mossmeld demande cinq Rock Elemental Shards, ainsi que des buzzard gizzards et des crag coyote fangs. Alchimiste, il cherche à réapprovisionner ses stocks et promet des pièces pour les composants récoltés."}},faq={{q="À quoi servent les Rock Elemental Shards ?",a="Jarkal Mossmeld, à Kargath, a besoin de cinq Rock Elemental Shards pour réapprovisionner ses stocks d’alchimie.",al={"utilité des fragments","pourquoi les fragments","besoins de jarkal"}},{q="D’où viennent les Rock Elemental Shards ?",a="Les Rock Elemental Shards proviennent des élémentaires de roche des Terres Ingrates.",al={"origine des fragments","où trouver les fragments","obtenir des fragments de roche"}},{q="Qui veut ces fragments ?",a="Jarkal Mossmeld, un alchimiste de Kargath, demande cinq Rock Elemental Shards.",al={"qui veut les fragments","fragments pour jarkal","qui est jarkal"}},{q="De quoi d’autre Jarkal a-t-il besoin ?",a="Jarkal demande aussi cinq buzzard gizzards et dix crag coyote fangs.",al={"autres composants","besoins de jarkal","gésiers et crocs"}}},fp="20,168,14.210.0,35.95.0,41.64.0,21.78.0,27.69.0"}
P.entries["item:rocket-car-parts"] = {n="Pièces de chariot explosif",s="Dans les Salines, des pièces de chariot explosif jonchent le sol après les accidents de la Piste des mirages. Les pilotes gnomes et gobelins poussent leurs bolides expérimentaux à toute vitesse, tandis que des marchands récupèrent les épaves pour les revendre aux équipes.",h="Dans les Salines, des pièces de chariot explosif jonchent le sol après les accidents de la Piste des mirages.",kw={"ingénierie","gnome","gobelin","kravel koalbarbe","piste des mirages","pièces de chariot explosif","récupération","les salines","mille pointes"},ang={["profession:Engineering"]="Des engrenages brûlés et des échappements broyés jonchent les salines, témoins des extrêmes auxquels se livrent les ingénieurs gnomes et gobelins.",["race:Dwarf"]="Les gnomes et les gobelins se concentrent sur la course, tandis que les nains comme Kravel Koalbarbe peuvent tirer profit des épaves abandonnées."},sec={{t="Vitesse, épaves et commerce",b="À la Piste des mirages, dans les Salines, les ingénieurs gnomes et gobelins rivalisent avec acharnement. Leurs pilotes cherchent à gagner toujours plus de vitesse sur terre. Pannes, ratés et collisions dispersent du métal sur les étendues salées, où récupérateurs et marchands ne tardent pas à se rassembler.\n\nLe nain Kravel Koalbarbe engage des voyageurs pour fouiller la vaste étendue éclatante et ramasser les débris. Les deux équipes de course ont besoin de pièces détachées pour leurs prochains prototypes : les épaves peuvent donc retourner aux équipes dont les bolides les ont laissées derrière eux."}},faq={{q="D'où viennent toutes ces pièces de chariot explosif ?",a="Les pièces de chariot explosif proviennent des collisions, des explosions et des pannes mécaniques sur la Piste des mirages. Les pilotes gnomes et gobelins lancent leurs véhicules expérimentaux à propulsion de fusée à travers les salines des Mille pointes, jusqu'à ce qu'ils se disloquent.",al={"pourquoi des pièces jonchent les salines","origine des débris de chariot explosif","d'où viennent les pièces"}},{q="Qui achète ces débris récupérés ?",a="Des marchands comme le nain Kravel Koalbarbe achètent les épaves ramassées par les voyageurs. Ils revendent engrenages, blindages et autres pièces aux gnomes et aux gobelins, qui ont besoin de matériaux pour réparer et améliorer leurs bolides de course.",al={"qui veut des pièces de chariot explosif","pièces de fusée de kravel koalbarbe","qui achète les épaves"}},{q="La récupération des pièces est-elle dangereuse ?",a="Les épaves elles-mêmes sont inertes, mais le métal peut porter les traces sinistres des collisions, notamment des appendices sectionnés qui y sont pris. Des basilics, des scorpides calcinés et des vautours des salines prédateurs rôdent près des débris.",al={"peut-on ramasser les pièces sans danger","dangers pendant la récupération des pièces"}},{q="Les gnomes et les gobelins se soucient-ils que les pièces viennent de bolides accidentés ?",a="Les pilotes gnomes et gobelins réutilisent volontiers les pièces. Ils veulent des mécanismes fonctionnels, des engrenages et des blindages pour construire des bolides assez rapides pour se distancer les uns les autres sur la piste.",al={"les pilotes se soucient-ils des épaves","pourquoi les gobelins réutilisent-ils les débris"}}},fx={["9a01e74a"]={q="Que sont les Pièces de chariot explosif ?",a="Il s’agit des débris éparpillés après des accidents de course à grande vitesse dans les Salines. Composés d’engrenages, de cylindres, de plaques de métal tordues et de gadgets de récupération, ces restes étaient autrefois fixés sur les engins expérimentaux rugissants construits par les pilotes gobelins et gnomes participant à la Piste des mirages.",al={"que sont les pièces de chariot explosif","lore des pièces de chariot explosif","que sont ces pièces"}}},fp="16,216,34.487.0,46.227.0,31.210.0,36.213.0,68.161.0"}
P.entries["item:rod-of-channeling"] = {n="Bâtonnet de canalisation",s="Dans les Paluns, les lanceurs de sorts Dragonmaw portent le Bâtonnet de canalisation. Strahad Farsan en a besoin de trois pour que ses acolytes stabilisent un cercle d’invocation de chasseur corrompu à Cabestan.",h="Dans les Paluns, les lanceurs de sorts Dragonmaw portent le Bâtonnet de canalisation.",kw={"campement de hargnecroc","gardien des os","dragonmaw","chasseur corrompu","bâtonnet de canalisation","gardien des ombres","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="En tant que démoniste, vous rassemblez trois Bâtonnets de canalisation au cours des épreuves du Tome of the Cabal. Ils aident à contenir le rituel tandis que vous liez votre premier chasseur corrompu."},sec={{t="Instruments de liaison",b="La volonté seule ne suffit pas aux démonistes pour lier un chasseur corrompu. Strahad Farsan demande trois bâtonnets assortis afin que ses acolytes canalisent leur magie ensemble et stabilisent le cercle d’invocation pendant que le démoniste lie la bête. Les lanceurs de sorts maléfiques Dragonmaw portent ces bâtonnets pour leurs propres rituels.\n\nAu Campement de Hargnecroc et dans les ruines des Paluns alentour, les gardiens des os Dragonmaw et les gardiens des ombres portent ces bâtonnets. Les combats les usent et les ébrèchent, mais ils focalisent toujours l’énergie chaotique du Néant."}},faq={{q="À quoi sert le Bâtonnet de canalisation ?",a="Strahad Farsan, au-dessus de Cabestan, a besoin des bâtonnets pour ses acolytes. Ils canalisent la magie afin de stabiliser le cercle où un démoniste invoque et lie un chasseur corrompu hostile.",al={"qu’est-ce que le bâtonnet de canalisation","utilité du bâtonnet de canalisation","pourquoi ai-je besoin du bâtonnet de canalisation"}},{q="Où trouver des Bâtonnets de canalisation ?",a="Les lanceurs de sorts Dragonmaw portent ces bâtonnets dans les Paluns. Les gardiens des os Dragonmaw et les gardiens des ombres en portent autour du Campement de Hargnecroc.",al={"où trouver des bâtonnets de canalisation","qui donne le bâtonnet de canalisation","emplacement du bâtonnet de canalisation"}},{q="Pourquoi Strahad a-t-il besoin de trois bâtonnets ?",a="Les acolytes de Strahad participent au rituel d’invocation du chasseur corrompu. Chacun a besoin d’un focalisateur pour stabiliser le conduit pendant que le démoniste soumet la bête.",al={"pourquoi trois bâtonnets","pourquoi trois bâtonnets de canalisation"}},{q="Pourquoi les Dragonmaw utilisent-ils ces bâtonnets ?",a="Le clan Dragonmaw utilise ces bâtonnets dans son chamanisme obscur et sa magie des ombres, héritages de la Old Horde. Ses gardiens des os et gardiens des ombres canalisent des malédictions, la nécromancie et la Shadow Magic dans leurs guerres territoriales qui se poursuivent dans les Paluns.",al={"bâtonnets dragonmaw","pourquoi les dragonmaw en ont-ils"}}},fx={af4e8f1c={q="Qu’est-ce qu’un Bâtonnet de canalisation ?",a="Un Bâtonnet de canalisation est un foyer arcanique utilisé par les lanceurs de sorts pour concentrer et canaliser des énergies magiques volatiles. Bien qu’initialement maniés par les sombres lanceurs de sorts du clan Gueule-de-Dragon dans les Paluns, ces bâtonnets sont des instruments rituels puissants, capables de stabiliser des invocations de haut niveau lorsqu’ils sont manipulés par des démonistes expérimentés.",al={"qu’est-ce qu’un bâtonnet de canalisation","lore du bâtonnet de canalisation","à propos du bâtonnet de canalisation"}}},fp="17,163,22.464.0,39.158.0,38.133.0,33.140.0,39.227.0"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="Médaillons de Rolf et Malakai",s="Dans l’est de la Forêt d’Elwynn, les Médaillons de Rolf et Malakai portent l’insigne du royaume, mais leurs propriétaires ont disparu en patrouille. Le Garde Thomas cherche ces insignes pour découvrir ce qui est arrivé à ses hommes.",h="Dans l’est de la Forêt d’Elwynn, les Médaillons de Rolf et Malakai portent l’insigne du royaume, mais leurs...",kw={"val d'est","forêt d’elwynn","garde thomas","malakai","médaillons","murloc","rolf","garde de hurlevent"},ang={["faction:Alliance"]="Même au cœur de l’Alliance, les gardes locaux affrontent des dangers mortels en protégeant les routes commerciales rurales.",["race:Human"]="Pour les habitants de la Forêt d’Elwynn, ces insignes marquent la perte de fils et de défenseurs. Leur mort révèle la vulnérabilité du royaume, dont les forces militaires sont occupées ailleurs."},sec={{t="Une sinistre confirmation",b="Le Garde Thomas commande le poste dans l’est de la Forêt d’Elwynn. Quand Rolf et Malakai ont disparu le long des berges, il a craint le pire. Leurs médaillons confirment que les gardes sont morts aux mains des murlocs qui avançaient. La garnison de Hurlevent a perdu des soldats qui tenaient la ligne face aux menaces de la nature sauvage, alors que les forces militaires du royaume étaient dispersées."},{t="Insignes de service",b="Les gardes humains portent des médaillons d’identification lors des rondes en ville et des patrouilles rurales. Ces insignes attestent de leur allégeance et de l’autorité que leur confère la couronne. Rapporter les médaillons de Rolf et Malakai au Garde Thomas lui permet de rendre compte de ses hommes disparus et de consigner leur sacrifice dans son rapport de terrain. Il peut aussi avertir des tribus de murlocs agressives qui s’installent près des routes commerciales."}},faq={{q="Que sont les Médaillons de Rolf et Malakai ?",a="Les Médaillons de Rolf et Malakai sont des insignes d’identification de service portés par les gardes de Hurlevent. Des murlocs ont tendu une embuscade aux gardes et les ont tués alors qu’ils étaient postés dans l’est de la Forêt d’Elwynn.",al={"que sont les médaillons","médaillon de rolf","médaillon de malakai"}},{q="À qui appartiennent ces médaillons ?",a="Les médaillons appartenaient aux gardes Rolf et Malakai. Ils servaient sous les ordres du Garde Thomas et surveillaient la rivière et les routes entre Comté-de-l’Or et le Camp de bûcherons du Val d'est.",al={"qui étaient rolf et malakai","à qui sont les médaillons"}},{q="À qui dois-je remettre ces médaillons ?",a="Remettez les médaillons au Garde Thomas. Il monte la garde près du pont est, sur la route entre Comté-de-l’Or et le Camp de bûcherons du Val d'est.",al={"qui veut les médaillons","où remettre ces médaillons","remise des médaillons"}},{q="Pourquoi ces médaillons sont-ils importants pour le Garde Thomas ?",a="Le Garde Thomas avait envoyé les deux gardes en patrouille et craignait qu’un sort funeste ne leur soit arrivé. Leurs médaillons confirment leur mort et lui permettent de consigner leur sacrifice et d’avertir Hurlevent de la menace grandissante des murlocs.",al={"pourquoi thomas les veut","réaction du garde thomas"}}},fp="29,178,19.339.0,17.358.0,39.180.1,34.161.0,39.135.0,51.197.1"}
P.entries["item:roon-s-kodo-horn"] = {n="Roon's Kodo Horn",s="La Corne de kodo de Roon Wildmane est un cadeau d’un chasseur tauren de Désolace. Elle porte une invitation à Hemet Nesingwary, dans la Vallée de Strangleronce, et rappelle l’époque où ils chassaient ensemble.",h="La Corne de kodo de Roon Wildmane est un cadeau d’un chasseur tauren de Désolace.",kw={"désolace","campement grom'gol","hemet nesingwary","corne de kodo","roon","roon wildmane","corne de kodo de roon","vallée de strangleronce"},ang={["race:Dwarf"]="En tant que nain, vous portez un cadeau qui rappelle l’amitié entre Hemet et Roon Wildmane, malgré l’animosité entre leurs peuples.",["race:Tauren"]="En tant que Tauren, vous connaissez peut-être la corne comme le cadeau de Roon Wildmane à Hemet Nesingwary, porteur de ses salutations."},sec={{t="Un cadeau de chasseur",b="Hemet Nesingwary chasse dans la Vallée de Strangleronce, au nord du Campement Grom'gol. Il y a longtemps, il chassait aux côtés de Roon Wildmane en Désolace, et tous deux ont mis de côté l’hostilité entre leurs peuples. Roon vous confie sa corne de kodo pour que vous la portiez au nain, afin qu’ils puissent un jour chasser de nouveau ensemble. Ce cadeau porte les salutations d’un ancien compagnon de chasse."}},faq={{q="Qui est Roon ?",a="Roon Wildmane est un chasseur taurène de Désolace qui chassait autrefois aux côtés de Hemet Nesingwary.",al={"roon","roon wildmane","chasseur taurène"}},{q="Pourquoi offrir la corne à Hemet ?",a="Roon envoie la corne en cadeau et souhaite bon retour à Hemet Nesingwary, son ancien compagnon de chasse.",al={"pourquoi une corne","cadeau de roon","corne pour hemet"}},{q="Où puis-je trouver Hemet ?",a="Hemet Nesingwary se trouve dans la Vallée de Strangleronce, au nord du Campement Grom'gol.",al={"où est hemet","emplacement de hemet","hemet dans la vallée de strangleronce"}},{q="Qui était le père de Hemet ?",a="Roon ne mentionne jamais de père. Le nain qui chassait les grands fauves avec lui en Désolace est Hemet Nesingwary lui-même, désormais installé dans la Vallée de Strangleronce.",al={"père de hemet","hemet senior","vieux hemet"}},{q="Que représente la corne pour Roon ?",a="La corne est un cadeau de Roon à Hemet Nesingwary et porte ses salutations.",al={"signification de la corne","pourquoi une corne de kodo","corne de kodo de roon"}},{q="Roon et Hemet s’entendaient-ils bien ?",a="Oui. Roon raconte qu’ils chassèrent ensemble pendant de nombreux jours et oublièrent l’animosité entre leurs peuples.",al={"roon et hemet","amitié entre nains et taurens","étaient-ils amis"}}},fp="16,169,15.318.0,12.90.0,24.96.0,23.66.0,23.142.0,32.71.0,29.102.0"}
P.entries["item:rot-blossom"] = {n="Racine pourrie",s="Dans le Bois de la Pénombre, les Racines pourries poussent sur les tombes profanées, nourries par la terre souillée et les restes de morts-vivants. Leurs propriétés alchimiques répugnantes sont très recherchées.",h="Dans le Bois de la Pénombre, les Racines pourries poussent sur les tombes profanées, nourries par la terre...",kw={"althea bouclenoire","sombre-comté","bois de la pénombre","racine pourrie","skeletal fiend","skeletal horror","cimetière des jardins paisibles","zombie juice"},ang={["faction:Alliance"]="Récolter ces fleurs morbides dans la terre maudite aide aussi les Veilleurs à tenir les squelettes voraces à l’écart des frontières de Sombre-Comté.",["profession:Herbalism"]="Les Racines pourries sont des plantes répugnantes nourries par la pourriture nécrotique et la terre des cimetières, contrairement aux herbes qui poussent sous la lumière et la pluie. Elles offrent un aperçu sinistre de la flore corrompue."},sec={{t="La flore des cryptes",b="Dans le Bois de la Pénombre, les Racines pourries poussent dans la terre profanée des cimetières, notamment au Cimetière des jardins paisibles. Selon les rumeurs locales, elles prennent racine dans les crânes fissurés des Skeletal Horrors et des Skeletal Fiends qui hantent les tumulus. Les habitants de Sombre-Comté les récoltent au prix d’un travail sinistre. Remuer la terre, c’est devoir affronter les morts sans repos."},{t="Un ingrédient macabre",b="Les Racines pourries entrent dans la composition de breuvages locaux. Leurs essences sombres sont nécessaires à la préparation de Zombie Juice, un breuvage répugnant lié à la lutte du Bois de la Pénombre pour survivre. Ceux qui sont envoyés cueillir ces fleurs aident souvent les Veilleurs en abattant les squelettes agités qui errent dans les tombes hantées."}},faq={{q="Où trouver des Racines pourries ?",a="Les Racines pourries poussent dans les cimetières corrompus du Bois de la Pénombre, en particulier au Cimetière des jardins paisibles. Elles jaillissent aussi des restes de morts-vivants squelettiques.",al={"où poussent les racines pourries","lieu où trouver des racines pourries","trouver des racines pourries"}},{q="À quoi servent les Racines pourries ?",a="Les brasseurs et alchimistes locaux utilisent les Racines pourries pour préparer Zombie Juice, un mélange puissant et répugnant.",al={"utilisation des racines pourries","pourquoi récolter des racines pourries","utilité des racines pourries"}},{q="Pourquoi ces fleurs poussent-elles dans les squelettes ?",a="La magie noire qui persiste dans le Bois de la Pénombre infecte la terre et les morts sans repos. Les Racines pourries se nourrissent de corruption nécrotique et de décomposition, et peuvent pousser dans les crânes et les cages thoraciques des squelettes errants.",al={"racines pourries dans les crânes","fleur de skeletal horror","racines pourries et squelettes"}},{q="En quoi récolter des Racines pourries aide-t-il Sombre-Comté ?",a="Récolter des Racines pourries dans des lieux comme le Cimetière des jardins paisibles implique d’abattre les Skeletal Horrors et les Skeletal Fiends qui infestent les lieux. Cela soulage Althea Bouclenoire et les Veilleurs, qui sont à bout de forces.",al={"althea bouclenoire et racines pourries","les veilleurs et racines pourries","aider sombre-comté"}}},fx={["93f3afdd"]={q="Qu’est-ce qu’une Racine pourrie ?",a="Une Racine pourrie est une curiosité botanique morbide qui prend racine dans les cimetières dévastés du Bois de la Pénombre. Plutôt que de pousser dans un sol sain, ces fleurs sinistres prospèrent au milieu de la décomposition, germant notoirement à l’intérieur des crânes creux des horreurs squelettiques et des monstres squelettiques morts-vivants. Imprégnées d’énergies impures, elles sont recherchées par les habitants excentriques qui préparent des concoctions puissantes à partir de cette pourriture.",al={"que sont les racines pourries","objet racine pourrie","qu’est-ce qu’une racine pourrie"}}},fp="11,152,19.329.0,21.281.0,32.165.0,31.94.0,40.188.0,47.215.0"}
P.entries["item:rot-hide-ichor"] = {n="Ichor de Poil-putride",s="Au Sépulcre, l’Apothicaire Renferrel recueille de l’ichor de Poil-putride pour la Société royale des apothicaires. Elle espère découvrir ce qui a corrompu les gnolls et comment leur résister.",h="Au Sépulcre, l’Apothicaire Renferrel recueille de l’ichor de Poil-putride pour la Société royale des...",kw={"apothicaire renferrel","ile de fenris","lac lordamere","gnolls de poil-putride","ichor de poil-putride","le sépulcre","forêt des pins-argentés"},ang={["race:Undead"]="En tant que Réprouvés, vous comprenez l’importance de l’étude de cet ichor. Il pourrait fournir des renseignements militaires pour protéger le flanc oriental de la Forêt des Pins-Argentés et faire progresser la maîtrise des sciences de la peste par la Société royale des apothicaires."},sec={{t="Une peste dans le sang",b="Sur l’Ile de Fenris, les gnolls de Poil-putride sont déformés par une corruption contre nature. Leur corps se décompose, mais un ichor nocif coule dans leurs veines et entretient leur chair animée. La Société royale des apothicaires espère que ce fluide révélera ce qui a corrompu la meute et qui la commande depuis le donjon en ruine."},{t="Recherches de l’apothicaire",b="Au Sépulcre, l’Apothicaire Renferrel recueille des fioles d’ichor pour les étudier. Les Réprouvés espèrent isoler les forces chimiques et magiques qui entretiennent les gnolls. Ils pourront alors découvrir les faiblesses de la meute avant d’envoyer des troupes de l’autre côté du Lac Lordamere pour lancer un assaut de grande envergure."}},faq={{q="D’où vient l’ichor de Poil-putride ?",a="L’ichor de Poil-putride provient des gnolls de Poil-putride de l’Ile de Fenris, sur le Lac Lordamere, à l’est du continent de la Forêt des Pins-Argentés.",al={"où trouver l’ichor de poil-putride","comment trouver l’ichor de poil-putride","lieu où trouver l’ichor de gnoll"}},{q="Pourquoi l’Apothicaire Renferrel veut-il cet ichor ?",a="L’Apothicaire Renferrel étudie ce fluide pour découvrir ce qui a corrompu les gnolls et trouver leurs faiblesses physiques ou alchimiques, dont les Réprouvés pourraient tirer parti avant d’attaquer l’île.",al={"pourquoi renferrel a-t-il besoin d’ichor","raison de la quête de renferrel","utilité de l’ichor de poil-putride"}},{q="Les gnolls de Poil-putride sont-ils membres du Fléau ?",a="Les gnolls de Poil-putride sont morts-vivants et déformés par la peste. Les Réprouvés cherchent à découvrir qui ou quoi les a créés et les commande sur l’Ile de Fenris.",al={"les poils-putrides sont-ils membres du fléau","qui contrôle les poils-putrides","que sont les gnolls de poil-putride"}},{q="Tous les gnolls ont-ils cet ichor ?",a="Non. Cet ichor appartient à la meute de Poil-putride, dont la chair et le sang sont corrompus par de funestes fléaux nécromantiques.",al={"tous les gnolls lâchent-ils de l’ichor","sang de gnoll ordinaire"}}},fx={c332bd61={q="Qu’est-ce que l’Ichor de Poil-putride ?",a="L’Ichor de Poil-putride est un fluide étrange et surnaturel qui circule dans le corps des gnolls Poil-putride sur l’île de Fenris. Ce n’est pas du sang ordinaire ; la Société royale des apothicaires pense que cette substance corrompue est directement responsable de la nature tordue, proche des morts-vivants, et de la résilience accrue de ces gnolls.",al={"qu’est-ce que l’ichor de poil-putride","fluide de poil-putride","qu’est-ce que l’ichor"}}},fp="14,168,21.303.0,19.267.0,36.117.0,46.166.0,32.142.0,30.109.0"}
P.entries["item:rough-quartz"] = {n="Quartz brut",s="À Durotar, un chaman reçoit du Quartz brut d’une Manifestation de terre mineure. Un ancien lie la pierre au premier Totem de terre du chaman.",h="À Durotar, un chaman reçoit du Quartz brut d’une Manifestation de terre mineure.",kw={"call of earth","canaga hucheterre","totem de terre","manifestation de terre mineure","quartz brut","vallée des épreuves"},ang={["class:Shaman"]="En tant que chaman, le Quartz brut marque votre première communion avec l’élément de la terre. Il ancre vos sorts et marque votre voie comme canal des esprits."},sec={{t="Cœur du Totem de terre",b="À Durotar ou à Mulgore, une Manifestation de terre mineure donne du Quartz brut à un chaman qui communie avec les esprits. Pour un œil non exercé, la pierre ressemble à un simple caillou du désert. Elle représente l’endurance, la patience et une force inébranlable.\n\nDans la Vallée des épreuves, Canaga Hucheterre lie le quartz à du bois sculpté pour façonner un Totem de terre. La pierre devient le point focal spirituel qui unit un jeune chaman au sol vivant d’Azeroth."}},faq={{q="À quoi sert le Quartz brut ?",a="Un chaman ancien lie le Quartz brut au premier Totem de terre d’un novice, où il forme le cœur spirituel. Il montre aussi que le novice a communié avec l’esprit élémentaire de la terre.",al={"à quoi sert le quartz brut","utilisation du quartz brut","pourquoi ai-je besoin de quartz brut"}},{q="Qui vous donne le Quartz brut ?",a="Une Manifestation de terre mineure vous donne du Quartz brut après que vous avez communié avec l’esprit lors du rituel de l’Appel de la Terre, à Durotar ou à Mulgore.",al={"où trouver du quartz brut","qui donne du quartz brut"}},{q="À qui dois-je apporter cette pierre à Durotar ?",a="Apportez le Quartz brut à Canaga Hucheterre, l’instructeur des chamans de la Vallée des épreuves. Canaga le façonne en Totem de terre.",al={"où remettre le quartz brut","remettre le quartz brut","qui prend le quartz brut"}},{q="Ce quartz sert-il à autre chose ?",a="Non. Le Quartz brut est un objet rituel sacré qui sert à fabriquer un Totem de terre. Il n’a aucune utilité dans le commerce courant.",al={"puis-je vendre le quartz brut","le quartz brut sert-il à fabriquer quelque chose"}}},fx={f25f16be={q="Qu’est-ce que le Quartz brut ?",a="Le Quartz brut est un petit caillou élémentaire donné aux aspirants chamans par une Manifestation de terre mineure. Bien que modeste par sa taille et son apparence, la pierre représente la réussite du rite de la terre par l’initié et sa communion avec l’esprit élémentaire, servant de preuve tangible de leur lien.",al={"qu’est-ce que le quartz brut","objet quartz brut","signification du quartz brut"}},["871e2ee1"]={q="Pourquoi Canaga Hucheterre veut-il le Quartz brut ?",a="Canaga Hucheterre a besoin du Quartz brut pour prouver que vous avez entendu l’appel et communié avec l’esprit élémentaire. Il utilise le caillou comme cœur de votre premier Totem de terre, vous permettant de communier davantage avec la terre et de lancer des sorts directement liés à son pouvoir.",al={"pourquoi avoir besoin de quartz brut","but du quartz brut","pourquoi apporter le quartz brut à canaga"}}},fp="12,143,24.439.0,40.172.0,31.143.0,40.127.0,38.102.0"}
P.entries["item:rumbleshot-s-ammo"] = {n="Munitions de Grondetrait",s="Près de L’antre Gris, les Munitions de Grondetrait gisent abandonnées dans la neige. Leur coursier a fui les wendigos affamés avant que la caisse n’atteigne l’armurier Hegnar Grondetrait, à Dun Morogh.",h="Près de L’antre Gris, les Munitions de Grondetrait gisent abandonnées dans la neige.",kw={"munitions","caisse","dun morogh","l'antre gris","hegnar","loslor","grondetrait","wendigo"},ang={["class:Hunter"]="Si vous chassez à Dun Morogh, veillez à ce que la poudre de Hegnar reste sèche et ses munitions bien approvisionnées. Les armes à feu naines ont besoin d’un approvisionnement régulier en munitions.",["profession:Engineering"]="En tant qu’ingénieur, vous avez besoin de munitions et de poudre pour tester les armes à feu que vous fabriquez et vos armes expérimentales."},sec={{t="Une cargaison égarée",b="Hegnar Grondetrait tient une armurerie au bord du chemin de montagne qui va de la Passe des Frigères vers Courbenclume. Les fusiliers de Forgefer, les montagnards et les équipes de mortiers naines s’entraînent dans les hauteurs enneigées ; ses réserves s’épuisent donc aussi vite que la poudre brûle.\n\nLoslor a expédié les munitions depuis Kharanos, mais la cargaison n’a jamais atteint les étagères. Son coursier a dressé son camp trop près de L’antre Gris. Quand les wendigos ont attaqué, il a fui, pris de panique, et laissé la lourde caisse sur leur territoire de chasse."}},faq={{q="Qui est Hegnar Grondetrait ?",a="Hegnar Grondetrait est un armurier nain qui tient boutique près de la route menant à Courbenclume. Il fournit les tireurs, les chasseurs et les artilleurs de l’armée qui s’exercent dans les montagnes de Dun Morogh.",al={"grondetrait","qui est hegnar","vendeur d’armes à feu"}},{q="Comment la caisse de munitions s’est-elle perdue ?",a="Un coursier transportant la caisse a dressé son camp près de L’antre Gris. Quand les wendigos qui s’y trouvaient ont attaqué, le coursier effrayé s’est enfui en abandonnant la lourde caisse dans la neige.",al={"pourquoi les munitions ont été perdues","qu’est-il arrivé aux munitions","munitions du coursier"}},{q="Où se trouve L’antre Gris ?",a="L’antre Gris est un réseau de cavernes dans les montagnes, au sud-ouest de Kharanos. Des wendigos y ont établi leur repaire et menacent les voyageurs isolés sur les versants alentour.",al={"emplacement de l’antre gris","où se trouve la caverne des wendigos"}}},fx={["4221fe47"]={q="Qu’est-ce que les Munitions de Grondetrait ?",a="Il s’agit d’une caisse de munitions fraîches destinée à la boutique de Hegnar Grondetrait, le long de la route de Courbenclume. Avec les fusiliers et les équipes de mortiers nains locaux qui s’entraînent constamment à proximité, Hegnar dépend d’envois réguliers et en gros comme celui-ci pour garder ses rayons approvisionnés et ses clients armés.",al={"que sont les munitions de grondetrait","caisse de munitions de grondetrait","que sont ces munitions"}},["008970c2"]={q="D’où proviennent les Munitions de Grondetrait ?",a="La caisse a été fournie et envoyée par Loslor Rudge depuis Kharanos. Malheureusement, le coursier chargé de l’apporter vers le sud-ouest en direction de Courbenclume a été pris en embuscade par des wendigos féroces près de l'antre Gris et s’est enfui, abandonnant toute la cargaison dans la neige.",al={"qui a fabriqué les munitions de grondetrait","d’où proviennent les munitions de grondetrait","qui a envoyé les munitions"}},["6d6b5eaa"]={q="Pourquoi Hegnar Grondetrait a-t-il besoin de ces munitions ?",a="Hegnar est sur le point d’être totalement en rupture de stock. Les montagnards, les fusiliers et les équipes de mortiers des environs consomment de la poudre à canon et des projectiles à un rythme effréné pendant les séances de tir, ce qui fait qu’une foule d’acheteurs impatients attend l’arrivée du nouvel approvisionnement.",al={"pourquoi les munitions de grondetrait sont-elles nécessaires","pourquoi vouloir des munitions de grondetrait","qui a besoin des munitions de grondetrait"}}},fp="17,177,19.477.0,25.175.0,32.152.0,26.171.0"}
P.entries["item:rune-inscribed-parchment"] = {n="Parchemin runique",s="Dans la Vallée des épreuves, Gornek remet aux aspirants chamans orcs un appel de Shikrik. Il les appelle à guider leur peuple et à communier avec les esprits élémentaires.",h="Dans la Vallée des épreuves, Gornek remet aux aspirants chamans orcs un appel de Shikrik.",kw={"durotar","gornek","parchemin","parchemin runique","chaman","shikrik","vallée des épreuves"},ang={["class:Shaman"]="En tant que chaman, vous faites vos premiers pas sur la voie des éléments. Sous la tutelle de Shikrik, vous apprenez le culte des ancêtres et la maîtrise des éléments.",["race:Orc"]="En tant qu’orc, vous portez la sagesse ancestrale en Durotar. La redécouverte des traditions chamaniques est au cœur de la New Horde."},sec={{t="Un appel aux esprits",b="Les nouveaux chamans orcs s’entraînent auprès de surveillants chevronnés dans la Vallée des épreuves. Lors des premières épreuves d’un initié, Gornek lui remet un message couvert de runes, écrit par Shikrik, l’instructeur chamanique local. Il les appelle à approfondir leur lien avec les éléments.\n\nChez les orcs, les chamans font le lien entre les vivants et leurs ancêtres. Le message marque le passage de la force brute à une vénération disciplinée des traditions ancestrales."}},faq={{q="Qu’est-ce que le Parchemin runique ?",a="Dans la Vallée des épreuves, Gornek remet aux novices chamans orcs un message manuscrit. Il leur demande de se présenter à Shikrik pour recevoir un enseignement officiel.",al={"parchemin runique","qu’est-ce que cet objet","parchemin de chaman"}},{q="Qui a écrit le parchemin ?",a="Shikrik, le maître des chamans de la Vallée des épreuves, a écrit le parchemin. Il enseigne aux jeunes initiés les voies des éléments et des esprits ancestraux.",al={"qui a envoyé le parchemin","auteur du parchemin"}},{q="Pourquoi les chamans sont-ils considérés comme des élus chez les orcs ?",a="Les chamans orcs guident leur peuple en tant que chefs spirituels. Ils écoutent les esprits élémentaires et servent de lien avec leurs ancêtres. Shikrik apprend à ses apprentis à soigner leurs alliés et à déchaîner la fureur des éléments contre leurs ennemis.",al={"pourquoi être chaman","rôle du chaman orc"}}},fx={["00232829"]={q="Pourquoi Shikrik veut-elle que vous lisiez le Parchemin runique ?",a="Shikrik a envoyé ce message par l’intermédiaire de Gornek pour vous convoquer directement à elle. Ayant reconnu que vous êtes choisi pour guider la vie spirituelle de votre peuple, elle a l’intention de commencer votre formation formelle à la communion avec les ancêtres, à la maîtrise élémentaire et aux rites d’un chaman orc.",al={"pourquoi lire le parchemin runique","pourquoi shikrik envoie-t-elle le parchemin","but du parchemin runique"}}},fp="24,154,24.414.0,37.140.0,24.153.0,49.220.0"}
P.entries["item:rune-inscribed-pendant"] = {n="Pendentif marqué de runes",s="Dans la Forêt des Pins-Argentés, un Pendentif marqué de runes arrive au Sépulcre dans une cargaison destinée au Moulin-de-l'Ambre. Le Kirin Tor utilise des pendentifs semblables pour canaliser la puissance des arcanes.",h="Dans la Forêt des Pins-Argentés, un Pendentif marqué de runes arrive au Sépulcre dans une cargaison destinée...",kw={"allister","moulin-de-l'ambre","dalar tisselaube","dalaran","kirin tor","pendentif","pendentif marqué de runes","le sépulcre"},ang={["class:Mage"]="En tant que mage, vous reconnaissez le savoir-faire du Kirin Tor dans ces runes. Elles stabilisent les flux instables pendant la canalisation de puissants sorts.",["race:Undead"]="En tant que Réprouvé chargé de garder la Forêt des Pins-Argentés, vous savez que les focalisateurs de Dalaran interceptés, comme ce pendentif, donnent des indices sur la résistance humaine qui se rassemble derrière les murs du Moulin-de-l'Ambre."},sec={{t="Relique du Kirin Tor",b="Un Pendentif marqué de runes se trouve parmi des fournitures cartographiques destinées à l'enclave de Dalaran, au Moulin-de-l'Ambre. Ses fines inscriptions arcaniques révèlent son rôle : focaliser et renforcer les sorts d'un mage. D'autres pendentifs de canalisation arrivent dans la région, et les Réprouvés du Sépulcre se demandent ce que prépare le Kirin Tor."},{t="Un indice sur les projets de Moulin-de-l'Ambre",b="Au Sépulcre, le Prêtre des ombres Allister voit une menace dans la position fortifiée des mages de Dalaran. Il envoie le pendentif à Dalar Tisselaube pour l'étudier de plus près. Dawnweaver y reconnaît un élément des opérations des mages. Le Kirin Tor rassemble des focalisateurs arcaniques pour de puissants rituels, défensifs ou offensifs, derrière les frontières de Moulin-de-l'Ambre."}},faq={{q="À quoi sert le Pendentif marqué de runes ?",a="Les mages du Kirin Tor utilisent le pendentif pour canaliser et diriger de puissants flux magiques. Il focalise les sorts complexes.",al={"à quoi sert le pendentif","fonction du pendentif","utilisation du pendentif runique"}},{q="D'où vient ce pendentif ?",a="Le pendentif fait partie d'une cargaison destinée au Moulin-de-l'Ambre, dans la Forêt des Pins-Argentés, où les derniers membres du Kirin Tor se sont retranchés.",al={"où trouver le pendentif","origine du pendentif","où a-t-il été trouvé"}},{q="Qui étudie le pendentif au Sépulcre ?",a="Le Prêtre des ombres Allister examine brièvement le pendentif avec des cartes saisies. Il l'envoie à Dalar Tisselaube, au Sépulcre, qui reconnaît le travail du Kirin Tor.",al={"qui étudie le pendentif","qui veut le pendentif","pendentif de dalaran"}},{q="Pourquoi les Réprouvés s'en inquiètent-ils ?",a="Les grandes cargaisons de pendentifs de canalisation laissent penser que le Kirin Tor, au Moulin-de-l'Ambre, prépare une importante opération magique. Les Réprouvés craignent qu'elle menace leur emprise sur la Forêt des Pins-Argentés.",al={"pourquoi les réprouvés s'en soucient","menace du moulin-de-l'ambre","pourquoi le pendentif est dangereux"}}},fx={bf28d080={q="Qu’est-ce que le Rune-Inscribed Pendant ?",a="Il s’agit d’un artefact arcanique fabriqué et utilisé par les puissants mages de Dalaran. Fréquemment utilisé par le Kirin Tor pour concentrer et canaliser des énergies magiques considérables, ces pendentifs sont des conduits de puissance arcanique plutôt que de simples ornements.",al={"qu’est-ce qu’un rune-inscribed pendant","identité du rune pendant","qu’est-ce que ce pendentif de dalaran"}}},fp="22,166,15.327.0,27.338.1,44.111.0,33.125.0,42.165.0,40.185.0"}
P.entries["item:rune-inscribed-tablet"] = {n="Tablette runique",s="Dans la Vallée des épreuves, Gornek remet un message de pierre aux jeunes chamans trolls sombrelances. Il envoie les mystiques prometteurs auprès de Shikrik pour recevoir un enseignement spirituel officiel.",h="Dans la Vallée des épreuves, Gornek remet un message de pierre aux jeunes chamans trolls sombrelances.",kw={"sombrelance","durotar","gornek","tablette runique","chaman","shikrik","maître","vallée des épreuves"},ang={["class:Shaman"]="En tant que chaman, la tablette marque votre premier pas officiel vers la maîtrise de la terre, du feu, de l'eau et de l'air. Votre force vient des esprits ancestraux.",["race:Troll"]="En tant que troll sombrelance, vous répondez à l'appel d'un maître orc. Cela marque les liens grandissants et la voie spirituelle commune entre votre peuple et ses nouveaux alliés de la Horde."},sec={{t="Un appel aux esprits",b="Gornek remet une pierre gravée de runes aux novices qui font leurs preuves dans la Vallée des épreuves. Le chaman troll Ishi-yo l'envoie à Shikrik, le maître chaman. Pour les Trolls sombrelances, la tablette ouvre une voie commune avec les orcs. Leurs anciennes traditions spirituelles rejoignent l'héritage chamanique renouvelé par le chef de guerre Thrall."}},faq={{q="À quoi sert la Tablette runique ?",a="Gornek remet la tablette aux jeunes chamans trolls dans la Vallée des épreuves. Elle les dirige vers Shikrik pour recevoir un enseignement spirituel officiel.",al={"utilité de la tablette","à quoi sert la tablette","usage de la tablette runique"}},{q="Qui envoie la tablette ?",a="Le chaman troll Ishi-yo envoie la tablette. Elle dirige le novice vers Shikrik, le maître chaman orc juste à l'extérieur de l'Antre, dans la Vallée des épreuves. Shikrik sait qu'ils arrivent.",al={"qui a écrit la tablette","expéditeur de la tablette","qui l'a gravée"}},{q="Qui reçoit cette tablette ?",a="Gornek remet la tablette aux chamans trolls sombrelances qui viennent d'arriver, comme premier appel à leur classe en Durotar.",al={"qui reçoit la tablette runique","quelle classe reçoit la tablette"}}},fx={cd2cca59={q="Qu’est-ce que la Tablette runique ?",a="La Tablette runique est une convocation écrite destinée aux aspirants chamans trolls s’entraînant dans la Vallée des épreuves. Marquée de runes chamaniques, elle sert de message personnel transmis par Gornek pour présenter les recrues prometteuses directement à leur instructeur local.",al={"qu’est-ce qu’une tablette runique","lore de la tablette runique","qu’est-ce que cette tablette"}},["33b46b09"]={q="Pourquoi Shikrik souhaite-t-elle que vous receviez la Tablette runique ?",a="La tablette vient en réalité d'Ishi-yo, le chaman troll qui vous a donné vos premières leçons ; Gornek suppose seulement qu'elle vient de Shikrik. Ishi-yo vous envoie auprès de Shikrik, qui vous attend déjà. Elle souhaite vous enseigner les fondements des éléments et des esprits de vos ancêtres, afin qu'un jour vous puissiez guider et protéger les villages et les villes de la Horde, comme Thrall guide la Horde elle-même.",al={"pourquoi shikrik envoie la tablette","pourquoi cette tablette est nécessaire","shikrik tablette runique"}}},fp="21,159,24.315.0,43.130.0,21.178.0,25.105.0"}
P.entries["item:rune-of-nesting"] = {n="Rune de nidification",s="Au Refuge des saisons de Ban'ethil, la Rune de nidification prépare le rite qui doit éveiller les druides de la Serre. Ils dorment dans le Rêve d'émeraude, et quatre reliques sacrées guident leur retour en toute sécurité.",h="Au Refuge des saisons de Ban'ethil, la Rune de nidification prépare le rite qui doit éveiller les druides de...",kw={"athridas mantelours","refuge des saisons de ban'ethil","chest of nesting","druides de la serre","rêve d'émeraude","relics of wakening","rune de nidification"},ang={["class:Druid"]="En tant que druide, vous savez que la Rune de nidification fait partie des rites sacrés du Cercle cénarien. Elle rappelle le danger auquel sont exposés vos frères endormis lorsque leurs sanctuaires sont profanés.",["race:NightElf"]="En tant qu'elfe de la nuit, vous voyez dans la disparition des reliques d'éveil et la profanation des refuges des signes de corruption croissante parmi la faune et les furbolgs de Teldrassil."},sec={{t="Un foyer sacré pour l'éveil",b="Au fond des salles tortueuses du Refuge des saisons de Ban'ethil, la Rune de nidification se trouve dans le Chest of Nesting. Les druides elfes de la nuit dorment dans des refuges souterrains et communient avec la nature à travers le Rêve d'émeraude.\n\nPour revenir sans danger, les druides de la Serre ont besoin d'un rituel d'éveil minutieux, guidé par des reliques sacrées. La Rune de nidification est l'une des quatre reliques, avec le Talisman de la griffe du corbeau, la Plume noire et le Saphir des cieux. Ensemble, ces reliques rappellent les druides endormis dans le monde éveillé."},{t="Crise à Ban'ethil",b="Des furbolgs Gnarlpine corrompus ont envahi le Refuge des saisons de Ban'ethil, et ses défenseurs endormis sont en péril. Sans les reliques, les druides risquent de rester prisonniers du Rêve d'émeraude tandis que les envahisseurs profanent leur sanctuaire. Récupérer la Rune de nidification et les reliques qui l'accompagnent permet à Athridas Mantelours, à Dolanaar, de préparer le rite qui les éveillera sans danger."}},faq={{q="À quoi sert la Rune de nidification ?",a="Athridas Mantelours a besoin de la Rune de nidification pour préparer le rituel qui éveillera sans danger les druides de la Serre de leur profond sommeil dans le Rêve d'émeraude. C'est l'une des quatre Relics of Wakening utilisées lors du rite.",al={"à quoi sert la rune de nidification","utilité de la rune de nidification"}},{q="Où trouver la Rune de nidification ?",a="La Rune de nidification se trouve dans le Chest of Nesting, dans les tunnels souterrains du Refuge des saisons de Ban'ethil, à l'ouest de Dolanaar, sur Teldrassil.",al={"où trouver la rune de nidification","emplacement du chest of nesting"}},{q="Pourquoi les druides endormis ne peuvent-ils pas simplement se réveiller seuls ?",a="Les druides entrent dans une transe délicate lorsqu'ils dorment dans le Rêve d'émeraude. Sans reliques sacrées ni rituel d'éveil, ils risquent de ne pas pouvoir revenir, laissant leur esprit errer et leur corps en danger.",al={"pourquoi les druides ont besoin d'un rituel d'éveil","pourquoi les druides ne peuvent-ils pas se réveiller seuls"}},{q="Quelles autres reliques faut-il avec la Rune de nidification ?",a="Le rite requiert quatre Relics of Wakening : la Rune de nidification, le Talisman de la griffe du corbeau, la Plume noire et le Saphir des cieux.",al={"autres relics of wakening","objets des relics of wakening"}}},fx={["375c0565"]={q="Qu’est-ce que la Rune de nidification ?",a="La Rune de nidification est l’une des quatre reliques sacrées de l’Éveil gardées par les druides de la Griffe à Teldrassil. Stockée dans un coffre dédié à l’intérieur du Refuge des saisons de Ban'ethil, elle porte les enchantements spécialisés requis pour effectuer correctement le rituel d’éveil des druides reposant en profonde communion avec le Rêve d’émeraude.",al={"rune de nidification","qu’est-ce que la rune de nidification","lore de la rune de nidification"}}},fp="15,179,28.497.0,19.354.0,37.212.0,35.133.0,58.204.0,59.139.0"}
P.entries["item:runes-of-summoning"] = {n="Runes d'invocation",s="À Fossoyeuse, les démonistes invoquent un marcheur du Vide avec les Runes d'invocation. La créature entre dans un cercle où un aspirant démoniste peut la plier à sa volonté.",h="À Fossoyeuse, les démonistes invoquent un marcheur du Vide avec les Runes d'invocation.",kw={"carendin halgar","quartier de la magie","runes d'invocation","the binding","fossoyeuse","marcheur du vide","démoniste"},ang={["class:Warlock"]="En tant que démoniste, vous utilisez les runes pour prouver votre domination sur le Vide et transformer une ombre chaotique en serviteur fidèle et durable.",["race:Undead"]="En tant que Mort-vivant, vous suivez les adeptes réprouvés dans les profondeurs de Fossoyeuse, où ils asservissent des entités du Vide sous les Ruines de Lordaeron, malgré d'anciens interdits."},sec={{t="Asservissement dans le Quartier de la Magie",b="Carendin Halgar remet les Runes d'invocation aux démonistes prêts à commander un marcheur du Vide. Dans le Quartier de la Magie de Fossoyeuse, les adeptes réprouvés étudient la manipulation du Néant. Un démoniste lance les runes dans le cercle d'invocation actif, sous le poste de Halgar. Le rituel déchire le Vide et fait surgir une créature qu'il faut vaincre et asservir."}},faq={{q="À quoi servent les Runes d'invocation ?",a="Un démoniste lance les runes dans le Quartier de la Magie de Fossoyeuse pour faire surgir un marcheur du Vide sans maître depuis le Néant jusque dans le monde physique. Il peut alors le vaincre et le plier à sa volonté.",al={"utilité des runes d'invocation","à quoi servent les runes d'invocation","comment utiliser les runes d'invocation"}},{q="Qui fournit les Runes d'invocation ?",a="Carendin Halgar, le maître démoniste réprouvé du Quartier de la Magie de Fossoyeuse, fournit les runes au dernier stade de l'entraînement pour asservir un marcheur du Vide.",al={"qui donne les runes d'invocation","maître des runes d'invocation","runes de carendin halgar"}},{q="Où faut-il activer les runes ?",a="Apportez les runes au cercle d'invocation violet, juste sous la plateforme de Carendin Halgar dans le Quartier de la Magie.",al={"où utiliser les runes d'invocation","emplacement des runes d'invocation","cercle d'invocation à fossoyeuse"}},{q="Que se passe-t-il après l'invocation de l'entité ?",a="Le marcheur du Vide attaque dès son invocation. Le démoniste doit le maîtriser par la magie et les armes. Une fois vaincue, l'entité est asservie, et Carendin Halgar enseigne le sort permanent qui permet de l'invoquer.",al={"que se passe-t-il après avoir utilisé les runes","marcheur du vide maîtrisé","après l'invocation du marcheur du vide"}}},fx={["1ce5479a"]={q="Que sont les Runes d’invocation ?",a="Les Runes d’invocation sont un catalyseur rituel spécialisé donné aux aspirants démonistes réprouvés de Fossoyeuse. Lorsqu’elles sont apportées au cercle d’invocation du Quartier de la Magie, les runes concentrent des énergies magiques pour ouvrir un passage et attirer un marcheur du Vide non lié depuis le Néant.",al={"que sont les runes d’invocation","runes d'invocation","objet runes d’invocation"}},["0508549c"]={q="Pourquoi Carendin Halgar veut-il que les Runes d’invocation lui soient rendues ?",a="Carendin Halgar fournit les runes spécifiquement comme une épreuve de maîtrise. Une fois que vous les activez et que vous soumettez le marcheur du Vide invoqué au combat, le fait de lui rendre les runes prouve que vous avez dominé la créature, ce qui lui permet de vous enseigner correctement le sort permanent pour invoquer et commander des marcheurs du Vide.",al={"pourquoi rendre les runes d’invocation","pourquoi carendin veut-il les runes","rendre les runes d’invocation"}}},fp="18,188,32.366.0,41.187.0,36.155.0,34.110.0,42.200.0"}
P.entries["item:ryedol-s-lucky-pick"] = {n="Ryedol's Lucky Pick",s="Ryedol’s Lucky Pick est un outil de mineur perdu lors de l’attaque des nains de Shadowforge contre Hammertoe’s Digsite, dans les Terres Ingrates. Le prospecteur Ryedol espère le récupérer.",h="Ryedol’s Lucky Pick est un outil de mineur perdu lors de l’attaque des nains de Shadowforge contre...",kw={"terres ingrates","dark iron","site de fouilles d'hammertoe","pioche porte-bonheur","prospecteur ryedol","ryedol’s lucky pick","shadowforge"},ang={["race:Dwarf"]="En tant que nain, vous pouvez aider le prospecteur Ryedol à récupérer son outil après l’attaque de Shadowforge contre Hammertoe’s Digsite."},sec={{t="Un outil de prospecteur",b="Le prospecteur Ryedol travaille au sud de Hammertoe’s Digsite, dans les Terres Ingrates. Le clan Shadowforge attaqua le site de fouilles et tua presque tout le monde, y compris le patron de Ryedol, Hammertoe. Ryedol s’échappa, mais sa pioche porte-bonheur fut abandonnée sur place. Il vous demande de chercher l’outil parmi les nains Dark Iron."}},faq={{q="À qui appartient Ryedol’s Lucky Pick ?",a="La pioche appartient au prospecteur Ryedol, qui veut la récupérer.",al={"pioche de ryedol","propriétaire de la pioche porte-bonheur"}},{q="Où la pioche a-t-elle été perdue ?",a="La pioche fut abandonnée à Hammertoe’s Digsite, dans les Terres Ingrates, après l’attaque du clan Shadowforge.",al={"lieu où la pioche a été perdue","emplacement de la pioche"}},{q="Qui a Ryedol’s Lucky Pick ?",a="L’un des nains de Shadowforge à Hammertoe’s Digsite a la pioche.",al={"qui a la pioche","pioche de shadowforge"}},{q="Pourquoi Ryedol veut-il récupérer la pioche ?",a="C’est la pioche porte-bonheur de Ryedol, et il vous demande de la reprendre aux nains de Shadowforge.",al={"pourquoi la pioche porte-bonheur","ryedol a besoin de sa pioche"}}},fp="19,156,21.309.0,31.54.0,24.95.0,30.69.0,35.88.0"}
P.entries["item:sack-of-murloc-heads"] = {n="Sac de têtes de murlocs",s="Sur les plages de Hautebrande, un Sac de têtes de murlocs prouve que les menaces côtières sont éliminées. Le lieutenant Farren Orinelle le confie à des aventuriers de passage pour le maréchal Redpath, à Austrivage.",h="Sur les plages de Hautebrande, un Sac de têtes de murlocs prouve que les menaces côtières sont éliminées.",kw={"prime","farren orinelle","têtes","hautebrande","maréchal redpath","murloc","austrivage"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous découvrez les rouages mal huilés et les tâches ingrates du quotidien que les défenseurs d’Austrivage assument pour maintenir l’enclave nord de l’Alliance."},sec={{t="Bureaucratie et nuisibles côtiers",b="Austrivage subit des attaques de hors-la-loi du Syndicat et de tirailleurs réprouvés. Des murlocs sauvages menacent aussi la côte. Les officiers doivent montrer aux dirigeants de la ville que les menaces côtières sont éliminées, afin d’obtenir des fonds et des faveurs. Le lieutenant Farren Orinelle recueille des têtes tranchées comme preuve, bien qu’il trouve cette cargaison répugnante. Son dégoût l’amène à confier le sac à des voyageurs plutôt qu’à porter lui-même ces preuves macabres au maréchal Redpath."}},faq={{q="Qu’est-ce que le Sac de têtes de murlocs ?",a="Le sac contient des têtes de murlocs tranchées, recueillies sur les plages occidentales de Hautebrande. Il apporte au commandant de la garnison d’Austrivage la preuve concrète des efforts déployés pour pacifier la côte.",al={"sac de têtes","sac de murlocs","quel est cet objet"}},{q="Pourquoi le lieutenant Farren ne le livre-t-il pas lui-même ?",a="Le lieutenant Farren Orinelle trouve répugnant de porter un sac de têtes de murlocs en décomposition. Il confie cette livraison déplaisante à un aventurier serviable, chargé de la transporter dans Austrivage.",al={"raison du transport confié par farren","excuse de farren","farren paresseux"}},{q="Qui reçoit le sac ?",a="Le maréchal Redpath reçoit le sac. Il commande les défenses d’Austrivage, évalue la sécurité de la ville et exige des preuves des efforts de défense.",al={"qui reçoit les têtes","lieu de remise","remise au maréchal redpath"}},{q="Pourquoi Austrivage exige-t-elle des têtes de murlocs comme preuve ?",a="Austrivage exige des têtes de murlocs comme preuve, car ces derniers attaquent constamment la côte et menacent le port. Les officiers doivent vérifier que les patrouilles assurent la sécurité du périmètre. Des trophées tangibles aident à s’assurer que les soldats ne s’attribuent pas le mérite de veilles passées à ne rien faire.",al={"pourquoi recueillir des têtes de murlocs","preuve d’élimination"}}},fx={["3f14ed35"]={q="D’où provient le Sac de têtes de murlocs et qui l’a fabriqué ?",a="Le sac est constitué des têtes tranchées des murlocs que vous avez chassés le long de la côte sud des Contreforts de Hautebrande. Le lieutenant Farren Orinelle les a rassemblées pour les présenter à son officier supérieur, bien qu’il vous rende rapidement le colis répugnant pour que vous le livriez à sa place.",al={"qui a fabriqué le sac de têtes de murlocs","d’où provient le sac de têtes","qui a donné le sac de têtes de murlocs"}}},fp="20,217,29.433.0,33.166.0,47.170.0,22.139.0,50.248.0"}
P.entries["item:sack-of-supplies"] = {n="Sac de ravitaillement",s="Dans le Canyon de Tranchevent, les sacs de ravitaillement destinés à Rezlak sont éparpillés parmi les nids des harpies. Les harpies Dustwind se sont emparées des marchandises alors qu’elles traversaient Durotar.",h="Dans le Canyon de Tranchevent, les sacs de ravitaillement destinés à Rezlak sont éparpillés parmi les nids...",kw={"durotar","harpies dustwind","gazlowe","canyon de tranchevent","rezlak","sac de ravitaillement"},ang={["faction:Horde"]="Récupérer le ravitaillement des prédateurs locaux permet aux chantiers frontaliers autour d’Orgrimmar de se poursuivre sans retards coûteux."},sec={{t="Une caravane pillée",b="Rezlak a besoin d’un approvisionnement régulier en marchandises pour son travail à l’extérieur d’Orgrimmar. Gazlowe a engagé l’ingénieur gobelin de Cabestan pour bâtir au service de la Horde. Une caravane transportant un chargement promis est passée près de la route du canyon, au sud d’Orgrimmar. Les harpies Dustwind l’ont prise en embuscade et ont traîné la cargaison dans leurs nids du Canyon de Tranchevent, éparpillant les sacs près de leurs nids, dans la terre et les éboulis."}},faq={{q="Que contiennent ces sacs de ravitaillement ?",a="Les sacs contiennent des matériaux de construction et des marchandises destinés aux travaux d’ingénierie de Gazlowe. Ils doivent soutenir les projets de construction des Orcs près d’Orgrimmar. Sans eux, Rezlak ne peut pas terminer son travail.",al={"contenu des sacs de ravitaillement","que contiennent les sacs","ravitaillement de rezlak"}},{q="Qui a volé le ravitaillement ?",a="Les harpies Dustwind ont volé le ravitaillement. Cette race aviaire sauvage infeste les hautes crevasses et les ravins du Canyon de Tranchevent.",al={"qui a pris le ravitaillement","qui a volé les sacs"}},{q="Qui est Rezlak ?",a="Rezlak est un ingénieur gobelin envoyé par Gazlowe depuis Cabestan pour aider la Horde à construire et à entretenir les infrastructures de première ligne en Durotar.",al={"qui est rezlak","histoire de rezlak"}}},fx={["812e6d27"]={q="D’où proviennent ces sacs de ravitaillement ?",a="Ces sacs faisaient partie d’un envoi expédié vers Durotar au nom de Gazlowe et de ses ingénieurs gobelins. Destinée à aider les orcs à construire et à entretenir leurs colonies, la caravane qui les transportait a été prise en embuscade et pillée sur la route avant de pouvoir atteindre sa destination.",al={"origine du sac de ravitaillement","d’où proviennent les fournitures","qui a fabriqué le sac de ravitaillement"}},["55ee41bd"]={q="Pourquoi Rezlak veut-il ces sacs de fournitures ?",a="Rezlak ne peut pas mener à bien les travaux de construction confiés par Gazlowe sans le matériel et les outils appropriés. Les harpies du Canyon de Tranchevent ont pillé la caravane transportant ses outils et ses provisions, laissant le contremaître gobelin totalement à l'arrêt jusqu'à ce que quelqu'un récupère la cargaison volée.",al={"pourquoi rezlak veut des fournitures","pourquoi avoir besoin de sacs de fournitures","winds in the desert fournitures pourquoi"}}},fp="16,156,19.381.0,34.197.0,23.118.0,14.122.0"}
P.entries["item:salty-scorpid-venom"] = {n="Venin de scorpide acide",s="Dans les Mille pointes, le Venin de scorpide acide attire les gnomes dans une course dangereuse. Les scorpides des Salines tirent les sels minéraux du désert dans leur venin, que les pilotes gnomes convoitent comme carburant.",h="Dans les Mille pointes, le Venin de scorpide acide attire les gnomes dans une course dangereuse.",kw={"féplouf zéboulon","piste des mirages","venin de scorpide acide","scorpid reaver","scorpid terror","venin de scorpide","les salines","mille pointes"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous voyez les inventeurs des Salines chercher au-delà du pétrole et du charbon. Ils testent des toxines organiques comme accélérateurs volatils.",["race:Gnome"]="En tant que gnome, vous connaissez les risques que comporte la transformation d’un venin mortel du désert en carburant pour fusée avec des néga-catalyseurs, tout cela pour gagner quelques secondes sur un tour."},sec={{t="Un agent de combustion volatile",b="Les scorpides des Salines, riches en minéraux, portent du sel dans leur venin. Au fil des générations, les Scorpid Reavers et les Scorpid Terrors ont absorbé les sels de la région. Féplouf Zéboulon et d’autres bricoleurs gnomes prisent ce venin caustique comme additif possible pour un carburant moteur à forte combustion, et non pour des antidotes ou des poisons ordinaires."},{t="La rivalité de la piste",b="Sur la Piste des mirages, les gnomes et les gobelins mettent à l’essai des matériaux toujours plus dangereux dans leurs bolides-fusées. Féplouf Zéboulon pense qu’en faisant bouillir le venin salé, en le traitant avec des catalyseurs spécialisés et en le mélangeant dans les réservoirs de propergol, il donnera à sa voiture la chaleur intense nécessaire pour distancer les pilotes gobelins sur les étendues salées."}},faq={{q="Quelles créatures produisent le Venin de scorpide acide ?",a="Les Scorpid Reavers et les Scorpid Terrors des étendues salées des Mille pointes produisent le Venin de scorpide acide.",al={"qui donne du venin de scorpide acide","où trouver du venin de scorpide","source du venin de scorpide"}},{q="Pourquoi ce venin est-il si salé ?",a="Les scorpides vivent sur le sol couvert de croûtes minérales des Salines. Leur organisme absorbe les sels concentrés de l’ancien lit lacustre asséché, ce qui donne à leur venin une forte salinité.",al={"pourquoi est-il salé","explication du venin des salines","lore sur le sel des scorpides"}},{q="Qui veut ce venin, et pourquoi ?",a="Féplouf Zéboulon, un ingénieur gnome de la Piste des mirages, cherche ce venin pour un mélange de carburant expérimental. Il pense qu’il brûlera assez fort pour propulser sa voiture-fusée jusqu’à la victoire.",al={"qui a besoin de venin de scorpide","pourquoi féplouf veut du venin","objet de quête de féplouf zéboulon"}}},fx={["9840b612"]={q="Qu'est-ce que le Venin de scorpide acide ?",a="C'est un fluide puissant et riche en minéraux récolté sur les scorpides qui rôdent dans Les Salines. Le bassin salé, rude et asséché, a amené les terreurs et les pillards scorpides locaux à développer un venin inhabituellement saturé en sel. Bien que mortel en tant que toxine naturelle, ses propriétés chimiques réactives le rendent bien plus intéressant pour les bricoleurs en tant que réactif brut volatil qu'en tant que simple poison.",al={"qu'est-ce que le venin de scorpide acide","venin de scorpide acide","venin de scorpide plat"}}},fp="19,215,27.321.0,27.317.0,43.99.0,26.173.0,29.181.0"}
P.entries["item:samophlange-item"] = {n="Samophlange",s="Dans les Tarides, le samophlange reste caché dans une console de commande automatisée. Les mécaniciens gobelins ne savent pas expliquer à quoi sert cet étrange composant.",h="Dans les Tarides, le samophlange reste caché dans une console de commande automatisée.",kw={"tarides","console","cabestan","samophlange","krachevalve","union des bricoleurs","undermine"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous reconnaîtrez peut-être dans le samophlange une conception inutilement complexe. Son extérieur ouvragé dissimule un mécanisme si fragile qu’il se brise lorsqu’on le pose au sol."},sec={{t="Un mécanisme déroutant",b="Le samophlange se trouve dans une console de commande des Tarides, derrière un labyrinthe de câbles et de tuyaux creux. Il faut fouiller avec soin pour le déloger de son logement. Il semble essentiel aux mécanismes d’horlogerie et aux machines à vapeur, mais les bricoleurs gobelins ne parviennent pas à découvrir son utilité. Ils comptent l’envoyer à l’Union des Bricoleurs, à Undermine, mais une manipulation brusque pourrait briser cette pièce fragile."},{t="Curiosité et catastrophe",b="Krachevalve, un ingénieur de Cabestan, compte envoyer le samophlange aux esprits les plus éminents de l’Union des Bricoleurs pour qu’ils l’étudient. Pourtant, la curiosité gobeline vient souvent bouleverser ses plans. Quand Krachevalve pose le délicat appareil pour en examiner les rouages, il se brise en morceaux."}},faq={{q="Qu’est-ce qu’un samophlange ?",a="Le samophlange est un étrange composant mécanique extrait d’une console de commande des Tarides. Son utilité est inconnue, et la console qui l’abrite est encombrée de tuyaux et de câbles qui semblent ne servir à rien.",al={"à quoi sert un samophlange","utilité du samophlange","qu’est-ce que cet objet"}},{q="Qui veut le samophlange ?",a="Krachevalve, un ingénieur de Cabestan, veut qu’on lui apporte le samophlange pour l’étudier. Il compte l’envoyer à l’Union des Bricoleurs.",al={"qui a besoin du samophlange","à qui donner le samophlange"}},{q="Que fait Krachevalve avec le samophlange ?",a="Krachevalve compte envoyer le samophlange à Undermine pour que l’Union des Bricoleurs l’étudie. D’abord, il le pose pour l’examiner, et le fragile mécanisme se brise.",al={"krachevalve samophlange","que devient le samophlange"}},{q="D’où vient le samophlange ?",a="Le samophlange est logé dans une console en fonctionnement, au nord des Tarides, derrière des couches de mécanismes déroutants qui semblent ne servir à rien.",al={"emplacement du samophlange","où le trouver"}}},fp="11,140,22.353.0,25.264.1,22.204.0,26.124.0,34.156.1,36.142.0"}
P.entries["item:samophlange-manual"] = {n="Manuel du samophlange",s="À Orgrimmar, Rilli Greasygob recherche les pages éparpillées du Manuel du samophlange. Ce manuel explique comment réparer et utiliser le samophlange de la KapitalRisk.",h="À Orgrimmar, Rilli Greasygob recherche les pages éparpillées du Manuel du samophlange.",kw={"les tarides","boss copperplug","mine des pierriers","ingénierie","manuel","rilli greasygob","samophlange","krachevalve","kapitalrisk"},ang={["faction:Horde"]="Le manuel permet aux gobelins de la Horde à Orgrimmar d’étudier et de réaffecter les machines de forage de l’entreprise, sous le nez de la KapitalRisk.",["profession:Engineering"]="Le manuel révèle des technologies exclusives à la KapitalRisk. Il montre aussi comment les bricoleurs gobelins protègent leurs secrets commerciaux et leurs plans de leurs pairs."},sec={{t="Les secrets de l’engin",b="Boss Copperplug gardait jalousement les connaissances de la KapitalRisk sur le samophlange. Cet ambitieux surveillant retenait les pages du manuel à l’écart de la plupart des ouvriers. Il ne confiait des feuilles volantes qu’à ses subordonnés les plus loyaux. Lorsque l’appareil échappa aux mains de l’entreprise, personne ne put le réparer sans récupérer les pages déchirées auprès de Copperplug et de son équipe, à la Mine des Pierriers."},{t="L’ambition d’un rival",b="Rilli Greasygob quitta la KapitalRisk et s’installa à Orgrimmar pour apprendre comment le samophlange avait été construit. Copperplug ne lui avait jamais accordé ses faveurs. Rilli compte donc sur des voyageurs entreprenants pour récupérer la couverture du manuel et ses feuilles volantes. Une fois reconstitué, le manuel offre aux bricoleurs gobelins qui travaillent avec la Horde un rare aperçu de l’ingénierie de la KapitalRisk."}},faq={{q="Qu’est-ce que le Manuel du samophlange ?",a="Le Manuel du samophlange explique comment utiliser et réparer l’appareil mécanique complexe et excentrique de la KapitalRisk.",al={"qu’est-ce que le manuel du samophlange","livre du samophlange","guide du samophlange"}},{q="À qui appartenait le manuel à l’origine ?",a="Boss Copperplug, un surveillant de la KapitalRisk à la Mine des Pierriers, dans le nord-est des Tarides, gardait le manuel. Il protégeait ses secrets et ne confiait des pages séparées qu’à ses ouvriers les plus dignes de confiance.",al={"qui a le manuel","manuel de boss copperplug","qui a écrit le manuel"}},{q="Pourquoi le manuel est-il déchiré en plusieurs pages ?",a="Boss Copperplug sépara les pages du manuel pour empêcher ses rivaux et ses subordonnés indignes de confiance de comprendre l’ensemble de l’appareil. Il conserva la couverture et confia cinq pages précises à ses mineurs et à ses opérateurs.",al={"pourquoi trouver les pages du manuel","pages éparpillées du manuel","pourquoi des pages manquent"}},{q="Qui veut lire le manuel reconstitué ?",a="Rilli Greasygob, un ingénieur à Orgrimmar, veut consulter le manuel reconstitué pour comprendre et réparer le samophlange cassé récupéré dans les Tarides.",al={"qui a besoin du manuel","rilli greasygob","qui veut le manuel du samophlange"}},{q="À quoi sert un samophlange ?",a="Personne en dehors de la KapitalRisk ne semble savoir à quoi sert un samophlange. L’entreprise en a étudié un dans un petit site de recherche au sud-ouest de la Videfange, dans les Tarides. Pourtant, même les ingénieurs qui l’ont étudié n’ont guère réussi à le comprendre.",al={"que fait le samophlange","utilité du samophlange","fonction du samophlange"}}},fp="18,165,26.354.0,18.351.0,31.117.0,32.197.0,34.191.0,39.147.0,31.252.0"}
P.entries["item:sample-elven-gem"] = {n="Sample Elven Gem",s="Le Sample Elven Gem prouve que l’équipage de Shakes O’Breen a trouvé un trésor. L’amiral Corne-de-mer, à la Baie-du-Butin, en a besoin pour apprendre leur découverte.",h="Le Sample Elven Gem prouve que l’équipage de Shakes O’Breen a trouvé un trésor.",kw={"baie-du-butin","gemme elfique","amiral corne-de-mer","sample elven gem","shakes o’breen","trésor englouti","trésor"},sec={{t="Un échantillon pour l’amiral Corne-de-mer",b="L’équipage de Shakes O’Breen a trouvé un trésor, mais la marée basse et des créatures aux aguets l’empêchent de partir. Il faut apporter le Sample Elven Gem à l’amiral Corne-de-mer, à la Baie-du-Butin. La gemme prouve leur découverte et informe l’amiral qu’ils cherchent à récupérer d’autres trésors."}},faq={{q="Qu’est-ce que le Sample Elven Gem ?",a="Le Sample Elven Gem prouve que l’équipage de Shakes O’Breen a découvert un trésor.",al={"échantillon de gemme","échantillon de gemme elfique"}},{q="Qui m’a donné le Sample Elven Gem ?",a="Shakes O’Breen vous a confié le Sample Elven Gem pour que vous l’apportiez à l’amiral Corne-de-mer.",al={"qui m’a donné la gemme","gemme de shakes"}},{q="Qui a besoin de la gemme ?",a="L’amiral Corne-de-mer, à la Baie-du-Butin, a besoin du Sample Elven Gem pour prouver la découverte de l’équipage.",al={"qui veut cette gemme","gemme pour corne-de-mer"}},{q="Pourquoi l’équipage de Shakes O’Breen ne peut-il pas partir ?",a="La marée est trop basse, et les créatures dérangées par l’équipage surveillent ses mouvements.",al={"pourquoi coincés","pourquoi ne peuvent-ils pas partir"}}},fp="16,150,20.265.0,29.83.0,33.87.0,18.96.0,44.87.0"}
P.entries["item:sample-ichor"] = {n="Echantillon d'ichor",s="Dans la Forêt des Pins-Argentés, l’Echantillon d’ichor porte des traces de nécromancie et de sorcellerie de démoniste. L’Apothicaire Renferrel l’a raffiné à partir du fluide qui soutient les gnolls Poil-putride.",h="Dans la Forêt des Pins-Argentés, l’Echantillon d’ichor porte des traces de nécromancie et de sorcellerie de...",kw={"apothicaire renferrel","bethor glacéclat","quartier de la magie","poil-putride","rot hide origins","echantillon d'ichor","forêt des pins-argentés","fossoyeuse"},ang={["class:Mage"]="En tant que mage, vous connaissez la valeur de l’étude classique des arcanes face à la sorcellerie noire. Bethor Glacéclat utilise des sorts de divination spécialisés pour lire les résidus présents dans l’Echantillon d’ichor.",["class:Warlock"]="En tant que démoniste, vous reconnaîtrez peut-être les arts des démonistes que l’Apothicaire Renferrel a trouvés mêlés à la nécromancie dans l’ichor. Cela laisse entendre que des pratiques gangrenées ont contribué à lier ces bêtes mortes-vivantes."},sec={{t="Démêler les Poil-putride",b="L’Apothicaire Renferrel a envoyé l’Echantillon d’ichor à Fossoyeuse pour l’étudier de plus près. Il l’a recueilli sur les gnolls Poil-putride et dans leurs restes persistants, puis a réduit ce liquide répugnant à ses composants de base. Ses découvertes ont révélé que des rites nécromantiques et la magie des démonistes avaient façonné l’ichor. Comme sa fabrication dépasse la simple alchimie, Renferrel l’a envoyé à Bethor Glacéclat pour qu’il le soumette à la divination."}},faq={{q="Qu’est-ce que l’Echantillon d’ichor ?",a="L’Echantillon d’ichor est un extrait que l’Apothicaire Renferrel a raffiné à partir des fluides corporels des gnolls Poil-putride. Il l’a séparé en ses composants de base pour découvrir comment la magie avait transformé ces bêtes mortes en créatures ambulantes.",al={"echantillon d'ichor","qu’est-ce que cet ichor","qu’est-ce que l’échantillon d’ichor"}},{q="Qui doit examiner cet échantillon ?",a="Bethor Glacéclat doit examiner l’Echantillon d’ichor. C’est un mage mort-vivant du Quartier de la Magie de Fossoyeuse, expert en divination et en traditions magiques capables de révéler des traces qu’une alchimie ordinaire ne peut déceler.",al={"à qui apporter l’ichor","remettre l’échantillon d’ichor","bethor glacéclat ichor"}},{q="Quel type de magie se trouve dans l’ichor ?",a="L’Echantillon d’ichor contient de la magie de démoniste et de la nécromancie liées à son fluide. Bethor Glacéclat affirme que la fiole porte de puissants enchantements anciens qui nécessitent une divination plus approfondie pour être entièrement révélés.",al={"quelle magie se trouve dans l’ichor","type de magie de l’ichor","magie des poil-putride"}},{q="Pourquoi les apothicaires n’ont-ils pas terminé eux-mêmes l’analyse ?",a="La Société royale des apothicaires excelle en alchimie, en toxines et en fléaux corporels. Les entrelacs arcaniques complexes nécessitent un sorcier comme Bethor Glacéclat, capable d’identifier les écoles de magie et de démêler des sorts ésotériques qui dépassent les outils habituels d’un apothicaire.",al={"pourquoi l’apothicaire l’a envoyé à bethor","pourquoi renoncer à l’ichor poil-putride"}}},fx={f4e4cc11={q="D'où vient cet Echantillon d'ichor et qui l'a créé ?",a="L'Apothicaire Renferrel a préparé cette fiole en décomposant de l'ichor brut récolté sur les gnolls patte-pourrie dans la Forêt des Pins-Argentés. Son analyse initiale a révélé que quiconque a créé la substance originale l'a imprégnée à la fois de nécromancie et de magie démoniaque, bien que le véritable cerveau derrière sa création reste à découvrir.",al={"origine de l'échantillon d'ichor","d'où vient l'échantillon d'ichor","qui a fabriqué l'échantillon d'ichor"}},["045e6062"]={q="Pourquoi Bethor Glacéclat veut-il l'Echantillon d'ichor ?",a="L'Apothicaire Renferrel a atteint les limites de la science alchimique en essayant de déterminer ce qui a créé les patte-pourrie. Il a envoyé cet échantillon raffiné à Bethor Glacéclat dans le Quartier de la Magie de Fossoyeuse car Bethor possède une connaissance approfondie des arts obscurs et des arcanes, ce qui lui permet d'utiliser la magie de divination pour identifier les sorts obscurs tissés dans le fluide.",al={"pourquoi bethor veut l'échantillon d'ichor","pourquoi l'échantillon d'ichor est-il recherché","but de l'échantillon d'ichor pour bethor"}}},fp="12,164,24.380.0,25.196.0,29.202.0,39.183.0,59.236.0"}
P.entries["item:sample-of-zanzil-s-altered-mixture"] = {n="Echantillon de la mixture altérée de Zanzil",s="De l’autre côté de la mer, l’Échantillon de la mixture altérée de Zanzil est destiné au Moulin-de-Tarren. Le breuvage vient du féticheur Zanzil et affaiblit son porteur. Serge Hinott pourra peut-être trouver un remède et découvrir le fonctionnement du poison.",h="De l’autre côté de la mer, l’Échantillon de la mixture altérée de Zanzil est destiné au Moulin-de-Tarren.",kw={"mixture altérée","hautebrande","poisons","voleur","serge hinott","la videfange","moulin-de-tarren","zanzil"},ang={["class:Rogue"]="En tant que voleur de la Horde, vous transportez cet échantillon dangereux à Serge Hinott, dont les leçons portent sur la préparation, le maniement et l’application de poisons mortels.",["faction:Horde"]="En tant que voyageur de la Horde, vous transportez le breuvage d’un continent à l’autre en zeppelin et par la route, en suivant les voies qui relient Kalimdor aux territoires des Réprouvés en Lordaeron."},sec={{t="Un présent toxique",b="Un agent transporte la mixture après s’être introduit dans la tour de la KapitalRisk, près de la Videfange, dans les Tarides. L’échantillon provient d’une cache dans le coffre-fort de Gallywix, et le breuvage de Zanzil a atteint l’agent. Shenthul envoie l’agent affaibli de l’autre côté de la Grande mer avec l’échantillon. À Moulin-de-Tarren, dans les Contreforts de Hautebrande, l’apothicaire Serge Hinott peut isoler la toxine et en découvrir les composants."},{t="Les secrets de l’art des poisons",b="Serge Hinott étudie la mixture altérée pour aider le coursier affligé et apprendre à préparer et à manier des poisons puissants sur le terrain. Les voleurs de la Horde cherchent ce savoir pour maîtriser les arts les plus sombres de leur profession."}},faq={{q="Qu’est-ce que cette mixture ?",a="La mixture est un breuvage alchimique lié au féticheur Zanzil, récupéré dans la tour de la KapitalRisk, près de la Videfange, dans les Tarides. Sa puissante toxine provoque des effets persistants et débilitants chez quiconque la touche directement.",al={"mixture de zanzil","échantillon de la mixture altérée de zanzil","échantillon de poison de zanzil"}},{q="Pourquoi dois-je l’apporter à Serge Hinott ?",a="Serge Hinott est un apothicaire de Moulin-de-Tarren, dans les Contreforts de Hautebrande. Son savoir peut contrer les effets du breuvage et permettre de préparer un remède fiable avant que la toxine ne cause des dommages permanents.",al={"serge hinott","pourquoi l’apporter à moulin-de-tarren","remède contre la mixture de zanzil"}},{q="Qui est Zanzil ?",a="Zanzil the Outcast est un féticheur troll des jungles, connu pour créer des élixirs, des poisons et des mutagènes qui provoquent la folie. Ses recettes toxiques se sont répandues au-delà de ses jungles natales, jusque dans les opérations de mercenaires et d’industriels comme la KapitalRisk.",al={"qui est zanzil","zanzil the outcast","histoire de zanzil"}},{q="Comment rejoindre Moulin-de-Tarren pour livrer l’échantillon ?",a="Prenez le zeppelin de Durotar jusqu’à Fossoyeuse, dans les Clairières de Tirisfal. Suivez ensuite la route principale vers le sud à travers la Forêt des Pins-Argentés, puis les panneaux vers l’est, dans les Contreforts de Hautebrande jusqu’à Moulin-de-Tarren.",al={"comment rejoindre moulin-de-tarren","voyage vers les contreforts de hautebrande","itinéraire vers moulin-de-tarren"}}},fp="34,213,13.394.0,22.207.1,21.236.0,41.185.0,14.243.0,43.189.0"}
P.entries["item:sample-snapjaw-shell"] = {n="Echantillon de carapace de Gueule d'acier",s="Dans Les Tarides, les carapaces de gueule d’acier gardent une étincelle de vie des oasis d’eau douce. Les druides taurens les envoient par-delà La Grande mer pour aider la Forêt des Pins-Argentés.",h="Dans Les Tarides, les carapaces de gueule d’acier gardent une étincelle de vie des oasis d’eau douce.",kw={"tarides","mura runetotem","oasis","echantillon de carapace de gueule d'acier","le sépulcre","forêt des pins-argentés","gueule d’acier","carapace de tortue"},ang={["class:Druid"]="Pour les druides du Cercle cénarien, l’étude des tortues mordantes des oasis enseigne comment la vie persévère et comment les terres flétries pourraient être soignées.",["race:Tauren"]="En tant que Tauren, vous pouvez voir dans le voyage de cette carapace un engagement envers la Terre-Mère. Votre peuple apporte son aide et des soins naturels par-delà la mer, même à ses alliés morts-vivants."},sec={{t="Une étincelle de vie des oasis",b="Les tortues mordantes prospèrent dans les étranges oasis luxuriantes des Tarides. Leurs carapaces résistantes gardent une faible lueur et vibrent d’énergie longtemps après la mort de la créature. Les druides taurens voient la terre changer rapidement et trouvent dans ces carapaces une étincelle résiliente de la nature sauvage de Kalimdor. Leur vigueur montre que la vie peut s’épanouir même dans les terres arides les plus rudes."},{t="Soigner des terres lointaines",b="Des naturalistes taurens envoient des coursiers par-delà la mer avec des carapaces pour Mura Runetotem, au Sépulcre. Elle est en poste dans les étendues flétries de la Forêt des Pins-Argentés et cherche à aider les Réprouvés à soigner les terres du nord. Mura étudie la force vitale contenue dans l’armure des gueules d’acier, dans l’espoir qu’elle révèle comment régénérer une forêt malade et faire repousser la végétation sur un sol mourant."}},faq={{q="Qu’est-ce qui rend cette carapace de gueule d’acier spéciale ?",a="Un Echantillon de carapace de Gueule d'acier conserve une faible lueur et une pulsation de vie longtemps après avoir été prélevé. Il provient des tortues mordantes des étranges oasis d’eau douce des Tarides, où les énergies naturelles sont particulièrement intenses.",al={"pourquoi la carapace est spéciale","qu’est-ce qu’une carapace de gueule d’acier","carapace lumineuse"}},{q="Qui a besoin de cet échantillon ?",a="Mura Runetotem, une druidesse tauren, a besoin de la carapace au Sépulcre, dans la Forêt des Pins-Argentés. Elle cherche à aider les Réprouvés à soigner les terres mourantes.",al={"qui veut la carapace","où apporter la carapace","quête de mura runetotem"}},{q="Pourquoi envoyer une carapace des Tarides jusqu’à la Forêt des Pins-Argentés ?",a="Les bois de la Forêt des Pins-Argentés sont flétris et malades, tandis que la vie a prospéré dans les oasis des Tarides et y a perduré. Les druides espèrent que la vitalité des bêtes de Kalimdor leur apprendra à soigner les sols endommagés de Lordaeron.",al={"pourquoi l’envoyer dans la forêt des pins-argentés","lien entre la carapace et la forêt des pins-argentés"}},{q="La carapace est-elle dangereuse ou corrompue ?",a="Non. La carapace porte une vitalité pure, pas de magie noire. Les druides voient dans l’énergie persistante au milieu de la croissance soudaine des Tarides une résilience naturelle qui mérite d’être cultivée.",al={"la carapace est-elle maléfique","la carapace est-elle corrompue"}}},fx={["6161673b"]={q="Qu'est-ce que l'Echantillon de carapace de Gueule d'acier ?",a="C'est un spécimen prélevé sur la carapace d'une tortue Gueule d'acier trouvée dans les étendues arides des Tarides. Imprégnée d'une étrange vitalité pulsante, cette carapace est soigneusement conservée afin que son énergie vitale inhabituelle puisse être examinée loin des plaines de Kalimdor.",al={"qu'est-ce que l'échantillon de carapace de gueule d'acier","objet carapace de gueule d'acier","identité de l'échantillon de carapace de gueule d'acier"}},c3ef5b23={q="D'où vient l'Echantillon de carapace de Gueule d'acier ?",a="Il provient des Gueules d'acier sauvages vivant autour des oasis et des cours d'eau des Tarides. La carapace naturelle a été récoltée par des aventuriers de la Horde en Kalimdor et choisie par les druides taurens en tant qu'échantillon représentatif de la force vitale florissante trouvée au sein des terres désolées baignées de soleil.",al={"origine de la carapace de gueule d'acier","d'où vient la carapace de gueule d'acier","qui a fabriqué l'échantillon de carapace de gueule d'acier"}}},fp="20,149,21.326.0,21.350.0,38.194.0,22.140.0,51.200.0,34.157.0"}
P.entries["item:samuel-s-remains"] = {n="Cadavre de Samuel",s="Près du Glas, les os de Samuel sont prélevés sur un serviteur du Fléau et déposés auprès de Marla.",h="Près du Glas, les os de Samuel sont prélevés sur un serviteur du Fléau et déposés auprès de Marla.",kw={"le glas","marla fipps","tombe de marla","marla's last wish","novice elreth","samuel fipps","cadavre de samuel"},ang={["race:Undead"]="En tant que mort-vivant, vous apprenez tôt qu'honorer les morts tragiques marque la frontière morale entre les Réprouvés libres et les serviteurs sans volonté du Fléau."},sec={{t="Une réunion tragique",b="Samuel Fipps et sa femme Marla vivaient en paix dans les Clairières de Tirisfal avant que le fléau de la non-mort ne ravage Lordaeron. Samuel succomba et devint un serviteur sans volonté du Fléau. Marla échappa à la non-mort, mais Samuel l'abattit. À l'agonie, elle demanda à être enterrée auprès de lui une fois sa forme maudite mise au repos.\n\nLa novice Elreth, au Glas, envoie les Réprouvés fraîchement éveillés au nord-est du campement. Ils doivent y retrouver la silhouette errante de Samuel, récupérer ses os et les enterrer au premier rang du cimetière local."}},faq={{q="Qui était Samuel Fipps ?",a="Samuel Fipps était un humain qui vivait dans les Clairières de Tirisfal avant la troisième guerre. La peste du Fléau l'a tué, puis relevé comme serviteur mort-vivant du roi-liche. Poussé par une faim sans volonté, il finit par tuer sa femme, Marla.",al={"samuel fipps","qui est samuel","histoire de samuel"}},{q="Où trouver les restes de Samuel ?",a="Les restes de Samuel sont récupérés sur sa silhouette errante, dans un camp en ruines au bord de la route au nord-est du Glas. Mettre fin à son existence sans volonté permet de récupérer ses os.",al={"trouver les restes de samuel","où est samuel fipps","emplacement de samuel"}},{q="Pourquoi les Réprouvés l'enterrent-ils auprès de sa femme ?",a="Le dernier souhait de Marla était de reposer auprès de son époux bien-aimé, même s'il l'avait tuée. La novice Elreth honore sa demande pour montrer que les Réprouvés fraîchement libérés ont encore de la compassion, respectent les morts et gardent l'humanité qui les distingue du Fléau.",al={"pourquoi enterrer samuel","tombe de marla","dernier souhait de marla"}}},fx={["29aac9a9"]={q="D'où provient le Cadavre de Samuel ?",a="Il s'agit des restes physiques mortels de Samuel Fipps, un ancien résident des Clairières de Tirisfal qui a succombé à la peste des morts-vivants et est devenu un pion sans esprit du Fléau. Après avoir erré dans la nature au nord-est du Glas, son corps de mort-vivant est abattu afin que ses restes puissent enfin être rassemblés et déposés en paix.",al={"origine du cadavre de samuel","d'où provient le cadavre de samuel","qui a créé le cadavre de samuel"}}},fp="16,88,16.522.0,21.221.0,33.177.0,45.258.0"}
P.entries["item:sapphire-of-aku-mai"] = {n="Saphir d'Aku'Mai",s="Le long des Profondeurs de Brassenoire, les nagas récoltent les saphirs d’Aku’mai. Des esprits de l’eau s’accrochent aux cristaux, et Je’neu Sancrea cherche de l’aide pour les récupérer avant que leur pouvoir arcanique ne soit utilisé.",h="Le long des Profondeurs de Brassenoire, les nagas récoltent les saphirs d’Aku’mai.",kw={"aku'mai","profondeurs de brassenoire","cristaux","je'neu sancrea","nagas","saphir","esprits de l’eau","la grève de zoram"},ang={["class:Mage"]="L’eau imprègne naturellement les saphirs, ce qui en fait des catalyseurs recherchés pour de puissants composants arcaniques.",["class:Shaman"]="En tant que chaman du Cercle terrestre, vous pouvez sentir les esprits de l’eau liés à ces gemmes. La récolte des nagas menace les éléments."},sec={{t="Gemmes des profondeurs",b="Aux entrées inondées des Profondeurs de Brassenoire, les parois de la grève de Zoram, en Orneval, portent des saphirs d’Aku’mai. Des esprits de l’eau s’accrochent aux cristaux, dont l’énergie élémentaire renforce la magie. Lorsque des éclaireurs ont signalé que les nagas extrayaient les gemmes sous terre, Je’neu Sancrea, un chaman, a demandé l’aide de voyageurs pour les récupérer. Entre les mains des nagas, ces pierres pourraient alimenter de dévastateurs rituels arcaniques."}},faq={{q="Qu’est-ce qu’un saphir d’Aku’mai ?",a="Les parois des Profondeurs de Brassenoire sont tapissées de saphirs d’Aku’mai. Des esprits de l’eau s’accrochent aux cristaux, leur conférant un grand pouvoir arcanique et élémentaire.",al={"qu’est-ce que ce cristal","histoire du saphir d’aku’mai","que sont ces gemmes"}},{q="Pourquoi les nagas récoltent-ils ces saphirs ?",a="Je’neu Sancrea soupçonne les nagas de vouloir exploiter l’énergie aquatique et arcanique des cristaux pour pratiquer une sorcellerie dangereuse dans le temple submergé. Leurs intentions exactes restent incertaines.",al={"pourquoi les nagas veulent-ils des saphirs","récolte de cristaux par les nagas"}},{q="Qui cherche ces saphirs ?",a="Je’neu Sancrea, un chaman du Cercle terrestre à l’avant-poste de Zoram’gar, sur la grève de Zoram en Orneval, demande aux voyageurs de récolter les saphirs et de les empêcher de tomber entre les mains des nagas.",al={"qui veut les saphirs d’aku’mai","qui rend l’essence d’aku’mai"}},{q="Ces cristaux sont-ils directement liés à la bête Aku’mai ?",a="Les cristaux tirent leur nom d’Aku’mai, l’hydre monstrueuse des profondeurs, mais poussent naturellement dans les parois des cavernes. Leur nom évoque leur proximité avec la présence ténébreuse des ruines.",al={"lien avec aku’mai","cela vient-il d’aku’mai"}}},fx={["12f03799"]={q="D'où viennent les Saphirs d'Aku'Mai et qui les a créés ?",a="Ces grands amas de saphirs poussent naturellement le long des parois des cavernes à l'intérieur des tunnels d'entrée des Profondeurs de Brassenoire. Ils ne sont pas façonnés par des mains mortelles ; il s'agit plutôt de formations minérales naturelles imprégnées des énergies ambiantes de la caverne. Des esprits de l'eau s'accrochent naturellement aux cristaux, leur conférant une puissance élémentaire inhérente.",al={"origine du saphir d'aku'mai","qui a fabriqué le saphir d'aku'mai","d'où viennent les saphirs d'aku'mai"}}},fp="19,179,16.380.0,30.139.0,44.176.0,35.158.0,54.186.0"}
P.entries["item:sapphire-of-sky"] = {n="Saphir des cieux",s="Au Refuge des saisons de Ban'ethil, le Saphir des cieux aide à rappeler du Rêve d'émeraude les Druides de la Serre endormis. Les elfes de la nuit le gardent comme l'une des quatre Reliques de l'éveil sacrées.",h="Au Refuge des saisons de Ban'ethil, le Saphir des cieux aide à rappeler du Rêve d'émeraude les Druides de la...",kw={"athridas mantelours","refuge des saisons de ban'ethil","coffre des cieux","druide de la serre","rêve d'émeraude","reliques de l'éveil","saphir des cieux"},ang={["class:Druid"]="En tant que druide, vous comprenez l'importance des ancrages sacrés lorsque votre esprit pénètre dans le Rêve d'émeraude. Sans eux, la communion peut devenir fatale.",["race:NightElf"]="En tant qu'elfe de la nuit, vous savez que protéger les reliques sacrées du Refuge des saisons de Ban'ethil contribue à préserver l'équilibre fragile de Teldrassil face à la corruption grandissante."},sec={{t="Le rituel de l'éveil",b="Les Druides de la Serre hibernent au Refuge des saisons de Ban'ethil, au plus profond des racines de Teldrassil. Là, ils communient avec la nature sauvage. Se réveiller de cette transe profonde est périlleux. Quatre reliques sacrées protègent donc ce passage : la Plume noire, le Talisman de la griffe du corbeau, la Rune de nidification et le Saphir des cieux. La gemme complète l'harmonie nécessaire pour rappeler du Rêve d'émeraude les esprits endormis. Sans elle, ils pourraient y rester prisonniers à jamais."},{t="La menace à Ban'ethil",b="Les furbolgs Fur-de-pin corrompus ont envahi le Refuge des saisons de Ban'ethil, laissant les reliques sacrées dans leurs réceptacles. Le Saphir des cieux repose dans le Coffre des cieux, le long des couloirs souterrains sinueux. Les druides dorment toujours tandis que les furbolgs font rage autour d'eux. À Dolanaar, Athridas Mantelours a besoin du saphir et des reliques qui l'accompagnent pour réveiller les dormeurs avant qu'ils ne soient perdus à jamais."}},faq={{q="Qu'est-ce que le Saphir des cieux ?",a="Le Saphir des cieux est une gemme sacrée et l'une des quatre Reliques de l'éveil conservées au Refuge des saisons de Ban'ethil. Avec trois talismans aviaires, il guide les Druides de la Serre hors du Rêve d'émeraude en toute sécurité.",al={"histoire du saphir des cieux","qu'est-ce que cette gemme","saphir du ciel"}},{q="Où le Saphir des cieux est-il conservé ?",a="Le Saphir des cieux est conservé dans le Coffre des cieux, au cœur du labyrinthe souterrain du Refuge des saisons de Ban'ethil, dans le centre de Teldrassil.",al={"où trouver le saphir des cieux","emplacement du coffre des cieux","emplacement du saphir"}},{q="Pourquoi le saphir est-il nécessaire maintenant ?",a="Des furbolgs Fur-de-pin corrompus ont envahi le Refuge des saisons de Ban'ethil et menacent gravement les druides endormis. Plongés dans une transe profonde, ils ne peuvent pas simplement se réveiller seuls. Athridas Mantelours a besoin du saphir et des autres reliques pour accomplir le délicat rituel de l'éveil avant que les dormeurs ne soient perdus à jamais.",al={"pourquoi récupérer le saphir","rôle des reliques de l'éveil"}},{q="Qui utilise cet artefact ?",a="Les Druides de la Serre et les gardiens du rituel comme Athridas Mantelours utilisent le saphir pour réveiller leurs frères endormis, plongés dans une profonde communion avec la nature.",al={"qui utilise le saphir des cieux","gemme du rituel druidique"}}},fp="15,171,19.457.0,23.394.0,28.199.0,34.132.0,37.295.0,23.152.0"}
P.entries["item:sara-balloo-s-plea"] = {n="Requête de Sara Balloo",s="Dans son chagrin, Sara Balloo demande à un champion de l’Alliance de remettre sa lettre manuscrite au Roi Magni Barbe-de-Bronze.",h="Dans son chagrin, Sara Balloo demande à un champion de l’Alliance de remettre sa lettre manuscrite au Roi...",kw={"a king's tribute","le haut siège","forgefer","magni barbe-de-bronze","sara balloo","requête de sara balloo"},ang={["faction:Alliance"]="En tant que champion de l’Alliance, vous portez la requête de Sara devant la royauté. Elle vous fait confiance en raison de vos services à l’Alliance.",["race:Dwarf"]="En tant que nain, vous portez le message de Sara au Haut Siège afin que le Roi Magni entende chaque montagnard et chaque citoyen, même dans le chagrin."},sec={{t="L’appel d’une veuve",b="Le chagrin empêche Sara de se présenter devant le Haut Siège. Elle confie donc ses mots à un aventurier fidèle à l’Alliance. Elle demande au Roi Magni de ne pas oublier le deuil privé et les sacrifices des familles naines ordinaires qui servent le royaume."}},faq={{q="Qu’est-ce que la Requête de Sara Balloo ?",a="La Requête de Sara Balloo est une lettre manuscrite destinée au Roi Magni Barbe-de-Bronze. Sara sollicite son attention tandis qu’elle porte son deuil en privé.",al={"requête sara balloo","message de veuve forgefer","message de sara"}},{q="Pourquoi Sara Balloo a-t-elle besoin de quelqu’un pour remettre sa lettre ?",a="Sara est accablée de chagrin et pense que se présenter ainsi devant le roi de Forgefer nuirait à sa requête. Elle confie donc la lettre à un champion de l’Alliance.",al={"pourquoi remettre la lettre","pourquoi sara ne peut pas y aller","chagrin de sara"}},{q="Qui reçoit ce message ?",a="Le Roi Magni Barbe-de-Bronze reçoit la lettre de Sara au Haut Siège de Forgefer.",al={"qui reçoit la requête","à qui remettre la lettre","lettre magni"}},{q="Que se passe-t-il après la remise de la lettre ?",a="La lettre porte le deuil de Sara Balloo à l’attention du Roi Magni et déclenche une réponse royale qui rend hommage aux membres de sa famille tombés au combat.",al={"suite de quêtes de la requête","lien a kings tribute","que se passe-t-il ensuite"}}},fx={["2b83ea9f"]={q="D'où vient la Requête de Sara Balloo et qui l'a rédigée ?",a="Cette note écrite a été rédigée directement par Sara Balloo, une naine en deuil à Forgefer. Dévastée par la perte, elle a préparé le message elle-même pour pétitionner le trône de Forgefer, le confiant à un champion de l'Alliance plutôt que de tenter seule le voyage émotionnel jusqu'au Haut Siège.",al={"qui a écrit la requête de sara balloo","d'où vient la requête de sara balloo","qui a créé la requête de sara balloo"}},["4ac5e6cf"]={q="Pourquoi quelqu'un voudrait-il la Requête de Sara Balloo ?",a="Le Roi Magni Bronzebeard a besoin de la lettre pour entendre la requête de l'un de ses sujets en deuil. Sara Balloo ne peut se résoudre à paraître devant le monarque dans son état de tristesse, elle compte donc sur vous pour présenter l'appel directement entre les mains du souverain de Forgefer.",al={"pourquoi la requête de sara balloo est-elle nécessaire","qui veut la requête de sara balloo","pourquoi livrer la requête de sara balloo"}}},fp="18,110,16.229.0,27.127.0,53.166.0,26.76.0,40.136.1"}
P.entries["item:sarilus-foulborne-s-head"] = {n="Tête de Sarilus Souillemporte",s="Venue des Tarides, la Tête de Sarilus Souillemporte atteint Orneval comme preuve de la mort du sorcier. Il a souillé les eaux d’Orneval, et les Sentinelles ont exigé sa tête.",h="Venue des Tarides, la Tête de Sarilus Souillemporte atteint Orneval comme preuve de la mort du sorcier.",kw={"tarides","pic de brume-funeste","tête","mage summoner","sarilus souillemporte","refuge de vent-argent","vélène heurtétoile","élémentaires d’eau"},ang={["faction:Alliance"]="Cette attaque exige de s’infiltrer profondément en territoire hostile de la Horde, dans les Tarides, pour éliminer un dangereux lanceur de sorts renégat.",["race:NightElf"]="Prendre la tête de Souillemporte permet aux Sentinelles d’assouvir leur vengeance contre un profanateur arcanique qui a souillé les esprits de la terre."},sec={{t="Un profanateur réduit au silence",b="Sarilus Souillemporte était un lanceur de sorts réprouvé qui s’était établi au sommet du Pic de Brume-funeste, dans le nord des Tarides. Il a provoqué la colère des elfes de la nuit en corrompant et en asservissant des nuées d’élémentaires d’eau.\n\nDepuis le Refuge de Vent-argent, la Sentinelle Vélène Heurtétoile a reconnu son œuvre et a envoyé des champions au-delà de la frontière, en territoire de la Horde, pour mettre fin à ses expériences. Heurtétoile n’accepterait que sa tête tranchée comme preuve de la mort du mage moqueur, afin que les eaux troublées d’Orneval puissent retrouver un peu de paix."}},faq={{q="Qui était Sarilus Souillemporte ?",a="Sarilus Souillemporte était un mage mort-vivant qui s’était établi au sommet du Pic de Brume-funeste, dans le nord des Tarides. Il a provoqué la colère des elfes de la nuit en déformant et en invoquant de nombreux élémentaires d’eau. La Sentinelle Vélène Heurtétoile a donc ordonné sa mort.",al={"qui est sarilus","histoire de sarilus souillemporte","qui est souillemporte"}},{q="Pourquoi la Sentinelle Vélène Heurtétoile veut-elle sa tête ?",a="Vélène Heurtétoile voulait avoir la certitude que l’arrogant sorcier était mort. Sarilus se moquait d’elle tout en profanant les esprits des eaux de la région. Sa tête tranchée était la seule preuve qu’elle accepterait que la menace avait pris fin.",al={"pourquoi prendre sa tête","tête de vélène heurtétoile","preuve de sa mort"}},{q="Où se trouve Sarilus Souillemporte ?",a="Sarilus Souillemporte se terre au sommet du Pic de Brume-funeste, dans le nord des Tarides, juste au sud de la frontière d’Orneval.",al={"où trouver souillemporte","emplacement de sarilus","mage du pic de brume-funeste"}},{q="Pourquoi Souillemporte profanait-il les élémentaires d’eau ?",a="Sarilus Souillemporte utilisait des invocations arcaniques pour soumettre à sa volonté de nombreux élémentaires d’eau et les corrompre. Ses manipulations inconsidérées ont perturbé l’équilibre naturel des eaux qui coulent près d’Orneval, entraînant une riposte rapide des Sentinelles.",al={"pourquoi corrompre les élémentaires","corruption des élémentaires d’eau","motivations de souillemporte"}}},fx={a996e76e={q="D'où vient la Tête de Sarilus Souillemporte ?",a="Cette tête coupée provient directement de Sarilus Souillemporte, un mage Réprouvé qui s'est établi au sommet du Pic de Brume-funeste dans le nord des Tarides. Opérant près des frontières d'Orneval, Souillemporte passait ses journées à souiller les élémentaires d'eau et à antagoniser les elfes de la nuit jusqu'à ce que la Sentinelle Vélène Heurtétoile envoie un aventurier en territoire ennemi pour mettre fin à ses moqueries.",al={"origine de la tête de sarilus","d'où vient la tête de souillemporte"}}},fp="24,177,18.497.1,26.241.1,50.217.0,35.104.1,44.240.0"}
P.entries["item:sarkoth-s-mangled-claw"] = {n="Pince abîmée de Sarkoth",s="Sur les falaises sud de la Vallée des épreuves, la Pince abîmée de Sarkoth porte la marque d'un chasseur blessé. Hana'zua écrasa la pince du scorpid avant que son dard venimeux ne le terrasse.",h="Sur les falaises sud de la Vallée des épreuves, la Pince abîmée de Sarkoth porte la marque d'un chasseur...",kw={"pince","durotar","hana'zua","pince abîmée","sarkoth","scorpid","vallée des épreuves"},ang={["faction:Horde"]="En tant que membre de la Horde, revendiquer ce trophée dans la Vallée des épreuves marque une première épreuve de courage et de force martiale dans les étendues sauvages et hostiles de Durotar.",["race:Troll"]="En tant que troll, rapporter la pince à Hana'zua rend un peu de dignité à un parent Sombrelance mourant. Il apprend que son dernier coup a marqué la bête avant sa fin."},sec={{t="Un trophée de vengeance",b="Hana'zua, un jeune troll Sombrelance, rencontra Sarkoth alors qu'il chassait dans la Vallée des épreuves. Le scorpid massif lui transperça la poitrine de son dard venimeux et le laissa saigner sous un arbre voisin.\n\nAvant la piqûre, Hana'zua écrasa la pince de la bête. La pince abîmée prouve que Sarkoth a été tué. Pour le chasseur blessé, sa cicatrice montre que son coup désespéré a porté et préserve son honneur de guerrier tandis que le venin coule dans ses veines."}},faq={{q="Pourquoi la pince est-elle abîmée ?",a="La pince de Sarkoth fut écrasée lors d'un duel désespéré contre Hana'zua, un chasseur troll. Sarkoth piqua Hana'zua à la poitrine, mais le troll frappa avant que la pince de la bête ne se referme sur sa jambe.",al={"pourquoi la pince est abîmée","qui a écrasé la pince de sarkoth","histoire de la pince abîmée"}},{q="Qui veut la Pince abîmée de Sarkoth ?",a="Hana'zua réclame la pince. Grièvement blessé sous un arbre dans la Vallée des épreuves, il craint d'y mourir. Il veut que Sarkoth soit tué pour préserver son honneur ; savoir que la bête a été vaincue lui donne la force de tenir jusqu'à l'arrivée des secours envoyés par Gornek.",al={"qui veut la pince de sarkoth","à qui remettre","pince de hana'zua"}},{q="D'où vient cette pince ?",a="La pince vient de Sarkoth, un scorpid imposant et agressif qui rôde sur le plateau élevé, le long des falaises sud de la Vallée des épreuves, en Durotar.",al={"emplacement de sarkoth","où se trouve sarkoth","où trouver la pince abîmée"}}},fx={["5a9dc5fc"]={q="Qu'est-ce que la Pince abîmée de Sarkoth ?",a="C'est la pince tranchée de Sarkoth, un scorpide inhabituellement grand et vicieux qui rôde sur le plateau sud au-dessus de la Vallée des épreuves. La pince porte des dommages sévères et fragmentés infligés par le troll Sombrelance Hana'zua, gravement blessé lors de leur lutte désespérée, servant de preuve indéniable que la bête monstrueuse a finalement été tuée.",al={"qu'est-ce que la pince abîmée de sarkoth","identité de la pince de sarkoth","pince abîmée"}}},fp="22,191,21.449.0,24.189.0,33.219.0,30.147.0"}
P.entries["item:sarltooth-s-talon"] = {n="Serre de Grondecroc",s="Au-dessus des Excavations de Whelgar, la Serre de Grondecroc est tout ce qui reste de l'attaque du raptor. Ormer Tressefer veut la griffe pour prouver que la bête est morte.",h="Au-dessus des Excavations de Whelgar, la Serre de Grondecroc est tout ce qui reste de l'attaque du raptor.",kw={"fouilles","ormer tressefer","raptor","grondecroc","serre","les paluns","whelgar"},ang={["class:Hunter"]="En tant que chasseur, traquer un chef de meute rusé comme Grondecroc et prendre une griffe en trophée met à l'épreuve votre adresse au tir et votre maîtrise des bêtes.",["race:Dwarf"]="En tant que nain, récupérer cette serre venge les archéologues nains morts au service de la Ligue des explorateurs, à la demande du roi Magni Barbe-de-Bronze."},sec={{t="Un trophée de vengeance",b="Ormer Tressefer observait depuis la crête tandis que des raptors envahissaient les Excavations de Whelgar et massacraient l'expédition naine. Il ne pouvait pas les arrêter. À ses yeux, un énorme raptor, Grondecroc, semblait diriger la meute. Pour venger les siens tombés au combat, Ormer exigea la mort de la bête et l'une de ses serres comme preuve. Cette griffe marque la fin du règne de Grondecroc sur les anciennes ruines naines."}},faq={{q="D'où vient la Serre de Grondecroc ?",a="La Serre de Grondecroc provient de Grondecroc, un grand raptor alpha qui rôde sur les crêtes occidentales au-dessus des Excavations de Whelgar, dans les Paluns.",al={"qui lâche la serre de grondecroc","emplacement de grondecroc","comment obtenir la serre"}},{q="Qui veut la Serre de Grondecroc ?",a="Ormer Tressefer veut la serre. Le nain monte la garde depuis le Surplomb, au-dessus des Excavations de Whelgar, et demande une preuve que la bête qui a massacré son équipe est morte.",al={"qui prend la serre","où rendre la serre","quête d'ormer tressefer"}},{q="Pourquoi Ormer Tressefer a-t-il besoin d'une preuve de la mort de Grondecroc ?",a="Ormer pense que Grondecroc dirigeait la meute de raptors qui a chassé et tué les excavateurs nains. Pour lui, la serre représente la justice et un peu de paix pour ses collègues tombés au combat.",al={"pourquoi tuer grondecroc","qu'a fait grondecroc"}},{q="Qu'est-il arrivé aux nains du site de fouilles ?",a="Les fouilles naines visaient à découvrir d'anciens artefacts pour la Ligue des explorateurs. Des raptors sauvages ont tendu une embuscade aux ouvriers, massacrant la plupart d'entre eux et repoussant les survivants vers la crête voisine.",al={"histoire des excavations de whelgar","pourquoi y a-t-il des raptors aux fouilles"}}},fx={["28fc0e8a"]={q="Qu'est-ce que la Serre de Grondecroc ?",a="C'est une griffe tranchée prélevée sur Grondecroc, le raptor féroce suspecté de mener la meute sauvage qui a envahi les Excavations de Whelgar. Ormer Tressefer exige la griffe comme preuve indéniable que la bête a été tuée et que les excavateurs nains tombés au combat ont été vengés.",al={"qu'est-ce que la serre de grondecroc","lore de la serre de grondecroc"}}},fp="17,153,21.384.0,39.137.0,28.174.0,57.173.0,52.167.0"}
P.entries["item:sathrah-s-sacrifice"] = {n="Sacrifice de Sathrah",s="Au Temple de la Lune, le Sacrifice de Sathrah offre à l’esprit de Dame Sathrah une chance de trouver la paix. Ses filières d’argent proviennent de la puissante araignée qui vit à Teldrassil.",h="Au Temple de la Lune, le Sacrifice de Sathrah offre à l’esprit de Dame Sathrah une chance de trouver la paix.",kw={"darnassus","elune","dame sathrah","prêtresse a'moora","sacrifice de sathrah","filières d'argent","araignée","teldrassil","temple de la lune"},ang={["class:Priest"]="En tant que prêtre, vous pouvez voir ce rite comme un acte de miséricorde divine. The Sisterhood of Elune se sert des eaux sacrées pour purifier la souillure, au lieu de simplement se débarrasser de la bête abattue.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous savez qu’éliminer la faune corrompue est un devoir solennel. Rendre l’esprit de Dame Sathrah à Elune's Grace honore ce devoir."},sec={{t="Purification dans les eaux sacrées",b="Dame Sathrah était une vénérable créature de Teldrassil. Puis une folie insidieuse et la corruption se sont répandues dans les branches du grand arbre et l’ont gagnée. The Sisterhood of Elune vous demande de rapporter ses filières d’argent comme offrande consacrée. Ce ne sont pas des trophées.\n\nÀ la fontaine du Temple de la Lune, ses restes sont baignés dans l’eau sacrée. Le rite lave la souillure qui empoisonnait l’esprit de Sathrah et libère son âme tourmentée. Son esprit apparaît paisiblement dans le sanctuaire, avec la promesse de renaître sous Elune's Grace."}},faq={{q="Qu’est-ce que le Sacrifice de Sathrah ?",a="Le Sacrifice de Sathrah est constitué de filières d’argent prélevées sur Dame Sathrah, une puissante araignée corrompue à Teldrassil. The Sisterhood of Elune les utilise lors d’un rite pour purifier son âme.",al={"que sont les filières","objet sacrifice de sathrah","offrande dame sathrah"}},{q="Pourquoi faut-il déposer les filières dans la fontaine ?",a="La fontaine du Temple de la Lune, à Darnassus, contient de l’eau sacrée consacrée à Elune. Immerger les restes de Sathrah lave la corruption qui l’a rendue folle et libère son esprit de l’agonie.",al={"pourquoi la fontaine du temple","pourquoi sacrifier sathrah","que fait la fontaine"}},{q="Que se passe-t-il quand l’offrande est présentée ?",a="Lorsque vous déposez l’offrande dans les eaux sacrées, la corruption est purgée et la forme spectrale de Dame Sathrah apparaît. Elle marche paisiblement autour du bassin, signe que son âme a trouvé la paix.",al={"que se passe-t-il à la fontaine","apparition de l’esprit de sathrah","événement de la fontaine"}},{q="Qui veille sur ce rituel ?",a="La Prêtresse A'moora veille sur le rite. Servante de The Sisterhood of Elune en poste au Temple de la Lune, elle vous demande d’accorder le repos à Sathrah et d’offrir ses restes à la déesse.",al={"qui donne le sacrifice de sathrah","quête prêtresse a'moora","qui purifie sathrah"}}},fx={c7289e92={q="D'où vient le Sacrifice de Sathrah ?",a="La Prêtresse A'moora a préparé cette offrande directement à partir des filières d'argent prélevées sur Dame Sathrah, une grande araignée abattue à Teldrassil après avoir sombré dans la folie et la corruption.",al={"origine du sacrifice de sathrah","d'où vient le sacrifice de sathrah","qui a fabriqué le sacrifice de sathrah"}},b18748b3={q="Pourquoi la Prêtresse A'moora veut-elle le Sacrifice de Sathrah ?",a="La Prêtresse A'moora a besoin du sacrifice pour qu'il puisse être déposé dans les eaux sacrées du Temple de la Lune. Grâce à cette offrande à Elune, la corruption qui a tordu Dame Sathrah de son vivant peut enfin être purifiée, permettant à la grande bête de reposer en paix et à son esprit de renaître renouvelé.",al={"pourquoi le sacrifice de sathrah est-il recherché","pourquoi offrir le sacrifice de sathrah","à quoi sert le sacrifice de sathrah"}}},fp="19,171,31.542.0,28.176.0,50.196.0,44.187.1,25.187.0"}
P.entries["item:satyr-horns"] = {n="Cornes de satyre",s="En Orneval, les Cornes de satyre attirent les dryades en quête de vengeance et les marchands en route pour Cabestan. Elles proviennent de satyres dont la corruption s’est enracinée dans la forêt antique.",h="En Orneval, les Cornes de satyre attirent les dryades en quête de vengeance et les marchands en route pour...",kw={"anilia","chant des forêts","illiyana","défilé de la nuit","pixel","cornes de satyre","satyrnaar","poste de bois-brisé","xavian"},ang={["faction:Horde"]="Depuis le Poste de Bois-brisé, les guerriers de la Horde éliminent les satyres qui menacent leurs opérations forestières, puis vendent leurs cornes aux acheteurs gobelins en route pour Cabestan.",["race:NightElf"]="Pour les kaldorei, prendre les cornes des satyres est un devoir amer. Cela purifie leur forêt ancestrale des cousins qui ont troqué leur héritage contre le service des démons."},sec={{t="Trophées de vengeance et de commerce",b="Les satyres d’Orneval portent des cornes qui témoignent de leur corruption démoniaque. Au sanctuaire d’Aessina, la dryade Illiyana les rassemble pour venger sa sœur disparue, Anilia. Pixel, une gobeline voyageuse qui se repose au Poste de Bois-brisé, les convoite pour le commerce. La demande a augmenté à Cabestan, où les chasseurs vendent ces restes de démons abattus."},{t="Purger les enclaves corrompues",b="Les Cornes de satyre doivent être coupées sur les satyres eux-mêmes ; les fournisseurs ordinaires n’en vendent pas. Les satyres occupent des bastions dans tout Orneval, des bosquets corrompus de Xavian aux creux de Satyrnaar et aux ruines du Défilé de la nuit. Purger ces enclaves repousse la souillure démoniaque persistante. Cela fournit aussi aux gardiennes endeuillées et aux marchands empressés la preuve de cette purge."}},faq={{q="Pourquoi Illiyana veut-elle des Cornes de satyre ?",a="Illiyana cherche les Cornes de satyre pour venger sa sœur Anilia, assassinée par les satyres d’Orneval. Ces cornes montrent que leur nombre diminue et apaisent l’esprit d’Anilia.",al={"cornes illiyana","anilia satyres","quête du chant des forêts"}},{q="Pourquoi Pixel rassemble-t-elle des Cornes de satyre ?",a="Pixel, une voyageuse entreprenante qui séjourne au Poste de Bois-brisé, rassemble des Cornes de satyre pour son voyage vers Cabestan. Elle sait qu’elles se vendent cher dans le port gobelin et engage donc des chasseurs pour affronter le danger avant son départ.",al={"pixel bois-brisé","pourquoi pixel veut-elle des cornes","cornes de satyre cabestan"}},{q="Où trouver les meilleurs endroits pour dénicher des satyres portant ces cornes ?",a="Les satyres vivent dans plusieurs régions corrompues d’Orneval. On en trouve beaucoup à Xavian et à Satyrnaar, au nord-est, ainsi qu’au Défilé de la nuit, dans la partie centre-est de la forêt.",al={"emplacement des satyres orneval","où sont les satyres","camps de satyres"}},{q="Que sont les satyres, et pourquoi ont-ils des cornes ?",a="Les satyres sont d’anciens elfes de la nuit transformés en êtres démoniaques et bestiaux par des pactes conclus durant la Guerre des Anciens. Leurs sabots, leurs queues et leurs cornes témoignent de la corruption démoniaque accordée par la Légion ardente.",al={"qu’est-ce qu’un satyre","pourquoi les satyres ont-ils des cornes"}}},fx={["2131c67f"]={q="Que sont les Cornes de satyre ?",a="Les Cornes de satyre sont les cornes courbées et diaboliques tranchées sur les têtes des satyres tués qui rôdent à Orneval. En tant que corruptions démoniaques d'anciens elfes de la nuit, les satyres portent ces excroissances menaçantes comme marques de leur affliction maudite. Entre les mains des aventuriers, elles servent principalement de preuve sinistre de la mort d'un satyre ou d'objets curieux et prisés échangés à travers Kalimdor.",al={"que sont les cornes de satyre","objet cornes de satyre","identité des cornes de satyre"}},["8a39621c"]={q="Pourquoi quelqu'un voudrait-il des Cornes de satyre ?",a="Différentes factions recherchent les cornes de satyre pour des raisons très différentes. Pour la dryade Illiyana au Chant des forêts, elles servent de trophées indéniables de rétribution contre les démons corrompus qui ont assassiné sa sœur Anilia. Pendant ce temps, des marchands opportunistes tels que Pixel les collectent pour les vendre dans le port animé de Cabestan, où la demande est forte pour des réactifs alchimiques exotiques, des curiosités et des morceaux de bêtes.",al={"qui veut des cornes de satyre","pourquoi collecter des cornes de satyre","pourquoi les cornes de satyre sont-elles recherchées"}}},fp="11,163,34.327.0,30.359.0,35.170.0,36.223.0,58.155.0,44.212.0"}
P.entries["item:savannah-lion-tusk"] = {n="Canine de lion des savanes",s="Dans Les Tarides, les Canines de lion des savanes passent du statut de trophées de chasse à celui d’ingrédient de la bière légendaire de Chen Stormstout.",h="Dans Les Tarides, les Canines de lion des savanes passent du statut de trophées de chasse à celui...",kw={"les tarides","brasseur drohn","chen stormstout","dishu","humar","cabestan","canine de lion des savanes"},ang={["class:Hunter"]="En tant que chasseur, vous mettez votre talent à l’épreuve en traquant les hardes féroces des Tarides. Leurs crocs dangereux peuvent être mortels au combat et précieux pour les brasseurs de la région."},sec={{t="Un curieux ingrédient de brassage",b="Les grands félins des Tarides portent des canines acérées et lourdes. Rôdeurs, chasseresses, hardes menées par des patriarches et bêtes comme Humar the Pridelord en ont. Les voyageurs prennent ces dents comme preuve d’une chasse réussie. À Cabestan, le Brasseur Drohn utilise les canines avec des rognons de trotteur des plaines et des cornes de lézard-tonnerre pour recréer le célèbre breuvage de Chen Stormstout. Cette bière puissante a un effet légendaire auquel peu de gosiers mortels peuvent résister."}},faq={{q="Pourquoi le Brasseur Drohn a-t-il besoin de Canines de lion des savanes ?",a="À Cabestan, le Brasseur Drohn utilise des Canines de lion des savanes pour recréer le breuvage éponyme de Chen Stormstout. Son mentor lui a transmis la recette, et les canines sont l’un des trois ingrédients des Tarides qui donnent à cette bière brune son goût et son effet si particuliers.",al={"pourquoi des défenses dans la bière","défenses de lion de drohn","recette du brasseur drohn"}},{q="Quelles bêtes portent des Canines de lion des savanes ?",a="Les hardes de lions des savanes des Tarides portent ces canines. On trouve parmi elles les Savannah Highmanes, les Patriarchs, les Matriarchs, les Huntresses, les Prowlers et des bêtes rares comme Dishu et Humar the Pridelord.",al={"où trouver des défenses de lion","qui donne une défense de lion","source des canines de lion des savanes"}},{q="Les lions ont-ils vraiment des défenses ?",a="Les grands félins des savanes ont des canines surdimensionnées qui deviennent proéminentes et épaisses dans les étendues sauvages et accidentées de Kalimdor. Les chasseurs et les pionniers de la région les appellent des défenses.",al={"pourquoi appeler les dents de lion des défenses","défenses de lion ou crocs","anatomie des défenses de lion"}}},fx={["98d362c4"]={q="Qu'est-ce qu'une Canine de lion des savanes ?",a="Une Canine de lion des savanes est une dent canine acérée récoltée sur les chats prédateurs rôdant dans les plaines ensoleillées des Tarides. Bien qu'appelées défenses, ce sont les crocs redoutables des lions des savanes qui dominent les zones de chasse locales. Au-delà de leur rôle de trophées sinistres de survie en milieu sauvage, ces pièces résistantes trouvent des usages particuliers parmi les habitants qui savent comment extraire leurs qualités essentielles.",al={"qu'est-ce qu'une canine de lion des savanes","lore de la canine de lion des savanes","canine de lion"}},ea601034={q="D'où vient une Canine de lion des savanes ?",a="Ces canines sont prélevées directement sur les chats sauvages qui chassent dans les savanes centrales de Kalimdor. Chaque race de lion rôdant dans les Tarides—des rôdeurs et chasseresses aux puissants patriarches et crinières—possède ces crocs acérés, comptant sur eux pour abattre des autruches et défendre leur territoire contre les prédateurs concurrents.",al={"d'où viennent les canines de lion","qui donne les canines de lion","source de la canine de lion"}}},fp="18,104,28.414.0,51.240.0,39.188.0,29.151.0"}
P.entries["item:sawtooth-snapper-claw"] = {n="Sawtooth Snapper Claw",s="Les Sawtooth Snapper Claws proviennent des sawtooth snappers qui vivent le long de la côte du Marais des Chagrins. Tok'Kar les prépare en armes pour aider à défendre Pierrêche.",h="Les Sawtooth Snapper Claws proviennent des sawtooth snappers qui vivent le long de la côte du Marais des...",kw={"côte","murloc","sawtooth snapper","sawtooth snapper claw","pierrêche","marais des chagrins","tok'kar","armes"},ang={["faction:Horde"]="Tok'Kar aide à protéger Pierrêche, une colonie orque, contre les menaces qui viennent de la côte."},sec={{t="Des griffes pour Pierrêche",b="Le long de la côte du Marais des Chagrins, Tok'Kar demande des Sawtooth Snapper Claws pour renforcer les défenses de Pierrêche. Bien préparées, les pinces des sawtooth snappers font d'excellentes armes. Tok'Kar est posté sur la côte pour surveiller les murlocs et avertir Pierrêche si le danger devient trop grand."}},faq={{q="D'où viennent les Sawtooth Snapper Claws ?",a="Les Sawtooth Snapper Claws viennent des sawtooth snappers qui vivent sur la côte du Marais des Chagrins.",al={"origine des griffes de snapper","origine des griffes"}},{q="Qui veut ces griffes ?",a="Tok'Kar veut des Sawtooth Snapper Claws pour préparer des armes afin de défendre Pierrêche.",al={"qui veut les griffes de snapper","griffes de tok'kar"}},{q="Pourquoi Tok'Kar a-t-il besoin de ces griffes ?",a="Tok'Kar dit que ces griffes font de bonnes armes quand elles sont bien préparées, ce qui permet à Pierrêche de disposer de davantage d'armes en cas d'attaque.",al={"pourquoi des griffes","utilité des griffes"}},{q="Que fait Tok'Kar sur la côte ?",a="Tok'Kar et ses troupes surveillent la côte pour protéger Pierrêche ou l'avertir si une menace devient trop grande.",al={"rôle de tok'kar","pourquoi tok'kar est là"}}},fp="21,145,17.275.0,42.84.0,20.78.0,32.113.0,35.96.0"}
P.entries["item:scaber-stalk"] = {n="Pédoncule d'amanite",s="À Sombrivage, Barithras Lunombrage cherche des pédoncules d'amanite dans une caverne derrière les Chutes de la Bondissante.",h="À Sombrivage, Barithras Lunombrage cherche des pédoncules d'amanite dans une caverne derrière les Chutes de...",kw={"auberdine","barithras lunombrage","cave mushrooms","chutes de la bondissante","sombrivage","amanite phalloïde","pédoncule d'amanite"},ang={["profession:Herbalism"]="Ces tiges souterraines ne sont pas des herbes couramment échangées. Elles permettent de mieux comprendre l'effet des climats inhabituels des cavernes et des ombres grandissantes sur les champignons locaux.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous tenez compte de l'avertissement du Bosquet des Anciens et approchez ces champignons de la caverne avec prudence. Une présence corruptrice prolifère près des Chutes de la Bondissante."},sec={{t="Un spécimen fongique rare",b="Derrière les Chutes de la Bondissante, des pédoncules d'amanite poussent dans une caverne des montagnes du nord-est de Sombrivage. Ces champignons pâles prospèrent dans ses passages humides et isolés, loin de la végétation forestière en surface. Peu de gens les cueillent dans un lieu si reculé. À Auberdine, Barithras Lunombrage envoie des éclaireurs dans les ténèbres pour en rapporter les rares tiges."},{t="Une ombre dans les chutes",b="Le Bosquet des Anciens a déconseillé aux Elfes de la nuit des environs de s'approcher de la caverne où poussent les pédoncules d'amanite. Ses esprits des arbres ont senti un mal obscur et grandissant s'emparer des Chutes de la Bondissante. Les alchimistes prisent ces tiges et les rares amanites phalloïdes pour préparer des breuvages expérimentaux. Ceux qui les cherchent pourraient rencontrer la malveillance qui s'amasse sous les montagnes."}},faq={{q="Où poussent les pédoncules d'amanite ?",a="Les pédoncules d'amanite poussent dans une caverne humide derrière les Chutes de la Bondissante, dans les montagnes du nord-est de Sombrivage.",al={"emplacement du pédoncule d'amanite","où trouver des pédoncules d'amanite","caverne des pédoncules d'amanite"}},{q="Qui recherche des pédoncules d'amanite ?",a="À Auberdine, Barithras Lunombrage recherche des pédoncules d'amanite et une amanite phalloïde pour préparer une potion spéciale.",al={"qui utilise les pédoncules d'amanite","champignons de barithras lunombrage","qui recherche des pédoncules d'amanite"}},{q="Pourquoi Barithras Lunombrage n'a-t-il pas cueilli les tiges lui-même ?",a="Le Bosquet des Anciens a averti Barithras de ne pas s'approcher après que ses esprits ont senti un nouveau mal dangereux se réfugier dans la caverne derrière la chute d'eau.",al={"pourquoi ne pas les cueillir lui-même","avertissement à barithras lunombrage","avertissement sur la caverne des chutes de la bondissante"}},{q="Qu'est-ce qui pousse aussi avec les pédoncules d'amanite ?",a="La caverne abrite aussi l'amanite phalloïde mortelle, un autre spécimen rare dont Barithras a besoin pour ses recherches alchimiques.",al={"autres champignons de la caverne","amanite phalloïde et pédoncule d'amanite","champignons des chutes de la bondissante"}}},fx={["053fa90e"]={q="Pourquoi quelqu'un voudrait-il des Pédoncules d'amanite ?",a="Barithras Lunombrage, à Auberdine, cherche des Pédoncules d'amanite car il s'agit d'un ingrédient vital pour la préparation de potions spécialisées. Comme ces champignons puissants ne poussent que dans la grotte isolée près des Chutes de la Bondissante, les herboristes et les alchimistes doivent compter sur des voyageurs aventureux pour les récolter.",al={"pourquoi récolter des pédoncules d'amanite","usage du pédoncule d'amanite","à quoi servent les pédoncules d'amanite"}},f5b84e96={q="Qu'est-ce qu'un Pédoncule d'amanite ?",a="Un Pédoncule d'amanite est une espèce rare de champignon de grotte originaire de la caverne ombragée nichée derrière les Chutes de la Bondissante à Sombrivage. Bien que les champignons souterrains soient courants à travers le nord de Kalimdor, cette variété particulière prospère dans les grottes sombres et humides qui abritent des énergies sinistres.",al={"qu'est-ce qu'un pédoncule d'amanite","infos sur le pédoncule d'amanite","champignon pédoncule d'amanite"}}},fp="12,91,22.313.0,21.337.1,28.101.0,24.98.0,58.141.0,40.122.0"}
P.entries["item:scale-of-old-murk-eye"] = {n="Ecaille du Vieux Troubloeil",s="Sur la côte de la Marche de l’Ouest, le Capitaine Grayson cherche la preuve de la mort du Vieux Troubloeil. Le fantôme hante le Phare de l'Ouest, où les attaques du murloc ont plongé le phare dans l’obscurité.",h="Sur la côte de la Marche de l’Ouest, le Capitaine Grayson cherche la preuve de la mort du Vieux Troubloeil.",kw={"capitaine grayson","menace côtière","murloc","vieux troubloeil","ecaille du vieux troubloeil","marche de l’ouest","phare de l'ouest"},ang={["faction:Alliance"]="En tant que marin de l’Alliance qui traverse la Grande mer vers Hurlevent, vous pouvez contribuer à mettre fin aux attaques du Vieux Troubloeil, maintenir le phare de la Marche de l’Ouest allumé et empêcher les navires de se fracasser contre les rochers."},sec={{t="Trophée d’un fléau côtier",b="Le Vieux Troubloeil a transformé la côte de la Marche de l’Ouest en un lieu de massacre. Le Capitaine Grayson, le fantôme lié au Phare de l'Ouest, raconte que ce murloc rusé ralliait des murlocs moins malins pour attaquer le rivage. Troubloeil a chassé la famille du gardien, laissant le phare dans l’obscurité lorsque le navire de Grayson s’est fracassé contre les rochers.\n\nQuand la famille est revenue rallumer la flamme, Troubloeil a attaqué de nouveau et l’a massacrée. Grayson cherche une écaille de la créature pour prouver que le rivage est débarrassé de son prédateur le plus féroce."}},faq={{q="À quoi sert l’Écaille du Vieux Troubloeil ?",a="Le Capitaine Grayson a besoin de l’écaille pour prouver que le Vieux Troubloeil est mort. Le fantôme hante le Phare de l'Ouest et cherche vengeance, car Troubloeil a laissé le phare dans l’obscurité lorsque le navire de Grayson a fait naufrage, puis a massacré la famille du gardien.",al={"qui veut l’écaille","remettre l’écaille de troubloeil","utilité de l’écaille du vieux troubloeil"}},{q="Qui est le Vieux Troubloeil ?",a="Le Vieux Troubloeil est un chef murloc féroce et rusé qui rôde sur les rivages sablonneux de la Marche de l’Ouest. Il sait organiser et contraindre les siens à mener des raids coordonnés et meurtriers contre les postes côtiers.",al={"qui est troubloeil","histoire de troubloeil","vieux troubloeil"}},{q="Pourquoi le Vieux Troubloeil a-t-il ciblé le phare ?",a="Le Vieux Troubloeil a d’abord attaqué le phare pour chasser le gardien et sa famille, plongeant la côte dans l’obscurité. À leur retour pour rallumer la flamme, il a rallié les siens pour une nouvelle attaque et a tué toute la famille. Les navires ne voyaient plus les dangereux hauts-fonds côtiers.",al={"pourquoi attaquer le phare","raid contre le phare","troubloeil et le phare"}}},fx={["6e72b95e"]={q="Qu'est-ce que l'Ecaille du Vieux Troubloeil ?",a="Il s'agit d'une écaille robuste et caractéristique prélevée directement sur la peau du Vieux Troubloeil, le célèbre chef murloc qui terrorise la côte de la Marche de l’Ouest. La porter constitue une preuve irréfutable que le redoutable pillard côtier a enfin été tué.",al={"qu'est-ce que l'écaille du vieux troubloeil","objet écaille du vieux troubloeil","écaille de troubloeil"}},["383f15e9"]={q="D'où provient l'Ecaille du Vieux Troubloeil ?",a="L'écaille provient de la peau naturelle du Vieux Troubloeil, un murloc particulièrement rusé et cruel qui rôde sur le rivage de la Marche de l’Ouest. Elle n'a pas été forgée ou fabriquée par des mains mortelles, mais récoltée sur sa dépouille après l'avoir vaincu au combat.",al={"origine de l'écaille du vieux troubloeil","où trouver l'écaille du vieux troubloeil","qui a fabriqué l'écaille du vieux troubloeil"}},e7059369={q="Pourquoi le Capitaine Grayson veut-il l'Ecaille du Vieux Troubloeil ?",a="Le Capitaine Grayson, le fantôme d'un capitaine de navire qui hante le Phare de l'Ouest, cherche à se venger et à trouver le repos. Le Vieux Troubloeil a fait fuir la famille du gardien de phare, laissant le fanal éteint la nuit où le navire de Grayson a heurté les récifs, et lorsque la famille est revenue, il a attaqué de nouveau et les a massacrés. Grayson exige l'écaille comme preuve irréfutable que la bête est morte et que la côte est plus sûre.",al={"pourquoi grayson veut-il l'écaille","pourquoi l'écaille du vieux troubloeil est-elle recherchée","qui veut l'écaille du vieux troubloeil"}}},fp="21,165,27.481.0,43.240.0,20.178.0,43.277.0"}
P.entries["item:scarlet-armband"] = {n="Bracelets écarlates",s="Au Glas, les Bracelets écarlates signalent les zélotes qui s’aventurent en territoire réprouvé. L’Exécuteur Arren les rassemble pour prouver que les nouveaux Réprouvés ont riposté.",h="Au Glas, les Bracelets écarlates signalent les zélotes qui s’aventurent en territoire réprouvé.",kw={"le glas","exécuteur arren","bracelets écarlates","nouveau converti écarlate","croisade écarlate","initié écarlate","clairières de tirisfal"},ang={["race:Undead"]="En tant que Réprouvé fraîchement relevé, rassembler des Bracelets écarlates vous confronte à la haine du monde des vivants. Votre survie dépend de votre capacité à vous défendre contre la Croisade."},sec={{t="Un insigne de fanatisme",b="Les Bracelets écarlates distinguent les fidèles de la Croisade écarlate, des Initiés écarlates aux nouveaux convertis. Leur insigne rouge avertit les Réprouvés nouvellement ressuscités du Glas qu’un danger rôde à proximité. Les croisés ne font aucune distinction entre les serviteurs sans esprit du Fléau et les sujets de la Dame noire dotés de libre arbitre. À leurs yeux, tout cadavre ambulant doit brûler.\n\nL’Exécuteur Arren rassemble les bracelets pour confirmer la mort des éclaireurs ennemis au sud-est du Glas. Il lui faut prouver que les nouveaux Réprouvés peuvent défendre leur nation naissante."}},faq={{q="Pourquoi l’Exécuteur Arren veut-il des Bracelets écarlates ?",a="L’Exécuteur Arren veut des Bracelets écarlates pour prouver que le camp de la Croisade écarlate au sud-est du Glas est en train d’être décimé. La Croisade menace les Réprouvés nouvellement éveillés, et ces insignes montrent que ses éclaireurs avancés et ses recrues ont été éliminés.",al={"pourquoi ramasser des bracelets","quête des bracelets d’arren","utilité des bracelets écarlates"}},{q="Qui porte ces bracelets ?",a="Les Initiés écarlates, les nouveaux convertis écarlates et le messager Meven Korgal portent ces bracelets. Ce sont des membres de bas rang de la Croisade écarlate stationnés près du Glas.",al={"qui fait tomber les bracelets écarlates","où trouver les bracelets"}},{q="Pourquoi la Croisade écarlate hait-elle les Réprouvés ?",a="La Croisade écarlate hait les Réprouvés, car ses zélotes ne voient aucune différence entre le Fléau sans esprit du roi-liche et les Réprouvés doués de libre arbitre. Ils considèrent tous les morts-vivants comme des abominations à éradiquer.",al={"pourquoi les écarlates attaquent les morts-vivants","croisade écarlate contre réprouvés","zélotes écarlates"}},{q="Où se trouve le camp où trouver ces bracelets ?",a="Le camp se trouve juste au sud-est du Glas, dans les Clairières de Tirisfal, dans les collines au-delà des limites de la colonie.",al={"emplacement du camp écarlate","camp écarlate du glas","où trouver les nouveaux convertis écarlates"}}},fx={["365b2391"]={q="Qu'est-ce que les Bracelets écarlates ?",a="Les Bracelets écarlates sont un morceau de tissu cramoisi porté par les initiés et les convertis de The Scarlet Crusade. Ils servent d'insigne d'identification pour cet ordre humain zélé, marquant ceux qui les portent comme des croisés dévoués à l'éradication de tous les morts-vivants de Lordaeron, que ces morts-vivants servent le Fléau ou possèdent leur libre arbitre, comme les Réprouvés.",al={"qu'est-ce qu'un bracelets écarlates","signification des bracelets écarlates","lore des bracelets écarlates"}}},fp="15,158,21.513.0,46.244.0,25.169.0,47.204.0,52.110.0"}
P.entries["item:scarlet-crusade-documents"] = {n="Documents de la Croisade écarlate",s="Au camp de la Croisade près du Glas, un messager transporte des Documents de la Croisade écarlate à travers les Clairières de Tirisfal. Leurs ordres nomment les commandants de terrain et dirigent leurs forces, renseignant les Réprouvés sur les positions écarlates dans les Clairières.",h="Au camp de la Croisade près du Glas, un messager transporte des Documents de la Croisade écarlate à travers...",kw={"brill","le glas","exécuteur arren","exécuteur zygand","meven korgal","documents de la croisade écarlate","the red messenger","vital intelligence"},ang={["race:Undead"]="Réprouvé nouvellement éveillé, vous transportez ces documents depuis les épreuves du cimetière du Glas jusqu’à Brill, où se coordonne l’effort de guerre."},sec={{t="Ordres interceptés",b="Meven Korgal transportait les documents depuis le campement de la Croisade au sud-est du Glas. Les ordres du Highlord s’adressent aux capitaines du Tirisfal Regional Command de la Croisade. Le Captain Perrine doit fortifier la tour sud-ouest et recueillir des informations sur les morts-vivants à Brill.\n\nLe Captain Vachon doit écraser les mouvements des morts-vivants près de la tour nord, tandis que le Captain Melrose surveille les frontières des Plaguelands. Les ordres nomment les officiers de terrain écarlates, leurs postes et leurs fonctions dans les Clairières de Tirisfal."},{t="Livraison à Brill",b="L’Exécuteur Arren constate que les forces locales du Glas ne peuvent pas pleinement exploiter ces renseignements. Les documents capturés deviennent le laissez-passer d’un Réprouvé nouvellement éveillé pour quitter Le Glas. Portez-les vers le nord-est, au-delà du Manoir du Foyer froid, jusqu’à Brill, puis remettez-les à l’Exécuteur Zygand devant l’Hôtel de ville de Brill. Munis de ces ordres, les chefs militaires réprouvés peuvent planifier des frappes rapides contre les commandants écarlates retranchés dans les Clairières."}},faq={{q="Qui transportait ces documents ?",a="Meven Korgal, un coursier de la Croisade écarlate, transportait les documents au campement de la Croisade au sud-est du Glas.",al={"qui a laissé tomber ces documents","messager écarlate","meven korgal"}},{q="Que contiennent ces documents ?",a="Les ordres du Highlord s’adressent au Tirisfal Regional Command de la Croisade. Le Captain Perrine doit fortifier la tour sud-ouest et recueillir des informations sur les morts-vivants à Brill. Le Captain Vachon doit écraser les mouvements des morts-vivants près de la tour nord, et le Captain Melrose doit surveiller les frontières des Plaguelands.",al={"que disent les documents","contenu des documents"}},{q="Qui doit recevoir ces documents ?",a="Vous récupérez les documents pour l’Exécuteur Arren au Glas. Il vous les confie pour les remettre à l’Exécuteur Zygand, qui supervise les opérations militaires régionales devant l’Hôtel de ville de Brill.",al={"où les apporter","à qui remettre les documents"}},{q="Pourquoi ces documents sont-ils importants pour les Réprouvés ?",a="Les ordres révèlent où sont déployés les officiers écarlates dans les Clairières de Tirisfal. Les Réprouvés peuvent s’en servir pour éliminer les chefs ennemis et briser le moral régional des fanatiques.",al={"pourquoi les réprouvés les veulent","importance des documents écarlates"}}},fx={b6ac443b={q="Que sont les Documents de la Croisade écarlate ?",a="Il s'agit d'une liasse de documents militaires confidentiels, de rapports de bataille et d'ordres portés par un messager de The Scarlet Crusade. Bien qu'une grande partie du paquet se compose de comptes-rendus de reconnaissance ordinaires et de propagande concernant des escarmouches avec les Réprouvés, il contient également des instructions opérationnelles détaillées destinées aux officiers de la Croisade stationnés dans les Clairières de Tirisfal.",al={"que sont les documents","informations sur les documents de la croisade écarlate","objet documents de la croisade écarlate"}},["5f5d9cee"]={q="D'où viennent les Documents de la Croisade écarlate ?",a="Ce sont des directives émises sur ordre du généralissime de la Croisade aux capitaines de son commandement régional de Tirisfal. Elles ont été confiées à un messager nommé Meven Korgal, que les Réprouvés ont trouvé au camp de la Croisade au sud-est de Le Glas.",al={"qui a écrit les documents de la croisade écarlate","source des documents écarlates","d'où viennent les documents"}}},fp="25,243,18.495.0,17.427.0,33.115.0,41.295.0,33.180.0,50.172.0"}
P.entries["item:scarlet-insignia-ring"] = {n="Anneau de la Croisade écarlate",s="Dans les Clairières de Tirisfal, les anneaux de la Croisade écarlate distinguent ses membres. À Brill, les Réprouvés les recueillent pour prouver qu'un autre zélote est tombé.",h="Dans les Clairières de Tirisfal, les anneaux de la Croisade écarlate distinguent ses membres.",kw={"brill","nécrogarde burgess","exécuteur zygand","proof of demise","croisade écarlate","anneau de la croisade écarlate","clairières de tirisfal","varimathras"},ang={["faction:Horde"]="En tant que membre de la Horde, collecter ces anneaux aide à assurer une présence dans les Royaumes de l'est. Chacun d'eux affaiblit les croisés fanatiques des environs de Fossoyeuse.",["race:Undead"]="En tant que Réprouvé, arracher ces anneaux aux Croisés morts affirme que les Clairières de Tirisfal appartiennent aux morts. Cela permet aussi d'obéir aux ordres de la Dame noire et de Varimathras."},sec={{t="Insignes du fanatisme",b="Chaque combattant de la Croisade écarlate dans les Clairières de Tirisfal porte un anneau distinctif. Les néophytes et les frères zélés en portent, tout comme les capitaines Melrache et Perrine. Le sceau ardent de la Croisade marque chaque anneau. Il identifie les membres d'un ordre rongé par la paranoïa. Pour les étrangers, ces anneaux signalent les derniers humains les plus fanatiques de Lordaeron."},{t="La prime du seigneur de l'effroi",b="Le Nécrogarde Burgess, à Brill, collecte les anneaux sur ordre de Varimathras. Il est le lieutenant seigneur de l'effroi de dame Sylvanas. Les Réprouvés voient la Croisade écarlate comme une peste qui ravage leur patrie nouvellement conquise. Les recrues rapportent les anneaux à Brill pour prouver la mort d'un Croisé et leur loyauté envers le trône de Fossoyeuse."}},faq={{q="Qui porte ces anneaux distinctifs ?",a="Presque tous les membres de la Croisade écarlate en poste dans les Clairières de Tirisfal portent un anneau distinctif. Les néophytes, les missionnaires, les zélotes et les avant-gardistes en portent, tout comme les officiers de terrain, les capitaines Perrine, Melrache et Vachon.",al={"qui laisse tomber des anneaux","quels croisés portent des anneaux","porteurs d'anneaux"}},{q="Pourquoi le Nécrogarde Burgess veut-il des anneaux de la Croisade écarlate ?",a="Le Nécrogarde Burgess collecte les anneaux pour prouver que des Croisés écarlates sont tués. Il obéit aux ordres de Varimathras et de la Dame noire. À Brill, la garnison réprouvée se sert des anneaux pour évaluer la loyauté des recrues et leur succès à chasser les humains de Lordaeron.",al={"pourquoi collecter les anneaux","raison de proof of demise","anneaux de burgess"}},{q="Que représente l'insigne de l'anneau ?",a="L'anneau porte la marque de la Croisade écarlate et représente sa guerre sainte visant à éradiquer tous les morts-vivants de Lordaeron. Les Croisés le portent avec une immense fierté, comme un symbole de leur vertu. Leur obsession les pousse à massacrer quiconque ne fait pas partie de leur ordre.",al={"symbole écarlate","que représente l'insigne","emblème de l'anneau"}},{q="Quel rôle Varimathras joue-t-il dans la collecte de ces anneaux ?",a="Varimathras est le principal lieutenant de Sylvanas Coursevent à Fossoyeuse. Il supervise les opérations militaires contre les humains vivants hostiles dans les Clairières de Tirisfal. La Croisade écarlate est une priorité pour les commandants réprouvés tels que l'Exécuteur Zygand et le Nécrogarde Burgess.",al={"ordres de varimathras","pourquoi varimathras veut les anneaux","rôle du seigneur de l'effroi"}}},fx={d4097e42={q="Qu'est-ce qu'un Anneau de la Croisade écarlate ?",a="Un Anneau de la Croisade écarlate est une bague d'identification portée par les membres de The Scarlet Crusade à travers les Clairières de Tirisfal. Arborant l'emblème de l'ordre militant, elle marque l'allégeance de celui qui la porte à leur croisade fanatique visant à éradiquer les morts-vivants. Pour les Réprouvés défendant leurs nouvelles frontières, ces anneaux servent de preuve indiscutable qu'un soldat ou un officier ennemi a été éliminé.",al={"qu'est-ce qu'un anneau de la croisade écarlate","lore de l'anneau de la croisade écarlate","que sont ces anneaux"}}},fp="21,155,18.319.0,23.321.0,31.226.0,56.262.0,45.244.0,58.256.0"}
P.entries["item:scavenged-goods"] = {n="Fournitures de récupération",s="Autour du Glas, les Réprouvés récupèrent des Fournitures de récupération dans des caisses d’équipement. Les morts-vivants récemment relevés comptent sur ces provisions abandonnées pour armer et vêtir les recrues qui les suivent.",h="Autour du Glas, les Réprouvés récupèrent des Fournitures de récupération dans des caisses d’équipement.",kw={"garde noir saltain","le glas","caisses d’équipement","provisions des réprouvés","fournitures de récupération","la chasse aux trésors"},ang={["race:Undead"]="En tant que Réprouvé, vous avez besoin d’équipement abandonné pour survivre. Les vivants ne vous offrent ni aide ni clémence."},sec={{t="Se débrouiller seuls",b="De nouveaux Réprouvés se lèvent dans le cimetière du Glas, vêtus de simples linceuls funéraires en décomposition. Les colonies et royaumes voisins ne leur portent aucun secours, ils doivent donc récupérer ce dont ils ont besoin. Le Garde noir Saltain rassemble des armes, des outils et des vêtements abandonnés dans des caisses réparties dans tout le village. Il remet ces fournitures aux prochaines recrues qui se lèvent."}},faq={{q="À quoi servent les fournitures récupérées ?",a="Le Garde noir Saltain rassemble des Fournitures de récupération pour équiper les nouveaux Réprouvés qui se lèvent du cimetière. Sans les provisions des caisses voisines, ils entreraient dans les Clairières de Tirisfal sans armes ni vêtements.",al={"utilité des fournitures récupérées","pourquoi récupérer des fournitures","que fait saltain des fournitures récupérées"}},{q="Où trouve-t-on ces fournitures ?",a="Ces fournitures se trouvent dans des caisses d’équipement devant les chaumières et autour des bâtiments en ruine, partout au Glas.",al={"où trouver des fournitures récupérées","emplacement des fournitures récupérées","où se trouvent les caisses d’équipement"}},{q="Qui réclame les fournitures récupérées ?",a="Le Garde noir Saltain, un officier du Glas, demande aux Réprouvés fraîchement éveillés de rassembler les provisions. Il leur apprend à se débrouiller seuls et prépare l’arrivée des recrues qui les suivent.",al={"qui veut les fournitures récupérées","quête du garde noir saltain"}}},fx={f565021a={q="Que sont les Fournitures de récupération ?",a="Ce sont divers équipements, vêtements et matériels utilisables, récupérés dans de vieilles caisses laissées éparpillées autour du Glas. Plutôt que de l'armement immaculé, il s'agit de vestiges de l'ancienne vie de la ville qui peuvent encore servir à des fins pratiques pour les Réprouvés récemment éveillés.",al={"que sont les fournitures de récupération","qu'est-ce que les fournitures de récupération"}},["0b2267aa"]={q="D'où viennent les Fournitures de récupération ?",a="Elles proviennent de caisses d'équipement abandonnées parmi les structures en ruine du Glas. Appartenant autrefois aux habitants vivants de Lordaeron avant que le royaume ne tombe sous le fléau, ces provisions sont restées oubliées dans les ruines jusqu'à ce que les Réprouvés commencent à récupérer la ville comme base d'opérations.",al={"origine des fournitures de récupération","qui a fabriqué les fournitures de récupération","d'où viennent les fournitures de récupération"}},["36f8df02"]={q="Pourquoi le Garde noir Saltain veut-il des Fournitures de récupération ?",a="Les Réprouvés éveillent continuellement de nouveaux morts depuis le cimetière, et ces nouvelles recrues arrivent dans le monde avec presque rien. Le Garde noir Saltain rassemble ces objets récupérés afin que les morts-vivants émergents disposent de vêtements et d'un équipement de base au lieu d'entrer au service du peuple sans armes et exposés.",al={"pourquoi saltain veut-il des fournitures de récupération","pourquoi collecter des fournitures de récupération","pourquoi les fournitures de récupération sont-elles nécessaires"}}},fp="15,161,22.332.0,34.183.0,28.96.0,33.170.0"}
P.entries["item:scavenger-paw"] = {n="Patte de charognard",s="Au Glas, la Patte de charognard provient de jeunes loups dépenaillés des collines. Les Réprouvés fraîchement réveillés ramassent ces pattes pour que les intendants locaux les assemblent en équipement de protection rudimentaire.",h="Au Glas, la Patte de charognard provient de jeunes loups dépenaillés des collines.",kw={"le glas","novice elreth","ragged scavenger","patte de charognard","the damned","young scavenger"},ang={["profession:Tailoring"]="En tant que couturier, vous pouvez voir comment Novice Elreth assemble des pattes de loup et des ailes de chauve-souris pour confectionner un équipement rudimentaire destiné aux jeunes communautés réprouvées.",["race:Undead"]="En tant que Réprouvé fraîchement réveillé, à la chair en décomposition et presque sans équipement, vous pouvez récupérer des morceaux sur les prédateurs locaux pour fabriquer assez d’armure face aux dangers de Tirisfal."},sec={{t="Armure de bric et de broc au Glas",b="Le Fléau et la Croisade écarlate menacent Tirisfal, et chaque morceau de peau ou d’os trouve une utilité pratique. Au Glas, les Réprouvés revenus depuis peu ont peu de ressources. Novice Elreth aide le Prêtre des ombres Sarvis en ramassant des pattes de loups charognards ainsi que des ailes de chauve-souris.\n\nElle confectionne des vêtements et des armures utilisables pour les Réprouvés qui viennent de sortir de leur tombe. Ils sont encore désorientés par leur retour."}},faq={{q="À quoi servent les Pattes de charognard ?",a="Novice Elreth ramasse des Pattes de charognard au Glas et assemble des pièces animales pour confectionner des vêtements et des armures rudimentaires destinés aux Réprouvés fraîchement sortis de leur tombe.",al={"utilité des pattes de charognard","usage des pattes","pourquoi ramasser des pattes"}},{q="Où les trouver ?",a="Vous les trouverez sur les Young Scavengers et les Ragged Scavengers, des loups sauvages qui rôdent dans les bois et les champs autour du Glas.",al={"lieu d’obtention des pattes","où trouver des pattes","loups qui donnent des pattes"}},{q="Qui réclame ces pattes ?",a="Novice Elreth réclame ces pattes. Elle aide le Prêtre des ombres Sarvis à soigner les recrues blessées, à confectionner leur équipement et à équiper ceux qui partent sur le terrain.",al={"qui réclame les pattes de charognard","personnage qui donne la quête des pattes","pattes de novice elreth"}}},fx={["41bb56d4"]={q="Qu'est-ce qu'une Patte de charognard ?",a="Une Patte de charognard est la patte coupée d'un loup charognard qui rôde dans les bois hantés des Clairières de Tirisfal autour du Glas. Bien qu'il s'agisse de trophées sinistres en apparence, ces pièces animales durables servent de matière première pour les Réprouvés récemment éveillés, qui doivent utiliser chaque morceau de la faune locale pour fabriquer les nécessités et survivre.",al={"identité de la patte de charognard","que sont les pattes de charognard","qu'est-ce qu'une patte de charognard"}},["366465d3"]={q="D'où provient une Patte de charognard ?",a="Ces pattes sont récoltées sur les jeunes loups charognards décharnés qui rôdent à la périphérie du Glas. Traquant les clairières flétries juste au-delà des murs du village, ces bêtes sauvages fouillent la campagne dévastée à la recherche de charogne, ce qui en fait des proies faciles pour les nouvelles recrues Réprouvés cherchant à prouver leur force.",al={"source de la patte de charognard","où obtenir une patte de charognard","pattes de loup charognard"}},f83538b8={q="Pourquoi quelqu'un voudrait-il des Pattes de charognard ?",a="La Novice Elreth, au Glas, les collectionne pour confectionner des armures et des vêtements robustes pour les soldats Réprouvés récemment éveillés. Les ressources sont désespérément rares pour les nouveaux morts-vivants libres, et Elreth assemble des peaux, des ailes et des pattes pour réparer l'équipement qui peut vous protéger des morts-vivants sans esprit et des Croisés écarlates qui menacent le refuge.",al={"pourquoi collecter des pattes de charognard","qui a besoin de pattes de charognard","lore sur l'utilisation des pattes de charognard"}}},fp="13,178,27.408.0,33.132.0,23.117.0,24.158.0"}
P.entries["item:sceptre-of-light"] = {n="Sceptre of Light",s="Le Sceptre of Light est une relique qui, selon la légende, peut engloutir des villes. Un voyant de la Lame ardente le détient à la Forteresse de Hache-Tonnerre, en Désolace.",h="Le Sceptre of Light est une relique qui, selon la légende, peut engloutir des villes.",kw={"azore aldamort","lame ardente","désolace","ethel rethor","nagas","sceptre of light","voyant","forteresse de hache-tonnerre"},sec={{t="Le prix d’un voyant",b="Depuis une tour de guet de la Forteresse de Hache-Tonnerre, un voyant de la Lame ardente étudie le Sceptre of Light. La Lame ardente l’aurait pris aux nagas. Les légendes affirment que son pouvoir peut engloutir des villes entières, aussi Azore Aldamort, à Ethel Rethor, cherche-t-il à le récupérer."}},faq={{q="Que fait le Sceptre of Light ?",a="La légende dit que le Sceptre of Light peut engloutir des villes entières.",al={"pouvoir du sceptre","que peut-il faire","sceptre de lumière"}},{q="Qui détient le Sceptre of Light ?",a="Un voyant de la Lame ardente étudie le Sceptre of Light depuis une tour de guet de la Forteresse de Hache-Tonnerre.",al={"qui le détient","détenteur du sceptre","sceptre de la lame ardente"}},{q="Où se trouve le Sceptre of Light ?",a="Le Sceptre of Light est détenu à la Forteresse de Hache-Tonnerre, en Désolace.",al={"où est le sceptre","emplacement du sceptre","sceptre de hache-tonnerre"}},{q="Qui veut récupérer le sceptre ?",a="Azore Aldamort, à la tour d’Ethel Rethor, veut récupérer le Sceptre of Light.",al={"qui le veut","sceptre d’azore","ethel rethor"}},{q="Où la Lame ardente l’a-t-elle trouvé ?",a="La Lame ardente aurait obtenu le Sceptre of Light auprès des nagas.",al={"sceptre des nagas","d’où vient-il","origine du sceptre"}}},fp="16,135,16.270.0,34.72.0,29.92.0,30.65.0,31.80.0,35.81.0"}
P.entries["item:scorched-ectoplasm"] = {n="Scorched Ectoplasm",s="Scorched Ectoplasm est une matière spectrale recueillie auprès des esprits torturés d’elfes de la nuit en Silithus. Mux Brouillemana en a besoin pour ses travaux sur les morts.",h="Scorched Ectoplasm est une matière spectrale recueillie auprès des esprits torturés d’elfes de la nuit en...",kw={"ectoplasme","alambic ectoplasmique","gadgetzan","mux brouillemana","scorched ectoplasm","silithus","tortured druide","tortured sentinel"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous reconnaîtrez peut-être l’Alambic ectoplasmique, l’appareil dont se sert Mux Brouillemana pour recueillir la matière spectrale."},sec={{t="Une trace calcinée",b="En Silithus, les esprits torturés de druides et de Sentinelles libèrent du Scorched Ectoplasm. Mux Brouillemana, un ingénieur gobelin de Gadgetzan, le recherche avec d’autres formes d’ectoplasme. Il pense que leurs étranges énergies peuvent atteindre les âmes qui demeurent près du monde des vivants."}},faq={{q="Qu’est-ce que le Scorched Ectoplasm ?",a="C’est une matière spectrale prélevée sur les esprits torturés d’elfes de la nuit de Silithus.",al={"scorched ectoplasm","qu’est-ce que le scorched ectoplasm","objet ectoplasmique"}},{q="D’où vient le Scorched Ectoplasm ?",a="Les Tortured Druids et les Tortured Sentinels de Silithus libèrent du Scorched Ectoplasm.",al={"où trouver le scorched ectoplasm","emplacement du scorched ectoplasm","où en trouver"}},{q="Pourquoi Mux Brouillemana en veut-il ?",a="Mux Brouillemana espère utiliser les énergies surnaturelles de l’ectoplasme pour atteindre les âmes qui demeurent près du monde des vivants.",al={"pourquoi mux veut de l’ectoplasme","mux et l’ectoplasme","que fait mux"}},{q="Quels sont les autres types d’ectoplasme ?",a="Le Frozen Ectoplasm provient des esprits des Bien-nés de Berceau-de-l’Hiver, tandis que le Stable Ectoplasm provient des fantômes et des banshees des Maleterres de l’Est.",al={"autres ectoplasmes","ectoplasme gelé et stable","types d’ectoplasme"}},{q="Où trouver Mux Brouillemana ?",a="Vous trouverez Mux Brouillemana à Gadgetzan, en Tanaris.",al={"où est mux","emplacement de mux","gobelin de gadgetzan"}}},fp="18,146,16.265.0,27.76.0,40.76.0,35.119.0,38.144.0,35.56.0"}
P.entries["item:scorched-spider-fang"] = {n="Croc d'araignée brûlé",s="Dans les Paluns, les Cave Stalkers et les Leech Stalkers portent des Crocs d'araignée brûlés. Furen Barbe-longue, à Hurlevent, en a besoin de cinquante pour renforcer les mailles des guerriers de l'Alliance.",h="Dans les Paluns, les Cave Stalkers et les Leech Stalkers portent des Crocs d'araignée brûlés.",kw={"cave stalker","fire hardened mail","furen barbe-longue","leech stalker","croc d'araignée brûlé","hurlevent","les paluns"},ang={["class:Warrior"]="En tant que guerrier, vous devez relever l'épreuve de Furen Barbe-longue : rassembler cinquante crocs. Cette tâche met votre endurance à l'épreuve et vous fournit les matériaux bruts de votre armure de mailles.",["profession:Blacksmithing"]="En tant que forgeron, vous pouvez observer comment Furen incorpore la chitine brûlée et les crocs aux anneaux des mailles, selon de rares traditions naines de forge d'armure qui dépassent la simple fusion."},sec={{t="La formule d'un forgeron nain",b="À Hurlevent, le forgeron Furen Barbe-longue renforce les mailles par des moyens inhabituels. Il lui faut cinquante crocs brûlés des araignées géantes des Paluns. Leur substance dense et venimeuse a durci sous l'effet de la chaleur. Furen l'incorpore aux anneaux des mailles pendant qu'il les trempe."},{t="Les rôdeuses des Paluns",b="Les Cave Stalkers et les Leech Stalkers portent les crocs dont Furen a besoin. Elles vivent dans les vallées englouties et les terriers des Paluns, parmi l'humidité et la pourriture. Leurs mandibules sont durcies et brûlées. En rassembler cinquante vous oblige à vous aventurer dans de profondes cavités et à affronter des essaims d'araignées."}},faq={{q="À quoi servent les Crocs d'araignée brûlés ?",a="Furen Barbe-longue, à Hurlevent, a besoin de cinquante Crocs d'araignée brûlés pour forger une armure de torse résistante destinée aux guerriers de l'Alliance. Il lui faut aussi des composants des Serres-Rocheuses et du Kraal de Tranchebauge.",al={"que faire des crocs d'araignée brûlés","utilité du croc d'araignée brûlé","qui a besoin de crocs d'araignée brûlés"}},{q="Où trouver des Crocs d'araignée brûlés ?",a="Les Cave Stalkers et les Leech Stalkers des Paluns portent des Crocs d'araignée brûlés. Cherchez dans leurs terriers humides, sur les flancs des collines et dans les cavernes d'excavation.",al={"où trouver le croc d'araignée brûlé","quelles araignées lâchent le croc d'araignée brûlé","où farmer des crocs d'araignée brûlés"}},{q="Pourquoi un forgeron a-t-il besoin d'autant de crocs d'araignée pour fabriquer une armure ?",a="Furen Barbe-longue emploie des méthodes naines inhabituelles pour renforcer les mailles. Il traite leurs anneaux avec des crocs durcis, du phlogiston et des cornes de bête.",al={"pourquoi cinquante crocs","pourquoi furen a-t-il besoin de crocs d'araignée"}},{q="N'importe quel aventurier peut-il ramasser ces crocs et les rapporter ?",a="Toute personne qui traverse les Paluns peut tuer les araignées et prendre leurs mandibules. Furen ne commande cette armure qu'aux aspirants guerriers qui veulent mériter des mailles trempées au feu.",al={"le croc d'araignée brûlé est-il réservé aux guerriers","qui peut rapporter des crocs d'araignée brûlés"}}},fx={a7a99cbb={q="Qu'est-ce qu'un Croc d'araignée brûlé ?",a="Un Croc d'araignée brûlé est une dent venimeuse durcie et traitée à la chaleur, récoltée sur des arachnides prédateurs comme les Cave Stalkers et les Leech Stalkers qui rôdent dans Les Paluns. Leur apparence noircie et cassante dissimule une densité extraordinaire, ce qui les rend prisés parmi les armuriers qualifiés à la recherche de composants rares pour des techniques de forge avancées.",al={"qu'est-ce qu'un croc d'araignée brûlé","crocs d'araignée brûlés","croc brûlé"}},c6d8f632={q="D'où viennent les Crocs d'araignée brûlés ?",a="Ces crocs ne sont pas fabriqués par des mains mortelles ; ils sont récoltés directement sur les arachnides géants des Paluns, spécifiquement les Leech Stalkers et les Cave Stalkers. Une exposition constante aux éléments souterrains et l'alchimie naturelle de leur venin confèrent à ces crocs leur résilience noircie et traitée par le feu.",al={"d'où viennent les crocs d'araignée brûlés","origine du croc d'araignée brûlé","source du croc d'araignée brûlé"}}},fp="20,165,25.253.0,24.267.0,40.185.0,39.138.0,62.133.0,51.175.0"}
P.entries["item:scorpashi-venom"] = {n="Scorpashi Venom",s="Le venin scorpashi est un réactif prélevé sur les scorpions qui parcourent le Désolace. Kreldig Ungor en a besoin pour réunir les matériaux demandés par Reclaimers Inc.",h="Le venin scorpashi est un réactif prélevé sur les scorpions qui parcourent le Désolace.",kw={"peau de kodo âgé","désolace","kreldig ungor","leftwitch","reclaimers inc","scorpashi","venin scorpashi"},ang={["class:Mage"]="La liste de Leftwitch comprend du venin scorpashi, l’un des réactifs les plus étranges qu’un mage puisse rechercher."},sec={{t="La liste d’un mage",b="Kreldig Ungor rassemble des matériaux dans le Désolace pour Reclaimers Inc., en suivant la liste préparée par Leftwitch. Le venin scorpashi est l’un des éléments requis par le mage, avec des peaux de kodos âgés. Kreldig a hâte de terminer la liste et de retourner à Forgefer."}},faq={{q="À quoi sert le venin scorpashi ?",a="Leftwitch demande du venin scorpashi pour la liste de matériaux que Kreldig Ungor rassemble pour Reclaimers Inc.",al={"utilisation du venin scorpashi","pourquoi récolter du venin","réactif de venin"}},{q="Qui a besoin du venin ?",a="Kreldig Ungor récolte le venin dans le Désolace pour Reclaimers Inc., en suivant la liste de Leftwitch.",al={"qui veut du venin scorpashi","venin de kreldig","qui en a besoin"}},{q="D’où vient le venin scorpashi ?",a="Le venin scorpashi provient des scorpions présents dans tout le Désolace.",al={"où trouver du venin","lieu des scorpashi","source du venin"}},{q="Quel autre matériau figure sur la liste de Leftwitch ?",a="Kreldig a aussi besoin de peaux de kodos âgés ; les consignes de Leftwitch précisent des kodos âgés, et non mourants ou anciens.",al={"autre réactif","de quoi kreldig a-t-il aussi besoin","peau de kodo âgé"}}},fp="15,147,15.257.0,33.104.0,20.100.0,37.67.0,45.120.0"}
P.entries["item:scrap-metal-scrounging"] = {n="Scrap Metal",s="La ferraille se récupère sur les ogres de la Grotte de Crache-poussière, dans les Terres Ingrates. Sigrun en a besoin pour construire des défenses et ravitailler un petit camp.",h="La ferraille se récupère sur les ogres de la Grotte de Crache-poussière, dans les Terres Ingrates.",kw={"terres ingrates","camp","grotte de crache-poussière","explorers' league","forgefer","ogres","ferraille","récupération de matériaux","sigrun"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous voyez pourquoi Sigrun a besoin de ferraille : le camp manque de matériaux pour ses défenses et ses autres besoins.",["race:Dwarf"]="En tant que nain, vous savez peut-être que le camp attend des nouvelles de Forgefer, tandis que Sigrun fait avec les fournitures dont elle dispose."},sec={{t="Pour le camp",b="Sigrun a besoin de ferraille pour les défenses et d’autres fournitures indispensables au camp des Terres Ingrates. Les ogres de la Grotte de Crache-poussière, à l’ouest, en portent, et le camp en a peu en réserve. En attendant des nouvelles de Forgefer ou de l’Explorers' League, chaque pièce est utile."}},faq={{q="À quoi sert la ferraille ?",a="Sigrun a besoin de ferraille pour construire des défenses et d’autres installations indispensables au camp des Terres Ingrates.",al={"utilité de la ferraille","pourquoi récupérer de la ferraille","métal pour sigrun"}},{q="Où trouver de la ferraille ?",a="Les ogres de la Grotte de Crache-poussière, à l’ouest du camp de Sigrun dans les Terres Ingrates, portent de la ferraille.",al={"emplacement de la ferraille","où trouver du métal","métal de crache-poussière"}},{q="Qui veut de la ferraille ?",a="Sigrun veut de la ferraille pour aider à ravitailler et à défendre le camp.",al={"qui a besoin de métal","ferraille pour sigrun","métal pour qui"}},{q="Pourquoi Sigrun rassemble-t-elle des fournitures ?",a="Sigrun a peu de matériaux pour les défenses du camp et ses autres besoins, alors il rassemble tout ce qu'il peut.",al={"fournitures nécessaires au camp","pourquoi récupérer des matériaux","défenses de sigrun"}}},fp="11,141,12.251.0,24.98.0,29.88.0,26.60.0,33.103.0"}
P.entries["item:scrimshank-s-surveying-gear"] = {n="Scrimshank's Surveying Gear",s="L’équipement d’arpentage de Scrimshank repose sous les sables de Tanaris, dans le Gouffre béant. Le grand géomètre Radiésthéflop a besoin de ses relevés pour enquêter sur les insectes étranges du désert.",h="L’équipement d’arpentage de Scrimshank repose sous les sables de Tanaris, dans le Gouffre béant.",kw={"radiésthéflop","le gouffre béant","gobelin","jeune géomètre","scrimshank","silithide","équipement d’arpentage","tanaris"},sec={{t="Sous les sables",b="Dans le Gouffre béant de Tanaris, l’équipement d’arpentage de Scrimshank est tout ce qui reste du jeune géomètre disparu. Son supérieur, le Grand Géomètre Radiésthéflop, l’avait envoyé dans le désert après des signalements d’insectes étranges. La machine contient les derniers relevés de Scrimshank, qui pourraient aider à comprendre le danger qui menace Gadgetzan."}},faq={{q="Qu’est-ce que l’équipement d’arpentage de Scrimshank ?",a="C’est l’équipement d’arpentage du jeune géomètre Scrimshank, retrouvé sous Tanaris, dans le Gouffre béant.",al={"équipement de scrimshank","machine d’arpentage","qu’est-ce que l’équipement"}},{q="Où se trouve l’équipement d’arpentage ?",a="L’équipement d’arpentage de Scrimshank repose dans le Gouffre béant, sous Tanaris.",al={"emplacement de l’équipement","où est l’équipement de scrimshank","équipement du gouffre béant"}},{q="Qui était Scrimshank ?",a="Le jeune géomètre Scrimshank était l’assistant du Grand Géomètre Radiésthéflop, qui l’avait envoyé enquêter sur d’étranges insectes dans le Gouffre béant.",al={"jeune géomètre","histoire de scrimshank","qui est scrimshank"}},{q="Pourquoi Radiésthéflop veut-il récupérer l’équipement ?",a="Radiésthéflop espère que les relevés de Scrimshank aideront à découvrir ce qui se passe avec les insectes étranges du désert.",al={"utilité de l’équipement","radiésthéflop le veut","qu’a-t-il consigné"}}},fp="27,178,17.297.0,36.103.0,28.69.0,19.126.0,36.111.0"}
P.entries["item:scroll-of-messaging"] = {n="Parchemin de contact",s="Dans les Serres-Rocheuses, Gaxim Larguerouille prépare un message qui déclenchera des explosifs à distance.",h="Dans les Serres-Rocheuses, Gaxim Larguerouille prépare un message qui déclenchera des explosifs à distance.",kw={"explosifs","gaxim larguerouille","ng-5","détonateur à distance","parchemin de contact","les serres-rocheuses","kapitalrisk"},ang={["faction:Alliance"]="Pour les agents de l’Alliance, le parchemin aide à saboter les machines de la KapitalRisk et à entraver la destruction de la forêt des Serres-Rocheuses.",["profession:Engineering"]="Le parchemin montre comment l’ingénierie gnome peut exploiter la magie des arcanes pour recevoir un signal et déclencher des explosifs à distance."},sec={{t="Un message explosif",b="À l’exploitation forestière de la KapitalRisk, Gaxim Larguerouille va transformer un message en explosion. Il prévoit d’associer l’incantation de transmission du parchemin à des charges volatiles de NG-5. L’explosion éloignera les gardes. Les agents pourront alors se faufiler et dérober des schémas d’ingénierie ainsi que de la correspondance confidentielle."}},faq={{q="À quoi sert le Parchemin de contact ?",a="Gaxim Larguerouille utilise la magie de transmission du Parchemin de contact pour déclencher du NG-5 à distance. Ensemble, ils lui permettent de provoquer une explosion à distance.",al={"utilité du parchemin de contact","effet du parchemin de contact","pourquoi gaxim veut le parchemin"}},{q="Qui reçoit ce parchemin ?",a="Gaxim Larguerouille, un ingénieur gnome des Serres-Rocheuses, reçoit le parchemin.",al={"qui reçoit le parchemin de contact","où apporter le parchemin de contact","destinataire du parchemin"}},{q="Pourquoi Gaxim a-t-il besoin d’un explosif à distance ?",a="Gaxim a besoin de provoquer une diversion majeure à l’exploitation de la KapitalRisk. Le chaos couvrira une infiltration, le vol de plans d’ingénierie et la récupération de documents destinés à mettre fin à la coupe à blanc de la forêt par la compagnie.",al={"raison de l’explosif de gaxim","pourquoi faire exploser la kapitalrisk","diversion dans les serres-rocheuses"}},{q="Qu’est-ce que le NG-5 ?",a="Le NG-5 est une charge chimique explosive utilisée par Gaxim Larguerouille. Associée au signal magique du parchemin, elle forme un détonateur à distance.",al={"ng-5","qu’est-ce que le ng-5","explosif ng-5"}}},fx={["2071477e"]={q="Qu'est-ce que le Parchemin de contact ?",a="Le Parchemin de contact est un parchemin enchanté portant un sortilège arcanique. Gaxim Larguerouille l'a recherché comme un catalyseur non conventionnel à combiner avec son composé explosif volatil, le NG-5, lui permettant de fabriquer une charge déclenchée à distance contre les opérations de la KapitalRisk dans les Serres-Rocheuses.",al={"qu'est-ce que le parchemin de contact","lore du parchemin de contact","à propos du parchemin de contact"}}},fp="19,98,18.314.0,41.152.0,25.84.0,39.220.0,13.130.0"}
P.entries["item:scroll-of-myzrael"] = {n="Parchemin de Myzrael",s="Le Parchemin de Myzrael s’utilise aux Fragments de Myzrael, dans les Hautes-terres Arathies, pour la rappeler.",h="Le Parchemin de Myzrael s’utilise aux Fragments de Myzrael, dans les Hautes-terres Arathies, pour la rappeler.",kw={"hautes-terres arathies","chaînes indicibles","myzrael","princesse","parchemin de myzrael","fragments de myzrael","invocation"},sec={{t="Aux fragments",b="Aux Fragments de Myzrael, dans les Hautes-terres Arathies, le parchemin invoque l’être retenu sous ces fragments. Vous devez vaincre Myzrael et lier ses Chaînes indicibles aux fragments. Cette tâche vise à la garder captive tandis que son pouvoir grandit."}},faq={{q="À quoi sert le Parchemin de Myzrael ?",a="Le Parchemin de Myzrael s’utilise pour invoquer Myzrael aux Fragments de Myzrael, dans les Hautes-terres Arathies.",al={"utilisation du parchemin de myzrael","à quoi sert ce parchemin","invoquer myzrael"}},{q="Où utiliser le parchemin ?",a="Le parchemin s’utilise aux Fragments de Myzrael, dans les Hautes-terres Arathies, où Myzrael a été rencontrée pour la première fois.",al={"où utiliser le parchemin","emplacement des fragments de myzrael","où l’invoquer"}},{q="Pourquoi invoquer Myzrael ?",a="Vous devez vaincre Myzrael avant que son pouvoir grandisse, puis la lier de nouveau aux fragments avec ses Chaînes indicibles.",al={"pourquoi invoquer myzrael","à quoi ça sert","pourquoi la rappeler"}},{q="À quoi servent les Chaînes indicibles ?",a="Les Chaînes indicibles sont liées aux Fragments de Myzrael pour la piéger de nouveau.",al={"utilité des chaînes indicibles","chaînes de myzrael","comment la lier"}}},fp="17,103,13.232.0,35.97.0,26.105.0,19.107.1,35.75.1"}
P.entries["item:sea-creature-bones"] = {n="Os de créature marine",s="À Sombrivage, des Os de créature marine s'échouent avec les dépouilles d'immenses créatures marines. Gwennyth Bly'Leggonde recueille des échantillons pour le Temple de la Lune, à Darnassus, où l'on enquête sur la cause de ces échouements.",h="À Sombrivage, des Os de créature marine s'échouent avec les dépouilles d'immenses créatures marines.",kw={"auberdine","beached sea creature","sombrivage","murlocs greymist","gwennyth bly'leggonde","la lisière des brumes","os de créature marine","temple de la lune"},ang={["class:Druid"]="En tant que druide, vous voyez dans la mort inexpliquée d'anciens prédateurs marins le signe d'un profond bouleversement des eaux au large de Kalimdor. Un tel bouleversement inquiète tout gardien voué à l'équilibre écologique.",["race:NightElf"]="En tant qu'elfe de la nuit, vous savez que ces échouements massifs et soudains troublent profondément votre peuple, qui révère l'harmonie du monde naturel. Il voit dans ces échouements un sombre présage qui requiert l'attention du Temple de la Lune."},sec={{t="Un présage sur le rivage",b="D'immenses créatures marines se jettent désormais sur les hauts-fonds de Sombrivage et y périssent. Parmi elles, des batteurs géants bien plus grands que ceux qui vivent dans ces eaux. Pour les elfes de la nuit, cette soudaine recrudescence est un présage funeste. Le Temple de la Lune a envoyé Gwennyth Bly'Leggonde à Auberdine pour recueillir des os sur les créatures échouées. Des hippogriffes transportent les spécimens à Darnassus pour un examen approfondi."},{t="Charognes et charognards",b="Les immenses carcasses attirent les charognards locaux. Les murlocs Greymist se rassemblent pour se nourrir des créatures mortes ou mourantes, puis défendent férocement leurs zones de nourrissage. Ils sont trop faibles pour chasser des bêtes de cette taille. Les enquêteurs et les aventuriers doivent donc se frayer un chemin à travers leurs groupes le long de La lisière des brumes afin de récupérer des fragments d'os pour les étudier."}},faq={{q="Pourquoi ces créatures s'échouent-elles ?",a="La cause exacte reste inconnue. Les échouements occasionnels sont un danger naturel, mais leur recrudescence soudaine et spectaculaire inquiète les prêtresses d'Élune, qui la jugent contre nature et ont ouvert une enquête officielle.",al={"pourquoi les batteurs s'échouent","baleines mortes à sombrivage","pourquoi les créatures s'échouent à sombrivage"}},{q="Qui veut ces os ?",a="Gwennyth Bly'Leggonde recueille les os à Auberdine pour le Temple de la Lune, à Darnassus. Les érudits et les prêtresses espèrent y découvrir ce qui perturbe la mer.",al={"qui récupère les os","qui rapporte les os de créature marine","gwennyth à sombrivage"}},{q="Les murlocs ont-ils tué ces bêtes géantes ?",a="Non. Les murlocs Greymist sont trop faibles pour abattre des créatures marines de cette taille. Ils se rassemblent pour se nourrir après leur échouement.",al={"les murlocs ont-ils tué le batteur","les murlocs greymist ont-ils tué le monstre marin"}},{q="D'où proviennent les os récupérés ?",a="Les os proviennent d'immenses carcasses échouées le long de Sombrivage, en particulier sur les plages au sud d'Auberdine et le long de La lisière des brumes.",al={"où trouver des os de créature marine","lieux d'échouement des créatures marines"}}},fx={["90a4db20"]={q="Que sont ces Os de créature marine ?",a="Ce sont des restes squelettiques récupérés sur la carcasse massive d'une bête marine échouée—spécifiquement un thresher inhabituellement grand—échoué le long du littoral brumeux de Sombrivage. Récupérés par les murlocs locaux Greymist, ces restes massifs servent de preuve physique vitale pour les chercheurs essayant de comprendre pourquoi les béhémoths de l'océan périssent sur le rivage.",al={"que sont les os de créature marine","lore des os de créature marine","os géants sombrivage"}},cb40613a={q="D'où viennent les Os de créature marine ?",a="Ces os proviennent d'un thresher colossal, bien plus grand que tout ce qui est attendu dans les eaux de Sombrivage, qui s'est inexplicablement jeté sur les plages de La lisière des brumes au sud d'Auberdine. Plutôt que d'avoir été fabriqués ou tués par des prédateurs locaux, les os appartiennent naturellement à des bêtes des grands fonds qui se sont mystérieusement échouées pour mourir.",al={"d'où viennent les os de créature marine","origine des os de créature marine","origine de la créature marine échouée"}}},fp="18,223,22.411.0,22.319.0,39.208.0,22.166.0,40.143.0,35.129.0"}
P.entries["item:sea-turtle-remains"] = {n="Restes de tortue de mer",s="Le long de Sombrivage, des Restes de tortue de mer s’accumulent sur la côte et sous les vagues. À Auberdine, des chercheurs étudient le nombre croissant de tortues marines mortes.",h="Le long de Sombrivage, des Restes de tortue de mer s’accumulent sur la côte et sous les vagues.",kw={"auberdine","beached sea turtle","sombrivage","gwennyth bly'leggonde","restes de tortue de mer","teldrassil","temple de la lune","washed ashore"},ang={["class:Druid"]="La mort anormale de grandes créatures marines révèle une corruption plus profonde qui trouble l’équilibre de la nature sur les côtes de Kalimdor.",["race:NightElf"]="L’échouage massif d’espèces marines au large de votre côte ancestrale est un signe inquiétant. La cause présumée se trouve dans les eaux qui entourent Teldrassil."},sec={{t="Un rivage inquiétant",b="D’immenses créatures marines s’échouent le long de Sombrivage, tandis que d’autres reposent sous l’eau, près d’épaves englouties. À Auberdine, Gwennyth Bly'Leggonde recueille des fragments d’os et des tissus sur leurs dépouilles. Le Temple de la Lune, à Darnassus, réclame ces échantillons de toute urgence. Ses érudits et ses prêtresses craignent que les créatures ne fuient une perturbation anormale dans les eaux autour de Teldrassil."},{t="Les charognards des bas-fonds",b="Récupérer les restes est dangereux. Des tribus de murlocs se rassemblent sur la côte autour des carcasses gigantesques, nettoient leurs os et nichent à leurs côtés. Les érudits ont besoin de fragments d’os et de tissus frais avant que les charognards ne détruisent des indices susceptibles d’expliquer la migration fatale des créatures."}},faq={{q="À quoi servent ces restes ?",a="À Auberdine, Gwennyth Bly'Leggonde recueille des restes pour les érudits et les prêtresses du Temple de la Lune, à Darnassus. Ils cherchent à comprendre pourquoi tant de créatures marines meurent le long de Sombrivage.",al={"pourquoi recueillir les restes de tortue","utilité des os de tortue","quête tortue marine sombrivage"}},{q="Pourquoi les tortues marines s’échouent-elles à Sombrivage ?",a="Les chercheurs n’ont pas trouvé la cause, mais ils craignent que la faune marine ne fuie une présence inquiétante dans les eaux autour de Teldrassil. Ces échouages témoignent d’une détresse généralisée parmi les espèces marines.",al={"pourquoi les tortues meurent","échouages de tortues à sombrivage","créatures marines échouées"}},{q="Où trouve-t-on ces carcasses ?",a="D’immenses carcasses de tortues marines reposent le long de la côte de Sombrivage. Certaines se trouvent dans des eaux peu profondes, près d’épaves à l’ouest d’Auberdine, tandis que d’autres jonchent les plages, entourées de campements de murlocs.",al={"emplacements des restes de tortue","où trouver une tortue marine squelettique"}},{q="Qui étudie ces restes ?",a="À Auberdine, Gwennyth Bly'Leggonde recueille les restes et envoie des rapports détaillés à la Sisterhood of Elune, au Temple de la Lune, à Darnassus.",al={"qui veut les restes","gwennyth blyleggonde"}}},fx={be90da46={q="D'où viennent les Restes de tortue de mer ?",a="Ils sont ramassés directement sur les carcasses squelettiques massives qui gisent le long des rivages et dans les eaux côtières de Sombrivage, notamment sur les spécimens trouvés près d'Auberdine. Ce sont des restes naturels de bêtes marines plutôt que des objets fabriqués, laissés là quand des tortues mourantes s'échouent et périssent.",al={"d'où viennent les restes de tortue de mer","origine des restes de tortue de mer","source des restes de tortue de mer"}},dfe0d6c5={q="Que sont ces Restes de tortue de mer ?",a="Ces restes sont des échantillons squelettiques récupérés sur des tortues de mer géantes qui se sont échouées le long du littoral de Sombrivage ou qui sont mortes dans ses eaux peu profondes. Bien que récupérés par des prédateurs locaux et des murlocs, des os et des tissus récupérables subsistent, offrant des indices physiques sur les derniers instants des créatures.",al={"que sont les restes de tortue de mer","lore des restes de tortue de mer","qu'est-ce que les restes de tortue de mer"}}},fp="18,149,19.379.0,26.287.0,32.199.0,53.195.0,32.181.0,30.150.0"}
P.entries["item:seahorn-s-sealed-letter"] = {n="Seahorn's Sealed Letter",s="La lettre scellée de Seahorn contient une correspondance secrète de la Baie-du-Butin à Shakes O'Breen, au large de la côte d'Arathi. Les Raiders de Blackwater comptent sur sa livraison en toute sécurité.",h="La lettre scellée de Seahorn contient une correspondance secrète de la Baie-du-Butin à Shakes O'Breen, au...",kw={"côte d'arathi","raiders de blackwater","baie-du-butin","seahorn","lettre scellée","correspondance secrète","shakes o'breen"},sec={{t="Un message scellé",b="Depuis la Baie-du-Butin, Seahorn vous demande de porter sa lettre scellée à Shakes O'Breen, dont le navire se trouve au large de la côte d'Arathi. La flotte de Seahorn attend des provisions dans la baie, tandis que des affaires inquiétantes se trament à proximité et au loin. Il vous demande de la discrétion autant qu'un passage sûr. Les Raiders de Blackwater attendent de savoir si le message est arrivé à bon port."}},faq={{q="Qui a envoyé la lettre scellée ?",a="Seahorn a envoyé la lettre scellée depuis la Baie-du-Butin. Il demande qu'elle parvienne à Shakes O'Breen en toute sécurité et en toute discrétion.",al={"qui l'a écrite","lettre de seahorn"}},{q="Qui doit la recevoir ?",a="Shakes O'Breen, retenu au large de la côte d'Arathi, est le destinataire prévu de la lettre.",al={"qui reçoit la lettre","à qui la remettre","lettre pour shakes"}},{q="Pourquoi Seahorn a-t-il besoin d'un messager ?",a="Seahorn a besoin que la correspondance scellée soit portée à Shakes O'Breen, tandis que sa flotte est immobilisée à la Baie-du-Butin dans l'attente de provisions.",al={"pourquoi la remettre","que contient la lettre","message secret"}},{q="Que se passe-t-il si je la livre sans encombre ?",a="Les Raiders de Blackwater vous sont reconnaissants d'avoir accompli ce long et périlleux voyage, et Seahorn est satisfait lorsque le message parvient à son destinataire.",al={"en échange de la livraison","raiders de blackwater","seahorn satisfait"}}},fp="23,166,16.341.0,27.109.0,30.88.0,32.122.0,36.133.1"}
P.entries["item:sealed-description-of-thredd-s-visitor"] = {n="Description scellée du visiteur de Thredd",s="Le Gardien Thelwater scelle un rapport sur l’homme qui rend visite à Bazil Thredd dans la Stormwind Stockade. Ce compte rendu confidentiel pourrait aider les enquêteurs à suivre quelqu’un dans les cercles politiques et criminels de Hurlevent.",h="Le Gardien Thelwater scelle un rapport sur l’homme qui rend visite à Bazil Thredd dans la Stormwind Stockade.",kw={"baros alexston","bazil thredd","maelik","mathias shaw","description scellée","prison","gardien thelwater"},ang={["class:Rogue"]="En tant que voleur, vous pouvez comprendre pourquoi les faux noms, les papiers falsifiés et les visites à la prison ont attiré l’attention de Mathias Shaw, lorsqu’il a comparé l’apparence de l’homme aux renseignements du SI:7.",["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez constater la faille dans la sécurité de Hurlevent : des conspirateurs peuvent franchir les portes de la Prison avec de faux papiers."},sec={{t="Un mystérieux protecteur",b="Pendant des années, le prisonnier Bazil Thredd n’a reçu aucune visite dans la Prison. Puis un homme discret a commencé à venir une ou deux fois par semaine, muni de papiers en règle au nom de Maelik. Le Gardien Thelwater l’a remarqué et a consigné son apparence. Il a scellé la description pour empêcher les curieux de la lire avant que les enquêteurs compétents n’agissent."},{t="Des maçons aux espions",b="L’architecte de la ville Baros Alexston n’a trouvé aucune correspondance évidente dans la description. Il soupçonnait le visiteur d’être lié à la rébellion des Defias. Il a donc envoyé l’Enveloppe scellée à Maître Mathias Shaw, chef du service de renseignement de Hurlevent, le SI:7. Shaw a reconnu un mercenaire mortel qui utilise notamment le nom de Marzon. À présent, ce mercenaire fait le sale travail du Lord Gregor Lescovar."}},faq={{q="Qui a rédigé cette description ?",a="Le Gardien Thelwater, chef des gardiens de la Stormwind Stockade, a rédigé et scellé le document. Il a commencé à se méfier lorsqu’un inconnu s’est mis à rendre régulièrement visite au chef des Defias emprisonné, Bazil Thredd.",al={"qui l’a rédigée","auteur de la description","qui a écrit la note"}},{q="Qui est le visiteur décrit dans le document ?",a="Le visiteur portait des papiers au nom de Maelik. Le Gardien Thelwater a consigné son apparence afin que les enquêteurs puissent l’identifier.",al={"qui rendait visite à thredd","qui est maelik","identité du visiteur"}},{q="Pourquoi le visiteur rencontrait-il Bazil Thredd ?",a="Après des années sans visite, Bazil Thredd a commencé à recevoir des visiteurs régulièrement. La description scellée fait l’objet d’une enquête afin de découvrir le motif de ces visites.",al={"pourquoi rendre visite à thredd","motif du visiteur de thredd"}},{q="Où faut-il apporter ce document scellé ?",a="Apportez d’abord le document à l’architecte de la ville Baros Alexston, à Hurlevent. Après avoir examiné cette description inconnue, Alexston vous demande de la remettre à Maître Mathias Shaw, au quartier général du SI:7, dans la Vieille ville.",al={"où l’apporter","qui veut la description"}}},fx={["7193ccc9"]={q="Pourquoi la description du visiteur de Thredd est-elle si importante ?",a="Pendant des années, Bazil Thredd est resté seul à la Prison sans recevoir une seule visite. Lorsqu'une silhouette mystérieuse portant des papiers au nom de « Maelik » a soudainement commencé à lui rendre visite chaque semaine, le Gardien Thelwater a commencé à soupçonner une conspiration plus profonde. Démasquer ce visiteur est vital pour découvrir qui à Hurlevent coordonne activement les actions avec les chefs incarcérés de la Confrérie défias, ce qui pousse les enquêteurs à solliciter le réseau de renseignements de Mathias Shaw pour identifier cet agent de l'ombre.",al={"pourquoi veulent-ils la description","description scellée du visiteur de thredd pourquoi demandée","pourquoi la description du visiteur est-elle importante"}}},fp="38,215,19.325.0,25.380.1,27.196.0,42.127.2,46.153.2,49.206.1"}
P.entries["item:sealed-envelope"] = {n="Enveloppe scellée",s="Dans les Serres-Rocheuses, Fizziks a scellé les secrets de la KapitalRisk dans l’Enveloppe scellée destinée à Krachevalve, à Cabestan.",h="Dans les Serres-Rocheuses, Fizziks a scellé les secrets de la KapitalRisk dans l’Enveloppe scellée destinée à...",kw={"plans","fizziks","cabestan","enveloppe scellée","krachevalve","les serres-rocheuses","super reaper 6000","kapitalrisk"},ang={["faction:Horde"]="En tant que membre de la Horde, transporter ces documents vers le sud depuis les Serres-Rocheuses aide les gobelins neutres de Cabestan à saper les exploitations forestières agressives et abusives de la KapitalRisk.",["profession:Engineering"]="Pour un ingénieur, l’enveloppe renferme les plans techniques du Super Reaper 6000, une machine destructrice et lucrative conçue par des gobelins."},sec={{t="Espionnage industriel",b="Banni des exploitations forestières de la KapitalRisk dans les Serres-Rocheuses, l’ingénieur gobelin Fizziks en a dérobé les secrets. L’enveloppe contient des manuels de l’entreprise, des procédures d’exploitation et des plans techniques. Parmi eux se trouvent les schémas du Super Reaper 6000, une machine conçue pour la coupe rase à l’échelle industrielle."},{t="Livraison à Cabestan",b="Fizziks envoie les documents vers le sud, à Krachevalve, un ingénieur du port gobelin neutre de Cabestan. Les rivaux du Cartel Gentepression n’ont guère d’affection ni de confiance pour Fizziks. Pourtant, les plans ont une réelle valeur technique. Ils révèlent le savoir-faire mécanique de la KapitalRisk et permettent aux ingénieurs indépendants d’adopter ses méthodes forestières avancées."}},faq={{q="Que contient l’Enveloppe scellée ?",a="L’Enveloppe scellée renferme des manuels de la KapitalRisk, des documents techniques et les schémas du Super Reaper 6000, une machine de défrichage. Fizziks les a volés en quittant précipitamment l’entreprise.",al={"contenu de l’enveloppe","que contient l’enveloppe scellée","objets de l’enveloppe scellée"}},{q="Qui a préparé ce paquet ?",a="L’ingénieur gobelin Fizziks a préparé l’enveloppe après que la KapitalRisk l’a banni de ses exploitations forestières dans les Serres-Rocheuses.",al={"qui a préparé l’enveloppe","qui a remis l’enveloppe scellée","enveloppe de fizziks"}},{q="À qui est-il destiné ?",a="L’enveloppe est destinée à Krachevalve, un bricoleur gobelin de Cabestan, ville portuaire des Tarides.",al={"qui reçoit l’enveloppe","où va l’enveloppe","livraison à krachevalve"}},{q="Pourquoi Krachevalve veut-il ces documents ?",a="Krachevalve n’aime pas la KapitalRisk, et les documents contiennent des améliorations précieuses et des schémas. Ils permettent aux bricoleurs indépendants de comprendre et d’adopter ses puissantes conceptions mécaniques.",al={"pourquoi krachevalve la veut","technologie de la kapitalrisk à cabestan"}}},fp="15,109,19.315.0,19.342.0,35.192.0,25.138.0,30.99.0,43.185.0"}
P.entries["item:sealed-note-to-advisor-belgrum"] = {n="Sealed Note to Advisor Belgrum",s="La note scellée de l’Historien Karnik porte un avertissement des Terres Ingrates au Conseiller Belgrum. Son contenu guide la prochaine étape contre les nains Shadowforge.",h="La note scellée de l’Historien Karnik porte un avertissement des Terres Ingrates au Conseiller Belgrum.",kw={"conseiller belgrum","terres ingrates","hammertoe","historien karnik","transmettre l’avertissement d’une menace","note scellée","shadowforge"},sec={{t="Un avertissement transmis",b="À Forgefer, vous portez la note de l’Historien Karnik au Conseiller Belgrum. Karnik vous demande de raconter à Belgrum ce dont vous avez été témoin et de solliciter son avis. Pendant ce temps, Karnik se tourne vers l’esprit de Hammertoe, dans l’espoir qu’il puisse aider à mettre fin aux activités des Shadowforge dwarves."}},faq={{q="Qui a écrit la note scellée ?",a="L’Historien Karnik a envoyé la note au Conseiller Belgrum.",al={"auteur de la note","qui a envoyé la note"}},{q="À qui est destinée la note ?",a="La note est adressée au Conseiller Belgrum.",al={"destinataire","note pour belgrum"}},{q="De quoi parle la note ?",a="Karnik dit que la note expliquera ce dont vous avez été témoin et demande à Belgrum de le guider sur la marche à suivre.",al={"que dit la note","contenu de la note"}},{q="Pourquoi Karnik envoie-t-il la note ?",a="Karnik veut que Belgrum entende votre récit et décide de la marche à suivre.",al={"pourquoi la porter","message de karnik"}},{q="Que fait Karnik pendant que vous la portez ?",a="Karnik prévoit de parler à l’esprit de Hammertoe, dans l’espoir qu’il puisse aider à mettre fin aux activités des nains Shadowforge dans les Terres Ingrates.",al={"que fait karnik","esprit de hammertoe"}}},fp="30,152,17.253.0,26.50.0,20.41.0,23.101.0,31.83.0,40.123.0"}
P.entries["item:sealed-note-to-elling"] = {n="Note scellée à Elling",s="À Hurlevent, Jorgen envoie un pli scellé à Elling Trias, propriétaire de Trias' Cheese. Le message du pêcheur entraîne Trias dans une enquête discrète sur la disparition d’un diplomate.",h="À Hurlevent, Jorgen envoie un pli scellé à Elling Trias, propriétaire de Trias' Cheese.",kw={"elling trias","jorgen","note scellée à elling","hurlevent","the missing diplomat","quartier commerçant","trias cheese"},ang={["class:Rogue"]="En tant que voleur familier des réseaux clandestins de Hurlevent, vous reconnaîtrez peut-être qu’Elling Trias est plus qu’un marchand de fromage. Cette correspondance discrète correspond aux méthodes de ces réseaux.",["faction:Alliance"]="En tant que membre de l’Alliance, vous transmettez le message de Jorgen au service de la Couronne. Vous contribuez ainsi à faire avancer une enquête essentielle à la stabilité politique de Hurlevent."},sec={{t="Une remise discrète",b="Jorgen confie une mission stricte à Hurlevent : remettre la note scellée à Elling Trias et garder le silence. L’enjeu ne laisse aucune place aux indiscrétions. Trias tient une fromagerie dans le Quartier commerçant. Là, le message de Jorgen lui apporte l’enquête sur la disparition du diplomate jusqu’à son comptoir."}},faq={{q="Que contient la note scellée ?",a="La note reste scellée jusqu’à ce qu’elle parvienne à Elling Trias. Elle contient le rapport de Jorgen et charge le messager de s’adresser à Trias pour poursuivre l’enquête sur la disparition du diplomate.",al={"contenu de la note","que dit la note","texte de la lettre"}},{q="Pourquoi un fromager reçoit-il des renseignements secrets ?",a="Elling Trias tient une modeste fromagerie dans le Quartier commerçant, qui lui sert de façade publique. Derrière cette apparence, il dispose dans toute la ville d’un vaste réseau souterrain d’yeux et d’oreilles. Cela le rend précieux pour les enquêtes délicates.",al={"pourquoi elling trias","pourquoi une fromagerie","trias est-il un espion"}},{q="Qui est Jorgen ?",a="Jorgen est un pêcheur que l’on trouve près de l’eau, dans la Vallée des héros de Hurlevent. Il a un passé commun avec Elling Trias et l’évêque DeLavey, qui fait appel à lui pour des affaires discrètes, à l’abri des regards indiscrets.",al={"qui a écrit la note","histoire de jorgen","garde jorgen"}},{q="En quoi consiste l’affaire du diplomate disparu ?",a="Un diplomate de Hurlevent envoyé à Theramore pour rencontrer Jaina Portvaillant n’est jamais arrivé. Les autorités royales examinent discrètement chaque piste suspecte afin d’éviter de semer la panique dans les rues.",al={"histoire du diplomate disparu","qui est le diplomate","pourquoi le diplomate a-t-il disparu"}}},fx={["76232759"]={q="Qu'est-ce que la Note scellée à Elling ?",a="Il s'agit d'un message confidentiel que vous remet Jorgen, destiné spécifiquement aux oreilles — et aux yeux — d'Elling Trias. Scellé à la cire pour garantir sa confidentialité, il contient des informations urgentes concernant l'enquête sur le diplomate disparu, que l'on vous a confié pour une livraison en main propre à travers Hurlevent.",al={"qu'est-ce que la note scellée à elling","objet note scellée à elling","qu'est-ce que la note de jorgen"}},["2cd529f3"]={q="D'où vient la Note scellée à Elling ?",a="La note a été écrite et scellée par Jorgen. Après avoir interrogé des témoins et évalué les pistes concernant le diplomate disparu du royaume, Jorgen rédige ce message discret et le place directement entre vos mains pour que vous l'apportiez à Elling Trias.",al={"qui a écrit la note scellée à elling","d'où vient la note scellée","qui a donné la note scellée à elling"}},["92e95eae"]={q="Pourquoi la Note scellée à Elling est-elle nécessaire ?",a="La disparition du diplomate est une affaire de la plus haute importance pour la sécurité de l'État. Jorgen ne peut s'exprimer librement dans les rues, c'est pourquoi la note sert d'introduction discrète et permet de transmettre des renseignements à Elling Trias, l'impliquant ainsi dans l'enquête sans éveiller les soupçons.",al={"pourquoi livrer la note scellée","pourquoi elling trias a-t-il besoin de la note","pourquoi la note de jorgen est-elle importante"}}},fp="21,176,16.297.0,39.169.0,53.235.0,14.197.0,40.177.0"}
P.entries["item:sealed-note-to-watcher-backus"] = {n="Note scellée pour Backus",s="À Hurlevent, Elling Trias envoie une note scellée au Gardien Backus, dans le Bois de la Pénombre. Il demande au garde des Veilleurs de signaler les activités défias près de Sombre-Comté.",h="À Hurlevent, Elling Trias envoie une note scellée au Gardien Backus, dans le Bois de la Pénombre.",kw={"sombre-comté","bois de la pénombre","elling trias","les veilleurs","note scellée","the missing diplomat","gardien backus"},ang={["class:Rogue"]="En tant que voleur, vous pouvez voir Trias s’appuyer sur un garde ordinaire pour obtenir des renseignements locaux. Cela lui permet de recueillir des informations bien au-delà des murs de la ville.",["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez voir comment les liens personnels et les renseignements informels aident à maintenir la cohésion des territoires fragilisés de la faction lorsque les voies officielles échouent."},sec={{t="Un mot pour la garde",b="Elling Trias accepte de faire appel à ses contacts pour aider à retrouver le diplomate disparu. Il scelle une note pour le Gardien Backus, un garde des Veilleurs en poste dans le Bois de la Pénombre.\n\nTrias envoie un voyageur vers le sud, à travers la forêt, pour la remettre en main propre. Il espère que Backus signalera toute présence défias près de Sombre-Comté."},{t="Le vaste réseau de Trias",b="Elling Trias vend du fromage dans le Quartier commerçant de Hurlevent et garde des contacts au-delà de la ville. Sa note parvient au Gardien Backus, un garde des Veilleurs méfiants de Sombre-Comté.\n\nSombre-Comté est menacée par les morts-vivants et les bêtes sauvages. Backus accueille avec plaisir le message de Trias, signe que celui-ci a gagné le respect au-delà de Hurlevent."}},faq={{q="Qui a écrit cette note ?",a="Elling Trias a écrit la note. Il possède Trias' Cheese dans le Quartier commerçant de Hurlevent et travaille secrètement comme espion et courtier en renseignements.",al={"qui a écrit la note scellée pour le gardien backus","auteur de la note","qui remet la note"}},{q="Pourquoi l’envoyer au Gardien Backus ?",a="Le Gardien Backus sert dans les Veilleurs de Sombre-Comté et est un contact de confiance d’Elling Trias. Trias lui demande de signaler les observations ou rumeurs locales concernant les activités de la Confrérie défias dans les environs du Bois de la Pénombre.",al={"qui est le gardien backus","pourquoi envoyer la note à backus","quel est le rôle de backus"}},{q="Où trouver le Gardien Backus ?",a="Le Gardien Backus patrouille sur la route, juste au nord de Sombre-Comté, dans le Bois de la Pénombre. Il surveille les abords forestiers de la ville.",al={"où se trouve backus","emplacement du gardien backus","trouver le gardien backus"}},{q="Que se passe-t-il après la remise de la note ?",a="Backus reconnaît le nom de Trias et fait confiance à sa demande. Il met de côté sa méfiance habituelle envers les voyageurs et accepte d’enquêter sur les activités suspectes dans les bois.",al={"que dit backus","après la remise de la note"}}},fx={["8647b8fc"]={q="Qu'est-ce que la Note scellée pour Backus ?",a="Il s'agit d'un message confidentiel écrit par Elling Trias, le maître marchand de fromage de Hurlevent, destiné au Gardien Backus dans le Bois de la Pénombre. Trias vous le confie pour obtenir l'aide de Backus dans la collecte de renseignements sur les activités locales de la Confrérie défias, dans le cadre de l'enquête en cours sur le diplomate disparu.",al={"qu'est-ce que la note scellée pour le gardien backus","but de la note scellée pour le gardien backus","note de trias pour backus"}}},fp="29,149,20.285.0,25.309.1,20.137.0,39.189.0,34.110.0,41.163.0"}
P.entries["item:sealed-venom-container"] = {n="Sealed Venom Container",s="Le Sealed Venom Container contient du venin récolté sur des créatures venimeuses de Silithus. À Gadgetzan, un ingénieur en a besoin pour fabriquer un appareil capable de parler aux morts.",h="Le Sealed Venom Container contient du venin récolté sur des créatures venimeuses de Silithus.",kw={"communiquer avec les morts","gadgetzan","mux brouillemana","sealed venom container","silithus","appareil surnaturel","venin"},sec={{t="Du venin pour Gadgetzan",b="Le venin de Silithus est transporté dans le Sealed Venom Container. L’échantillon est destiné à un ingénieur de Gadgetzan qui étudie le surnaturel. Il construit un appareil pour communiquer avec les morts, et le venin constitue le paiement de son travail."}},faq={{q="Que contient le Sealed Venom Container ?",a="Le Sealed Venom Container contient du venin récolté sur des créatures venimeuses de Silithus.",al={"contenu du conteneur de venin"}},{q="Où doit-on apporter le conteneur ?",a="Le conteneur est destiné à un ingénieur de Gadgetzan qui travaille sur un appareil permettant de parler aux morts.",al={"où apporter le venin","destination du conteneur de venin"}},{q="Qui veut le venin ?",a="Mux Brouillemana, un ingénieur de Gadgetzan qui s’intéresse au surnaturel, veut le venin.",al={"qui a besoin du conteneur","venin pour mux"}},{q="Pourquoi l’ingénieur a-t-il besoin de venin ?",a="Le venin constitue le paiement du travail de Mux Brouillemana sur un appareil capable de communiquer avec les morts.",al={"à quoi sert le venin","pourquoi donner du venin à mux"}}},fp="22,171,19.233.0,38.86.0,28.102.0,20.98.0,33.97.0"}
P.entries["item:searing-collar"] = {n="Collier brûlant",s="Au Rocher du Crâne, en Durotar, les Colliers brûlants brûlent les sectateurs de la Lame ardente qui les portent. Leur chaleur les aide à s'accorder aux pouvoirs démoniaques.",h="Au Rocher du Crâne, en Durotar, les Colliers brûlants brûlent les sectateurs de la Lame ardente qui les...",kw={"lame ardente","démon","durotar","gangrené","margoz","collier brûlant","rocher du crâne"},ang={["class:Warlock"]="En tant que démoniste, vous connaissez peut-être les Colliers brûlants comme de grossiers conduits qui canalisent la corruption gangrenée dans la chair des mortels.",["race:Orc"]="En tant qu'orc, découvrir des sectateurs utilisant ces colliers aux portes de Durotar vous rappelle sinistrement que l'ombre de la servitude démoniaque plane toujours."},sec={{t="Instruments de corruption",b="La Lame ardente se rassemble au Rocher du Crâne, juste à l'est d'Orgrimmar, pour accomplir de sombres rites. Les sectateurs, néophytes et voyous portent des Colliers brûlants autour du cou. Le métal marque et cautérise leur peau tandis qu'ils supportent sa chaleur.\n\nMargoz, un ermite, étudie ces cruels dispositifs. Il soupçonne que leur brûlure et leurs enchantements accordent leurs porteurs aux énergies démoniaques. Quel rôle les colliers jouent-ils dans la corruption qui se répand dans la société orque sous le nez de la Horde ?"}},faq={{q="Qu'est-ce qu'un Collier brûlant ?",a="Les sectateurs de la Lame ardente portent des Colliers brûlants autour du cou lors de rituels. Le métal chauffé leur brûle la chair et les aide à s'accorder aux pouvoirs démoniaques.",al={"que sont les colliers brûlants","histoire des colliers brûlants","à quoi sert le collier"}},{q="Qui porte ces colliers ?",a="Les membres de la Lame ardente qui se cachent dans le Rocher du Crâne portent ces colliers. Parmi eux figurent des sectateurs, des fanatiques, des voyous, des apprentis et des néophytes.",al={"qui les utilise","qui fait tomber les colliers brûlants","colliers de la lame ardente"}},{q="Pourquoi les sectateurs se brûlent-ils la chair ?",a="La Lame ardente utilise le métal brûlant dans ses rituels. En supportant les brûlures et l'enchantement démoniaque, les sectateurs accordent leur corps et leur esprit aux pouvoirs démoniaques.",al={"pourquoi se brûler la chair","pourquoi porter un collier brûlant","fonction du collier"}},{q="Qui veut examiner les Colliers brûlants ?",a="Margoz, un enquêteur qui campe en Durotar, rassemble des Colliers brûlants pour étudier leurs enchantements et découvrir l'influence de la Lame ardente.",al={"qui a besoin de colliers brûlants","qui étudie les colliers","colliers de margoz"}}},fp="14,140,25.448.0,25.149.0,24.139.0,41.162.0,41.141.0"}
P.entries["item:searing-coral"] = {n="Corail torride",s="Sur la côte des Paluns, on récolte le Corail torride sur des Iron Coral vivants, sous la mer. Les bricoleurs et les forgerons prisent ce minéral résistant à la chaleur pour renforcer les armures.",h="Sur la côte des Paluns, on récolte le Corail torride sur des Iron Coral vivants, sous la mer.",kw={"furen barbe-longue","iron coral","forgefer","klockmort spannerspan","port de menethil","corail torride","armure de guerrier","les paluns"},ang={["class:Warrior"]="En tant que guerrier, récolter du Corail torride prouve votre dévouement aux maîtres armuriers de Forgefer. Ils vous forgent un plastron sur mesure pour les combats en première ligne.",["profession:Blacksmithing"]="En tant que forgeron, vous pouvez voir comment l’ingéniosité gnome s’allie au travail traditionnel des métaux nain pour transformer des minéraux marins en plaques trempées."},sec={{t="Une ressource côtière rare",b="Le Corail torride pousse dans les eaux froides au sud du Port de Menethil. Les Iron Coral vivants prospèrent dans l’eau salée et produisent une matière riche en minéraux qui résiste à une chaleur extrême. Les récolteurs doivent détacher ces formations durcies tandis que des murlocs sauvages et d’autres bêtes aquatiques rôdent à proximité."},{t="Utilisation en forge",b="Les forgerons nains ne travaillent pas traditionnellement le Corail torride. À Forgefer, des artisans gnomes curieux comme Klockmort Spannerspan suivent les méthodes de Furen Barbe-longue, un armurier vétéran. Ils fondent le corail et le martèlent pour l’incorporer à des alliages métalliques, créant ainsi une armure légère et résistante pour les guerriers en herbe."}},faq={{q="Où pousse le Corail torride ?",a="Le Corail torride pousse dans des bancs d’Iron Coral, sous les eaux côtières peu profondes au sud du Port de Menethil, dans les Paluns.",al={"emplacement du corail torride","où trouver le corail torride","emplacement de l’iron coral"}},{q="Qui veut du Corail torride à Forgefer ?",a="Klockmort Spannerspan, un artificier gnome du quartier de Tinkertown à Forgefer, recherche du Corail torride. Il expérimente des méthodes de forge apprises auprès du célèbre armurier nain Furen Barbe-longue.",al={"qui utilise le corail torride","klockmort spannerspan et le corail","furen barbe-longue et le corail"}},{q="Comment forger le corail pour en faire une armure ?",a="Le Corail torride possède une structure particulièrement dense et résistante à la chaleur. Fondu dans une forge puis martelé pour l’incorporer à des alliages métalliques, il renforce le blindage composite et permet de créer un équipement de protection exceptionnellement robuste.",al={"forge du corail","peut-on fondre le corail","métallurgie du corail torride"}},{q="La récolte du Corail torride est-elle dangereuse ?",a="Le corail lui-même peut être récolté sans danger une fois trouvé. Pour l’atteindre, il faut nager en pleine mer au large des côtes des Paluns, où rôdent des murlocs sauvages et des bêtes aquatiques agressives.",al={"le corail torride est-il chaud","récolte de l’iron coral"}}},fx={["3e3d13aa"]={q="Qu'est-ce que le Corail torride ?",a="Le Corail torride est une excroissance marine rare et riche en minéraux, récoltée sur des formations de corail de fer sous les vagues le long de la côte des Paluns, au sud du Port de Menethil. Bien qu'il s'agisse d'un spécimen océanique, ses propriétés denses et particulières permettent aux forgerons qualifiés de le fondre, de le marteler et de le travailler comme du métal.",al={"qu'est-ce que le corail torride","infos sur le corail torride","lore du corail torride"}},["1c0d8f00"]={q="D'où vient le Corail torride ?",a="Le Corail torride est une croissance aquatique naturelle et non un artefact manufacturé. Il ne pousse qu'à un seul endroit connu au monde : au milieu des lits de corail de fer submergés le long des eaux côtières au sud du Port de Menethil dans les Paluns.",al={"origine du corail torride","d'où vient le corail torride","qui a fabriqué le corail torride"}}},fp="13,170,23.267.0,23.290.0,30.115.0,37.187.0,35.198.0,38.167.0"}
P.entries["item:secure-crate"] = {n="Caisse sûre",s="Dans les Tarides, une Caisse sûre est en route pour Cabestan. Des potions et des produits alchimiques qu’elle contient traverseront la mer jusqu’aux Royaumes de l'est.",h="Dans les Tarides, une Caisse sûre est en route pour Cabestan.",kw={"tarides","crique des flots noirs","potions","cabestan","réactifs","caisse sûre","expédition","wharfmaster dizzywig"},ang={["faction:Horde"]="En tant que voyageur de la Horde, vous savez que le port neutre de Cabestan relie Kalimdor et les Royaumes de l'est grâce aux navires gobelins.",["profession:Herbalism"]="En tant qu’herboriste, vous savez que les alchimistes et herboristes d’outre-mer comptent sur les routes commerciales des confins pour échanger des ingrédients bruts."},sec={{t="La cargaison d’un coursier",b="Coursiers, caravanes et navires gobelins assurent le commerce entre Kalimdor et les Royaumes de l'est. Quand une caravane des Tarides manque son départ, des voyageurs acheminent jusqu’à la côte les cargaisons fragiles comme cette Caisse sûre. À l’intérieur se trouvent des potions, des produits alchimiques et des réactifs destinés à des associés de l’autre côté de La Grande mer. Son sceau protège la caisse sur les pistes des Tarides et pendant la traversée."},{t="Par le port de Cabestan",b="Le trajet terrestre de la caisse s’achève aux quais de Cabestan, où Wharfmaster Dizzywig supervise les expéditions. Cabestan est un port neutre pour les marchandises qui traversent la mer, notamment celles destinées à la Crique des Flots noirs. Dizzywig travaille avec le registre du Cartel Gentepression et consigne colis et fret avant de les charger sur le prochain navire. Cabestan relie l’Ancien Monde à la frontière."}},faq={{q="Que contient la Caisse sûre ?",a="La Caisse sûre contient des potions, des réactifs alchimiques et d’autres fournitures destinés à des associés des Royaumes de l'est.",al={"contenu de la caisse","que contient la caisse","objets de la caisse sûre"}},{q="Où la caisse est-elle envoyée ?",a="Portez la Caisse sûre à Wharfmaster Dizzywig, sur les quais de Cabestan. Il l’inscrira au registre d’un navire marchand à destination de la Crique des Flots noirs, dans l’Ancien Monde.",al={"destination de la caisse","où va la caisse sûre"}},{q="Pourquoi confier la caisse à un aventurier plutôt qu’à une caravane ?",a="L’expéditeur ne pouvait pas atteindre Cabestan à temps, et la caravane commerciale prévue était déjà partie. Un coursier engagé doit porter la caisse aux quais avant la marée.",al={"pourquoi ai-je la caisse","caravane manquée"}},{q="Qui réceptionne la caisse à Cabestan ?",a="Wharfmaster Dizzywig réceptionne la caisse sur les quais de Cabestan. Il la consigne dans son registre d’expédition avant de la charger sur le prochain navire qui part avec la marée.",al={"qui reçoit la caisse","caisse de dizzywig"}}},fx={e5dd21c1={q="Qu'est-ce que la Caisse sûre ?",a="La Caisse sûre est un chargement étroitement emballé contenant un assortiment de potions, de réactifs et d'autres fournitures précieuses. Elle est emballée en toute sécurité afin que son contenu délicat survive à un long voyage par caravane et par navire à travers la mer jusqu'aux Royaumes de l'est.",al={"qu'est-ce que la caisse sûre","lore de la caisse sûre","à propos de la caisse sûre"}},["4df2d75b"]={q="D'où vient la Caisse sûre et qui l'a fabriquée ?",a="La caisse provient des Tarides, emballée et scellée par un apothicaire ou un érudit qui avait un besoin urgent d'exporter ses fournitures alchimiques. N'ayant pas eu le temps de se rendre à la côte personnellement après avoir manqué la caravane commerciale régulière, il a préparé la caisse pour qu'elle soit transportée à la main directement jusqu'au port de Cabestan.",al={"qui a fabriqué la caisse sûre","d'où vient la caisse sûre","origine de la caisse sûre"}},b7ad6ca4={q="Pourquoi la Caisse sûre est-elle recherchée ?",a="Des associés dans les Royaumes de l'est, de l'autre côté de la mer, attendent ces réactifs et potions essentiels. Wharfmaster Dizzywig à Cabestan a besoin que la caisse soit livrée à ses quais afin qu'il puisse l'enregistrer dans son registre commercial et la ranger à bord du prochain navire en partance pour la Crique des Flots noirs.",al={"pourquoi vouloir la caisse sûre","qui a besoin de la caisse sûre","pourquoi dizzywig veut-il la caisse sûre"}}},fp="12,139,17.376.0,27.382.0,32.111.0,30.151.0,62.163.0,31.158.0"}
P.entries["item:senir-s-report"] = {n="Rapport de Senir",s="Dans les contreforts de Dun Morogh, Senir Blanchebarbe transmet au Sénateur Barin Redstone, à Forgefer, ses découvertes sur les trolls Crindegivre.",h="Dans les contreforts de Dun Morogh, Senir Blanchebarbe transmet au Sénateur Barin Redstone, à Forgefer, ses...",kw={"barin redstone","crindegivre","forgefer","magni barbe-de-bronze","sénat","senir blanchebarbe","rapport de senir","the reports"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, transporter le Rapport de Senir contribue à défendre Dun Morogh, tandis que vous évoluez dans les intrigues des dirigeants de Forgefer.",["race:Dwarf"]="En tant que nain, transporter le Rapport de Senir vous plonge dans le conflit entre les décrets du Roi Magni Barbe-de-Bronze et l’autorité que réclame le Sénat de Forgefer."},sec={{t="Une directive royale",b="Le rapport de Senir rassemble les observations des montagnards qui ont repéré les trolls Crindegivre dans les escarpements de Dun Morogh. Il contient aussi le récit de son frère Grelin sur la Vallée des Frigères. Grelin y a agi avec l’accord du Roi Magni Barbe-de-Bronze.\n\nSenir transmet les conclusions au Sénateur Barin Redstone, au Haut Siège de Forgefer. Il conseille aux coursiers de taire l’ampleur de l’aide extérieure dont il a eu besoin pour les compiler."},{t="Tensions au Haut Siège",b="Le rapport de Senir Blanchebarbe parvient à la cour royale et provoque un tollé. Le Sénateur Barin Redstone est irrité par la menace des trolls et par l’autorité affichée dans le rapport. Magni a contourné le contrôle législatif, tandis que Blanchebarbe a agi sur des ordres royaux sans contrôle.\n\nCette décision accroît le ressentiment des sénateurs qui réclament le contrôle des procédures. La tension s’accentue entre le pouvoir décisionnel de Magni et les revendications d’autorité du Sénat."}},faq={{q="Qu’est-ce que le Rapport de Senir ?",a="Le rapport de Senir Blanchebarbe consigne ses recherches sur les trolls Crindegivre de Dun Morogh. Il l’envoie au Sénat nain de Forgefer.",al={"rapport de senir","qu’est-ce que ce rapport","le rapport"}},{q="À qui le rapport est-il destiné ?",a="Senir Blanchebarbe adresse le rapport au Sénateur Barin Redstone, au Haut Siège de Forgefer, près du trône du Roi Magni Barbe-de-Bronze.",al={"qui reçoit le rapport","à qui remettre le rapport","destinataire du rapport"}},{q="Pourquoi le Sénateur Redstone se met-il tellement en colère en le lisant ?",a="Le Sénateur Redstone est furieux, car le rapport joint de Grelin Blanchebarbe indique que Grelin a agi sous l’autorité du Roi Magni sans consulter le Sénat. Redstone s’indigne que la couronne prenne seule des mesures de défense sans l’approbation du Sénat.",al={"pourquoi barin est en colère","pourquoi le sénateur est en colère","réaction de redstone"}},{q="Pourquoi Senir vous demande-t-il de ne pas parler de votre aide ?",a="Senir Blanchebarbe vous demande de garder votre aide secrète pour que ses supérieurs croient qu’il a effectué seul les reconnaissances périlleuses dans les collines enneigées. Il veut protéger sa réputation de montagnard diligent et compétent.",al={"pourquoi garder le silence","secret de senir","mérite de senir"}}},fx={["078e838e"]={q="D'où vient le Rapport de Senir et qui l'a rédigé ?",a="Senir Blanchebarbe a rédigé ce rapport lui-même en Dun Morogh après avoir repéré les menaces locales des trolls Crins-de-givre et obtenu de l'aide pour gérer le Repaire des Crins-de-givre. En plus de ses propres conclusions, il contient le rapport de son frère Grelin sur la Vallée des Frigères, que Grelin a écrit sous l'autorisation du Roi Magni Bronzebeard, et il transporte les deux documents depuis les frontières enneigées jusqu'aux grandes salles de la capitale.",al={"qui a écrit le rapport de senir","d'où vient le rapport de senir","auteur du rapport de senir"}},e0c0da53={q="Pourquoi a-t-on besoin du Rapport de Senir ?",a="Le Sénateur Barin Redstone et le Sénat de Forgefer ont besoin d'évaluations officielles sur le terrain pour suivre les développements régionaux et les actions militaires en Dun Morogh. Cependant, comme ce rapport spécifique affirme l'autorité unilatérale du roi Magni sur les manœuvres locales, il revêt un poids politique important, informant le Sénat des actions de la couronne qu'ils estiment contourner leur surveillance.",al={"pourquoi livrer le rapport de senir","pourquoi redstone a-t-il besoin du rapport de senir","objectif du rapport de senir"}}},fp="14,133,17.399.0,25.430.1,23.143.0,38.131.0,56.253.1,50.210.0"}
P.entries["item:serena-s-head"] = {n="Tête de Serena",s="Dans les Collines arides, Darsok Vivedague cherche la tête de Serena Bloodfeather pour prouver sa mort. Il compte l’exposer sur un chariot de ravitaillement de la Horde afin de prévenir de nouveaux raids de harpies.",h="Dans les Collines arides, Darsok Vivedague cherche la tête de Serena Bloodfeather pour prouver sa mort.",kw={"la croisée","darsok vivedague","les collines arides","harpie","rexxar","serena bloodfeather","tête de serena","witchwing"},ang={["class:Rogue"]="Darsok Vivedague apprécie le travail propre et impitoyable. Il félicite les mercenaires qui se glissent derrière les perchoirs ennemis et exécutent leur cible sans hésiter.",["faction:Horde"]="Les caravanes de la Horde relient Durotar à Mulgore et aux avant-postes lointains. Exposer la tête de Serena sur un chariot de ravitaillement affirme la domination de la Horde sur les terres sauvages."},sec={{t="Un avertissement sur la route",b="Serena Bloodfeather menait les harpies Witchwing des Collines arides lors de leurs attaques contre le commerce dans le nord des Tarides. Ses assauts contre les lignes de ravitaillement de la Horde se sont faits plus violents après que le maître des bêtes Rexxar eut tué sa sœur.\n\nDarsok Vivedague, un voleur orc, a ordonné la traque de Serena pour briser le moral de la nuée. Il compte fixer sa tête tranchée sur une caravane en partance, afin que les harpies qui observent depuis les escarpements voient l’avertissement."}},faq={{q="Pourquoi Darsok Vivedague veut-il la tête de Serena ?",a="Darsok veut prouver que Serena Bloodfeather est morte. Il compte fixer sa tête sur une caravane de ravitaillement de la Horde et espère que cette exposition éloignera des voyageurs les harpies Witchwing qui ont survécu.",al={"pourquoi prendre la tête de serena","darsok tête serena","que fait darsok de la tête"}},{q="Pourquoi Serena Bloodfeather attaquait-elle les caravanes de la Horde ?",a="Serena Bloodfeather attaquait les caravanes de la Horde pour venger sa sœur, tuée par le champion demi-ogre Rexxar. Elle s’en prenait aux lignes de ravitaillement de la Horde et aux voyageurs dans les Tarides.",al={"pourquoi serena attaquait les caravanes","motif de serena bloodfeather","attaques de harpies dans les tarides"}},{q="D’où vient ce trophée ?",a="Ce trophée vient de Serena Bloodfeather, la matriarche qui niche parmi les escarpements des Collines arides, dans l’extrême nord-ouest des Tarides.",al={"où trouver la tête de serena","emplacement de serena bloodfeather","comment obtenir la tête de serena"}}},fx={["29e11954"]={q="Qu'est-ce que la Tête de Serena ?",a="La Tête de Serena est la tête tranchée de Serena Bloodfeather, la matriarche vengeresse de la volée de harpies Aile-de-sorcière dans le nord des Tarides. La récupérer marque la fin de ses raids contre les routes d'approvisionnement de La Croisée et sert de preuve irréfutable que la menace des harpies a été frappée en plein cœur.",al={"qu'est-ce que la tête de serena","tête de serena bloodfeather","objet tête de serena"}}},fp="13,176,21.411.1,47.194.0,53.175.1,33.126.0"}
P.entries["item:serpentbloom"] = {n="Fleur de serpent",s="Au fond des Cavernes des lamentations, la Fleur de serpent suscite l’intérêt de la Société royale des apothicaires.",h="Au fond des Cavernes des lamentations, la Fleur de serpent suscite l’intérêt de la Société royale des...",kw={"apothecary zamah","tarides","herbe","société royale des apothicaires","fleur de serpent","pitons-du-tonnerre","cavernes des lamentations"},ang={["profession:Herbalism"]="Votre œil exercé d’herboriste repère les fleurs rares des cavernes là où d’autres ne voient que de la pierre humide.",["race:Undead"]="En tant que mort-vivant, récolter de la Fleur de serpent aide l’Apothicaire Zamah et la Société royale des apothicaires à trouver des ressources botaniques en terres étrangères pour renforcer les Réprouvés."},sec={{t="Une flore souterraine rare",b="Dans les Tarides, la Fleur de serpent prospère dans les tunnels humides et sombres des Cavernes des lamentations. Les énergies débridées du Rêve d’émeraude ont déformé l’écosystème des cavernes. Des serpents venimeux nichent souvent parmi les tiges de la plante.\n\nDes bêtes hostiles et des druides corrompus infestent les grottes. Rares sont ceux qui s’y aventurent et en reviennent avec des spécimens viables."},{t="L’intérêt des apothicaires",b="Aux Bassins de la Vision, sous Pitons-du-Tonnerre, l’Apothicaire Zamah récolte de la Fleur de serpent pour la Société royale des apothicaires de Fossoyeuse. Les Réprouvés recherchent à travers Kalimdor des plantes virulentes, étranges et chimiquement puissantes afin d’alimenter leurs recherches pour la Dame noire.\n\nZamah pense qu’une récolte importante de Fleur de serpent pourrait apporter de précieuses avancées à l’alchimie réprouvée."}},faq={{q="Où pousse la Fleur de serpent ?",a="La Fleur de serpent ne pousse qu’au fond des Cavernes des lamentations, un réseau labyrinthique au sud-ouest de la Croisée, dans les Tarides. Elle s’accroche au sol dans les recoins sombres et humides des cavernes.",al={"où trouver la fleur de serpent","emplacement de la fleur de serpent","herbe des cavernes des lamentations"}},{q="Pourquoi la Société royale des apothicaires veut-elle de la Fleur de serpent ?",a="L’Apothicaire Zamah, agent de la Société royale des apothicaires en poste à Pitons-du-Tonnerre, recherche la Fleur de serpent pour ses travaux. Les Réprouvés étudient la flore inhabituelle et dangereuse de Kalimdor afin de créer de nouveaux composés chimiques et de faire progresser les objectifs plus larges de la Société au service de Sylvanas Coursevent.",al={"qui veut la fleur de serpent","apothicaire zamah herbe","pourquoi récolter la fleur de serpent"}},{q="Pourquoi la récolte de la Fleur de serpent est-elle dangereuse ?",a="Les Cavernes des lamentations grouillent de raptors, de crocilisques et de druides corrompus. La Fleur de serpent abrite souvent des serpents venimeux, qui peuvent frapper quand on dérange la plante.",al={"danger de la fleur de serpent","serpent fleur de serpent"}},{q="Les herboristes peuvent-ils trouver plus facilement la Fleur de serpent ?",a="Oui. Les herboristes ont naturellement l’œil pour repérer la végétation et peuvent déceler les pousses de Fleur de serpent dans les recoins sombres des cavernes.",al={"trouver la fleur de serpent avec l’herboristerie","repérer la fleur de serpent"}}},fx={bee22cd2={q="Qu'est-ce que la Fleur de serpent ?",a="La Fleur de serpent est un spécimen de flore extrêmement rare originaire des recoins les plus sombres des Cavernes des lamentations dans les Tarides. Enracinée dans les profondeurs humides et souterraines, cette herbe inhabituelle se distingue par ses qualités rappelant celles d'un serpent : la déranger attire souvent les serpents agressifs nichés autour de ses racines.",al={"qu'est-ce que la fleur de serpent","herbe fleur de serpent","infos sur la fleur de serpent"}}},fp="12,133,25.327.0,19.368.0,29.186.0,56.295.0,41.163.0,45.131.0"}
P.entries["item:sethir-s-journal"] = {n="Journal de Sethir",s="À Teldrassil, le Journal de Sethir a été dérobé avec discrétion. Ses pages révèlent que la corruption venue de Kalimdor a atteint l’Arbre-monde.",h="À Teldrassil, le Journal de Sethir a été dérobé avec discrétion.",kw={"sombrivage","destiny calls","la clairière de l'oracle","satyre","sethir the ancient","journal de sethir","syurna","teldrassil"},ang={["class:Rogue"]="En tant que voleur, vous pouvez recourir à la discrétion et au vol à la tire pour trouver des renseignements essentiels là où guerriers et diplomates ont échoué.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous êtes confronté à la preuve que Teldrassil n’est pas à l’abri de l’ancienne souillure démoniaque qui se répand sur le continent de Kalimdor."},sec={{t="Un indice sur la souillure",b="Le Journal de Sethir a été dérobé à Sethir the Ancient, un satyre solitaire près de la Clairière de l’Oracle. Teldrassil a été élevé dans l’espoir de rendre aux elfes leur immortalité, mais la maladie a pris racine parmi ses branches.\n\nÀ Darnassus, Syurna soupçonnait Sethir de détenir des réponses. Les éclaireurs qui ont tenté de négocier avec lui ou de l’attaquer ont trouvé la mort, alors le journal a été subtilisé dans ses paquetages. Ses écrits montrent que le fléau qui empoisonne les bois et les eaux de Sombrivage, par-delà la mer, a atteint Teldrassil."}},faq={{q="Qu’est-ce que le Journal de Sethir ?",a="Sethir the Ancient, un satyre hostile, porte le Journal de Sethir sur les branches extérieures, près de la Clairière de l’Oracle. Ses notes décrivent la propagation de la corruption dans la région.",al={"qu’est-ce que le journal de sethir","histoire du journal de sethir","à qui appartient le journal de sethir"}},{q="Comment obtenir le journal ?",a="Les éclaireurs qui ont tenté de négocier avec Sethir ou de le combattre ont échoué et trouvé la mort. Il faut subtiliser le journal dans ses paquetages grâce à la discrétion.",al={"comment obtenir le journal de sethir","où trouver le journal de sethir","vol à la tire sur sethir"}},{q="Que révèle le journal ?",a="Syurna, maîtresse des voleurs, affirme que le journal prouve que l’étrange maladie qui ravage les forêts et les eaux de Sombrivage a atteint Teldrassil.",al={"que dit le journal de sethir","que contient le journal de sethir"}},{q="Qui est Sethir the Ancient ?",a="Sethir the Ancient est un satyre solitaire sur une branche isolée, près des abords de la Clairière de l’Oracle. Il traite violemment les intrus et détient des informations sur la corruption qui se répand dans l’Arbre-monde.",al={"qui est sethir","sethir the ancient"}}},fx={["3d18c972"]={q="D'où vient le Journal de Sethir et qui l'a écrit ?",a="Le journal appartient à Sethir l'Ancien, un satyre hostile tapi sur une haute branche en bordure de la Clairière de l'Oracle à Teldrassil. Contenant ses écrits et documents personnels parmi ses affaires, il a gardé le journal jusqu'à ce que des voleurs de Darnassus cherchent à le dérober discrètement pour découvrir quelle corruption se propage à travers l'arbre-monde.",al={"qui a écrit le journal de sethir","origine du journal de sethir","origine journal de sethir"}}},fp="16,144,19.475.1,25.171.0,28.130.0,29.130.0,26.207.0"}
P.entries["item:sevren-s-orders"] = {n="Ordres de Sevren",s="À Brill, le Magistrat Sevren envoie au sud, vers Fossoyeuse, un agent réprouvé qui a fait ses preuves. Les ordres le dirigent vers Bethor Glacéclat, dans le Quartier de la Magie.",h="À Brill, le Magistrat Sevren envoie au sud, vers Fossoyeuse, un agent réprouvé qui a fait ses preuves.",kw={"bethor glacéclat","brill","quartier de la magie","magistrat sevren","prodigal lich","ordres de sevren","fossoyeuse"},ang={["class:Mage"]="En tant que mage, remettre les ordres vous mène auprès de Bethor Glacéclat, l’un des plus éminents lanceurs de sorts du royaume réprouvé.",["race:Undead"]="En tant que Mort-vivant, porter le sceau de Sevren vous fait passer du service local dans les Clairières de Tirisfal au service de l’élite des arcanes de Fossoyeuse."},sec={{t="Convocation dans la capitale",b="Les agents réprouvés qui font leurs preuves contre le Fléau dans les Clairières de Tirisfal sont convoqués au sud, tandis que leur peuple renforce son emprise sur Lordaeron. Le Magistrat Sevren rédige ces ordres pour présenter l’agent à Bethor Glacéclat et lui remettre ses lettres de créance. Bethor est l’un des plus éminents praticiens des arcanes de la Dame noire au Quartier de la Magie. Sevren sait seulement que la mission consiste à prendre contact avec une liche errante. Les hauts mages de Fossoyeuse confèrent à cette convocation toute leur autorité."}},faq={{q="Qui a rédigé ces ordres ?",a="Le Magistrat Sevren, qui supervise les affaires des Réprouvés à Brill, a rédigé ces ordres.",al={"auteur des ordres de sevren","qui est sevren","qui donne les ordres de sevren"}},{q="À qui ces ordres sont-ils destinés ?",a="Ces ordres sont adressés à Bethor Glacéclat, un mage réprouvé de haut rang dans le Quartier de la Magie de Fossoyeuse.",al={"qui reçoit les ordres","où apporter les ordres de sevren","qui est bethor glacéclat"}},{q="Quelle mission les ordres mentionnent-ils ?",a="Les ordres demandent de recruter une liche égarée pour aider les Réprouvés. Cette tâche périlleuse revient à un agent qui a déjà fait ses preuves contre le Fléau.",al={"quelle est la mission de la liche","que veut bethor","mission de prodigal lich"}},{q="Pourquoi m’a-t-on choisi pour les remettre ?",a="Bethor a demandé un agent qui a fait ses preuves contre le Fléau. Le Magistrat Sevren a jugé que vos efforts dans les Clairières de Tirisfal répondaient à la dangereuse demande de Bethor.",al={"pourquoi moi","pourquoi sevren m’a choisi"}}},fx={["59d8f724"]={q="Qu'est-ce que les Ordres de Sevren ?",a="Les Ordres de Sevren sont un document officiel écrit par le Magistrat Sevren de Brill. Il sert de références formelles, vous identifiant comme un agent ayant fait ses preuves, qui a combattu efficacement contre le Fléau et qui est prêt à entreprendre une mission délicate.",al={"que sont les ordres de sevren","objet ordres de sevren","qu'est-ce que ce document"}},["680dc8a1"]={q="Pourquoi Bethor Glacéclat veut-il les Ordres de Sevren ?",a="Bethor Glacéclat, un mage éminent du Quartier de la Magie de Fossoyeuse, a exigé que Sevren lui fournisse un agent capable de gérer une tâche périlleuse impliquant une liche renégate. Présenter ces ordres prouve que vous êtes l'opérateur choisi par Sevren et que votre interruption auprès du puissant sorcier est justifiée.",al={"pourquoi livrer les ordres de sevren","pourquoi bethor veut-il les ordres","qui a besoin des ordres de sevren"}}},fp="15,150,22.460.0,23.76.0,40.107.0,44.139.0,33.157.0"}
P.entries["item:shackle-key-stranglethorn-vale"] = {n="Shackle Key",s="La Shackle Key est détenue par le roi Mukla sur l’Ile aux jagueros. La princesse Poobah en a besoin pour échapper à sa captivité.",h="La Shackle Key est détenue par le roi Mukla sur l’Ile aux jagueros.",kw={"captivité","ile aux jagueros","roi mukla","princesse poobah","entrave","shackle key","vallée de strangleronce"},sec={{t="Une princesse captive",b="La princesse Poobah est enchaînée sur l’Ile aux jagueros, où le roi Mukla la retient contre son gré. La clé de ses entraves est liée à sa liberté, et elle demande de l’aide à quiconque est prêt à affronter le grand roi Skymane."}},faq={{q="Qu’ouvre la Shackle Key ?",a="La Shackle Key ouvre les entraves qui retiennent captive la princesse Poobah sur l’Ile aux jagueros.",al={"à quoi sert la clé","qu’ouvre la clé"}},{q="Qui détient la Shackle Key ?",a="Le roi Mukla détient la Shackle Key sur l’Ile aux jagueros.",al={"qui détient la clé","clé de mukla"}},{q="Où la princesse Poobah est-elle retenue ?",a="La princesse Poobah est retenue sur l’Ile aux jagueros, dans la Vallée de Strangleronce.",al={"où est poobah","poobah captive"}},{q="Pourquoi la princesse Poobah a-t-elle besoin de la clé ?",a="La princesse Poobah a besoin de la Shackle Key pour se libérer de la chaîne qui la retient captive.",al={"pourquoi la clé est nécessaire","libérer poobah"}}},fp="11,104,18.208.0,31.82.0,24.47.0,30.62.0,38.89.0"}
P.entries["item:shackle-key-the-hinterlands"] = {n="Shackle Key",s="La Shackle Key est détenue par Hitah'ya the Keeper dans une grotte près de Jintha'alor. L'Ancien Torntusk en a besoin pour desserrer ses liens et rentrer chez lui.",h="La Shackle Key est détenue par Hitah'ya the Keeper dans une grotte près de Jintha'alor.",kw={"entraves","l'ancien torntusk","hinterlands","hitah'ya the keeper","jintha'alor","shackle key"},sec={{t="L'Ancien enchaîné",b="À Jintha'alor, dans les Hinterlands, L'Ancien Torntusk attend la clé de ses entraves. Hitah'ya the Keeper la détient dans une grotte voisine, bien gardée. Rapportez la clé à Torntusk pour qu'il soit libéré et puisse rentrer chez lui."}},faq={{q="Qui détient la Shackle Key ?",a="Hitah'ya the Keeper détient la Shackle Key dans une grotte près de Jintha'alor.",al={"qui détient la clé","détenteur de la clé","clé de hitah'ya"}},{q="À quoi sert la Shackle Key ?",a="La Shackle Key desserre les entraves de L'Ancien Torntusk pour qu'il puisse rentrer chez lui.",al={"fonction de la clé","but de la clé","clé de torntusk"}},{q="Où se trouve la clé ?",a="Hitah'ya the Keeper détient la clé dans une grotte près de Jintha'alor, dans les Hinterlands.",al={"emplacement de la clé","où est la clé","grotte voisine"}},{q="Qui a besoin de la clé ?",a="L'Ancien Torntusk, à Jintha'alor, a besoin de la clé pour se libérer de ses entraves.",al={"qui veut la clé","qui en a besoin","l'ancien torntusk"}}},fp="11,138,15.218.0,24.69.0,28.72.0,17.80.0,18.78.0"}
P.entries["item:shadow-hunter-knife"] = {n="Shadow Hunter Knife",s="Le Couteau du chasseur des ombres est une lame troll Witherbark recherchée par l’Apprenti Kryten au Refuge de l’Ornière.",h="Le Couteau du chasseur des ombres est une lame troll Witherbark recherchée par l’Apprenti Kryten au Refuge de...",kw={"archimage malin","kryten","refuge de l’ornière","rites de passage","couteau du chasseur des ombres","troll","witherbark"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, Kryten mène ses travaux au Refuge de l’Ornière au service des recherches de l’Archimage Malin en Arathi."},sec={{t="Une lame de Troll",b="L’Apprenti Kryten recherche le Couteau du chasseur des ombres au Refuge de l’Ornière pour les recherches de l’Archimage Malin. Il affirme que les plus puissants chasseurs des ombres Witherbark reçoivent cette lame spéciale après avoir accompli leurs rites de passage. Leur village se trouve au sud-est d’Arathi, et Kryten ne peut savoir quel chasseur en porte une avant la fin du combat."}},faq={{q="Qui recherche le Couteau du chasseur des ombres ?",a="L’Apprenti Kryten, au Refuge de l’Ornière, recherche le Couteau du chasseur des ombres pour les recherches de l’Archimage Malin.",al={"qui a besoin du couteau","couteau de kryten","qui le veut"}},{q="Qui porte le Couteau du chasseur des ombres ?",a="Les plus puissants chasseurs des ombres Witherbark peuvent porter le couteau spécial qu’ils reçoivent après leurs rites de passage.",al={"qui a le couteau","quel troll l’a","lame de chasseur des ombres"}},{q="Pourquoi ce couteau est-il spécial ?",a="Kryten affirme que les Witherbark donnent ce couteau à leurs plus puissants chasseurs des ombres après leurs rites de passage.",al={"pourquoi ce couteau est spécial","signification du couteau troll","qu’est-ce qui le rend spécial"}},{q="Où vivent les Witherbark ?",a="Les Witherbark vivent au sud-est d’Arathi, près de Fanécorce.",al={"où vivent les witherbark","emplacement du village troll","où sont les withbark"}}},fp="19,154,15.328.0,34.97.0,36.103.0,25.119.0,29.65.0"}
P.entries["item:shadowhide-pendant"] = {n="Pendentif sombrepoil",s="Dans les Carmines, les pendentifs sombrepoils marquent les gnolls au service de Morganth. Comté-du-Lac en réclame dix pour prouver que la loi y a été appliquée.",h="Dans les Carmines, les pendentifs sombrepoils marquent les gnolls au service de Morganth.",kw={"bailli conacher","gnoll","comté-du-lac","lieutenant fangore","morganth","pendentif","les carmines","sombrepoil","solomon's law"},ang={["class:Warrior"]="En tant que guerrier, vous affrontez des gnolls Sombrepoil agressifs et imposants. Leurs rangs mettent à l'épreuve ceux qui défendent les routes menant à Comté-du-Lac.",["faction:Alliance"]="En tant qu'aventurier loyal de l'Alliance, vous pourriez être appelé à faire respecter les lois du royaume. Les colonies frontalières comme Comté-du-Lac reçoivent peu d'aide de la garnison de Hurlevent, alors les magistrats locaux comptent sur vous."},sec={{t="Symboles de défi",b="Les guerriers, brutes et lanceurs de sorts Sombrepoil portent des pendentifs sombrepoils. Au cœur des collines des Carmines, le Lieutenant Fangore dirige le clan, désormais sous l'emprise de Morganth. Morganth est un utilisateur renégat des Arcanes. Pour les habitants de Comté-du-Lac, ces parures rudimentaires signalent une menace organisée qui harcèle les colonies pour le compte d'un ennemi de la Couronne."},{t="La justice de Comté-du-Lac",b="Le Magistrat Salomon fait appliquer la loi de Hurlevent, qui condamne à mort quiconque aide activement un criminel notoire du royaume. Les renforts royaux sont trop peu nombreux, alors le Bailli Conacher, à l'Hôtel de ville de Comté-du-Lac, compte sur les aventuriers pour maintenir la paix. Dix pendentifs sombrepoils prouvent que les gnolls obéissant aux ordres de Morganth ont subi la justice des frontières."}},faq={{q="Qu'est-ce qu'un pendentif sombrepoil ?",a="Les membres du clan gnoll Sombrepoil portent des pendentifs sombrepoils dans les Carmines. Le magistrat local les accepte comme preuve que des gnolls envahisseurs ont été tués pour défendre la ville.",al={"que sont les pendentifs sombrepoils","histoire des pendentifs sombrepoils","pendentif des carmines"}},{q="Pourquoi le Bailli Conacher veut-il ces pendentifs ?",a="Le Bailli Conacher rassemble les pendentifs pour prouver que Solomon's Law a été appliquée. Le clan Sombrepoil travaille avec le mage renégat Grand magus Doane pour terroriser la population locale. La ville considère donc chaque gnoll affilié comme un ennemi passible de la peine capitale.",al={"pourquoi récupérer des pendentifs","prime du bailli conacher","quête de conacher"}},{q="Qui porte ces pendentifs ?",a="Les voleurs, les brutes et les gnolls enragés portent ces pendentifs. Rohh the Silent et le Lieutenant Fangore en portent aussi dans les étendues sauvages des Carmines.",al={"qui donne les pendentifs","quels gnolls portent des pendentifs","source des pendentifs sombrepoils"}},{q="Quel lien unit le clan Sombrepoil et Morganth ?",a="Morganth est un utilisateur renégat des Arcanes dans les contreforts orientaux. Il soumet les gnolls Sombrepoil à sa volonté par des pouvoirs sinistres, puis les envoie terroriser Comté-du-Lac et mettre ses plans à exécution.",al={"gnolls et morganth","pourquoi les gnolls travaillent avec morganth","sombrepoil et morganth"}}},fp="18,127,18.341.0,19.340.0,29.212.0,46.256.0,27.145.0,66.218.0"}
P.entries["item:shadowmaw-claw"] = {n="Shadowmaw Claw",s="Une Shadowmaw Claw provient d’une panthère de la Vallée de Strangleronce. Le Prophète Mok'thardin a besoin de ces griffes pour un enchantement au service de la Horde.",h="Une Shadowmaw Claw provient d’une panthère de la Vallée de Strangleronce.",kw={"elder shadowmaw panther","campement grom'gol","mok'thardin","enchantement de mok'thardin","pristine tigress fang","shadowmaw claw","shadowmaw panther","vallée de strangleronce"},ang={["faction:Horde"]="Mok'thardin recherche ces griffes pour exploiter la magie de la jungle et créer un enchantement spécial au service de la Horde."},sec={{t="Griffes de panthère",b="De l’autre côté de la rivière, près des Ruines de Mizjah, les Shadowmaw Panthers et leurs aînées chassent dans la jungle. Le Prophète Mok'thardin, au Campement Grom'gol, recherche leurs griffes ainsi qu’un Pristine Tigress Fang pour son enchantement. Il pense pouvoir exploiter la magie de la jungle au profit de la Horde."}},faq={{q="D’où viennent les Shadowmaw Claws ?",a="Les Shadowmaw Panthers et les Elder Shadowmaw Panthers de la Vallée de Strangleronce portent ces griffes.",al={"origine des shadowmaw claws","griffe de panthère","où trouver les griffes"}},{q="Qui recherche les Shadowmaw Claws ?",a="Le Prophète Mok'thardin, au Campement Grom'gol, recherche huit Shadowmaw Claws et un Pristine Tigress Fang.",al={"qui recherche les griffes","griffes mokthardin","griffes pour qui"}},{q="Pourquoi Mok'thardin a-t-il besoin de ces griffes ?",a="Mok'thardin a besoin de Shadowmaw Claws et d’un Pristine Tigress Fang pour un enchantement qu’il compte créer au profit de la Horde.",al={"pourquoi ces griffes","enchantement mokthardin","à quoi ça sert"}},{q="Où se trouvent les panthères ?",a="Mok'thardin dit que les Shadowmaw Panthers rôdent au sud-est, de l’autre côté de la rivière, près des Ruines de Mizjah.",al={"emplacement des shadowmaw","panthères près de gromgol","où sont les panthères"}}},fp="14,137,13.273.0,35.87.0,26.99.0,36.112.0,23.94.0"}
P.entries["item:shadowstalker-scalp"] = {n="Shadowstalker Scalp"}
P.entries["item:shadra-s-venom"] = {n="Shadra's Venom",s="Shadra's Venom est prélevé sur la déesse-araignée des Hinterlands. L'Apothicaire Lydon, au Moulin-de-Tarren, en a besoin après l'invocation de Shadra.",h="Shadra's Venom est prélevé sur la déesse-araignée des Hinterlands.",kw={"apothicaire lydon","parchemin de gadrin","hinterlands","shadra","shadra'alor","shadra's venom","dieu-araignée","moulin-de-tarren"},sec={{t="Du venin pour Lydon",b="À Shadra'Alor, dans les Hinterlands, le parchemin invoque Shadra depuis son antre. Son venin est apporté à l'Apothicaire Lydon, au Moulin-de-Tarren, qui l'attend."}},faq={{q="Qu'est-ce que Shadra's Venom ?",a="Shadra's Venom est prélevé sur Shadra, la déesse-araignée des Hinterlands.",al={"venin de shadra","quel venin"}},{q="Qui a besoin de Shadra's Venom ?",a="L'Apothicaire Lydon, au Moulin-de-Tarren, vous demande de lui apporter Shadra's Venom.",al={"qui veut le venin","venin de lydon"}},{q="Où trouver Shadra's Venom ?",a="Shadra's Venom provient de Shadra, à l'autel de Shadra'Alor, dans les Hinterlands.",al={"où trouver le venin","obtenir shadra's venom"}},{q="Comment invoquer Shadra ?",a="Lisez Gadrin's Parchment à l'autel de Shadra'Alor, au cœur du Witherbark realm, dans les Hinterlands.",al={"invoquer shadra","autel de shadra"}}},fp="14,130,15.151.0,23.71.0,25.72.0,32.80.0,23.105.0"}
P.entries["item:shaman-voodoo-charm"] = {n="Charme vaudou des chamans",s="Dans le Refuge des saisons de Ban'ethil, les chamans Gnarlpine manient le Charme vaudou des chamans. Sa magie peut séparer l'esprit d'un druide endormi de son corps.",h="Dans le Refuge des saisons de Ban'ethil, les chamans Gnarlpine manient le Charme vaudou des chamans.",kw={"refuge des saisons de ban'ethil","rêve d'émeraude","furbolg","gnarlpine","oben grifferage","charme vaudou des chamans","druide endormi","teldrassil"},ang={["class:Druid"]="En tant que druide, vous voyez dans ce charme une perversion terrifiante du sommeil sacré. Sa magie noire piège le rêveur dans le Rêve d'émeraude et transforme son corps en marionnette.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous savez que les charmes du Refuge des saisons de Ban'ethil révèlent à quel point les Gnarlpine ont profané l'un des lieux de repos communautaires les plus sacrés des kaldorei."},sec={{t="Une magie pervertie",b="Sur Teldrassil, la tribu Gnarlpine a sombré dans la folie et la corruption. Dans le Refuge des saisons de Ban'ethil, ses chamans manient une magie qui dépasse la sorcellerie sauvage ordinaire. Leurs charmes arrachent la conscience d'un druide endormi au royaume des mortels et la piègent dans le Rêve d'émeraude. Les furbolgs animent ensuite le corps vide. Les protecteurs elfes de la nuit deviennent des gardiens écervelés qui tuent quiconque entre dans les terriers."},{t="Défaire la malédiction",b="Oben Grifferage fut victime du rituel. Son esprit reste piégé dans le Rêve d'émeraude tandis que son corps animé terrorise les profondeurs des terriers. Oben a tendu la main à travers le voile pour demander aux aventuriers d'abattre les chamans Gnarlpine et de rapporter l'un de leurs charmes. Il espérait étudier son enchantement infâme, comprendre les pratiques corrompues des furbolgs et trouver un moyen de libérer sa chair dérobée."}},faq={{q="À quoi sert le Charme vaudou des chamans ?",a="Les chamans Gnarlpine utilisent ce charme pour séparer l'esprit d'un druide endormi de son corps et le piéger dans le Rêve d'émeraude. Sa magie anime la chair vide pour attaquer les intrus.",al={"utilité du charme vaudou","effet du charme","usage du charme des chamans"}},{q="Qui porte ces charmes ?",a="Les chamans Gnarlpine portent ces charmes dans les profondeurs du Refuge des saisons de Ban'ethil, sur Teldrassil.",al={"qui lâche le charme","où trouver le charme vaudou des chamans","charme du chaman gnarlpine"}},{q="Pourquoi Oben Grifferage en a-t-il besoin ?",a="Oben Grifferage est piégé dans le Rêve d'émeraude tandis que son corps animé sème la terreur. Il doit étudier l'aura infâme et la magie du charme pour trouver un moyen de briser l'enchantement des furbolgs.",al={"pourquoi oben le veut","charme d'oben grifferage","objet le druide dormant"}},{q="Pourquoi les furbolgs pratiquent-ils la magie vaudou ?",a="La corruption a poussé les chamans Gnarlpine de Teldrassil à pratiquer la magie noire. Leurs charmes dégagent une aura infâme et contre nature, à l'opposé du respect traditionnel des furbolgs pour les esprits de la nature et les éléments.",al={"pourquoi les furbolgs pratiquent le vaudou","histoire du vaudou furbolg"}}},fx={["6bf5e1a6"]={q="Qu'est-ce que le Charme vaudou des chamans ?",a="Il s'agit d'un talisman en fourrure enchanté, manié par les chamans corrompus des Gnarlpine à l'intérieur du Refuge des saisons de Ban'ethil. Émanant une aura magique vile, le charme utilise des rituels sombres capables de séparer l'esprit d'un druide elfe de la nuit endormi de sa forme physique, laissant l'esprit sans défense pendant que les furbolgs animent et contrôlent le corps endormi.",al={"qu'est-ce que le charme vaudou des chamans","lore du charme vaudou","que sont ces charmes"}}},fp="19,134,17.393.0,20.378.1,41.170.0,25.89.0,32.180.0,34.204.0"}
P.entries["item:shard-of-water"] = {n="Eclat d'eau",s="Sur la côte des Tarides, Islen Oeil-des-rivières reçoit l’Eclat d’eau d’un chaman qui a affronté la corruption.",h="Sur la côte des Tarides, Islen Oeil-des-rivières reçoit l’Eclat d’eau d’un chaman qui a affronté la...",kw={"les tarides","call of water","islen oeil-des-rivières","eclat d'eau","forêt des pins-argentés","totem d'eau"},ang={["class:Shaman"]="En tant que chaman, obtenir l’éclat achève votre communion avec les esprits de l’eau et le long voyage nécessaire pour gagner votre Totem d’eau."},sec={{t="Gage de pureté élémentaire",b="Pour maîtriser l’eau, un chaman doit comprendre l’équilibre, la vie et la préservation. Lors du Call of Water, vous vous rendez auprès de sources corrompues, en traversant la mer jusqu’à la Forêt des Pins-Argentés flétrie. Là, vous purifiez les eaux souillées et recevez l’Eclat d’eau. Vous rapportez ensuite ce symbole cristallin à Islen Oeil-des-rivières, sur les rivages rocheux des Tarides. Il prouve votre valeur et fournit la dernière clé nécessaire pour forger un Totem d’eau."}},faq={{q="À quoi sert l’Eclat d’eau ?",a="Vous apportez l’éclat à Islen Oeil-des-rivières, sur la côte orientale des Tarides, comme preuve de votre épreuve. Présentez-le pour achever votre communion avec l’eau et obtenir un Totem d’eau.",al={"utilité de l’éclat d’eau","à quoi sert l’éclat d’eau","pourquoi ai-je l’éclat d’eau"}},{q="Qui a besoin de cet objet ?",a="Islen Oeil-des-rivières vous demande l’éclat pour confirmer que vous avez purifié l’eau souillée. C’est une chamane qui vit dans une hutte au sud de Cabestan, le long de la Côte des marchands.",al={"qui veut l’éclat d’eau","où remettre l’éclat d’eau","éclat d’islen oeil-des-rivières"}},{q="Pourquoi l’épreuve a-t-elle lieu si loin, dans la Forêt des Pins-Argentés ?",a="L’eau apporte guérison et préservation, tandis que la corruption arrête la vie. Les eaux souillées de la Forêt des Pins-Argentés éprouvent votre capacité à rétablir l’harmonie élémentaire au milieu d’un profond déclin.",al={"quête de l’eau en forêt des pins-argentés","pourquoi la forêt des pins-argentés","chaman en forêt des pins-argentés"}}},fx={aaf07767={q="Qu'est-ce que l'Eclat d'eau ?",a="L'Eclat d'eau est un fragment élémentaire sacré accordé aux chamans qui entreprennent les épreuves de l'eau. Il sert de preuve tangible que vous avez effectué le rituel pour purifier les eaux corrompues et comprendre la véritable nature de l'eau en tant que donneuse et protectrice de la vie.",al={"qu'est-ce que l'éclat d'eau","objet éclat d'eau","qu'est-ce que cet éclat"}},["47314211"]={q="D'où provient l'Eclat d'eau, et qui l'a créé ?",a="Vous recevez l'éclat à la fin de votre voyage spirituel dans la Forêt des Pins-Argentés, obtenu après avoir terminé votre rituel visant à purifier les eaux corrompues de la région. Il incarne le pouvoir élémentaire de l'eau pure éveillé par ce rite.",al={"où trouver l'éclat d'eau","qui donne l'éclat d'eau","origine de l'éclat d'eau"}}},fp="14,108,25.403.0,36.165.0,23.141.0,48.163.0"}
P.entries["item:sharpbeak-s-feather"] = {n="Sharpbeak's Feather",s="La plume de Sharpbeak porte la trace du jeune griffon recherché dans les Hinterlands. Le maître des griffons Talonaxe espère que la magie divinatoire de Thadius Sinissombre pourra lui permettre de le retrouver.",h="La plume de Sharpbeak porte la trace du jeune griffon recherché dans les Hinterlands.",kw={"nid-de-l’aigle","divination","griffon","sharpbeak","plume de sharpbeak","thadius sinissombre","wildhammer"},ang={["race:Dwarf"]="En tant que nain, la quête de Sharpbeak touche les Wildhammer : Thadius Sinissombre a quitté le Nid-de-l’Aigle, mais garde toujours un cœur Wildhammer."},sec={{t="Une plume de griffon",b="Le maître des griffons Talonaxe vous confie une plume prélevée dans le nid où dort Sharpbeak, à remettre à Thadius Sinissombre au Rempart-du-Néant. Le devin a quitté le Nid-de-l’Aigle il y a des années pour poursuivre un savoir plus sombre, bien qu’il reste Wildhammer dans son cœur. Talonaxe espère que la plume pourra l’aider à retrouver le jeune griffon."},{t="Un signe prometteur",b="Thadius reconnaît dans la plume celle d’un griffon remarquable. Selon lui, Sharpbeak est promis à un grand destin, s’il atteint l’âge adulte sans mal. La plume en main, il vous invite à écouter attentivement tandis qu’il commence à deviner où se trouve le griffon."}},faq={{q="À quoi sert la plume de Sharpbeak ?",a="Thadius Sinissombre se sert de la plume de Sharpbeak comme lien pour deviner où se trouve le jeune griffon.",al={"plume de sharpbeak","à quoi sert la plume","utilité de la plume"}},{q="D’où vient la plume ?",a="La plume a été prélevée dans le nid où dort le petit griffon Sharpbeak.",al={"origine de la plume de sharpbeak","d’où vient la plume","plume du nid de griffon"}},{q="Qui est Thadius Sinissombre ?",a="Thadius Sinissombre est un devin Wildhammer qui a quitté le Nid-de-l’Aigle il y a des années pour poursuivre des connaissances plus sombres. Il se trouve dans la tour des mages du Rempart-du-Néant, dans les Terres Foudroyées.",al={"passé de thadius","qui est thadius","sinissombre"}},{q="Que pense Thadius de Sharpbeak ?",a="Thadius dit que Sharpbeak est un griffon remarquable, promis à un grand destin s’il atteint l’âge adulte sans dommage.",al={"destin de sharpbeak","avis de thadius","petit griffon"}}},fp="19,172,19.311.0,17.259.0,32.98.0,32.77.0,25.170.0,37.104.0"}
P.entries["item:shaw-s-report"] = {n="Rapport de Shaw",s="Maître Mathias Shaw scelle ce dossier du SI:7 à l’intention de Gryan Roidemantel, à la Colline des Sentinelles. C’est la réponse de Hurlevent à la People's Militia, qui a demandé qui se cache derrière les bandits qui attaquent la Marche de l’Ouest.",h="Maître Mathias Shaw scelle ce dossier du SI:7 à l’intention de Gryan Roidemantel, à la Colline des...",kw={"defias","edwin vancleef","gryan roidemantel","mathias shaw","rapport de shaw","si:7","guilde des maçons","marche de l’ouest"},ang={["class:Rogue"]="Le Rapport de Shaw révèle l’étendue de l’influence de Maître Mathias Shaw. Il dirige le SI:7, le réseau d’espionnage de Hurlevent.",["faction:Alliance"]="Le rapport met au jour la corruption qui ronge Hurlevent. Une dette impayée envers les architectes du royaume a contribué à déclencher une insurrection qui menace les terres agricoles du royaume."},sec={{t="Renseignements sur les maçons",b="Edwin VanCleef a autrefois dirigé la Stonemasons Guild, dont les maçons ont reconstruit Hurlevent après sa destruction lors de la First War.\n\nLa couronne et la noblesse ont refusé de les rémunérer équitablement, et le ressentiment s’est enraciné. Les renseignements de Shaw relient ces artisans déplacés au soulèvement qui s’empare aujourd’hui des territoires périphériques du royaume."}},faq={{q="Qu’est-ce que le Rapport de Shaw ?",a="Le Rapport de Shaw est un dossier de renseignements scellé que Maître Mathias Shaw a préparé pour Gryan Roidemantel. Shaw dirige le SI:7, le service secret de Hurlevent, et le rapport contient les renseignements de la couronne sur la guilde des maçons et le passé d’Edwin VanCleef.",al={"rapport shaw","que dit shaw","contenu du rapport de shaw"}},{q="Que révèle le rapport sur Edwin VanCleef ?",a="Le rapport désigne Edwin VanCleef comme l’ancien chef de la guilde des maçons. Il a supervisé la reconstruction de Hurlevent après la Première Guerre, puis lui et ses artisans se sont révoltés lorsque les dirigeants du royaume leur ont refusé une juste rémunération.",al={"vancleef dans le rapport","que dit le rapport sur vancleef"}},{q="Pourquoi Gryan Roidemantel a-t-il besoin de ce rapport ?",a="Gryan Roidemantel a besoin du rapport, car il dirige la People's Militia contre des raids de bandits coordonnés dans la Marche de l’Ouest. Sans troupes régulières du royaume pour l’aider, il compte sur les renseignements de Mathias Shaw pour découvrir qui dirige les hors-la-loi et ce qui les pousse à agir.",al={"pourquoi envoyer le rapport à gryan","pourquoi roidemantel a besoin du rapport"}},{q="Comment Roidemantel réagit-il au rapport ?",a="Le rapport trouble profondément Gryan Roidemantel. Il se souvient d’Edwin VanCleef comme d’un artisan industrieux et talentueux, et peine à croire qu’un bâtisseur aussi respecté soit devenu un criminel sans preuve supplémentaire.",al={"réaction de gryan","réaction de roidemantel"}}},fx={c86c6e50={q="D'où provient le Rapport de Shaw, et qui l'a rédigé ?",a="Le rapport a été rédigé par le Maître Mathias Shaw, à la tête du service de renseignement de Hurlevent, le SI:7. Depuis son quartier général dans la Vieille ville, Shaw a compilé les renseignements collectés par le SI:7 concernant l'histoire de la Guilde des maçons et d'Edwin VanCleef, afin de les transmettre à Gryan Roidemantel à la Colline des Sentinelles.",al={"qui a écrit le rapport de shaw","qui a créé le rapport de shaw","d'où vient le rapport de shaw"}}},fp="13,187,31.311.1,22.250.0,49.224.0,44.254.0,41.211.0"}
P.entries["item:shay-s-bell"] = {n="Shay's Bell",s="Shay’s Bell est une cloche précieuse conservée dans un coffre à Féralas. Shay Leafrunner dit que son tintement peut la rappeler lorsqu’elle s’égare.",h="Shay’s Bell est une cloche précieuse conservée dans un coffre à Féralas.",kw={"féralas","croque-roc","shay","shay leafrunner","shay’s bell","shay’s chest","shay s’égare"},sec={{t="Un son familier",b="Shay Leafrunner garde sa cloche dans un coffre à Féralas. Elle aime son tintement et dit qu’il la fera revenir en courant si elle s’éloigne. Croque-roc attend Shay à son camp, et la cloche doit l’aider à retrouver son chemin."}},faq={{q="À quoi sert Shay’s Bell ?",a="Shay dit que le son de la cloche attirera son attention et la fera revenir si elle s’égare.",al={"cloche de shay","utilité de la cloche","rappeler shay"}},{q="Où trouver Shay’s Bell ?",a="Shay’s Bell est conservée dans Shay’s Chest, à Féralas.",al={"emplacement de la cloche","coffre de shay","où trouver la cloche"}},{q="À qui appartient la cloche ?",a="Cette cloche est précieuse aux yeux de Shay Leafrunner, qui aime son tintement.",al={"à qui appartient la cloche","objet de shay","propriétaire de la cloche"}},{q="Qui Shay essaie-t-elle de retrouver ?",a="Shay Leafrunner essaie de retrouver son ami Croque-roc, qui se trouve à son camp.",al={"où va shay","ami de shay","croque-roc"}}},fp="11,128,16.225.0,26.90.0,31.51.0,28.61.0,27.75.0"}
P.entries["item:sheathed-trol-kalar"] = {n="Sheathed Trol'kalar",s="Trol'kalar repose libérée dans son fourreau de pierre, dans les Hautes-terres Arathies. Zengu, à Trépas-d'Orgrim, attend l'épée que les Trolls sombrelances chérissent.",h="Trol'kalar repose libérée dans son fourreau de pierre, dans les Hautes-terres Arathies.",kw={"sombrelance","trépas-d'orgrim","nimboya","trol'kalar dans son fourreau","fourreau de pierre","trol'kalar","tombeau de trollbane","zengu"},ang={["race:Troll"]="En tant que troll, vous portez une arme que Zengu qualifie de plus grande arme de Strom et d'Arathor. Les Sombrelances vous sont redevables de l'avoir rendue."},sec={{t="Le fourreau de pierre",b="Depuis le tombeau de Trollbane, dans les Hautes-terres Arathies, vous portez Trol'kalar dans son fourreau de pierre. La lumière qui retenait l'épée s'estompe et libère l'arme. Zengu vous attend à Trépas-d'Orgrim pour la recevoir."}},faq={{q="Qu'est-ce que Trol'kalar dans son fourreau ?",a="Sheathed Trol'kalar renferme l'épée Trol'kalar dans un fourreau de pierre. La lumière qui s'estompe libère l'arme.",al={"trolkalar dans son fourreau","épée dans un fourreau de pierre"}},{q="Où ai-je trouvé Trol'kalar ?",a="Vous trouvez Sheathed Trol'kalar dans le tombeau de Trollbane, dans les Hautes-terres Arathies.",al={"emplacement de trolkalar","tombeau de trollbane"}},{q="Qui veut l'épée ?",a="Zengu, à Trépas-d'Orgrim, attend Trol'kalar. Il dit qu'elle sera remise à Nimboya à Grom'gol.",al={"qui reçoit trolkalar","épée de zengu"}},{q="Pourquoi Trol'kalar compte-t-elle pour les trolls ?",a="Trol'kalar est appelée la plus grande arme de Strom et d'Arathor. Zengu dit que les Trolls sombrelances vous sont redevables de l'avoir rendue.",al={"importance de trolkalar","pourquoi les trolls veulent l'épée"}}},fp="19,136,16.186.0,28.107.0,28.69.0,20.91.0,41.132.0"}
P.entries["item:shellfish"] = {n="Shellfish",s="Les coquillages se récoltent dans des casiers sous les quais de Proie-de-l'Ombre. Jinar'Zillen veut qu'on les récupère et propose un poisson Bloodbelly en échange.",h="Les coquillages se récoltent dans des casiers sous les quais de Proie-de-l'Ombre.",kw={"poisson bloodbelly","désolace","quais","jinar'zillen","proie-de-l'ombre","coquillages","casiers à coquillages"},sec={{t="Sous les quais",b="Les eaux à l'ouest de Proie-de-l'Ombre abritent des casiers à coquillages sous les quais. Jinar'Zillen vous demande d'en récupérer cinq pour pouvoir confier cette tâche à quelqu'un d'autre. En échange, il vous propose un beau poisson Bloodbelly."}},faq={{q="Où trouver des coquillages ?",a="Vous pouvez récolter des coquillages dans les casiers des eaux à l'ouest de Proie-de-l'Ombre, sous ses quais.",al={"lieu des coquillages","où trouver des coquillages","casiers à coquillages"}},{q="Qui veut les coquillages ?",a="Jinar'Zillen, à Proie-de-l'Ombre, vous demande de récupérer des coquillages dans les casiers sous les quais.",al={"qui veut des coquillages","coquillages jinar'zillen","coquillages pour qui"}},{q="Combien de coquillages faut-il à Jinar'Zillen ?",a="Jinar'Zillen vous demande de récupérer cinq coquillages.",al={"nombre de coquillages","combien de coquillages","cinq coquillages"}},{q="Que propose Jinar'Zillen en échange des coquillages ?",a="Pour chaque lot de cinq coquillages que vous lui apportez, Jinar'Zillen vous propose un poisson Bloodbelly.",al={"récompense pour les coquillages","poisson bloodbelly","quoi en échange des coquillages"}}},fp="9,146,15.223.0,26.96.0,24.96.0,42.48.0,43.78.0"}
P.entries["item:shimmering-frond"] = {n="Racines chatoyantes",s="Dans la Clairière de l'Oracle, une plante venue de l'autre côté de la Grande mer dégage une aura chatoyante et tourbillonnante. Ses frondes appartiennent à une espèce originaire du Marais des Chagrins.",h="Dans la Clairière de l'Oracle, une plante venue de l'autre côté de la Grande mer dégage une aura chatoyante...",kw={"botanique","denalan","lac al'ameth","la clairière de l'oracle","racines chatoyantes","plante étrange à frondes","marais des chagrins","teldrassil"},ang={["class:Druid"]="En tant que druide, vous trouverez peut-être curieux qu'une plante des marais prospère sur les branches récemment élevées de Teldrassil.",["profession:Herbalism"]="En tant qu'herboriste, vous pouvez apprécier la résilience qu'il a fallu à une plante du Marais des Chagrins pour traverser l'océan et prospérer dans une terre étrangère."},sec={{t="Un spécimen venu de loin",b="Près de la Clairière de l'Oracle, une plante rayonnante pousse parmi les arbres. Son aura palpite et ses frondes scintillent dans la lumière des bois. Denalan entretient des jardinières près du lac Al'Ameth. Il reconnaît ces feuilles comme celles d'une espèce du Marais des Chagrins, dans les Royaumes de l'est. La façon dont des graines de ce marais lointain ont traversé la Grande mer et pris racine sur Teldrassil reste un mystère. Denalan fait pousser des spécimens dans sa propre terre pour les étudier."}},faq={{q="D'où viennent les Racines chatoyantes ?",a="Une plante étrange de la Clairière de l'Oracle, sur Teldrassil, porte les Racines chatoyantes. Ses feuilles scintillent d'une lueur tourbillonnante et palpitante dans la lumière de la forêt.",al={"où trouver les racines chatoyantes","emplacement des racines chatoyantes","plante étrange à frondes"}},{q="Qui s'intéresse aux Racines chatoyantes ?",a="Denalan, un naturaliste elfe de la nuit près du lac Al'Ameth, veut étudier les Racines chatoyantes. Il étudie les plantes étranges qui prennent racine partout sur Teldrassil.",al={"qui veut les racines chatoyantes","à qui donner les racines chatoyantes","denalan racines chatoyantes"}},{q="Qu'est-ce qui rend cette plante si inhabituelle sur Teldrassil ?",a="Cette plante vient du Marais des Chagrins, dans les Royaumes de l'est, de l'autre côté de la Grande mer. Sa présence sur Teldrassil est inattendue, car elle n'est originaire ni de Kalimdor ni de l'Arbre-monde.",al={"pourquoi les racines chatoyantes sont spéciales","origine de la plante","plante du marais des chagrins"}},{q="Que se passe-t-il après avoir donné les Racines chatoyantes à Denalan ?",a="Denalan plante le spécimen dans ses jardinières près du lac Al'Ameth. Il étudie sa croissance rapide et ses propriétés exotiques.",al={"que fait denalan avec","histoire des frondes germées"}}},fx={["7be1ca60"]={q="Qu'est-ce que les Racines chatoyantes ?",a="Il s'agit d'une feuille prélevée sur une flore inhabituelle et envahissante, connue sous le nom de plante aux frondes étranges, que l'on trouve dans La Clairière de l'Oracle. La fronde scintille constamment sous la canopée de la forêt, rayonnant d'une aura tordue et pulsante, inhabituelle pour les branches de Teldrassil.",al={"qu'est-ce que les racines chatoyantes","objet racines chatoyantes","qu'est-ce que cette fronde"}}},fp="16,152,20.421.0,42.151.0,42.139.0,47.183.0,47.116.0"}
P.entries["item:shimmerweed"] = {n="Chatoyante",s="Sur la Crête scintillante, les trolls Crins-de-givre récoltent la Chatoyante pour leurs rituels. Rejold Brasselorge, de Brassetout, veut en tester la saveur prononcée dans sa bière brune.",h="Sur la Crête scintillante, les trolls Crins-de-givre récoltent la Chatoyante pour leurs rituels.",kw={"brassetout","dun morogh","crins-de-givre","bière brune parfaite","rejold brasselorge","crête scintillante","chatoyante"},ang={["profession:Herbalism"]="En tant qu’herboriste, vous pouvez constater comment les plantes régionales trouvent leur place dans les traditions brassicoles et l’alchimie rituelle locales.",["race:Dwarf"]="En tant que nain, vous pouvez constater comment l’ingéniosité transforme une plante étrange d’une falaise voisine en expérience brassicole."},sec={{t="Une récolte troll",b="La Chatoyante pousse sur les pics glacés qui dominent les basses terres de Dun Morogh, où les trolls Crins-de-givre en prennent soin. Ils récoltent la plante et la conservent dans des paniers tressés à travers leurs camps. Elle alimente leurs rituels sacrés. Peu de montagnards étrangers à la société trolle lui prêtent attention, mais des outsiders inventifs s’y intéressent."},{t="Un ingrédient secret",b="À Brassetout, le maître brasseur Rejold Brasselorge soupçonne que la Chatoyante pourrait être l’ingrédient manquant pour brasser la bière brune naine ultime. Il a décelé la saveur âcre et inimitable de l’herbe et veut la tester dans ses cuves de fermentation. Rejold engage donc des voyageurs pour s’introduire dans les camps Crins-de-givre, éviter les trolls hostiles et rapporter des boisseaux."}},faq={{q="Où pousse la Chatoyante ?",a="La Chatoyante pousse sur la Crête scintillante, un relief glacé au nord-ouest de Brassetout, dans Dun Morogh. Les trolls Crins-de-givre en prennent soin et rangent leurs récoltes dans des paniers autour de leurs camps.",al={"emplacement de la chatoyante","où trouver la chatoyante","plante de la crête scintillante"}},{q="À quoi les trolls Crins-de-givre utilisent-ils la Chatoyante ?",a="Les trolls Crins-de-givre utilisent la Chatoyante dans leurs mystérieux rites et cérémonies tribaux. Les étrangers n’en connaissent pas les détails précis, mais l’herbe occupe une place dans leurs pratiques culturelles et spirituelles sur la Crête scintillante.",al={"usage de la chatoyante par les trolls","pourquoi les trolls veulent la chatoyante"}},{q="Pourquoi Rejold Brasselorge veut-il de la Chatoyante ?",a="Rejold Brasselorge veut de la Chatoyante pour tenter de brasser la bière brune naine parfaite à Brassetout. Il en a décelé le goût unique et espère que des boisseaux frais donneront à son brassin expérimental le caractère prononcé dont sa recette a besoin.",al={"quête de rejold brasselorge","qui veut la chatoyante","pourquoi brasser avec la chatoyante"}},{q="La Chatoyante pousse-t-elle ailleurs qu’à Dun Morogh ?",a="La Chatoyante a aussi été récoltée dans des terres arides comme Durotar, où des visionnaires comme Drek'Thar l’apprécient pour ses puissantes préparations à base de plantes et ses breuvages médicinaux. Cette plante pousse aussi au-delà des pics gelés de Khaz Modan.",al={"chatoyante à durotar","chatoyante hors de dun morogh"}}},fx={["1978b4f9"]={q="Qu'est-ce que la Chatoyante ?",a="La Chatoyante est une plante distinctive cultivée sur les hauteurs enneigées de Dun Morogh par les trolls des Givre-crâne, en particulier autour de la Crête scintillante. Remarquable pour sa saveur et ses propriétés inhabituelles, l'herbe est ramassée dans des paniers par les trolls et joue un rôle dans les rituels tribaux locaux, bien que des brasseurs nains ambitieux aient récemment commencé à tester ses propriétés puissantes dans des bières expérimentales.",al={"qu'est-ce que la chatoyante","plante chatoyante","à propos de la chatoyante"}},d2fd1cd1={q="D'où vient la Chatoyante, et qui l'a produite ?",a="La Chatoyante est cultivée naturellement par les trolls des Givre-crâne à Dun Morogh, qui entretiennent et récoltent la plante dans des paniers sur la Crête scintillante. Bien que les Givre-crâne maintiennent des cultures de cette plante pour leurs propres rituels, des variétés sauvages de cette herbe puissante poussent également dans des contrées lointaines comme le Durotar, où les herboristes et les chamans du désert la prisent pour la préparation de potions.",al={"d'où vient la chatoyante","qui a créé la chatoyante","origine de la chatoyante"}}},fp="11,155,15.319.0,19.352.0,28.175.0,49.209.0,44.230.0,50.210.0"}
P.entries["item:shindrell-s-note"] = {n="Note de Shindrell",s="À Astranaar, Shindrell Prestefeu signale une corruption près de la ville et le long des côtes d’Orneval. Son rapport traverse la forêt vers l’est pour parvenir à Kayneth Stillwind.",h="À Astranaar, Shindrell Prestefeu signale une corruption près de la ville et le long des côtes d’Orneval.",kw={"orneval","astranaar","chant des forêts","kayneth stillwind","bois de chantenuit","shindrell prestefeu","note de shindrell"},ang={["class:Druid"]="Les observations de Shindrell aident Kayneth Stillwind et ses confrères druides à découvrir l’origine du fléau surnaturel qui trouble Orneval.",["race:NightElf"]="Les sentinelles qui défendent les colonies d’Orneval coopèrent avec les druides cénariens qui étudient le mal dont souffre la forêt."},sec={{t="Une missive à travers les bois",b="Les sentinelles et les druides surveillent ensemble les frontières d’Orneval tandis que l’agitation gagne la forêt. Depuis Astranaar, la sentinelle Shindrell Prestefeu signale des perturbations inquiétantes sur la côte ouest et dans les frondaisons centrales.\n\nSon rapport est adressé à Kayneth Stillwind, un druide du sanctuaire de Chant des forêts, dans les Bois de Chantenuit, à l’est. Des courriers transmettent les observations directes de Shindrell pour l’aider à rechercher la corruption dans les bosquets sacrés."}},faq={{q="Qu’est-ce que la Note de Shindrell ?",a="Le rapport de terrain de la sentinelle Shindrell Prestefeu décrit des perturbations et une corruption présumée près d’Astranaar et le long du littoral d’Orneval.",al={"qu’est-ce que cette note","note de shindrell","que dit la note"}},{q="À qui la note est-elle destinée ?",a="La note est adressée à Kayneth Stillwind, un druide elfe de la nuit de Chant des forêts, dans les Bois de Chantenuit, à l’est d’Orneval.",al={"à qui remettre cette note","où l’envoyer","pour qui est la note"}},{q="Pourquoi la note a-t-elle été écrite ?",a="Kayneth Stillwind craignait que la corruption ne s’enracine dans les forêts occidentales et avait demandé des rapports sur les événements inhabituels. Shindrell a recueilli ses observations pour l’aider à évaluer la menace.",al={"pourquoi écrire cette note","de quelle corruption parle shindrell","but du rapport"}},{q="Où réside Shindrell Prestefeu ?",a="Shindrell Prestefeu est une sentinelle elfe de la nuit affectée à Astranaar, une colonie au centre d’Orneval.",al={"où se trouve shindrell","emplacement de shindrell prestefeu","qui l’a envoyée"}}},fx={ed6c40b2={q="D'où provient la Note de Shindrell, et qui l'a rédigée ?",a="La note a été rédigée par la Sentinelle Shindrell Prestefeu à Astranaar. Rédigée sous la forme d'un rapport de terrain officiel, elle détaille les événements troublants qu'elle a observés le long de la côte d'Orneval et dans les bois environnants.",al={"qui a écrit la note de shindrell","qui a créé la note de shindrell","origine de la note de shindrell"}}},fp="16,162,26.450.0,25.139.0,33.121.0,25.183.0,38.102.0"}
P.entries["item:shipment-of-boots"] = {n="Cargaison de bottes",s="Le long du littoral des Tarides, la Cargaison de bottes se trouve toujours dans un campement des Southsea Freebooters, au sud de Cabestan. Drizzlik a expédié la caisse depuis Baie-du-Butin pour le réseau commercial de Gazlowe, mais les pirates l’ont saisie avant qu’elle n’atteigne le port.",h="Le long du littoral des Tarides, la Cargaison de bottes se trouve toujours dans un campement des Southsea...",kw={"baie-du-butin","drizzlik","gazlowe","cabestan","cargaison de bottes","southsea freebooters","stolen booty"},ang={["class:Rogue"]="En tant que voleur, vous pouvez vous faufiler dans les campements des Southsea Freebooters, le long du littoral. Les patrouilles pirates sont nombreuses ; mieux vaut donc avancer sans bruit pour récupérer le chargement volé de Gazlowe."},sec={{t="Une cargaison pillée",b="Gazlowe a demandé à Drizzlik, un marchand de vêtements de Baie-du-Butin, d’envoyer des bottes à Cabestan. Les Southsea Freebooters ont attaqué le navire alors qu’ils patrouillaient le long de la Côte des marchands. Ils ont transporté les caisses jusqu’à des campements sur la plage, au sud du port, et ont dispersé les biens volés dans leurs tentes et leurs cabanes. La cargaison s’y trouve toujours, loin des quais de Cabestan."}},faq={{q="Qui a envoyé cette cargaison de bottes ?",a="Drizzlik, un marchand gobelin de Baie-du-Butin, a envoyé les bottes depuis le port du sud.",al={"qui a fabriqué les bottes","d’où viennent les bottes","bottes de drizzlik"}},{q="À qui les bottes devaient-elles être livrées ?",a="Gazlowe a commandé les bottes pour Cabestan. Il en est l’ingénieur en chef et le superviseur, et la cargaison devait approvisionner sa main-d’œuvre locale et soutenir le commerce.",al={"à qui sont les bottes","cargaison de bottes de gazlowe"}},{q="Comment les pirates se sont-ils emparés des bottes ?",a="Les Southsea Freebooters ont attaqué le navire marchand le long du littoral des Tarides. Ils l’ont pillé et ont transporté les caisses jusqu’à leurs campements au sud de Cabestan.",al={"pourquoi les pirates southsea ont des bottes","qui a volé les bottes"}},{q="Où trouver la cargaison ?",a="La cargaison se trouve parmi les biens pillés dans le campement des pirates Southsea, sur le littoral au sud de Cabestan.",al={"emplacement des bottes","où se trouve la cargaison de bottes","trouver la cargaison de bottes"}}},fx={["06b396e7"]={q="Qu'est-ce que la Cargaison de bottes ?",a="La Cargaison de bottes est une caisse de chaussures envoyée à travers La Grande mer depuis Baie-du-Butin jusqu'à Cabestan. Expédiée par le marchand gobelin Drizzlik, elle était destinée directement à Gazlowe avant que les pirates de la Mer du Sud ne interceptent le navire marchand transportant ses marchandises.",al={"qu'est-ce que la cargaison de bottes","objet cargaison de bottes","qu'est-ce que les bottes"}}},fp="17,211,17.348.0,32.80.0,38.152.0,42.149.0,32.107.0"}
P.entries["item:shipment-of-iron"] = {n="Chargement de fer",s="Aux Champs de Hautebrande, le fer brut attend à la forge humaine, où il arme les habitants contre les Réprouvés.",h="Aux Champs de Hautebrande, le fer brut attend à la forge humaine, où il arme les habitants contre les...",kw={"battle of hillsbrad","darthalia","champs de hautebrande","chargement de fer","moulin-de-tarren","verringtan"},ang={["faction:Horde"]="En tant que membre de la Horde, priver Hautebrande de ses approvisionnements affaiblit la résistance armée des fermiers avant la campagne contre Austrivage.",["profession:Blacksmithing"]="Pour un forgeron, le fer brut permet à la production d’armes humaines de se poursuivre dans la vallée. Sans les lingots, la forge de Verringtan reste inutilisée."},sec={{t="Nourrir la résistance",b="Les paysans humains des Contreforts de Hautebrande résistent à Moulin-de-Tarren. Une grande part de leur force vient de la forge, à l’extrémité sud-ouest des Champs de Hautebrande. Le Forgeron Verringtan et ses apprentis transforment de lourds chargements de fer en armes et en armures, jour et nuit.\n\nLes commandants réprouvés ont ordonné d’éteindre la forge, de tuer ses forgerons et de saisir le métal entreposé pour l’effort de guerre de la Horde. Ils espèrent briser la détermination des fermiers."}},faq={{q="Où le chargement de fer est-il entreposé ?",a="Le fer est entreposé dans l’atelier de forge, à l’extrémité sud-ouest des Champs de Hautebrande. Le Forgeron Verringtan et ses apprentis le gardent de près.",al={"emplacement du chargement de fer","où se trouve le fer","emplacement du fer à hautebrande"}},{q="Pourquoi les Réprouvés veulent-ils ce fer ?",a="Le fer arme la milice humaine locale, et les Réprouvés veulent lui couper cet approvisionnement. La Grande exécutrice Darthalia entend aussi utiliser les réserves pour l’effort de guerre de la Horde, lorsque l’offensive se tournera vers la destruction d’Austrivage.",al={"pourquoi voler le fer","fer de moulin-de-tarren","utilité du fer pendant la bataille de hautebrande"}},{q="Qui utilisait ce fer à l’origine ?",a="Le Forgeron Verringtan et ses quatre apprentis forgerons utilisaient le fer pour armer les habitants et les travailleurs des champs. Ils ont transformé de simples fermiers en force de défense locale contre les morts-vivants.",al={"à qui appartient le fer","fer de verringtan","forgerons de hautebrande"}},{q="Qui ordonne de récupérer le chargement de fer ?",a="La Grande exécutrice Darthalia commande les opérations des Réprouvés depuis Moulin-de-Tarren. Pendant la bataille de Hautebrande, elle ordonne de tuer les forgerons et de s’emparer du fer.",al={"qui donne la quête","quête du fer de darthalia"}}},fx={["8a003d21"]={q="Qu'est-ce que le Chargement de fer ?",a="Le Chargement de fer est une réserve de métal brut stockée à la forge humaine dans les Champs de Hautebrande. Elle sert de matériau principal au forgeron Verringtan et à ses apprentis pour forger des armes et des armures pour les habitants locaux de Hautebrande qui résistent aux Réprouvés.",al={"qu'est-ce que le chargement de fer","chargement de fer","chargement de fer hautebrande"}}},fp="16,106,22.445.0,35.153.0,37.217.0,35.182.0,46.154.0"}
P.entries["item:shipment-to-nethergarde"] = {n="Shipment to Nethergarde",s="La caravane de Biggs envoie une cargaison de provisions essentielles du Marais des Chagrins au Rempart-du-Néant. Le donjon en a besoin pour surveiller La Porte des ténèbres.",h="La caravane de Biggs envoie une cargaison de provisions essentielles du Marais des Chagrins au...",kw={"azoran crystals","biggs","terres foudroyées","la porte des ténèbres","rempart-du-néant","attaques d'ogres","intendant lungertz","cargaison pour le rempart-du-néant"},ang={["faction:Alliance"]="En tant que voyageur de l'Alliance, vous transportez des provisions au Rempart-du-Néant, qui surveille La Porte des ténèbres."},sec={{t="Une livraison nécessaire",b="Biggs vous demande de porter au Rempart-du-Néant des provisions récupérées après des attaques d'ogres, à l'intendant Lungertz. Le donjon surveille La Porte des ténèbres depuis les collines du nord des Terres Foudroyées. Biggs répare son chariot, alors la cargaison doit faire la route sans lui."}},faq={{q="Que contient la cargaison ?",a="La cargaison contient des provisions essentielles récupérées après des attaques d'ogres. L'intendant Lungertz espère qu'elle comprend des Azoran Crystals, dont les réserves du Rempart-du-Néant s'épuisent.",al={"contenu de la cargaison","que contient le colis","azoran crystals"}},{q="Qui a envoyé la cargaison ?",a="Biggs a préparé les provisions pour le Rempart-du-Néant après que des attaques d'ogres ont menacé la caravane.",al={"qui l'a préparé","colis de biggs","origine de la cargaison"}},{q="Qui doit recevoir la cargaison ?",a="L'intendant Lungertz attend la cargaison au Rempart-du-Néant.",al={"qui reçoit le colis","livraison au rempart-du-néant","intendant lungertz"}},{q="Pourquoi le Rempart-du-Néant en a-t-il besoin ?",a="Le Rempart-du-Néant a besoin des provisions, et l'intendant Lungertz dit que ses réserves d'Azoran Crystals s'épuisent.",al={"pourquoi des provisions","de quoi le donjon a-t-il besoin","réserves du rempart-du-néant"}}},fp="23,147,17.266.0,24.163.0,22.89.0,32.71.0,29.113.0"}
P.entries["item:shipping-schedule"] = {n="Shipping Schedule",s="Au Débarcadère de Jerod, la Confrérie défias fait passer de la contrebande par les voies navigables de la Forêt d’Elwynn. Son maître des quais garde un registre des cargaisons entre Les Carmines et la Marche de l’Ouest, que convoite SI:7.",h="Au Débarcadère de Jerod, la Confrérie défias fait passer de la contrebande par les voies navigables de la...",kw={"défias","maître des quais","forêt d’elwynn","le débarcadère de jerod","mathias shaw","shipping schedule","si:7","contrebande"},ang={["class:Rogue"]="En tant que voleur, vous pouvez mettre à l’épreuve la discrétion et le vol à la tire que SI:7 attend de ses recrues, en dérobant le registre dans les poches du maître des quais."},sec={{t="Contrebande au Débarcadère de Jerod",b="Au sud de Comté-de-l’Or, le Débarcadère de Jerod se trouve sur la rive d’Elwynn de la rivière Nazferiti. La Confrérie défias s’en est emparée pour en faire une plaque tournante du trafic fluvial. De là, elle transporte de la contrebande entre Les Carmines et la Marche de l’Ouest par des voies navigables qui échappent à la vigilance de la garde de Hurlevent. Son maître des quais garde précieusement le Shipping Schedule, où il consigne chaque cargaison."},{t="Dans le viseur de SI:7",b="Maître Mathias Shaw dirige SI:7, l’agence de renseignement de Hurlevent, et a ordonné le vol du registre. Celui-ci peut révéler les lignes d’approvisionnement des Défias, et son vol met à l’épreuve les nouvelles recrues. Le vol doit avoir lieu dans la maison des quais, dans les poches du maître des quais. Si l’agent se fait prendre, SI:7 nie tout lien avec lui. Aucune piste ne mène à ses casernes de Hurlevent."}},faq={{q="Qu’est-ce que le Shipping Schedule ?",a="Le Shipping Schedule consigne les cargaisons de contrebande transportées par le maître des quais de la Confrérie défias au Débarcadère de Jerod. Il suit les marchandises acheminées entre Les Carmines et la Marche de l’Ouest par les voies navigables de l’intérieur de la Forêt d’Elwynn.",al={"programme d'embarquement des défias","nature de ce document","registre du maître des quais"}},{q="Qui veut récupérer ce registre ?",a="Maître Mathias Shaw, chef de SI:7, veut récupérer le registre. Il s’en sert pour suivre la contrebande des Défias et mettre à l’épreuve sur le terrain les voleurs prometteurs.",al={"qui a besoin du registre","registre de mathias shaw","qui prend le shipping schedule"}},{q="Où trouve-t-on le registre ?",a="Le maître des quais défias porte le registre dans la maison des quais du Débarcadère de Jerod. Le débarcadère se trouve sur la rivière Nazferiti, au sud de Comté-de-l’Or, dans la Forêt d’Elwynn ; il faut dérober le document sur lui, là-bas.",al={"emplacement du shipping schedule","où se trouve le maître des quais","comment obtenir le registre"}},{q="À quoi sert le Débarcadère de Jerod ?",a="La Confrérie défias s’est emparée du Débarcadère de Jerod pour en faire une étape de contrebande. Son accès à la rivière relie ses opérations des Carmines à ses bastions de la Marche de l’Ouest.",al={"débarcadère de jerod et défias","pourquoi les défias ont le débarcadère de jerod","quai défias en elwynn"}}},fx={["45ccd8c3"]={q="D'où provient le Programme d'embarquement des Défias, et qui l'a créé ?",a="Le programme est conservé par le maître de port de la Confrérie des Défias stationné au Débarcadère de Jerod, au sud du Comté-de-l’Or. Il détaille les opérations fluviales du syndicat de hors-la-loi, suivant le mouvement des biens illicites et de la contrebande entre Les Carmines et la Marche de l’Ouest.",al={"qui a écrit le programme d'embarquement","origine du programme d'embarquement","qui a créé le programme d'embarquement des défias"}}},fp="17,181,28.335.0,25.350.0,30.208.0,34.141.0,28.208.0,33.167.0"}
P.entries["item:shrunken-head"] = {n="Shrunken Head",s="Une Shrunken Head est prélevée sur les Bloodscalp Headhunters du nord de la Vallée de Strangleronce. Au Campement Grom'gol, Nimboya les examine dans l'espoir d'obtenir des nouvelles de Yenniku.",h="Une Shrunken Head est prélevée sur les Bloodscalp Headhunters du nord de la Vallée de Strangleronce.",kw={"bloodscalp","campement grom'gol","chasseur de têtes","nimboya","tête réduite","yenniku","zul'kunda","zuuldaia"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez apporter à Nimboya les têtes dont il a besoin pour rechercher Yenniku, le fils du chef."},sec={{t="La quête de Nimboya",b="Au Campement Grom'gol, Nimboya vous demande de lui rapporter des Shrunken Heads prélevées sur les Bloodscalp Headhunters. Il cherche dans chacune des traces de Yenniku, le fils du chef, dont il ignore le sort. Les ruines de Zuuldaia et de Zul'Kunda se trouvent le long de la côte nord, où l'on peut trouver de nombreux Headhunters."}},faq={{q="À quoi sert une Shrunken Head ?",a="Nimboya examine les Shrunken Heads pour savoir si Yenniku compte parmi les morts.",al={"utilité des têtes réduites","pourquoi collecter des têtes"}},{q="Qui recherche Yenniku ?",a="Nimboya, au Campement Grom'gol, craint pour Yenniku, le fils du chef, et cherche des indices sur son sort.",al={"qui recherche yenniku","quête de nimboya"}},{q="D'où viennent les Shrunken Heads ?",a="Les Bloodscalp Headhunters du nord de la Vallée de Strangleronce portent les têtes que recherche Nimboya.",al={"où trouver des têtes","têtes bloodscalp"}},{q="Où trouver les Bloodscalp Headhunters ?",a="Nimboya indique les ruines de Zuuldaia et de Zul'Kunda, le long de la côte nord.",al={"emplacement des chasseurs de têtes","où trouver les chasseurs de têtes"}}},fp="13,154,16.289.0,28.75.0,27.94.0,34.79.0,40.79.0"}
P.entries["item:sida-s-bag"] = {n="Sac de Sidonie",s="Près de la Tombe de Barbe-de-fer, le Sac de Sidonie a été englouti par un limon. Sidonie a fui au Port de Menethil après avoir lancé sa besace sur l’un des limons lors de sa visite hebdomadaire. À présent, il faut fouiller ces créatures acides pour retrouver ses affaires.",h="Près de la Tombe de Barbe-de-fer, le Sac de Sidonie a été englouti par un limon.",kw={"dun modr","tombe de barbe-de-fer","port de menethil","limon","sidonie","sac de sidonie","les paluns"},ang={["faction:Alliance"]="Les réfugiés et les habitants éprouvés du Port de Menethil comptent sur les voyageurs de passage pour affronter les horreurs prédatrices qui s’avancent depuis les Paluns inondés."},sec={{t="Une défense paniquée",b="Chaque semaine, Sidonie se rend à la Tombe de Barbe-de-fer, près de Dun Modr. De terrifiants limons dégoulinants l’y ont prise en embuscade, et la panique l’a poussée à lancer sa besace sur l’un d’eux. Le limon a englouti le sac. Cela a donné à Sidonie le temps de s’enfuir vivante et de regagner le Port de Menethil, tandis que ses affaires restaient prisonnières d’un limon inconnu."},{t="Récupéré dans le limon",b="Les limons autour de la Tombe de Barbe-de-fer vont du cramoisi au monstrueux et se ressemblent beaucoup. Abattez les limons des marais jusqu’à ce que le Sac de Sidonie ressorte intact. La boue acide a imprégné le sac résistant, mais son contenu est resté préservé. Sidonie récupère ses affaires, puis se débarrasse de l’enveloppe abîmée et couverte de limon, et offre le contenant rincé à qui a bravé le marais pour elle."}},faq={{q="Pourquoi le sac de Sidonie se trouvait-il dans un limon ?",a="Des limons dégoulinants ont attaqué Sidonie lors de sa visite à la Tombe de Barbe-de-fer, et la panique l’a gagnée. Elle a lancé sa besace sur l’un d’eux pour s’échapper, et le limon l’a engloutie tout entière.",al={"comment le limon a eu le sac","pourquoi le sac est dans un limon","comment sidonie a perdu son sac"}},{q="Quels limons transportent le Sac de Sidonie ?",a="Sidonie ne distingue pas les limons les uns des autres. N’importe quel limon prédateur autour de la Tombe de Barbe-de-fer, dans le nord-est des Paluns, pourrait donc avoir englouti le sac. Les Crimson Oozes, les Black Oozes et les Monstrous Oozes rôdent tous dans la région.",al={"où trouver le sac de sidonie","que donne le sac de sidonie","quel limon a le sac"}},{q="Pourquoi Sidonie se rend-elle à la Tombe de Barbe-de-fer ?",a="Chaque semaine, Sidonie part du Port de Menethil pour visiter l’ancienne crypte naine près de Dun Modr. Elle garde pour elle les raisons personnelles de ces visites.",al={"lien entre sidonie et barbe-de-fer","pourquoi la tombe de barbe-de-fer"}},{q="Que contenait le sac de Sidonie ?",a="Sidonie dépose au sol les objets qu’elle a récupérés, puis les ramasse sans révéler ce qu’ils sont. Elle dit seulement qu’ils étaient bien trop importants pour les laisser se dissoudre dans un limon.",al={"que sort sidonie de son sac","contenu du sac"}}},fx={["113113dd"]={q="Qu'est-ce que le Sac de Sidonie ?",a="Le Sac de Sidonie est une sacoche personnelle appartenant à Sidonie, une résidente séjournant au Port de Menethil. Lors d'une visite de routine à la Tombe de Barbe-de-fer dans Les Paluns, elle a été prise en embuscade par des limons et a lancé son sac sur l'un d'eux dans une tentative désespérée de s'échapper. La créature l'a avalé tout rond, laissant le sac piégé à l'intérieur du corps gélatineux de la créature.",al={"qu'est-ce que le sac de sidonie","sac de sidonie","à qui appartient le sac de sidonie"}},afbd2451={q="Pourquoi Sidonie veut-elle récupérer son sac ?",a="Sidonie a désespérément besoin du contenu enfermé dans sa sacoche perdue, plutôt que du sac lui-même. Une fois que vous l'aurez arraché des restes des vases à la Tombe de Barbe-de-fer et que vous l'aurez rapporté à Sidonie au Port de Menethil, elle videra immédiatement le contenu visqueux sur le sol, le ramassera et vous remettra la sacoche vide et tachée par la vase.",al={"pourquoi sidonie veut-elle son sac","pourquoi le sac de sidonie","pourquoi quelqu'un voudrait le sac de sidonie"}}},fp="10,224,18.300.0,24.369.0,34.160.0,29.204.0,37.154.0,27.179.0"}
P.entries["item:sigil-fragment"] = {n="Sigil Fragment",s="Le Sigil Fragment est un morceau d’un sceau protecteur recherché dans les Hautes-terres Arathies. Tor’gan, à Trépas-d'Orgrim, peut lier les fragments réunis.",h="Le Sigil Fragment est un morceau d’un sceau protecteur recherché dans les Hautes-terres Arathies.",kw={"hautes-terres arathies","sceau brisé","galen","trépas-d'orgrim","sigil fragment","sigil of thoradin","stromgarde","thoras trollbane","tor'gan"},ang={["class:Shaman"]="En tant que chamane, vous pouvez reconnaître le rôle de Tor’gan : ce chamane troll peut réunir les fragments pour reformer le sceau."},sec={{t="Morceaux d’un sceau",b="Les défenseurs de Stromgarde détiennent des fragments du sceau dans les ruines de Stromgarde. Galen, fils de Thoras Trollbane, a divisé le Sigil of Thoradin en onze morceaux et les a dispersés parmi les défenseurs. Tor’gan, un chamane troll à Trépas-d'Orgrim, peut réunir les morceaux pour reconstituer le sceau complet."}},faq={{q="Qu’est-ce qu’un Sigil Fragment ?",a="Un Sigil Fragment est un morceau du Sigil of Thoradin, que Galen a divisé en onze parties.",al={"morceau de sceau","que signifie ce fragment","signification du fragment"}},{q="Qui détient les fragments ?",a="Les défenseurs de Stromgarde, dans les Hautes-terres Arathies, détiennent les fragments.",al={"où trouver les fragments","qui détient les morceaux du sceau","fragments de stromgarde"}},{q="Qui peut reconstituer le sceau ?",a="Tor’gan, le chamane troll à Trépas-d'Orgrim, peut lier les fragments pour reconstituer le Sigil of Thoradin complet.",al={"qui répare le sceau","fragments de tor’gan","reconstituer le sceau brisé"}},{q="Pourquoi le sceau a-t-il été séparé ?",a="Galen, fils de Thoras Trollbane, a divisé le Sigil of Thoradin en onze morceaux et les a dispersés parmi les défenseurs de Stromgarde.",al={"pourquoi séparer le sceau","qui l’a brisé","sceau de galen"}}},fp="14,151,17.297.0,25.94.0,22.64.0,36.102.1,31.127.1"}
P.entries["item:sigil-of-arathor"] = {n="Sigil of Arathor",s="Le Sigil of Arathor est détenu par Lieutenant Valorcall, chef de la cavalerie de Stromgarde. Zengu, à Trépas-d'Orgrim, le veut pour poursuivre ses recherches sur Trol’kalar.",h="Le Sigil of Arathor est détenu par Lieutenant Valorcall, chef de la cavalerie de Stromgarde.",kw={"hautes-terres arathies","cavalerie","trépas-d'orgrim","lieutenant valorcall","sigil of arathor","stromgarde","trol'kalar","zengu"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez entendre Zengu, à Trépas-d'Orgrim, réclamer l'insigne pour affaiblir les défenseurs de Stromgarde."},sec={{t="Un insigne de cavalerie",b="Lieutenant Valorcall transporte le Sigil of Arathor à travers les Hautes-terres Arathies. Il dirige la cavalerie au service du prince humain et des défenseurs de Stromgarde. Zengu, à Trépas-d'Orgrim, convoite l'insigne, et le cheval de Valorcall lui permet de parcourir rapidement la campagne."},{t="Le but de Zengu",b="Zengu veut que l'insigne lui soit rapporté à Trépas-d'Orgrim. Il croit que le prendre à Valorcall affaiblira les défenseurs de Stromgarde. Il affirme aussi que l'insigne le rapproche de Trol’kalar."}},faq={{q="Qu'est-ce que le Sigil of Arathor ?",a="Le Sigil of Arathor est un insigne porté par Lieutenant Valorcall, le chef de la cavalerie de Stromgarde.",al={"sigil of arathor","insigne arathor"}},{q="Qui détient l'insigne ?",a="Lieutenant Valorcall transporte le Sigil of Arathor tandis qu'il chevauche à travers les Hautes-terres Arathies.",al={"insigne valorcall","qui le détient"}},{q="Où se trouve Lieutenant Valorcall ?",a="Lieutenant Valorcall chevauche à travers les Hautes-terres Arathies, où son cheval lui permet de voyager rapidement.",al={"où se trouve valorcall","trouver valorcall"}},{q="Qui veut le Sigil of Arathor ?",a="Zengu, à Trépas-d'Orgrim, veut qu'on lui rapporte le Sigil of Arathor.",al={"qui veut l'insigne","zengu le veut"}},{q="Pourquoi Zengu veut-il l'insigne ?",a="Zengu croit que prendre l'insigne affaiblira les défenseurs de Stromgarde et le rapprochera de Trol’kalar.",al={"pourquoi zengu le veut","trolkalar insigne"}}},fp="16,149,15.259.0,17.203.1,29.102.0,18.91.0,30.97.0,31.63.0,30.115.0"}
P.entries["item:sigil-of-ignaeus"] = {n="Glyphe d'Ignaeus",s="Le Glyphe d’Ignaeus réunit quatre glyphes anciens à Trépas-d'Orgrim. Sa lumière peut ouvrir le passage à travers les protections du tombeau de Trollbane.",h="Le Glyphe d’Ignaeus réunit quatre glyphes anciens à Trépas-d'Orgrim.",kw={"trépas-d'orgrim","igneaus","sanctuaire","glyphe","glyphe d'ignaeus","stromgarde","trol'kalar","trollbane","zengu"},sec={{t="Les glyphes réunis",b="À Trépas-d'Orgrim, Zengu vous remet le Glyphe d’Ignaeus une fois les quatre glyphes réunis. Ses lignes lumineuses correspondent aux gravures sur la façade du tombeau de Trollbane, au Sanctuaire de Stromgarde. Les protections du tombeau barrent l’accès à ce qui se trouve à l’intérieur."},{t="Au tombeau de Trollbane",b="Lorsque vous alignez les lignes du glyphe sur les gravures du tombeau de Trollbane, un éclair de lumière le consume. Les mains de pierre libèrent l’épée légendaire Trol'kalar."}},faq={{q="Qu’est-ce que le Glyphe d’Ignaeus ?",a="Le Glyphe d’Ignaeus est un glyphe unique formé par la réunion des Sigils of Strom, Thoradin, Arathor et Trollbane.",al={"glyphe d’igneaus","qu’est-ce que le glyphe"}},{q="Qui vous remet le Glyphe d’Ignaeus ?",a="Zengu vous remet le Glyphe d’Ignaeus à Trépas-d'Orgrim.",al={"qui possède le glyphe d’ig","où trouver le glyphe","glyphe de zengu"}},{q="À quoi sert le glyphe ?",a="Ses lignes lumineuses correspondent aux gravures du tombeau de Trollbane et brisent les protections qui le gardent.",al={"utilisation du glyphe","pourquoi faut-il le glyphe d’ig","briser les protections du tombeau"}},{q="Où se trouve le tombeau de Trollbane ?",a="Le tombeau de Trollbane se trouve au Sanctuaire, derrière la chapelle de Stromgarde.",al={"emplacement du tombeau de trollbane","où se trouve le tombeau","emplacement du sanctuaire"}},{q="Qu’arrive-t-il au glyphe dans le tombeau ?",a="Un éclair de lumière consume le Glyphe d’Ignaeus lorsque ses lignes sont alignées sur les gravures du tombeau.",al={"glyphe consumé","qu’arrive-t-il au glyphe","éclair dans le tombeau"}}},fp="16,139,17.256.0,19.155.1,29.126.0,35.51.0,23.94.1,26.69.0,38.97.1"}
P.entries["item:sigil-of-strom"] = {n="Sigil of Strom",s="Le Sigil of Strom est l’un des sceaux qui protègent Trol'kalar dans le tombeau de Trollbane. Zengu de Trépas-d'Orgrim le cherche auprès du Syndicat, à Stromgarde.",h="Le Sigil of Strom est l’un des sceaux qui protègent Trol'kalar dans le tombeau de Trollbane.",kw={"trépas-d'orgrim","sigil of strom","stromgarde","syndicat","trol'kalar","tueur de trolls","trollbane","zengu"},sec={{t="Un sigil de Stromgarde",b="Le Syndicat a pris l’un des sigils qui protègent Trol'kalar, l’ancienne épée tueuse de trolls. Zengu de Trépas-d'Orgrim en a besoin pour commencer à rassembler les sceaux qui protègent la lame dans le tombeau de Trollbane."}},faq={{q="Qu’est-ce que le Sigil of Strom ?",a="Le Sigil of Strom est l’un des nombreux sceaux qui protègent Trol'kalar dans le tombeau de Trollbane.",al={"signification du sigil de strom","sigil de strom","qu’est-ce que le sigil"}},{q="Qui cherche le Sigil of Strom ?",a="Zengu, à Trépas-d'Orgrim, cherche le Sigil of Strom pour commencer à rassembler les sceaux qui protègent Trol'kalar.",al={"qui a besoin du sigil","sigil de zengu","qui le cherche"}},{q="Où trouver le Sigil of Strom ?",a="Le Syndicat a pris le Sigil of Strom, et l’un de ses agents à Stromgarde le porte.",al={"emplacement du sigil","où trouver le sigil de strom","trouver le sigil"}},{q="Pourquoi Zengu a-t-il besoin du sigil ?",a="Le sigil est l’un des nombreux sceaux dont Zengu a besoin pour retirer Trol'kalar du tombeau de Trollbane.",al={"pourquoi récupérer le sigil","pourquoi zengu le veut","sceaux de trolkalar"}},{q="Qu’est-ce que Trol'kalar ?",a="Trol'kalar est une ancienne épée dont le nom signifie « tueuse de trolls » dans la langue des trolls. Lord Ignaeus of Strom, surnommé Trollbane, la maniait au combat.",al={"épée trolkalar","tueur de trolls","signification de trolkalar"}}},fp="14,145,18.204.0,27.85.0,29.98.0,36.86.0,30.89.1,19.146.0"}
P.entries["item:sigil-of-the-hammer"] = {n="Glyphe du Marteau",s="Le Glyphe du Marteau permet d'approcher les érudits qui possèdent le Sommaire de Yagyin. Il ouvre la voie à un savoir recherché pour se protéger.",h="Le Glyphe du Marteau permet d'approcher les érudits qui possèdent le Sommaire de Yagyin.",kw={"forlorn cavern","gerrig poigne-d'os","glyphe du marteau","forgefer","gardien bel'dugur","fossoyeuse","sommaire de yagyin"},sec={{t="Un signe de savoir",b="Une tablette indique la voie vers un ouvrage rédigé par Yagyin, le Sommaire de Yagyin. Le Glyphe du Marteau est le signe qui permet d'y accéder. À Forgefer, Gerrig Poigne-d'os tient boutique dans la Forlorn Cavern. À Fossoyeuse, le Gardien Bel'dugur veille sur une collection de livres. Présentez le glyphe à l'un ou l'autre érudit et demandez le sommaire."}},faq={{q="À quoi sert le Glyphe du Marteau ?",a="Le Glyphe du Marteau permet aux érudits de reconnaître son porteur, qui peut leur demander le Sommaire de Yagyin.",al={"utilisation du glyphe","utilité du glyphe du marteau"}},{q="À qui dois-je montrer le glyphe ?",a="Montrez le Glyphe du Marteau à Gerrig Poigne-d'os, à Forgefer, ou au Gardien Bel'dugur, à Fossoyeuse.",al={"à qui donner le glyphe","destinataire du glyphe"}},{q="Où se trouve Gerrig Poigne-d'os ?",a="Gerrig Poigne-d'os tient boutique dans la Forlorn Cavern de Forgefer.",al={"emplacement de gerrig","boutique de gerrig"}},{q="Où se trouve le Gardien Bel'dugur ?",a="Le Gardien Bel'dugur se trouve à Fossoyeuse, où il veille sur une collection de livres.",al={"emplacement de bel'dugur","érudit de fossoyeuse"}},{q="Pourquoi le sommaire est-il important ?",a="Le sommaire renferme un savoir recherché pour protéger ceux qui le convoitent.",al={"pourquoi le sommaire de yagyin","importance du sommaire"}}},fp="19,139,18.303.0,36.95.0,27.98.0,25.64.0,26.75.0,27.63.0"}
P.entries["item:sigil-of-thoradin"] = {n="Sigil of Thoradin",s="Le Sigil of Thoradin est un sceau restauré lié à la tombe de Trollbane, dans les Hautes-terres Arathies. Zengu, à Trépas-d'Orgrim, en a besoin pour ouvrir la tombe.",h="Le Sigil of Thoradin est un sceau restauré lié à la tombe de Trollbane, dans les Hautes-terres Arathies.",kw={"arathi","trépas-d'orgrim","sigil of thoradin","thoradin","tombe","trol'kalar","trollbane","zengu"},sec={{t="Un sceau restauré",b="Zengu, à Trépas-d'Orgrim, a besoin du Sigil of Thoradin pour aider à déverrouiller le sceau de la tombe de Trollbane. Sa reconstitution a réussi, et les travaux pour atteindre Trol'kalar peuvent se poursuivre. Zengu affirme que les recherches ne sont qu'à mi-parcours ; les détenteurs du troisième sceau se déplacent dans Arathi."}},faq={{q="Qu’ouvre le Sigil of Thoradin ?",a="Le Sigil of Thoradin restauré peut aider à déverrouiller le sceau de la tombe de Trollbane.",al={"qu’ouvre le sceau","sceau de la tombe"}},{q="Qui a besoin du sceau ?",a="Zengu, à Trépas-d'Orgrim, a besoin du Sigil of Thoradin restauré.",al={"qui veut le sceau","à qui donner le sceau"}},{q="Pourquoi le sceau est-il important ?",a="Il est nécessaire pour aider à retirer Trol'kalar de la tombe de Trollbane.",al={"importance du sceau","but du sceau"}},{q="Où se trouve le troisième sceau ?",a="Zengu ignore où se trouve le troisième sceau ; ses détenteurs se déplacent dans Arathi.",al={"emplacement du troisième sceau","où se trouve le troisième"}}},fp="17,138,15.265.0,37.76.0,20.57.0,27.61.1,25.77.0"}
P.entries["item:sigil-of-trollbane"] = {n="Sigil of Trollbane",s="Prince Galen Trollbane garde le Sigil of Trollbane dans Stromgarde. Zengu, à Trépas-d'Orgrim, le recherche, et vous devez affronter le prince pour le récupérer.",h="Prince Galen Trollbane garde le Sigil of Trollbane dans Stromgarde.",kw={"galen trollbane","prince galen","sigil of trollbane","stromgarde","thoras trollbane","trol'kalar","trollbane","zengu"},ang={["class:Warrior"]="En tant que guerrier, vous trouverez peut-être en Prince Galen un gardien tout indiqué pour le dernier sceau ; c'est lui-même un combattant chevronné."},sec={{t="Le dernier sceau",b="Zengu, à Trépas-d'Orgrim, recherche le dernier sceau, que Prince Galen Trollbane garde dans Stromgarde. Galen vit dans une chapelle du quartier tenu par la milice et est bien protégé. Apportez le sceau à Zengu, et la voie vers la tombe de Thoras Trollbane pourra être ouverte."}},faq={{q="À quoi sert le Sigil of Trollbane ?",a="Le Sigil of Trollbane est le dernier sceau nécessaire pour ouvrir la tombe de Thoras Trollbane et récupérer Trol’kalar.",al={"utilité du sceau","pourquoi avoir besoin du sceau","sceau de trollbane"}},{q="Qui détient le Sigil of Trollbane ?",a="Prince Galen Trollbane détient le Sigil of Trollbane dans Stromgarde.",al={"qui le détient","détenteur du sceau","sceau galen"}},{q="Où trouver Prince Galen ?",a="Prince Galen réside dans une chapelle du quartier de Stromgarde tenu par la milice.",al={"où est galen","emplacement de galen","trouver prince trollbane"}},{q="Qui veut le sceau ?",a="Zengu, à Trépas-d'Orgrim, recherche le Sigil of Trollbane.",al={"qui le veut","sceau pour zengu","sceau à trépas-d'orgrim"}},{q="Que se passe-t-il une fois les sceaux réunis ?",a="Une fois les sceaux en sa possession, Zengu prévoit de s'en prendre aux trolls de Zul’Gurub et de prendre Trol’kalar dans la tombe de Thoras Trollbane.",al={"que faire après les sceaux","suite de trolkalar","ouvrir la tombe"}}},fp="18,142,14.244.0,35.106.2,31.66.0,30.76.0,20.49.0,41.134.1"}
P.entries["item:sign-of-the-earth"] = {n="Signe de la Terre",s="Le Signe de la Terre est un sceau forgé par les Sombrefers, recherché dans les Terres Ingrates. Il ouvre une prison dans le Ravin de Lethlor.",h="Le Signe de la Terre est un sceau forgé par les Sombrefers, recherché dans les Terres Ingrates.",kw={"forteresse d'angor","terres ingrates","blacklash","aile de mort","garek","gorn","hematus","ravin de lethlor","signe de la terre","tho'grun"},ang={["class:Mage"]="En tant que mage, vous connaissez peut-être Krasus, un maître du Kirin Tor. Il a envoyé Garek dans les Terres Ingrates pour mettre fin aux troubles qui couvent dans le Ravin de Lethlor.",["faction:Horde"]="En tant que membre de la Horde, le Signe vous rappelle l’ancienne alliance avec Aile de mort pendant la Seconde guerre. Gorn le cherche pour libérer Blacklash et Hematus, même s’il les voue à leur perte."},sec={{t="Un sceau volé",b="Garek, envoyé dans les Terres Ingrates par Krasus du Kirin Tor, vous demande de récupérer le Signe de la Terre. Des ogres errants l’ont pris et passent près du Camp Boff. Des nains Sombrefer l’ont forgé à la Forteresse d’Angor. Il retient deux prisonniers dans le Ravin de Lethlor."},{t="La clé de la prison",b="À Kargath, Gorn vous raconte que la Horde s’est autrefois alliée à Aile de mort pendant la Seconde guerre. Tho'grun et ses ogres furent engagés pour obtenir le Signe, mais Tho'grun trahit la Horde et le garda. Une fois le sceau récupéré, Gorn compte ouvrir la prison des drakes et les libérer pour les mener à leur perte."}},faq={{q="Qu’est-ce que le Signe de la Terre ?",a="Le Signe de la Terre est un sceau forgé par les nains Sombrefer à la Forteresse d’Angor. Il retient Blacklash et Hematus dans le Ravin de Lethlor.",al={"signe de la terre","signe de terre","qu’est-ce que le signe"}},{q="Qui veut le Signe de la Terre ?",a="Garek, envoyé par Krasus du Kirin Tor, vous demande de récupérer le Signe. Gorn, à Kargath, le cherche aussi pour la Horde.",al={"qui veut le signe","signe garek","signe gorn"}},{q="Qui a volé le Signe ?",a="Une bande d’ogres errants a pris le Signe de la Terre. Leur chef, Tho'grun, l’a gardé après avoir trahi la Horde.",al={"qui a le signe","signe tho'grun","les ogres l’ont volé"}},{q="Que permet d’ouvrir le Signe ?",a="Le Signe de la Terre est la clé de la prison qui retient les drakes noirs Blacklash et Hematus dans le Ravin de Lethlor.",al={"clé de la prison du signe","qu’ouvre-t-il","prison des drakes noirs"}},{q="Où trouver le Signe ?",a="Les ogres errants traversent parfois le Camp Boff, dans les Terres Ingrates. Tho'grun pourrait s’y trouver.",al={"emplacement du signe","où trouver le signe de la terre","signe camp boff"}}},fp="17,118,13.251.0,16.281.1,30.130.0,32.115.0,19.112.1,26.112.0,26.100.0"}
P.entries["item:signed-recruitment-letter"] = {n="Lettre de recrutement signée",s="Du Poste de garde extérieur, Kargal Balafre-glorieuse envoie vers l’ouest une lettre signée et des recrues prêtes au service. Elle leur ordonne de se présenter à Sergra Darkthorn à la Croisée.",h="Du Poste de garde extérieur, Kargal Balafre-glorieuse envoie vers l’ouest une lettre signée et des recrues...",kw={"conscription","la croisée","poste de garde extérieur","kargal balafre-glorieuse","sergra darkthorn","lettre de recrutement signée","les tarides","thrall"},ang={["class:Shaman"]="En tant que chamane, vous rendez compte à Sergra Darkthorn, une chamane orque à qui Thrall a confié la défense des Tarides.",["faction:Horde"]="En tant que membre de la Horde, vous transportez cette lettre depuis votre service de base à Durotar jusqu’aux forces de la Horde déployées sur une frontière plus vaste."},sec={{t="Transfert d’un conscrit",b="À l’est du Fleuve Furie-du-Sud, Kargal Balafre-glorieuse prépare les recrues du Poste de garde extérieur à servir dans les Tarides. Le poste se trouve là où les nouveaux venus traversent le fleuve depuis Durotar. Quand un conscrit se montre prêt, Kargal tamponne et signe une lettre d’introduction. Les ordres envoient les recrues vers l’ouest, le long de la route jusqu’à la Croisée, où Sergra Darkthorn coordonne les approvisionnements et la défense des plaines arides."},{t="Tensions aux avant-postes",b="Les ordres de Kargal trahissent son mépris pour l’officière qui attend la recrue. Il qualifie Sergra Darkthorn de chamane acerbe qui parle en rond aux soldats. Kargal remet ouvertement en question la haute estime que le chef de guerre Thrall lui porte. Malgré tout, la dépêche doit parvenir à Sergra avant que d’autres affectations soient accordées à la Croisée."}},faq={{q="À quoi sert la Lettre de recrutement signée ?",a="La Lettre de recrutement signée vous transfère du Poste de garde extérieur, où sert Kargal Balafre-glorieuse, vers un poste dans les Tarides. Elle prouve à Sergra Darkthorn, à la Croisée, que Kargal vous estime prêt.",al={"à quoi sert cette lettre","utilisation de la lettre de recrutement","lettre signée des tarides"}},{q="Qui a signé la lettre ?",a="Kargal Balafre-glorieuse signe la lettre. Ce vétéran orc dirige le Poste de garde extérieur, à la frontière entre Durotar et les Tarides. Il signe après qu’une recrue a accompli ses premières tâches sur place.",al={"qui a écrit la lettre","lettre de kargal","qui a signé cette lettre"}},{q="À qui dois-je remettre la lettre ?",a="Vous remettez la lettre à Sergra Darkthorn, une influente chamane orque en poste au croisement central de la Croisée.",al={"où remettre la lettre","qui reçoit la lettre","destinataire de la lettre"}},{q="Pourquoi Kargal parle-t-il mal de Sergra Darkthorn ?",a="Kargal trouve Sergra acerbe et difficile, et pense qu’elle perd son temps à parler quand il faut agir. Le chef de guerre Thrall la tient en haute estime, mais Kargal doute de ses talents de dirigeante.",al={"rivalité entre kargal et sergra","pourquoi kargal déteste sergra"}}},fx={ea3ee62a={q="Qu'est-ce que la Lettre de recrutement signée ?",a="Il s'agit d'un document officiel de conscription de la Horde remis aux recrues arrivant dans Les Tarides depuis le Durotar. Rédigé et approuvé par Kargal Balafre-glorieuse au Poste de garde extérieur, il sert de certification formelle indiquant que vous avez été contrôlé, enrôlé et envoyé pour aider la colonie à La Croisée.",al={"qu'est-ce que la lettre de recrutement signée","lettre de recrutement","qu'est-ce que cette lettre"}},ea22ddb8={q="Pourquoi Sergra Darkthorn veut-elle la Lettre de recrutement signée ?",a="Sergra Darkthorn supervise les opérations à La Croisée et compte sur l'arrivée de main-d'œuvre pour sécuriser Les Tarides pour la Horde. La lettre confirme votre enrôlement sous l'autorité de Kargal, prouvant que vous êtes prêt à recevoir des ordres, à faire vos preuves, et à vous attaquer au travail pénible et aux menaces auxquels fait face la colonie.",al={"pourquoi sergra veut-elle la lettre","pourquoi livrer la lettre de recrutement","qui a besoin de la lettre de recrutement"}}},fp="25,164,22.389.0,23.320.0,53.190.0,22.183.0,31.120.0,49.182.0"}
P.entries["item:silithid-egg-the-barrens"] = {n="Oeuf de silithide",s="Dans le Champ des Géants, des Oeufs de silithide sont enfouis sous la terre. Des chercheurs de la Horde les recueillent pour étudier l’essaim qui se répand dans le sud des Tarides.",h="Dans le Champ des Géants, des Oeufs de silithide sont enfouis sous la terre.",kw={"la croisée","griffe d'excavation","egg hunt","champ des géants","korran","monticules","silithides","oeuf de silithide","les tarides"},ang={["faction:Horde"]="Pour la Horde, des essaims d’insectes intelligents près de La Croisée menacent les routes commerciales et le territoire au centre de Kalimdor."},sec={{t="Un essaim mystérieux",b="Des monticules de silithides s’élèvent dans le Champ des Géants tandis que d’étranges créatures insectoïdes remuent la terre. Leurs œufs reposent sous la terre durcie, gardés par des silithides territoriaux. La Horde en sait peu sur eux, mais les éclaireurs de La Croisée ont observé des signes de coordination et d’intelligence dépassant celles des bêtes sauvages ordinaires. Des œufs non éclos pourraient aider les érudits d’Orgrimmar à découvrir le cycle de vie et la nature des silithides."},{t="Excavation et danger",b="Une griffe d’excavation adaptée est nécessaire pour extraire les Oeufs de silithide des monticules. Ces créatures défendent farouchement leurs pouponnières souterraines et submergent quiconque menace leurs petits non éclos. Korran, un chercheur troll, a besoin de spécimens intacts pour les étudier avant que l’essaim ne se répande davantage dans Kalimdor."}},faq={{q="Que sont les Oeufs de silithide ?",a="Les Oeufs de silithide sont des couvées non écloses enfouies dans des monticules de terre au sud des Tarides, surtout autour du Champ des Géants.",al={"oeuf de silithide","qu’est-ce qu’un oeuf de silithide","monticules de silithides"}},{q="Qui veut que ces œufs soient recueillis ?",a="Korran, un chercheur troll de La Croisée, recueille les œufs pour ses maîtres à Orgrimmar. Ils veulent étudier la biologie et le comportement des silithides.",al={"qui a besoin des oeufs","quête de korran","donneur de quête de la chasse aux oeufs"}},{q="Pourquoi étudie-t-on les silithides ?",a="La Horde en sait peu sur les silithides. Korran a observé des signes d’intelligence et de coordination dépassant celles des animaux sauvages ordinaires. Leur apparition dans les Tarides inquiète les chefs de la Horde.",al={"pourquoi étudier les silithides","menace des silithides","les silithides sont-ils intelligents"}},{q="Comment recueille-t-on les œufs ?",a="Une griffe d’excavation adaptée permet d’extraire les œufs des monticules de silithides. L’essaim agressif défend ses nids.",al={"comment obtenir les oeufs","griffe d'excavation","récolter des oeufs de silithide"}}},fx={["04f05afd"]={q="D'où viennent les oeufs de silithide ?",a="Ces oeufs sont pondus par les étranges silithides insectoïdes au plus profond de leurs tertres de terre dans les Tarides du sud, et plus particulièrement dans tout le Champ des Géants. Les silithides enterrent et gardent soigneusement leurs couvées à l'intérieur de ces monticules de terre imposants, attaquant férocement quiconque ose déranger les nids.",al={"origine oeuf de silithide","d'où viennent les oeufs de silithide","qui a pondu les oeufs de silithide"}}},fp="12,168,18.405.0,21.294.0,23.125.0,31.142.0,35.191.0,26.96.0"}
P.entries["item:silixiz-s-tower-key"] = {n="Clé de la tour de Silixiz",s="Dans la tour de KapitalRisk, près de la Videfange, Foreman Silixiz porte la Clé de la tour de Silixiz dans sa poche. Un agent de Shattered Hand doit la dérober sans être vu lors d’une mission secrète de sabotage.",h="Dans la tour de KapitalRisk, près de la Videfange, Foreman Silixiz porte la Clé de la tour de Silixiz dans sa...",kw={"tarides","foreman silixiz","shattered hand","shenthul","silixiz","la videfange","clé de la tour","kapitalrisk"},ang={["class:Rogue"]="En tant que voleur de la Horde, vous obtenez la Clé de la tour de Silixiz comme épreuve pour rejoindre Shattered Hand. Le test exige de la discrétion et du talent pour faire les poches.",["faction:Horde"]="En tant que membre de la Horde, vous rapportez un trophée de la lutte contre l’exploitation et les expériences chimiques de KapitalRisk dans le nord des Tarides."},sec={{t="Une épreuve de discrétion",b="Au nord de la Videfange, KapitalRisk surveille étroitement sa tour. Grand Foreman Puzik Gallywix supervise le poste de guet isolé, tandis que des mercenaires gobelins patrouillent dans l’enceinte. Foreman Silixiz porte la clé de la tour à l’extérieur.\n\nUn agent de Shattered Hand venu d’Orgrimmar doit voler la clé et la conserver. La force ne servira à rien. L’agent doit entrer sans être vu et faire les poches de Silixiz, prouvant sa discrétion avant de gravir les niveaux toxiques de la tour."}},faq={{q="Où trouver Foreman Silixiz ?",a="Foreman Silixiz se trouve à l’extérieur de la tour de KapitalRisk, directement au nord de la Videfange, dans le nord-est des Tarides.",al={"emplacement de silixiz","où trouver foreman silixiz","trouver silixiz"}},{q="Puis-je obtenir la clé en tuant Foreman Silixiz ?",a="Non. Il est impossible de prendre la clé sur le cadavre de Silixiz. Un agent doit faire les poches de Silixiz de son vivant.",al={"butin de la clé de silixiz","peut-on tuer silixiz","récupérer la clé de silixiz"}},{q="Qui a besoin de cette clé ?",a="Les contacts de Shattered Hand demandent que la clé soit remise à Shenthul, l’entraîneur des voleurs à Orgrimmar.",al={"qui veut la clé","remettre la clé de silixiz","quête de la clé de la tour de silixiz"}},{q="À quoi sert cette clé ?",a="La clé prouve qu’un agent est entré dans la tour de KapitalRisk, près de la Videfange. Elle est remise à Shattered Hand avec la tête de Grand Foreman Puzik Gallywix et le Cache de mixture altérée de Zanzil.",al={"que déverrouille la clé de silixiz","utilité de la clé de silixiz","utiliser la clé de la tour"}}},fx={["163c94d7"]={q="Qu'est-ce que la Clé de la tour de Silixiz ?",a="Il s'agit d'une clé détenue par le contremaître Silixiz à l'extérieur de la tour de la KapitalRisk au nord de La Videfange. L'agent est chargé de la voler et de la conserver au cas où le contact de la Main brisée en aurait besoin plus tard.",al={"qu'est-ce que la clé de la tour de silixiz","clé de silixiz","clé de la tour kapitalrisk"}}},fp="19,195,18.451.0,32.115.0,48.103.0,22.94.0,25.198.1"}
P.entries["item:silver-dawning-s-lockbox"] = {n="Coffret de l'Aube argentée",s="Au large de Sombrivage, le Coffret de l'Aube argentée repose dans une épave au nord d'Auberdine. Des murlocs côtiers ont coulé le navire, et le coffret contient les effets personnels de son capitaine et le journal de bord.",h="Au large de Sombrivage, le Coffret de l'Aube argentée repose dans une épave au nord d'Auberdine.",kw={"auberdine","sombrivage","gorbold main-d'acier","coffret","murloc","épave","silver dawning"},ang={["race:Dwarf"]="Gorbold Main-d'acier se charge d'honorer les capitaines disparus et de rendre leurs effets personnels à leurs compagnons survivants.",["race:NightElf"]="Le coffret renferme les derniers écrits et les effets personnels d'un capitaine kaldorei mort en défendant son navire au large des côtes du nord de Kalimdor."},sec={{t="Vestiges engloutis",b="Le Silver Dawning faisait route vers Auberdine lorsque des murlocs côtiers l'ont attaqué. Ils ont entraîné le navire sous les flots, au nord du port, et le capitaine a péri dans l'assaut. La coque inondée abrite encore le coffret du capitaine, avec le journal de bord et ses effets personnels. Les récupérer pourrait apporter un peu de réconfort aux membres d'équipage survivants sur le rivage."}},faq={{q="Où se trouve le Coffret de l'Aube argentée ?",a="Le coffret repose dans l'épave immergée du Silver Dawning, au fond de l'océan, au nord d'Auberdine, au large de Sombrivage.",al={"emplacement du coffret","où se trouve le coffret du silver dawning","épave du silver dawning"}},{q="Qu'est-il arrivé au Silver Dawning ?",a="Des murlocs côtiers ont attaqué le Silver Dawning alors qu'il faisait route vers Auberdine. Ils ont submergé le navire, qui a sombré avec son capitaine.",al={"pourquoi le silver dawning a sombré","histoire du silver dawning","comment le navire a fait naufrage"}},{q="Que contient le coffret ?",a="Le coffret contient les effets personnels du capitaine du Silver Dawning et son journal de bord.",al={"contenu du silver dawning","que contient le coffret"}},{q="Qui cherche le coffret ?",a="Gorbold Main-d'acier, un nain en poste à Auberdine, demande à des nageurs de récupérer le coffret dans les épaves afin que les membres d'équipage survivants puissent honorer la mémoire du capitaine disparu.",al={"qui cherche le coffret","qui donne la quête","rendre le coffret"}}},fx={["9cc39920"]={q="Qu'est-ce que le Coffret de l'Aube argentée ?",a="Il s'agit du coffre personnel appartenant au défunt capitaine de l'Aube argentée. Lorsque le navire a été envahi et coulé par des murlocs au large de la côte nord de Sombrivage, le coffret a sombré avec l'épave. Il contient le journal du capitaine et ses effets personnels survivants, reposant au fond de l'eau au milieu des créatures rôdeuses.",al={"qu'est-ce que le coffret de l'aube argentée","histoire du coffre de l'aube argentée","coffret du capitaine aube argentée"}}},fp="24,179,15.344.0,46.130.0,36.149.0,27.76.0,27.167.0"}
P.entries["item:silvermane-stalker-flank"] = {n="Silvermane Stalker Flank",s="Les Silvermane Stalker Flanks sont de la viande crue qu’Agnar Beastamer cherche dans les Hinterlands. Il en a besoin pour nourrir un bébé Fée fléchetteuse.",h="Les Silvermane Stalker Flanks sont de la viande crue qu’Agnar Beastamer cherche dans les Hinterlands.",kw={"agn ar beastamer","agnarbeastamer","nourriture pour bébé","hinterlands","viande crue","silvermane stalker","silvermane stalker flank","fée fléchetteuse"},sec={{t="Premier repas",b="Agnar Beastamer se prépare à l’éclosion de l’œuf et craint que la jeune Fée fléchetteuse ne survive pas sans un bon premier repas. Il vous demande de rapporter cinq Silvermane Stalker Flanks. La viande est destinée au bébé à sa naissance."}},faq={{q="Qui a besoin de Silvermane Stalker Flanks ?",a="Agnar Beastamer, dans les Hinterlands, a besoin de cinq Silvermane Stalker Flanks pour nourrir un bébé Fée fléchetteuse.",al={"qui a besoin des flancs","viande d’agnar","qui veut cette viande"}},{q="À quoi servent ces flancs ?",a="Agnar prévoit de donner cette viande crue à une Fée fléchetteuse lorsque son œuf éclora.",al={"pourquoi cette viande","nourriture pour bébé fée","à quoi sert ce flanc"}},{q="De combien de flancs Agnar a-t-il besoin ?",a="Agnar Beastamer vous demande de rapporter cinq Silvermane Stalker Flanks.",al={"combien de morceaux","cinq flancs","quantité de viande"}},{q="Où trouver des Silvermane Stalker Flanks ?",a="Les Silvermane Stalker Flanks proviennent des Silvermane Stalkers des Hinterlands.",al={"où trouver des flancs","viande de traqueur","origine des flancs silvermane"}},{q="Que mange une Fée fléchetteuse ?",a="Les Fées flécheteuses mangent de la viande et des végétaux. Agnar demande des Silvermane Stalker Flanks crus pour le premier repas du bébé.",al={"régime de la fée fléchetteuse","que mangent les fées flécheteuses","nourriture pour bébé dragon"}}},fp="24,129,12.235.0,36.106.0,24.73.0,32.65.0,45.75.0,30.124.0"}
P.entries["item:silvery-spinnerets"] = {n="Filières d'argent",s="Près du Lac d’Aigue-vive, les Filières d’argent sont recherchées pour un rite en l’honneur de Dame Sathrah. Ses toiles d’argent recueillaient jadis la rosée guérisseuse du soir pour The Sisterhood of Elune à Darnassus.",h="Près du Lac d’Aigue-vive, les Filières d’argent sont recherchées pour un rite en l’honneur de Dame Sathrah.",kw={"dame sathrah","prêtresse a'moora","sacrifice de sathrah","filières d'argent","tears of the moon","temple de la lune","lac d'aigue-vive"},ang={["class:Priest"]="Pour les serviteurs d’Elune, récupérer les filières est un rite funéraire sacré. Ils demandent à la Mère Lune de racheter une créature plutôt que de considérer sa mort comme une simple extermination.",["race:NightElf"]="La fin tragique de Dame Sathrah rappelle aux Kaldorei que même les créatures chéries d’Elune peuvent succomber au fléau qui rend Teldrassil malade."},sec={{t="Toiles sacrées et corruption",b="Au clair de lune, près du Lac d’Aigue-vive, Dame Sathrah tissait des toiles chatoyantes. Sa soie d’argent recueillait la brume du soir pour en faire une rosée guérisseuse, très prisée par The Sisterhood of Elune à Darnassus.\n\nPuis la corruption l’atteignit sur Teldrassil et la plongea dans une violente folie. Sathrah menaçait sa couvée et la forêt alentour. La Prêtresse A'moora demande aux voyageurs de mettre fin à ses souffrances et de récupérer ses filières, par miséricorde pour une créature jadis vénérée des grands branchages."},{t="Un sacrifice pour renaître",b="The Sisterhood offre les filières récupérées à Elune, à la fontaine centrale du Temple de la Lune. Lors du rite appelé Sacrifice de Sathrah, les prêtresses prient la Déesse de la Lune d’accueillir l’esprit de la créature. Elles lui demandent de purifier la folie qui s’est emparée du corps mortel de Sathrah et de lui accorder la paix dans la renaissance."}},faq={{q="Où trouver les Filières d’argent ?",a="Récupérez les Filières d’argent sur Dame Sathrah, une grande araignée près du Lac d’Aigue-vive, aux frontières nord de Teldrassil.",al={"où trouver les filières d’argent","butin des filières d’argent","qui donne les filières d’argent"}},{q="Pourquoi la Prêtresse A'moora veut-elle les filières ?",a="La Prêtresse A'moora cherche les filières pour un sacrifice sacré à Elune. Ce rite honore la pureté passée de Dame Sathrah et demande à la déesse de purifier son esprit et de lui accorder la paix et la renaissance.",al={"pourquoi amoora veut les filières","utilité des larmes de la lune"}},{q="Pourquoi les toiles de Dame Sathrah étaient-elles si particulières ?",a="Dame Sathrah tissait une soie d’argent lumineuse qui capturait la brume du soir au clair de lune. La rosée possédait une puissante magie réparatrice, et The Sisterhood of Elune la conservait avec soin dans le Temple de la Lune pour soigner les blessés.",al={"toiles de dame sathrah","qu’a fait dame sathrah"}},{q="Pourquoi tuer Dame Sathrah si elle était sacrée ?",a="La corruption plongea Dame Sathrah dans une folie incurable, comme d’autres animaux de Teldrassil. Son agressivité mettait la forêt en danger et menaçait sa couvée ; les prêtresses jugèrent donc que la tuer était un acte de miséricorde douloureux.",al={"pourquoi tuer dame sathrah","pourquoi sathrah est devenue folle"}}},fx={["6e94bdc8"]={q="Qu'est-ce que les Filières d'argent ?",a="Les Filières d'argent sont les organes producteurs de soie prélevés sur l'araignée sacrée Dame Sathrah dans le nord de Teldrassil. À des époques plus saines, elle les utilisait pour tisser des fils d'argent chatoyants à la lumière de la lune. Ces toiles capturaient la brume du soir, produisant une rosée miraculeuse aux puissantes propriétés curatives chérie par les prêtresses d'Elune.",al={"qu'est-ce que les filières d'argent","info sur les filières d'argent","filières de dame sathrah"}},["48fdca9c"]={q="D'où viennent les Filières d'argent ?",a="Elles sont récoltées sur Dame Sathrah, une araignée géante vivant près du Lac d'Aigue-vive le long des frontières nord de Teldrassil. Autrefois vénérée comme une créature gracieuse et pure bénie par Elune, Sathrah a récemment succombé à la folie, obligeant les elfes de la nuit à mettre fin à ses souffrances et à récupérer ses restes sacrés.",al={"origine des filières d'argent","qui a créé les filières d'argent","où obtenir les filières d'argent"}}},fp="18,177,29.453.0,23.332.1,40.123.0,47.192.0,37.213.0,46.220.0"}
P.entries["item:simple-memorandum"] = {n="Note de service simple",s="Dans la Vallée des Frigères, les guerriers gnomes novices partent s’entraîner auprès de Thran Khorman, à Courbenclume. Ils se préparent à reprendre Gnomeregan.",h="Dans la Vallée des Frigères, les guerriers gnomes novices partent s’entraîner auprès de Thran Khorman, à...",kw={"courbenclume","vallée des frigères","dun morogh","gnomeregan","note de service simple","thran khorman","entraînement de guerrier"},ang={["class:Warrior"]="En tant que guerrier, vous commencez votre entraînement au combat auprès de Thran Khorman, à Courbenclume. Vous dépassez les escarmouches rudimentaires.",["race:Gnome"]="En tant que gnome exilé, vous partagez l’objectif d’aiguiser vos talents au combat aux côtés de vos alliés nains. Vous vous préparez à libérer Gnomeregan."},sec={{t="Un appel à Courbenclume",b="Dans la Vallée des Frigères, de jeunes combattants gnomes affrontent la faune et les troggs, munis de lettres de recommandation. La Note de service simple les dirige vers Thran Khorman, le maître d’armes de Courbenclume.\n\nLes gnomes mettent leur intelligence et leurs inventions au service du combat. Mais reprendre Gnomeregan exige de la force et de la discipline martiale. La note envoie son porteur au-delà de l’entraînement élémentaire, pour apprendre l’art de la guerre auprès de Thran."}},faq={{q="Qu’est-ce que la Note de service simple ?",a="La Note de service simple est un message écrit destiné aux guerriers gnomes novices de la Vallée des Frigères. Elle leur demande de se présenter auprès du maître d’armes nain de Courbenclume.",al={"note de service simple","qu’est-ce que cette note","objet note de service"}},{q="Qui a écrit la Note de service simple ?",a="La Note de service simple ne porte aucune signature. Sten Rudebras suppose que Thran Khorman l’a écrite, mais ses mots sur la reconquête de Gnomeregan en font une directive gnome. Elle vous ordonne de vous présenter auprès de Thran, le maître d’armes nain de Courbenclume.",al={"qui a écrit la note","qui a envoyé la note","auteur de la note de service simple"}},{q="Que faire après avoir lu la Note de service simple ?",a="Après avoir lu la Note de service simple, vous l’apportez à Thran Khorman, à Courbenclume. Il reconnaît votre détermination à reconquérir votre foyer perdu et vous propose de vous enseigner les bases du combat de guerrier.",al={"que faire de la note","où l’apporter","rendre la note de service simple"}},{q="Pourquoi un nain entraîne-t-il des guerriers gnomes ?",a="Un nain entraîne des guerriers gnomes parce que les réfugiés gnomes se sont installés à Forgefer et à Courbenclume après la chute de Gnomeregan. Des vétérans nains comme Thran Khorman mettent leur savoir martial au service de leurs alliés exilés, pour les aider à s’entraîner et à reprendre leur cité irradiée.",al={"pourquoi thran entraîne les gnomes","nains qui entraînent des gnomes"}}},fx={b027c55a={q="Pourquoi la Note de service simple m'a-t-elle été remise ?",a="La note de service est une directive gnomique vous ordonnant de vous présenter à Thran Khorman, l'instructeur des guerriers nains à l'intérieur de Courbenclume. En tant que guerrier gnome déplacé, votre directive première est de vous préparer à la guerre pour reprendre Gnomeregan, et Thran a donné sa parole pour vous aider, vous et votre peuple, à vous y préparer. Sten Rudebras vous a transmis la note pendant que vous l'aidiez dans la Vallée des Frigères.",al={"pourquoi une note de service simple","utilité de la note de service simple","pourquoi ai-je besoin de la note de service simple"}}},fp="17,142,21.407.0,30.159.0,32.237.0,49.185.0,39.244.0"}
P.entries["item:simple-rune"] = {n="Rune simple",s="Dans la Vallée des Frigères, Thran Khorman envoie les jeunes guerriers nains prometteurs à Courbenclume pour les former à la Rune simple.",h="Dans la Vallée des Frigères, Thran Khorman envoie les jeunes guerriers nains prometteurs à Courbenclume pour...",kw={"courbenclume","vallée des frigères","dun morogh","rune naine","rune simple","thran khorman","entraînement de guerrier"},ang={["class:Warrior"]="En tant que guerrier nain, la Rune simple marque votre premier pas vers une formation officielle auprès de Thran Khorman, un instructeur vétéran.",["race:Dwarf"]="En tant que nain, la rune de Thran Khorman vous enseigne les bases du combat : tenir une hache, porter une armure et suer au cœur d'une véritable bataille."},sec={{t="Une convocation aux armes",b="Les jeunes combattants qui ont commencé à débarrasser la Vallée des Frigères de ses menaces reçoivent la convocation officielle de Thran. Les marques martiales de la rune n'ont aucun pouvoir magique ; elles indiquent à chaque recrue de se présenter auprès de Thran, à Courbenclume. Là, il enseigne les rudiments du combat et donne des conseils pratiques pour survivre dans les étendues sauvages et hostiles de Dun Morogh."}},faq={{q="À quoi sert la Rune simple ?",a="La Rune simple indique aux recrues de venir recevoir une formation officielle auprès de Thran Khorman, à Courbenclume. Les jeunes guerriers de la Vallée des Frigères la reçoivent sous forme de tablette d'instruction.",al={"utilité de la rune simple","à quoi sert la rune","objet de quête rune simple"}},{q="Qui envoie la Rune simple ?",a="Thran Khorman envoie la Rune simple. Ce maître d'armes nain, installé à Courbenclume, repère les combattants prometteurs qui prêtent main-forte dans la vallée.",al={"qui a écrit la rune","qui m'a donné la rune simple","expéditeur de la rune"}},{q="Où dois-je apporter la Rune simple ?",a="Apportez la Rune simple à Thran Khorman, à Courbenclume, au centre de la Vallée des Frigères.",al={"où aller","remettre la rune","emplacement de thran khorman"}}},fx={["0f0eb9fb"]={q="Qu'est-ce que la Rune simple ?",a="La Rune simple est une pierre naine gravée transmise aux guerriers prometteurs dans la Vallée des Frigères. Plutôt que de porter des enchantements mystiques, elle fonctionne comme une convocation écrite de Thran Khorman, appelant les combattants novices à se présenter à lui à Courbenclume pour commencer leur entraînement martial formel.",al={"qu'est-ce que la rune simple","histoire de la rune simple","objet rune simple"}},["2d1fc984"]={q="Pourquoi Thran Khorman veut-il que vous ayez la Rune simple ?",a="Thran Khorman envoie la rune pour vous recruter dans une formation formelle de guerrier. Voyant du potentiel dans vos premiers exploits autour de la Vallée des Frigères, il souhaite vous ancrer dans la discipline martiale naine appropriée et vous apprendre ce qu'il faut vraiment pour se battre pour Forgefer face aux menaces locales croissantes.",al={"pourquoi thran envoie la rune","pourquoi ai-je besoin de la rune simple","pourquoi vouloir la rune simple"}}},fp="11,120,17.305.0,39.169.0,26.137.0,32.83.0"}
P.entries["item:simple-sigil"] = {n="Sceau simple",s="À Sombrevallon, un Sceau simple appelle les jeunes guerriers elfes de la nuit à s’entraîner avec Alyissia. Il marque leur premier pas dans la défense de Teldrassil.",h="À Sombrevallon, un Sceau simple appelle les jeunes guerriers elfes de la nuit à s’entraîner avec Alyissia.",kw={"alyissia","ilthalaine","guerrier kaldorei","sombrevallon","sceau simple","teldrassil","entraînement de guerrier"},ang={["class:Warrior"]="En tant que guerrier kaldorei, le Sceau simple marque votre premier pas dans les traditions martiales qui protègent Teldrassil.",["race:NightElf"]="En tant qu’elfe de la nuit, vous voyez l’urgence à laquelle les kaldorei font face. Alyissia et d’autres instructeurs recrutent des combattants capables de lutter contre la corruption grandissante dans les branches de l’Arbre-monde."},sec={{t="Un appel aux armes",b="À Sombrevallon, le Conservateur Ilthalaine guide les jeunes elfes de la nuit dans leur quête d’une vocation. Un messager apporte un Sceau simple d’Alyissia, l’instructrice des guerriers. Ilthalaine le remet aux guerriers novices, et son inscription indique à chaque recrue où se présenter pour recevoir des instructions. Leur entraînement martial commence alors que des temps troublés s’annoncent pour l’Arbre-monde."},{t="Le devoir de défense",b="Alyissia se sert du sceau pour expliquer aux recrues les besoins des kaldorei. Teldrassil a récemment grandi, la corruption se répand parmi les bêtes de la forêt, et la redécouverte de terres lointaines comme Féralas a dispersé les protecteurs elfes de la nuit. Le sceau n’a aucun pouvoir. Il accueille chaque recrue parmi les gardiens chargés de protéger leur peuple des menaces nouvelles."}},faq={{q="Qu’est-ce que le Sceau simple ?",a="Le Sceau simple est un jeton gravé destiné aux guerriers elfes de la nuit novices de Sombrevallon. Le Conservateur Ilthalaine le leur remet, et son inscription leur indique de se présenter auprès d’Alyissia pour s’entraîner.",al={"objet sceau simple","utilité du sceau simple","qu’est-ce que ce sceau"}},{q="Qui envoie le Sceau simple ?",a="Un messager apporte le Sceau simple d’Alyissia, l’instructrice des guerriers de Sombrevallon, au Conservateur Ilthalaine. Ilthalaine le remet aux guerriers novices.",al={"qui a créé le sceau","qui a envoyé le sceau simple"}},{q="Que dois-je en faire ?",a="Lisez l’inscription et apportez le Sceau simple à Alyissia, près de la base d’Aldrassil à Sombrevallon, pour commencer votre entraînement de guerrier.",al={"où remettre le sceau simple","à qui remettre le sceau simple"}},{q="Le sceau confère-t-il des pouvoirs particuliers ?",a="Non. Le Sceau simple est un avis écrit qui présente les aspirants guerriers à leur mentor.",al={"pouvoirs du sceau","caractéristiques du sceau simple"}}},fp="12,138,17.341.0,21.366.0,25.193.0,27.150.0,25.131.0,43.91.0"}
P.entries["item:simple-tablet"] = {n="Tablette simple",s="Dans la Vallée des épreuves, Gornek remet aux nouveaux guerriers trolls un message à transmettre à Frang.",h="Dans la Vallée des épreuves, Gornek remet aux nouveaux guerriers trolls un message à transmettre à Frang.",kw={"sombrelance","durotar","frang","gornek","tablette simple","l'antre","vallée des épreuves","maître des guerriers"},ang={["class:Warrior"]="En tant que guerrier, ce message vous présente à Frang pour votre entraînement au combat.",["race:Troll"]="En tant que troll Sombrelance en Durotar, cet appel vous invite à renforcer les rangs de première ligne de la Horde aux côtés des orcs."},sec={{t="Un appel au combat",b="Gornek remet aux nouveaux guerriers trolls un message de Tar'sere, destiné à Frang, le maître des guerriers près de l'Antre. Il présente la recrue à l'entraînement au combat en Durotar et lui demande de se présenter à Frang. Le message l'appelle à prendre les armes pour la Horde."}},faq={{q="Qu'est-ce que la Tablette simple ?",a="Dans la Vallée des épreuves, Gornek remet aux aspirants guerriers trolls un message qui les dirige vers Frang pour leur entraînement au combat.",al={"tablette simple","qu'est-ce que cette tablette","tablette de guerrier troll"}},{q="Qui envoie la tablette ?",a="Tar'sere signe le message et dirige la recrue vers Frang, le maître des guerriers à l'extérieur de l'Antre, dans la Vallée des épreuves.",al={"qui a envoyé la tablette simple","qui a écrit la tablette","expéditeur de la tablette"}},{q="Où dois-je apporter la tablette ?",a="Apportez la Tablette simple à Frang, qui se repose à l'extérieur de l'Antre, dans la Vallée des épreuves.",al={"à qui donner la tablette simple","où apporter la tablette","emplacement de frang"}},{q="Qui reçoit cette tablette ?",a="La Tablette simple est destinée aux guerriers trolls qui commencent leurs rites de passage dans la Vallée des épreuves.",al={"tout le monde peut-il obtenir la tablette simple","quelle classe reçoit la tablette simple"}}},fx={["219776b3"]={q="Pourquoi Frang vous envoie-t-il la Tablette simple ?",a="En réalité, Frang ne l'a pas écrite. Gornek suppose qu'elle vient de Frang, mais la tablette est signée par le troll Tar'sere, qui vous envoie auprès de Frang, à l'extérieur de l'Antre. Frang a besoin de guerriers trolls rusés pour montrer aux orcs comment se battre autrement que par la force brute, et il peut vous préparer aux batailles à venir de la Horde.",al={"pourquoi la tablette simple","pourquoi frang cherche des recrues","utilité de la tablette simple"}}},fp="13,85,19.269.0,26.116.0,21.121.0,27.83.0,25.98.0"}
P.entries["item:singed-scale"] = {n="Ecaille roussie",s="À Durotar, les guerriers rapportent une Écaille roussie prélevée sur les plaques calcinées des lézards-tonnerre électrifiés pour prouver leur endurance et apprendre à se défendre.",h="À Durotar, les guerriers rapportent une Écaille roussie prélevée sur les plaques calcinées des...",kw={"poste de garde extérieur","peau d’éclair","path of defense","ecaille roussie","lézard-tonnerre","falaises du tonnerre","uzzek"},ang={["class:Warrior"]="Pour un guerrier en formation, rapporter les écailles à Uzzek marque une étape essentielle dans l’apprentissage de la protection et de l’art de servir de bouclier impénétrable à la Horde.",["faction:Horde"]="Au Poste de garde extérieur, les épreuves garantissent que les gardes et les avant-gardes des frontières de Durotar et des Tarides possèdent une endurance inébranlable."},sec={{t="Un Test of Endurance",b="Les vétérans de la Horde jugent un guerrier aux coups qu’il endure en protégeant ses alliés. Les Falaises du Tonnerre sont un canyon de l’ouest de Durotar, où la foudre se dissimule et où les lézards-tonnerre crépitent d’énergie orageuse. Les chasser, c’est subir des décharges électriques incessantes et des coups écrasants. Leurs écailles noircies montrent qu’un combattant peut résister à de rudes assauts et tenir bon sous la pression."},{t="La voie du bouclier",b="Au Poste de garde extérieur, à la frontière entre Durotar et les Tarides, le guerrier vétéran Uzzek demande cinq écailles aux initiés avant de leur enseigner son art. Il estime qu’ils doivent d’abord acquérir une robustesse physique avant d’apprendre les postures et la défense tactique. Rapporter les écailles prouve qu’ils ont la ténacité nécessaire pour associer cuir épais, armure lourde et jeu de jambes calculé afin de former une défense solide contre les ennemis de la Horde."}},faq={{q="À quoi servent les écailles roussies ?",a="Les écailles roussies prouvent l’endurance au combat. Uzzek, un maître guerrier, en exige cinq avant d’enseigner des techniques défensives avancées à un initié.",al={"utilité de l’écaille roussie","qui demande des écailles roussies","quête de l’écaille roussie"}},{q="Où trouver des écailles roussies ?",a="Vous trouverez des écailles roussies sur les lézards-tonnerre et les peaux d’éclair, aux Falaises du Tonnerre, un canyon de l’ouest de Durotar, de l’autre côté de la rivière depuis les Tarides.",al={"emplacement de l’écaille roussie","où trouver des écailles roussies","comment obtenir une écaille roussie"}},{q="Pourquoi les écailles sont-elles roussies ?",a="Les lézards-tonnerre canalisent la foudre et les tempêtes électriques à travers leur corps. Le crépitement constant de l’énergie élémentaire brûle et noircit leur peau extérieure, donnant aux écailles leur texture calcinée.",al={"pourquoi roussie","pourquoi les écailles sont brûlées"}},{q="Qui est Uzzek et pourquoi ces écailles l’intéressent-elles ?",a="Uzzek est un guerrier vétéran au Poste de garde extérieur, dans l’est des Tarides. Il entraîne les aspirants guerriers de la Horde au combat défensif et leur demande d’abord de prouver leur résistance face à des bêtes mortelles.",al={"qui est uzzek","uzzek"}}},fx={c263d0cb={q="Qu'est-ce qu'une Écaille roussie ?",a="Une Écaille roussie est une écaille reptilienne robuste prélevée sur les féroces lézards du tonnerre et les peaux-de-foudre qui habitent les Falaises du Tonnerre. Crépitant constamment d'énergie électrique naturelle, ces créatures portent des plaques noircies et cicatrisées par leurs propres décharges violentes de foudre, laissant derrière elles une armure carbonisée mais remarquablement résistante.",al={"qu'est-ce qu'une écaille roussie","lore de l'écaille roussie","infos sur les écailles roussies"}}},fp="12,138,19.371.0,21.395.0,32.137.0,32.142.0,26.201.0,53.197.0"}
P.entries["item:singed-scroll-fragment"] = {n="Singed Scroll Fragment",s="Le Singed Scroll Fragment est l'un des trois morceaux d'un parchemin détruit que recherche Theldurin l'Egaré. Le retrouver pourrait aider à se prémunir contre Myzrael.",h="Le Singed Scroll Fragment est l'un des trois morceaux d'un parchemin détruit que recherche Theldurin l'Egaré.",kw={"terres ingrates","fragment de parchemin froissé","élémentaire de roche enragé","myzrael","parchemin de myzrael","singed scroll fragment","theldurin l'egaré","torn scroll fragment"},sec={{t="Un morceau calciné",b="Des élémentaires de roche enragés dans les collines derrière Theldurin l'Egaré portent le Singed Scroll Fragment. Il le recherche avec deux autres morceaux du Parchemin de Myzrael, dans l'espoir de réunir les fragments."}},faq={{q="Qu'est-ce que le Singed Scroll Fragment ?",a="C'est l'un des trois fragments du Parchemin de Myzrael détruit.",al={"fragment roussi","morceau de parchemin roussi"}},{q="D'où vient le fragment ?",a="Des élémentaires de roche enragés dans les collines derrière Theldurin l'Egaré le portent.",al={"où trouver le fragment roussi","emplacement du fragment roussi"}},{q="Qui veut le fragment ?",a="Theldurin l'Egaré le demande avec le Torn Scroll Fragment et le Crumpled Scroll Fragment.",al={"qui a besoin du fragment roussi","fragment de theldurin"}},{q="Pourquoi Theldurin veut-il les fragments ?",a="Il espère les réunir pour que le Parchemin de Myzrael puisse servir contre Myzrael.",al={"pourquoi rassembler les fragments","pourquoi le parchemin de myzrael"}}},fp="22,146,16.198.0,35.66.0,34.72.0,23.99.0,38.79.0"}
P.entries["item:singing-blue-crystal"] = {n="Singing Blue Crystal",s="Les cristaux bleus chantants sont extraits par la KapitalRisk dans les collines autour de la Mine aux cristaux. Crank Fizzlebub, à Baie-du-Butin, les veut comme preuve que les gobelins perdent du terrain.",h="Les cristaux bleus chantants sont extraits par la KapitalRisk dans les collines autour de la Mine aux...",kw={"basilics","baie-du-butin","crank fizzlebub","mine aux cristaux","cristal bleu chantant","cristaux chantants","vallée de strangleronce","kapitalrisk"},sec={{t="Des cristaux dans les collines",b="Près de la Mine aux cristaux, les équipes de la KapitalRisk extraient des cristaux bleus chantants dans les collines voisines. Elles comptaient travailler dans la mine, mais les basilics les en ont chassées. Crank Fizzlebub, à Baie-du-Butin, vous demande de lui apporter des cristaux pris aux mineurs de la compagnie. Selon lui, leur retraite ferait plus de place au commerce honnête dans la Vallée de Strangleronce."}},faq={{q="Que sont les cristaux bleus chantants ?",a="Ce sont des cristaux extraits par la KapitalRisk dans les collines autour de la Mine aux cristaux.",al={"cristaux chantants","cristal bleu","que sont ces cristaux"}},{q="Où la KapitalRisk les extrait-elle ?",a="La KapitalRisk extrait des cristaux bleus chantants dans les collines qui entourent la Mine aux cristaux, dans la Vallée de Strangleronce.",al={"où sont les cristaux","emplacement des cristaux","où la kapitalrisk extrait"}},{q="Pourquoi ne les extraient-ils pas dans la Mine aux cristaux ?",a="Les basilics de la Mine aux cristaux ont chassé la KapitalRisk. Ses équipes extraient donc les cristaux dans les collines voisines.",al={"pourquoi pas dans la mine","basilics de la mine","basilics de la mine aux cristaux"}},{q="Qui veut ces cristaux ?",a="Crank Fizzlebub, à Baie-du-Butin, veut des cristaux bleus chantants comme preuve que la KapitalRisk perd du terrain.",al={"qui veut les cristaux chantants","cristaux de crank fizzlebub","cristaux pour crank"}},{q="Que veut faire la KapitalRisk de ces cristaux ?",a="La KapitalRisk comptait extraire des cristaux bleus chantants dans la Mine aux cristaux, puis s'est tournée vers les collines après que les basilics l'en ont chassée.",al={"pourquoi extraire les cristaux","cristaux de la kapitalrisk","que creusent les gobelins"}}},fp="20,177,21.344.0,31.84.0,41.113.0,47.109.0,23.108.0,53.137.0"}
P.entries["item:singing-crystal-shard"] = {n="Singing Crystal Shard",s="Les Singing Crystal Shards sont de précieux cristaux bleus que l’on trouve dans la Vallée de Strangleronce. Les basilics les mangent, ce qui durcit leur peau.",h="Les Singing Crystal Shards sont de précieux cristaux bleus que l’on trouve dans la Vallée de Strangleronce.",kw={"basilic","éclats bleus","crank fizzlebub","singing crystal shard","singing crystals","vallée de strangleronce","kapitalrisk"},sec={{t="Cristal et écailles",b="Dans la Vallée de Strangleronce, les basilics mangent des Singing Crystals, qui durcissent leur peau. On peut parfois récolter un éclat sur ces créatures. Crank Fizzlebub affirme que ces cristaux sont propres à Strangleronce et intéressent certaines parties. KapitalRisk lui complique la tâche pour les récolter."}},faq={{q="Que sont les Singing Crystal Shards ?",a="Les Singing Crystal Shards sont des fragments de cristaux que l’on trouve dans la Vallée de Strangleronce. Les basilics les mangent, ce qui durcit leur peau.",al={"éclats chantants","éclats de cristal bleu"}},{q="Pourquoi les basilics ont-ils la peau dure ?",a="Les basilics de la Vallée de Strangleronce mangent des Singing Crystals, qui durcissent leur peau.",al={"peau dure des basilics","pourquoi les basilics sont-ils coriaces"}},{q="Où trouver les éclats ?",a="On peut récolter des Singing Crystal Shards sur les basilics de la Vallée de Strangleronce.",al={"lieu où trouver les éclats","où trouver les cristaux chantants"}},{q="Pourquoi Crank Fizzlebub les veut-il ?",a="Crank Fizzlebub affirme que ces cristaux intéressent certaines parties et qu’il peut les revendre avec profit.",al={"crank veut les éclats","ce dont crank a besoin"}},{q="Quel est le rapport entre KapitalRisk et ces cristaux ?",a="KapitalRisk complique la tâche de Crank Fizzlebub, qui cherche à récolter les cristaux.",al={"cristaux de kapitalrisk","pourquoi kapitalrisk"}}},fp="21,134,17.294.0,32.127.0,36.89.0,28.77.0,35.101.0,59.82.0"}
P.entries["item:skeleton-finger"] = {n="Doigt de squelette",s="Dans le Bois de la Pénombre, les morts agités livrent des Doigts de squelette à Madame Eva de Sombre-Comté. Elle les rassemble avec des crocs de goule et du venin d’araignée pour fabriquer des talismans protecteurs.",h="Dans le Bois de la Pénombre, les morts agités livrent des Doigts de squelette à Madame Eva de Sombre-Comté.",kw={"sombre-comté","bois de la pénombre","croc de goule","madame eva","écumeur squelette","doigt de squelette","totem d'affliction"},ang={["class:Mage"]="En tant que mage étudiant la divination populaire, vous pourriez trouver inhabituel ce mélange de sorcellerie des campagnes et de magie sympathique chez Madame Eva, qui associe des doigts squelettiques et des venins naturels dans un enchantement de riposte.",["class:Paladin"]="En tant que paladin, vous pourriez frémir à l’idée de profaner des restes squelettiques et d’en porter les morceaux sectionnés. Dans la sinistre pénombre du Bois de la Pénombre, utiliser les os des impies pour protéger les vivants est une sombre nécessité."},sec={{t="Les os des morts agités",b="Des Écumeurs squelettes et des guerriers squelettes se dressent dans tout le Bois de la Pénombre, ainsi que des mages nécrotiques et des fiélons. La plupart des voyageurs évitent leurs restes infects, mais les diseuses de bonne aventure et les mystiques prisent leur essence glaciale. Madame Eva, la voyante de Sombre-Comté, rassemble leurs doigts osseux pour le Totem d’affliction. Elle lie leurs énergies nécrotiques persistantes dans une protection qui riposte aux attaques."}},faq={{q="Quelles créatures donnent des Doigts de squelette ?",a="Dans tout le Bois de la Pénombre, les Doigts de squelette proviennent des Skeletal Raiders, Skeletal Healers, Skeletal Warders, Skeletal Warriors, Skeletal Horrors, Skeletal Fiends et Skeletal Mages.",al={"où trouver des doigts de squelette","qu’est-ce qui donne des doigts de squelette","source des doigts de squelette"}},{q="Qui veut des Doigts de squelette dans le Bois de la Pénombre ?",a="Madame Eva, la voyante de Sombre-Comté, a besoin de Doigts de squelette pour créer une protection.",al={"qui a besoin de doigts de squelette","qui donne la quête des doigts de squelette","à quoi servent les doigts de squelette"}},{q="Qu’est-ce que le Totem d’affliction ?",a="Madame Eva fabrique le Totem d’affliction avec des doigts de squelette, des crocs de goule et du venin d’araignée. Elle lie leurs énergies obscures en une aura qui blesse quiconque attaque son porteur.",al={"utilité du totem d’affliction","que fabrique madame eva"}},{q="Pourquoi Madame Eva a-t-elle besoin de restes de morts-vivants pour un charme protecteur ?",a="Madame Eva utilise la souillure persistante et l’agressivité des créatures locales dans ses rituels. Elle lie les essences violentes des squelettes, des goules et des bêtes venimeuses du Bois de la Pénombre dans une protection qui punit les assaillants.",al={"pourquoi la magie des os","pourquoi des doigts de squelette pour le totem"}}},fx={["7c732e26"]={q="Qu'est-ce qu'un Doigt de squelette ?",a="Un Doigt de squelette est un fragment d'os séché et sectionné provenant de l'une des horreurs squelettiques animées qui errent dans les forêts et les cryptes dévastées du Bois de la Pénombre. Préservés par la souillure nécromantique qui a envahi la région, ces doigts conservent des traces de la magie noire qui maintient les morts-vivants agités et en mouvement.",al={"doigt de squelette qu'est-ce que c'est","que sont les doigts de squelette","identifier le doigt de squelette"}},a7de6990={q="D'où provient un Doigt de squelette ?",a="Ces doigts proviennent des restes squelettiques relevés dans les cimetières et ruines hantés du Bois de la Pénombre. Plutôt que d'être fabriqués ou manufacturés, ils sont récoltés directement sur les cadavres animés — comme les guerriers squelettiques, les démons, les gardiens et les pillards — qui rampent dans l'obscurité, animés par la souillure mystérieuse et rampante qui corrompt les bois.",al={"origine du doigt de squelette","d'où viennent les doigts de squelette","qui a fait le doigt de squelette"}}},fp="15,157,21.373.0,38.125.0,39.84.0,32.179.0,63.206.0"}
P.entries["item:skeleton-key-mold"] = {n="Skeleton Key Mold",s="Le Skeleton Key Mold façonne une tige de clé en thorium et en os dans la lave de la Crête de la Fournaise. L’Apothicaire Dithers a besoin de la clé inachevée pour combattre le Fléau à Andorhal.",h="Le Skeleton Key Mold façonne une tige de clé en thorium et en os dans la lave de la Crête de la Fournaise.",kw={"andorhal","apothicaire dithers","crête de la fournaise","fléau","clé squelette","skeleton key mold","thorium","cratère d’un’goro","clé squelette inachevée"},ang={["faction:Horde"]="Dithers vous demande de l’aider à contrer le Fléau, qui tient Andorhal sous son emprise.",["profession:Mining"]="Il faut du thorium pour forger la tige de clé, mais Krinkle Goodsteel vous laisse vous en procurer."},sec={{t="Un moule pour la clé",b="Krinkle Goodsteel, à Gadgetzan, vous vend le Skeleton Key Mold pour travailler à la Crête de la Fournaise, dans le Cratère d’Un’Goro. Avec deux Thorium Bars, son porteur peut utiliser le moule près du lac de lave pour fondre le thorium et l’os en une ébauche de tige de clé. Krinkle dit que la chaleur de la lave fera la forge, mais que le thorium doit être fourni séparément."}},faq={{q="À quoi sert le Skeleton Key Mold ?",a="Le Skeleton Key Mold façonne une tige de clé en thorium et en os dans la lave de la Crête de la Fournaise.",al={"utilité du skeleton key mold","fonction du moule"}},{q="Qui me donne le moule ?",a="Krinkle Goodsteel, à Gadgetzan, vous vend le Skeleton Key Mold pour le travail à la Crête de la Fournaise. L’Apothicaire Dithers regrette que vous ayez dû en payer le prix.",al={"où obtenir skeleton key mold","moule de dithers"}},{q="De quoi ai-je besoin avec le moule ?",a="Il faut deux Thorium Bars avec le Skeleton Key Mold pour forger la tige de clé inachevée.",al={"ingrédients du moule","barres de thorium pour la clé"}},{q="Où utiliser le moule ?",a="Utilisez le Skeleton Key Mold près du lac de lave, au sommet de la Crête de la Fournaise, dans le Cratère d’Un’Goro.",al={"où utiliser skeleton key mold","lave de la crête de la fournaise"}},{q="Pourquoi Dithers fabrique-t-il une clé squelette ?",a="Dithers prépare la clé dans le cadre des efforts pour frapper le Fléau à Andorhal.",al={"clé pour andorhal","pourquoi une clé squelette"}}},fp="17,177,18.331.0,34.89.0,22.149.0,29.88.0,23.96.0,37.88.0"}
P.entries["item:skin-of-sweet-rum"] = {n="Outre de rhum doux",s="À l’Auberge de la Fierté du Lion, à Comté-de-l’Or, l’Outre de rhum doux part pour Comté-du-Lac, où la guerre a vidé les réserves de la taverne.",h="À l’Auberge de la Fierté du Lion, à Comté-de-l’Or, l’Outre de rhum doux part pour Comté-du-Lac, où la guerre...",kw={"tavernier daniels","dry times","comté-de-l’or","comté-du-lac","auberge de la fierté du lion","outre de rhum doux","rhum doux"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous pouvez constater les difficultés que l’invasion des orcs Rochenoire impose aux petites communautés qui défendent les frontières orientales de Hurlevent."},sec={{t="Un réconfort rare pour Comté-du-Lac",b="La taverne de Comté-du-Lac manque de boissons, car l’invasion des orcs Rochenoire bloque les routes menant aux Carmines. Le Tavernier Daniels a besoin de boissons pour les gardes de la ville et les réfugiés. Il envoie donc des voyageurs chercher des spécialités régionales, dont une outre de rhum doux à l’Auberge de la Fierté du Lion, à Comté-de-l’Or."}},faq={{q="Où trouver une outre de rhum doux ?",a="Vous pouvez acheter une Outre de rhum doux auprès de l’aubergiste ou du tavernier de l’Auberge de la Fierté du Lion, à Comté-de-l’Or, dans la Forêt d’Elwynn.",al={"emplacement du rhum doux","où acheter du rhum doux","qui vend du rhum doux"}},{q="Qui veut de ce rhum ?",a="Le Tavernier Daniels tient la taverne de Comté-du-Lac. Il veut une outre de rhum doux et d’autres boissons régionales pour remplir ses étagères pendant les Dry Times.",al={"qui a besoin de rhum doux","remettre le rhum doux","quête du rhum doux"}},{q="Pourquoi Comté-du-Lac manque-t-il d’alcool ?",a="L’invasion des orcs Rochenoire a coupé les routes commerciales menant aux Carmines. Les caravanes marchandes ne peuvent plus circuler sans danger, et les réserves d’alcool de Comté-du-Lac sont presque épuisées.",al={"pourquoi manquent-ils d’alcool","pourquoi comté-du-lac manque d’alcool","raison des dry times"}},{q="Quels autres spiritueux faut-il avec le rhum ?",a="Le Tavernier Daniels a aussi besoin d’un fût de Thunderbrew Lager de la Marche de l’Ouest, d’un tonneau de merlot de Hurlevent et d’une bouteille de tord-boyaux de Sombre-Comté.",al={"boissons pour les dry times","liste des boissons de daniels","autres alcools nécessaires"}}},fx={efbd5e13={q="Qu'est-ce qu'une Outre de rhum doux ?",a="Une Outre de rhum doux est une outre en cuir remplie de liqueur sucrée vendue au Comté-de-l’Or dans la Forêt d’Elwynn. C'est l'un des nombreux spiritueux régionaux prisés dans les royaumes humains du sud d'Azeroth.",al={"qu'est-ce que le rhum doux","infos sur l'outre de rhum doux","rhum doux"}}},fp="17,123,28.311.0,37.117.0,19.140.0,39.152.0,48.148.0"}
P.entries["item:skittering-blood"] = {n="Sang du Grouillement",s="Dans la Forêt des Pins-Argentés, le Sang du Grouillement fournit à la Société royale des apothicaires des matériaux pour sa New Plague. Les alchimistes réprouvés l'extraient des arachnides du Grouillement en quête d'une arme contre le Fléau et l'humanité.",h="Dans la Forêt des Pins-Argentés, le Sang du Grouillement fournit à la Société royale des apothicaires des...",kw={"faranell","new plague","renferrel","société royale des apothicaires","forêt des pins-argentés","sang du grouillement","le grouillement","skitterweb"},ang={["faction:Horde"]="En tant que membre de la Horde, vous aidez les apothicaires réprouvés à sécuriser Lordaeron grâce aux armes qu'ils fabriquent eux-mêmes dans leur guerre contre le Fléau.",["race:Undead"]="En tant que Mort-vivant, vous aidez la reine Sylvanas et la Société royale des apothicaires à mettre au point une arme biologique contre Arthas et l'humanité vivante."},sec={{t="Un distillat toxique",b="Les Skitterweb lurkers, les strikers et leur mère de couvée Krethis the Shadowspinner produisent un sang venimeux. L'Apothicaire Renferrel a découvert que, raffiné avec les toxines de cœurs d'ours grisonnants, il forme la base d'un élixir particulièrement mortel. Ses agents contaminants conviennent aussi aux expériences chimiques de l'Apothicarium."},{t="Alimenter la New Plague",b="À Fossoyeuse, le Maître apothicaire Faranell dirige les recherches de la Société royale des apothicaires sur une nouvelle peste. Les Réprouvés font face aux hordes du Fléau et aux vestiges hostiles de l'humanité ; ils se tournent donc vers la guerre biologique pour rétablir l'équilibre. Faranell étudie la puissance toxique du sang tandis qu'il cherche à créer un fléau capable de détruire aussi bien les morts-vivants que la chair vivante."}},faq={{q="À quoi sert le Sang du Grouillement ?",a="La Société royale des apothicaires utilise le Sang du Grouillement dans ses recherches sur la New Plague des Réprouvés. Mélangé aux toxines de cœurs d'ours, il forme un mélange instable que le Maître apothicaire Faranell étudie pour l'utiliser contre le Fléau et les humains vivants.",al={"utilisation du sang du grouillement","pourquoi récolter du sang d'araignée","que fait faranell du sang du grouillement"}},{q="Où trouve-t-on le Sang du Grouillement ?",a="Les Skitterweb lurkers, les strikers et Krethis the Shadowspinner produisent du Sang du Grouillement dans le Grouillement et ses environs. Ce bois sombre, étouffé par les toiles, se trouve dans le nord-ouest de la Forêt des Pins-Argentés.",al={"où trouver du sang du grouillement","emplacement du sang du grouillement","qui donne du sang du grouillement"}},{q="Qui demande ces échantillons ?",a="L'Apothicaire Renferrel, au Sépulcre dans la Forêt des Pins-Argentés, demande ce sang. Les échantillons sont envoyés au Maître apothicaire Faranell, à l'Apothicarium de Fossoyeuse.",al={"qui veut du sang du grouillement","donneur de quête du sang du grouillement"}},{q="Pourquoi les Réprouvés ont-ils besoin du venin des bêtes locales ?",a="La Société royale des apothicaires extrait les toxines naturelles de la faune corrompue de Lordaeron. Le venin des arachnides géantes de la Forêt des Pins-Argentés fournit des agents pathogènes biologiques bruts, qui peuvent être concentrés et transformés en armes sous forme de pestes synthétiques.",al={"pourquoi le venin d'araignée","recherches des apothicaires sur les bêtes"}}},fx={["8eea8a63"]={q="Qu'est-ce que le Sang du Grouillement ?",a="Le Sang du Grouillement est l'ichor virulent récolté sur les araignées massives habitant Le Grouillement dans la Forêt des Pins-Argentés. Il possède des propriétés venimeuses et contaminantes naturelles qui en font un réactif biologique inestimable pour les expériences alchimiques.",al={"qu'est-ce que le sang du grouillement","objet sang du grouillement","à propos du sang du grouillement"}},f7d32240={q="D'où provient le Sang du Grouillement et qui l'a créé ?",a="Il n'est pas fabriqué, mais prélevé naturellement sur les arachnides prédatrices habitant le nord-ouest de la Forêt des Pins-Argentés, notamment les rôdeurs toile-grouillante, les frappeurs toile-grouillante et la mère des couvées Krethis la Tisseuse d'ombre. Le sang est extrait directement de leurs carcasses par des chasseurs rassemblant des matériaux pour les Réprouvés.",al={"d'où vient le sang du grouillement","qui a créé le sang du grouillement","origine du sang du grouillement"}}},fp="16,224,18.307.0,22.345.0,34.245.0,32.185.0,27.156.0,49.221.0"}
P.entries["item:skullsplitter-fetish"] = {n="Skullsplitter Fetish",s="Frère Nimetz reçoit au Camp rebelle un fétiche Tranche-tête lié à la magie troll. Il espère que cet objet éclairera la corruption du colonel Kurzen.",h="Frère Nimetz reçoit au Camp rebelle un fétiche Tranche-tête lié à la magie troll.",kw={"frère nimetz","colonel kurzen","mystique","tranche-tête","fétiche tranche-tête","vallée de strangleronce","magie troll","witch doctor"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous pouvez apporter ces fétiches à Frère Nimetz pour l’aider à étudier la corruption du colonel Kurzen."},sec={{t="Magie troll",b="Au Camp rebelle, Frère Nimetz recherche des fétiches Tranche-tête auprès des Witch Doctors et des Mystics Tranche-tête de la Vallée de Strangleronce. Il étudie ces charmes pour comprendre ce qui a poussé le colonel Kurzen vers le mal."}},faq={{q="Qu’est-ce qu’un fétiche Tranche-tête ?",a="Un fétiche Tranche-tête est un instrument de magie troll porté par les Witch Doctors et les Mystics Tranche-tête.",al={"signification du fétiche tranche-tête","qu’est-ce que le fétiche","charme troll"}},{q="Qui veut ces fétiches ?",a="Frère Nimetz, au Camp rebelle, veut des fétiches Tranche-tête pour étudier leur magie.",al={"qui veut le fétiche","où apporter les fétiches","frère nimetz"}},{q="Pourquoi Frère Nimetz les veut-il ?",a="Frère Nimetz espère que ces fétiches révéleront le secret de la corruption du colonel Kurzen.",al={"pourquoi les fétiches","corruption de kurzen","que veut nimetz"}},{q="Où trouve-t-on les fétiches Tranche-tête ?",a="Les Witch Doctors et les Mystics Tranche-tête de la Vallée de Strangleronce portent ces fétiches.",al={"emplacement des fétiches","où trouver les tranche-tête","obtenir des fétiches"}},{q="De combien de fétiches Nimetz a-t-il besoin ?",a="Frère Nimetz demande quatre fétiches Tranche-tête.",al={"nombre de fétiches","combien de charmes","quatre fétiches"}}},fp="20,160,11.211.0,31.106.0,23.90.0,34.91.0,39.81.0,35.52.0"}
P.entries["item:skullsplitter-tusk"] = {n="Skullsplitter Tusk",s="Une défense de Tranche-tête sert à forger de fausses canines de tigre vendues dans les Mers du sud. Kebok, à Baie-du-Butin, veut une grosse livraison pour son commerce.",h="Une défense de Tranche-tête sert à forger de fausses canines de tigre vendues dans les Mers du sud.",kw={"baie-du-butin","kebok","défense de tranche-tête","défenses de tranche-tête","mers du sud","vallée de strangleronce","canines de tigre"},sec={{t="Une fausse défense",b="Kebok, à Baie-du-Butin, vous envoie chercher les trolls Tranche-tête et leurs défenses. Celles-ci font d’excellentes copies de canines de tigre, qu’il est coûteux de récupérer sur les bêtes elles-mêmes. Les contrefaçons sont destinées à une livraison pour les îles des Mers du sud."}},faq={{q="Qu’est-ce qu’une défense de Tranche-tête ?",a="Une défense de Tranche-tête est une défense de troll que Kebok utilise pour fabriquer de fausses canines de tigre.",al={"défense de tranche-tête","défense de troll","quelle défense"}},{q="Qui veut des défenses de Tranche-tête ?",a="Kebok, à Baie-du-Butin, veut des défenses de Tranche-tête pour sa livraison de fausses canines de tigre.",al={"qui veut des défenses","défenses pour kebok","acheteur de défenses"}},{q="Pourquoi Kebok a-t-il besoin de ces défenses ?",a="Kebok utilise les défenses de Tranche-tête pour fabriquer d’excellentes imitations de canines de tigre, qu’il est coûteux de récupérer.",al={"pourquoi des défenses","fausses canines de tigre","utilité des défenses"}},{q="D’où viennent les défenses de Tranche-tête ?",a="Ces défenses viennent des trolls Tranche-tête de la Vallée de Strangleronce.",al={"origine des défenses","emplacement des tranche-tête","défenses de troll"}}},fp="18,157,12.256.0,29.83.0,30.84.0,30.98.0,39.63.0"}
P.entries["item:skylord-plume"] = {n="Skylord Plume",s="La Plume de Skylord provient d’un Razorbeak Skylord des Hinterlands. Le Veneur Markhor, au Village des Revantusk, la réclame comme preuve qu’un de ces dangereux griffons a été tué.",h="La Plume de Skylord provient d’un Razorbeak Skylord des Hinterlands.",kw={"griffon","hinterlands","markhor","razorbeak skylord","village des revantusk","plume de skylord","chasseurs trolls"},ang={["class:Hunter"]="Le Veneur Markhor vous charge de traquer un rare griffon qui s’en prend aux chasseurs des Hinterlands.",["race:Troll"]="Markhor affirme que les Razorbeak Skylords ont dévoré des chasseurs trolls dans les Hinterlands, et que la menace est donc tout près."},sec={{t="La preuve d’un Chasseur",b="Au Village des Revantusk, le Veneur Markhor vous demande de lui rapporter une Plume de Skylord. Les Razorbeak Skylords sont de rares griffons des Hinterlands, et Markhor affirme qu’ils s’en prennent aux chasseurs trolls. Il veut que l’un d’eux soit tué et que sa plume lui soit rapportée comme preuve."}},faq={{q="Qu’est-ce que la Plume de Skylord ?",a="La Plume de Skylord provient d’un Razorbeak Skylord, un rare griffon des Hinterlands.",al={"plume de skylord","quelle plume","plume de griffon"}},{q="Qui veut la Plume de Skylord ?",a="Le Veneur Markhor, au Village des Revantusk, veut qu’on lui rapporte une Plume de Skylord.",al={"qui veut la plume","plume de markhor","chasseur revantusk"}},{q="Pourquoi Markhor la veut-il ?",a="Markhor vous demande de tuer un Razorbeak Skylord et de lui rapporter sa plume comme preuve.",al={"pourquoi la plume","markhor veut une plume","à quoi ça sert"}},{q="Où trouver un Razorbeak Skylord ?",a="Les Razorbeak Skylords sont de rares griffons qui vivent dans les étendues sauvages des Hinterlands.",al={"où trouver un skylord","trouver un razorbeak","emplacement des skylords"}},{q="Pourquoi les Skylords sont-ils dangereux pour les trolls ?",a="Markhor affirme que les anciens griffons s’en prennent aux chasseurs trolls et élèvent des petits qui tuent eux aussi les trolls.",al={"skylords et trolls","menace des griffons","pourquoi tuer un skylord"}}},fp="13,180,16.235.0,26.84.0,28.75.0,25.80.0,37.78.0,41.96.0"}
P.entries["item:slagtree-s-lost-tools"] = {n="Slagtree's Lost Tools",s="Slagtree’s Lost Tools sont un ensemble d’outils de forge volés que recherche le Forgeron Slagtree, au Village des Revantusk. Il vous demande de les retrouver après l’invasion du village par les trolls Vilebranch.",h="Slagtree’s Lost Tools sont un ensemble d’outils de forge volés que recherche le Forgeron Slagtree, au Village...",kw={"agol'watha","gnome","outils perdus","village des revantusk","shaol'watha","rocher de l'affût","slagtree","forgeron slagtree","vilebranch","voyous vilebranch"},ang={["race:Gnome"]="Un gnome a donné ces outils à Slagtree après lui avoir sauvé la vie lorsqu’il était un jeune orc. Ce cadeau reste précieux pour le forgeron.",["race:Orc"]="Slagtree se souvient que ces outils lui ont été offerts par le gnome qui lui a sauvé la vie lorsqu’il était un jeune orc."},sec={{t="Un cadeau volé",b="Au Village des Revantusk, le Forgeron Slagtree vous demande de retrouver les outils volés lors de l’invasion des trolls Vilebranch. Il garde un jeu de rechange, mais ces outils lui ont été offerts par un gnome au grand cœur qui lui a sauvé la vie dans sa jeunesse. Markhor les a signalés près des temples d’Agol'watha et de Shaol'watha. Slagtree veut récupérer ce vieux cadeau."}},faq={{q="Qui veut récupérer les outils de Slagtree ?",a="Le Forgeron Slagtree, du Village des Revantusk, veut récupérer ses outils volés.",al={"qui veut les outils","outils de slagtree","forgeron slagtree"}},{q="Pourquoi ces outils comptent-ils tant pour Slagtree ?",a="Un gnome au grand cœur a donné ces outils à Slagtree après lui avoir sauvé la vie lorsqu’il était un jeune orc.",al={"pourquoi les outils sont importants","importance des outils","pourquoi les veut-il"}},{q="Qui a volé les outils ?",a="Les trolls Vilebranch ont volé les outils de Slagtree lors de leur invasion du Village des Revantusk.",al={"qui a pris les outils de slagtree","vilebranch a volé les outils","outils volés"}},{q="Où les outils pourraient-ils se trouver ?",a="Les outils ont été aperçus près des temples d’Agol'watha et de Shaol'watha, dans le nord-est des Hinterlands.",al={"où sont les outils","emplacement des outils","trouver les outils de slagtree"}},{q="Slagtree a-t-il d’autres outils ?",a="Slagtree possède un jeu de rechange, mais les outils volés lui sont précieux, car ils viennent du gnome qui lui a sauvé la vie.",al={"outils de rechange","a-t-il des outils de rechange","autres outils du forgeron"}}},fp="21,180,13.332.0,32.68.0,36.94.1,20.77.0,25.99.0,31.113.1"}
P.entries["item:sleepers-key"] = {n="Clé du dormeur",s="Au Pic des Serres-Rocheuses, la Clé du dormeur aide à protéger un caveau druidique sacré. Les druides elfes de la nuit en firent l'une des trois clés enchantées du trésor de l'antre des Serres.",h="Au Pic des Serres-Rocheuses, la Clé du dormeur aide à protéger un caveau druidique sacré.",kw={"clé du gardien","sleepers' cache","clé du dormeur","pic des serres-rocheuses","antre des serres","trésor de l'antre des serres","l'antre"},ang={["class:Druid"]="En tant que druide, vous pouvez voir comment les clés et les caches de l'antre des Serres renforcent ses défenses. Des caches dissimulées et des serrures à clé scellent des reliques puissantes.",["faction:Horde"]="En tant que membre de la Horde, vous participez à un raid organisé au cœur du Pic des Serres-Rocheuses pour récupérer la Clé du dormeur. Le raid fait tomber les protections défensives des elfes de la nuit afin de s'emparer des reliques scellées dans leur trésor."},sec={{t="Une protection druidique",b="L'antre des Serres est une redoute et un sanctuaire pour les druides de Kalimdor, au Pic des Serres-Rocheuses. Les gardiens elfes de la nuit ont bâti des serrures et des caches dissimulées pour protéger les reliques sacrées et les puissants trésors des regards indésirables. La Clé du dormeur est l'une des trois clés qui forment une protection magique.\n\nLa Clé du dormeur repose dans une cache isolée, au cœur de l'antre. La Clé du gardien, dissimulée près du seuil, ouvre cette cache. La Clé des griffes et la Clé du refuge complètent l'ensemble. Insérez les trois clés dans les serrures de pierre du trésor de l'antre des Serres pour dissiper la protection. Des objets anciens se trouvent à l'intérieur."}},faq={{q="À quoi sert la Clé du dormeur ?",a="La Clé du dormeur ouvre le trésor de l'antre des Serres avec la Clé du refuge et la Clé des griffes. Le caveau de pierre protégé se trouve au fond de l'antre du tertre, au Pic des Serres-Rocheuses.",al={"à quoi sert la clé du dormeur","utilité de la clé du dormeur","clés du trésor de l'antre des serres"}},{q="Comment la Clé du dormeur a-t-elle été mise sous clé ?",a="Les druides ont placé la Clé du dormeur dans le Sleepers' Cache, dans les tunnels nord-ouest de l'antre des Serres. La Clé du gardien l'ouvre. Les druides ont caché cette clé dans une lanterne banale, près de l'entrée de l'antre.",al={"où trouver la clé du dormeur","ouvrir le sleepers' cache","condition pour la clé du gardien"}},{q="Pourquoi les druides ont-ils caché leurs reliques avec plusieurs clés ?",a="Les druides elfes de la nuit ont créé des protections complexes pour préserver leurs objets puissants et leurs héritages sacrés des mains ennemies si l'antre était attaqué. En cachant les clés dans des caches séparées, ils ont rendu le trésor difficile à piller pour les intrus.",al={"pourquoi tant de clés","défenses de l'antre des serres","énigme du trésor druidique"}},{q="Pourquoi l'appelle-t-on la Clé du dormeur ?",a="Les druides n'expliquent jamais ce nom. La Clé du dormeur partage son nom avec le Sleepers' Cache, le coffre caché de l'antre des Serres où la clé est conservée.",al={"qui sont les dormeurs","signification du nom clé du dormeur"}}},fx={["0a862a33"]={q="Qu'est-ce que la Clé du dormeur ?",a="La Clé du dormeur est l'une des trois clés spécialisées fabriquées par les druides elfes de la nuit du Pic des Serres-Rocheuses. Dissimulée à l'intérieur d'une cache verrouillée au plus profond de L'antre des Serres, elle constitue un élément essentiel du système de protection gardant le trésor central de reliques sacrées des druides.",al={"qu'est-ce que la clé du dormeur","lore de la clé du dormeur","à propos de la clé du dormeur"}},["8275ad63"]={q="D'où provient la Clé du dormeur et qui l'a créée ?",a="La clé a été façonnée par les druides qui ont établi L'antre des Serres sur le Pic des Serres-Rocheuses. Pour protéger leurs puissants artefacts des intrus, ils ont mis au point un système de sécurité complexe, enfermant la clé à l'intérieur d'un coffre dédié appelé la Cache du dormeur.",al={"qui a créé la clé du dormeur","origine de la clé du dormeur","d'où vient la clé du dormeur"}},["3884172c"]={q="Pourquoi quelqu'un voudrait-il la Clé du dormeur ?",a="La Horde cherche la clé pour contourner les défenses en couches des druides et déverrouiller le trésor de L'antre des Serres. Avec la Clé des griffes et la Clé du refuge, elle ouvre la chambre forte en pierre contenant les puissantes reliques que les druides ont dissimulées sur le Pic des Serres-Rocheuses.",al={"pourquoi trouver la clé du dormeur","pourquoi besoin de la clé du dormeur","qui veut la clé du dormeur"}}},fp="13,149,19.546.0,35.148.0,38.200.0,56.237.0,35.141.0"}
P.entries["item:small-brass-key"] = {n="Small Brass Key",s="La Small Brass Key est cachée dans un registre au camp de Kurzen. Elle pourrait ouvrir un coffre dans le Stockpile.",h="La Small Brass Key est cachée dans un registre au camp de Kurzen.",kw={"hérode la paperasse","hérode","clé cachée","base de kurzen","muddy note","small brass key","stockpile","vallée de strangleronce","coffre"},sec={{t="Une clé dans le registre",b="Les papiers d’Hérode vous dirigent vers le Stockpile, une caverne derrière le camp de Kurzen, dans la Vallée de Strangleronce. La Small Brass Key est cachée dans la reliure de l’un de ses registres. Elle pourrait ouvrir le coffre sécurisé mentionné dans ses notes."},{t="Dans le coffre",b="Le coffre contient les pièces et les objets les plus précieux d’Hérode. L’ouvrir avec la Small Brass Key révèle aussi une Muddy Note, qui relance la recherche du traître."}},faq={{q="Où trouver la Small Brass Key ?",a="La Small Brass Key est cachée dans la reliure de l’un des registres d’Hérode la Paperasse.",al={"emplacement de la small brass key","où trouver la small brass key","clé d’hérode"}},{q="Qu’ouvre la Small Brass Key ?",a="La Small Brass Key ouvre le coffre sécurisé d’Hérode la Paperasse, dans le Stockpile, au camp de Kurzen.",al={"quelle clé ouvre","coffre de la small brass key","clé du coffre"}},{q="Que contient le coffre d’Hérode ?",a="Hérode garde ses pièces et ses objets les plus précieux dans le coffre. On y trouve aussi une Muddy Note.",al={"contenu du coffre d’hérode","contenu du coffre","coffre d’hérode la paperasse"}},{q="Que signifie la Muddy Note ?",a="La Muddy Note fait avancer la recherche du traître.",al={"indice de la muddy note","note du coffre","note sur le traître"}}},fp="15,111,19.248.0,14.172.1,36.85.0,35.100.0,31.97.0,30.71.1"}
P.entries["item:small-stone-shard"] = {n="Small Stone Shard",s="Les Small Stone Shards proviennent d’élémentaires de roche inférieurs des Terres Ingrates. Lotwil Veriatus en a besoin pour tester des sorts et des appareils dans le cadre de ses travaux sur l’asservissement des élémentaires.",h="Les Small Stone Shards proviennent d’élémentaires de roche inférieurs des Terres Ingrates.",kw={"terres ingrates","asservissement des élémentaires","élémentaire de roche inférieur","lotwil veriatus","sorts offensifs","entraves","small stone shard","small stone shards"},ang={["class:Mage"]="En tant que mage, vous pouvez voir Lotwil Veriatus tester des sorts offensifs et des appareils pendant qu’il travaille sur des entraves destinées à lier les élémentaires."},sec={{t="La pierre à étudier",b="Des élémentaires de roche inférieurs rôdant dans les collines à l’ouest de Lotwil Veriatus portent des Small Stone Shards. Le mage les rassemble pour tester ses sorts offensifs et les appareils qu’il a assemblés. Il travaille sur des entraves destinées à lier les élémentaires, et ces éclats comptent parmi les matériaux dont il a besoin."}},faq={{q="D’où viennent les Small Stone Shards ?",a="Vous les récupérez sur les élémentaires de roche inférieurs qui rôdent dans les collines à l’ouest de Lotwil Veriatus.",al={"origine des petits éclats","où trouver des éclats de pierre","élémentaires de roche inférieurs"}},{q="Qui veut ces éclats ?",a="Lotwil Veriatus a besoin de Small Stone Shards pour ses travaux sur l’asservissement des élémentaires et ses tests de sorts et d’appareils.",al={"qui a besoin des éclats","éclats pour lotwil","à qui donner les éclats"}},{q="À quoi servent ces éclats ?",a="Lotwil Veriatus utilise les Small Stone Shards pour tester des sorts offensifs et des appareils destinés à ses travaux sur des entraves capables de lier les élémentaires.",al={"pourquoi des éclats","utilité des éclats","que fait lotwil"}},{q="Où Lotwil Veriatus travaille-t-il ?",a="Lotwil Veriatus travaille dans les Terres Ingrates, près d’élémentaires de roche inférieurs dans les collines juste à l’ouest.",al={"emplacement de lotwil","où se trouve lotwil","mage dans les terres ingrates"}}},fp="17,154,15.278.0,38.90.0,21.111.0,29.123.0,33.109.0"}
P.entries["item:smithing-tuyere"] = {n="Tuyère de forge",s="La Tuyère de forge est un outil volé par les Dark Iron dwarves dans la Gorge des Vents brûlants. La Confrérie du thorium veut la rendre au Sous-chef Scrange.",h="La Tuyère de forge est un outil volé par les Dark Iron dwarves dans la Gorge des Vents brûlants.",kw={"outil de forge","dark iron dwarves","fourneau","gorge des vents brûlants","tuyère de forge","sous-chef scrange","confrérie du thorium","tuyère"},ang={["profession:Blacksmithing"]="En tant que forgeron, vous savez qu’une tuyère alimente un fourneau en air et attise le feu pour travailler le métal."},sec={{t="Un outil volé",b="La Confrérie du thorium recherche la Tuyère de forge dans la Gorge des Vents brûlants, où des Dark Iron dwarves l’ont volée. Cet outil sert dans une forge. L’air soufflé dans son tube attise le feu du fourneau et ramollit le métal pour le travailler."}},faq={{q="Qu’est-ce qu’une Tuyère de forge ?",a="Une Tuyère de forge est un tube qui souffle de l’air dans un fourneau. Le feu devient plus ardent et le métal peut être travaillé.",al={"qu’est-ce qu’une tuyère","outil tuyère","tube de forge"}},{q="Qui a volé la tuyère ?",a="La Confrérie du thorium pense que des Dark Iron dwarves ont volé la Tuyère de forge dans la Gorge des Vents brûlants.",al={"qui l’a prise","vol des dark iron dwarves","qui a volé l’outil"}},{q="Qui veut récupérer la tuyère ?",a="La Confrérie du thorium veut que la Tuyère de forge soit rendue au Sous-chef Scrange, dans la Gorge des Vents brûlants.",al={"qui la veut","rendre la tuyère","objet de la confrérie du thorium"}},{q="Où la tuyère a-t-elle été volée ?",a="La Tuyère de forge a été volée par des Dark Iron dwarves dans la Gorge des Vents brûlants.",al={"où a-t-elle disparu","emplacement de la tuyère","où trouver l’outil"}}},fp="15,154,13.240.0,26.105.0,21.94.0,26.98.0,28.69.0"}
P.entries["item:smoky-iron-ingot"] = {n="Lingot de fer cendré",s="À la Combe des Cisailles, les kobolds fondent des lingots de fer cendré avec le minerai extrait des Serres-Rocheuses. Les armuriers orcs prisent ces barres pour fabriquer des cottes de mailles solides destinées aux guerriers de la Horde.",h="À la Combe des Cisailles, les kobolds fondent des lingots de fer cendré avec le minerai extrait des...",kw={"brutal armor","kobold","lingot de fer cendré","les serres-rocheuses","thun'grim firegaze","guerrier","combe des cisailles"},ang={["class:Warrior"]="Pour les guerriers de la Horde, rassembler ces lingots met leur endurance à l’épreuve dans les Serres-Rocheuses. Ces barres sont nécessaires pour forger le Brutal Hauberk.",["profession:Blacksmithing"]="Ces lingots montrent comment les mineurs kobolds fondent le métal avec des méthodes rudimentaires, tandis que les forgerons expérimentés emploient des techniques raffinées."},sec={{t="Métallurgie rudimentaire des kobolds",b="Les kobolds fondent des lingots de fer cendré dans les tunnels de la Combe des Cisailles, dans les Serres-Rocheuses. Ils extraient le minerai des pentes rocheuses et le chauffent sur des feux rudimentaires et fumants. Des résidus et du charbon s’accrochent aux barres, mais le métal reste dense et résistant."},{t="La forge de Brutal Armor",b="Thun'grim Firegaze est un armurier orc presque aveugle, installé dans un campement escarpé qui surplombe les Tarides. Il demande ces lingots pour fabriquer des armures destinées aux guerriers aguerris de la Horde. Avec des barres de fer raffiné, de l’azurite en poudre et du phlogiston volatil, le métal cendré forme un noyau résistant pour les Brutal Hauberk."}},faq={{q="D’où viennent les lingots de fer cendré ?",a="Les kobolds des sites de fouilles et des tunnels de l’est des Serres-Rocheuses transportent des lingots de fer cendré. Parmi eux se trouvent des mineurs, des tailleurs de pierre, de la vermine, des géomanciens et leurs maîtres.",al={"où trouver des lingots de fer cendré","emplacement des lingots de fer cendré","qui lâche des lingots de fer cendré"}},{q="À quoi servent les lingots de fer cendré ?",a="Les guerriers qui répondent à l’appel de Thun'grim Firegaze rassemblent des lingots de fer cendré. Le maître armurier vit sur les sommets près de la Croisée, dans les Tarides, et a besoin de quinze lingots pour forger le Brutal Hauberk.",al={"utilité des lingots de fer cendré","à quoi sert le fer cendré","objet de quête de brutal armor"}},{q="Pourquoi dit-on que les lingots sont « cendrés » ?",a="Les kobolds utilisent des feux rudimentaires et peu ardents pour fondre le métal dans leurs tunnels sombres. La suie, la poussière de charbon et la cendre s’accrochent aux lingots et leur ôtent tout éclat.",al={"pourquoi est-il cendré","histoire du fer cendré"}},{q="N’importe quel forgeron peut-il travailler ces lingots ?",a="Non. Ces barres irrégulières et couvertes de suie ne conviennent pas au travail habituel des forgerons. Seuls des artisans comme Thun'grim Firegaze savent les façonner en équipement de combat sur mesure.",al={"les joueurs peuvent-ils forger le fer cendré","le fer cendré est-il une marchandise"}}},fx={["9ee5c553"]={q="D'où provient le Lingot de fer cendré et qui l'a fabriqué ?",a="Ces lingots sont extraits et fondus par les kobolds de la Combe des Cisailles dans Les Serres-Rocheuses. Au fond de leurs tunnels souterrains, les mineurs et la vermine déterrent le minerai brut et le coulent en lingots de fer utilisables pour renforcer leurs opérations souterraines et armer leurs bandes de guerre.",al={"source du lingot de fer cendré","d'où viennent les lingots de fer cendré","qui fabrique le lingot de fer cendré"}},["18404e72"]={q="Qu'est-ce qu'un Lingot de fer cendré ?",a="Les Lingots de fer cendré sont des barres de fer sombre, grossièrement fondues et striées de suie, détenues par les kobolds Windshear qui creusent au plus profond des Serres-Rocheuses. Rudimentaires comparés aux ouvrages de métal raffiné, ils possèdent néanmoins la solidité nécessaire aux forgerons habiles qui souhaitent fabriquer des armures lourdes et durables.",al={"qu'est-ce qu'un lingot de fer cendré","informations lingot de fer cendré","à propos du lingot de fer cendré"}},["8ab45f92"]={q="Pourquoi recherche-t-on le Lingot de fer cendré ?",a="Thun'grim Firegaze, un maître forgeron orc presque aveugle établi au sommet des pitons des Tarides, a besoin de quinze de ces lingots pour fabriquer Brutal Armor pour les guerriers méritants de la Horde. Associé à d'autres composants alchimiques et minéraux rares, ce métal brut sert de matériau de base à une armure conçue pour résister aux combats les plus brutaux.",al={"pourquoi obtenir un lingot de fer cendré","qui veut un lingot de fer cendré","histoire et usage du lingot de fer cendré"}}},fp="16,164,23.242.0,24.281.0,37.182.0,36.194.0,40.159.0,43.166.0"}
P.entries["item:smoldering-embers"] = {n="Braises fumantes",s="Dans le Val calciné, des Braises fumantes subsistent quand les élémentaires de feu sont anéantis. Les Sentinelles elfes de la nuit les recueillent pour prouver que les incendies sont maîtrisés.",h="Dans le Val calciné, des Braises fumantes subsistent quand les élémentaires de feu sont anéantis.",kw={"destructeur brûlant","ravageur brûlant","le val calciné","enraged spirits","kaela ombrelance","esprit de la flamme renégat errant","braises fumantes","les serres-rocheuses","kapitalrisk"},ang={["class:Druid"]="En tant que druide, vous voyez dans ces braises la preuve tragique que la cupidité industrielle a déséquilibré la nature. La fureur élémentaire empêche le sol étouffé sous les cendres de se régénérer.",["race:NightElf"]="Pour les elfes de la nuit, l’incendie du Val calciné est une blessure infligée à Kalimdor. Recueillir ses braises est un devoir solennel : purger la profanation étrangère et rétablir la paix sous le regard d’Elune."},sec={{t="Vestiges du Val calciné",b="L’exploitation forestière et l’industrie de la KapitalRisk ont embrasé le Val calciné. Leurs activités ont réveillé des forces destructrices au plus profond de la terre. Des Ravageurs brûlants, des Destructeurs brûlants et des Esprits de la flamme renégats errants ont déferlé dans le bassin calciné. Quand un élémentaire de feu est anéanti, il laisse un cœur couvert de cendres. Cette cendre est une Braise fumante, preuve que les incendies qui ravagent le val sont en train d’être maîtrisés."}},faq={{q="D’où viennent les Braises fumantes ?",a="Les Braises fumantes proviennent des élémentaires de feu du Val calciné, dans le sud des Serres-Rocheuses. Les Ravageurs brûlants, les Destructeurs brûlants et les Esprits de la flamme renégats errants en laissent tous derrière eux.",al={"où trouver des braises fumantes","qui laisse tomber des braises fumantes","source des braises fumantes"}},{q="Pourquoi Kaela Ombrelance veut-elle ces braises ?",a="Kaela Ombrelance veut ces braises comme preuve que les élémentaires de feu du Val calciné sont éliminés. Elle croit que cette terre meurtrie ne peut guérir sous la grâce d’Elune tant que des esprits violents rôdent sans entrave.",al={"pourquoi recueillir des braises fumantes","braises de kaela ombrelance","objectif des esprits enragés"}},{q="Qu’est-ce qui a fait apparaître les élémentaires de feu dans le Val calciné ?",a="La KapitalRisk a fait apparaître des élémentaires de feu dans le Val calciné en défrichant l’ancienne forêt à l’aide de machines agressives et de brûlis indiscriminés. Ses activités imprudentes ont déstabilisé la terre et libéré des élémentaires hostiles de flamme et de pierre. Ces forces ont chassé les gobelins.",al={"qu’est-il arrivé au val calciné","pourquoi y a-t-il des élémentaires de feu dans les serres-rocheuses","esprits de feu de la kapitalrisk"}}},fx={["4d13fc7e"]={q="Qu'est-ce que des Braises fumantes ?",a="Les Braises fumantes sont les restes physiques brûlants laissés par les élémentaires de feu destructeurs infestant Le Val calciné. Ces restes incandescents persistent après que des créatures comme les dévastateurs brûlants, les esprits de flamme scélérats et les destructeurs brûlants sont tués, servant de preuve tangible que leur déchaînement ardent à travers la forêt en ruine a été réprimé.",al={"que sont les braises fumantes","lore des braises fumantes","qu'est-ce qu'une braise fumante"}}},fp="17,159,28.404.0,37.182.0,45.208.0,62.277.0"}
P.entries["item:smotts-cutlass"] = {n="Smotts' Cutlass",s="Le Captain Smotts veut récupérer son coutelas dans la Vallée de Strangleronce. Il vous demande d’apporter du vin et des Barbecued Buzzard Wings à son vieux canot de sauvetage, sur la côte.",h="Le Captain Smotts veut récupérer son coutelas dans la Vallée de Strangleronce.",kw={"barbecued buzzard wings","captain smotts","coutelas","negolash","canot de sauvetage détruit","coutelas de smotts","vallée de strangleronce"},sec={{t="La lame d’un capitaine",b="Sprogger, le cuisinier du navire, vous demande d'apporter du vin et ses Barbecued Buzzard Wings à l'ancien canot de sauvetage de l'équipage, sur la côte. Negolash, le géant affamé qui s'est précipité vers la cuisine quand les géants ont détruit le navire, apprécie les deux. La nourriture attirera le géant, afin que le capitaine Smotts puisse récupérer son coutelas. La lame est entre les mains de Negolash."}},faq={{q="À qui appartient le Smotts' Cutlass ?",a="Le Captain Smotts possède le coutelas et en demande la restitution.",al={"propriétaire du coutelas de smotts","épée de capitaine","qui est smotts"}},{q="Comment Negolash a-t-il obtenu le coutelas ?",a="Negolash a pris le coutelas après que le géant a détruit le navire du Captain Smotts.",al={"coutelas de negolash","comment le géant l’a obtenu","coutelas volé"}},{q="Pourquoi Smotts veut-il du vin et des ailes de busard ?",a="Negolash raffole du vin et des Barbecued Buzzard Wings de Sprogger. Sprogger vous demande donc de les déposer dans l'ancien canot de sauvetage de l'équipage pour attirer le géant.",al={"appât pour negolash","pourquoi du vin et des ailes","nourriture de smotts"}},{q="Où se trouve le Smotts' Cutlass ?",a="Negolash a le Smotts' Cutlass dans la Vallée de Strangleronce.",al={"emplacement du coutelas","où est la lame de smotts","objet de negolash"}}},fp="15,148,17.341.0,25.56.0,33.73.1,44.137.0,25.51.1"}
P.entries["item:snapshot-of-gammerita"] = {n="Snapshot of Gammerita",s="Dans les Hinterlands, Curgle immortalise Gammerita avec le Preneur d’images FX. Daryn Lightwind, à Rut’theran Village, veut ce cliché pour ses études.",h="Dans les Hinterlands, Curgle immortalise Gammerita avec le Preneur d’images FX.",kw={"daryn lightwind","gammerita","hinterlands","rut’theran village","photo de gammerita","le preneur d'images fx"},sec={{t="Un portrait pour Daryn",b="Curgle prête le Preneur d’images FX pour photographier Gammerita dans les Hinterlands. Daryn Lightwind attend le cliché à Rut’theran Village et affirme que l’invention de Curgle a répondu à ses attentes."}},faq={{q="Qui est Gammerita ?",a="Gammerita est une créature des Hinterlands, et Daryn Lightwind demande son portrait.",al={"gammerita","qui est gammerita"}},{q="Qui veut ce cliché ?",a="Daryn Lightwind le veut pour ses études ; elle attend à Rut’theran Village.",al={"qui veut la photo de gammerita","pour qui est le cliché"}},{q="Comment le cliché a-t-il été pris ?",a="Le Preneur d’images FX de Curgle prend le cliché lorsqu’on le dirige vers Gammerita.",al={"comment photographier gammerita","photo avec le preneur d’images"}},{q="Qu’est-ce que le Preneur d’images FX ?",a="Le Preneur d’images FX est une invention de Curgle, prêtée pour photographier Gammerita.",al={"preneur d’images","invention de curgle"}},{q="Où trouver Gammerita ?",a="Gammerita se trouve dans les Hinterlands.",al={"emplacement de gammerita","où trouver gammerita"}}},fp="21,161,19.206.0,17.85.0,24.76.0,27.71.0,29.93.0,27.32.0"}
P.entries["item:snellig-s-snuffbox"] = {n="Tabatière de Snellig",s="Dans la flotte perdue, la tabatière de Snellig reste auprès de son propriétaire mort-vivant, parmi les épaves. Le Second Fitzsimmons, à Port de Menethil, la veut comme preuve que son compagnon d’équipage maudit a trouvé le repos.",h="Dans la flotte perdue, la tabatière de Snellig reste auprès de son propriétaire mort-vivant, parmi les épaves.",kw={"équipage maudit","fitzsimmons","kul tiras","la flotte perdue","snellig","tabatière","third fleet","les paluns"},ang={["faction:Alliance"]="En tant qu’aventurier de l’Alliance, récupérer les possessions des marins kultirassiens tombés au combat et apaiser leurs esprits maudits est un devoir sinistre envers un vieil allié naval."},sec={{t="Un souvenir de la Third Fleet",b="Le Second Snellig serre toujours sa tabatière dans une épave au large du nord des Paluns. La Third Fleet de Kul Tiras s’y est échouée, et ses marins et officiers se sont noyés sous l’effet d’une puissance mystérieuse liée à un trésor caché à bord des navires. Lié à cette puissance, l’équipage noyé s’est relevé sous la forme d’esprits torturés et de morts-vivants squelettiques.\n\nSnellig hante la cale pourrissante de l’épave la plus proche du rivage. Sa tabatière est un souvenir ordinaire de sa vie de mortel en mer. Le Second Fitzsimmons, seul survivant de la catastrophe, veut qu’on la lui rapporte comme preuve qu’au moins un compagnon d’équipage disparu a été libéré de ses tourments."}},faq={{q="Qu’est-ce que la tabatière de Snellig ?",a="Le Second Snellig possédait autrefois le petit contenant personnel appelé Tabatière de Snellig. Son vestige mort-vivant l’emporte à bord d’une épave au large de la côte nord des Paluns.",al={"qu’est-ce que cet objet","tabatière de snellig","tabatière"}},{q="Où trouver la tabatière de Snellig ?",a="Vous pouvez prendre la tabatière sur le Second Snellig, qui hante la cale de l’épave la plus proche du rivage, à la flotte perdue, dans le nord-ouest des Paluns.",al={"où trouver la tabatière de snellig","trouver snellig","emplacement du second snellig"}},{q="Qui veut cette tabatière ?",a="Le Second Fitzsimmons veut que vous lui apportiez la tabatière à Port de Menethil. Seul survivant vivant de la Third Fleet, il la réclame comme preuve que Snellig a trouvé le repos.",al={"qui prend la tabatière","à qui rapporter cet objet","quête de fitzsimmons"}},{q="Pourquoi le Second Snellig est-il maudit ?",a="Fitzsimmons affirme qu’un trésor sombre et terrible, caché à bord d’un navire de la Third Fleet, a condamné les équipages lorsque les navires ont fait naufrage. Leurs âmes restent prisonnières des membrures pourries, privées de repos.",al={"pourquoi snellig est-il mort-vivant","malédiction de la flotte perdue","malédiction de la third fleet"}}},fp="18,184,29.620.0,27.168.0,35.152.0,24.167.0,33.194.0"}
P.entries["item:snufflenose-command-stick"] = {n="Bâton de commandement de Sniffetarin",s="À Cabestan, Mebok Mizzyrix envoie des gaufres dressées chercher des Blueleaf Tubers dans le Kraal de Tranchebauge.",h="À Cabestan, Mebok Mizzyrix envoie des gaufres dressées chercher des Blueleaf Tubers dans le Kraal de...",kw={"racines de feuillebleue","bâton de commandement","gaufre","mebok mizzyrix","cabestan","kraal de tranchebauge","museau renifleur","les tarides"},ang={["profession:Cooking"]="Les Blueleaf Tubers sont recherchés comme mets délicats dans le monde entier. Pour les trouver, il faut un animal dressé et le bâton de son maître, plutôt que des ustensiles de cuisine ordinaires."},sec={{t="Une baguette pour les rongeurs",b="Mebok Mizzyrix a dressé des gaufres à museau renifleur pour trouver des Blueleaf Tubers au cœur du Kraal de Tranchebauge. Les racines se cachent sous des tunnels épineux, où il est presque impossible de les trouver sans aide. Mebok est un marchand de Cabestan et évite d'entrer lui-même dans les repaires des quillboars. Il confie donc aux aventuriers le Bâton de commandement de Sniffetarin pour guider les gaufres. À cinquante pas de distance, le bâton les dirige pour flairer et déterrer les racines."}},faq={{q="À quoi sert le Bâton de commandement de Sniffetarin ?",a="Le Bâton de commandement de Sniffetarin guide une gaufre à museau renifleur dressée jusqu'aux Blueleaf Tubers cachés dans le Kraal de Tranchebauge. Pointez-le vers une gaufre, et elle suit la piste pour déterrer les racines.",al={"utiliser le bâton de commandement","fonction du bâton de commandement","utilité du bâton de commandement"}},{q="Où obtenir le Bâton de commandement de Sniffetarin ?",a="Vous obtenez le Bâton de commandement de Sniffetarin à Cabestan, juste devant l'atelier de Mebok Mizzyrix. Il est accompagné d'une caisse contenant une gaufre dressée et d'un manuel d'instructions.",al={"où obtenir le bâton de commandement","emplacement du bâton de commandement","qui donne le bâton de commandement"}},{q="Pourquoi Mebok Mizzyrix veut-il des Blueleaf Tubers ?",a="Mebok Mizzyrix recherche des Blueleaf Tubers, car ces mets rares lui rapportent gros auprès de ses contacts fortunés dans le monde de la gastronomie. Ils poussent dans les profondeurs des Tarides, en territoire quillboar. Il engage donc des aventuriers pour les récolter.",al={"pourquoi les tubercules","utilité des blueleaf tubers","pourquoi mebok veut des tubercules"}},{q="Peut-on garder le bâton après avoir trouvé les tubercules ?",a="Non. Après avoir récolté les tubercules demandés, vous rapportez à Mebok, à Cabestan, le Bâton de commandement de Sniffetarin et la caisse de transport avec votre récolte.",al={"garder le bâton de commandement","rendre le bâton de commandement"}}},fx={["8cc828c2"]={q="Qu'est-ce que le Bâton de commandement de Sniffetarin ?",a="Le Bâton de commandement de Sniffetarin est l'outil de manipulation breveté de la société Snuff Inc., fourni avec les gophers dressés de l'entrepreneur gobelin Mebok Mizzyrix à Cabestan. Il est conçu spécifiquement pour diriger les gophers sniffetarin dressés, leur donnant le signal pour déterrer des mets délicats enfouis et insaisissables qu'un éclaireur ordinaire ignorerait complètement.",al={"qu'est-ce que le bâton de commandement","bâton de sniffetarin","qu'est-ce que le bâton de commandement de sniffetarin"}},["9fdd5faa"]={q="D'où provient le Bâton de commandement de Sniffetarin et qui l'a créé ?",a="Le bâton de commandement est un produit breveté de Snuff Inc., dont le propriétaire Marwig Rustbolt explique l'utilisation dans le Manuel d'utilisateur de Sniffetarin. Mebok Mizzyrix à Cabestan a dressé ses gophers sniffetarin pour récolter des mets délicats rares et garde les bâtons de commandement, les caisses et les manuels ensemble afin que les employés puissent contrôler les créatures correctement.",al={"qui a créé le bâton de commandement","origine du bâton de commandement","d'où vient le bâton de commandement"}},fb1cfa60={q="Pourquoi quelqu'un voudrait-il le Bâton de commandement de Sniffetarin ?",a="Les rares tubercules de feuille-bleue sont impossibles à repérer sans aide sous les ronces du Kraal de Tranchebauge. Le bâton de commandement est vital car il oblige un gopher sniffetarin dressé à renifler à cinquante pas de distance et à excaver les tubercules, qui peuvent ensuite être rapportés à Mebok Mizzyrix pour une belle récompense.",al={"pourquoi as-tu besoin du bâton","pourquoi le bâton de commandement est-il recherché","pourquoi obtenir le bâton de commandement de sniffetarin"}}},fp="25,93,17.432.0,47.178.0,50.166.0,45.247.0,54.141.0"}
P.entries["item:snufflenose-owner-s-manual"] = {n="Manuel d'utilisateur de Sniffetarin",s="À Cabestan, près de Mebok Mizzyrix, le Manuel d'utilisateur de Sniffetarin explique comment envoyer un Snufflenose Gopher dressé chercher des Blueleaf Tubers au Kraal de Tranchebauge. Marwig Rustbolt de Snuff Inc. l'a écrit dans ce but.",h="À Cabestan, près de Mebok Mizzyrix, le Manuel d'utilisateur de Sniffetarin explique comment envoyer un...",kw={"racines de feuillebleue","gopher","manuel","mebok mizzyrix","cabestan","kraal de tranchebauge","snufflenose"},ang={["profession:Cooking"]="Le manuel explique comment déterrer les Blueleaf Tubers, une racine souterraine prisée comme mets rare par les gourmets et les marchands d'Azeroth."},sec={{t="Guide pratique d'un gobelin",b="Marwig Rustbolt de Snuff Inc. a écrit ce guide pour expliquer comment s'occuper des Snufflenose Gophers dressés de l'entreprise. Leur odorat aiguisé leur permet de trouver des Blueleaf Tubers enfouis à cinquante pas de distance. Le manuel explique comment libérer un gopher d'une caisse aérée et guider son fouissage avec un bâton de commande. Les prospecteurs le conduisent à travers les épines du Kraal de Tranchebauge et les tunnels des quilboars à la recherche de tubers."}},faq={{q="À quoi sert le Manuel d'utilisateur de Sniffetarin ?",a="Le manuel explique comment libérer de sa caisse le Snufflenose Gopher dressé de Mebok Mizzyrix et le guider avec un bâton de commande. Le gopher cherche des Blueleaf Tubers au Kraal de Tranchebauge.",al={"à quoi sert le manuel","pourquoi lire le manuel","utilité du manuel"}},{q="Où trouver le manuel ?",a="Vous trouverez le manuel à Cabestan, près de Mebok Mizzyrix, des caisses et des bâtons de commande utilisés pour récolter les tubers.",al={"emplacement du manuel","où se trouve le livre","comment obtenir le manuel"}},{q="Pourquoi utiliser des Snufflenose Gophers pour trouver des Blueleaf Tubers ?",a="Les Blueleaf Tubers sont enfouis profondément dans le Kraal de Tranchebauge, où les humanoïdes les repèrent à peine. Un gopher dressé peut en sentir un à cinquante pas de distance.",al={"pourquoi utiliser des gophers","peut-on trouver des tubers sans gophers"}},{q="Qui a écrit le manuel ?",a="Marwig Rustbolt, propriétaire de Snuff Inc., a signé le manuel. Il l'a écrit pour apprendre aux nouveaux propriétaires à nourrir et promener leurs gophers, et à les diriger avec le bâton de commande breveté.",al={"auteur du manuel","qui l'a créé"}}},fx={["1c231f00"]={q="Qu'est-ce que le Manuel d'utilisateur de Sniffetarin ?",a="Il s'agit d'un manuel d'instruction fourni avec un gopher sniffetarin dressé et un bâton de commandement. Le manuel guide les aventuriers sur la façon de manipuler la créature dans les tunnels souterrains du Kraal de Tranchebauge, expliquant comment commander au gopher de renifler les insaisissables tubercules de feuille-bleue souterrains.",al={"qu'est-ce que le manuel d'utilisateur de sniffetarin","identité du manuel de sniffetarin","qu'est-ce que le manuel"}}},fp="26,193,26.388.0,54.184.0,28.114.0,59.142.0,21.165.0"}
P.entries["item:sodium-nitrate"] = {n="Nitrate de sodium",s="À Bael Modan, le Nitrate de sodium entre dans les charges que les nains utilisent contre la roche des Tarides du sud. Gann Cime-de-pierre cherche ce produit chimique pour fabriquer des charges contre la forteresse.",h="À Bael Modan, le Nitrate de sodium entre dans les charges que les nains utilisent contre la roche des Tarides...",kw={"bael modan","bael'dun","blackforge","gann cime-de-pierre","nitroglycérine","revenge of gann","nitrate de sodium","pulpe de bois"},ang={["profession:Engineering"]="Les ingénieurs reconnaissent dans le nitrate de sodium, la nitroglycérine et la Pulpe de bois la recette de la dynamite stabilisée, à la base des charges improvisées de Gann.",["race:Tauren"]="En tant que tauren, Gann Cime-de-pierre recourt aux produits chimiques des nains pour riposter à la destruction de ses terres ancestrales."},sec={{t="Démolition industrielle",b="À Bael Modan, les excavateurs nains utilisent le Nitrate de sodium pour percer la roche des Tarides du sud. L’expédition de Bael'dun a pénétré sur les terres ancestrales de la tribu Stonespire avec des engins de terrassement et des réactifs de dynamitage. Fusiliers, soldats et officiers transportent ce produit chimique dans le site d’excavation et la forteresse voisine."},{t="Riposte et représailles",b="Gann Cime-de-pierre a observé les envahisseurs après qu’ils ont dévasté la patrie de sa tribu et récupéré leurs schémas d’ingénierie. Les attaques ordinaires ne pouvaient pas franchir les défenses du donjon, alors le tauren exilé retourne contre les nains leurs fournitures de dynamitage. Il mélange le Nitrate de sodium pillé avec de la nitroglycérine et de la Pulpe de bois pour fabriquer des charges destinées à ébranler les fondations de Bael Modan."}},faq={{q="À quoi sert le Nitrate de sodium dans les Tarides ?",a="Les nains de Forgefer utilisent le Nitrate de sodium dans des explosifs pour dynamiter le sol rocheux de leur site d’excavation. Gann Cime-de-pierre le mélange avec de la nitroglycérine et de la Pulpe de bois pour fabriquer des charges contre Bael Modan.",al={"utilité du nitrate de sodium","à quoi sert le nitrate de sodium"}},{q="D’où vient le Nitrate de sodium ?",a="Les forces naines stationnées à Bael Modan, dans les Tarides du sud, transportent du Nitrate de sodium. Fusiliers, soldats, officiers et commandants comme Lord Cyrik Blackforge en gardent sur eux.",al={"qui laisse tomber le nitrate de sodium","où trouver du nitrate de sodium"}},{q="Pourquoi Gann Cime-de-pierre a-t-il besoin de ce produit chimique ?",a="Gann Cime-de-pierre a perdu son village ancestral à cause des excavations naines. Sans équipement de siège lourd, il a étudié leurs schémas et entrepris de fabriquer des charges capables de briser leurs positions fortifiées avec les propres fournitures des nains.",al={"pourquoi gann veut du nitrate de sodium","explosifs de gann cime-de-pierre"}},{q="Le Nitrate de sodium est-il dangereux à lui seul ?",a="À lui seul, le nitrate de sodium est un oxydant et un sel chimique, pas un explosif instantané. Mélangé à une source de combustible et à des produits chimiques sensibles aux chocs comme la nitroglycérine, il devient dangereux et instable.",al={"le nitrate de sodium est-il un explosif"}}},fx={caaef0db={q="Qu'est-ce que le Nitrate de sodium ?",a="Le nitrate de sodium est un agent chimique volatil stocké par les forces expéditionnaires naines stationnées à Bael Modan. Bien que relativement stable lorsqu'il est stocké, les nains comptent sur lui comme composant principal pour composer des charges explosives de haute qualité utilisées pour faire exploser la pierre solide sur leurs sites de fouilles. Entre les mains d'un saboteur intelligent, cependant, il peut tout aussi facilement être réutilisé pour démanteler la forteresse elle-même.",al={"qu'est-ce que le nitrate de sodium","lore du nitrate de sodium","nitrate de sodium tarides"}}},fp="14,175,21.313.0,25.375.1,47.185.0,36.176.0,44.233.0,39.199.0"}
P.entries["item:soft-shelled-clam-meat"] = {n="Soft-Shelled Clam Meat",s="La Soft-Shelled Clam Meat constitue un appât irrésistible pour les poissons près de Proie-de-l’Ombre. Mai'Lahii vous demande de lui en rapporter depuis le navire naufragé au nord.",h="La Soft-Shelled Clam Meat constitue un appât irrésistible pour les poissons près de Proie-de-l’Ombre.",kw={"appât de palourde","désolace","pêche","mai'lahii","proie-de-l'ombre","chair de palourde à coquille molle","épave"},sec={{t="Un appât pour Mai'Lahii",b="À Proie-de-l’Ombre, Mai'Lahii préfère la Soft-Shelled Clam Meat pour pêcher. Elle dit que les poissons ne peuvent pas y résister et vous demande de lui rapporter dix morceaux des palourdes près du navire naufragé au nord du village."}},faq={{q="À quoi sert la chair de palourde à coquille molle ?",a="Mai'Lahii, à Proie-de-l'Ombre, utilise la chair de palourde à coquille molle comme appât pour pêcher.",al={"utilité de la chair de palourde","chair de palourde à coquille molle","appât de palourde"}},{q="Où trouver des palourdes à coquille molle ?",a="Des palourdes à coquille molle se trouvent près de l'épave au large de la côte, au nord de Proie-de-l'Ombre.",al={"emplacement des palourdes","où trouver des palourdes","palourdes près du navire au nord"}},{q="Qui veut la chair de palourde ?",a="À Proie-de-l’Ombre, Mai'Lahii vous demande de lui rapporter dix morceaux de Soft-Shelled Clam Meat.",al={"pour qui est la chair de palourde","appât pour mai'lahii","qui a besoin de palourdes"}},{q="Pourquoi Mai'Lahii veut-il aller pêcher ?",a="Mai'Lahii dit que son féticheur lui a conseillé d’aller pêcher pour soulager son mal de tête, et elle se sent mieux après que vous lui avez apporté la chair de palourde.",al={"mal de tête de mai'lahii","raison de pêcher","conseil du féticheur"}}},fp="22,153,18.206.0,35.80.0,36.87.0,24.91.0,38.127.1"}
P.entries["item:solid-crystal-leg-shaft"] = {n="Solid Crystal Leg Shaft"}
P.entries["item:solomon-s-plea-to-darkshire"] = {n="Demande d'aide de Salomon à Sombre-comté",s="Comté-du-Lac se tourne vers Sombre-Comté face aux menaces grandissantes. Le Magistrat Salomon demande au Seigneur Ello Bouclenoire d'envoyer les Veilleurs vers le nord pour défendre les Carmines.",h="Comté-du-Lac se tourne vers Sombre-Comté face aux menaces grandissantes.",kw={"sombre-comté","bois de la pénombre","comté-du-lac","seigneur ello bouclenoire","magistrat salomon","un message pour darkshire","les veilleurs","les carmines","demande de salomon"},ang={["faction:Alliance"]="Pour l'Alliance, la demande de Salomon montre que les colonies du sud cherchent à s'entraider tandis que Hurlevent leur apporte peu de soutien.",["race:Human"]="En tant que voyageur humain, vous transportez un message qui témoigne du danger menaçant les Carmines et le Bois de la Pénombre."},sec={{t="Un appel à l'aide désespéré",b="Des orcs Rochenoire, des gnolls et des murlocs attaquent Comté-du-Lac, tandis que peu de renforts arrivent de Hurlevent. Le Magistrat Salomon adresse une demande officielle au maire Ello Bouclenoire, à Sombre-Comté, et lui demande d'envoyer des miliciens des Veilleurs vers le nord, dans les Carmines. Alors que le soutien militaire central fait défaut dans tout le sud d'Azeroth, les colonies humaines doivent s'entraider pour survivre."},{t="La sombre situation de Sombre-Comté",b="Sombre-Comté peine à défendre ses frontières contre les morts-vivants, les bêtes voraces et les ténèbres qui gagnent le Bois de la Pénombre. Les Veilleurs sont débordés et la ville ne peut envoyer de défenseurs dans les Carmines lorsque la demande de Salomon arrive."}},faq={{q="Qu'est-ce que la Demande d'aide de Salomon à Sombre-comté ?",a="Dans sa lettre urgente au Seigneur Ello Bouclenoire, le Magistrat Salomon demande aux Veilleurs d'aider à défendre les Carmines contre les orcs Rochenoire et les gnolls.",al={"lettre de salomon à sombre-comté","que demande salomon","lettre de comté-du-lac au bois de la pénombre"}},{q="Pourquoi Comté-du-Lac demande-t-il une aide militaire à Sombre-Comté plutôt qu'à Hurlevent ?",a="Hurlevent a envoyé peu de troupes de garnison dans ses territoires éloignés, en raison de l'inertie politique et de conflits internes. Seul face à des attaques toujours plus nombreuses, le Magistrat Salomon cherche l'aide des villes humaines voisines.",al={"pourquoi demander à sombre-comté","pourquoi pas hurlevent","pourquoi salomon a-t-il besoin des veilleurs"}},{q="Qui est le Seigneur Ello Bouclenoire ?",a="Le Seigneur Ello Bouclenoire est le maire de Sombre-Comté et le principal dirigeant civil du Bois de la Pénombre. Il dirige la ville et coordonne les Veilleurs, sa force de défense civile contre les dangers de la forêt.",al={"qui est bouclenoire","maire de sombre-comté","seigneur ello"}},{q="Sombre-Comté peut-il vraiment envoyer les Veilleurs aider Comté-du-Lac ?",a="Non. Le Bois de la Pénombre fait face aux morts-vivants, aux worgens sauvages et à la magie noire, et les Veilleurs peinent à défendre le périmètre de Sombre-Comté. Ils ne peuvent envoyer de combattants jusqu'aux Carmines.",al={"sombre-comté aide-t-il","les veilleurs viendront-ils","bouclenoire a-t-il envoyé des gardes"}}},fx={a3b7e1d6={q="D'où provient la Demande d'aide de Salomon à Sombre-comté et qui l'a rédigée ?",a="La lettre a été rédigée directement par le Magistrat Salomon, le chef de la ville de Comté-du-Lac dans Les Carmines. Avec les orcs de Rochenoire faisant pression sur sa ville et Hurlevent incapable de fournir des renforts royaux, Salomon a rédigé l'appel urgent lui-même depuis l'hôtel de ville de Comté-du-Lac dans l'espoir d'obtenir de l'aide des colonies voisines.",al={"qui a écrit la demande de salomon","origine de la demande d'aide de salomon à sombre-comté","qui a fait la demande de salomon"}},["5061acb5"]={q="Pourquoi le seigneur Ello Bouclenoire veut-il la Demande d'aide de Salomon à Sombre-comté ?",a="Le seigneur Ello Bouclenoire a besoin de cette lettre car elle détaille formellement la défense désespérée de Comté-du-Lac et la demande directe d'assistance militaire du magistrat Salomon. En tant que maire de Sombre-comté et commandant des Veilleurs, Bouclenoire se fie à des dépêches officielles comme celle-ci pour comprendre les menaces qui pèsent sur ses voisins de l'Alliance et évaluer si sa ville peut se permettre de détacher des gardes.",al={"pourquoi livrer la demande d'aide de salomon","pourquoi bouclenoire a besoin de la lettre","but de la demande d'aide de salomon à sombre-comté"}}},fp="27,149,24.361.0,23.222.1,36.139.0,73.206.0,27.193.0,63.165.1"}
P.entries["item:solomon-s-plea-to-westfall"] = {n="Demande d'aide de Salomon à la marche de l'Ouest",s="À Comté-du-Lac, le Magistrat Salomon demande l’aide de la Marche de l’Ouest, car des orcs Rochenoire et des gnolls menacent Les Carmines. L’armée royale de Hurlevent n’ayant pas répondu, il demande à Gryan Roidemantel d’envoyer la People's Militia.",h="À Comté-du-Lac, le Magistrat Salomon demande l’aide de la Marche de l’Ouest, car des orcs Rochenoire et des...",kw={"gryan roidemantel","comté-du-lac","magistrat salomon","people's militia","les carmines","demande d’aide de salomon","armée de hurlevent","marche de l’ouest"},ang={["faction:Alliance"]="Pour l’Alliance, l’appel de Salomon montre que les villes périphériques se tournent vers les volontaires locaux quand les troupes royales tardent à arriver.",["race:Human"]="En tant qu’humain, vous pouvez voir à quel point les communautés rurales sont sous pression. L’absence du roi et la négligence politique rendent les terres frontalières vulnérables."},sec={{t="Un appel désespéré à l’aide",b="Des orcs Rochenoire et des gnolls hostiles menacent Les Carmines, tandis que le Magistrat Salomon se retrouve isolé à Comté-du-Lac. L’armée royale de Hurlevent n’est pas arrivée en force pour défendre les frontières de la région. Faute de temps pour attendre la capitale, Salomon écrit en dehors de l’armée régulière. Il a appris qu’une force de défense volontaire se formait à l’ouest, en Elwynn. Il fait donc appel à la People's Militia."},{t="Au-delà de la frontière",b="Salomon adresse son message à Gryan Roidemantel, un guerrier vétéran qui organise la défense des confins de la Marche de l’Ouest. Il espère que Roidemantel pourra envoyer des combattants à Comté-du-Lac en attendant que Hurlevent dépêche des réserves régulières. Un aventurier transporte le document. Les territoires périphériques de Hurlevent sont mal coordonnés ; les magistrats locaux doivent donc organiser eux-mêmes l’entraide."}},faq={{q="Qu’est-ce que la Demande d'aide de Salomon à la marche de l'Ouest ?",a="Le Magistrat Salomon de Comté-du-Lac écrit à Gryan Roidemantel et demande à la People's Militia de la Marche de l’Ouest d’envoyer des renforts pour défendre Les Carmines.",al={"demande d’aide de salomon","lettre de salomon à la marche de l’ouest","lettre de comté-du-lac à la marche de l’ouest"}},{q="Pourquoi le Magistrat Salomon demande-t-il l’aide de la Marche de l’Ouest plutôt que celle de Hurlevent ?",a="Les troupes royales de Hurlevent ne sont pas arrivées en force, tandis que le danger grandit à Comté-du-Lac. Faute de temps pour attendre la Couronne, Salomon cherche de l’aide auprès d’une force armée voisine.",al={"pourquoi demander l’aide de la marche de l’ouest","pourquoi ne pas demander l’aide de hurlevent","pourquoi envoyer une demande à la marche de l’ouest"}},{q="Qui est Gryan Roidemantel ?",a="Gryan Roidemantel dirige la People's Militia, une ligue de défense volontaire composée de fermiers et de colons locaux qui protègent la Marche de l’Ouest contre la Confrérie défias.",al={"qui est roidemantel","rôle de gryan roidemantel"}},{q="Quelles menaces poussent Salomon à envoyer cette lettre ?",a="Les orcs Rochenoire envahissent la région, et des gnolls pillent les environs des Carmines. Leurs attaques mettent à rude épreuve la garde de Comté-du-Lac.",al={"pourquoi comté-du-lac est en danger","qu’est-ce qui menace les carmines"}}},fx={["7804da1c"]={q="D'où provient la Demande d'aide de Salomon à la marche de l'Ouest, et qui l'a rédigée ?",a="La lettre est rédigée directement par le magistrat Salomon à Comté-du-Lac, la ville assiégée des Carmines. Désespéré par le fait que l'armée de Hurlevent n'ait pas envoyé les renforts promis pour défendre son peuple, Salomon a écrit ce message urgent lui-même pour implorer ses alliés proches de lui venir en aide.",al={"qui a écrit la demande d'aide de salomon à la marche de l'ouest","d'où vient la demande d'aide de salomon","créateur de la demande d'aide de salomon"}},["6d6e291d"]={q="Pourquoi Gryan Roidemantel veut-il la Demande d'aide de Salomon à la marche de l'Ouest ?",a="Gryan Roidemantel dirige The People's Militia dans la Marche de l’Ouest, et cette dépêche l'informe de la situation critique de Comté-du-Lac. Salomon espère que la milice pourra détacher des combattants pour renforcer les défenses déclinantes des Carmines pendant que la ville attend des nouvelles et des troupes de la cour du roi Anduin à Hurlevent.",al={"pourquoi livrer la demande d'aide de salomon","pourquoi roidemantel veut la demande d'aide","à quoi sert la lettre"}}},fp="26,207,24.381.0,26.355.0,35.148.0,72.165.0,25.151.0,53.124.0"}
P.entries["item:soran-ruk-fragment"] = {n="Fragment de Soran'ruk",s="Dans les Profondeurs de Brassenoire, des cultistes puisent dans des fragments de Soran'ruk, un orbe-prison brisé. Les morceaux conservent l'énergie gangrenée du démon autrefois emprisonné à l'intérieur.",h="Dans les Profondeurs de Brassenoire, des cultistes puisent dans des fragments de Soran'ruk, un orbe-prison...",kw={"profondeurs de brassenoire","doan karhan","gangrène","orbe de soran'ruk","soran'ruk","acolyte du crépuscule"},ang={["class:Warlock"]="En tant que démoniste, vous pouvez utiliser des réceptacles-prisons démoniaques comme l'Orbe de Soran'ruk pour canaliser l'énergie gangrenée brute sans asservir directement un démon."},sec={{t="Une prison brisée",b="L'orbe-prison de Soran'ruk fut brisé après que son démon eut perdu la faveur de la Légion ardente. Les démons qui déplaisent à leurs maîtres peuvent voir leur esprit scellé dans des orbes, puis remis à des lanceurs de sorts gangrenés pour leur servir de source de pouvoir. Dans les ruines submergées des Profondeurs de Brassenoire, des cultistes du Marteau du crépuscule détiennent de petits fragments provenant d'une moitié de l'orbe. Ils puisent dans l'essence démoniaque persistante pour leurs propres rituels."},{t="Reconstitution dans les Tarides",b="Chaque fragment conserve une trace de la vitalité du démon emprisonné. Doan Karhan, un érudit reclus dans les Tarides du sud, a consacré sa vie à l'étude des réceptacles démoniaques. Il possède un orbe similaire, l'Orbe de Zargain. Un démoniste ambitieux peut lui apporter trois petits fragments et le morceau plus grand détenu dans la Forêt des Pins-Argentés. Doan peut reforger la relique pour la reconstituer et en faire un instrument de pouvoir."}},faq={{q="Qui est Soran'ruk ?",a="Soran'ruk était un démon de la Légion ardente qui avait perdu la faveur de ses dirigeants. Pour le punir, son esprit fut extrait et enfermé dans un orbe de cristal. Des démonistes et des mages mortels utilisaient l'orbe comme source d'énergie.",al={"qui est soran'ruk","histoire de soran'ruk","soran'ruk est-il un démon"}},{q="Où trouve-t-on ces fragments ?",a="Des acolytes du crépuscule transportent les petits fragments dans les salles caverneuses des Profondeurs de Brassenoire, le long de la grève de Zoram.",al={"où trouver un fragment de soran'ruk","qui lâche les fragments de soran'ruk","emplacement du fragment de soran'ruk"}},{q="Pourquoi le Marteau du crépuscule possède-t-il ces fragments ?",a="Les cultistes du Marteau du crépuscule rassemblent les fragments pour récupérer l'essence magique du démon captif. Ils utilisent des artefacts corrompus pour alimenter leurs rituels ténébreux et canaliser une magie interdite.",al={"pourquoi les cultistes le possèdent","marteau du crépuscule et soran'ruk"}},{q="Qui peut restaurer l'Orbe de Soran'ruk ?",a="Doan Karhan peut restaurer l'Orbe de Soran'ruk. Cet ermite solitaire vit dans les Tarides du sud, près de la frontière de Mille pointes. Il étudie et reforge les orbes démoniaques de la Légion ardente.",al={"qui répare l'orbe","où rendre le fragment de soran'ruk","orbe de doan karhan"}}},fx={["49c59cce"]={q="D'où viennent les fragments de Soran'ruk et qui les a créés ?",a="Il s'agit des restes brisés de The Orb of Soran'ruk, un réceptacle démoniaque forgé par la Légion ardente. Lorsque des démons tombent en disgrâce, la Légion emprisonne leurs esprits dans de tels orbes et les confie à ses mages et ses démonistes. L'orbe de Soran'ruk fut plus tard brisé en morceaux, ces éclats plus petits finissant entre les mains des acolytes du Marteau du crépuscule dans les Profondeurs de Brassenoire.",al={"origine du fragment de soran'ruk","qui a fabriqué les fragments de soran'ruk","d'où viennent les fragments de soran'ruk"}},["5e1e8c12"]={q="Pourquoi vouloir les fragments de Soran'ruk ?",a="Même brisés en éclats, les fragments vibrent encore de l'essence et de la puissance du démon emprisonné. Le démoniste ermite Doan Karhan dans les Tarides a consacré sa vie à l'étude et à la reconstruction des orbes de la Légion. Si vous lui apportez ces éclats plus petits ainsi que le grand fragment du Donjon d'Ombrecroc, il pourra reforger The Orb of Soran'ruk en un instrument puissant pour votre art.",al={"pourquoi rassembler les fragments de soran'ruk","qui veut les fragments de soran'ruk","pourquoi avez-vous besoin des fragments de soran'ruk"}}},fp="18,150,18.407.0,29.373.1,18.217.0,32.115.0,49.168.0,37.191.0"}
P.entries["item:southsea-treasure"] = {n="Trésor des mers du Sud",s="Le Trésor des mers du Sud se trouve à bord d’un navire pirate au sud de Cabestan, où Wrenix le Misérable convoite le butin. La cale la plus basse du Tide Razor se trouve sous le terrain d’entraînement des Southsea Freebooters.",h="Le Trésor des mers du Sud se trouve à bord d’un navire pirate au sud de Cabestan, où Wrenix le Misérable...",kw={"b.g.a.c.","crochetage","polly","cabestan","main brisée","trésor des mers du sud","tide razor","wrenix le misérable"},ang={["class:Rogue"]="Pour un voleur en devenir, récupérer le Trésor des mers du Sud permet de s’exercer au crochetage et de découvrir la Main brisée, un syndicat clandestin.",["faction:Horde"]="En tant que membre de la Horde, perturber la cache des Southsea Freebooters peut aider les autorités locales. Les pirates harcèlent les marchands autour des Tarides et du port de Cabestan."},sec={{t="Un vol périlleux",b="Le Tide Razor est ancré le long de la Côte des marchands, au sud de Cabestan. Les Southsea Freebooters s’en servent comme base avancée et terrain d’entraînement. Leur butin, appelé Trésor des mers du Sud, attend dans la cale la plus basse.\n\nWrenix le Misérable, une fripouille gobeline de Cabestan, fait de ce vol une épreuve pour les aspirants tire-laine. Il affirme que les cinq derniers agents envoyés récupérer le coffre sont revenus en morceaux. Des pirates sur leurs gardes défendent le navire, et une créature féroce veille sur la cale."},{t="Le souvenir de Polly",b="Polly garde le Trésor des mers du Sud dans la cale. Les voleurs qui échappent aux instructeurs pirates et crochettent la serrure du coffre trouvent un perroquet hostile à la place du butin.\n\nLe dispositif B.G.A.C. de Wrenix peut aider à venir à bout de Polly. Ce n’est qu’alors que le trésor peut être emporté hors de la cale et ramené intact à Cabestan."}},faq={{q="Où se trouve le Trésor des mers du Sud ?",a="Le Trésor des mers du Sud se trouve à bord du Tide Razor, ancré le long de la côte au sud de Cabestan, dans les Tarides. Il repose dans la cale la plus basse, sous les quartiers d’entraînement des pirates.",al={"où se trouve le trésor","emplacement du tide razor","comment trouver le trésor des mers du sud"}},{q="Qui convoite le Trésor des mers du Sud ?",a="Wrenix le Misérable, un gobelin de Cabestan, convoite le Trésor des mers du Sud. Il engage des agents discrets pour s’introduire dans le navire et le récupérer pour lui.",al={"qui donne la quête","qui est wrenix","qui le convoite"}},{q="Pourquoi le coffre est-il vide quand on le crochète ?",a="Polly garde le Trésor des mers du Sud dans la cale. Crocheter la serrure du coffre fait surgir le perroquet féroce ; vaincre Polly permet d’obtenir le trésor.",al={"d’où vient polly","pourquoi polly apparaît","pourquoi le coffre ne contient pas le trésor"}},{q="Qu’est-ce que le B.G.A.C. et pourquoi en a-t-on besoin ?",a="Wrenix le Misérable fournit le B.G.A.C., un dispositif gobelin expérimental conçu pour affaiblir les menaces aériennes particulièrement féroces. Il le destine à Polly, le perroquet mortel qui garde la cale du navire.",al={"qu’est-ce que le b.g.a.c.","comment vaincre polly","perroquet hostile"}},{q="À quoi les Southsea Freebooters utilisent-ils le navire ?",a="Le Tide Razor sert de base et de repaire de voleurs aux Southsea Freebooters. À son deuxième niveau, des coffrets d’entraînement permettent à l’équipage d’exercer ses coupe-bourses au crochetage.",al={"qu’est-ce que le tide razor","repaire de pirates dans les tarides","cale du navire des mers du sud"}}},fx={c9f033cd={q="Qu'est-ce que le Trésor des mers du Sud ?",a="Le Trésor des mers du Sud est le butin pillé amassé par les Southsea Freebooters à bord de leur navire, le Tide Razor, ancré au large des Tarides. Conservé au fond de la cale du navire et gardé par un perroquet pirate notoirement féroce nommé Polly, il représente les gains mal acquis accumulés par les corsaires lors de leurs raids le long de la Côte des marchands.",al={"qu'est-ce que le trésor des mers du sud","objet trésor des mers du sud","quel genre de trésor est le trésor des mers du sud"}}},fp="17,189,14.462.0,16.299.1,39.172.0,32.139.0,35.155.1,41.195.0,50.159.0"}
P.entries["item:spectral-comb"] = {n="Peigne spectral",s="Au sud de Sombre-Comté, le Peigne spectral recueille les cheveux fantomatiques de Marie l'aveugle, dans une ferme en ruine.",h="Au sud de Sombre-Comté, le Peigne spectral recueille les cheveux fantomatiques de Marie l'aveugle, dans une...",kw={"marie l'aveugle","peigne","sombre-comté","bois de la pénombre","fantôme","mèche de cheveux fantômes","peigne spectral"},ang={["faction:Alliance"]="En tant que voyageur de l'Alliance, vous pouvez porter le peigne au sud de Sombre-Comté et découvrir le destin tragique des anciens colons du Bois de la Pénombre.",["profession:Tailoring"]="En tant que couturier, vous pouvez utiliser le Peigne spectral pour recueillir des fibres éthérées auprès de fantômes consentants, au lieu de les tondre par des moyens ordinaires."},sec={{t="Un outil pour les morts agités",b="Les peignes ordinaires ne peuvent atteindre les cheveux d'un esprit, et peu d'artisans mortels savent les recueillir. Le Peigne spectral traverse ces tresses invisibles. Dans une ferme en ruine au sud de Sombre-Comté, on le propose à Marie l'aveugle, un fantôme en pleurs qui se lamente seule. Se coiffer lui apporte du réconfort, et elle prend volontiers le peigne. Les fibres qu'elle laisse derrière elle peuvent être tissées en Mèche de cheveux fantômes."}},faq={{q="À quoi sert le Peigne spectral ?",a="Vous donnez le Peigne spectral à Marie l'aveugle, un fantôme en pleurs au sud de Sombre-Comté. En se peignant, elle permet au peigne de recueillir des mèches éthérées qui peuvent être filées pour créer un fil surnaturel.",al={"utilité du peigne spectral","pourquoi ai-je besoin du peigne spectral","à quoi sert le peigne"}},{q="Qui est Marie l'aveugle ?",a="Marie l'aveugle est un esprit tourmenté qui hante une maison abandonnée dans les collines au sud de Sombre-Comté. Rendue folle par une tragédie, elle s'est arraché les yeux et craint que les autres la trouvent hideuse dans la mort.",al={"histoire de marie l'aveugle","qui est le fantôme au peigne","marie l'aveugle"}},{q="Pourquoi ne peut-on pas utiliser un peigne ordinaire ?",a="Un peigne ordinaire ne peut pas toucher les cheveux intangibles d'un esprit. Le Peigne spectral traverse les tresses d'une apparition.",al={"pourquoi le peigne spectral","peigne ordinaire fantôme"}}},fx={e893aa2f={q="Qu'est-ce que le Peigne spectral ?",a="Le Peigne spectral est un outil de toilettage éthéré spécifiquement enchanté pour interagir avec les êtres incorporels. Alors que des instruments ordinaires passeraient à travers un fantôme sans effet, ce peigne peut réellement toucher, démêler et collecter les mèches spectrales des cheveux d'un fantôme.",al={"qu'est-ce que le peigne spectral","peigne spectral","identité du peigne spectral"}}},fp="13,95,24.375.0,35.177.0,18.186.0,37.119.0"}
P.entries["item:spells-of-shadow"] = {n="Les Sorts de l'Ombre",s="Sous Orgrimmar, Les Sorts de l'Ombre fait partie des trésors bien gardés de la Searing Blade. Les dirigeants réprouvés de Fossoyeuse veulent le récupérer.",h="Sous Orgrimmar, Les Sorts de l'Ombre fait partie des trésors bien gardés de la Searing Blade.",kw={"les incantations du néant","gouffre de ragefeu","searing blade","les sorts de l'ombre","sylvanas","le pouvoir de détruire","fossoyeuse","varimathras"},ang={["class:Warlock"]="En tant que démoniste, vous voyez comment les sectateurs de la Searing Blade manient les arts de l'ombre et du Néant grâce aux dons démoniaques de la Légion.",["race:Undead"]="En tant que mort-vivant, vous aidez Dame Sylvanas à s'emparer d'un savoir démoniaque dangereux sous Orgrimmar. Son pouvoir doit renforcer Fossoyeuse contre le Fléau."},sec={{t="Tomes de la Searing Blade",b="Dans le Gouffre de Ragefeu, les sectateurs de la Searing Blade gardent Les Sorts de l'Ombre parmi leurs trésors. Cette secte dissidente est liée au Shadow Council, et ses membres pratiquent des rites obscurs accordés par les maîtres démoniaques de la Légion ardente. Le livre renferme des arcanes de l'ombre et de la magie gangrenée. Les sectateurs et les démonistes le gardent à portée de main tandis qu'ils complotent sous la Horde, en Durotar."},{t="L'ambition de la Dame noire",b="La nouvelle des dons démoniaques de la Searing Blade parvint aux quartiers royaux de Fossoyeuse. Dame Sylvanas Coursevent et son lieutenant seigneur de l'effroi, Varimathras, jugèrent que ces reliques étaient gaspillées entre les mains de sectateurs aux ambitions limitées. Varimathras envoie donc des aventuriers de la Horde dans le Gouffre de Ragefeu pour s'emparer des Sorts de l'Ombre et de son tome compagnon, Les Incantations du Néant. Leur pouvoir doit servir la cause des Réprouvés contre le Fléau et le Lich King."}},faq={{q="Que sont Les Sorts de l'Ombre ?",a="Les sectateurs de la Searing Blade détiennent Les Sorts de l'Ombre dans le Gouffre de Ragefeu. Ce grimoire contient la Shadow Magic accordée par la Légion ardente.",al={"livre les sorts de l'ombre","que sont les sorts de l'ombre","livre de sorts de l'ombre gouffre de ragefeu"}},{q="Qui veut ce livre ?",a="Varimathras cherche à obtenir Les Sorts de l'Ombre pour Dame Sylvanas Coursevent. Son conseiller seigneur de l'effroi réside dans le Quartier royal de Fossoyeuse.",al={"qui a besoin des sorts de l'ombre","qui rend les sorts de l'ombre","donneur de quête des sorts de l'ombre"}},{q="Où trouver ce livre ?",a="Les sectateurs et les démonistes de la Searing Blade portent Les Sorts de l'Ombre dans le Gouffre de Ragefeu, les cavernes ardentes sous Orgrimmar.",al={"emplacement des sorts de l'ombre","où trouver les sorts de l'ombre","comment obtenir les sorts de l'ombre"}},{q="Pourquoi les Réprouvés veulent-ils ce grimoire ?",a="Dame Sylvanas estime que les dons obscurs de la Légion doivent revenir aux Réprouvés plutôt qu'à des sectateurs aux ambitions limitées. Elle veut que cette magie renforce les Réprouvés contre le Fléau et le Lich King.",al={"pourquoi sylvanas veut-elle le livre","pourquoi varimathras veut-il les sorts de l'ombre"}}},fp="16,148,26.335.0,24.437.0,29.130.0,20.133.0,28.114.0,39.193.0"}
P.entries["item:spirit-of-silverpine-charts"] = {n="Spirit of Silverpine Charts",s="Les cartes du Spirit of Forêt des Pins-Argentés sont celles du navire, désormais recherchées dans son épave des Hautes-terres Arathies. Le Second Nilzlix veut les mettre en sûreté avant que ces informations ne tombent entre de mauvaises mains.",h="Les cartes du Spirit of Forêt des Pins-Argentés sont celles du navire, désormais recherchées dans son épave...",kw={"hautes-terres arathies","cartes","récupération en haute mer","second nilzlix","amiral corne-de-mer","spirit of forêt des pins-argentés","cartes du spirit of forêt des pins-argentés"},sec={{t="Échoué dans la crique",b="Les cartes de l’épave sont recherchées en même temps que le journal de bord du navire. Le Second Nilzlix vous demande de récupérer les deux. D’après l’équipage, le Spirit of Forêt des Pins-Argentés s’est échoué sur un temple du récif à la marée descendante. Ses cartes contiennent des informations que l’équipage craint de voir tomber entre les mains de l’ennemi. L’Amiral Corne-de-mer attend qu’elles soient rapportées à Baie-du-Butin."}},faq={{q="Que sont les cartes du Spirit of Forêt des Pins-Argentés ?",a="Ce sont les cartes marines du Spirit of Forêt des Pins-Argentés, un navire naufragé dans les Hautes-terres Arathies.",al={"cartes des pins-argentés","cartes du spirit"}},{q="Où trouver les cartes ?",a="Les cartes du Spirit of Forêt des Pins-Argentés sont recherchées dans l’épave du navire, dans les Hautes-terres Arathies.",al={"où trouver les cartes","emplacement des cartes des pins-argentés"}},{q="Qui veut récupérer les cartes ?",a="Le Second Nilzlix veut récupérer les cartes et les journaux de bord du Spirit of Forêt des Pins-Argentés et du Maiden's Folly.",al={"qui veut les cartes","cartes du second nilzlix"}},{q="Pourquoi recherche-t-on les cartes ?",a="L’équipage craint que les cartes ne révèlent des informations à des indiscrets si elles sont abandonnées sur place.",al={"pourquoi les cartes sont importantes","contenu des cartes"}},{q="Comment le Spirit of Forêt des Pins-Argentés a-t-il sombré ?",a="D’après l’équipage, le Spirit of Forêt des Pins-Argentés s’est échoué sur un temple du récif lorsque la marée a commencé à baisser.",al={"épave des pins-argentés","pourquoi le navire a sombré"}},{q="Où les cartes seront-elles emportées ?",a="Les cartes récupérées doivent être mises en sûreté pour l’Amiral Corne-de-mer et le commandement de Baie-du-Butin.",al={"cartes pour baie-du-butin","qui reçoit les cartes"}}},fp="27,187,19.336.0,41.98.0,28.110.0,21.108.0,26.81.0,38.105.0,33.99.0"}
P.entries["item:spirit-of-silverpine-log"] = {n="Spirit of Silverpine Log",s="Le journal du Spirit of Forêt des Pins-Argentés est le registre du capitaine d’un navire échoué. Ses cartes et son journal contiennent des informations que l’équipage veut protéger des ennemis.",h="Le journal du Spirit of Forêt des Pins-Argentés est le registre du capitaine d’un navire échoué.",kw={"hautes-terres arathies","baie-du-butin","journal du capitaine","récupération sous-marine","second nilzlix","amiral corne-de-mer","naufrage","spirit of forêt des pins-argentés","journal du spirit of forêt des pins-argentés"},sec={{t="Les navires échoués",b="Le Second Nilzlix veut récupérer le journal de bord et les cartes du navire avant que l’équipage ne quitte la crique. Le Spirit of Forêt des Pins-Argentés et le Maiden’s Folly se sont échoués quand la marée s’est retirée, heurtant ce qui semblait être un temple dans le récif. Les deux navires ont rapidement sombré. Leurs documents comptent désormais pour le commandement de Baie-du-Butin, qui craint que ces informations ne parviennent à ses ennemis."}},faq={{q="Qu’est-ce que le journal du Spirit of Forêt des Pins-Argentés ?",a="C’est le journal de bord du capitaine du Spirit of Forêt des Pins-Argentés, l’un des navires échoués dans les Hautes-terres Arathies.",al={"journal de la forêt des pins-argentés","journal de bord","journal du capitaine"}},{q="Où le Spirit of Forêt des Pins-Argentés a-t-il sombré ?",a="Le Spirit of Forêt des Pins-Argentés s’est échoué sur ce qui semblait être un temple dans le récif, dans une crique des Hautes-terres Arathies.",al={"où se trouve la forêt des pins-argentés","épave de la forêt des pins-argentés","navire dans les hautes-terres arathies"}},{q="Pourquoi le Second Nilzlix veut-il le journal ?",a="Le Second Nilzlix veut récupérer le journal et les cartes du Spirit of Forêt des Pins-Argentés avant le départ de l’équipage, afin que ces informations ne tombent pas entre les mains de l’ennemi.",al={"pourquoi récupérer le journal","que veut le second nilzlix","récupérer le journal du spirit of forêt des pins-argentés"}},{q="Qu’est-il arrivé au Spirit of Forêt des Pins-Argentés ?",a="À mesure que la marée baissait, le Spirit of Forêt des Pins-Argentés s’est échoué sur ce qui semblait être un temple dans le récif, puis a rapidement sombré.",al={"épave de la forêt des pins-argentés","qu’est-il arrivé au navire","comment le navire a-t-il sombré"}},{q="Pourquoi les cartes et les journaux sont-ils importants ?",a="L’équipage craint que ces documents ne tombent entre les mains de l’ennemi, et l’Amiral Corne-de-mer le tiendrait responsable si cela arrivait.",al={"pourquoi récupérer les cartes","mains de l’ennemi","documents de baie-du-butin"}}},fp="24,168,17.358.0,37.111.0,40.113.0,41.155.0,42.117.0,38.126.0"}
P.entries["item:split-bone-necklace"] = {n="Split Bone Necklace",s="Les Split Bone Necklaces sont des trophées pris aux trolls Tranche-tête de la Vallée de Strangleronce. Kin'weelay les réclame pour aider les Sombrelance dans leur longue guerre.",h="Les Split Bone Necklaces sont des trophées pris aux trolls Tranche-tête de la Vallée de Strangleronce.",kw={"sombrelance","campement grom'gol","kin'weelay","collier","tranche-tête","split bone necklace","vallée de strangleronce","troll"},ang={["race:Troll"]="En tant que troll, vous voyez la vieille guerre d'une tribu se poursuivre par l'entremise d'une autre. Les Sombrelance ne vivent plus dans la Vallée de Strangleronce, mais Kin'weelay affirme qu'ils restent liés à leur conflit avec les Tranche-tête."},sec={{t="Le compte des Sombrelance",b="Au Campement Grom'gol, Kin'weelay vous envoie vers le sud-est, chez la tribu Tranche-tête. Leurs guerriers vivent parmi les ruines trolles de la Vallée de Strangleronce, et les Sombrelance les combattent depuis des années. Bien que les Sombrelance ne vivent plus dans la vallée, Kin'weelay affirme qu'ils restent liés à ce conflit. Rapportez-lui les colliers, et vos actes aideront son peuple."}},faq={{q="Qui veut les Split Bone Necklaces ?",a="Kin'weelay, de la tribu Sombrelance, vous demande de lui apporter les Split Bone Necklaces au Campement Grom'gol.",al={"qui veut ces colliers","collier kin'weelay","collier pour qui"}},{q="Qui porte ces colliers ?",a="Les trolls Tranche-tête portent des Split Bone Necklaces. Kin'weelay les convoite comme trophées dans la guerre des Sombrelance contre les Tranche-tête.",al={"de quoi viennent ces colliers","signification de split bone necklace","collier tranche-tête"}},{q="Pourquoi Kin'weelay les veut-il ?",a="Kin'weelay veut ces colliers pour aider les Sombrelance dans leur long conflit avec la tribu Tranche-tête.",al={"pourquoi ramasser des split bones","pourquoi kin'weelay en a-t-il besoin","guerre des sombrelance"}},{q="Où se trouvent les Tranche-tête ?",a="Les Tranche-tête vivent au sud-est du Campement Grom'gol, parmi les ruines trolles de la Vallée de Strangleronce.",al={"où trouver les tranche-tête","emplacement des tranche-tête","ruines trolles"}},{q="Combien de colliers Kin'weelay demande-t-il ?",a="Kin'weelay vous demande de lui rapporter vingt-cinq Split Bone Necklaces.",al={"nombre de colliers","combien de split bones","25 colliers"}}},fp="19,158,17.364.0,35.106.0,26.137.0,30.105.0,29.100.0,43.66.0"}
P.entries["item:spotted-sunfish"] = {n="Poisson-lune",s="Au Lac placide, les poissons-lunes attirent pêcheurs et murlocs affamés. Leurs prises alimentent le commerce de Comté-du-Lac, tandis que les murlocs rendent les hauts-fonds dangereux.",h="Au Lac placide, les poissons-lunes attirent pêcheurs et murlocs affamés.",kw={"dockmaster baren","lac placide","comté-du-lac","murloc","les carmines","selling fish","poisson-lune"},ang={["profession:Cooking"]="En cuisine, vous pouvez utiliser le poisson-lune, un poisson d'eau douce originaire des Carmines."},sec={{t="Une prise recherchée",b="Les poissons-lunes alimentent le commerce sur les quais de Comté-du-Lac. Dockmaster Baren achète les prises régulières du lac, fournissant nourriture et marchandises à une ville sous tension. Des tribus agressives de murlocs rôdent dans les hauts-fonds et perturbent la pêche. Dans leurs campements, les voyageurs peuvent prendre de force les poissons qu'ils ont rassemblés."}},faq={{q="Où trouve-t-on des poissons-lunes ?",a="Les poissons-lunes vivent dans le Lac placide, dans les Carmines. Les pêcheurs les y attrapent, et les murlocs les rassemblent dans des campements le long du rivage.",al={"où trouver des poissons-lunes","lieu où trouver les poissons-lunes","poissons du lac placide"}},{q="Qui achète ou a besoin de poissons-lunes ?",a="Dockmaster Baren achète des poissons-lunes sur les quais de Comté-du-Lac. Il fait commerce de ces poissons et paie pour les prises fraîches.",al={"qui veut des poissons-lunes","poissons de dockmaster baren","quête vente de poissons"}},{q="Pourquoi les murlocs transportent-ils ces poissons ?",a="Les murlocs du Lac placide rassemblent des poissons-lunes pour nourrir leurs tribus grandissantes. Ils gardent leurs prises dans des campements le long des hauts-fonds.",al={"poisson-lune des murlocs","pourquoi les murlocs lâchent des poissons"}},{q="Peut-on en obtenir sans pêcher ?",a="Oui. Les voyageurs sans canne à pêche peuvent vaincre les murlocs hostiles sur les rives du Lac placide et prendre les poissons qu'ils ont rassemblés.",al={"obtenir des poissons-lunes sans canne à pêche","poissons-lunes sans canne à pêche"}}},fx={["723094c5"]={q="Qu'est-ce qu'un Poisson-lune ?",a="Le Poisson-lune est un poisson d'eau douce prisé, originaire du Lac placide dans les Carmines. Réputé dans toute la région pour son goût et sa valeur commerciale, il prospère dans les eaux profondes du lac et sert de denrée de base pour les pêcheurs de Comté-du-Lac, ainsi que de source de nourriture principale pour les murlocs locaux.",al={"qu'est-ce que le poisson-lune","infos sur le poisson-lune","lore du poisson-lune"}},["1a933976"]={q="D'où vient le Poisson-lune ?",a="Les Poissons-lunes sont originaires naturellement des eaux fraîches du Lac placide dans les Carmines. Plutôt que d'être fabriqués ou cultivés, ce sont des poissons sauvages récoltés directement dans le lac, attrapés à la ligne le long des quais et des rives ou récupérés des griffes des Murloc Poachers locaux.",al={"origine du poisson-lune","d'où vient le poisson-lune","source du poisson-lune"}}},fp="15,149,14.293.0,32.145.0,34.109.0,36.126.0,36.137.0"}
P.entries["item:spy-s-report"] = {n="Spy's Report",s="Le Spy’s Report de Marg Nighteye est le texte d’un espion orc, trouvé près du Manoir des Flammeroles, dans le Marécage d’Âprefange. On demande au Capitaine Garran Vimaire, à Theramore, de le lire, car il connaît l’orc.",h="Le Spy’s Report de Marg Nighteye est le texte d’un espion orc, trouvé près du Manoir des Flammeroles, dans le...",kw={"capitaine vimaire","marécage d’âprefange","espions de la horde","marg nighteye","espion orc","spy’s report","manoir des flammeroles","theramore","colline des sorcières"},ang={["faction:Alliance"]="Le rapport signale la présence d’espions de la Horde près de Theramore, une colonie de l’Alliance sur la côte du Marécage d’Âprefange."},sec={{t="Un rapport enfoui",b="Près de la Colline des sorcières, de la terre meuble dissimule un rapport écrit par Marg Nighteye, à côté du Manoir des Flammeroles. Ce texte est lié aux espions orcs près de Theramore, et l’on demande au Capitaine Garran Vimaire de l’examiner. Il connaît l’orc mieux que la plupart des habitants de Theramore."}},faq={{q="Qui a écrit le Spy’s Report ?",a="Marg Nighteye a écrit le Spy’s Report.",al={"auteur du rapport","rapport de marg nighteye"}},{q="Où le rapport a-t-il été trouvé ?",a="Le Spy’s Report était enfoui dans la terre meuble, à côté du Manoir des Flammeroles, sur la Colline des sorcières, dans le Marécage d’Âprefange.",al={"lieu où le rapport a été trouvé","lieu du rapport d’espion","rapport dans la terre meuble"}},{q="Qui devrait lire le rapport ?",a="Le Capitaine Garran Vimaire, à l’Ile de Theramore, devrait lire le rapport, car il connaît l’orc mieux que la plupart des gens.",al={"destinataire du rapport","rapport du capitaine vimaire","rapport pour vimaire"}},{q="De quoi parle le rapport ?",a="Le rapport est le texte d’un espion orc et pourrait renseigner le Capitaine Garran Vimaire sur les espions de la Horde près de Theramore.",al={"contenu du rapport","rapport d’espion orc","espions de la horde à theramore"}}},fp="12,186,15.237.0,29.39.0,27.102.0,27.103.0,29.104.0"}
P.entries["item:stable-ectoplasm"] = {n="Stable Ectoplasm",s="Près des fantômes des Maleterres de l’Est, un Alambic ectoplasmique peut recueillir Stable Ectoplasm. Mux Brouillemana en a besoin pour atteindre les esprits dont l’âme n’a pas quitté ce monde.",h="Près des fantômes des Maleterres de l’Est, un Alambic ectoplasmique peut recueillir Stable Ectoplasm.",kw={"banshees","maleterres de l’est","ectoplasme","alambic ectoplasmique","gadgetzan","fantômes","mux brouillemana","valnord","stable ectoplasm"},ang={["profession:Engineering"]="Mux qualifie l’Alambic ectoplasmique de véritable merveille d’ingénierie. Ses travaux montrent comment les inventions gobelines peuvent servir à étudier le monde des esprits."},sec={{t="Parmi les fantômes",b="Mux Brouillemana demande Stable Ectoplasm aux fantômes et aux banshees des Maleterres de l’Est. Il en a besoin avec deux autres sortes d’ectoplasme, recueillies à Silithus et au Berceau-de-l’Hiver. L’alambic extrait la substance des morts-vivants incorporels à proximité. Valnord est un bon endroit pour les trouver."}},faq={{q="Qu’est-ce que Stable Ectoplasm ?",a="Stable Ectoplasm est une substance recueillie sur les fantômes et les banshees des Maleterres de l’Est à l’aide d’un Alambic ectoplasmique.",al={"stable ectoplasm","qu’est-ce que l’ectoplasme","substance fantomatique"}},{q="Qui a besoin de Stable Ectoplasm ?",a="Mux Brouillemana, à Gadgetzan, a besoin de Stable Ectoplasm, ainsi que de Scorched Ectoplasm et Frozen Ectoplasm, pour ses travaux avec l’Alambic ectoplasmique.",al={"qui veut stable ectoplasm","mux et l’ectoplasme","de quoi mux a-t-il besoin"}},{q="Où trouver Stable Ectoplasm ?",a="Les fantômes et les banshees des Maleterres de l’Est donnent Stable Ectoplasm. Valnord est un bon endroit pour les trouver.",al={"lieu de stable ectoplasm","où trouver de l’ectoplasme","fantômes de valnord"}},{q="Pourquoi Mux veut-il de l’ectoplasme ?",a="Mux espère utiliser l’énergie surnaturelle de l’ectoplasme pour atteindre les esprits dont l’âme n’a pas tout à fait quitté ce monde.",al={"pourquoi l’ectoplasme","plan de mux","atteindre les esprits"}}},fp="16,179,16.303.0,25.123.0,27.141.0,34.110.0,28.118.0"}
P.entries["item:stalker-claws"] = {n="Griffes de traqueur",s="Dans tout Mulgore, les chamans taurens utilisent les Griffes de traqueur lors d’un rite destiné à purifier les puits souillés. Ils les lient dans des totems qui purifient l’eau empoisonnée.",h="Dans tout Mulgore, les chamans taurens utilisent les Griffes de traqueur lors d’un rite destiné à purifier...",kw={"totem de purification","mulgore","mull corne-tonnerre","traqueur des prairies","griffes de traqueur","thunderhorn totem","puits d’eau"},ang={["class:Shaman"]="En tant que chaman, vous liez la pureté féroce des prédateurs sauvages des plaines dans des totems de purification. Leurs griffes confèrent leur pouvoir aux totems.",["race:Tauren"]="En tant que tauren, recueillir ces griffes aide votre tribu à restaurer ses eaux sacrées, empoisonnées par des intrus industriels imprudents."},sec={{t="Prédateurs des plaines",b="Les traqueurs des prairies chassent dans les steppes herbeuses de Mulgore. Leur discrétion et leur précision les rendent mortels, mais ils maintiennent un équilibre nécessaire dans le dessein de la Terre-Mère. Mull Corne-tonnerre a besoin de leurs griffes pour aider à guérir la terre flétrie. Il ne veut pas nuire aux bêtes, car la force naturelle de leur chasse possède la puissance spirituelle qui peut contrer la corruption artificielle."},{t="Purifier les puits",b="Les forages et les exploitations minières gobelines dans le centre de Kalimdor ont déversé des poisons chimiques dans les eaux souterraines qui alimentent les puits ancestraux des taurens. Le Puits Corne-tonnerre est souillé par une fange immonde. Les chamans de la tribu lient des Griffes de traqueur et des Griffes de puma dans un Totem de purification de Corne-tonnerre. Le totem élimine la boue contre nature des sources de la terre."}},faq={{q="D’où viennent les Griffes de traqueur ?",a="Les traqueurs des prairies parcourent les collines herbeuses de Mulgore, surtout à l’est et à l’ouest du village Sabot-de-Sang. On obtient leurs griffes en les chassant.",al={"où trouver les griffes de traqueur","qui donne les griffes de traqueur","origine des griffes de traqueur"}},{q="Pourquoi Mull Corne-tonnerre a-t-il besoin de ces griffes ?",a="Mull Corne-tonnerre a besoin de Griffes de traqueur et de griffes de puma des plaines pour fabriquer un Totem de purification de Corne-tonnerre. La pureté et la force des chasseurs natifs aident à purifier les puits empoisonnés.",al={"pourquoi recueillir les griffes de traqueur","but de mull corne-tonnerre","utilité des griffes de traqueur"}},{q="Pourquoi le Puits Corne-tonnerre est-il souillé ?",a="Les activités gobelines à Mulgore provoquent une pollution industrielle contre nature. Leur travail perturbe l’équilibre naturel et empoisonne les eaux souterraines locales.",al={"qui a empoisonné le puits","pourquoi le puits corne-tonnerre est-il pollué","pollution à corne-tonnerre"}},{q="Que se passe-t-il après la collecte des griffes ?",a="Mull grave les griffes recueillies dans un totem de purification. Il faut ensuite le porter directement au Puits Corne-tonnerre pour en chasser la corruption persistante.",al={"what comes next","étape suivante après les griffes","rituel du totem de purification"}}},fx={a496bd75={q="Que sont les Griffes de traqueur ?",a="Les Griffes de traqueur sont les serres naturelles récoltées sur les traqueurs des prairies, de féroces prédateurs félins parcourant les plaines de Mulgore. Bien qu'il s'agisse de simples trophées de chasse pour un étranger, les chamans taurens les considèrent comme l'incarnation de la concentration prédatrice naturelle de la créature et de son harmonie avec la terre.",al={"que sont les griffes de traqueur","objet griffes de traqueur","griffe de traqueur"}}},fp="13,148,23.364.0,19.338.0,33.136.0,43.173.0,42.141.0,42.152.0"}
P.entries["item:star-of-xil-yeh"] = {n="Etoile de Xil'yeh",s="L’Etoile de Xil'yeh est une gemme réputée permettre de parler à des êtres d’autres mondes. Gerrig Poigne-d'os la cherche parmi trois reliques à Forgefer.",h="L’Etoile de Xil'yeh est une gemme réputée permettre de parler à des êtres d’autres mondes.",kw={"gemme","gerrig poigne-d'os","main de dagun","legacy heart","autres mondes","etoile de xil'yeh","xil'yeh","sommaire de yagyin"},ang={["faction:Alliance"]="En tant qu’aventurier de l’Alliance, vous pouvez apporter cette relique à Gerrig Poigne-d'os, à Forgefer, où il la recherche pour son ordre."},sec={{t="Une relique convoitée",b="À Forgefer, Gerrig Poigne-d'os demande l’Etoile de Xil'yeh, l’une des trois reliques dont il a besoin. Il veut échanger ces objets contre le Sommaire de Yagyin, un livre lié au début d’un nouveau chapitre pour son ordre."}},faq={{q="À quoi sert l’Etoile de Xil'yeh ?",a="On dit que l’Etoile de Xil'yeh permet à son détenteur de parler à des êtres d’autres mondes.",al={"pouvoir de l’étoile de xil'yeh","qu’est-ce que l’étoile gemme","gemme de xil'yeh"}},{q="Pourquoi Gerrig Poigne-d'os veut-il l’Etoile ?",a="Gerrig a besoin de l’Etoile de Xil'yeh, de la Main de Dagun et du Legacy Heart. Il cherche ces trois reliques en échange du Sommaire de Yagyin.",al={"pourquoi gerrig veut l’étoile","étoile de poigne-d'os","reliques de gerrig"}},{q="Où trouver l’Etoile ?",a="Grel'borg the Miser détient l’Etoile de Xil'yeh dans les Montagnes d’Alterac.",al={"emplacement de l’étoile","où se trouve xil'yeh","trouver l’étoile"}},{q="Qu’est-ce que le Sommaire de Yagyin ?",a="Le Sommaire de Yagyin est un livre que Gerrig Poigne-d'os propose en échange de trois reliques. Il pense que le livre pourrait aider son ordre à entamer un nouveau chapitre.",al={"sommaire de yagyin","pourquoi poigne-d'os veut le sommaire","livre de poigne-d'os"}},{q="Quelles sont les autres reliques recherchées par Gerrig ?",a="En plus de l’Etoile de Xil'yeh, Gerrig demande la Main de Dagun et le Legacy Heart.",al={"main et cœur","trois reliques","objets de poigne-d'os"}}},fp="15,153,14.201.0,33.80.0,39.141.0,28.69.0,24.137.0,39.87.0"}
P.entries["item:stave-of-equinex"] = {n="Bâton d'Equinex",s="Le Bâton d'Equinex est un bâton chargé d'énergie, lié à l'Equinex Monolith en Féralas. Son pouvoir est nécessaire pour ouvrir l'ancienne pierre.",h="Le Bâton d'Equinex est un bâton chargé d'énergie, lié à l'Equinex Monolith en Féralas.",kw={"byltan","equinex monolith","féralas","imbel","lahassa","morrow stone","ruines de vent-du-corbeau","samha","bâton d'equinex","bâton de troyas"},sec={{t="Le monolithe silencieux",b="Aux Ruines de Vent-du-Corbeau, en Féralas, le bâton de Troyas peut devenir le Bâton d'Equinex. Quatre flammes brûlent encore à proximité : Samha, Imbel, Byltan et Lahassa. Leurs essences éveillent le bâton près de l'Equinex Monolith. Le bâton est une clé, et le monument de pierre renferme quelque chose."},{t="Un pouvoir déclinant",b="Lorsque le Bâton d'Equinex chargé d'énergie touche le monolithe, une petite porte s'ouvre dans sa surface froide. Des rayons de lumière emplissent les ruines tandis que l'artefact caché est emporté. Le pouvoir du bâton commence alors à décliner, et Troyas Moonbreeze, au Bastion de Pennelune, peut étudier ce qui a été découvert."}},faq={{q="À quoi sert le Bâton d'Equinex ?",a="Le Bâton d'Equinex est une clé qui ouvre l'Equinex Monolith, aux Ruines de Vent-du-Corbeau.",al={"utilité du bâton","qu'est-ce que le bâton d'equinex"}},{q="Comment le bâton de Troyas est-il transformé ?",a="Les essences des quatre flammes Samha, Imbel, Byltan et Lahassa chargent le bâton de Troyas près de l'Equinex Monolith.",al={"charger le bâton de troyas","fabriquer le bâton d'equinex"}},{q="Où se trouve l'Equinex Monolith ?",a="L'Equinex Monolith se dresse parmi les Ruines de Vent-du-Corbeau, en Féralas, à l'ouest du Bosquet du rêve.",al={"emplacement du monolithe","où se trouve equinex"}},{q="Que renferme le monolithe ?",a="Une petite porte s'ouvre dans le monolithe et révèle un artefact. Troyas Moonbreeze identifie la pierre qui en a été extraite comme étant la Morrow Stone.",al={"artefact du monolithe","que renferme equinex"}},{q="Pourquoi le bâton perd-il son pouvoir ?",a="Le Bâton d'Equinex commence à perdre son énergie dès que l'artefact est retiré du monolithe.",al={"bâton qui perd son pouvoir","pourquoi le bâton faiblit"}}},fp="16,130,19.283.0,14.273.1,34.88.0,29.117.0,30.93.0,28.131.1,30.100.1"}
P.entries["item:steelgrill-s-tools"] = {n="Outils de Grillacier",s="Au Dépôt de Grillacier, Beldin Grillacier a besoin d'outils neufs pour faire tourner son atelier. Il met les engins de siège et leur équipement à rude épreuve, alors Kharanos lui envoie régulièrement des pièces de rechange.",h="Au Dépôt de Grillacier, Beldin Grillacier a besoin d'outils neufs pour faire tourner son atelier.",kw={"beldin","dépôt","kharanos","cabestan","engin de siège","clé à molette","grillacier","outils"},ang={["profession:Engineering"]="En tant qu'ingénieur, vous savez que réparer de lourds engins de siège use les clés à molette arcaniques et les clés délicates.",["race:Dwarf"]="En tant que nain, vous connaissez la fierté qu'il y a à entretenir les engins de siège blindés de l'Alliance. Approvisionner Beldin aide l'avant-garde blindée de Forgefer à rester prête au combat."},sec={{t="Un artisan brutal",b="Beldin Grillacier est l'un des meilleurs techniciens d'engins de siège de Dun Morogh. Les marchands connaissent aussi sa poigne brutale. Il travaille sans relâche sur des chars blindés et des dispositifs mécaniques, et les outils délicats ne résistent pas longtemps entre ses mains. Les clés à molette arcaniques cassent et les clés à cliquet s'usent. Il en commande donc régulièrement de nouvelles à Kharanos pour ses établis de réparation."},{t="Des engins toujours prêts",b="Dans son dépôt au nord-est de Kharanos, Beldin entretient des véhicules de combat pour des conducteurs chevronnés comme le Pilote Engrepierre. Les outils maintiennent les machines de guerre de Forgefer en état de marche. De nouvelles clés et de nouveaux cliquets permettent de poursuivre les réparations sur les engins de siège assemblés là-bas et contribuent à la défense locale."}},faq={{q="À quoi servent les Outils de Grillacier ?",a="Ces outils remplacent le matériel de mécanicien usé au Dépôt de Grillacier. Beldin Grillacier s'en sert pour réviser de lourdes machines naines, notamment l'engin de siège endommagé du Pilote Engrepierre.",al={"à quoi servent ces outils","utilité des outils de grillacier"}},{q="Pourquoi Beldin Grillacier use-t-il autant d'outils ?",a="Beldin travaille brutalement et met ses outils à rude épreuve. Les clés à molette arcaniques cassent et les clés à cliquet se brisent si souvent que les fournisseurs de Kharanos peinent à suivre.",al={"pourquoi des outils cassés","pourquoi beldin a besoin d'outils"}},{q="D'où vient cette caisse d'outils ?",a="La caisse est préparée et remplie dans le Kharanos tout proche, puis transportée au nord-est jusqu'au Dépôt de Grillacier.",al={"où trouver des outils","origine de la livraison d'outils"}},{q="Qui est Beldin Grillacier ?",a="Beldin est un maître mécanicien nain qui dirige le Dépôt de Grillacier au nord-est de Kharanos. Il est considéré comme le meilleur technicien d'engins de siège de la région.",al={"qui est beldin","histoire de beldin grillacier"}}},fx={["8eb066d8"]={q="Qu'est-ce que les Outils de Grillacier ?",a="Les Outils de Grillacier sont une commande fraîchement emballée d'équipement mécanique lourd, comprenant des clés à molette à arc et des cliquets à croc. Elle a été préparée pour être livrée directement à Beldin Grillacier, le maître technicien de moteurs de siège travaillant au Dépôt de Grillacier près de Kharanos.",al={"que sont les outils de grillacier","caisse d'outils de grillacier","qu'est-ce que les outils de grillacier"}},["11454cb4"]={q="Pourquoi Beldin Grillacier a-t-il besoin de cette caisse d'outils ?",a="Beldin est un mécanicien expert, mais il use son équipement jusqu'à la corde lors de l'entretien de machines lourdes. Ayant tout juste cassé son dernier cliquet à croc, il a besoin de toute urgence de cette nouvelle cargaison pour terminer des réparations critiques sur des moteurs de siège comme ceux du Pilote Engrepierre.",al={"pourquoi beldin veut-il des outils","pourquoi avoir besoin des outils de grillacier","pourquoi les outils sont-ils recherchés"}}},fp="18,182,24.349.0,27.287.0,37.180.0,52.151.0,40.99.0,25.147.0"}
P.entries["item:steelsnap-s-rib"] = {n="Côte de Broie-l'acier",s="Aux Mille pointes, la Côte de Broie-l'acier témoigne de la fin d'une hyène redoutée. Melor Sabot-de-pierre, aux Pitons-du-Tonnerre, veut qu'on l'apporte à la Cime des chasseurs pour prouver que Broie-l'acier a été tué.",h="Aux Mille pointes, la Côte de Broie-l'acier témoigne de la fin d'une hyène redoutée.",kw={"camp e'thok","cime des chasseurs","hyène","melor sabot-de-pierre","steelsnap","côte de broie-l'acier","mille pointes","pitons-du-tonnerre"},ang={["class:Hunter"]="En tant que chasseur, traquer Broie-l'acier met votre talent à l'épreuve face à un chef de meute dangereux. Vous contribuez aussi à éliminer une menace pour l'équilibre de la nature.",["race:Tauren"]="En tant que tauren, rapporter la Côte de Broie-l'acier accomplit votre devoir envers la Mère-Terre. Vous éliminez une créature cruelle qui souille l'équilibre sacré."},sec={{t="Une chasse hors de la bénédiction",b="Les taurens chassent souvent pour se nourrir, pour l'honneur ou pour vivre en harmonie avec la nature. Broie-l'acier est un cas à part. Cette hyène alpha rôde au fond du canyon, au sud du Camp E'thok, dans les Mille pointes. Elle terrorise les animaux paisibles et pousse des prédateurs moins puissants à répandre le sang.\n\nLe maître de la chasse Melor Sabot-de-pierre attend à la Cime des chasseurs. Il a condamné Broie-l'acier à mort et demande sa côte comme preuve. Une fois Broie-l'acier tué, le canyon pourra être débarrassé de son fléau."}},faq={{q="À quoi sert la Côte de Broie-l'acier ?",a="Apportez la Côte de Broie-l'acier à Melor Sabot-de-pierre, à la Cime des chasseurs, aux Pitons-du-Tonnerre. Cet os prouve que Broie-l'acier a été vaincu.",al={"quête de la côte de broie-l'acier","qui veut la côte de broie-l'acier","que faire de la côte de broie-l'acier"}},{q="Où trouver Broie-l'acier pour récupérer sa côte ?",a="Broie-l'acier rôde au fond du canyon, dans le nord-ouest des Mille pointes, au sud du Camp E'thok. Des membres fidèles de sa meute l'escortent souvent.",al={"emplacement de broie-l'acier","où se trouve broie-l'acier","trouver broie-l'acier"}},{q="Pourquoi Melor Sabot-de-pierre veut-il tuer Broie-l'acier ?",a="Pour Melor, Broie-l'acier est un tyran contre nature, privé de la bénédiction de la Mère-Terre. Cette hyène répand le sang et la peur parmi les bêtes paisibles, contrairement aux prédateurs qui chassent pour survivre.",al={"pourquoi tuer broie-l'acier","motivation de melor sabot-de-pierre","histoire de broie-l'acier"}},{q="Qui est Melor Sabot-de-pierre ?",a="Melor Sabot-de-pierre est un chasseur tauren chevronné de la Cime des chasseurs, aux Pitons-du-Tonnerre. Il envoie les pisteurs en herbe traquer des bêtes dangereuses à travers Kalimdor.",al={"qui est melor","emplacement de melor sabot-de-pierre","melor à la cime des chasseurs"}}},fx={["27efcb35"]={q="Qu'est-ce que la Côte de Broie-l'acier ?",a="Il s'agit d'un os lourd prélevé sur la carcasse de Steelsnap, une hyène notoirement sauvage qui terrorise les canyons de Mille pointes. Plutôt qu'un matériau d'artisanat ou de la viande utile, il sert de preuve physique indéniable que la bête vicieuse a été abattue.",al={"qu'est-ce que la côte de broie-l'acier","qu'est-ce que la côte de steelsnap","os de steelsnap"}},["57ae26da"]={q="D'où vient la Côte de Broie-l'acier ?",a="La côte provient directement des restes de Steelsnap, une hyène anormalement féroce errant dans les plaines arides de Mille pointes au sud des Tarides. Pour l'obtenir, un chasseur doit traquer la bête et vaincre à la fois Steelsnap et sa meute.",al={"où obtenir la côte de broie-l'acier","origine de la côte de broie-l'acier","qui lâche la côte de broie-l'acier"}},["4a69fb67"]={q="Pourquoi Melor Sabot-de-pierre veut-il la Côte de Broie-l'acier ?",a="Melor Sabot-de-pierre demande cette côte comme preuve physique de la mort de Steelsnap. Contrairement aux chasses entreprises pour la nourriture ou l'honneur, Melor envoie des chasseurs éradiquer Steelsnap car la bête existe en dehors de la bénédiction de la Mère Terre, répandant le carnage et la peur parmi des créatures plus paisibles. Revenir avec l'os confirme que le canyon a été purifié de cette souillure.",al={"pourquoi apporter la côte de broie-l'acier à melor","pourquoi melor a-t-il besoin de la côte","pourquoi collecter la côte de broie-l'acier"}}},fp="15,181,27.428.0,33.118.0,42.121.0,47.180.0,23.142.0"}
P.entries["item:stolen-silver"] = {n="Argent volé",s="À La Croisée, l’Argent volé a disparu de la tour de garde. Des raptors Sunscale ont emporté les pièces au sud de Cabestan, jusqu’à leurs nids des Terres des Raptors.",h="À La Croisée, l’Argent volé a disparu de la tour de garde.",kw={"paie des tarides","la croisée","gazrog","terres des raptors","coffret d’argent","argent volé","raptor sunscale"},ang={["faction:Horde"]="La Croisée est le cœur de la présence de la Horde dans les Tarides. Récupérer la solde permet de nourrir et de payer les grunts locaux, afin qu’ils soient prêts à tenir la ligne face aux incursions des centaures et de l’Alliance."},sec={{t="Un vol bestial",b="Des raptors Sunscale ont emporté un coffret d’argent de la tour de garde de La Croisée. Les pièces devaient servir à payer les gardes de la garnison. Les raptors ont traîné le coffret jusqu’à leurs nids communautaires des Terres des Raptors, au sud de Cabestan. Gazrog et les autres surveillants ne savent pas ce qui a poussé les prédateurs à le prendre. Ils se demandent si les raptors convoitent les objets brillants ou s’ils sont plus rusés que les bêtes sauvages ordinaires."}},faq={{q="Qu’est-ce que l’Argent volé ?",a="L’Argent volé est un lourd coffret de pièces destiné à payer les gardes de La Croisée. Des raptors l’ont dérobé dans la tour de garde et l’ont emporté jusqu’à leurs terres de nidification.",al={"qu’est-ce que l’argent volé","qu’est-ce que l’argent"}},{q="Pourquoi les raptors ont-ils volé un coffret de pièces ?",a="Même Gazrog ne sait pas pourquoi les raptors ont pris le coffret. Peut-être que son métal brillant les a attirés, ou qu’une ruse inhabituelle les a poussés à l’emporter au fond de leur repaire.",al={"pourquoi les raptors veulent de l’argent","intelligence des raptors","pourquoi de l’argent"}},{q="Où l’argent a-t-il été emporté ?",a="Les raptors ont emporté le coffret aux Terres des Raptors, un canyon accidenté où se trouvent leurs nids, au sud de Cabestan, dans l’est des Tarides.",al={"emplacement de l’argent volé","où se trouve l’argent"}},{q="Qui recherche l’Argent volé ?",a="Gazrog, un orc en poste à La Croisée, recherche le coffre. L’argent représente un mois entier de solde pour les défenseurs débordés de l’avant-poste.",al={"qui veut l’argent","qui remettre l’argent volé"}}},fp="13,157,15.406.0,26.160.0,41.157.0,27.120.0,37.146.0"}
P.entries["item:stoley-s-bottle"] = {n="Stoley's Bottle",s="La bouteille de Stoley contient du rhum de cale Steamwheedle, envoyé à Baie-du-Butin pour Sea Wolf MacKinley. MacKinley doit goûter le rhum et juger son âpreté.",h="La bouteille de Stoley contient du rhum de cale Steamwheedle, envoyé à Baie-du-Butin pour Sea Wolf MacKinley.",kw={"baie-du-butin","sea wolf mackinley","rhum de cale steamwheedle","stoley","bouteille de stoley","dette de stoley"},sec={{t="Une bouteille amère",b="À Baie-du-Butin, Sea Wolf MacKinley reçoit de Stoley une bouteille de rhum de cale Steamwheedle. MacKinley espère que cette boisson dissipera ses doutes sur l’alcool de Baie-du-Butin. Une seule gorgée suffit à prouver que le rhum est infect. Épais comme du gravier, il brûle comme de la lave, exactement comme Stoley l’avait promis."}},faq={{q="Que contient la bouteille de Stoley ?",a="La bouteille de Stoley contient du rhum de cale Steamwheedle.",al={"contenu de la bouteille","contenu de la bouteille de stoley"}},{q="À qui est destinée la bouteille ?",a="La bouteille de Stoley doit être remise à Sea Wolf MacKinley, à Baie-du-Butin.",al={"qui reçoit la bouteille","à qui remettre la bouteille"}},{q="Pourquoi MacKinley veut-il la bouteille ?",a="MacKinley veut goûter le rhum de cale Steamwheedle de Stoley pour dissiper ses doutes sur l’alcool de Baie-du-Butin.",al={"pourquoi de l’alcool pour mackinley","bouteille de mac kinley"}},{q="Quel goût a le rhum ?",a="MacKinley trouve le rhum infect, épais comme du gravier et brûlant comme de la lave.",al={"le rhum est-il bon","goût du rhum de cale"}},{q="La bouteille règle-t-elle la dette de Stoley ?",a="Après avoir goûté le rhum, MacKinley dit à Stoley qu’il peut garder l’argent qu’il lui doit. La boisson est aussi âpre que Stoley l’avait promis.",al={"dette de stoley et bouteille","mac kinley pardonne-t-il à stoley"}}},fp="15,150,15.272.0,29.50.0,22.70.0,35.109.0,29.72.1,39.114.1"}
P.entries["item:stoley-s-shipment"] = {n="Stoley's Shipment",s="Stoley’s Shipment est une cargaison de rhum volée que des pirates retiennent à la Crique des Gréements. Stoley veut la récupérer pour régler un pari avec “Sea Wolf” MacKinley.",h="Stoley’s Shipment est une cargaison de rhum volée que des pirates retiennent à la Crique des Gréements.",kw={"baie-du-butin","capitaine cuergo","crique des gréements","rhum","sea wolf mackinley","port gentepression","stoley","stoley's shipment","tanaris","pari"},sec={{t="Du rhum pour un pari",b="À la Crique des Gréements, Stoley’s Shipment se trouve parmi les cargaisons volées par les pirates. Le capitaine Cuergo a pris le dernier rhum de Stoley et le garde dans la ville fortifiée des pirates. Stoley a besoin que la cargaison soit rapportée au Port Gentepression pour régler son pari avec “Sea Wolf” MacKinley à la Baie-du-Butin."}},faq={{q="Qu’est-ce que Stoley’s Shipment ?",a="Stoley’s Shipment est une cargaison de rhum volée que le capitaine Cuergo a prise à Stoley.",al={"stoleys shipment","rhum de stoley","cargaison de stoley"}},{q="Qui a volé le rhum ?",a="Le capitaine Cuergo a volé la dernière cargaison de rhum de Stoley.",al={"qui a pris le rhum de stoley","cargaison de cuergo","pirate qui a volé le rhum"}},{q="Où se trouve Stoley’s Shipment ?",a="Stoley’s Shipment est gardée dans la ville fortifiée des pirates, à la Crique des Gréements, en Tanaris.",al={"où se trouve le rhum","cargaison de la crique des gréements","lieu de la cargaison"}},{q="Pourquoi Stoley veut-il récupérer la cargaison ?",a="Stoley veut récupérer le rhum pour régler un pari avec “Sea Wolf” MacKinley à la Baie-du-Butin.",al={"pourquoi rapporter le rhum","pari de stoley","pari sur l’alcool"}},{q="Qui est MacKinley ?",a="“Sea Wolf” MacKinley est le marin de la Baie-du-Butin avec qui Stoley a parié au sujet du rhum de Kalimdor.",al={"sea wolf","pari de mackinley","type de la baie-du-butinin"}}},fp="17,151,15.287.0,28.82.0,18.53.0,29.85.0,39.94.0,17.102.0"}
P.entries["item:stone-circle"] = {n="Cercle de pierres",s="Le Cercle de pierres est une pierre marquée d’un serpent, conservée dans l’atelier de Marvon Rivetseeker à Cabestan. Elle évoque une salle circulaire du Temple englouti.",h="Le Cercle de pierres est une pierre marquée d’un serpent, conservée dans l’atelier de Marvon Rivetseeker à...",kw={"salle circulaire","marvon rivetseeker","cabestan","symbole de serpent","cercle de pierres","temple englouti"},sec={{t="Une marque de serpent",b="Marvon Rivetseeker conserve le Cercle de pierres dans son atelier à Cabestan, où il vous demande de le récupérer. Il se souvient avoir trouvé un symbole de serpent identique après avoir fui le Temple englouti. La pierre pourrait l’aider à se rappeler ce qu’il y a vu."}},faq={{q="Qu’est-ce que le Cercle de pierres ?",a="Le Cercle de pierres est une pierre ronde marquée d’un symbole de serpent, conservée dans l’atelier de Marvon Rivetseeker à Cabestan.",al={"cercle de pierres","quelle est cette pierre"}},{q="Où se trouve le Cercle de pierres ?",a="Marvon Rivetseeker possède le Cercle de pierres dans son atelier à Cabestan.",al={"où trouver le cercle de pierres","trouver la pierre"}},{q="Qui veut le Cercle de pierres ?",a="Marvon Rivetseeker vous demande de récupérer le Cercle de pierres dans son atelier à Cabestan.",al={"qui veut cette pierre","pierre de marvon"}},{q="Que signifie la marque de serpent ?",a="Le symbole de serpent correspond aux statues dont Marvon se souvient dans une salle circulaire du Temple englouti.",al={"symbole de serpent","signification de la marque de serpent"}},{q="Pourquoi Marvon le veut-il ?",a="Marvon espère que la pierre l’aidera à se souvenir de sa fuite du Temple englouti et à en apprendre davantage sur cet endroit.",al={"pourquoi le cercle de pierres","marvon veut la pierre"}}},fp="12,146,14.238.0,25.115.0,26.67.0,27.86.0,32.99.0,24.114.0"}
P.entries["item:stone-of-relu"] = {n="Pierre de Relu",s="Dans les Paluns, la Pierre de Relu disparaît après l’embuscade de raptors contre l’Archéologue Outrepanse. Il pense qu’elle peut révéler les secrets des fossiles anciens.",h="Dans les Paluns, la Pierre de Relu disparaît après l’embuscade de raptors contre l’Archéologue Outrepanse.",kw={"archéologue outrepanse","ligue des explorateurs","fossile","raptor tacheté","prospecteur whelgar","pierre de relu","les paluns"},ang={["faction:Alliance"]="Les expéditions de l’Alliance au Port de Menethil s’appuient sur des artefacts retrouvés comme la Pierre de Relu pour justifier les fouilles difficiles dans les marais périlleux.",["race:Dwarf"]="Pour la Ligue des explorateurs, la Pierre de Relu pourrait aider à reconstituer les origines de la vie ancienne et l’héritage oublié du monde."},sec={{t="Une clé des reliques anciennes",b="La Ligue des explorateurs a découvert la Pierre de Relu. L’Archéologue Outrepanse pense que l’artefact peut déchiffrer les fossiles préhistoriques recueillis en Kalimdor et dans les Royaumes de l’est. Il prévoit d’étudier ses spécimens des Paluns ainsi que le fossile déterré à Sombrivage par le Prospecteur Songerrance."},{t="Perdue dans les marais",b="Sur une route des Paluns, l’Archéologue Outrepanse se rendait auprès du Prospecteur Whelgar quand des raptors tachetés l’ont attaqué. Dans la mêlée, la relique a été perdue, puis avalée par l’une des bêtes. La Ligue recherche maintenant les raptors des marais, dans l’espoir de leur retirer l’ancienne pierre du gosier."}},faq={{q="Qu’est-ce que la Pierre de Relu ?",a="L’Archéologue Outrepanse recherche la Pierre de Relu, un ancien artefact qui, selon lui, peut révéler les mystères cachés et le pouvoir des fossiles préhistoriques.",al={"pierre de relu","à quoi sert cette pierre","artefact de relu"}},{q="Comment la pierre s’est-elle retrouvée dans un raptor ?",a="Des raptors tachetés ont attaqué l’Archéologue Outrepanse sur une route des Paluns, alors qu’il se rendait auprès du Prospecteur Whelgar. Dans la confusion, l’une des bêtes a avalé la pierre perdue.",al={"pourquoi les raptors l’ont-ils","qui a perdu la pierre","comment a-t-elle été perdue"}},{q="Que compte faire Outrepanse de la pierre ?",a="Outrepanse compte utiliser la Pierre de Relu sur le fossile qu’il a retrouvé et sur celui découvert à Sombrivage par le Prospecteur Songerrance. Il espère en déchiffrer les secrets magiques latents et les libérer.",al={"que veut outrepanse","rôle de la pierre de relu"}}},fp="13,142,23.275.0,19.285.0,26.146.0,41.160.0,48.179.0"}
P.entries["item:stone-of-the-tides"] = {n="Pierre des Marées",s="La Pierre des Marées est une ancienne relique gurubashi que le baron Revilgaz convoite pour sa collection. Elle commande aux eaux et peut invoquer des élémentaires d’eau.",h="La Pierre des Marées est une ancienne relique gurubashi que le baron Revilgaz convoite pour sa collection.",kw={"baron revilgaz","malédiction","gurubashi","pierre des marées","artefact troll","eau","élémentaires d’eau"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance dans la Vallée de Strangleronce, vous pouvez aider le baron Revilgaz à retrouver la Pierre pour sa collection d’artefacts trolls anciens.",["race:Troll"]="En tant que troll, vous pouvez reconnaître la Pierre des Marées comme un artefact autrefois utilisé par le Gurubashi Empire."},sec={{t="Une relique engloutie",b="Le baron Revilgaz recherche la Pierre des Marées pour sa collection d’artefacts trolls anciens. Cette relique appartenait autrefois au puissant Gurubashi Empire et peut commander aux eaux et invoquer des élémentaires d’eau. Mais son pouvoir est maudit : son utilisateur s’efface lentement de l’existence."}},faq={{q="Qu’est-ce que la Pierre des Marées ?",a="La Pierre des Marées est un puissant artefact magique autrefois utilisé par le Gurubashi Empire. Elle commande aux eaux et invoque des élémentaires d’eau.",al={"pierre des marées","qu’est-ce que la pierre des marées"}},{q="Que fait la Pierre des Marées ?",a="La Pierre des Marées permet à son utilisateur de contrôler l’eau et d’invoquer des élémentaires d’eau.",al={"pouvoirs de la pierre","que peut faire la pierre des marées"}},{q="Quelle est la malédiction de la Pierre des Marées ?",a="La Pierre des Marées fait lentement disparaître son utilisateur de l’existence.",al={"malédiction de la pierre des marées","pourquoi fait-elle disparaître son utilisateur"}},{q="Pourquoi le baron Revilgaz veut-il la Pierre ?",a="Le baron Revilgaz veut la Pierre des Marées pour sa collection d’artefacts trolls anciens.",al={"revilgaz veut la pierre","pourquoi le baron la veut-il"}},{q="D’où vient la Pierre ?",a="La Pierre des Marées était autrefois utilisée par le Gurubashi Empire.",al={"origine de la pierre","pierre des marées gurubashi"}}},fp="18,149,14.263.0,31.136.0,36.79.0,44.65.1,39.90.0,30.61.0"}
P.entries["item:stonetalon-sap"] = {n="Sève des Serres-Rocheuses",s="Près du lac Mirkfallon et du Pic des Serres-Rocheuses, des sap beasts portent la Sève des Serres-Rocheuses. Jin'Zil, le féticheur Sombrelance, la convoite pour préparer un breuvage destiné à ses prisonniers elfes de la nuit.",h="Près du lac Mirkfallon et du Pic des Serres-Rocheuses, des sap beasts portent la Sève des Serres-Rocheuses.",kw={"jin'zil","malaka'jin","lac mirkfallon","sap beast","pic des serres-rocheuses","sève des serres-rocheuses"},ang={["race:NightElf"]="Un féticheur de la Horde empoisonne des prisonniers elfes de la nuit enfermés avec les éléments natifs des Serres-Rocheuses. C'est un outrage à la nature et à Elune.",["race:Troll"]="Le féticheur Jin'Zil montre comment les Sombrelance peuvent transformer les lieux chers à un ennemi en arme vaudou."},sec={{t="Une récolte amère",b="Des sap beasts près du lac Mirkfallon et du Pic des Serres-Rocheuses portent la Sève des Serres-Rocheuses. Jin'Zil de Malaka'jin la convoite pour préparer un breuvage qu'il appelle magie de la forêt. Il compte l'utiliser sur ses prisonniers elfes de la nuit enfermés, retournant contre eux la nature sauvage qu'ils chérissent."}},faq={{q="Quelles créatures portent la Sève des Serres-Rocheuses ?",a="Des sap beasts près du lac Mirkfallon et sur les pentes menant au Pic des Serres-Rocheuses portent la Sève des Serres-Rocheuses.",al={"où trouver la sève des serres-rocheuses","qui donne la sève des serres-rocheuses","sap beasts"}},{q="À quoi le féticheur Jin'Zil utilise-t-il la sève ?",a="Jin'Zil mélange la sève avec des courser eyes, des twilight whiskers et une Ecaille de dragon-faë pour préparer un breuvage toxique destiné à ses prisonniers elfes de la nuit enfermés.",al={"pourquoi jin'zil veut-il de la sève","recette de magie de la forêt de jin'zil"}},{q="Où trouve-t-on le plus facilement des sap beasts ?",a="Les sap beasts vivent dans les bosquets autour du lac Mirkfallon et le long des chemins menant au Pic des Serres-Rocheuses.",al={"emplacement des sap beasts","sap beasts du lac mirkfallon"}},{q="La sève est-elle magique en elle-même ?",a="La sève porte la vitalité des hauts plateaux des Serres-Rocheuses. Jin'Zil a besoin de mojo troll et de réactifs précis pour la rendre mortelle.",al={"la sève des serres-rocheuses est-elle magique","propriétés de la sève des serres-rocheuses"}}},fx={b24da591={q="Qu'est-ce que la Sève des Serres-Rocheuses ?",a="La Sève des Serres-Rocheuses est une résine naturelle collante recueillie sur les bêtes de sève qui parcourent les Serres-Rocheuses, en particulier autour d'endroits comme le Lac Mirkfallon et le Pic des Serres-Rocheuses. Elle est épaisse, visqueuse et pleine d'essence naturelle brute, ce qui en fait un composant idéal pour les concoctions et les breuvages vaudous qui puisent dans la magie particulière de la nature locale.",al={"qu'est-ce que la sève des serres-rocheuses","objet sève des serres-rocheuses","à propos de la sève des serres-rocheuses"}},["7615d27b"]={q="D'où vient la Sève des Serres-Rocheuses ?",a="Cette sève ambrée est récoltée directement sur les bêtes de sève vivantes qui errent dans les forêts et les rives des lacs des Serres-Rocheuses. Elle n'est pas fabriquée ou distillée par un artisan mortel, mais secrétée naturellement par ces étranges créatures végétales primordiales.",al={"source de la sève des serres-rocheuses","où obtenir de la sève","origine de la sève des serres-rocheuses"}}},fp="14,172,16.241.1,36.94.0,47.141.1,43.96.0,30.123.0"}
P.entries["item:stormpike-banner"] = {n="Bannière foudrepique",s="Dans la Vallée d'Alterac, l'Alliance recrute des harpies courageuses pour récupérer la Bannière foudrepique. L'épreuve se déroule au sud-ouest de Dun Baldar, dans la Caverne de l'Aile de glace.",h="Dans la Vallée d'Alterac, l'Alliance recrute des harpies courageuses pour récupérer la Bannière foudrepique.",kw={"vallée d'alterac","dun baldar","haggerdin","cavernes de l'aile de glace","insigne","proving grounds","bannière foudrepique"},ang={["faction:Alliance"]="En tant que recrue de l'Alliance, rapporter la bannière vous permet d'intégrer la Garde Foudrepique et vous donne le droit de porter son insigne de bataille contre le Clan Loup-de-givre.",["race:Dwarf"]="En tant que nain, vous voyez dans la bannière le symbole des revendications de Forgefer et de la mission du clan Foudrepique : découvrir les reliques de son passé dans toute la vallée."},sec={{t="Un rite d'admission",b="Le Lieutenant Haggerdin envoie les nouvelles recrues de l'Alliance dans la Caverne de l'Aile de glace, au sud-ouest de Dun Baldar. Avant d'affronter les orcs du Clan Loup-de-givre, chaque recrue doit braver les harpies et s'emparer de la Bannière foudrepique. Celles et ceux qui la rapportent obtiennent le rang et l'insigne d'initié de la Garde Foudrepique."}},faq={{q="Où se trouve la Bannière foudrepique ?",a="La Bannière foudrepique se trouve au fond de la Caverne de l'Aile de glace, au sud-ouest de Dun Baldar, dans la Vallée d'Alterac.",al={"emplacement de la bannière","où se trouve la bannière foudrepique","trouver la bannière"}},{q="Pourquoi les recrues doivent-elles récupérer la bannière ?",a="Le Lieutenant Haggerdin demande aux recrues de l'Alliance de prouver leur courage avant de rejoindre les lignes de bataille. Rapporter la bannière leur vaut leur premier insigne Foudrepique.",al={"épreuve des terrains d'entraînement","pourquoi récupérer la bannière","quête de haggerdin"}},{q="Quelles menaces gardent la bannière dans la caverne ?",a="Des harpies sauvages des environs gardent la Caverne de l'Aile de glace et attaquent quiconque y entre en quête de la bannière.",al={"monstres près de la bannière","ennemis de la caverne de l'aile de glace"}},{q="À qui dois-je rapporter la bannière une fois trouvée ?",a="Rapportez la bannière au Lieutenant Haggerdin, l'officier de l'Alliance posté à l'entrée de la caverne, dans les Montagnes d’Alterac.",al={"rendre la bannière","remettre la bannière"}}},fx={["27f01085"]={q="Qu'est-ce que la Bannière foudrepique ?",a="La Bannière foudrepique est un étendard militaire représentant la Garde Foudrepique, l'expédition naine qui mène actuellement la guerre dans la Vallée d'Alterac. Plantée au plus profond des dangereuses cavernes d'Aile-de-glace, infestées de harpies, au sud-ouest de Dun Baldar, la bannière sert de marqueur d'épreuve. Les recrues doivent s'aventurer dans les profondeurs gelées, braver les bêtes sauvages qui y rôdent et récupérer les couleurs pour prouver leur courage et leur dignité à porter l'insigne Foudrepique.",al={"qu'est-ce que la bannière foudrepique","histoire de la bannière foudrepique","à propos de la bannière foudrepique"}}},fp="16,139,19.286.0,38.96.0,44.167.0,46.90.0,41.125.0"}
P.entries["item:stormpike-s-request"] = {n="Requête de Foudrepique",s="Depuis Loch Modan, le Montagnard foudrepique envoie à Furen Barbe-longue une commande pour un magnifique bouclier nain.",h="Depuis Loch Modan, le Montagnard foudrepique envoie à Furen Barbe-longue une commande pour un magnifique...",kw={"forgeron","dun morogh","quartier des nains","furen barbe-longue","requête","bouclier","stormpike","hurlevent"},ang={["profession:Blacksmithing"]="La requête de Foudrepique témoigne du prestige des maîtres fabricants d’armures. Des clients de tous les royaumes recherchent des forgerons nains talentueux.",["race:Dwarf"]="En tant que nain, vous partagez les liens du clan et du métier avec les montagnards qui gardent Khaz Modan et les artisans qui vivent à l’étranger, dans les cités humaines."},sec={{t="Une commande venue du nord",b="Le Montagnard foudrepique monte la garde à Loch Modan, où la frontière naine est dangereuse. Il lui faut un bouclier solide et ne confierait pas ce travail à un forgeron ordinaire. Il admire le savoir-faire de Furen Barbe-longue, fabricant d’armures. Furen a quitté Forgefer et vit désormais parmi les humains, dans le Quartier des Nains de Hurlevent. Foudrepique suppose qu’une rançon de roi l’a attiré vers le sud et compte donc sur les voyageurs pour transmettre sa requête à travers les royaumes."},{t="Le clan Stormpike",b="Furen Barbe-longue reçoit la lettre de Foudrepique dans le Quartier des Nains de Hurlevent et accepte de fabriquer le bouclier. Le clan Stormpike est fier et bien établi. Il est réputé dans tout Khaz Modan pour sa vaillance au combat et sa richesse. Les nouvelles et les affaires de sa terre natale du nord sont les bienvenues. Furen se met donc à l’ouvrage pour honorer la commande du montagnard."}},faq={{q="Qu’est-ce que la Requête de Foudrepique ?",a="Depuis Loch Modan, le Montagnard foudrepique demande à Furen Barbe-longue de lui forger un magnifique bouclier.",al={"quelle est cette lettre","objet de commande de foudrepique","requête de foudrepique"}},{q="Qui a écrit cette lettre ?",a="Le Montagnard foudrepique a écrit cette lettre. C’est une sentinelle naine qui garde les cols de Loch Modan et admire le travail de forge de Furen Barbe-longue.",al={"qui a envoyé la requête de foudrepique","qui l’a écrite","montagnard foudrepique"}},{q="Où faut-il apporter cette lettre ?",a="La lettre est adressée à Furen Barbe-longue, à sa forge dans le Quartier des Nains de Hurlevent.",al={"où apporter la requête de foudrepique","qui reçoit cette lettre","livrer la requête de foudrepique"}},{q="Pourquoi Foudrepique engage-t-il un forgeron établi à Hurlevent ?",a="Foudrepique estime que le talent de Furen est inégalé et n’acceptera aucun autre fabricant d’armures. Furen a quitté Forgefer pour travailler parmi les humains du sud.",al={"pourquoi furen","pourquoi ne pas forger à forgefer","pourquoi envoyer à hurlevent"}}},fx={["181a24c8"]={q="Pourquoi Furen Barbe-longue veut-il la Requête de Foudrepique ?",a="Cette commande écrite demande un bouclier nain finement ouvragé. Furen Barbe-longue, un forgeron résidant dans le Quartier des Nains de Hurlevent, apprécie les affaires avec le célèbre clan Foudrepique. Il sait que la famille est non seulement fière et estimée dans tout Khaz Modan, mais aussi assez riche pour payer gracieusement un savoir-faire exceptionnel.",al={"pourquoi furen veut-il cela","pourquoi la requête de foudrepique est-elle voulue","pourquoi vouloir la requête de foudrepique"}}},fp="19,100,21.422.0,18.312.0,28.87.0,22.131.0,34.93.0,57.137.0"}
P.entries["item:stormwind-armor-marker"] = {n="Bon pour une pièce d'armure de Hurlevent",s="Au Camp de bûcherons du Val d'est, Sara Timberlain accepte un bon pour une pièce d'armure de Hurlevent de la part de ceux qui aident le royaume. Il leur permet de recevoir de l'équipement confectionné par des artisans mandatés par Hurlevent.",h="Au Camp de bûcherons du Val d'est, Sara Timberlain accepte un bon pour une pièce d'armure de Hurlevent de la...",kw={"bon d'armure","cloth and leather armor","camp de bûcherons du val d'est","forêt d’elwynn","réquisition","sara timberlain","bon pour une pièce d'armure de hurlevent"},ang={["faction:Alliance"]="En tant que membre de l'Alliance, vous pouvez voir comment le Camp de bûcherons du Val d'est relie les colonies frontalières au commandement militaire de Hurlevent."},sec={{t="Réquisitions militaires",b="Les commandants de Hurlevent remettent des bons d'armure à ceux qui servent le royaume. Maintenir l'ordre dans la Forêt d’Elwynn met à rude épreuve les ressources de Hurlevent. Les commandants utilisent donc parfois ces bons officiels à la place de l'équipement standard dans les avant-postes militaires. Un bon atteste le service de son porteur et permet à un artisan local sous contrat de lui fournir une armure sur mesure."},{t="Ravitaillement du Val d'est",b="Sara Timberlain et d'autres artisans travaillent sous contrat avec l'armée de Hurlevent au Camp de bûcherons du Val d'est. Le camp se trouve à la frontière orientale de la Forêt d’Elwynn, où ils utilisent des matériaux locaux pour confectionner des vêtements de protection en tissu et en cuir. Présentez-y un bon pour recevoir une protection ajustée, destinée à garder les bois environnants."}},faq={{q="À quoi sert le bon pour une pièce d'armure de Hurlevent ?",a="Le bon pour une pièce d'armure de Hurlevent est un bon militaire officiel destiné à ceux qui aident les gardes de Hurlevent. Il prouve votre service et vous permet de recevoir une armure de protection auprès d'un artisan sous contrat avec l'armée.",al={"qu'est-ce qu'un bon d'armure","utilité du bon","utilisation du bon de hurlevent"}},{q="Qui accepte le bon ?",a="Sara Timberlain accepte le bon au Camp de bûcherons du Val d'est, juste de l'autre côté de la rivière, dans la Forêt d’Elwynn. Sous contrat avec l'armée de Hurlevent, elle fournit de l'équipement en tissu et en cuir ajusté sur mesure.",al={"qui accepte le bon","où remettre le bon","bon sara timberlain"}},{q="Pourquoi Hurlevent utilise-t-elle des bons au lieu de distribuer directement des armures ?",a="Hurlevent utilise des bons, car ses postes de garde isolés ne disposent pas toujours des réserves, des forges ou des ateliers de couture nécessaires pour équiper les recrues sur place. Les commandants sur le terrain peuvent envoyer les recrues chez des artisans locaux comme Sara Timberlain, qui disposent d'ateliers dédiés.",al={"pourquoi des bons plutôt que des armures","pourquoi des bons militaires","bons militaires d'elwynn"}},{q="Quel type d'équipement le bon permet-il d'obtenir ?",a="Le porteur du bon peut choisir une pièce d'armure en tissu ou en cuir, confectionnée sur mesure par un fournisseur de l'armée sous contrat.",al={"quelle armure vais-je recevoir","récompenses du bon","tissu ou cuir"}}},fx={e5398b12={q="Qu'est-ce que le Bon pour une pièce d'armure de Hurlevent ?",a="Il s'agit d'un bon militaire officiel émis au nom de l'armée de Hurlevent. Plutôt que de transporter des ensembles d'équipement de protection encombrants à travers la Forêt d’Elwynn, les commandants locaux émettent ce jeton comme garantie de réquisition, autorisant le porteur à réclamer une armure en tissu ou en cuir fraîchement fabriquée auprès d'un armurier agréé.",al={"qu'est-ce que le bon pour une pièce d'armure de hurlevent","bon pour une armure","qu'est-ce que le bon"}},["618263b5"]={q="Pourquoi Sara Timberlain veut-elle le Bon pour une pièce d'armure de Hurlevent ?",a="Sara Timberlain a été chargée par l'armée de Hurlevent d'équiper leurs recrues et volontaires en armures en tissu et en cuir. Elle exige le bon comme preuve officielle d'autorisation avant de remettre son équipement artisanal, garantissant que les fournitures du royaume ne vont qu'aux défenseurs reconnus.",al={"pourquoi sara veut-elle le bon","pourquoi apporter le bon à eastvale","pourquoi avoir besoin du bon d'armure"}},["3e7f2980"]={q="D'où vient le Bon pour une pièce d'armure de Hurlevent, et qui l'a créé ?",a="Le bon est délivré au nom de Stormwind Army par le Garde Thomas, à son poste près du pont oriental d'Elwynn, aux défenseurs qui prouvent leur perspicacité et leur vaillance. Il porte l'autorité de l'armée du royaume et charge les artisans locaux d'équiper les recrues aux frais de la couronne.",al={"qui a créé le bon pour une pièce d'armure","d'où vient le bon","qui donne le bon pour une pièce d'armure"}}},fp="22,177,21.341.0,21.324.0,50.195.0,23.195.0,69.244.0,47.128.0"}
P.entries["item:stoutmantle-s-response-to-solomon"] = {n="Réponse de Roidemantel à Salomon",s="Depuis la Colline des Sentinelles, Gryan Roidemantel informe le Comté-du-Lac qu’aucun soldat ne peut être envoyé aux Carmines.",h="Depuis la Colline des Sentinelles, Gryan Roidemantel informe le Comté-du-Lac qu’aucun soldat ne peut être...",kw={"gryan","comté-du-lac","lettre","magistrat salomon","messenger to westfall","people's militia","les carmines","salomon","roidemantel","marche de l’ouest"},ang={["faction:Alliance"]="Pour l’Alliance, cette lettre montre des villages isolés qui se demandent mutuellement de l’aide tandis que la capitale retient ses forces.",["race:Human"]="En tant que défenseur humain, vous voyez la Marche de l’Ouest et les Carmines lutter pour survivre sans les gardes royaux de Hurlevent."},sec={{t="Une demande refusée",b="Le magistrat Salomon du Comté-du-Lac demande l’aide de la Colline des Sentinelles, alors que les orcs Rochenoire et les gnolls assiègent sa ville. Gryan Roidemantel lui répond par écrit et déplore les pertes du Comté-du-Lac. Pourtant, la Marche de l’Ouest mène sa propre guerre. La People's Militia s’est formée après le retrait de la garnison de la Couronne, et les fermiers et volontaires combattent désormais seuls la Confrérie défias. Les forces de Roidemantel sont déjà éprouvées et dispersées, sans hommes à envoyer vers une autre frontière abandonnée."},{t="L’abandon du royaume",b="Les Carmines et la Marche de l’Ouest partagent un sort sombre. La cour royale de Hurlevent les a toutes deux abandonnées. Le roi Varian Wrynn a disparu, et l’armée permanente du royaume est mystérieusement tenue à l’écart des frontières provinciales. Les villes isolées doivent former des patrouilles de volontaires ou périr. Salomon reçoit la réponse scellée et comprend qu’aucune des deux régions ne peut sauver l’autre. Le royaume se délite tandis que la capitale garde le silence."}},faq={{q="Que dit la réponse de Roidemantel ?",a="Gryan Roidemantel écrit que la Marche de l’Ouest mène une guerre brutale contre la Confrérie défias et a perdu l’armée de Hurlevent, comme les Carmines. Il déplore la mort des défenseurs tombés au combat, mais refuse la demande de renforts du magistrat Salomon.",al={"contenu de la lettre","lettre de roidemantel","texte de la réponse à salomon"}},{q="Pourquoi Salomon a-t-il d’abord demandé de l’aide à la Marche de l’Ouest ?",a="Le Comté-du-Lac subit de lourdes attaques des gnolls et des orcs Rochenoire. La demande de renforts du magistrat Salomon au général Marcus Jonathan, à Hurlevent, n’a amené aucune troupe. Il demande donc à la People's Militia, de l’autre côté d’Elwynn, l’aide de défenseurs des frontières comme lui.",al={"pourquoi demander de l’aide à la marche de l’ouest","salomon demande de l’aide à roidemantel","pourquoi le comté-du-lac demande la milice"}},{q="Pourquoi la People's Militia ne peut-elle envoyer de troupes ?",a="La People's Militia est une armée de volontaires qui lutte pour défendre la Colline des Sentinelles et les plaines alentour contre la Confrérie défias. Les pertes s’accumulent chaque jour et, sans le soutien de l’armée régulière, envoyer des combattants au Comté-du-Lac laisserait la Marche de l’Ouest sans défense.",al={"pourquoi la milice ne peut pas aider","la marche de l’ouest peut-elle aider les carmines","pourquoi refuser salomon"}},{q="Pourquoi l’armée de Hurlevent ne protège-t-elle pas ces villes ?",a="Personne dans les deux villes ne sait pourquoi l’armée de Hurlevent est absente. Roidemantel écrit que Hurlevent a retiré ses troupes et laissé la Marche de l’Ouest sans défense, tandis que Salomon se demande ce qui a pu détourner l’armée de son peuple. Les deux régions comptent sur leurs volontaires locaux.",al={"où est l’armée de hurlevent","pourquoi hurlevent n’aide-t-elle pas","abandon de hurlevent"}}},fx={["399f6159"]={q="Qu'est-ce que la Réponse de Roidemantel à Salomon ?",a="Il s'agit d'une dépêche officielle écrite par Gryan Roidemantel, commandant de The People's Militia à la Colline des Sentinelles, adressée au magistrat Salomon dans les Carmines. La lettre annonce la triste nouvelle que la Marche de l’Ouest est engluée dans sa propre guerre désespérée contre The Defias Brotherhood et ne peut envoyer aucun soldat ni ressource pour aider le Comté-du-Lac.",al={"qu'est-ce que la réponse de roidemantel","lettre de roidemantel à salomon","réponse de gryan au comté-du-lac"}},["945d8c3a"]={q="D'où vient la Réponse de Roidemantel à Salomon et qui l'a écrite ?",a="Elle a été rédigée par Gryan Roidemantel lui-même à la Colline des Sentinelles, dans la Marche de l’Ouest. Après avoir lu l'appel au renfort du magistrat Salomon, Roidemantel a rédigé la réponse et vous l'a confiée pour la rapporter à travers le royaume jusqu'aux montagnes des Carmines.",al={"qui a écrit la réponse de roidemantel","qui a créé la réponse de roidemantel à salomon","d'où vient la réponse de roidemantel"}},c46920a1={q="Pourquoi quelqu'un voudrait-il la Réponse de Roidemantel à Salomon ?",a="Le magistrat Salomon attend cette réponse au Comté-du-Lac, dans l'espoir d'obtenir une aide militaire pour repousser l'invasion orque du clan Rochenoire qui menace les Carmines. Il a besoin de la parole de Roidemantel pour savoir si The People's Militia peut chevaucher jusqu'au Comté-du-Lac pour le défendre ou si sa ville doit affronter ses périls seule.",al={"qui veut la réponse de roidemantel","pourquoi remettre la lettre de roidemantel","pourquoi apporter la réponse à salomon"}}},fp="33,116,13.458.0,21.393.1,42.230.0,57.236.0,48.253.0,52.254.0"}
P.entries["item:strange-smelling-powder"] = {n="Poudre à l'odeur étrange",s="À Loch Modan, la Poudre à l'odeur étrange inquiète les ingénieurs qui enquêtent sur un sabotage. L'ingénieur en chef Hinderweir craint qu'elle soit explosive et cherche l'avis d'un expert.",h="À Loch Modan, la Poudre à l'odeur étrange inquiète les ingénieurs qui enquêtent sur un sabotage.",kw={"a dark threat looms","ashlan rictus-de-pierre","dun modr","hinderweir","loch modan","poudre à l'odeur étrange","viaduc de thandol"},ang={["profession:Engineering"]="En tant qu'ingénieur, vous reconnaîtrez peut-être l'odeur de soufre des mélanges explosifs instables, différente de celle des formules standard utilisées dans les avant-postes miniers de l'Alliance.",["race:Dwarf"]="En tant que nain, vous savez qu'il est primordial de protéger les ouvrages de pierre et les réservoirs de Loch Modan. Tout signe d'explosifs ennemis représente une crise immédiate pour le clan."},sec={{t="Une découverte volatile",b="La Poudre à l'odeur étrange a été trouvée parmi des traces de sabotage visant les infrastructures de Loch Modan. L'ingénieur en chef Hinderweir craint qu'il s'agisse d'un explosif conçu, différent de la poudre habituellement utilisée dans les mines. Il ne peut identifier ni son mélange ni son origine, et refuse d'y toucher lui-même. La moindre étincelle pourrait provoquer un désastre."},{t="La route vers le nord",b="L'ingénieur en chef Hinderweir envoie des échantillons par la Porte d'Algaz, jusque dans les Paluns, pour les faire examiner. Ashlan Rictus-de-pierre, expert chevronné en explosifs au sein du régiment de Dun Modr, près du Viaduc de Thandol, doit inspecter les grains et déterminer quel type d'explosion les saboteurs préparent."}},faq={{q="Qu'est-ce que la Poudre à l'odeur étrange ?",a="La Poudre à l'odeur étrange est un résidu chimique suspect découvert à Loch Modan lors d'une enquête sur un sabotage local. Son odeur forte et sa composition portent les ingénieurs nains à croire qu'elle est explosive.",al={"qu'est-ce que la poudre à l'odeur étrange","qu'est-ce que cette poudre","poudre loch modan"}},{q="Pourquoi l'ingénieur en chef Hinderweir veut-il la faire examiner ?",a="L'ingénieur en chef Hinderweir soupçonne cette poudre d'être un explosif spécialisé. Il lui faut l'avis d'un expert en démolitions lourdes pour comprendre la menace qui pèse sur Loch Modan.",al={"pourquoi examiner la poudre","poudre hinderweir","qui a besoin de cette poudre"}},{q="Qui peut identifier la poudre ?",a="L'ingénieur en chef Hinderweir demande aux voyageurs d'apporter l'échantillon à Ashlan Rictus-de-pierre, expert en explosifs au sein du régiment de Dun Modr, près du Viaduc de Thandol.",al={"qui identifie la poudre","où apporter la poudre","expert en explosifs"}},{q="Pourquoi le transport de la poudre est-il dangereux ?",a="La poudre pourrait être volatile, et son transport vous oblige à traverser la Porte d'Algaz puis les routes marécageuses et hostiles des Paluns.",al={"la poudre est-elle dangereuse","pourquoi est-elle dangereuse"}}},fp="23,168,20.322.0,14.284.1,32.196.0,52.153.0,28.158.0,41.130.0"}
P.entries["item:strangely-marked-box"] = {n="Boîte aux marques étranges",s="À Sombrivage, les runes de la Boîte aux marques étranges désignent une cargaison naga échouée sur des tortues de mer mortes. Leur présence suggère que les tortues ne se sont pas échouées par hasard.",h="À Sombrivage, les runes de la Boîte aux marques étranges désignent une cargaison naga échouée sur des tortues...",kw={"auberdine","chariot","sombrivage","greymist","gwennyth bly'leggonde","naga","tortue de mer","boîte aux marques étranges"},ang={["class:Priest"]="En tant que prêtre, vous aidez les érudits du Temple de la Lune à Auberdine à sécuriser les reliques du rivage tandis qu'ils s'efforcent de protéger la côte de la corruption marine.",["race:NightElf"]="Les boîtes de ravitaillement naga attachées aux tortues de mer natives de Sombrivage avertissent les kaldorei que leurs anciens parents mutants débarquent depuis la Grande mer."},sec={{t="Trophées des profondeurs",b="Des tortues de mer mortes et d'autres créatures marines s'échouent sur les plages de Sombrivage. Certaines portent des harnais brisés et des chariots attachés à leur carapace. Parmi les débris se trouvent des boîtes scellées couvertes de runes étrangères et sinueuses. Les murlocs Greymist s'abritent dans les côtes creuses et les chariots brisés, se nourrissent des carcasses et gardent ce qui en reste."},{t="Preuves de l'expansion naga",b="Gwennyth Bly'Leggonde, chercheuse au Temple de la Lune à Auberdine, reconnaît les marques. L'écriture et les chariots appartiennent aux nagas, qui utilisent des tortues géantes pour transporter des provisions et du matériel de guerre sur la terre ferme. Les boîtes situent les nagas le long des côtes du nord et suggèrent qu'ils poussent peut-être leurs montures vers le sud, en direction d'Orneval. Le clergé d'Auberdine envoie les reliques à Darnassus pour les faire étudier."}},faq={{q="Où trouver la Boîte aux marques étranges ?",a="La boîte se trouve dans un chariot abandonné, attaché à une tortue de mer morte sur la côte de Sombrivage. Les murlocs Greymist se nourrissent près des carcasses et gardent ce qui en reste.",al={"où trouver la boîte aux marques étranges","emplacement de la boîte","boîte dans un chariot de tortue"}},{q="Qui a fabriqué la Boîte aux marques étranges ?",a="Les nagas ont fabriqué la boîte et ses inscriptions. Ils attachent des chariots à des tortues de mer vivantes pour transporter provisions, armes et équipement depuis les profondeurs océaniques jusqu'aux côtes de Kalimdor.",al={"qui a fabriqué la boîte","marques sur la boîte","runes de la boîte","que signifient les marques"}},{q="Qui veut cette boîte à Auberdine ?",a="Gwennyth Bly'Leggonde, chercheuse au Temple de la Lune à Auberdine, récupère la boîte pour étudier les échouages étranges et la menace naga.",al={"à qui remettre la boîte","remise de la boîte","qui veut la boîte"}},{q="Pourquoi les tortues de mer transportaient-elles ces boîtes ?",a="Les nagas utilisent des tortues de mer géantes pour transporter des provisions et du matériel de guerre sur la terre ferme, grâce à des harnais et des chariots attachés à leur dos. Gwennyth soupçonne qu'une tortue a été tuée alors qu'elle se dirigeait vers le sud, peut-être en direction d'Orneval.",al={"pourquoi les tortues ont des boîtes","chariots de tortues","pourquoi les tortues sont harnachées"}},{q="Que devient la boîte après l'avoir remise à Gwennyth ?",a="Gwennyth Bly'Leggonde envoie la boîte et les résultats de l'étude côtière au Temple de la Lune à Darnassus, où les dirigeants elfes de la nuit pourront étudier l'étendue de l'influence naga.",al={"où va la boîte","boîte envoyée à darnassus"}}},fx={["981461f5"]={q="Qu'est-ce que la Boîte aux marques étranges ?",a="Il s'agit d'une cargaison découverte à l'intérieur d'un chariot disloqué attaché à la carapace d'une tortue de mer échouée le long de la côte de Sombrivage. Marquée de runes particulières, la caisse sert de preuve physique d'un transport maritime organisé le long de la côte, abandonnée après que la créature porteuse ait péri et ait été par la suite envahie par des charognards.",al={"qu'est-ce que la boîte marquée","qu'est-ce que la boîte aux marques étranges","objet boîte aux marques étranges"}},b4ce745f={q="Pourquoi Gwennyth Bly'Leggonde veut-elle la Boîte aux marques étranges ?",a="Gwennyth Bly'Leggonde cherche la boîte au nom de The Temple of the Moon pour enquêter sur la raison pour laquelle des créatures marines massives s'échouent sur Sombrivage. Le déchiffrement des marques confirme que les tortues étaient harnachées et utilisées comme bêtes de somme par des naga hostiles transportant des fournitures à l'intérieur des terres, des indices qu'elle transmet directement aux érudits de Darnassus.",al={"pourquoi gwennyth veut-elle la boîte","pourquoi livrer la boîte aux marques étranges","utilité de la boîte marquée"}}},fp="20,168,20.323.0,26.395.1,40.154.0,34.171.0,32.145.0,46.218.0,52.162.0"}
P.entries["item:strigid-owl-feather"] = {n="Plume de Hibou Strigid",s="Dans les branches de Teldrassil, les chouettes strigides laissent des plumes de hibou strigid à ramasser. Zenn Vilsabot les convoite pour ses affaires secrètes.",h="Dans les branches de Teldrassil, les chouettes strigides laissent des plumes de hibou strigid à ramasser.",kw={"dolanaar","réactifs","chouette strigide","plume de hibou strigid","hurleur strigide","teldrassil","zenn vilsabot"},ang={["class:Druid"]="En tant que druide, vous tenez en haute estime les chasseurs ailés de Teldrassil. Les voir dépouillés de leurs plumes sous de faux prétextes, pour obtenir des réactifs suspects, peut vous troubler.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous savez que les chouettes de Teldrassil sont des créatures d’Élune. L’exploitation qu’en fait Zenn Vilsabot insulte le bois sacré."},sec={{t="Plumage forestier et sombres affaires",b="Les chouettes strigides et les hurleurs strigides chassent dans la Crown of the Earth, laissant des plumes et du duvet sur le sol forestier. À l’extérieur de Dolanaar, le satyre renégat Zenn Vilsabot envoie des voyageurs inexpérimentés sur la route depuis Sombrevallon. Il leur demande de ramasser des plumes strigides, de la soie d’araignée et des crocs de nightsaber pour ses affaires louches."}},faq={{q="Où trouver des plumes de hibou strigid ?",a="Les chouettes strigides et les hurleurs strigides vivent dans les bois autour de Dolanaar et partout sur Teldrassil. Vous pouvez y ramasser leurs plumes.",al={"lieu des plumes","où trouver des plumes de hibou strigid","récolte de plumes de hibou"}},{q="Qui veut des plumes de hibou strigid ?",a="Zenn Vilsabot, un satyre qui se trouve sur le sentier menant à Dolanaar, vous demande de ramasser ces plumes, ainsi que de la soie de webwood et des crocs de nightsaber.",al={"qui veut des plumes de hibou","rendre les plumes de hibou","plumes de hibou zenn"}},{q="Que fait Zenn Vilsabot des plumes ?",a="Zenn affirme que ces plumes sont des réactifs pour ses affaires secrètes dans la forêt. Il aime aussi duper les recrues naïves pour leur faire accomplir ses sales besognes.",al={"pourquoi zenn veut des plumes","utilité des réactifs de zenn"}}},fx={c56fcaa2={q="Qu'est-ce qu'une Plume de Hibou Strigid ?",a="Une Plume de Hibou Strigid est une plume prélevée sur les hiboux strigid prédateurs originaires des branches de Teldrassil. Bien qu'il s'agisse en apparence de simples plumes d'oiseau, elles servent de puissants réactifs naturels pour ceux qui s'adonnent à l'artisanat, à l'alchimie ou à des rites forestiers plus sombres.",al={"plume de hibou strigid","qu'est-ce qu'une plume de hibou strigid","plume de hibou à teldrassil"}},["91562481"]={q="D'où vient une Plume de Hibou Strigid ?",a="Ces plumes sont récoltées directement sur les hiboux strigid et les hurleurs strigid nichant dans les forêts de Teldrassil, en particulier autour de Dolanaar. En tant que matériaux biologiques naturels perdus ou pris sur les prédateurs aviaires de la forêt, elles sont produites par la nature plutôt que façonnées par des mains mortelles.",al={"d'où viennent les plumes de hibou strigid","source de la plume de hibou strigid","qui a créé la plume de hibou strigid"}}},fp="19,121,32.327.1,38.133.0,31.125.0,45.147.1"}
P.entries["item:sturdy-dragonmaw-shinbone"] = {n="Solide tibia de Gueule-de-dragon",s="Au Campement de Hargnecroc, les orcs renégats Gueule-de-dragon fournissent des tibias solides pour les armures. À Fossoyeuse, Velora Nitely en a besoin pour armer les jambières des guerriers.",h="Au Campement de Hargnecroc, les orcs renégats Gueule-de-dragon fournissent des tibias solides pour les...",kw={"campement de hargnecroc","tibia de dragonmaw","jambières","solide tibia de gueule-de-dragon","fossoyeuse","velora nitely","les paluns"},ang={["class:Warrior"]="En tant que guerrier, vous testez à la main la densité des os d’orcs et rassemblez des pièces pour armer une armure sur mesure. Ce travail témoigne de votre puissance physique.",["race:Undead"]="En tant que mort-vivant, vous voyez le pragmatisme des Réprouvés dans la façon dont Velora Nitely utilise les os de leurs ennemis pour équiper les champions de la Dame noire."},sec={{t="Des os pour l’armature",b="Velora Nitely a besoin d’os assez solides pour supporter la tension de jambières brutales. Les orcs renégats Gueule-de-dragon du Campement de Hargnecroc, au centre des Paluns, ont une ossature épaisse, et leurs tibias peuvent renforcer l’armure. Chaque os est testé à la main. Les guerriers ne gardent que ceux qui résistent à la rupture."}},faq={{q="Qu’est-ce qui rend ces tibias plus solides que les tibias ordinaires ?",a="Les orcs Gueule-de-dragon ont une ossature épaisse, mais une fracture peut rendre un os trop fragile pour une armure. Un guerrier plie chaque tibia à la main et ne garde que ceux qui résistent à la rupture.",al={"pourquoi des tibias solides","solidité des os gueule-de-dragon","tester les tibias"}},{q="Qui veut des Dragonmaw Shinbones solides ?",a="Velora Nitely, une artisane d’armures de Fossoyeuse, veut des Dragonmaw Shinbones solides. Elle les utilise comme montants d’armature pour fabriquer des jambières brutales destinées aux guerriers prometteurs de la Horde.",al={"qui a besoin de tibias","os de velora nitely","remettre des dragonmaw shinbones"}},{q="Où ces os sont-ils récoltés ?",a="Ces os proviennent d’orcs renégats Gueule-de-dragon des Paluns, au sud des Hautes-terres Arathies. On en trouve surtout au Campement de Hargnecroc, dans les collines au sud-ouest du Viaduc de Thandol.",al={"où trouver des dragonmaw shinbones","emplacement des tibias de gueule-de-dragon","os de hargnecroc"}},{q="Pourquoi Velora Nitely utilise-t-elle des os d’orcs pour les armures ?",a="Les forgerons réprouvés utilisent des os, des tendons et du métal pour fabriquer un équipement de guerre durable. Le clan Gueule-de-dragon est hostile à la Horde de Thrall, alors les forgerons réprouvés utilisent ses dépouilles comme matériau résistant.",al={"pourquoi des os d’orcs","armure en os des réprouvés","artisanat osseux de velora"}}},fp="25,163,19.292.0,58.180.0,37.166.0,31.189.0,47.185.0"}
P.entries["item:sully-balloo-s-letter"] = {n="Lettre de Sully Balloo",s="Sous le Viaduc de Thandol, la Lettre de Sully Balloo porte les adieux d’un soldat à Sara, à Forgefer. Ses mots témoignent de l’amour qu’il lui a porté jusqu’à ses derniers jours.",h="Sous le Viaduc de Thandol, la Lettre de Sully Balloo porte les adieux d’un soldat à Sara, à Forgefer.",kw={"hautes-terres arathies","forgefer","lettre","sara balloo","sully balloo","viaduc de thandol","enveloppe gorgée d’eau","les paluns"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez porter les dernières pensées d’un soldat tombé à sa veuve, afin qu’elles ne sombrent pas dans l’oubli sous le pont.",["race:Dwarf"]="En tant que nain, vous pouvez voir dans cette lettre le sacrifice des simples montagnards et soldats qui gardent les hauts ponts et les cols de montagne de Khaz Modan."},sec={{t="Un dernier adieu sous les flots",b="Sous le Viaduc de Thandol, la route des Paluns mène vers les Hautes-terres Arathies. Sous les eaux tumultueuses, les restes squelettiques d’un nain gisent, coincés. Une enveloppe fragile et gorgée d’eau repose dans sa main. À l’intérieur, la lettre commence ainsi : « Ma chère Sara... » Le parchemin a souffert sous l’eau, mais l’encre témoigne encore de l’affection du défenseur nain durant ses derniers jours ou ses dernières heures. Il n’est jamais revenu à Forgefer."},{t="Porter la lettre à Forgefer",b="À Forgefer, Sara Balloo attend sans savoir ce qu’il est advenu de son époux après son départ à la guerre. Les dernières pensées de Sully lui apportent une sombre conclusion et confirment la crainte qui l’habitait : il est mort loin de chez lui, sous les courants du passage du nord. Son dévouement lui parvient dans ses propres mots."}},faq={{q="Où trouve-t-on la Lettre de Sully Balloo ?",a="Vous trouvez la lettre dans une enveloppe gorgée d’eau, serrée dans la main d’un nain squelette sous les eaux du Viaduc de Thandol, entre les Paluns et les Hautes-terres Arathies.",al={"emplacement de la lettre","où trouver la lettre de sully","où trouver la lettre de sully balloo"}},{q="Qui était Sully Balloo ?",a="Sully Balloo était un soldat nain mort en défendant le passage du nord, près du Viaduc de Thandol. Ses restes gisent, coincés sous les courants du fleuve.",al={"qui est sully balloo","histoire de sully balloo","qu’est-il arrivé à sully"}},{q="À qui la lettre est-elle adressée ?",a="La lettre est adressée à Mme Sara Balloo, l’épouse de Sully, qui vit à Forgefer.",al={"qui reçoit la lettre","qui est sara balloo","où remettre la lettre de sully"}},{q="Que se passe-t-il quand vous remettez la lettre à Sara Balloo ?",a="Quand Sara Balloo lit la lettre, elle est bouleversée d’apprendre que son époux est mort sous les eaux. Elle peut tout de même lire les derniers mots qu’il lui a écrits avec amour.",al={"réaction de sara balloo","remise de la lettre","fin de quête de la lettre de sully"}}},fx={efe638b9={q="Qu'est-ce que la Lettre de Sully Balloo ?",a="Il s'agit d'une lettre tendre, déchirée par la guerre, rédigée avec le plus grand soin par un soldat nain nommé Sully Balloo. Trouvée préservée sous les eaux glacées du Viaduc de Thandol, elle contient les derniers mots sincères écrits à sa femme à Forgefer avant sa mort au combat.",al={"qu'est-ce que la lettre de sully","lettre de sully balloo","à propos de la lettre de sully balloo"}},b8624ec6={q="D'où vient la Lettre de Sully Balloo et qui l'a écrite ?",a="La lettre a été écrite par Sully Balloo, un soldat de l'Alliance servant sur la ligne de front au Viaduc de Thandol entre les Paluns et les Hautes-terres Arathies. Elle a survécu immergée dans une enveloppe imbibée d'eau, tenue dans l'étreinte de ses restes submergés sous le grand pont.",al={"qui a écrit la lettre de sully balloo","d'où vient la lettre de sully","créateur de la lettre de sully balloo"}},b54d6872={q="Pourquoi quelqu'un voudrait-il la Lettre de Sully Balloo ?",a="Sa destinataire, Sara Balloo, réside à Forgefer, ignorant le décès tragique de son mari. Remettre la lettre accomplit le dernier souhait d'un soldat tombé au combat et apporte une conclusion douce-amère à une veuve en deuil attendant des nouvelles de son bien-aimé.",al={"pourquoi remettre la lettre de sully balloo","qui veut la lettre de sully","pourquoi apporter la lettre à sara balloo"}}},fp="21,158,34.417.0,21.302.1,37.168.0,21.155.0,31.82.0,56.160.1"}
P.entries["item:sundried-driftwood"] = {n="Sundried Driftwood",s="Sundried Driftwood borde le Marais des Chagrins. Gardien Biggs a besoin de bois sec et solide pour réparer son chariot.",h="Sundried Driftwood borde le Marais des Chagrins.",kw={"littoral","bois flotté","rempart-du-néant","sundried driftwood","marais des chagrins","chariot","gardien biggs"},sec={{t="Bois du littoral",b="Gardien Biggs a besoin de bois pour réparer son chariot, mais les arbres des marais sont trop spongieux et enchevêtrés. Sur la côte est, le soleil sèche le bois flotté en morceaux légers et résistants qui peuvent lui convenir."}},faq={{q="Où trouver Sundried Driftwood ?",a="Sundried Driftwood se trouve sur la côte du Marais des Chagrins. Gardien Biggs vous indique de chercher vers l'est.",al={"emplacement de sundried driftwood","où trouver du bois flotté","bois du littoral"}},{q="Qui a besoin du bois flotté ?",a="Gardien Biggs a besoin de Sundried Driftwood pour réparer son chariot.",al={"qui veut du bois flotté","bois pour biggs","qui a besoin du bois"}},{q="Pourquoi Biggs a-t-il besoin de ce bois ?",a="Gardien Biggs a besoin de bois sec et solide pour réparer son chariot et pouvoir rejoindre Rempart-du-Néant.",al={"pourquoi biggs a besoin de bois","réparation du chariot","réparer le chariot de biggs"}},{q="Pourquoi ne pas utiliser les arbres des marais ?",a="Gardien Biggs explique que les arbres des marais sont spongieux et enchevêtrés. Il cherche donc du bois flotté sec sur la côte.",al={"bois des arbres des marais","pourquoi pas le bois des marais","bois spongieux"}},{q="À quoi ressemble le bois flotté ?",a="Gardien Biggs décrit ce bois comme léger, mais résistant, et affirme qu'il conviendra parfaitement à son chariot.",al={"le bois flotté est-il résistant","qualité du bois","bois léger et résistant"}},{q="Combien de morceaux Biggs lui faut-il ?",a="Gardien Biggs demande huit morceaux de Sundried Driftwood.",al={"quantité de bois flotté","nombre de morceaux","huit morceaux de bois flotté"}}},fp="18,115,19.189.0,36.111.0,24.59.0,30.85.0,28.102.0,27.89.0,32.58.0"}
P.entries["item:sunscorched-shell"] = {n="Coquille brûlée par le soleil",s="Sous Haut-perchoir, la chaleur du désert durcit les coquilles d’œufs de wyverne. L’armurier Mathiel, à Darnassus, les utilise pour fabriquer une laque destinée aux mailles.",h="Sous Haut-perchoir, la chaleur du désert durcit les coquilles d’œufs de wyverne.",kw={"darnassus","furen barbe-longue","haut-perchoir","armure de mailles","mathiel","coquille brûlée par le soleil","mille pointes","wyverne"},ang={["class:Warrior"]="En tant que guerrier cherchant à se protéger avec une armure de mailles, vous pouvez aider Mathiel à rassembler des coquilles d’œufs résistantes pour renforcer les armures.",["profession:Blacksmithing"]="En tant que forgeron, vous pouvez découvrir comment des artisans chevronnés utilisent des revêtements minéraux naturels pour créer une laque protectrice destinée aux armures de mailles."},sec={{t="Couvées du désert",b="Les wyvernes de Haut-perchoir pondent leurs œufs sur les aiguilles rocheuses des plateaux du sud de Kalimdor. Sous leurs perchoirs, les coquilles abandonnées cuisent au soleil du désert et dans les vents brûlants. Leurs fragiles vestiges conservent une résistance naturelle qui attire l’attention des artisans chevronnés."},{t="La laque d’un artisan",b="À Darnassus, l’armurier Mathiel étudie des méthodes d’abord mises à l’essai par son confrère, le forgeron nain Furen Barbe-longue. Il transforme les coquilles en une laque fine pour les armures de mailles. Ce revêtement renforce les maillons métalliques sans alourdir celui qui les porte."}},faq={{q="Où trouve-t-on les Sunscorched Shells ?",a="Vous pouvez en trouver sous les nids de wyvernes de Haut-perchoir, un haut plateau qui s’élève du fond du canyon, dans l’ouest des Mille pointes.",al={"emplacement de la coquille brûlée par le soleil","où trouver des coquilles","coquilles de haut-perchoir"}},{q="De quelle créature ces coquilles proviennent-elles ?",a="Ce sont des coquilles d’œufs brisées des wyvernes de Haut-perchoir, qui nichent au sommet des plateaux des Mille pointes.",al={"qui a pondu ces œufs","œufs de wyverne","origine des coquilles"}},{q="Pourquoi Mathiel veut-il des Sunscorched Shells ?",a="Mathiel veut essayer les méthodes de forge d’armures découvertes par Furen Barbe-longue. Il transforme les coquilles durcies en une laque résistante qui renforce les maillons des armures de mailles.",al={"coquilles pour mathiel","à quoi servent les coquilles","laque pour armure"}},{q="Qui est Furen Barbe-longue et quel est son rôle ?",a="Furen Barbe-longue est un confrère de Mathiel dans le travail du fer, installé dans le Quartier des Nains de Hurlevent. Ses expériences avec des réactifs inhabituels et des méthodes de durcissement ont inspiré Mathiel à essayer une laque à base de coquilles de wyverne.",al={"lien avec furen","coquilles de furen barbe-longue"}}},fx={f589915a={q="Qu'est-ce qu'une Coquille brûlée par le soleil ?",a="Une Coquille brûlée par le soleil est la coquille d'œuf durable et abandonnée d'une wyverne de Haut-perchoir. Trouvées cuites sous le soleil intense de Mille pointes, sous les nids élevés des créatures, ces coquilles résistantes possèdent une force naturelle remarquable qui les rend prisées par les armuriers qualifiés.",al={"qu'est-ce qu'une coquille brûlée par le soleil","objet coquille brûlée par le soleil","coquille d'œuf brûlée par le soleil"}}},fp="17,131,15.237.0,21.234.0,35.126.0,40.102.0,41.153.0,46.211.0"}
P.entries["item:super-reaper-6000-blueprints"] = {n="Plan du Super-Découpeur 6000",s="À la Combe des Cisailles, des rivaux gobelins convoitent le Plan du Super-Découpeur 6000 de KapitalRisk. Il montre comment construire la machine à couper le bois déployée dans les Serres-Rocheuses, sous la supervision de l’ingénieur gnome Gerenzo Wrenchwhistle.",h="À la Combe des Cisailles, des rivaux gobelins convoitent le Plan du Super-Découpeur 6000 de KapitalRisk.",kw={"plans","gerenzo","krachevalve","les serres-rocheuses","super reaper 6000","kapitalrisk","combe des cisailles","ziz fizziks"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous pouvez constater que les schémas gnomes précis de Gerenzo laissent les bricoleurs ordinaires perplexes, tandis que les hommes de main gobelins de la compagnie mettent les machines au travail.",["race:Gnome"]="En tant que gnome, vous pouvez apprécier l’ingéniosité de Gerenzo Wrenchwhistle dans ces plans. Même KapitalRisk s’en remet à un ingénieur gnome pour concevoir ses machines lourdes complexes."},sec={{t="Espionnage industriel à la Combe des Cisailles",b="Les opérateurs de KapitalRisk transportent le Plan du Super-Découpeur 6000 à travers la Combe des Cisailles. Les plans montrent comment construire les imposantes récolteuses de bois mécanisées qui permettent à la compagnie de pratiquer la coupe à blanc. Les ingénieurs gobelins en veulent à Gerenzo, un gnome, d’avoir été chargé de la conception. Après que la compagnie a évincé l’ingénieur gobelin Ziz Fizziks, Krachevalve l’a engagé pour dérober les plans. Pourtant, les notes denses et excentriques de Gerenzo sont presque aussi difficiles à déchiffrer que les plans à saisir par la force."}},faq={{q="Qu’est-ce que le Super Reaper 6000 ?",a="Le Super Reaper 6000 est une gigantesque machine mécanisée à couper le bois, construite pour les opérations de coupe à blanc de KapitalRisk dans les Serres-Rocheuses.",al={"qu’est-ce que le super reaper","machine super reaper"}},{q="Qui a conçu le Super Reaper 6000 ?",a="Gerenzo Wrenchwhistle, un ingénieur gnome, a conçu les plans sous la supervision de KapitalRisk après avoir été recruté pour diriger ses travaux mécaniques à la Combe des Cisailles. Sa nomination a irrité les mécaniciens gobelins locaux.",al={"qui a créé les plans","qui a conçu le super reaper"}},{q="Pourquoi Ziz Fizziks veut-il ces plans ?",a="Après que KapitalRisk a évincé Ziz Fizziks, Krachevalve l’a engagé pour dérober les plans. Ziz veut prouver sa valeur et son génie mécanique à son nouveau patron.",al={"pourquoi ziz veut-il les plans","qui veut les plans"}},{q="Qui détient les plans à la Combe des Cisailles ?",a="Les opérateurs de KapitalRisk transportent les schémas originaux et supervisent les machines ainsi que le déboisement dans toute la Combe des Cisailles.",al={"où trouver les plans","qui donne les plans"}}},fp="28,235,38.481.0,30.131.0,35.214.0,43.156.0,43.120.0"}
P.entries["item:super-snapper-fx"] = {n="Le Preneur d'images FX",s="Le Preneur d'images FX est l'appareil photo de Curgle, prêté pour Daryn Lightwind à Rut'theran. Daryn veut une photo de Gammerita, une créature des Hinterlands.",h="Le Preneur d'images FX est l'appareil photo de Curgle, prêté pour Daryn Lightwind à Rut'theran.",kw={"appareil photo","cargle","daryn lightwind","gammerita","cliché","preneur d'images","le preneur d'images fx"},sec={{t="Une nouvelle invention",b="Daryn Lightwind vous envoie chez Curgle pour récupérer sa nouvelle invention, le Preneur d'images FX. Elle vous demande de prendre une photo de Gammerita, la créature des Hinterlands, et attend que vous rapportiez la photo à Rut'theran. Curgle vous dit de viser votre sujet et d'appuyer sur le bouton."}},faq={{q="Qu'est-ce que le Preneur d'images FX ?",a="Le Preneur d'images FX est un appareil photo fabriqué par Curgle. Curgle vous le prête pour prendre une photo de Gammerita pour Daryn Lightwind.",al={"preneur d'images","appareil photo"}},{q="Qui veut une photo de Gammerita ?",a="Daryn Lightwind, à Rut'theran, vous demande de rapporter un cliché de Gammerita, dans les Hinterlands.",al={"qui a besoin de la photo","photo de daryn"}},{q="Qui a fabriqué le Preneur d'images FX ?",a="Curgle a fabriqué le Preneur d'images FX pour Daryn Lightwind.",al={"qui a fabriqué le preneur d'images","invention de curgle"}},{q="À quoi sert le Preneur d'images FX ?",a="Visez ce que vous voulez photographier avec le Preneur d'images FX, puis appuyez sur son bouton.",al={"comment fonctionne le preneur d'images","bouton de l'appareil photo"}}},fp="16,164,15.275.0,29.123.0,33.106.0,30.54.0,34.77.0"}
P.entries["item:super-sticky-tar"] = {n="Super Sticky Tar",s="Dans le nord du Cratère d’Un’Goro, le goudron des bêtes près des fosses adhère avec une force inhabituelle. Tran'rek, à Gadgetzan, veut des échantillons pour une idée de colle lucrative.",h="Dans le nord du Cratère d’Un’Goro, le goudron des bêtes près des fosses adhère avec une force inhabituelle.",kw={"chlorophylle","gadgetzan","colle","super collant","super sticky tar","goudron","bêtes de goudron","tran'rek","cratère d’un’goro"},sec={{t="Du goudron des fosses",b="Tran'rek vous demande de recueillir du goudron auprès des bêtes près des fosses du nord du Cratère d’Un’Goro. Leur peau contient de la chlorophylle, qui, selon lui, rend ce goudron bien plus collant que le goudron ordinaire. Il espère en faire une colle utile."}},faq={{q="D’où vient Super Sticky Tar ?",a="Vous récoltez Super Sticky Tar auprès des bêtes de goudron près des fosses du nord du Cratère d’Un’Goro.",al={"origine du goudron","origine de super sticky tar"}},{q="Qui veut le goudron ?",a="Tran'rek, à Gadgetzan, veut des échantillons de Super Sticky Tar pour son idée de colle.",al={"qui veut du goudron","goudron de tran'rek"}},{q="Pourquoi ce goudron est-il si collant ?",a="Selon Tran'rek, la peau des bêtes, riche en chlorophylle, se mélange au goudron et le rend particulièrement collant.",al={"pourquoi si collant","raison du goudron collant"}},{q="Que compte faire Tran'rek avec ce goudron ?",a="Tran'rek espère fabriquer une colle lucrative avec le goudron et la chlorophylle présente dans la peau des bêtes.",al={"projet de tran'rek","à quoi sert la colle"}}},fp="16,152,17.228.0,38.90.0,18.74.0,26.97.0,38.94.0"}
P.entries["item:supplies-for-sven"] = {n="Fournitures pour Sven",s="Dans le nord-ouest du Bois de la Pénombre, le camp de Sven Yorgen dépend des provisions de Sombre-Comté. La famille Carevin ravitaille sa petite troupe, qui monte la garde contre les ombres.",h="Dans le nord-ouest du Bois de la Pénombre, le camp de Sven Yorgen dépend des provisions de Sombre-Comté.",kw={"camp","carevin","sombre-comté","bois de la pénombre","provisions","fournitures pour sven","sven yorgen"},ang={["class:Paladin"]="En tant que paladin, vous pouvez voir dans le défi de Sven face aux ténèbres du Bois de la Pénombre l’œuvre de la Lumière. Ces provisions sont destinées à un frère de foi.",["faction:Alliance"]="Les Veilleurs étant débordés par la défense de Sombre-Comté, les voyageurs de l’Alliance transportent souvent des provisions vers des avant-postes isolés comme le camp de Sven."},sec={{t="Une bouée de sauvetage pour le camp",b="Sven Yorgen et ses quelques compagnons campent dans les étendues sauvages du nord-ouest, loin de Sombre-Comté. Ils sont trop peu nombreux pour quitter leur poste et se rendre en ville. La famille Carevin leur envoie donc nourriture, bandages et autres produits de première nécessité pour les aider à tenir leurs positions."}},faq={{q="Qui a envoyé ces provisions ?",a="La famille Carevin de Sombre-Comté envoie ces provisions. Elle organise le ravitaillement de Sven Yorgen et de son camp dans les étendues sauvages.",al={"qui a envoyé les provisions pour sven","qui a préparé les provisions de sven","provisions de la famille carevin"}},{q="Pourquoi Sven ne peut-il pas aller chercher ses provisions lui-même ?",a="La troupe de Sven est trop peu nombreuse pour quitter le camp. Ses compagnons survivants le défendent contre les bêtes et les morts-vivants dans le nord-ouest du Bois de la Pénombre. Aucun ne peut être épargné pour emprunter la route dangereuse vers Sombre-Comté.",al={"pourquoi sven ne va-t-il pas chercher à manger","pourquoi livrer des provisions à sven","pourquoi faut-il des provisions"}},{q="Où se trouve le camp de Sven ?",a="Le camp de Sven se trouve à la lisière nord-ouest du Bois de la Pénombre, dans les collines au-delà de la zone directement protégée par les Veilleurs.",al={"où se trouve sven yorgen","emplacement du camp de sven","trouver sven dans le bois de la pénombre"}},{q="Qui est Sven Yorgen ?",a="Sven Yorgen est un homme des frontières et un fervent croyant en la Lumière, qui cultivait autrefois une ferme dans le Bois de la Pénombre. Après la tragédie qui frappa sa ferme, il établit un camp armé à la frontière pour riposter aux forces maléfiques qui ravagent la région.",al={"qui est sven","histoire de sven yorgen"}}},fx={["0c0166a3"]={q="Qu'est-ce que les Fournitures pour Sven ?",a="Ces fournitures sont un colis de soutien rassemblé pour aider Sven Yorgen et son petit groupe de partisans qui tiennent bon dans le Bois de la Pénombre. La famille The Carevin Family prépare régulièrement une telle aide afin que ces croisés dévoués puissent continuer à accomplir l'œuvre de la Lumière contre les horreurs qui hantent la forêt sombre sans abandonner leur vigile.",al={"que sont les fournitures pour sven","quelles sont les fournitures de sven","objet fournitures pour sven"}}},fp="17,177,23.274.0,24.125.0,38.195.0,29.114.0,19.227.0"}
P.entries["item:supply-crate-blasted-lands"] = {n="Caisse de fournitures",s="La Caisse de fournitures est du matériel d'excavation abandonné que Sigrun Ironhew recherche dans les Terres Ingrates. Son contenu pourrait aider sa compagnie affamée.",h="La Caisse de fournitures est du matériel d'excavation abandonné que Sigrun Ironhew recherche dans les Terres...",kw={"terres ingrates","camp kosh","excavation","nourriture","mirages","sigrun ironhew","caisse de fournitures","uldaman"},sec={{t="Abandonnées sur place",b="Après avoir quitté précipitamment le site d’excavation d’Uldaman, la compagnie de Sigrun Ironhew a abandonné des chariots et des caisses de fournitures. Des ogres du Camp Kosh se sont emparés de leur équipement, dont un chariot chargé d’armes. La compagnie se retrouve sans nourriture et Sigrun vous demande de récupérer une Caisse de fournitures."}},faq={{q="Qui veut la Caisse de fournitures ?",a="Sigrun Ironhew veut que vous récupériez la Caisse de fournitures pour sa compagnie dans les Terres Ingrates.",al={"qui a besoin de la caisse","caisse de sigrun"}},{q="Où la Caisse de fournitures a-t-elle été laissée ?",a="La caisse se trouvait parmi les provisions abandonnées lorsque la compagnie de Sigrun Ironhew a fui le site d’excavation d’Uldaman.",al={"emplacement de la caisse","où est la caisse"}},{q="Pourquoi Sigrun a-t-elle besoin de la caisse ?",a="La compagnie de Sigrun a perdu ses vivres après que des ogres du Camp Kosh se sont emparés de son équipement. Il vous demande de récupérer une Caisse de fournitures.",al={"pourquoi la caisse","ils ont besoin de provisions"}},{q="Qu’ont pris les ogres ?",a="Des ogres du Camp Kosh se sont emparés de l’équipement abandonné de la compagnie, dont un chariot chargé d’armes.",al={"ogres du camp kosh","qu’ont volé les ogres"}},{q="Que se passe-t-il à votre retour ?",a="Sigrun vous remercie, puis dit que la compagnie partira chercher de la nourriture ce soir.",al={"fin de la quête de la caisse","réponse de sigrun"}}},fp="12,131,11.279.0,27.86.0,32.106.0,31.129.0,24.97.0,29.77.1"}
P.entries["item:surena-s-choker"] = {n="Foulard de Surena",s="À Hurlevent, Gakin le Tisse-noir cherche l’écharpe de pierre de sang qu’il a donnée à son ancienne apprentie, Surena Caledon. Elle s’est enfuie avec Erlan Drudgemoor pour rejoindre la Confrérie défias, et Gakin envoie désormais des acolytes en devenir la reprendre par la force.",h="À Hurlevent, Gakin le Tisse-noir cherche l’écharpe de pierre de sang qu’il a donnée à son ancienne apprentie...",kw={"echarpe de pierre de sang","champ de potirons des brackwell","erlan drudgemoor","gakin le tisse-noir","slaughtered lamb","surena caledon","foulard de surena"},ang={["class:Warlock"]="Pour un démoniste Humain ou Gnome, récupérer l’écharpe de Surena Caledon est une première épreuve. Cela montre que les sentiments n’ont pas leur place dans la quête du pouvoir démoniaque."},sec={{t="L’investissement perdu d’un maître",b="Sous The Slaughtered Lamb, à Hurlevent, Gakin le Tisse-noir a jadis formé Surena Caledon aux arts sombres. Il a vu en son charme juvénile et son talent magique de belles promesses, et lui a donné une précieuse écharpe de pierre de sang pour l’aider dans ses études. Mais Surena a abandonné sa formation et s’est enfuie avec Erlan Drudgemoor, un voleur affilié à la Confrérie défias.\n\nGakin ne laissera pas une traîtresse garder un artefact aussi puissant. Il envoie désormais des initiés en quête de maîtrise du Vide la retrouver au Champ de potirons des Brackwell et reprendre l’écharpe par la force. Leur acte prouvera où va leur loyauté."}},faq={{q="Pourquoi Gakin le Tisse-noir veut-il récupérer le Foulard de Surena ?",a="Gakin a donné l’écharpe de pierre de sang à Surena quand elle était son apprentie. Elle a abandonné ses études et s’est enfuie avec un membre de la Confrérie défias. Gakin ne laissera pas une traîtresse garder un précieux artefact de magie noire.",al={"pourquoi gakin veut l’écharpe","collier gakin surena","pourquoi reprendre l’écharpe"}},{q="Qui est Surena Caledon ?",a="Surena Caledon est une ancienne apprentie démoniste qui a montré un talent naturel auprès de Gakin le Tisse-noir, à Hurlevent. Elle s’est détournée de son maître et s’est enfuie avec Erlan Drudgemoor, se cachant parmi les hors-la-loi défias dans la Forêt d’Elwynn.",al={"qui est surena","histoire de surena caledon","qui a l’écharpe"}},{q="Où trouver l’écharpe ?",a="Surena Caledon porte l’écharpe au Champ de potirons des Brackwell, dans l’est de la Forêt d’Elwynn, où elle s’est retranchée parmi les bandits défias.",al={"où se trouve surena","emplacement de l’écharpe","où se trouve surena caledon"}},{q="À quoi sert l’écharpe une fois récupérée ?",a="Reprendre l’écharpe prouve la cruauté et la loyauté d’un acolyte envers Gakin le Tisse-noir. Il n’a pas dit ce qu’il compte en faire. Il déplore le talent gâché de Surena et espère que son investissement dans un nouvel élève donnera de meilleurs résultats.",al={"que fait gakin de l’écharpe","utilité de l’écharpe","pourquoi les démonistes ont besoin de l’écharpe"}}},fx={["195efbf9"]={q="Qu'est-ce que le Foulard de Surena ?",a="C'est un collier orné en pierre de sang appartenant à l'origine à Gakin le Tisse-noir, le maître démoniste résidant dans The Slaughtered Lamb à Hurlevent. Gakin a offert ce précieux bijou à son ancienne apprentie, Surena Caledon, lorsqu'il était épris de sa jeunesse et de sa beauté, avant qu'elle ne le trahisse.",al={"qu'est-ce que le foulard de surena","echarpe de pierre de sang"}},["7b9593ae"]={q="D'où vient le Foulard de Surena et qui l'a fabriqué ?",a="L'artisan précis du collier est inconnu, mais il était à l'origine en possession de Gakin le Tisse-noir. Gakin a offert le collier en pierre de sang à sa jeune élève Surena Caledon pendant sa formation auprès de lui, bien avant qu'elle ne s'enfuie avec un voleur défias vers le champ de citrouilles d'Elwynn.",al={"qui a créé le foulard de surena","origine du foulard de surena","d'où vient le foulard"}}},fp="15,236,26.570.0,56.212.0,22.220.0,30.138.0,50.235.0"}
P.entries["item:swoop-gizzard"] = {n="Gésier de Rapace",s="Dans Mulgore, les rapaces chassent dans les plaines et sur les mesas, et les remèdes taurens utilisent leur gésier contre les toxines mortelles.",h="Dans Mulgore, les rapaces chassent dans les plaines et sur les mesas, et les remèdes taurens utilisent leur...",kw={"sabot-de-sang","gésier","maur mande-pluie","mazzranache","mulgore","remède","rapace"},ang={["race:Tauren"]="Pour un chasseur ou un chaman tauren, rassembler ces parties honore la tradition qui consiste à utiliser la faune de Mulgore pour nourrir et soigner la tribu."},sec={{t="Un ingrédient populaire rare",b="Les rapaces chassent dans les plaines et sur les mesas de Mulgore. Leur regard perçant les aide à trouver leur nourriture. Les Tauren utilisent leurs plumes et leur viande au quotidien. Les herboristes et les guérisseurs prisent leurs organes internes, surtout le gésier. Associé à des os de puma et à des cœurs de loup, il aide à contrer les morsures venimeuses et les infections purulentes."},{t="Un remède contre la morsure de Mazzranache",b="À Sabot-de-Sang, Maur Mande-pluie soigne la blessure laissée par Mazzranache sur son épaule. Le venin de ce légendaire trotteur des plaines plonge Maur dans le délire tandis que le poison se répand dans son corps. Pour préparer un cataplasme qui expulsera le venin mortel, Maur a besoin d’un Gésier de Rapace, d’un Cœur de loup des prairies, d’un Fémur de puma des basses plaines et d’une Écaille de trotteur des plaines."}},faq={{q="À quoi sert un Gésier de Rapace ?",a="À Sabot-de-Sang, Maur Mande-pluie a besoin d’un Gésier de Rapace pour préparer un remède. Mélangé à trois autres parties animales, il forme un remède contre l’infection venimeuse laissée par Mazzranache, le féroce trotteur des plaines.",al={"utilité du gésier de rapace","pourquoi avoir besoin d’un gésier de rapace","rôle de l’organe du rapace"}},{q="D’où viennent les gésiers de rapace ?",a="Les gésiers de rapace proviennent des rapaces qui planent au-dessus des plaines de Mulgore. Il peut s’agir de rapaces ordinaires, de rapaces décharnés ou de rapaces à serres.",al={"où trouver un gésier de rapace","qu’est-ce qui donne un gésier de rapace","swoop hunting"}},{q="Pourquoi Maur Mande-pluie a-t-il besoin de cette partie précise ?",a="Mazzranache a mordu Maur, et le venin de ce trotteur des plaines particulièrement féroce provoque de fortes fièvres et des cauchemars. La médecine populaire taurène utilise des parties animales puissantes, dont un gésier, pour contrer les toxines dans les veines de Maur.",al={"remède de maur","pourquoi un gésier","remède contre mazzranache"}},{q="Le gésier sert-il à autre chose qu’au remède de Maur ?",a="Non. En dehors du remède populaire spécialisé de Maur Mande-pluie, à Sabot-de-Sang, les gésiers de rapace n’ont pas d’usage courant en cuisine, en alchimie ou en artisanat.",al={"autres usages du gésier de rapace","cuisiner un gésier de rapace","alchimie et gésier de rapace"}}},fx={["8f6be1e3"]={q="Qu'est-ce qu'un Gésier de Rapace ?",a="Un Gésier de Rapace est un organe interne récolté sur les oiseaux prédateurs connus sous le nom de rapaces qui planent au-dessus des plaines de Mulgore. Comme beaucoup d'organes digestifs aviaires, il aide à digérer les proies coriaces. Dans la médecine traditionnelle tauren, ces parties d'animaux puissantes et spécialisées sont appréciées pour leurs qualités naturelles brutes et utilisées comme ingrédients dans des remèdes à base de plantes et des concoctions réparatrices.",al={"qu'est-ce qu'un gésier de rapace","objet gésier de rapace"}}},fp="13,123,22.322.0,31.338.0,33.200.0,34.128.0,49.218.0,56.147.0"}
P.entries["item:symbol-of-ragnaros"] = {n="Symbole de Ragnaros",s="Le Symbole de Ragnaros est une relique du Marteau du crépuscule trouvée dans la Gorge des Vents brûlants. Velarok convoite sa magie impie pour façonner une gaine pour la Torche de vindicte.",h="Le Symbole de Ragnaros est une relique du Marteau du crépuscule trouvée dans la Gorge des Vents brûlants.",kw={"gaine de la flamme","magie impie","ragnaros","gorge des vents brûlants","symbole de ragnaros","torche de vindicte","marteau du crépuscule","velarok"},sec={{t="Magie impie",b="Velarok Windblade a besoin d'un Symbole de Ragnaros pour la Torche de vindicte. Il pense que le campement du Marteau du crépuscule, dans les montagnes au nord-ouest d'ici, abrite des symboles et des idoles assez puissants pour former la gaine de la torche. La magie du symbole lui convient."}},faq={{q="Qu'est-ce que le Symbole de Ragnaros ?",a="C'est un symbole porté par le Marteau du crépuscule, dont la magie peut aider à façonner une gaine pour la Torche de vindicte.",al={"symbole de ragnaros"}},{q="Qui veut le symbole ?",a="Velarok Windblade a besoin du Symbole de Ragnaros pour façonner la gaine de la Torche de vindicte.",al={"qui le veut","ce dont velarok a besoin"}},{q="Pourquoi Velarok en a-t-il besoin ?",a="Velarok espère en extraire la magie impie et l'utiliser pour façonner une gaine pour la Torche de vindicte.",al={"pourquoi avoir besoin du symbole","gaine de la torche"}},{q="Où pouvez-vous en trouver un ?",a="Selon les rumeurs, le campement du Marteau du crépuscule, dans les montagnes au nord-ouest d'ici, abrite des symboles et des idoles.",al={"où trouver le symbole","trouver le symbole de ragnaros"}}},fp="18,151,10.262.0,31.115.0,21.89.0,25.97.0,21.105.0"}
P.entries["item:tablet-of-verga"] = {n="Tablette de Verga",s="Au Rocher du Crâne, la Tablette de Verga reste aux mains de la Lame ardente, tandis que les démonistes d’Orgrimmar convoitent ses runes démoniaques.",h="Au Rocher du Crâne, la Tablette de Verga reste aux mains de la Lame ardente, tandis que les démonistes...",kw={"lame ardente","la faille de l'ombre","durotar","gan'rul oeil-sanglant","rocher du crâne","tablette de verga","marcheur du vide"},ang={["class:Warlock"]="En tant que démoniste en formation à Orgrimmar, récupérer la tablette marque une étape vers la preuve de votre valeur auprès de la Horde et l’apprentissage de l’asservissement d’un marcheur du Vide protecteur.",["faction:Horde"]="En tant que membre de la Horde, vous affrontez la Lame ardente près des portes d’Orgrimmar. Reprendre les reliques volées au culte porte atteinte à son influence sur la jeune nation de Thrall."},sec={{t="Une relique volée",b="La Tablette de Verga porte des runes rituelles permettant d’invoquer des créatures du Néant et de les soumettre à la volonté d’un maître. La Lame ardente a volé la pierre et l’a cachée dans un coffre, à l’intérieur du Rocher du Crâne, juste à l’est d’Orgrimmar.\n\nLes démonistes de la Faille de l’Ombre convoitent la tablette pour étudier ses inscriptions et apprendre à invoquer un marcheur du Vide. La récupérer empêche aussi le culte d’obtenir ce même avantage."}},faq={{q="Où se trouve la Tablette de Verga ?",a="La Tablette de Verga se trouve dans une Burning Blade Stash, à l’intérieur du Rocher du Crâne, un réseau de cavernes grouillant de cultistes, juste à l’est d’Orgrimmar, en Durotar.",al={"emplacement de la tablette de verga","où trouver la tablette de verga","où se trouve la tablette de verga"}},{q="Qui veut récupérer la Tablette de Verga ?",a="Gan'rul Oeil-sanglant, un maître démoniste de la Faille de l’Ombre, sous Orgrimmar, envoie des novices récupérer la tablette afin de leur apprendre à invoquer des serviteurs plus puissants.",al={"qui a besoin de la tablette de verga","à qui apporter la tablette de verga","tablette de gan'rul"}},{q="Quel pouvoir renferme la tablette ?",a="La pierre porte d’anciennes runes nécessaires pour invoquer et asservir un marcheur du Vide, une créature venue du Twisting Nether.",al={"à quoi sert la tablette","histoire de la tablette de verga","runes de la tablette de verga"}},{q="Pourquoi la Lame ardente l’a-t-elle volée ?",a="Le culte de la Lame ardente cherche à déstabiliser la Horde et à accroître son pouvoir démoniaque. En volant la tablette, le culte prive les pratiquants d’Orgrimmar de connaissances rituelles essentielles tout en les gardant pour lui-même.",al={"pourquoi la lame ardente a la tablette","lame ardente verga"}}},fx={["5fa1e5b5"]={q="Qu'est-ce que la Tablette de Verga ?",a="La Tablette de Verga est une relique inscrite avec des connaissances arcaniques de démoniste, spécifiquement les runes et rituels nécessaires pour invoquer et lier un marcheur du Vide. Volée par des cultistes de la Lame ardente, elle contient des secrets sombres prisés par les démonistes cherchant à accroître leur maîtrise du Néant distordu et à invoquer des serviteurs démoniaques pour obéir à leurs ordres.",al={"qu'est-ce que la tablette de verga","tablette de verga"}}},fp="15,117,14.387.0,37.143.0,40.162.0,35.112.0,35.197.0"}
P.entries["item:tablet-shard"] = {n="Tablet Shard",s="Le Tablet Shard provient d'une ancienne tablette troll sous le Récif infâme. Kin'weelay le cherche pour un lieu sacré à Orgrimmar, où il honorera le héros sombrelance Gri'lek.",h="Le Tablet Shard provient d'une ancienne tablette troll sous le Récif infâme.",kw={"sombrelance","gri'lek","gri'lek the wanderer","kin'weelay","la côte sauvage","fragment de tablette","tablette troll","le récif infâme"},ang={["faction:Horde"]="La tribu Sombrelance cherche le Tablet Shard pour un lieu sacré dans son nouveau foyer à Orgrimmar.",["race:Troll"]="En tant qu'objet troll, le Tablet Shard porte le récit sacré de Gri'lek, un héros des légendes trolls, et doit lui rendre hommage parmi les Sombrelance."},sec={{t="Un fragment de Gri'lek",b="Sous les eaux de la Côte sauvage, le Tablet Shard est prélevé sur une tablette qui raconte l'histoire de Gri'lek the Wanderer. Kin'weelay veut un fragment pour le nouveau foyer de la tribu Sombrelance à Orgrimmar. Là, il rappellera à la tribu la puissance et l'honneur de Gri'lek."}},faq={{q="Qu'est-ce que le Tablet Shard ?",a="Le Tablet Shard est un fragment d'une ancienne tablette troll sous le Récif infâme. Il raconte l'histoire de Gri'lek the Wanderer.",al={"fragment de tablette","quel fragment","morceau de tablette troll"}},{q="Qui veut le Tablet Shard ?",a="Kin'weelay, au Campement Grom'gol, veut le Tablet Shard pour un lieu sacré à Orgrimmar.",al={"qui veut le fragment","fragment de kin'weelay","à qui le remettre"}},{q="Pourquoi la tribu Sombrelance le veut-elle ?",a="Le fragment honorera Gri'lek the Wanderer et rappellera à la tribu Sombrelance sa puissance et son honneur.",al={"pourquoi le fragment","tablette sombrelance","à quoi sert-il"}},{q="Où se trouve la tablette ?",a="La tablette repose sous les eaux de la Côte sauvage, dans les ruines connues sous le nom de Récif infâme.",al={"emplacement de la tablette","d'où vient le fragment","tablette du récif infâme"}}},fp="12,174,21.260.0,25.123.0,27.88.0,37.96.0,20.92.0"}
P.entries["item:tainted-heart"] = {n="Coeur corrompu",s="À Teldrassil, Denalan veille sur un cœur encore corrompu. La mousse fétide a disparu, mais la souillure demeure. Il cherche à le purifier avec une terre riche.",h="À Teldrassil, Denalan veille sur un cœur encore corrompu.",kw={"purification","corruption","denalan","lac al'ameth","jardinière","coeur corrompu","teldrassil"},ang={["class:Druid"]="En tant que druide Cenarion, purifier le Coeur corrompu vous permet de mieux comprendre la corruption insidieuse qui menace la santé du jeune Arbre-monde.",["profession:Herbalism"]="En tant qu’herboriste, vous pouvez apprécier le savoir-faire de Denalan, qui mélange des terres enrichies pour extraire la pourriture contre nature des plantes vivantes."},sec={{t="Un noyau corrompu",b="Un fléau menace l’équilibre naturel de Teldrassil et déforme ses plantes et ses bêtes. Après avoir retiré la mousse fétide d’une pousse flétrie, Denalan remet aux aventuriers le Coeur corrompu qu’elle renferme. Les ténèbres imprègnent encore ses tissus. Il espère qu’une terre spécialement préparée et riche en nutriments pourra contrer la souillure et restaurer ce qui a été corrompu."},{t="Le remède de Denalan",b="Le Coeur corrompu manifeste une vitalité étrange dans la jardinière enchantée de Denalan. Il s’enfouit dans la terre riche et en absorbe les nutriments curatifs. La terre consume la corruption. Le cœur en ressort vivant, vibrant d’une énergie saine et prêt à défendre ceux qui l’ont guéri."}},faq={{q="Qu’est-ce que le Coeur corrompu ?",a="Le Coeur corrompu est le noyau interne d’une plante corrompue de Teldrassil. Le botaniste Denalan a retiré sa mousse fétide, mais le cœur reste corrompu jusqu’à sa purification.",al={"qu’est-ce que le cœur corrompu","objet cœur corrompu"}},{q="Qui purifie le Coeur corrompu ?",a="Denalan demande aux aventuriers de planter le Coeur corrompu dans sa jardinière spécialement préparée, au lac Al’Ameth. Sa terre nutritive purifie le cœur et élimine sa corruption contre nature.",al={"qui le purifie","comment purifier le cœur corrompu"}},{q="Que se passe-t-il après sa plantation ?",a="Le cœur s’enfouit dans la terre de la jardinière. Quelques instants plus tard, il ressort purifié et vibrant de vitalité, prêt à se lier à la personne qui l’a restauré.",al={"que devient le cœur","résultat de la plantation du cœur"}},{q="Pourquoi le cœur est-il corrompu au départ ?",a="Un étrange fléau se répand dans l’Arbre-monde Teldrassil, corrompant la flore indigène, les timberlings et la faune sur toute sa ramure.",al={"pourquoi est-il corrompu","cœur corrompu de teldrassil"}}},fx={ae8829e0={q="Pourquoi Denalan veut-il que vous plantiez le Coeur corrompu ?",a="Denalan a réussi à enlever la mousse infecte qui s'accrochait au cœur, mais son noyau intérieur reste profondément corrompu. Il espère que le sol riche et nutritif de son bac à plantes spécialement préparé guérira l'affliction, extrayant la corruption et redonnant vitalité à la graine vivante.",al={"pourquoi planter le cœur corrompu","utilité du cœur corrompu","pourquoi denalan veut-il le cœur corrompu"}}},fp="13,150,16.325.0,16.267.1,26.165.0,31.186.0,33.144.1,46.132.0"}
P.entries["item:tainted-keg"] = {n="Baril infecté",s="À Moulin-de-Tarren, le Baril infecté contient un breuvage mortel préparé par l’Apothicaire Lydon. Une bière naine volée transporte le poison, destiné aux fermiers humains emprisonnés pour tester les travaux de la Société royale des apothicaires.",h="À Moulin-de-Tarren, le Baril infecté contient un breuvage mortel préparé par l’Apothicaire Lydon.",kw={"apothicaire lydon","fermiers capturés","dun garok","elixir of agony","shindigger stout","baril infecté","moulin-de-tarren"},ang={["race:Human"]="Une bière empoisonnée servant à tuer des travailleurs ruraux capturés témoigne des tactiques impitoyables auxquelles les survivants sont confrontés dans tout Hautebrande.",["race:Undead"]="Pour la Société royale des apothicaires, la bière contaminée marque un progrès vers des armes biologiques capables d’éradiquer l’humanité."},sec={{t="Un brassin mortel",b="Les fusiliers nains de Dun Garok ont perdu un baril de Shindigger Stout, dérobé par des voleurs. L’Apothicaire Lydon l’a mélangée à son Elixir of Agony fraîchement raffiné. Les Réprouvés ont choisi une boisson ordinaire pour transporter le poison, espérant que personne ne le soupçonnerait. Une bière familière est devenue une condamnation à mort rapide."},{t="Tester sur les condamnés",b="Plusieurs fermiers humains étaient détenus à l’étage de l’auberge de Moulin-de-Tarren. La Grande exécutrice Darthalia soupçonnait un stratège militaire de Hurlevent de se cacher parmi eux. Lorsqu’on apprit que le stratège était mort ailleurs, les fermiers ne furent plus d’aucune utilité. Darthalia les livra à Lydon, qui plaça le baril empoisonné sur le tapis de leur chambre pour une cruelle célébration. Assoiffés et désespérés, les prisonniers burent. L’élixir les tua rapidement, prouvant son pouvoir meurtrier."}},faq={{q="Que contient le Baril infecté ?",a="Le baril contient du Shindigger Stout, volé à Dun Garok et mélangé à l’Elixir of Agony. L’Apothicaire Lydon a préparé ce poison expérimental à Moulin-de-Tarren.",al={"contenu du baril infecté","quel poison contient le baril","que contient le baril"}},{q="D’où venait la bière à l’origine ?",a="La bière provenait des montagnards et des fusiliers nains de Dun Garok, une forteresse lourdement défendue au sud-est des Contreforts de Hautebrande.",al={"qui a préparé la bière","où la bière a été volée","origine du shindigger stout"}},{q="Qui boit dans le baril ?",a="Des fermiers humains détenus à l’étage de l’auberge de Moulin-de-Tarren boivent dans le baril. Le breuvage empoisonné les tue presque aussitôt.",al={"qui en boit","victimes du baril infecté","fermiers capturés"}},{q="Pourquoi les fermiers étaient-ils prisonniers ?",a="La Grande exécutrice Darthalia a emprisonné les fermiers, car elle soupçonnait un stratège militaire de Hurlevent de se cacher parmi eux. Après avoir appris que le stratège était mort ailleurs, elle les jugea inutiles et les remit aux apothicaires.",al={"pourquoi les fermiers sont prisonniers","pourquoi darthalia a capturé des fermiers","pourquoi des fermiers sont à moulin-de-tarren"}}},fx={fd5e0197={q="Qu'est-ce que le Baril infecté ?",a="Le Baril infecté est un récipient de bière naine volée, la Shindigger Stout, qui a été mélangée à une concoction mortelle brassée par les Réprouvés. L'Apothicaire Lydon a créé ce lot létal de breuvage corrompu pour servir d'essai pratique à ses recherches alchimiques en cours.",al={"qu'est-ce que le baril infecté","objet baril infecté","qu'est-ce que ce baril"}},["5c778a45"]={q="Pourquoi l'Apothicaire Lydon veut-il que le Baril infecté soit utilisé ?",a="L'Apothicaire Lydon veut que le baril soit livré pour tester l'efficacité de son Elixir of Agony tout juste terminé. Avec les fermiers humains capturés mis à sa disposition par la Grande exécutrice Darthalia, leur offrir la bière empoisonnée fournit à la Société royale des apothicaires un moyen pratique d'observer les effets fatals de la toxine de première main.",al={"pourquoi utiliser le baril infecté","pourquoi lydon veut-il le baril infecté","utilité du baril infecté"}}},fp="11,201,16.276.0,24.458.1,31.151.0,39.136.0,24.115.1,41.243.0"}
P.entries["item:tainted-letter"] = {n="Lettre contaminée",s="Près de l'Abbaye de Comté-du-Nord, Drusilla La Salle convoque en secret les aspirants démonistes humains.",h="Près de l'Abbaye de Comté-du-Nord, Drusilla La Salle convoque en secret les aspirants démonistes humains.",kw={"drusilla la salle","forêt d’elwynn","abbaye de comté-du-nord","lettre contaminée","twisting nether","démoniste"},ang={["class:Warlock"]="En tant que démoniste, vous recevez la Lettre contaminée, qui vous initie aux arts occultes dans le royaume de Hurlevent. Le pouvoir sur le Néant exige une vigilance et une discrétion constantes.",["race:Human"]="En tant qu'humain, vous vivez dans une société qui défend largement la Lumière sacrée. Les adeptes de la magie noire s'entraînent en secret, en marge de lieux comme l'Abbaye de Comté-du-Nord."},sec={{t="Une convocation secrète",b="Les initiés de retour des camps de kobolds voisins portent la convocation de Drusilla vers l'Abbaye de Comté-du-Nord. Prêtres, paladins et soldats s'entraînent ouvertement sur ses pelouses, mais les adeptes de la magie gangrenée doivent rester discrets. Les gardes de la ville et les clercs pourraient se méfier si les novices démonistes attirent l'attention en cherchant leur mentor près de l'abbaye."},{t="Le prix de l'ambition",b="Drusilla La Salle retrouve ses élèves en périphérie, où les sentinelles risquent moins de poser des questions. Les gens ordinaires d'Elwynn se méfient des démonistes, et la lettre amorce une leçon de discipline. Les magies arcanique et du Néant risquent de corrompre. Ceux qui communient avec les habitants du Twisting Nether doivent tempérer leur ambition par une maîtrise de soi patiente."}},faq={{q="Qui a envoyé la Lettre contaminée ?",a="Drusilla La Salle, la formatrice des démonistes près de l'Abbaye de Comté-du-Nord, a envoyé la lettre.",al={"qui a écrit la lettre contaminée","lettre de drusilla","expéditeur de la lettre contaminée"}},{q="Pourquoi la lettre est-elle considérée comme contaminée ?",a="L'insigne de Drusilla La Salle et des traces de magie gangrenée révèlent que la lettre vient d'une adepte des arts démoniaques.",al={"pourquoi est-elle contaminée","qu'est-ce qui rend la lettre contaminée","sceau contaminé"}},{q="Pourquoi les gardes du Comté-du-Nord surveillent-ils Drusilla La Salle ?",a="Les gardes et les prêtres du Comté-du-Nord se méfient de la magie gangrenée et des invocations démoniaques. Drusilla reste aux abords de l'abbaye pour échapper à leur surveillance rapprochée.",al={"drusilla et les gardes","pourquoi les gardes se méfient-ils de drusilla","démoniste caché au comté-du-nord"}},{q="Quel conseil Drusilla donne-t-elle à la lecture de la lettre ?",a="Drusilla avertit que traiter avec des entités du Twisting Nether mène à la tentation et à la corruption. Elle exhorte ses élèves à faire preuve de maîtrise de soi et de prudence sans renoncer à leur ambition.",al={"conseil de drusilla","que dit drusilla","entraînement de drusilla"}}},fx={["63258adc"]={q="Qu'est-ce que la Lettre contaminée ?",a="La Lettre contaminée est un message scellé laissé à votre intention à votre retour à l'Abbaye de Comté-du-Nord, portant l'insigne personnel indubitable de Drusilla La Salle. Adressée aux apprentis pratiquants des arts sombres, cette correspondance fait office de convocation urgente pour vous entretenir directement avec elle. Elle porte la légère empreinte de la corruption gangrenée, ce qui la distingue nettement des affaires pieuses et ordonnées de la Lumière sacrée pratiquées dans l'enceinte de l'abbaye.",al={"qu'est-ce que la lettre contaminée","identité de la lettre contaminée","à propos de la lettre contaminée"}},["3c923280"]={q="Pourquoi la Lettre contaminée vous est-elle donnée ?",a="La lettre vous est remise afin que vous puissiez établir le contact avec votre maître, Drusilla La Salle, dès que vos tâches initiales autour de Comté-du-Nord sont terminées. Drusilla opère discrètement en marge de l'abbaye, gardant un œil vigilant sur les démonistes émergents. La lettre vous ordonne de la trouver avant que d'autres affaires de l'abbaye ne vous distraient, lui permettant de vous transmettre des avertissements vitaux sur la maîtrise de soi, l'ambition et la nature corruptrice du Néant distordu.",al={"pourquoi ai-je besoin de la lettre contaminée","qui veut la lettre contaminée","pourquoi donner la lettre contaminée"}}},fp="14,130,16.336.0,21.323.0,28.78.0,37.117.0,53.145.0,55.187.0"}
P.entries["item:tainted-memorandum"] = {n="Note de service contaminée",s="Dans la Vallée des Frigères, Alamar Grimm exhorte les démonistes gnomes novices à délaisser les anciennes voies et à chercher le pouvoir dans les arts sombres.",h="Dans la Vallée des Frigères, Alamar Grimm exhorte les démonistes gnomes novices à délaisser les anciennes...",kw={"alamar grimm","courbenclume","vallée des frigères","démoniste gnome","gnomeregan","note de service contaminée"},ang={["class:Warlock"]="En tant que démoniste, vous vous entraînez auprès d’Alamar Grimm. Il présente l’invocation des ténèbres comme une voie vers le contrôle et le pouvoir.",["race:Gnome"]="En tant que gnome, vous entendez Grimm faire appel au ressentiment suscité par la perte de Gnomeregan et par la place que votre peuple occuperait, selon certains, parmi les réfugiés dépendants des nains."},sec={{t="Une convocation discrète",b="À Courbenclume, peu célèbrent les adeptes de la magie gangrenée, et beaucoup s’en méfient. Alamar Grimm remet la Note de service contaminée aux jeunes gnomes qui étudient les arts interdits. Il rejette la Sainte Lumière et les armes ordinaires. À ses yeux, la chute de Gnomeregan prouve que les anciennes méthodes et le bricolage ont échoué à protéger leur peuple.\n\nGrimm voit dans la dépendance à la charité des nains une impasse. Il exhorte les gnomes à s’emparer d’un pouvoir incontestable et à invoquer des serviteurs qui obéissent sans poser de questions. Il croit que c’est le seul moyen d’assurer leur propre avenir."}},faq={{q="Qui a écrit la Note de service contaminée ?",a="Alamar Grimm, l’instructeur démoniste gnome de Courbenclume, a écrit la Note de service contaminée.",al={"auteur note de service contaminée","qui a envoyé la note de service contaminée","note alamar grimm"}},{q="Pourquoi la note est-elle considérée comme « contaminée » ?",a="La note traite de la magie interdite des démonistes. Son titre reflète la méfiance envers les pouvoirs démoniaques et gangrenés à Dun Morogh, où les hôtes nains tiennent les adeptes à distance.",al={"pourquoi contaminée","histoire de la lettre contaminée"}},{q="Que dit Alamar Grimm au sujet de Gnomeregan ?",a="Alamar Grimm accuse la magie des arcanes traditionnelle et le bricolage imprudent d’avoir mené les gnomes au bord de l’extinction lors de la chute de Gnomeregan. Il croit que les nains considèrent les gnomes comme des citoyens de seconde classe et exhorte les démonistes à s’emparer de leur propre pouvoir absolu au lieu d’attendre l’aide de l’Alliance.",al={"alamar grimm gnomeregan","avis d’alamar grimm"}}},fx={["0c729b68"]={q="Qu'est-ce que la Note de service contaminée ?",a="La Note de service contaminée est un message discret et personnel destiné aux démonistes gnomes prometteurs qui commencent tout juste leur formation dans la Vallée des Frigères. Transmise discrètement par des alliés à la surface, cette note sert d'invitation à regarder au-delà des traditions conventionnelles de la Lumière sacrée ou du combat physique et à rechercher des pratiquants de même esprit, ouverts d'esprit, qui hébergent des arts plus sombres.",al={"qu'est-ce que la note de service contaminée","note contaminée","qu'est-ce que cette note"}},e7be2e4a={q="Pourquoi quelqu'un souhaite-t-il que vous possédiez la Note de service contaminée ?",a="La note vous est donnée pour vous recruter dans le giron des arts démoniaques. Le maître démoniste Alamar Grimm l'envoie pour identifier les lanceurs de sorts novices qui rejettent les dogmes ordinaires des Nains et des Gnomes, vous poussant à le rencontrer à Courbenclume pour maîtriser des alliés invoqués obéissants et déverrouiller la véritable source du pouvoir démoniaque.",al={"pourquoi m'a-t-on donné la note de service","pourquoi la note de service contaminée","qui veut la note de service contaminée"}}},fp="18,125,18.486.0,33.82.0,43.180.0,44.277.0"}
P.entries["item:talisman-of-corruption"] = {n="Talisman de corruption",s="À Sombrivage, Xabraxxis retourne les furbolgs Blackwood contre leurs anciens alliés grâce au Talisman de corruption. Il le garde dans sa sacoche personnelle, et sa magie plonge la tribu dans la folie gangrenée.",h="À Sombrivage, Xabraxxis retourne les furbolgs Blackwood contre leurs anciens alliés grâce au Talisman de...",kw={"auberdine","blackwood","sombrivage","furbolg","satyre","talisman de corruption","thundris windweaver","xabraxxis"},ang={["class:Druid"]="En tant que druide, vous voyez dans des objets comme le talisman une perversion de l’ordre naturel. Ils transforment des bêtes sacrées en pions sauvages des séides restants de la Légion ardente.",["race:NightElf"]="En tant que Kaldorei d’Auberdine, récupérer le talisman aide à libérer vos alliés furbolgs ancestraux de la déchéance démoniaque et à guérir la terre."},sec={{t="Un conduit de folie",b="À Auberdine, les elfes de la nuit cherchent la cause du retournement des furbolgs Blackwood contre leurs anciens alliés. Thundris Windweaver a découvert que des satyres ont provoqué la chute de la tribu. Des talismans comme celui-ci répandent une sorcellerie corruptrice dans les étendues sauvages. Ils souillent la nourriture et changent de paisibles esprits de la forêt en bêtes frénétiques. Leur magie gangrenée s’empare de l’esprit et de la volonté des tribus locales."},{t="Briser l’emprise",b="Pour attirer Xabraxxis, vous purifiez des échantillons de nourriture des furbolgs avec de l’eau bénite de puits de lune. Cette purification met le surveillant en rage. Quand Xabraxxis est tué, sa sacoche démoniaque livre le talisman. Vous l’apportez à Thundris Windweaver, à Auberdine, où les Kaldorei peuvent neutraliser ses viles émanations et étudier comment annuler l’affliction démoniaque qui frappe la forêt."}},faq={{q="Qu’est-ce que le Talisman de corruption ?",a="Xabraxxis utilise le Talisman de corruption pour canaliser une magie vile à travers la nourriture et l’esprit des furbolgs Blackwood, à Sombrivage.",al={"qu’est-ce que le talisman de corruption","fonction du talisman","que fait le talisman"}},{q="Qui porte le talisman ?",a="Xabraxxis, le satyre qui surveille le campement furbolg Blackwood du nord, près de La Bondissante, porte le talisman dans sa sacoche démoniaque.",al={"qui donne le talisman de corruption","où trouver le talisman de corruption","comment obtenir le talisman"}},{q="Comment attirer le porteur du talisman ?",a="Vous ramassez les fruits, les céréales et les noix des furbolgs, puis les mélangez à de l’eau de puits de lune dans un récipient purificateur. Déposez l’offrande près du feu de joie, au bord de la rivière. La purification met Xabraxxis en rage et le pousse à attaquer.",al={"comment invoquer xabraxxis","où trouver xabraxxis","invoquer un satyre à sombrivage"}},{q="Que devient le talisman après sa récupération ?",a="Vous apportez le talisman à Thundris Windweaver, à Auberdine. Il le met en sécurité en vue de sa destruction et étudie comment libérer définitivement les furbolgs de la corruption démoniaque.",al={"à qui donner le talisman","rendre le talisman de corruption","talisman thundris windweaver"}}},fp="22,194,20.379.0,17.350.1,35.126.0,25.134.0,46.205.0,51.160.0"}
P.entries["item:tallonkai-s-jewel"] = {n="Joyau de Tallonkai",s="Sur Teldrassil, le joyau manque au talisman druidique de Tallonkai Viveracine. Ferocitas the Dream Eater convoite l’émeraude, nécessaire pour réparer le Capturêve d’émeraude.",h="Sur Teldrassil, le joyau manque au talisman druidique de Tallonkai Viveracine.",kw={"dolanaar","capturêve d'émeraude","ferocitas the dream eater","mystiques gnarlpine","brise-stellaire","tallonkai viveracine","joyau de tallonkai"},ang={["class:Druid"]="En tant que druide, vous savez que l’émeraude est accordée au Rêve d’émeraude. Son utilisation abusive par les furbolgs corrompus porte atteinte à l’équilibre.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous contribuez à rétablir l’ordre sur Teldrassil en reprenant un ouvrage sacré aux Gnarlpine qui avancent."},sec={{t="Un cœur dérobé",b="Tallonkai Viveracine a reçu le Capturêve d’émeraude de Gaerolas Talvethren, gardien des druides au Refuge des saisons de Ban’ethil. Ce talisman est un puissant focalisateur qui puise son énergie dans le Rêve d’émeraude. Lorsqu’il a été endommagé, quelqu’un a arraché son émeraude centrale rayonnante et l’a emportée dans l’est de Teldrassil.\n\nFerocitas the Dream Eater, un Gnarlpine corrompu, s’est emparé du joyau et en a fait un collier. Sa lueur verte scintillait dans la pénombre de la forêt, mais le furbolg se moquait de son harmonie avec le Rêve d’émeraude. Pour Ferocitas, ce n’était qu’un trophée en attendant qu’on le récupère."}},faq={{q="Qu’est-ce que le Joyau de Tallonkai ?",a="Le Joyau de Tallonkai est une émeraude enchantée au cœur du Capturêve d’émeraude, un focalisateur druidique que Gaerolas Talvethren a donné à Tallonkai Viveracine, de Dolanaar.",al={"qu’est-ce que le joyau","histoire du joyau de tallonkai"}},{q="Qui a volé le Joyau de Tallonkai ?",a="Ferocitas the Dream Eater a volé le joyau. Il dirige les mystiques Gnarlpine corrompus qui vivent au nord de Brise-stellaire.",al={"qui possède le joyau","qui l’a volé","qui a pris le joyau de tallonkai"}},{q="Les furbolgs Gnarlpine peuvent-ils utiliser le pouvoir du joyau ?",a="Non. Ferocitas portait l’émeraude en collier lumineux, mais son pouvoir druidique ne servait à rien au furbolg corrompu.",al={"ferocitas peut-il s’en servir","pouvoir de l’émeraude gnarlpine"}},{q="Où va le joyau après avoir été récupéré ?",a="Le joyau retourne auprès de Tallonkai Viveracine, sur la terrasse supérieure de Dolanaar. Il s’en sert pour réparer et restaurer pleinement le Capturêve d’émeraude.",al={"que devient le joyau","réparer le capturêve"}}},fx={["4dd99e12"]={q="Pourquoi quelqu'un souhaite-t-il le Joyau de Tallonkai ?",a="Tallonkai Viveracine a désespérément besoin que cette émeraude brillante lui soit rendue afin de pouvoir réparer son Capturêve d'émeraude endommagé. Le mystique furbolg Gnarlpine corrompu, Ferocitas the Dream Eater, l'a prise pour la porter en guise de collier brillant, attiré par son éclat magique sans comprendre que son pouvoir accordé au rêve est totalement inutile entre ses mains.",al={"pourquoi le joyau de tallonkai est-il recherché","pourquoi tallonkai veut-il le joyau","pourquoi voler le joyau de tallonkai"}}},fp="17,157,13.586.0,26.160.0,28.119.0,49.113.0,46.135.0"}
P.entries["item:talon-of-tethis"] = {n="Talon of Tethis",s="La Griffe de Tethis prouve une chasse dans la Vallée de Strangleronce. Hemet Nesingwary vous demande de la rapporter après avoir vaincu ce raptor insaisissable.",h="La Griffe de Tethis prouve une chasse dans la Vallée de Strangleronce.",kw={"arène des gurubashi","hemet nesingwary","raptor","maîtrise de la chasse aux raptors","vallée de strangleronce","griffe de tethis","tethis"},ang={["class:Hunter"]="En tant que Chasseur, vous devez relever le défi d’Hemet et affronter Tethis, un raptor qu’il n’a pas réussi à tuer."},sec={{t="La preuve du Chasseur",b="Hemet Nesingwary affirme que peu de chasseurs peuvent prétendre avoir tué Tethis, un raptor. Rapportez-lui la griffe, et il vous qualifiera de maître dans la chasse aux raptors."}},faq={{q="Qu'est-ce que la Griffe de Tethis ?",a="La Griffe de Tethis prouve que vous avez vaincu le raptor Tethis pour Hemet Nesingwary.",al={"griffe de tethis","objet griffe","à quoi sert la griffe"}},{q="Qui veut la griffe de Tethis ?",a="Hemet Nesingwary veut la griffe de Tethis comme preuve de la chasse.",al={"qui veut la griffe","griffe hemet","où rapporter la griffe de tethis"}},{q="Où puis-je trouver Tethis ?",a="Tethis rôde autour de l’Arène des Gurubashi, surtout au nord.",al={"où trouver tethis","emplacement de tethis","trouver le raptor"}},{q="Pourquoi Hemet veut-il la griffe ?",a="Hemet demande la griffe pour prouver que vous avez tué Tethis, un raptor qu’il n’a pas réussi à abattre lui-même.",al={"pourquoi la griffe","raison de la chasse à tethis","que veut hemet"}}},fp="15,140,18.140.0,28.86.0,25.59.0,24.63.0,30.103.0"}
P.entries["item:taming-rod"] = {n="Bâtonnet de domptage",s="À Durotar, les Bâtonnets de domptage aident les jeunes chasseurs à apprendre à commander aux bêtes. Les maîtres les prêtent à leurs élèves pour s’exercer avant de créer des liens durables avec des compagnons animaux.",h="À Durotar, les Bâtonnets de domptage aident les jeunes chasseurs à apprendre à commander aux bêtes.",kw={"scorpide cuirassé","sanglier tacheté redoutable","familier du chasseur","tranchecolline","bâtonnet de domptage","taming the beast","thotar"},ang={["class:Hunter"]="En tant que chasseur, vous utilisez un Bâtonnet de domptage pour vous exercer avant de créer des liens durables avec des bêtes sauvages.",["faction:Horde"]="À Durotar et à Mulgore, les maîtres comme Thotar se servent des Bâtonnets de domptage pour vérifier que les jeunes recrues ont la discipline nécessaire pour maîtriser la faune hostile de Kalimdor."},sec={{t="Un outil d’entraînement pour les apprentis",b="À Tranchecolline, les maîtres comme Thotar prêtent des Bâtonnets de domptage aux chasseurs orcs et trolls débutants. L’enchantement leur permet de s’exercer avant de pouvoir lier définitivement une créature sauvage. Un bâtonnet apaise un prédateur local, comme un sanglier tacheté redoutable ou un scorpide cuirassé. Le chasseur apprend à donner des ordres et à combattre aux côtés d’un compagnon animal, mais le lien ne dure que peu de temps."},{t="Vers la maîtrise",b="La magie de chaque Bâtonnet de domptage s’estompe rapidement, et chacun est harmonisé avec certains types de bêtes sauvages. Les novices affrontent des épreuves contre des bêtes aux tempéraments variés, des paisibles cueilleurs aux chasseurs venimeux agressifs. Quand un élève prouve qu’il sait commander à ces bêtes, il rend le bâtonnet au maître. Celui-ci lui apprend alors à apprivoiser, appeler et renvoyer des compagnons pour la vie, sans artéfact."}},faq={{q="À quoi sert un Bâtonnet de domptage ?",a="Les chasseurs utilisent un Bâtonnet de domptage pour s’exercer à commander une bête au combat. Un maître le prête à un jeune chasseur, et sa magie apaise et charme brièvement la créature.",al={"à quoi sert le bâtonnet de domptage","utilisation du bâtonnet de domptage","pourquoi ai-je un bâtonnet de domptage"}},{q="Est-ce que je garde l’animal apprivoisé avec le bâtonnet ?",a="Non. Une bête sous l’influence d’un Bâtonnet de domptage ne sert qu’à l’entraînement. Le lien prend fin quand la magie s’estompe ou que vous rendez le bâtonnet. Après vos épreuves, vous apprenez à apprivoiser un compagnon durable.",al={"l’animal apprivoisé est-il permanent","est-ce que je garde le sanglier","est-ce que je garde le scorpide"}},{q="Puis-je utiliser n’importe quel Bâtonnet de domptage sur n’importe quel animal ?",a="Non. Chaque Bâtonnet de domptage est harmonisé avec une créature précise pour cette étape de l’entraînement, comme un sanglier tacheté redoutable ou un scorpide cuirassé.",al={"le bâtonnet fonctionne-t-il sur tous les animaux","cibles du bâtonnet de domptage"}},{q="Puis-je garder le Bâtonnet de domptage après l’entraînement ?",a="Non. Vous rendez le Bâtonnet de domptage à votre maître chasseur après votre mission. Après votre dernière épreuve, le maître vous apprend à apprivoiser, invoquer et renvoyer des bêtes par vous-même.",al={"garder le bâtonnet de domptage","puis-je conserver le bâtonnet"}}},fx={c3dba9d3={q="Qu'est-ce qu'un Bâtonnet de domptage ?",a="Un Bâtonnet de domptage est un outil pédagogique confié aux chasseurs novices par leurs maîtres. Enchanté pour plier temporairement la volonté d'une créature sauvage à la vôtre, il sert d'aide à l'entraînement. Le manier permet à un aspirant chasseur de faire l'expérience du lien délicat requis pour commander la faune au combat sans créer de lien permanent avant que ses compétences fondamentales ne soient pleinement maîtrisées.",al={"qu'est-ce qu'un bâtonnet de domptage","objet bâtonnet de domptage","histoire du bâtonnet de domptage"}},da578f9f={q="Pourquoi un chasseur veut-il un Bâtonnet de domptage ?",a="Les chasseurs novices ont besoin du bâtonnet pour prouver leur autorité naissante sur la nature. En soumettant avec succès des bêtes dangereuses comme des sangliers ou des scorpides, vous démontrez la détermination et le sang-froid nécessaires pour contrôler un esprit sauvage. Une fois que vous avez prouvé à votre maître que vous pouvez diriger ces créatures au combat, vous apprenez les véritables arts durables du compagnonnage des bêtes.",al={"pourquoi avoir besoin d'un bâtonnet de domptage","but du bâtonnet de domptage","pourquoi utiliser le bâtonnet de domptage"}}},fp="10,164,28.377.0,21.391.0,30.160.0,38.189.0,39.141.0,56.172.0"}
P.entries["item:tapped-dowsing-widget"] = {n="Tapped Dowsing Widget",s="Un Tapped Dowsing Widget contient un échantillon d’eau prélevé dans un bassin près du Guet de Tristesable, à Tanaris. La Compagnie des Eaux de Gadgetzan a besoin de tels relevés, car les puits du désert se raréfient.",h="Un Tapped Dowsing Widget contient un échantillon d’eau prélevé dans un bassin près du Guet de Tristesable, à...",kw={"radiésthéflop","gadgetzan","guet de tristesable","tanaris","tapped dowsing widget","untapped dowsing widget","échantillon d’eau","relevé des sources"},sec={{t="Un échantillon du désert",b="Le Grand Géomètre Radiésthéflop vous envoie de Gadgetzan tester le bassin près du Guet de Tristesable. Le widget prélève un échantillon pour la Compagnie des Eaux de Gadgetzan, qui cherche des sources d’eau libre alors que des nomades s’emparent de ses puits. Pourtant, le bassin se trouve à portée de vue des trolls, et le relevé expose à un autre danger du désert."}},faq={{q="Qu’est-ce que le Tapped Dowsing Widget ?",a="C’est un Untapped Dowsing Widget qui a recueilli un échantillon d’eau du bassin près du Guet de Tristesable, à Tanaris.",al={"widget prélevé","gadget échantillon d’eau","truc de sourcier"}},{q="Où utiliser le widget de sourcier ?",a="Utilisez l’Untapped Dowsing Widget au bassin près du Guet de Tristesable, à l’ouest de Gadgetzan et au sud de Zul’Farrak.",al={"où utiliser le widget","emplacement du bassin","eau de tristesable"}},{q="Qui veut l’échantillon d’eau ?",a="Le Grand Géomètre Radiésthéflop, à Gadgetzan, vous demande de lui rapporter le Tapped Dowsing Widget pour la Compagnie des Eaux de Gadgetzan.",al={"qui veut l’échantillon","radiésthéflop","compagnie des eaux de gadgetzan"}},{q="Pourquoi la compagnie relève-t-elle les sources d’eau ?",a="La Compagnie des Eaux de Gadgetzan cherche des sources d’eau libre, car des nomades s’emparent de ses puits.",al={"pourquoi relever les sources","pas de puits","pénurie d’eau"}},{q="Quel danger rôde près du bassin ?",a="Des rapports parlent d’étranges créatures insectoïdes qui aspirent l’eau du désert. Les trolls qui rôdent autour du bassin peuvent aussi apercevoir les géomètres.",al={"danger près du bassin","insectes à tristesable","bestiole rampante"}}},fp="21,172,15.314.0,34.114.0,34.109.0,27.130.0,35.90.0,29.131.1"}
P.entries["item:taragaman-the-hungerer-s-heart"] = {n="Coeur de Taragaman l'Affameur",s="Sous Orgrimmar, Neeru Fireblade cherche le Coeur de Taragaman l'Affameur pour prouver que la présence démoniaque a disparu. Ce trophée provient du garde-gangrené qui règne dans les profondeurs du Gouffre de Ragefeu.",h="Sous Orgrimmar, Neeru Fireblade cherche le Coeur de Taragaman l'Affameur pour prouver que la présence...",kw={"garde-gangrené","cœur","affameur","neeru fireblade","orgrimmar","gouffre de ragefeu","searing blade","taragaman"},ang={["class:Warlock"]="En tant que démoniste, vous connaissez les subtils réseaux d'ombre et de tromperie à l'œuvre dans la Faille de l'Ombre. Traiter avec Neeru Fireblade et s'occuper de restes démoniaques vous sont familiers.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à protéger Orgrimmar de la corruption intérieure. Le cœur arraché de la bête témoigne de la vigilance de la Horde."},sec={{t="Un trophée trompeur",b="Le Coeur de Taragaman l'Affameur prouve que le garde-gangrené a été vaincu. Neeru Fireblade affirme à Thrall et aux aventuriers impatients que Taragaman dirige les sectateurs de la Searing Blade dans le Gouffre de Ragefeu. Remettre le cœur à Neeru semble accomplir l'ordre du chef de guerre de protéger Orgrimmar de la corruption démoniaque. En attribuant la direction de la secte à un garde-gangrené brutal, il dissimule aussi les réseaux mortels sous la ville."}},faq={{q="Qui veut le Coeur de Taragaman l'Affameur ?",a="Neeru Fireblade, un démoniste orc dans la Faille de l'Ombre d'Orgrimmar, vous demande de lui apporter le cœur pour prouver que le démon a été tué.",al={"qui récupère le cœur de taragaman","remettre le cœur de taragaman","qui veut le cœur"}},{q="Où trouver ce cœur ?",a="Vous prenez le cœur sur le cadavre de Taragaman l'Affameur, dans les chambres magmatiques centrales du Gouffre de Ragefeu, sous Orgrimmar. Cet imposant garde-gangrené y réside.",al={"comment obtenir le cœur de taragaman","où tombe le cœur de taragaman","emplacement du cœur de taragaman"}},{q="Thrall voit-il un jour le cœur ?",a="Non. Vous apportez le cœur directement à Neeru Fireblade. Il dit qu'il s'occupera des restes démoniaques et qu'il annoncera lui-même la victoire au chef de guerre Thrall.",al={"thrall reçoit-il le cœur","donner le cœur à thrall","thrall et le cœur de taragaman"}},{q="Taragaman était-il vraiment le chef de la Searing Blade ?",a="Neeru Fireblade désigne Taragaman l'Affameur comme chef de la Searing Blade. Il affirme que le tuer et rapporter son cœur apaisera Thrall.",al={"taragaman est-il le chef","qui dirige la searing blade","taragaman est-il le vrai chef"}}},fx={a71e3ad9={q="Qu'est-ce que le Coeur de Taragaman l'Affameur ?",a="Il s'agit du cœur tranché de Taragaman l'Affameur, un garde gangrené massif tapi dans les profondeurs ardentes du Gouffre de Ragefeu sous Orgrimmar. Sorti des cavernes par des aventuriers, il sert de preuve physique que le démon que Neeru Fireblade désigne comme le chef de la Lame enflammée a été abattu.",al={"qu'est-ce que le coeur de taragaman","coeur de taragaman l'affameur","histoire du coeur de taragaman"}},d8388abb={q="D'où vient le Coeur de Taragaman l'Affameur ?",a="Le cœur est extrait de la poitrine de Taragaman l'Affameur, un énorme garde gangrené stationné au plus profond du Gouffre de Ragefeu. Taragaman a été invoqué et hébergé dans les tunnels souterrains sous Orgrimmar par les cultistes de la Lame enflammée, faisant du cœur une relique organique de la corruption démoniaque infestant les entrailles de la ville.",al={"origine du coeur de taragaman","d'où vient le coeur","qui a créé le coeur de taragaman"}}},fp="30,182,18.408.1,41.130.0,29.153.0,31.144.0,52.144.1"}
P.entries["item:tattered-manuscript"] = {n="Manuscrit en lambeaux",s="À Mille pointes, le Manuscrit en lambeaux est caché au Bastion du Sabot fendu. Ses pages déchirées viennent du Tome of the Cabal, que les démonistes recherchent pour apprendre à invoquer un chasseur corrompu.",h="À Mille pointes, le Manuscrit en lambeaux est caché au Bastion du Sabot fendu.",kw={"chasseur corrompu","jorah annison","krom rudebras","tome moisi","bastion du sabot fendu","manuscrit en lambeaux","mille pointes","tome of the cabal"},ang={["class:Warlock"]="En tant que démoniste, vous recherchez le manuscrit pour apprendre à commander aux chasseurs corrompus."},sec={{t="Un grimoire vandalisé",b="Autrefois, le Tome of the Cabal était un ouvrage unique et complet, conservé dans le royaume déchu de Lordaeron. Un profanateur inconnu en arracha presque la moitié des pages de la reliure. Le dos et les pages restantes furent connus sous le nom de Tome moisi. Ils furent envoyés vers le sud, en direction de Khaz Modan, puis perdus en mer. Les feuillets déchirés traversèrent La Grande mer jusqu’en Kalimdor et tombèrent entre les mains des centaures Galak, au Bastion du Sabot fendu."},{t="Retrouver les écrits",b="Un coffre abîmé, au fond des cavernes du Bastion du Sabot fendu, renferme le manuscrit. Il y a résisté aux vents secs de Mille pointes. Les démonistes de l’Alliance collaborent avec Krom Rudebras à Forgefer, tandis que ceux de la Horde aident Jorah Annison à Fossoyeuse. Les deux groupes affrontent les centaures agressifs pour réunir les feuillets au Tome moisi. Ensemble, les livres contiennent de sombres rituels permettant d’invoquer et de lier un chasseur corrompu démoniaque."}},faq={{q="Qu’est-ce que le Manuscrit en lambeaux ?",a="Le Manuscrit en lambeaux rassemble des pages déchirées qui constituent environ la moitié du Tome of the Cabal, un grimoire unique consacré à la démonologie.",al={"histoire du manuscrit en lambeaux","qu’est-ce que le manuscrit","pages du tome of the cabal"}},{q="Comment ces pages sont-elles arrivées à Mille pointes ?",a="Après qu’un profanateur inconnu a déchiré le Tome of the Cabal à Lordaeron, ses pages ont traversé la mer. Les centaures Galak les ont récupérées et cachées dans un coffre au Bastion du Sabot fendu.",al={"pourquoi au bastion du sabot fendu","centaures et tome","manuscrit de mille pointes"}},{q="À quoi sert le manuscrit ?",a="Les démonistes réunissent le Manuscrit en lambeaux au Tome moisi, détrempé, pour reconstituer le Tome of the Cabal. Le livre restauré enseigne le rituel permettant d’invoquer un chasseur corrompu.",al={"pourquoi ai-je besoin du manuscrit","pages de quête du chasseur corrompu"}},{q="Qui a déchiré le livre original ?",a="Personne ne sait qui a déchiré le livre original. Krom Rudebras, à Forgefer, et Jorah Annison, à Fossoyeuse, déplorent tous deux les dommages infligés à cet ouvrage savant unique.",al={"qui a déchiré le tome","qui a vandalisé le tome of the cabal"}}},fp="19,178,21.399.0,20.415.0,32.126.0,47.167.0,32.166.0,56.168.0"}
P.entries["item:tazan-s-satchel"] = {n="Sacoche de Tazan",s="Près de Cabestan, Tazan affronte des pirates sur la côte, une sacoche verrouillée à la main. La Main brisée convoite les renseignements qu'elle contient.",h="Près de Cabestan, Tazan affronte des pirates sur la côte, une sacoche verrouillée à la main.",kw={"tarides","la faille de l'ombre","gamon","cabestan","main brisée","tazan","sacoche de tazan","therzok"},ang={["class:Rogue"]="En tant que voleur de la Horde, vous devez récupérer la sacoche et subtiliser sa clé à Gamon pour gagner votre place dans la Main brisée.",["faction:Horde"]="À Orgrimmar, la Main brisée cherche un avantage clandestin tandis que le chef de guerre Thrall suit une voie plus mesurée."},sec={{t="Secrets des Tarides",b="Près de Cabestan, Tazan traite avec des pirates installés sur la côte des Tarides. Therzok, maître de guilde de la Main brisée sous Orgrimmar, dans la Faille de l'Ombre, a remarqué ses activités. La guilde cherche secrètement à accroître son pouvoir, au-delà de la diplomatie prudente du chef de guerre Thrall. Elle a désigné Tazan pour être éliminé et s'emparer des renseignements contenus dans sa sacoche."},{t="Une serrure complexe",b="La serrure de la sacoche est difficile à ouvrir sur le terrain. Tazan a confié la clé à Gamon, son associé, qui boit dans une taverne d'Orgrimmar. Les voleurs qui convoitent la sacoche doivent subtiliser la clé dans la poche de Gamon sans donner l'alerte. Ils pourront ensuite lire le journal de Tazan."}},faq={{q="À qui appartient cette sacoche ?",a="Tazan, un troll qui traite avec des pirates près de Cabestan, dans les Tarides, porte la sacoche.",al={"qui est tazan","propriétaire de tazan","propriétaire de la sacoche"}},{q="Pourquoi la Main brisée veut-elle la Sacoche de Tazan ?",a="Therzok et la Main brisée convoitent les renseignements sur les relations de Tazan avec les pirates de la côte. Ils espèrent étendre leur réseau et retrouver leur fierté martiale depuis l'ombre.",al={"pourquoi therzok la veut","sacoche de la main brisée","pourquoi voler la sacoche"}},{q="Où se trouve la clé de la sacoche ?",a="Tazan a laissé la clé à son associé Gamon, un habitué ivre d'une taverne d'Orgrimmar.",al={"comment ouvrir la sacoche","clé de tazan","où se trouve la clé"}},{q="Que contient la Sacoche de Tazan ?",a="Le journal de Tazan se trouve dans la sacoche verrouillée. Il détaille ses échanges secrets et ses liens avec les flibustiers de la côte.",al={"contenu de la sacoche","que contient le sac","journal de tazan"}}},fp="15,130,22.331.0,14.260.1,32.87.0,49.170.0,37.85.1,31.108.1"}
P.entries["item:tear-of-the-moons"] = {n="Larme des lunes",s="À Bael Modan, dans les Tarides du sud, des excavateurs nains ont mis au jour la Larme des lunes. Son étrange pouvoir s'empare de Feegly, et le général Twinbraid redoute son influence.",h="À Bael Modan, dans les Tarides du sud, des excavateurs nains ont mis au jour la Larme des lunes.",kw={"bael modan","donjon de bael'dun","tarides","fouilles","feegly","larme des lunes","trogg","twinbraid"},ang={["faction:Horde"]="En tant que membre de la Horde, vous aidez à récupérer la relique au donjon de Bael'dun, perturbant la présence militaire de Forgefer qui empiète sur les terres ancestrales des taurens.",["race:Dwarf"]="En tant que nain, le sort de Feegly rappelle le danger que l'expédition de Bael'dun risque de réveiller sous Kalimdor."},sec={{t="Une relique déterrée",b="Des excavateurs nains ont découvert la Larme des lunes lors des premières fouilles à Bael Modan. Son étrange lumière a captivé les mineurs, surtout Feegly. Il disait qu'elle lui donnait une grande force, mais il est vite devenu instable et s'est retourné contre ses compagnons.\n\nLe général Twinbraid, commandant de l'expédition, craignait l'influence de la relique et la disait maudite. Il s'est emparé du cristal et l'a enfermé dans son coffre personnel au donjon de Bael'dun. Puis il a banni Feegly dans les Tarides."},{t="Le prix de l'obsession",b="Exilé, Feegly ne parvient pas à maîtriser son désir du pouvoir du cristal. Il demande aux voyageurs de la Horde de passage de l'aider à s'introduire dans la forteresse naine et à le reprendre dans le coffre de Twinbraid.\n\nQuand Feegly récupère la Larme et la frotte, d'étranges grognements lui échappent. Le cristal lui tombe des mains et se brise au sol. Feegly se transforme en trogg et meurt peu après."}},faq={{q="D'où vient la Larme des lunes ?",a="Des Dwarven Prospectors et des excavateurs ont mis au jour la Larme des lunes à Bael Modan, un site de fouilles archéologiques dans les Tarides du sud.",al={"origine de la larme","où la larme a été trouvée","histoire de la larme des lunes"}},{q="Pourquoi le cristal a-t-il été enfermé au donjon de Bael'dun ?",a="Le général Twinbraid craignait que le cristal soit maudit après que Feegly en est devenu obsédé et s'est retourné contre ses compagnons mineurs. Il l'a enfermé dans son coffre au donjon de Bael'dun pour protéger l'expédition.",al={"pourquoi l'enfermer","larme dans le coffre de twinbraid","pourquoi twinbraid l'a prise"}},{q="Que se passe-t-il quand Feegly récupère la Larme ?",a="Feegly frotte le cristal, qui lui tombe des mains et se brise. Il se transforme en trogg et meurt peu après.",al={"feegly se transforme en trogg","que devient feegly","transformation de feegly en trogg"}},{q="Peut-on sauver ou réparer la Larme des lunes ?",a="La Larme se brise lorsque Feegly la récupère. Le récit ne dit pas si quelqu'un la répare par la suite.",al={"peut-on garder la larme","larme brisée","réparer la larme des lunes"}}},fx={f703febe={q="Qu'est-ce que la Larme des lunes ?",a="La Larme des lunes est un mystérieux cristal brillant déterré par des excavateurs nains lors de leur exploration de Bael Modan dans les Tarides du sud. Bien qu'elle soit célébrée comme la première grande découverte du site, l'artefact s'est avéré profondément instable, irradiant un pouvoir corrupteur qui a déformé l'esprit du nain qui le détenait et a incité la direction de l'expédition à l'enfermer.",al={"larme des lunes","qu'est-ce que la larme des lunes","qu'est-ce que la larme"}}},fp="17,170,17.458.0,22.354.1,42.133.0,48.194.0,44.115.1,47.103.1"}
P.entries["item:tear-of-tilloa"] = {n="Larme de Tilloa",s="Près de Sombre-Comté, la Larme de Tilloa attire ceux qui cherchent des réactifs alchimiques rares. La fleur pousse sur le domaine Mantebrume, dans le Bois de la Pénombre.",h="Près de Sombre-Comté, la Larme de Tilloa attire ceux qui cherchent des réactifs alchimiques rares.",kw={"a noble brew","sombre-comté","mantebrume","stalvan","larme de tilloa","tilloa","wishock","zardeth"},ang={["class:Warlock"]="En tant que démoniste, vous connaissez peut-être la Larme de Tilloa, un réactif recherché par des agents occultes sous la capitale. Ils l’utilisent dans des breuvages destinés à faire taire les nobles trop curieux.",["profession:Herbalism"]="En tant qu’herboriste, vous pouvez trouver la Larme de Tilloa dans les terres flétries du Bois de la Pénombre, loin des champs habituellement luxuriants."},sec={{t="Un jardin dans la pénombre",b="À l’extérieur de Sombre-Comté, la Larme de Tilloa pousse sur le domaine de Stalvan Mantebrume. Le sol du Bois de la Pénombre est devenu hostile à la végétation saine, mais la petite fleur blanche persiste parmi les parcelles ombragées. Rare et isolée, elle attire ceux qui cherchent des réactifs inhabituels en dehors des marchés légaux."},{t="Un breuvage pour les nobles",b="Sous les rues de Hurlevent, Zardeth de la Griffe noire cherche la Larme de Tilloa pour préparer un breuvage destiné au seigneur Wishock. Membre de la Maison des Nobles, Wishock menace d’enquêter sur les opérations clandestines sous la capitale. Zardeth associe la fleur à de la Racine de Musquash provenant de sous le Barrage de Formepierre. Le breuvage doit distraire et neutraliser Wishock avant le début d’une enquête officielle."}},faq={{q="Où pousse la Larme de Tilloa ?",a="La fleur pousse dans le jardin envahi par la végétation du domaine familial Mantebrume, aux abords de Sombre-Comté, dans le Bois de la Pénombre.",al={"emplacement de la larme de tilloa","où trouver la larme de tilloa","lieu de tilloa"}},{q="Qui veut la Larme de Tilloa ?",a="Zardeth de la Griffe noire cherche la fleur dans le cadre de ses activités clandestines sous Hurlevent. Il en a besoin pour un breuvage spécial.",al={"qui a besoin de la larme de tilloa","donneur de quête de la larme de tilloa","qui la veut"}},{q="À quoi sert la fleur ?",a="La fleur entre dans la préparation d’un breuvage avec de la Racine de Musquash. Celui-ci doit neutraliser le seigneur Wishock et faire taire ses appels à enquêter sur les sombres affaires sous la capitale.",al={"usage de la larme de tilloa","à quoi sert la larme de tilloa","fleur pour breuvage noble"}},{q="Qui est le seigneur Wishock ?",a="Le seigneur Wishock est un noble de la Maison des Nobles de Hurlevent. Après avoir découvert des opérations subversives sous la ville, il a commencé à exhorter le conseil à enquêter.",al={"wishock","qui est wishock","seigneur wishock"}}},fx={e7b72a0d={q="Qu'est-ce que la Larme de Tilloa ?",a="La Larme de Tilloa est une fleur blanche délicate et rare qui fleurit dans le Bois de la Pénombre. Trouvée spécifiquement dans le jardin négligé de Stalvan, en périphérie de Sombre-Comté, cette plante discrète possède des propriétés puissantes convoitées par les pratiquants des arts sombres qui opèrent loin, dans les tunnels sous Hurlevent.",al={"qu'est-ce que la larme de tilloa","fleur larme de tilloa","larme de tilloa"}},d8c5f010={q="D'où vient la Larme de Tilloa ?",a="La fleur pousse naturellement dans le jardin envahi de Stalvan, situé juste au-delà de la sécurité de Sombre-Comté dans la forêt ombragée du Bois de la Pénombre. Aucun artisan mortel ne l'a créée ; elle fleurit simplement sans être dérangée au milieu du domaine tragique de l'ancienne demeure des Mantebrume.",al={"d'où vient la larme de tilloa","qui a créé la larme de tilloa","origine de la larme de tilloa"}}},fp="14,135,21.284.0,27.398.1,35.115.0,29.124.0,28.155.1,20.162.0"}
P.entries["item:techbot-s-memory-core"] = {n="Mémoire de Techbot",s="À Gnomeregan, Tinkmaster Overspark cherche la Mémoire de Techbot pour étudier le comportement altéré de l’automate.",h="À Gnomeregan, Tinkmaster Overspark cherche la Mémoire de Techbot pour étudier le comportement altéré de...",kw={"cerveau","gnomeregan","mémoire","négatronique","overspark","positronique","techbot","brikabrok"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous pouvez voir comment un simple court-circuit a polarisé le cerveau positronique de Techbot et inversé sa logique.",["race:Gnome"]="Pour les gnomes, Techbot est une autre victime de la chute de Gnomeregan. La ruine de la cité a emporté une brillante ingénierie de temps de paix."},sec={{t="Un cerveau polarisé",b="Avant la chute de Gnomeregan, Techbot aidait Tinkmaster Overspark et ses collègues inventeurs grâce à ses appareils et à ses connaissances. Pendant la chute de la cité, une décharge électrique errante secoua Techbot et transforma son cerveau positronique en un état négatronique hostile. Désormais, l’automate erre dans les couloirs souillés de Gnomeregan et attaque quiconque passe à sa portée. Overspark espère que la mémoire l’aidera à comprendre la panne et à rendre ses esprits à sa création."}},faq={{q="Qu’est-ce que la Mémoire de Techbot ?",a="La Mémoire de Techbot contient les données et les connaissances de Techbot. Techbot est l’automate créé par Tinkmaster Overspark, et sa mémoire consigne la perturbation électrique qui l’a altéré pendant la chute de Gnomeregan.",al={"mémoire de techbot","objet cerveau de techbot","qu’est-ce que le noyau de techbot"}},{q="Qui veut la Mémoire de Techbot ?",a="Tinkmaster Overspark veut la Mémoire de Techbot. Il a trouvé refuge auprès d’autres gnomes exilés à Brikabrok, dans Forgefer. Il demande aux aventuriers d’entrer dans Gnomeregan, de désactiver Techbot et de rapporter sa mémoire afin qu’il puisse tenter de le réparer.",al={"qui a besoin de la mémoire de techbot","à qui remettre la mémoire de techbot","où apporter la mémoire de techbot"}},{q="Pourquoi Techbot est-il devenu fou furieux ?",a="Pendant la chute de Gnomeregan, une étincelle électrique errante secoua le cerveau positronique de Techbot. La surtension le polarisa en un état négatronique, transformant sa personnalité et ses protocoles, autrefois serviables, en une frénésie violente.",al={"pourquoi techbot est-il hostile","qu’est-il arrivé à techbot","techbot devenu fou"}},{q="Où récupérer la mémoire ?",a="La mémoire se récupère sur Techbot, qui rôde dans les couloirs mécaniques supérieurs et près des entrées de Gnomeregan, à Dun Morogh.",al={"où trouver la mémoire de techbot","emplacement de techbot","comment obtenir le cerveau de techbot"}}},fx={a503508b={q="D'où vient la Mémoire de Techbot, et qui l'a créée ?",a="La mémoire provient de Techbot, une construction mécanique complexe conçue par Tinkmaster Overspark à Gnomeregan. Overspark a conçu la machine pour l'assister, lui et ses collègues inventeurs, avec une réserve infinie de données et de gadgets. Cependant, lorsque Gnomeregan est tombée aux mains des troggs, une surtension électrique a secoué Techbot et a polarisé son cerveau positronique dans un état négatronique, rendant la machine folle.",al={"qui a créé la mémoire de techbot","origine de techbot","qui a construit techbot"}}},fp="21,108,17.433.0,30.204.0,32.231.0,27.207.0,27.116.0"}
P.entries["item:telescopic-lens"] = {n="Lentille du télescope",s="Au-dessus du port de Cabestan, Gazlowe a besoin de la Lentille du télescope pour achever son télescope d’observatoire. Des pirates Southsea ont pris la lentille sur un navire, et elle se trouve toujours dans leur camp au sud de la ville.",h="Au-dessus du port de Cabestan, Gazlowe a besoin de la Lentille du télescope pour achever son télescope...",kw={"caisse","gazlowe","observatoire","cabestan","southsea freebooters","stolen booty","lentille du télescope"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous pouvez admirer la finesse de l’ouvrage optique de cette lentille. Elle focalise les mécanismes d’observation à longue portée sans aberration sphérique.",["race:Gnome"]="En tant que gnome, vous pouvez vous moquer des fusées gobelines. Pourtant, le dévouement de Gazlowe à l’astronomie optique montre que l’ingénierie gobeline ne se résume pas aux explosifs puissants."},sec={{t="Les yeux tournés vers le ciel",b="Cabestan est réputé pour son commerce impitoyable, mais Gazlowe, son contremaître et ingénieur en chef, nourrit de plus grandes ambitions mécaniques. Son observatoire s’élève au-dessus du port, bâti pour surveiller le trafic maritime et les étoiles. La plus grande lentille est arrivée sans encombre par voie terrestre depuis Durotar. La plus petite, essentielle, a voyagé par mer, où les Southsea Freebooters s’en prennent aux routes marchandes au large des côtes des Tarides."},{t="Butin des pirates",b="Quand les Southsea Freebooters ont attaqué le navire de transport, ils ont pris tout ce qui avait de la valeur, y compris les optiques délicates. La lentille se trouve peut-être parmi le désordre de leur campement sur la plage, au sud de Cabestan. Les pirates n’en apprécient peut-être pas la finesse, ou ignorent comment la mettre en gage. Gazlowe a besoin qu’on lui rapporte le verre intact pour que sa terrasse d’observation puisse enfin faire la mise au point."}},faq={{q="Pourquoi Gazlowe a-t-il besoin de cette lentille ?",a="Gazlowe a besoin de la Lentille du télescope pour achever le télescope de l’observatoire de Cabestan. La plus grande lentille est arrivée par voie terrestre depuis Durotar, mais la plus petite a été perdue en mer.",al={"lentille de gazlowe","à quoi sert la lentille","pourquoi une lentille de télescope"}},{q="Qui a volé la Lentille du télescope ?",a="Les Southsea Freebooters ont volé la Lentille du télescope. Ces pirates humains et gobelins s’en prennent aux navires marchands près de La Côte des marchands. Ils gardent la lentille dans une caisse marquée, dans leur camp côtier au sud de Cabestan.",al={"qui a pris la lentille","qui a la lentille","emplacement de la lentille du télescope"}},{q="D’où venait la lentille à l’origine ?",a="La Lentille du télescope a voyagé par mer jusqu’à Cabestan, tandis que sa jumelle est arrivée par voie terrestre depuis Durotar. Les navires qui accostent au port viennent souvent de l’autre côté de La Grande mer ou de territoires gobelins du sud, comme Baie-du-Butin.",al={"où la lentille a-t-elle été fabriquée","origine de la lentille","où gazlowe a-t-il commandé la lentille"}},{q="La lentille est-elle intacte malgré le vol ?",a="La lentille est restée intacte. Une caisse marquée « Fragile - Ne pas faire tomber » a protégé le verre de précision des manipulations brutales des pirates.",al={"la lentille est-elle cassée","caisse fragile ne pas faire tomber"}}},fx={ddcd39c0={q="Qu'est-ce que la Lentille du télescope ?",a="Il s'agit d'une lentille optique de précision conçue pour un télescope d'observatoire. Gazlowe a commandé deux lentilles spécialisées pour compléter le télescope au sommet de sa tour à Cabestan, et cette pièce secondaire plus petite a été expédiée outre-mer avant d'être interceptée par les Southsea Freebooters.",al={"qu'est-ce que la lentille du télescope","objet lentille du télescope","qu'est-ce que cette lentille"}}},fp="15,186,15.371.0,14.346.0,32.171.0,30.203.0,40.213.0,43.136.0"}
P.entries["item:teronis-journal"] = {n="Journal de Teronis",s="En Orneval, le Journal de Teronis retrace la quête d’un éclaireur à la recherche d’une gemme liée à une baguette censée freiner les attaques des furbolgs.",h="En Orneval, le Journal de Teronis retrace la quête d’un éclaireur à la recherche d’une gemme liée à une...",kw={"orneval","astranaar","gemme luminescente","raene mène-loup","raene's cleansing","sentinels","teronis","journal de teronis"},ang={["faction:Alliance"]="Rapporter les notes de terrain de Teronis à Astranaar aide la garnison à coordonner les secours et à récupérer la dépouille de son éclaireur tombé au combat.",["race:NightElf"]="En tant qu’elfe de la nuit, vous pouvez lire le journal de Teronis comme un rappel des dangers auxquels les éclaireurs font face en protégeant les antiques forêts d’Orneval contre la corruption qui gagne du terrain."},sec={{t="Le dernier récit d’un éclaireur",b="Teronis était un ami de longue date de Raene Mène-loup et prêtait main-forte aux Sentinels. Il cherchait en Orneval une gemme qu’il croyait liée à une baguette capable de ralentir les attaques des furbolgs contre son peuple. Près du rivage, des créatures agressives mirent fin à son voyage.\n\nLe journal fut retrouvé parmi ses effets personnels, en remarquablement bon état. Ses notes sur une gemme rayonnante qui avait autrefois fait partie de la baguette donnent aux défenseurs d’Astranaar une piste pour poursuivre sa quête inachevée."}},faq={{q="À qui appartenait ce journal ?",a="Le journal appartenait à Teronis, un elfe de la nuit et ami de longue date de Raene Mène-loup. Il cherchait en Orneval une gemme liée à une baguette qu’il croyait capable de ralentir les attaques des furbolgs, mais il mourut dans les étendues sauvages avant de revenir avec ses découvertes.",al={"qui a écrit le journal","qui est teronis","histoire de teronis"}},{q="Où trouve-t-on le journal ?",a="Le journal fut retrouvé parmi les affaires de Teronis après que son corps sans vie eut été découvert dans les étendues sauvages d’Orneval. Il se trouvait près du rivage où vivent les murlocs locaux.",al={"où trouver le journal","emplacement du journal de teronis","comment obtenir le journal"}},{q="Pourquoi apporter le journal à Astranaar ?",a="Rapporter le journal à Raene Mène-loup apprend à Astranaar la mort de Teronis. Ses notes donnent aussi aux Sentinels un moyen de poursuivre sa quête de la baguette qu’il espérait capable de ralentir les attaques des furbolgs.",al={"pourquoi apporter le journal à raene","à qui remettre le journal","remise du journal"}},{q="Quel objet Teronis cherchait-il selon sa mission ?",a="Teronis cherchait une Gemme luminescente, l’un des éléments d’une baguette fabriquée par le magicien défunt Dartol. Son enquête laisse penser que les murlocs des environs ont peut-être récupéré l’artefact.",al={"que recherchait teronis","quelle gemme cherchait-il","gemme de teronis"}}},fx={["5fb93f8f"]={q="Qu'est-ce que le Journal de Teronis ?",a="Le Journal de Teronis est un carnet personnel tenu par l'éclaireur elfe de la nuit Teronis. Retrouvé parmi ses effets personnels à côté de son corps à Orneval, il détaille sa mission et ses efforts de reconnaissance initiaux concernant une étrange gemme qu'il avait été envoyé chercher avant de rencontrer une mort prématurée.",al={"qu'est-ce que le journal de teronis","objet journal de teronis","à propos du journal de teronis"}}},fp="16,115,22.463.0,31.224.0,27.158.0,57.192.0,59.156.0"}
P.entries["item:tharil-zun-s-head"] = {n="Tête de Tharil'zun",s="À Comté-du-Lac, la tête de Tharil'zun prouve que le commandant qui terrorisait les Carmines est mort. Il dirigeait les Outrunners orcs de Rochenoire qui occupaient Guet-de-pierre.",h="À Comté-du-Lac, la tête de Tharil'zun prouve que le commandant qui terrorisait les Carmines est mort.",kw={"blackrock outrunners","comté-du-lac","maréchal marris","guet-de-pierre","donjon de guet-de-pierre","tharil'zun","tête de tharil'zun"},ang={["faction:Alliance"]="Chaque chef Rochenoire tué soulage Comté-du-Lac, une ville assiégée qui lutte pour survivre sans renforts officiels de Hurlevent."},sec={{t="Trophée de Guet-de-pierre",b="Les orcs de Rochenoire du donjon de Guet-de-pierre ont pillé les fermes de Comté-du-Lac et tendu des embuscades aux voyageurs sur les routes. Tharil'zun dirigeait les Blackrock Outrunners responsables de ces attaques.\n\nLe maréchal Marris ne prendra pas le risque d'agir sur la base de rumeurs ou de victoires partielles. Il exige la preuve de la mort de Tharil'zun, et sa tête tranchée la lui apporte. Les embuscades coordonnées des Outrunners depuis le donjon ont subi un coup dur."}},faq={{q="Qui était Tharil'zun ?",a="Tharil'zun était un commandant orc de Rochenoire rusé et cruel, installé au donjon de Guet-de-pierre. Il dirigeait les Blackrock Outrunners, qui tendaient sans relâche des embuscades avec les Renegades entre Comté-du-Lac et le donjon.",al={"lore de tharil'zun","qui est tharil'zun","chef tharil'zun"}},{q="Pourquoi le maréchal Marris veut-il sa tête ?",a="Hurlevent refuse une aide militaire importante aux Carmines. Le maréchal Marris et la garde de Comté-du-Lac comptent donc sur des mercenaires pour frapper les menaces majeures. Marris a besoin d'une preuve de la mort de Tharil'zun pour savoir que les chefs des Outrunners sont bel et bien anéantis.",al={"pourquoi la tête de tharil'zun","preuve de la mort pour marris","prime de marris"}},{q="Où trouver Tharil'zun ?",a="Tharil'zun tient le donjon de Guet-de-pierre, dans les collines orientales des Carmines. Des orcs de Rochenoire et des gnolls encerclent le donjon.",al={"emplacement de tharil'zun","où est tharil'zun","trouver tharil'zun"}},{q="La tête de Tharil'zun met-elle fin à la menace de Rochenoire ?",a="Non. La mort de Tharil'zun perturbe les embuscades des Outrunners, mais le Clan Rochenoire conserve une force massive retranchée dans le donjon de Guet-de-pierre et dans les Carmines.",al={"les orcs sont-ils partis","avons-nous sauvé les carmines","après tharil'zun"}}},fx={a015b31b={q="Qu'est-ce que la Tête de Tharil'zun ?",a="Cette tête tranchée est la preuve physique que Tharil'zun, le commandant dirigeant les embuscades des orcs Rochenoire autour du Donjon de Guet-de-pierre, a été tué. Rapportée à Comté-du-Lac, elle montre à la garde de la ville assiégée que l'un des chefs de terrain les plus dangereux du clan Rochenoire dans les montagnes des Carmines ne terrorisera plus les routes.",al={"objet tête de tharil'zun","histoire de la tête de tharil'zun"}},f673cecf={q="D'où vient la Tête de Tharil'zun ?",a="Elle est prélevée directement sur le cadavre de Tharil'zun, un éminent chef orc Rochenoire opérant depuis les ruines du Donjon de Guet-de-pierre. Après qu'il tombe au combat face à vous ou aux défenseurs de Comté-du-Lac, la tête est réclamée comme un trophée indéniable et une sinistre vérification de sa mort.",al={"qui a pris la tête de tharil'zun","origine de la tête de tharil'zun","d'où vient la tête de tharil'zun"}}},fp="17,139,20.381.0,19.185.0,38.234.0,26.121.0,55.167.0"}
P.entries["item:tharnariun-s-hope"] = {n="Espoir de Tharnariun",s="À Sombrivage, Tharnariun Soigneflore cherche un remède pour les ours des chardons malades. Son piège les apaise assez longtemps pour les mener jusqu’à son camp.",h="À Sombrivage, Tharnariun Soigneflore cherche un remède pour les ours des chardons malades.",kw={"sombrivage","plagued lands","ours des chardons enragé","tharnariun","espoir de tharnariun","ours des chardons","piège"},ang={["class:Druid"]="En tant que druide, vous pouvez voir dans le piège de Tharnariun un choix de préserver les bêtes corrompues tant qu’il leur reste une chance d’être sauvées.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous savez que les ours des chardons sont chers aux habitants de Sombrivage. Leur maladie fait du piège de Tharnariun le signe d’une compassion désespérée."},sec={{t="Un piège doux",b="Tharnariun Soigneflore a fabriqué un piège pour apaiser les ours des chardons malades. Une mystérieuse affliction les rend de plus en plus frénétiques et violents à travers Sombrivage. Il espère les guérir plutôt que de les voir tués. Posé au sol, l’Espoir de Tharnariun brille d’une lumière apaisante. Un ours des chardons enragé qui le traverse retrouve son calme pour un temps et peut suivre un voyageur jusqu’au camp de Tharnariun pour y être soigné."},{t="Un remède insaisissable",b="La magie guérisseuse de Tharnariun Soigneflore ne peut sauver un ours capturé. Le piège apaise l’animal en furie sans lui faire de mal, mais la corruption est plus virulente qu’il ne le pensait. Lorsqu’il dirige sa magie guérisseuse vers l’ours, celle-ci entre en conflit avec l’infection. L’animal s’effondre et meurt. Bien que sa première tentative se termine dans le chagrin, Tharnariun reste déterminé à découvrir la véritable nature du mal qui frappe la forêt."}},faq={{q="Que fait l’Espoir de Tharnariun ?",a="L’Espoir de Tharnariun apaise un ours des chardons enragé pour un temps. Posé sur le sol de la forêt, il projette un halo lumineux qui permet à un voyageur de mener paisiblement l’ours jusqu’à Tharnariun Soigneflore.",al={"utilisation de l’espoir de tharnariun","comment fonctionne le piège","qu’est-ce que ce piège"}},{q="Pourquoi Tharnariun veut-il capturer un ours vivant ?",a="Tharnariun pense qu’il est possible de guérir la maladie qui frappe la faune de Sombrivage plutôt que de répondre par un massacre. Il lui faut un ours vivant pour tester ses remèdes purificateurs.",al={"pourquoi capturer un ours des chardons","pourquoi capturer un ours enragé","que veut tharnariun"}},{q="Peut-on obtenir un autre piège si on le perd ?",a="Oui. Tharnariun dit que son espoir est éternel. Si le piège se déclenche pour rien ou se perd dans la nature, retournez le voir pour en obtenir un autre.",al={"espoir de tharnariun perdu","piège inefficace","piège disparu"}},{q="Qu’arrive-t-il à l’ours une fois qu’on l’a ramené ?",a="Lorsque l’ours arrive auprès de Tharnariun, celui-ci lance un sort de guérison pour purger la corruption. La maladie terrasse la bête, qui meurt en quelques instants.",al={"l’ours survit-il","tharnariun peut-il guérir l’ours","l’ours meurt chez tharnariun"}}},fx={["820181a1"]={q="Qu'est-ce que l'Espoir de Tharnariun ?",a="L'Espoir de Tharnariun est un piège enchanté conçu par Tharnariun Soigneflore. Lorsqu'il est posé au sol, il émet une lumière apaisante capable de pacifier temporairement les ours chardon enragés et affligés qui errent à Sombrivage. L'enchantement apaisant rend la bête frénétique douce et disposée à vous suivre jusqu'à Auberdine.",al={"qu'est-ce que l'espoir de tharnariun","objet espoir de tharnariun","piège de tharnariun"}},["88ba9e19"]={q="D'où vient l'Espoir de Tharnariun, et qui l'a créé ?",a="Le piège a été fabriqué et enchanté par Tharnariun Soigneflore, un naturaliste elfe de la nuit stationné à Sombrivage. Horrifié par la mystérieuse maladie poussant la faune de la forêt à la folie, il a façonné cet appareil en utilisant une magie douce pour soumettre les bêtes infectées sans leur causer davantage de tort.",al={"qui a créé l'espoir de tharnariun","origine de l'espoir de tharnariun","créateur du piège de tharnariun"}},c80e933b={q="Pourquoi quelqu'un souhaite-t-il l'Espoir de Tharnariun ?",a="Tharnariun a besoin que le piège soit utilisé pour capturer un ours chardon enragé vivant afin qu'il puisse étudier la corruption qui ravage Sombrivage. Une chasse ordinaire ne ferait que tuer la bête, mais ce piège pacifie l'animal assez longtemps pour que vous puissiez le mener en toute sécurité jusqu'à lui dans l'espoir de découvrir un remède.",al={"pourquoi utiliser l'espoir de tharnariun","pourquoi avoir besoin du piège de tharnariun","but de l'espoir de tharnariun"}}},fp="17,135,14.402.0,18.413.1,31.184.0,46.168.0,40.122.0,49.144.1"}
P.entries["item:the-book-of-ur"] = {n="Le Livre d'Ur",s="Au Donjon d'Ombrecroc, le Livre d'Ur intéresse les érudits réprouvés. L'archimage Arugal l'a pris après la mort d'Ur. Le mage de Dalaran a écrit sur d'étranges êtres venus d'autres plans.",h="Au Donjon d'Ombrecroc, le Livre d'Ur intéresse les érudits réprouvés.",kw={"l'apothicarium","arugal","livre d'ur","dalaran","gardien bel'dugur","donjon d'ombrecroc","forêt des pins-argentés","ur"},ang={["class:Mage"]="En tant que mage, vous voyez dans les écrits d'Ur jusqu'où les érudits de Dalaran étudiaient d'autres royaumes, et le prix mortel de leur savoir interdit quand Arugal en fit mauvais usage.",["race:Undead"]="En tant que mort-vivant, vous savez que mettre la main sur les travaux d'Ur aiderait les érudits de la Dame noire à l'Apothicarium. Les recherches d'un prudent sorcier humain pourraient devenir une source de pouvoir pour les Réprouvés."},sec={{t="Le mage de Dalaran",b="Ur était un mage de Dalaran qui étudiait d'autres plans et leurs créatures. Avant l'arrivée du Fléau, le Kirin Tor connaissait bien ses travaux. Il voulait comprendre la magie au-delà de ce monde, mais consignait ses découvertes au lieu de franchir imprudemment le voile. La prudence et la retenue guidaient ses recherches. Quand le Fléau attaqua Dalaran, ni sa magie ni sa prudence ne purent le sauver."},{t="Les ambitions réprouvées",b="Le Livre d'Ur contient les écrits que l'archimage Arugal a pris après la mort d'Ur. Arugal s'en est servi pour invoquer des worgens dans la Forêt des Pins-Argentés. Le livre repose désormais sur une étagère du Donjon d'Ombrecroc. Le Gardien Bel'dugur, de l'Apothicarium de Fossoyeuse, en a entendu parler et veut les travaux d'Ur. Les Réprouvés n'ont pas la retenue d'Ur. Ils emploieront une magie dangereuse pour survivre et conquérir."}},faq={{q="Qui était Ur ?",a="Ur était un mage humain de Dalaran, connu avant la troisième guerre pour étudier d'autres dimensions et leurs créatures. Il refusait de les invoquer, par crainte du danger qu'elles représentaient.",al={"qui a écrit le livre d'ur","ur mage de dalaran"}},{q="Où se trouve le Livre d'Ur ?",a="Le Livre d'Ur repose sur une étagère du Donjon d'Ombrecroc, dans la Forêt des Pins-Argentés, dans la salle où vit le grand fauve Fenrus.",al={"emplacement du livre d'ur","où se trouve le livre d'ur"}},{q="Pourquoi le Gardien Bel'dugur veut-il le livre ?",a="Le Gardien Bel'dugur rassemble les écrits d'Ur pour les intéressés de Fossoyeuse. Les Réprouvés pensent que la conscience d'Ur bridait son pouvoir et cherchent à exploiter ses recherches sans limites éthiques pour se renforcer.",al={"gardien bel'dugur livre d'ur","pourquoi fossoyeuse veut le livre"}},{q="Comment le livre a-t-il fini au Donjon d'Ombrecroc ?",a="Après la mort d'Ur lors de la chute de Dalaran, l'archimage Arugal s'est emparé de ses recherches. Cherchant à se défendre contre le Fléau, Arugal a emporté les notes dans la Forêt des Pins-Argentés et s'est servi des théories d'Ur pour invoquer des worgens en Azeroth.",al={"arugal et le livre d'ur","comment arugal a obtenu le livre"}}},fx={["62a01830"]={q="Qu'est-ce que Le Livre d'Ur ?",a="Le Livre d'Ur est un ouvrage érudit contenant les recherches ésotériques d'Ur, un mage accompli de Dalaran. Il détaille ses études approfondies sur d'autres mondes et des phénomènes arcaniques dangereux, des connaissances qui se sont révélées si puissantes que l'archimage Arugal a plus tard utilisé les écrits d'Ur pour invoquer les monstrueux worgens dans la Forêt des Pins-Argentés.",al={"qu'est-ce que le livre d'ur","connaissances sur le livre d'ur"}},["905bb2c4"]={q="D'où vient Le Livre d'Ur, et qui l'a créé ?",a="Le livre a été rédigé dans le royaume magique de Dalaran par le mage Ur avant la destruction de la ville par le Fléau. Ur y a consigné ses théories arcaniques et ses explorations d'autres dimensions, bien que son travail ait été abandonné après sa mort lors de la chute de Dalaran.",al={"qui a écrit le livre d'ur","origine du livre d'ur","d'où vient le livre d'ur"}}},fp="14,174,19.378.0,17.359.1,11.167.0,32.128.0,40.215.0,43.216.0"}
P.entries["item:the-collector-s-schedule"] = {n="Plan de route du collecteur",s="Près du Champ de potirons des Brackwell, le Plan de route du collecteur signale le passage de cargaisons d’or illicites dans la Forêt d’Elwynn. Des gnolls transportent son itinéraire manuscrit, et le Maréchal Dughan reconnaît le nom qui y figure.",h="Près du Champ de potirons des Brackwell, le Plan de route du collecteur signale le passage de cargaisons d’or...",kw={"brackwell","collecteur","dughan","elwynn","or","comté-de-l’or","mines","plan"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez constater à quel point Hurlevent contrôle mal son propre territoire lorsque des équipes non autorisées s’emparent de ses ressources près de la capitale.",["profession:Mining"]="En tant que mineur, vous pouvez constater que les mines d’Elwynn ne sont pas à l’abandon. De riches filons d’or sont exploités et évacués."},sec={{t="Or volé et cargaisons secrètes",b="L’or quitte toujours les mines d’Elwynn selon un calendrier, bien que Hurlevent ne les exploite officiellement plus depuis des mois. Le banditisme et les incursions de créatures ont chassé les mineurs. L’itinéraire indique les jours et les heures où un personnage nommé The Collector reçoit chaque cargaison.\n\nLa piste mène à un camp près du Champ de potirons des Brackwell, dans l’est de la Forêt d’Elwynn. Le Maréchal Dughan reconnaît le nom du collecteur lorsqu’il voit le plan. On ignore toujours qui paie pour l’or volé."}},faq={{q="Qu’est-ce que le Plan de route du collecteur ?",a="Le Plan de route du collecteur indique quand des cargaisons d’or quittent les mines abandonnées de la Forêt d’Elwynn à destination d’un agent nommé The Collector.",al={"qu’est-ce que cette note","objet plan du collecteur","plan de l’or"}},{q="D’où vient le plan ?",a="Des gnolls transportent le plan le long des berges et sur les collines de la Forêt d’Elwynn. Ils l’ont peut-être pris à un courrier ou participent peut-être au transport de l’or.",al={"qui laisse tomber le plan","où trouver le plan"}},{q="Qui est The Collector ?",a="The Collector est un agent posté près du Champ de potirons des Brackwell, dans l’est de la Forêt d’Elwynn. Le Maréchal Dughan reconnaît son nom, mais ignore qui l’emploie.",al={"qui est the collector","identité du collecteur"}},{q="Pourquoi ce plan inquiète-t-il le Maréchal Dughan ?",a="Le Maréchal Dughan est inquiet, car Hurlevent n’a plus de mineurs officiels dans les mines d’Elwynn depuis des mois, et pourtant d’importantes cargaisons d’or en sortent toujours. Ces cargaisons révèlent une exploitation minière illicite organisée au sein du royaume.",al={"pourquoi dughan s’en soucie","or des mines d’elwynn"}}},fp="24,216,32.467.0,33.129.0,33.150.0,21.170.0,47.231.0"}
P.entries["item:the-embalmer-s-heart"] = {n="Cœur de l'embaumeur",s="Dans le Bois de la Pénombre, le cœur d’Eliza bat encore dans son cadavre enterré. L’Embalmer a placé son propre cœur dans la poitrine de sa défunte épouse par magie noire, et il est devenu le pilier de son pouvoir.",h="Dans le Bois de la Pénombre, le cœur d’Eliza bat encore dans son cadavre enterré.",kw={"bride of the embalmer","sombre-comté","bois de la pénombre","eliza","ello bouclenoire","cœur de l’embaumeur","l’embaumeur"},ang={["class:Warlock"]="En tant que démoniste, vous pouvez reconnaître comment le cœur ancre la non-mort nécromantique par le façonnage de la chair et le lien de l’âme.",["race:Human"]="En tant qu’humain, vous entendez les habitants accablés du Bois de la Pénombre murmurer sur la chute tragique du gentil alchimiste."},sec={{t="Un amour qui défia la mort",b="Sombre-Comté se souvient de l’Embalmer comme d’un alchimiste doux. Quand son épouse Eliza mourut, le chagrin lui fit perdre la raison. Il eut recours à une magie impie, s’arracha le cœur et le plaça dans sa poitrine sans vie. La magie ranima son cadavre et le rendit mort-vivant. Mais Eliza revint sous la forme d’une créature vorace, avide de chair humaine vivante. Horrifié par son acte, l’alchimiste l’enterra de nouveau."},{t="Un rempart pour Sombre-Comté",b="Le cœur de l’Embalmer bat toujours dans la tombe d’Eliza et entretient son pouvoir obscur. Le maire Ello Bouclenoire pense que Sombre-Comté peut affaiblir la sorcellerie de l’Embalmer en détruisant sa promise réanimée et en s’emparant du cœur. S’ils le récupèrent tant qu’il bat encore, les dirigeants de la ville espèrent retourner son essence contre le nécromancien. Ils espèrent qu’elle deviendra un rempart contre ses terreurs."}},faq={{q="Pourquoi Eliza a-t-elle le cœur de l’Embalmer ?",a="Le chagrin poussa l’Embalmer à placer son propre cœur battant dans le cadavre d’Eliza par magie interdite. Le rituel la ramena à la non-mort, mais la rendit avide de chair humaine.",al={"pourquoi eliza a le cœur","cœur de l’embaumeur dans eliza","qui a mis le cœur dans eliza"}},{q="Pourquoi le maire Bouclenoire veut-il que le cœur soit rapporté à Sombre-Comté ?",a="Le maire Ello Bouclenoire espère que la magie noire du cœur affaiblira l’Embalmer et deviendra un rempart protégeant Sombre-Comté.",al={"pourquoi ello veut le cœur","plan de bouclenoire pour le cœur","que fait sombre-comté du cœur"}},{q="Comment l’Embalmer survit-il sans son cœur ?",a="L’Embalmer a lié sa force vitale et son pouvoir au cœur par la sorcellerie noire. Il bat toujours dans les restes enterrés de son épouse, tandis que l’Embalmer survit sans lui.",al={"l’embaumeur est-il vivant","comment l’embaumeur survit sans cœur"}},{q="Où peut-on trouver le cœur ?",a="Le cœur se trouve dans le corps d’Eliza, enterré dans une tombe cachée du Bois de la Pénombre. On ne peut s’en emparer qu’en affrontant et en vainquant la promise vorace, ramenée à la non-mort.",al={"où se trouve le cœur de l’embaumeur","emplacement de la tombe d’eliza","comment obtenir le cœur de l’embaumeur"}}},fx={cac9cdef={q="Qu'est-ce que le Cœur de l'embaumeur ?",a="Il s'agit du cœur battant, maintenu par magie, de l'alchimiste renégat connu sous le nom d'Embalmer. Poussé à la folie par le chagrin suite à la mort de sa femme, Eliza, il s'est arraché le cœur et l'a placé dans son cadavre pour la ramener à la vie. Même séparé de sa poitrine, le cœur sert de réceptacle et de conduit à son pouvoir nécromantique, maintenant à la fois l'état de morte-vivante maudite d'Eliza et sa propre vitalité impie.",al={"qu'est-ce que le cœur de l'embaumeur","connaissances sur le cœur de l'embaumeur","le cœur de l'embaumeur"}}},fp="20,173,24.367.0,22.376.1,41.169.0,66.117.0,48.156.0,29.163.0"}
P.entries["item:the-first-troll-legend"] = {n="The First Troll Legend"}
P.entries["item:the-fourth-troll-legend"] = {n="The Fourth Troll Legend",s="Aux Ruines de Zul'Kunda, la Fourth Troll Legend entraîne les recherches de Frère Nimetz dans les vieilles pierres de la Vallée de Strangleronce. Ses inscriptions pourraient aider à comprendre la corruption du Colonel Kurzen.",h="Aux Ruines de Zul'Kunda, la Fourth Troll Legend entraîne les recherches de Frère Nimetz dans les vieilles...",kw={"frère nimetz","colonel kurzen","emperor's tomb","quatrième légende troll","vallée de strangleronce","tablette troll","zul'kunda"},ang={["faction:Alliance"]="En tant que voyageur de l'Alliance, vous pouvez aider Frère Nimetz à enquêter sur la chute du Colonel Kurzen en lui rapportant les inscriptions de Zul'Kunda."},sec={{t="Une tablette à Zul'Kunda",b="Parmi les ruines du nord de Zul'Kunda, Emperor's Tomb porte la Fourth Troll Legend. Frère Nimetz en cherche les inscriptions, ainsi que celles de trois autres légendes trolles. Il espère que ces mots anciens éclaireront la chute du Colonel Kurzen et vous a envoyé les rapporter pour les étudier."}},faq={{q="Qu'est-ce que la Fourth Troll Legend ?",a="La Fourth Troll Legend est un ensemble d'inscriptions sur une tablette de pierre appelée Emperor's Tomb, dans les Ruines de Zul'Kunda.",al={"quatrième légende troll","quatrième tablette","légende troll numéro quatre"}},{q="Où trouver la Fourth Troll Legend ?",a="Emperor's Tomb se trouve parmi les Ruines de Zul'Kunda, au nord-ouest de la Vallée de Strangleronce.",al={"emplacement de la quatrième légende","où se trouve emperor's tomb","tablette de zul'kunda"}},{q="Qui veut la Fourth Troll Legend ?",a="Frère Nimetz, au Camp rebelle, veut les inscriptions de la Fourth Troll Legend afin de les étudier.",al={"qui veut la quatrième légende","tablette de frère nimetz","légendes de nimetz"}},{q="Pourquoi Frère Nimetz étudie-t-il les légendes trolles ?",a="Frère Nimetz espère que les légendes trolles révéleront la cause de la corruption du Colonel Kurzen.",al={"mystère de kurzen","pourquoi les légendes trolles","corruption de kurzen"}},{q="Quelles sont les autres légendes trolles ?",a="Les autres tablettes portent les First, Second et Third Troll Legends. Elles se trouvent dans les Ruines de Bal'lal, au Récif infâme et dans les Ruines de Zul'Kunda, en Vallée de Strangleronce.",al={"première deuxième troisième légendes","autres tablettes","les quatre légendes"}}},fp="23,177,21.271.0,32.115.0,41.90.0,34.102.0,45.90.0,33.150.0"}
P.entries["item:the-general-s-response"] = {n="La réponse du général",s="Depuis Hurlevent, le Général Marcus Jonathan répond à l’appel à l’aide de Comté-du-Lac, alors que Les Carmines sont menacées. Sa dépêche accuse réception de l’appel du Magistrat Salomon face aux orcs de Blackrock et aux gnolls, mais n’envoie aucun renfort immédiat depuis Hurlevent.",h="Depuis Hurlevent, le Général Marcus Jonathan répond à l’appel à l’aide de Comté-du-Lac, alors que Les...",kw={"général marcus jonathan","comté-du-lac","magistrat salomon","un message pour stormwind","les carmines","hurlevent","la réponse du général"},ang={["faction:Alliance"]="La réponse de Hurlevent révèle les tensions qui pèsent sur la Grand Alliance. Comté-du-Lac saigne tandis que la cour semble étrangement sourde à sa détresse.",["race:Human"]="Pour les humains des royaumes du sud, cette réponse tardive révèle un fossé grandissant entre ceux qui luttent pour survivre dans les provinces et la noblesse isolée au Donjon de Hurlevent."},sec={{t="Une impasse diplomatique",b="Le Magistrat Salomon demande des troupes à Hurlevent pour défendre Les Carmines contre les clans orcs de Blackrock et les bandes de gnolls qui se rassemblent. Le Général Marcus Jonathan répond qu’il a transmis l’appel au trône, mais qu’aucun soldat ne viendra pour l’instant. Il ordonne que la lettre soit renvoyée à Comté-du-Lac. Salomon est troublé par ce retard et soupçonne que quelque chose ne va pas chez les dirigeants de Hurlevent."}},faq={{q="Que dit La réponse du général ?",a="Le Général Marcus Jonathan déplore les morts et affirme qu’il informera le roi de la détresse de Comté-du-Lac. Il espère pouvoir envoyer des renforts et confie que Sa Majesté se fait rare et agit étrangement.",al={"contenu de la lettre","que dit la lettre","lettre du général"}},{q="Pourquoi le Général Marcus Jonathan ne peut-il pas envoyer de troupes à Comté-du-Lac ?",a="Le Général Marcus Jonathan attend la réponse du roi avant de promettre des renforts. En confidence, il dit à Solomon que Sa Majesté se fait rare et agit étrangement.",al={"pourquoi aucun renfort","pourquoi hurlevent n’aide pas comté-du-lac","pourquoi aucune aide"}},{q="Comment le Magistrat Salomon réagit-il à la lettre ?",a="Le Magistrat Salomon est profondément troublé par la dépêche. Le retard de Hurlevent n’a aucun sens alors que Comté-du-Lac fait face à un tel danger, et il craint que cette négligence ne révèle des problèmes plus graves dans le royaume.",al={"réaction de solomon","que pense solomon","réponse de solomon"}}},fx={["3ebc4cbb"]={q="Qu'est-ce que La réponse du général ?",a="C'est une dépêche officielle scellée écrite par le général Marcus Jonathan, commandant de la garde de la cité d'Hurlevent, adressée au magistrat Salomon à Comté-du-Lac. Transportée par des messagers entre la capitale et Comté-du-Lac, la missive contient la réponse formelle du haut commandement concernant l'appel désespéré de Comté-du-Lac pour obtenir des renforts royaux.",al={"qu'est-ce que la réponse du général","objet la réponse du général","qu'est-ce que cette lettre"}},["174955dc"]={q="D'où vient La réponse du général, et qui l'a créée ?",a="La lettre est rédigée directement par le général Marcus Jonathan au sein d'Hurlevent. Après avoir reçu la pétition urgente du magistrat Salomon à la Vallée des héros, Jonathan rédige cette réponse formelle en attendant des nouvelles de la cour royale, et vous confie le soin de la rapporter au magistrat à Comté-du-Lac.",al={"qui a écrit la réponse du général","d'où vient la réponse du général","qui a envoyé la réponse du général"}},d0ef00e9={q="Pourquoi quelqu'un voudrait-il La réponse du général ?",a="Le magistrat Salomon attend anxieusement cette dépêche pour savoir si Hurlevent déploiera des soldats pour sauver Comté-du-Lac des orcs du Rochenoire et des gnolls. La lui remettre permet aux dirigeants de la ville assiégée de savoir clairement quelle aide le royaume peut, ou ne peut pas, fournir.",al={"pourquoi salomon veut-il la lettre","qui veut la réponse du général","pourquoi livrer la réponse du général"}}},fp="22,247,21.365.0,42.193.0,59.176.0,48.190.0"}
P.entries["item:the-legacy-heart"] = {n="The Legacy Heart",s="Une magie noire s’accroche au Legacy Heart, une relique recherchée avec deux autres objets de pouvoir. Gerrig Poigne-d'os, à Forgefer, le veut pour une raison liée au Sommaire de Yagyin.",h="Une magie noire s’accroche au Legacy Heart, une relique recherchée avec deux autres objets de pouvoir.",kw={"bonegrip's note","magie noire","gerrig poigne-d'os","main de dagun","legacy heart","etoile de xil'yeh","sommaire de yagyin"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous pouvez apporter le Legacy Heart et deux autres reliques à Gerrig Poigne-d'os, à Forgefer, en échange du Sommaire de Yagyin."},sec={{t="Une relique de pouvoir",b="Gerrig Poigne-d'os demande le Legacy Heart parmi trois reliques qu’il a inscrites sur Bonegrip's Note. Il les échangera contre le Sommaire, mais tait leurs noms. La sombre enchantement du Cœur lui a valu une sinistre réputation."}},faq={{q="Qu’est-ce que le Legacy Heart ?",a="Le Legacy Heart est une relique de pouvoir recherchée par Gerrig Poigne-d'os en échange du Sommaire de Yagyin.",al={"legacy heart","relique du cœur","cœur de magie noire"}},{q="Qui veut le Legacy Heart ?",a="Gerrig Poigne-d'os, à Forgefer, demande le Legacy Heart et deux autres reliques.",al={"qui veut le cœur","cœur de gerrig poigne-d'os","relique de poigne-d'os"}},{q="Pourquoi Gerrig le veut-il ?",a="Gerrig a besoin du Legacy Heart et de deux autres reliques avant de céder le Sommaire de Yagyin.",al={"pourquoi poigne-d'os le veut","pouvoir du cœur","raison de gerrig"}},{q="Que serait capable de faire le Cœur ?",a="On dit que la magie noire confère l’immortalité à celui qui détient le Legacy Heart ; son propriétaire actuel porte le titre de the Undying.",al={"pouvoir du cœur","magie du legacy heart","cœur qui ne meurt jamais"}},{q="Quelles autres reliques Gerrig recherche-t-il ?",a="Gerrig demande l'Etoile de Xil'yeh, la Main de Dagun et le Legacy Heart.",al={"autres reliques","étoile main cœur","liste de poigne-d'os"}}},fp="16,166,16.236.0,25.95.0,27.76.0,24.91.0,29.113.2,35.76.0"}
P.entries["item:the-lich-s-spellbook"] = {n="Le grimoire de la liche",s="Sur l’île du lac Étincelant, Bethor Glacéclat cherche un grimoire gardé par une liche libre de sa volonté. Il espère que ses pages révéleront le savoir-faire de la liche et qui elle était de son vivant.",h="Sur l’île du lac Étincelant, Bethor Glacéclat cherche un grimoire gardé par une liche libre de sa volonté.",kw={"bethor glacéclat","lac etincelant","gunther arcanus","liche","nécromancie","grimoire","clairières de tirisfal","fossoyeuse"},ang={["class:Mage"]="En tant que mage, vous pouvez voir comment le grimoire associe la magie de Dalaran à la nécromancie noire. Son auteur a considérablement développé son art après être devenu mort-vivant.",["race:Undead"]="En tant que mort-vivant, vous savez que certains de ceux qui ont échappé au contrôle du roi-liche n’ont pas rejoint les Réprouvés immédiatement. Les survivants morts-vivants Voleurs des Clairières de Tirisfal se méfient encore les uns des autres."},sec={{t="Les grimoires d’un maître reclus",b="Une liche libre de sa volonté veille sur une île du lac Étincelant, entourée de serviteurs squelettiques. Elle se méfie du monde extérieur et prend les autres morts-vivants pour des esclaves du Fléau. Elle ordonne donc à ses gardiens de tuer quiconque s’approche.\n\nBethor Glacéclat cherche des nécromanciens doués pour les Réprouvés, sous les ordres de la reine Sylvanas Coursevent. Il envoie un émissaire dans le camp de l’île pour s’emparer du grimoire de la liche. Bethor espère que ses pages révéleront la puissance du maître et son identité, avant que la mort ne s’empare de Lordaeron."},{t="Percer le mystère de Gunther Arcanus",b="Le grimoire récupéré révèle que la liche recluse se nomme Gunther Arcanus. C’était le vieil ami de Bethor Glacéclat et son compagnon d’armes avant la Troisième guerre. De son vivant, Gunther était un prodige de la nécromancie. Ses écrits montrent que ses pouvoirs se sont accrus après sa mort.\n\nBethor sait que Gunther pourrait devenir un maître précieux des arts sombres pour les Réprouvés. D’abord, quelqu’un devra convaincre cette liche méfiante que les Réprouvés ont échappé à l’emprise du roi-liche."}},faq={{q="Où trouver le grimoire de la liche ?",a="Le grimoire se trouve dans un conteneur nommé Gunther's Books, dans le campement de l’île centrale du lac Étincelant, au nord des Clairières de Tirisfal.",al={"où se trouve le livre","lieu du grimoire","gunther's books"}},{q="À qui appartient ce grimoire ?",a="Le livre appartient à une liche libre de sa volonté et recluse sur une île du lac Étincelant. Bethor Glacéclat espère que ses pages révéleront l’identité et le savoir-faire de la liche.",al={"à qui appartient ce livre","identité de la liche","qui a écrit le grimoire"}},{q="Pourquoi Bethor Glacéclat veut-il ce livre ?",a="Bethor Glacéclat veut découvrir l’identité de la liche et évaluer son savoir-faire en nécromancie. Il espère la recruter pour Dame Sylvanas et les Réprouvés.",al={"pourquoi prendre le livre","raison de la quête de bethor","pourquoi fossoyeuse le veut"}},{q="Pourquoi la liche attaque-t-elle les visiteurs de son île ?",a="La liche croit que les autres morts-vivants des environs sont toujours des esclaves du Fléau sous contrôle mental. Elle ordonne à ses serviteurs d’attaquer quiconque approche de son refuge insulaire.",al={"pourquoi gunther est hostile","pourquoi les serviteurs attaquent","hostilité au lac étincelant"}},{q="Que Bethor espère-t-il apprendre au sujet de l’auteur ?",a="Bethor espère découvrir qui était cette liche isolée de son vivant et si ses connaissances en nécromancie pourraient aider les Réprouvés.",al={"ce que bethor apprendra","étude de l’auteur liche","étude du grimoire par bethor"}}},fx={["44ee6981"]={q="D'où vient le grimoire de la liche, et qui l'a créé ?",a="Le grimoire appartient à la liche recluse et dotée de libre arbitre qui demeure sur l'île du Lac Etincelant. Elle a elle-même rédigé et enrichi ce tome, remplissant ses pages lumineuses de ses arts nécromantiques, de son vivant comme après sa transformation en liche. Bethor Glacéclat le convoite pour découvrir qui était cette liche.",al={"qui a créé le grimoire de la liche","origine du grimoire de la liche","d'où vient le grimoire de la liche"}}},fp="20,161,26.483.0,25.432.1,36.140.0,24.154.1,39.145.0,48.149.0,48.117.1"}
P.entries["item:the-second-troll-legend"] = {n="The Second Troll Legend"}
P.entries["item:the-state-of-lakeshire"] = {n="La situation de Comté-du-lac",s="Les défenseurs de Comté-du-Lac subissent des attaques, et le Magistrat Salomon demande l’aide de Hurlevent. Son rapport exhorte le Général Marcus Jonathan à envoyer des renforts royaux pour contrer la crise dans les Carmines.",h="Les défenseurs de Comté-du-Lac subissent des attaques, et le Magistrat Salomon demande l’aide de Hurlevent.",kw={"dépêche","magistrat salomon","marcus jonathan","les carmines","renforts","rapport","situation de comté-du-lac","hurlevent"},ang={["faction:Alliance"]="Pour l’Alliance, ce rapport montre à quel point les colonies isolées sont exposées et comment les retards politiques dans la capitale freinent l’aide militaire.",["race:Human"]="En tant qu’humain du royaume, transporter ce rapport montre comment les gens du peuple des Carmines perdent leurs liens avec la couronne lointaine de Hurlevent."},sec={{t="Un appel à l’aide",b="Le Magistrat Salomon écrit que des attaques menacent Comté-du-Lac. Des orcs Rochenoire et des gnolls font pression sur la ville, et ses défenseurs ne peuvent pas tenir les frontières indéfiniment. Des courriers transportent son rapport vers l’ouest, le long de la route menant à la Forêt d’Elwynn. Salomon demande à l’armée de Hurlevent de protéger les confins orientaux du royaume."},{t="Lourdeurs administratives et impasse",b="Aux portes de Hurlevent, le Général Marcus Jonathan reçoit le rapport de Salomon. Il respecte le rang du magistrat et comprend le danger, mais ne peut pas déplacer l’armée seul. Les déploiements nécessitent l’accord de la couronne. L’appel de Comté-du-Lac doit donc attendre un conseil avec le jeune roi et le régent Bolvar Fordragon."}},faq={{q="Qu’est-ce que La situation de Comté-du-lac ?",a="Le rapport officiel du Magistrat Salomon décrit le danger militaire qui menace Comté-du-Lac et demande à Hurlevent des renforts de troupes.",al={"document sur la situation de comté-du-lac","qu’est-ce que ce rapport","message de salomon"}},{q="Qui est censé recevoir ce rapport ?",a="Le Général Marcus Jonathan est censé recevoir le rapport. Il commande la garde de la ville de Hurlevent et les forces royales, et se trouve aux portes de Hurlevent.",al={"qui reçoit le rapport","à qui remettre le rapport","rapport de marcus jonathan"}},{q="Pourquoi Comté-du-Lac a-t-il besoin de renforts royaux ?",a="Les orcs Rochenoire, les gnolls Shadowhide et les murlocs de la région assiègent sans cesse Comté-du-Lac, submergeant sa garde municipale. La colonie a besoin de renforts royaux.",al={"pourquoi comté-du-lac est-il en danger","qu’est-ce qui menace les carmines"}},{q="Le Général Marcus Jonathan envoie-t-il de l’aide immédiatement ?",a="Non. Le Général Marcus Jonathan reconnaît la gravité de la crise, mais il lui faut l’approbation officielle du roi pour déployer l’armée. La demande doit d’abord être examinée par la couronne.",al={"hurlevent apporte-t-elle son aide","jonathan envoie-t-il des troupes"}}},fx={["629511cc"]={q="D'où vient La situation de Comté-du-lac, et qui l'a rédigée ?",a="Le magistrat Salomon, dirigeant civil et juge de Comté-du-Lac, a rédigé ce rapport critique. Face à la pression incessante des forces hostiles entourant la ville, Salomon a rédigé lui-même la dépêche pour détailler formellement la situation périlleuse de Comté-du-Lac et demander au haut commandement d'Hurlevent une aide militaire immédiate.",al={"qui a écrit la situation de comté-du-lac","qui a créé la situation de comté-du-lac","auteur de la situation de comté-du-lac"}},["09d61feb"]={q="Pourquoi La situation de Comté-du-lac est-elle si urgente ?",a="Comté-du-Lac est sous siège constant, et le magistrat Salomon sait que la ville ne peut pas tenir seule sans renforts royaux. Le général Marcus Jonathan a besoin de ce compte-rendu officiel pour justifier l'envoi d'éléments de l'armée d'Hurlevent et pour présenter la situation désespérée de Comté-du-Lac directement au Roi et au généralissime Bolvar Fordragon.",al={"pourquoi la situation de comté-du-lac est-elle nécessaire","pourquoi livrer la situation de comté-du-lac","pourquoi marcus jonathan veut-il la situation de comté-du-lac"}}},fp="22,188,13.289.0,24.301.0,31.130.0,41.150.0,45.150.0,51.161.0"}
P.entries["item:the-third-troll-legend"] = {n="The Third Troll Legend",s="Aux Ruines de Zul'Kunda, Third Troll Legend est l'une des quatre transcriptions de tablettes que cherche Frère Nimetz. Il espère que ces anciennes inscriptions éclaireront la corruption du colonel Kurzen.",h="Aux Ruines de Zul'Kunda, Third Troll Legend est l'une des quatre transcriptions de tablettes que cherche...",kw={"frère nimetz","colonel kurzen","fall of gurubashi","mystère de kurzen","troisième légende troll","tablette troll","zul'kunda"},ang={["faction:Alliance"]="Frère Nimetz s'inquiète du colonel Kurzen, un officier de l'Alliance dont la corruption l'a alarmé. Les légendes pourraient expliquer ce qui est arrivé à Kurzen."},sec={{t="Une pierre à Zul'Kunda",b="Parmi les salles sans toit des Ruines de Zul'Kunda, Third Troll Legend figure sur une tablette de pierre appelée Fall of Gurubashi. Frère Nimetz, au Camp rebelle, recherche ces inscriptions. Il étudie quatre légendes trolls pour déterminer si elles ont un lien avec la corruption du colonel Kurzen."}},faq={{q="Qu'est-ce que Third Troll Legend ?",a="Third Troll Legend est une transcription des inscriptions de la tablette Fall of Gurubashi, aux Ruines de Zul'Kunda.",al={"troisième légende troll","tablette troll","légende de zul'kunda"}},{q="Où se trouve la tablette Fall of Gurubashi ?",a="La tablette Fall of Gurubashi se trouve dans la salle sud-ouest des Ruines de Zul'Kunda, sur le plateau.",al={"emplacement de fall of gurubashi","où se trouve la troisième tablette","tablette de zul'kunda"}},{q="Qui cherche Third Troll Legend ?",a="Frère Nimetz, au Camp rebelle, cherche les quatre légendes trolls afin d'étudier leur possible lien avec la corruption du colonel Kurzen.",al={"qui cherche la tablette","légende de frère nimetz","mystère de kurzen"}},{q="Pourquoi Frère Nimetz rassemble-t-il des légendes trolls ?",a="Frère Nimetz soupçonne la magie troll d'avoir un lien avec la corruption du colonel Kurzen. Il espère que les légendes l'aideront dans son enquête.",al={"pourquoi nimetz cherche des légendes","magie troll de kurzen","pourquoi le mystère de kurzen"}}},fp="22,182,18.270.0,31.114.0,38.99.0,33.128.0,47.138.0"}
P.entries["item:theramore-medal"] = {n="Médaille de Theramore",s="Au Fort de Guet-du-Nord, la Médaille de Theramore distingue les marins et les officiers qui défendent l’avant-poste de La Côte des marchands. Son emblème identifie la garnison de l’Alliance.",h="Au Fort de Guet-du-Nord, la Médaille de Theramore distingue les marins et les officiers qui défendent...",kw={"les tarides","capitaine fairmount","la côte des marchands","fort de guet-du-nord","thalo'thas brillesoleil","médaille de theramore"},ang={["faction:Alliance"]="Pour les fidèles de l’Alliance, les médailles de Theramore récoltées comme primes de sang montrent à quel point le Fort de Guet-du-Nord est devenu isolé et agressif sur la frontière de Kalimdor.",["faction:Horde"]="Pour les aventuriers de la Horde, ces médailles prouvent que la présence militaire de l’Alliance grandit sur les côtes des Tarides."},sec={{t="Insignes de Guet-du-Nord",b="Les marins, tireurs d’élite, commandos et officiers en poste au Fort de Guet-du-Nord portent des médailles frappées du symbole de Theramore. Ils sont loyaux envers le royaume de Dame Jaina Portvaillant. Pour les soldats humains sur les falaises qui surplombent Les Tarides, ces médailles attestent la légitimité de leur service et de l’autorité de Theramore.\n\nD’autres voient ces insignes comme des trophées pris à une garnison étrangère trop zélée. Le Fort de Guet-du-Nord considère chaque navire approchant de la côte comme une menace mortelle."},{t="Vengeance de corsaire",b="Les batteries de canons du Fort de Guet-du-Nord menacent les navires le long de La Côte des marchands, bombardant souvent corsaires et navires marchands sans distinction. Après avoir perdu des navires sous leurs tirs, le corsaire de Cabestan, le Capitaine Thalo'thas Brillesoleil, réclame les médailles.\n\nIl veut la preuve que les troupes de Guet-du-Nord, trop promptes à tirer, ont payé de leur sang pour avoir coulé ses navires, et que les soldats responsables ont été tués en représailles."}},faq={{q="Qu’est-ce qu’une Médaille de Theramore ?",a="Le symbole de Theramore sur la médaille identifie son porteur comme un marin ou un officier en service dans la garnison de l’Alliance au Fort de Guet-du-Nord, dans Les Tarides.",al={"médaille de theramore","que sont les médailles de theramore","médaille de guet-du-nord"}},{q="Qui porte ces médailles ?",a="Les marins, tireurs d’élite, matelots, commandos, artilleurs chevronnés et officiers en poste au Fort de Guet-du-Nord portent ces médailles le long de La Côte des marchands.",al={"qui possède des médailles de theramore","qui donne des médailles de theramore","d’où viennent les médailles de theramore"}},{q="Pourquoi le Capitaine Thalo'thas Brillesoleil les veut-il ?",a="L’artillerie du Fort de Guet-du-Nord a bombardé des navires de passage, dont ceux de la flotte du Capitaine Thalo'thas Brillesoleil. Il réclame les médailles comme preuve que les soldats responsables ont été tués en représailles.",al={"pourquoi cabestan veut des médailles","médailles brillesoleil","pourquoi collectionner les médailles de theramore"}},{q="Pourquoi le Fort de Guet-du-Nord attaque-t-il les navires de passage ?",a="La garnison du Fort de Guet-du-Nord est paranoïaque, aux confins du territoire de la Horde. Ses artilleurs sont devenus imprudents et prompts à tirer sur presque tout navire qui approche de leur enclave côtière.",al={"pourquoi guet-du-nord tire sur les navires","agressivité de guet-du-nord","pourquoi guet-du-nord attaque cabestan"}}},fp="15,169,20.455.0,16.386.0,26.153.0,25.150.0,48.222.0,47.193.0"}
P.entries["item:thick-bear-fur"] = {n="Fourrure d'ours épaisse",s="À Dun Morogh, la Fourrure d'ours épaisse aide les voyageurs et les soldats à supporter le froid montagnard. Les ours parcourent les champs de neige, et leurs peaux servent à confectionner des vêtements isolants et de la literie.",h="À Dun Morogh, la Fourrure d'ours épaisse aide les voyageurs et les soldats à supporter le froid montagnard.",kw={"claquesoufflet","dun morogh","l'antre gris","ice claw bear","jetsteam","dépôt de grillacier","fourrure d'ours épaisse"},ang={["class:Hunter"]="En tant que chasseur, vous apprenez à vous déplacer dans les broussailles glacées de Dun Morogh, à traquer de dangereuses bêtes des montagnes et à récolter des matériaux résistants dans la nature.",["race:Gnome"]="En tant que gnome, vous savez que les pilotes comme Claquesoufflet, au Dépôt de Grillacier, comptent sur la chasse pratique en territoire nain pour que leurs machines résistent aux longues missions alpines."},sec={{t="À l’abri du gel des montagnes",b="Les ours parcourent les crêtes de Dun Morogh, au milieu de certains des champs de neige les plus rudes des Royaumes de l'est. Leur épaisse fourrure les protège des blizzards, et les habitants comme les voyageurs utilisent leurs peaux. Les chasseurs les récoltent pour doubler les vêtements, isoler les avant-postes exposés aux courants d’air et matelasser les sacs de couchage froids."},{t="Une couche pour la brigade de siège",b="Le Pilote Claquesoufflet a équipé son char de siège, Jetsteam, au Dépôt de Grillacier pour un mois sur le terrain, lors d’une longue mission pour la Siege Brigade. Le fer froid offrait peu de réconfort dans les hauts bancs de neige. Il a donc engagé des éclaireurs locaux pour récolter de la fourrure d’ours épaisse dans les champs de neige au sud de L'antre Gris. Les peaux serviraient à confectionner une literie chaude pour ses quartiers dans la cabine."}},faq={{q="D’où vient la Fourrure d’ours épaisse ?",a="La Fourrure d’ours épaisse provient des ours de Dun Morogh, notamment des Young Black Bears et des Ice Claw Bears. Ils chassent dans la toundra enneigée et les pinèdes au sud de L'antre Gris.",al={"où trouver de la fourrure d’ours épaisse","qui donne de la fourrure d’ours épaisse","lieu où trouver de la fourrure d’ours"}},{q="Pourquoi le Pilote Claquesoufflet a-t-il besoin de cette fourrure ?",a="Le Pilote Claquesoufflet a besoin de fourrure d’ours épaisse pour confectionner une literie chaude dans son char, Jetsteam. Il l’équipe pour une mission d’un mois avec la Siege Brigade, et la literie l’aidera à supporter les froides nuits montagnardes.",al={"fourrure pour claquesoufflet","pourquoi claquesoufflet a-t-il besoin de fourrure","fourrure pour stocking jetsteam"}},{q="Quelles créatures de Dun Morogh donnent cette peau ?",a="Les Young Black Bears et les Ice Claw Bears donnent de la Fourrure d’ours épaisse. Tous deux parcourent les hauteurs enneigées de Dun Morogh, et leur fourrure dense sert à confectionner de la literie d’hiver et des isolants.",al={"quels ours donnent de la fourrure","types d’ours de dun morogh"}}},fx={a2edc513={q="Qu'est-ce que la Fourrure d'ours épaisse ?",a="La Fourrure d'ours épaisse est la peau lourde et isolante récoltée sur les ours sauvages qui rôdent dans les crêtes glaciales et les congères de Dun Morogh. Adaptée pour survivre aux blizzards mordants sous zéro, cette peau dense fournit une chaleur et une protection vitales contre le froid alpin incessant de Khaz Modan.",al={"fourrure d'ours épaisse","qu'est-ce que cette fourrure","fourrure d'ours de dun morogh"}}},fp="14,164,33.281.0,29.350.0,36.162.0,39.213.0,45.160.0"}
P.entries["item:thick-yeti-hide"] = {n="Thick Yeti Hide",s="En Féralas, les peaux de yéti attirent les artisans du cuir en quête de matériaux de qualité. Pratt McGrubben et Jangdor Swiftstrider les recherchent pour leur travail.",h="En Féralas, les peaux de yéti attirent les artisans du cuir en quête de matériaux de qualité.",kw={"val des griffes farouches","féralas","la côte oubliée","jangdor swiftstrider","travail du cuir","pratt mcgrubben","tannage","thick yeti hide","yéti"},ang={["profession:Tailoring"]="En tant qu’artisan du cuir, vous comprendrez peut-être pourquoi Pratt McGrubben et Jangdor Swiftstrider recherchent des peaux qu’ils pensent pouvoir rendre remarquablement résistantes grâce à un traitement adapté."},sec={{t="La marque d’un artisan du cuir",b="Les yétis de Féralas sont recherchés par deux artisans du cuir pour leurs peaux épaisses. Pratt McGrubben, au Bastion de Pennelune, et Jangdor Swiftstrider, au Camp Mojache, en demandent chacun dix. En échange, ils promettent de vous laisser choisir parmi leurs articles en cuir. Tous deux pensent qu’un tannage minutieux peut rendre ces peaux remarquablement résistantes."}},faq={{q="D’où viennent les peaux épaisses de yéti ?",a="Les Thick Yeti Hides proviennent des yétis de Féralas. On en trouve beaucoup au Val des Griffes farouches, juste à l’intérieur des terres depuis La Côte oubliée.",al={"source de peaux épaisses","où trouver des peaux de yéti","peaux de yéti de féralas"}},{q="Qui recherche les peaux épaisses de yéti ?",a="Pratt McGrubben, au Bastion de Pennelune, et Jangdor Swiftstrider, au Camp Mojache, recherchent chacun dix Thick Yeti Hides.",al={"qui recherche des peaux","peaux pratt","peaux jangdor"}},{q="À quoi servent ces peaux ?",a="Pratt McGrubben et Jangdor Swiftstrider veulent ces peaux pour leur travail du cuir. Ils pensent qu’un tannage habile peut les rendre exceptionnellement résistantes.",al={"utilisation des peaux de yéti","à quoi servent les peaux","peaux pour le travail du cuir"}},{q="Que proposent les artisans du cuir ?",a="Chaque artisan du cuir propose de choisir parmi ses articles en cuir confectionnés en échange d’une pile de dix Thick Yeti Hides.",al={"échange de peaux","récompense pour dix peaux","que vais-je recevoir"}}},fp="15,152,24.298.0,36.117.0,27.114.0,28.149.0,33.96.0"}
P.entries["item:thistlenettle-s-badge"] = {n="Plaque de Crispechardon",s="Dans les Mortemines, la Plaque de Crispechardon est tout ce qui reste après l’effondrement d’un tunnel.",h="Dans les Mortemines, la Plaque de Crispechardon est tout ce qui reste après l’effondrement d’un tunnel.",kw={"les mortemines","ligue des explorateurs","ruisselune","oh frère","crispechardon","plaque de crispechardon","marche de l’ouest","wilder"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez apporter un peu de réconfort à un nain éploré dans le Quartier des Nains de Hurlevent.",["race:Dwarf"]="En tant que nain, vous savez que le Contremaître Crispechardon a emporté l’insigne de la Ligue des explorateurs dans la Marche de l’Ouest. Le récupérer empêchera qu’un fils de Forgefer tombé au combat soit oublié."},sec={{t="La Ligue des explorateurs dans les Mortemines",b="Avant que la Confrérie défias ne condamne Ruisselune et les tunnels qui s’étendent sous le village, des prospecteurs de la Ligue des explorateurs de Forgefer travaillaient dans les anciennes mines d’or de la Marche de l’Ouest. Le Contremaître Crispechardon et son équipe se trouvaient profondément sous terre lorsqu’un tunnel s’effondra et les sépara. Son frère Wilder Crispechardon s’échappa jusqu’à Hurlevent, mais le contremaître et plusieurs ouvriers restèrent prisonniers sous terre."},{t="Une sinistre confirmation",b="Le Contremaître Crispechardon mourut dans les tunnels non condamnés et se releva en mort-vivant privé de raison parmi les galeries effondrées, à l’extérieur de la fonderie principale. Son insigne de la Ligue des explorateurs était toujours sur lui. Wilder, son frère éploré, reçoit l’insigne, qui prouve la mort du contremaître."}},faq={{q="À qui appartenait cet insigne ?",a="L’insigne appartenait au Contremaître Crispechardon, un mineur nain membre de la Ligue des explorateurs. L’effondrement d’un tunnel l’a piégé profondément sous terre, sous la Marche de l’Ouest.",al={"à qui appartenait l’insigne de crispechardon","propriétaire de l’insigne de crispechardon"}},{q="Où trouve-t-on l’insigne ?",a="Le Contremaître Crispechardon porte l’insigne dans les couloirs supérieurs des Mortemines infestés de monstres, à l’extérieur de l’entrée principale de la forteresse des défias.",al={"emplacement de l’insigne","comment obtenir l’insigne de crispechardon","où trouver crispechardon"}},{q="Qui veut la Plaque de Crispechardon ?",a="Wilder Crispechardon veut récupérer l’insigne. Le frère du contremaître vit dans le Quartier des Nains de Hurlevent et attend des nouvelles du sort de son parent.",al={"qui prend l’insigne de crispechardon","qui rend la quête oh frère","emplacement de wilder crispechardon"}},{q="Pourquoi les frères Crispechardon étaient-ils dans les Mortemines ?",a="Les frères exploraient et prospectaient les cavernes riches en minerais sous Ruisselune pour la Ligue des explorateurs. Des voleurs hostiles et des effondrements de tunnels ont ruiné leur expédition.",al={"pourquoi des nains étaient dans les mortemines","mission de crispechardon aux mortemines"}}},fp="21,84,38.365.0,19.261.1,30.162.0,25.143.0,32.137.0,53.168.0"}
P.entries["item:thistleshrub-dew"] = {n="Rosée des chardonniers",s="À Gadgetzan, la Rosée des chardonniers laisse un goût amer à Marin Noggenfogger et lui donne une nouvelle idée. Il l’envoie à Sprinkle, espérant qu’elle pourra rendre sa mixture plus facile à boire.",h="À Gadgetzan, la Rosée des chardonniers laisse un goût amer à Marin Noggenfogger et lui donne une nouvelle...",kw={"mixture amère","cuisine","gadgetzan","marin noggenfogger","sprinkle","rosée des chardonniers"},ang={["profession:Cooking"]="En tant que cuisinier, vous comprenez pourquoi Marin fait appel à Sprinkle : il espère que son savoir-faire rendra cette mixture amère plus facile à boire."},sec={{t="Un goût amer",b="Marin Noggenfogger a goûté à la Rosée des chardonniers, et c’est infect. Plutôt que d’abandonner son idée, il vous demande de l’apporter à Sprinkle, son amie de Gadgetzan. C’est une excellente cuisinière, et Marin espère qu’elle donnera du caractère à sa boisson."}},faq={{q="À quoi sert la Rosée des chardonniers ?",a="Marin Noggenfogger veut que Sprinkle utilise la rosée pour rendre sa mixture désagréable plus facile à boire.",al={"utilisation de la rosée des chardonniers","à quoi sert la rosée"}},{q="Pourquoi Marin veut-il l’aide de Sprinkle ?",a="Marin trouve sa mixture infecte et pense que Sprinkle, une excellente cuisinière, peut l’améliorer.",al={"pourquoi sprinkle","marin a besoin d’aide"}},{q="Qui est Sprinkle ?",a="Sprinkle est une cuisinière de Gadgetzan et une amie de Marin Noggenfogger.",al={"sprinkle à gadgetzan","qui est sprinkle"}},{q="Où faut-il apporter la Rosée des chardonniers ?",a="Marin vous demande d’apporter la Rosée des chardonniers à Sprinkle, à Gadgetzan.",al={"livraison de la rosée","où apporter la rosée"}}},fp="16,169,14.241.0,29.99.0,36.98.0,16.67.0,31.69.0"}
P.entries["item:thorium-plated-dagger"] = {n="Thorium Plated Dagger",s="Un Thorium Plated Dagger est une arme enchantée portée par les contremaîtres et les esclavagistes Dark Iron dans le Chaudron. Velarok Windblade a besoin de son alliage de thorium pour fabriquer un manche solide.",h="Un Thorium Plated Dagger est une arme enchantée portée par les contremaîtres et les esclavagistes Dark Iron...",kw={"chaudron","esclavagiste dark iron","contremaître dark iron","alliage enchanté","thorium","thorium plated dagger","velarok windblade"},sec={{t="Thorium enchanté",b="Les contremaîtres et les esclavagistes Dark Iron du Chaudron portent des Thorium Plated Daggers fabriqués en thorium enchanté. Velarok Windblade cherche cet alliage solide pour reforger un manche destiné à la flamme parfaite."}},faq={{q="Qui utilise les Thorium Plated Daggers ?",a="Les contremaîtres et les esclavagistes Dark Iron du Chaudron portent des Thorium Plated Daggers.",al={"qui possède des dagues en thorium","utilisateurs de dagues dark iron"}},{q="Pourquoi Velarok veut-il les dagues ?",a="Velarok Windblade peut récupérer leur alliage de thorium enchanté et reforger un manche.",al={"pourquoi velarok a besoin de dagues","utilité de la dague"}},{q="De quoi la dague est-elle faite ?",a="La dague est faite de thorium enchanté, un alliage extrêmement solide.",al={"matériau de la dague en thorium","composition de la dague"}},{q="De combien de dagues Velarok a-t-il besoin ?",a="Velarok Windblade a besoin de huit Thorium Plated Daggers.",al={"nombre de dagues","combien de dagues en thorium"}}},fp="21,170,17.191.0,32.79.0,34.83.0,27.61.0,35.53.0"}
P.entries["item:thresher-eye"] = {n="Oeil de batteur",s="Sur Sombrivage, Crackboum Tournelevier a besoin d’yeux de batteur pour ses Buzzbox. Il s’en sert pour réparer la Buzzbox 411, une machine de communication sur la plage au nord d’Auberdine.",h="Sur Sombrivage, Crackboum Tournelevier a besoin d’yeux de batteur pour ses Buzzbox.",kw={"auberdine","buzzbox 411","sombrivage","batteur de sombrivage","oeil de batteur","crackboum tournelevier"},ang={["profession:Engineering"]="L’utilisation de parties animales par Crackboum pour réparer des relais mécaniques est un exemple inhabituel d’ingénierie gnome.",["race:Gnome"]="En tant que gnome, vous pouvez découvrir une facette plus sauvage de l’ingéniosité gnome chez Crackboum Tournelevier. Il bricole des machines de terrain dans les étendues sauvages de Kalimdor, entre deux coupes de vin de trotteur."},sec={{t="Échantillons écologiques pour gadgets gnomes",b="Les Batteurs de Sombrivage chassent dans les vagues et les hauts-fonds au large de Sombrivage. Ils menacent les pêcheurs et les voyageurs locaux, et leurs grands yeux ont attiré l’attention de Crackboum Tournelevier. L’ingénieur gnome est installé non loin et raffole du vin de trotteur. Il a besoin de ces yeux pour réparer la Buzzbox 411, une machine de communication sur la plage au nord d’Auberdine."},{t="À quoi servent les yeux",b="Crackboum n’explique pas comment des yeux visqueux peuvent réparer des machines délicates. Ils pourraient servir de lentilles rudimentaires, d’agents chimiques ou d’engrenages biologiques. Quelle que soit la méthode, placer trois yeux dans la trappe de maintenance de la Buzzbox 411 rétablit sa liaison de communication. Crackboum envoie alors des provisions par des transmissions brouillées par les parasites."}},faq={{q="D’où viennent les yeux de batteur ?",a="Les yeux de batteur proviennent des Batteurs de Sombrivage et des Anciens Batteurs de Sombrivage dans l’océan au large de Sombrivage, surtout près d’Auberdine.",al={"où trouver des yeux de batteur","comment obtenir un œil de batteur","source des yeux de batteur"}},{q="Pourquoi Crackboum Tournelevier veut-il des yeux de batteur ?",a="Crackboum veut des yeux de batteur pour ses Buzzbox. Il s’en sert pour réparer la Buzzbox 411, une machine de communication gnome sur le rivage au nord d’Auberdine. Placer les yeux dans sa trappe rétablit les systèmes de la machine.",al={"pourquoi faut-il des yeux de batteur","yeux pour la buzzbox 411","à quoi servent les yeux de batteur"}},{q="Comment un œil répare-t-il une machine ?",a="Crackboum Tournelevier n’explique pas comment un œil répare une machine. La Buzzbox 411 accepte les yeux et se rallume, mais on ignore s’il utilise leurs rétines pour faire la mise au point ou s’il se sert de leurs composants organiques.",al={"pourquoi des yeux dans une machine","pièces biologiques pour machine gnome"}},{q="Qu’est-ce que la Buzzbox 411 ?",a="La Buzzbox 411 est l’un des nombreux appareils de communication et de surveillance installés par Crackboum Tournelevier à travers Sombrivage. Une fois chargée des matériaux demandés, elle lui permet de communiquer à distance et de distribuer des provisions.",al={"utilité de la buzzbox 411","qui a construit la buzzbox 411"}}},fx={eb2ee385={q="Qu'est-ce qu'un Oeil de batteur ?",a="Un Oeil de batteur est l'organe oculaire prélevé sur les batteurs prédateurs qui nagent dans les eaux côtières au large de Sombrivage. Bien qu'il s'agisse de matière biologique ordinaire pour la plupart, l'artisan excentrique Crackboum Tournelevier leur trouve une étrange utilité mécanique ou chimique pour réparer ses boîtes à bourdonner à longue portée.",al={"qu'est-ce qu'un oeil de batteur","yeux de batteur"}}},fp="12,168,38.344.0,23.314.0,33.128.0,48.213.0,30.217.0,20.205.0"}
P.entries["item:thule-s-head"] = {n="Tête de Thule",s="Au Sépulcre, le Grand exécuteur Hadrec cherche la preuve de la mort de Thule Ravenclaw. Sa tête tranchée confirme la chute du commandant du Fléau sur l'Ile de Fenris et aide les Réprouvés à tenir la Forêt des Pins-Argentés.",h="Au Sépulcre, le Grand exécuteur Hadrec cherche la preuve de la mort de Thule Ravenclaw.",kw={"fenris","hadrec","nécromancien","ravenclaw","fléau","le sépulcre","thule"},ang={["faction:Horde"]="La mort de Thule Ravenclaw sécurise les frontières orientales de la Forêt des Pins-Argentés et protège les territoires récemment acquis par la Horde des attaques du Fléau.",["race:Undead"]="Pour les Réprouvés, trancher la tête de Thule est une victoire militaire et une vengeance personnelle contre l'emprise du roi-liche sur Lordaeron."},sec={{t="Trophée de l'Ile de Fenris",b="L'Ile de Fenris est le principal bastion du Fléau du roi-liche dans la Forêt des Pins-Argentés. Depuis le Donjon de Fenris, le nécromancien Thule Ravenclaw commande des peaux-pourries et des serviteurs mort-vivants qui menacent les avant-postes des Réprouvés, dont le Sépulcre. Le Grand exécuteur Hadrec n'accepte aucun rapport sur la mort de Thule sans sa tête tranchée.\n\nÀ la mort de Thule, une vague de magie noire traverse les bois. Sa tête apporte à Hadrec la preuve nécessaire pour déclarer l'Ile de Fenris vaincue."}},faq={{q="Qui veut la Tête de Thule ?",a="Le Grand exécuteur Hadrec commande les forces des Réprouvés depuis le Sépulcre, dans la Forêt des Pins-Argentés. Il exige la Tête de Thule comme preuve de la mort du chef du Fléau.",al={"qui a besoin de la tête de thule","à qui remettre la tête de thule","qui prend la tête de thule"}},{q="Qui était Thule Ravenclaw ?",a="Thule Ravenclaw est un puissant nécromancien qui commande le Fléau sur l'Ile de Fenris. Depuis le Donjon de Fenris, il dirige des attaques contre les Réprouvés et manie des enchantements comme le Hex of the Ravenclaw.",al={"histoire de thule","qui est thule","passé de thule ravenclaw"}},{q="Pourquoi les Réprouvés exigent-ils précisément sa tête ?",a="Les Réprouvés ne peuvent pas laisser la Forêt des Pins-Argentés sous la menace du Fléau. Les nécromanciens sont connus pour leurs tromperies et leurs résurrections impies ; le Grand exécuteur Hadrec exige donc une preuve matérielle de la destruction de Thule.",al={"pourquoi la tête de thule","pourquoi veulent-ils sa tête"}},{q="Que se passe-t-il quand Thule Ravenclaw est tué ?",a="Quand Thule Ravenclaw est tué, une vague d'énergie nécrotique déferle dans la région. Les érudits et apothicaires réprouvés du Sépulcre ressentent l'onde de choc magique à distance.",al={"que se passe-t-il après la mort de thule","énergie libérée à la mort de thule"}}},fx={["3fe7e40b"]={q="D'où vient la Tête de Thule ?",a="Cette tête coupée provient directement du nécromancien Thule Ravenclaw, dans les salles du Donjon de Fenris. Thule dirigeait les forces du Fléau qui ont pris l'île de Fenris dans le nord de la Forêt des Pins-Argentés, transformant la forteresse en un bastion des morts-vivants jusqu'à ce que vous l'abattiez.",al={"origine de la tête de thule","où trouver la tête de thule","source de la tête de thule"}}},fp="12,201,21.432.1,23.152.0,24.198.0,49.193.0,43.163.1"}
P.entries["item:thunder-lizard-blood"] = {n="Sang de lézard-tonnerre",s="Les chasseurs rapportent du Sang de lézard-tonnerre des Tarides du sud. Il provient des grandes bêtes qui parcourent les plaines.",h="Les chasseurs rapportent du Sang de lézard-tonnerre des Tarides du sud.",kw={"tarides","camp taurajo","jorn oeil-des-cieux","stormhide","stormsnout","sang de lézard-tonnerre","thunderhead"},ang={["class:Hunter"]="En tant que chasseur, vous devez avoir le pied sûr et être agile pour vaincre un lézard-tonnerre. Rapporter son sang prouve que vous maîtrisez les plus grandes bêtes de la savane.",["race:Tauren"]="En tant que chasseur tauren de Camp Taurajo, vous affrontez les lézards-tonnerre lors d'une épreuve traditionnelle de survie, au milieu des redoutables géants de votre terre natale."},sec={{t="Trophée de chasse",b="Stormsnouts, Stormhides et Thunderheads sont les noms donnés aux lézards-tonnerre dans les plaines. Leurs pas lourds font trembler la terre, et leur poids écrasant peut aplatir un chasseur imprudent. Rapporter leur sang prouve que vous savez les chasser et que vous pouvez survivre sous leurs pattes tonitruantes."}},faq={{q="Quelles créatures fournissent ce sang ?",a="Les Stormsnouts, les Stormhides et les Thunderheads fournissent ce sang. Ces lézards-tonnerre adultes parcourent la savane autour de Camp Taurajo, dans les Tarides du sud.",al={"qui rapporte du sang de lézard-tonnerre","où trouver du sang de lézard-tonnerre","quels lézards-tonnerre"}},{q="Pourquoi recherche-t-on le Sang de lézard-tonnerre ?",a="Jorn Oeil-des-cieux, à Camp Taurajo, demande aux chasseurs de récolter ce sang dans le cadre d'épreuves organisées à travers les Tarides. Le rapporter intact prouve qu'un chasseur peut affronter les plus grandes bêtes piétinantes de Kalimdor.",al={"qui veut du sang de lézard-tonnerre","utilité du sang de lézard-tonnerre"}},{q="Où trouve-t-on généralement ces lézards-tonnerre ?",a="Les lézards-tonnerre parcourent les prairies au nord, à l'est et au sud de Camp Taurajo. Là, ils paissent aux côtés des autres grands animaux des Tarides du sud.",al={"lieux où trouver des lézards-tonnerre","où trouver des stormsnouts"}}},fx={["25735f1e"]={q="Qu'est-ce que le Sang de lézard-tonnerre ?",a="Le Sang de lézard-tonnerre est un fluide vital récolté sur les énormes lézards-tonnerre qui parcourent les Tarides du sud. Ces bêtes imposantes font trembler les plaines à chaque enjambée, et prélever leur sang sert de preuve irréfutable qu'un chasseur possédait l'habileté et la résilience nécessaires pour abattre de telles créatures redoutables sans être écrasé sous leurs pattes.",al={"qu'est-ce que le sang de lézard-tonnerre","objet sang de lézard-tonnerre","à propos du sang de lézard-tonnerre"}},d2820178={q="D'où vient le Sang de lézard-tonnerre, et qui l'a fabriqué ?",a="Ce sang est prélevé naturellement sur les puissants lézards-tonnerre habitant les Tarides du sud, en particulier les espèces connues sous le nom de groin-d'orage, cuir-d'orage et tête-de-tonnerre. Il n'est pas fabriqué ou façonné par des mains mortelles, mais prélevé directement sur ces bêtes colossales par les chasseurs qui osent affronter leurs sabots piétinants à travers la savane.",al={"d'où vient le sang de lézard-tonnerre","qui a fabriqué le sang de lézard-tonnerre","origine du sang de lézard-tonnerre"}}},fp="20,118,18.304.0,34.152.0,41.186.0,46.152.0"}
P.entries["item:thunder-lizard-horn"] = {n="Corne de lézard-tonnerre",s="Dans les Tarides, le Brasseur Drohn cherche une Corne de lézard-tonnerre pour le breuvage légendaire de Chen Stormstout.",h="Dans les Tarides, le Brasseur Drohn cherche une Corne de lézard-tonnerre pour le breuvage légendaire de Chen...",kw={"les tarides","brasseur drohn","chen stormstout","owatanka","cabestan","stormsnout","stormstout","corne de lézard-tonnerre","thunderhead"},ang={["class:Hunter"]="En tant que chasseur, soyez prudent lorsque vous pistez les lézards-tonnerre dans la savane ouverte. Leurs éclairs les rendent plus dangereux que les kodos ou les trotteurs des plaines ordinaires des Tarides.",["profession:Cooking"]="En tant que cuisinier, la recette de Drohn vous semblera peut-être inhabituelle. Elle associe des organes de trotteur des plaines, des défenses de prédateur et la corne d'une bête dans un breuvage enivrant."},sec={{t="Un puissant ingrédient de brassage",b="Les lézards-tonnerre parcourent les Tarides, le corps à crête parcouru d'éclairs. À Cabestan, le Brasseur Drohn apprécie leurs cornes pour préparer la bière Stormstout. Son mentor avait appris la recette auprès du Brasseur pandaren itinérant Chen Stormstout, puis la lui a transmise. La corne donne à la boisson son puissant effet."}},faq={{q="À quoi sert la corne ?",a="Le Brasseur Drohn, à Cabestan, utilise la corne dans le breuvage rendu célèbre par Chen Stormstout.",al={"utilité de la corne de lézard-tonnerre","à quoi sert la corne de lézard-tonnerre","pourquoi faut-il une corne de lézard-tonnerre"}},{q="Quelles bêtes peuvent donner une corne de lézard-tonnerre ?",a="Les Thunderheads, stormsnouts, thunderstomps, stormhides et l'insaisissable Owatanka peuvent donner une corne de lézard-tonnerre.",al={"où trouver une corne de lézard-tonnerre","qui donne une corne de lézard-tonnerre","sources de cornes de lézard-tonnerre"}},{q="Qui est le Brasseur Drohn ?",a="Le Brasseur Drohn brasse à Cabestan. Son ancien mentor avait appris la recette Stormstout auprès de Chen Stormstout et la lui a transmise.",al={"qui est drohn","histoire du brasseur drohn","drohn à cabestan"}},{q="La chasse aux lézards-tonnerre pour leurs cornes est-elle dangereuse ?",a="Les lézards-tonnerre peuvent décharger des éclairs et faire trembler le sol sous leurs pas lorsqu'on les provoque. Les chasser seul est dangereux.",al={"dangerosité des lézards-tonnerre","chasser les lézards-tonnerre"}}},fx={["6ace69b3"]={q="Qu'est-ce qu'une Corne de lézard-tonnerre ?",a="Une corne de lézard-tonnerre est un trophée naturel robuste récolté sur les grands lézards-tonnerre parcourant les plaines des Tarides. Ces reptiles imposants, en accord avec la tempête, canalisent l'énergie électrique à travers leurs corps massifs, faisant de leurs cornes un composant naturel puissant prisé par de rares artisans aux recettes non conventionnelles.",al={"qu'est-ce qu'une corne de lézard-tonnerre","infos sur la corne de lézard-tonnerre","à propos de la corne de lézard-tonnerre"}},["1dc3a738"]={q="D'où vient une Corne de lézard-tonnerre ?",a="Ce n'est pas une création artificielle, mais une corne prélevée directement sur les redoutables lézards-tonnerre des Tarides, y compris des créatures comme les groin-d'orage, les tête-de-tonnerre et l'insaisissable Owatanka. Terrasser l'une de ces bêtes massives vous permet de récupérer la corne intacte.",al={"d'où viennent les cornes de lézard-tonnerre","qui fabrique la corne de lézard-tonnerre","source de la corne de lézard-tonnerre"}}},fp="19,98,24.297.0,26.82.0,41.111.0,24.130.0,54.117.0"}
P.entries["item:thunderhawk-saliva-gland"] = {n="Glande salivaire de faucon-tonnerre",s="Dans les Tarides, les grands faucons-tonnerre fournissent au Brasseur Drohn la glande nécessaire pour recréer la Trogg Ale ardente de Chen Stormstout.",h="Dans les Tarides, les grands faucons-tonnerre fournissent au Brasseur Drohn la glande nécessaire pour recréer...",kw={"tarides","drohn","glande","tonneau","cabestan","salive","faucon-tonnerre","trogg ale"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez faire vos preuves en chassant les féroces faucons-tonnerre des Tarides tandis que vous parcourez Kalimdor.",["profession:Cooking"]="En tant que cuisinier, vous pourriez hésiter à utiliser des glandes salivaires, mais les maîtres brasseurs inventifs prisent les essences animales insolites pour leur saveur et leur puissance."},sec={{t="Un ingrédient sauvage",b="Les grands faucons-tonnerre chassent dans les savanes arides des Tarides. Ces serpents ailés commandent aux tempêtes, et les plus âgés, plus dangereux, produisent une glande salivaire riche en puissance naturelle. Les voyageurs évitent ces bêtes mortelles. Les maîtres brasseurs prisent cette glande, rare ingrédient de base pour des boissons exotiques."},{t="Les recettes secrètes de Chen",b="Le Brasseur Drohn s'est installé aux abords de Cabestan après le passage de Chen Stormstout par Kalimdor. Drohn étudie les méthodes de fermentation du maître brasseur itinérant. Pour brasser la Trogg Ale, il lui faut une glande salivaire de faucon-tonnerre fraîche, des glandes d'éclair de peau d'orage et un Foie de kodo. Cette boisson ardente a du mordant et doit fortifier les aventuriers robustes."}},faq={{q="Où trouver une Glande salivaire de faucon-tonnerre ?",a="Les grands faucons-tonnerre chassent dans les savanes ouvertes des Tarides, où l'on peut prélever leurs glandes salivaires.",al={"butin de glande salivaire de faucon-tonnerre","où trouver une glande salivaire","emplacement de la glande de faucon-tonnerre"}},{q="À quoi sert la glande salivaire ?",a="Le Brasseur Drohn, aux abords de Cabestan, a besoin de cette glande pour brasser la Trogg Ale, une recette puissante laissée par Chen Stormstout.",al={"utilisation de la glande salivaire","à quoi sert la glande salivaire de faucon-tonnerre","utilité de la salive de faucon-tonnerre"}},{q="Qui est le Brasseur Drohn ?",a="Le Brasseur Drohn vit près du port de Cabestan. Le voyageur itinérant Chen Stormstout lui a enseigné l'art des brassins exotiques, et Drohn échange des ales puissantes contre les ingrédients rapportés par les aventuriers qui affrontent la faune locale.",al={"drohn à cabestan","qui est drohn","histoire du brasseur drohn"}},{q="Qu'est-ce que la Trogg Ale ?",a="Chen Stormstout a conçu la Trogg Ale comme une boisson d'une puissance redoutable. Le Brasseur Drohn la prépare avec une glande salivaire de grand faucon-tonnerre, des glandes d'éclair et un Foie de kodo.",al={"histoire de la trogg ale","qu'est-ce que la trogg ale","trogg ale de chen"}}},fx={bfe8bf39={q="Qu'est-ce qu'une Glande salivaire de faucon-tonnerre ?",a="C'est un organe récolté sur les grands faucons-tonnerre prédateurs adultes qui planent au-dessus des plaines arides des Tarides. Imprégnée des énergies naturelles et des fluides venimeux propres à ces bêtes aviaires, la glande fournit une sécrétion piquante et volatile, prisée par les brasseurs audacieux à la recherche de concoctions non traditionnelles avec un goût inimitable.",al={"qu'est-ce qu'une glande salivaire de faucon-tonnerre","connaissances sur la glande salivaire de faucon-tonnerre","à propos de la glande salivaire de faucon-tonnerre"}},dda65d1e={q="D'où vient une Glande salivaire de faucon-tonnerre ?",a="Ce n'est pas un produit manufacturé, mais un organe biologique prélevé sur les grands faucons-tonnerre qui parcourent les cieux ouverts et les crêtes des Tarides. Les chasseurs doivent traquer ces puissants prédateurs ailés et extraire soigneusement la glande intacte de leurs carcasses.",al={"origine de la glande salivaire de faucon-tonnerre","d'où viennent les glandes salivaires de faucon-tonnerre","qui a créé la glande salivaire de faucon-tonnerre"}}},fp="24,125,17.286.0,21.332.0,45.104.0,34.112.0,24.197.0,18.166.0"}
